function getAgentGitAllStatusChanges(status = agentGitLastStatus) {
  const primary = Array.isArray(status?.changes) ? status.changes : [];
  const extra = Array.isArray(status?.outOfBatch?.changes) ? status.outOfBatch.changes : [];
  const byPath = new Map();
  for (const change of [...primary, ...extra]) {
    const pathKey = String(change?.path || "").trim();
    if (!pathKey) continue;
    if (!byPath.has(pathKey)) byPath.set(pathKey, change);
  }
  return [...byPath.values()];
}

function agentGitCommitBatchExtensionSet(batch) {
  const raw = batch?.extensions;
  const chunks = Array.isArray(raw) ? raw : raw == null || raw === "" ? [] : [raw];
  const set = new Set();
  for (const chunk of chunks) {
    for (const part of String(chunk || "").split(/[,\s\n]+/)) {
      const normalized = String(part || "")
        .trim()
        .toLowerCase()
        .replace(/^\./, "");
      if (normalized) set.add(normalized);
    }
  }
  return set;
}

function getAgentGitActiveExtensions() {
  const batches = agentGitModuleConfig?.commitBatches;
  if (Array.isArray(batches) && batches.length) {
    const union = new Set();
    for (const batch of batches) {
      for (const ext of batch.extensions || []) {
        const normalized = String(ext || "").trim().toLowerCase().replace(/^\./, "");
        if (normalized) union.add(normalized);
      }
    }
    if (union.size) return [...union];
  }
  return [...AGENT_GIT_FILE_EXTENSIONS];
}

function appendAgentGitExtensionTags(container, extensions, { activeCounts = null } = {}) {
  for (const ext of extensions || []) {
    const normalized = String(ext || "").trim().toLowerCase().replace(/^\./, "");
    const activeCount = activeCounts instanceof Map
      ? Number(activeCounts.get(normalized) || activeCounts.get(ext) || 0)
      : activeCounts && typeof activeCounts === "object"
        ? Number(activeCounts[normalized] || activeCounts[ext] || 0)
        : 0;
    const tag = document.createElement("span");
    tag.className = "agent-git-ext-tag";
    if (activeCount > 0) {
      tag.classList.add("is-active");
      tag.title = `${activeCount} изменённых файл(ов) · .${normalized}`;
    }
    tag.textContent = ext;
    container.appendChild(tag);
  }
}

function appendAgentGitFolderHintTags(container, folders) {
  for (const folder of folders || []) {
    const rel = String(folder || "").trim();
    if (!rel) continue;
    const tag = document.createElement("span");
    tag.className = "agent-git-ext-tag agent-git-folder-hint-tag";
    tag.textContent = rel;
    tag.title = `Рекомендуется: ${rel}/.gitkeep`;
    container.appendChild(tag);
  }
}

function formatAgentGitBatchMaxFileSizeLabel(maxFileSizeMb) {
  const n = Number(maxFileSizeMb);
  if (!Number.isFinite(n) || n <= 0) return "—";
  const rounded = Math.round(n * 100) / 100;
  const text = Number.isInteger(rounded) ? String(rounded) : String(rounded);
  return `${text} МБ`;
}

