function ensureAgentGitExtensionsLegend(statusData = null) {
  if (agentGitExtensionsLegendNode?.isConnected) {
    return agentGitExtensionsLegendNode;
  }

  const changes = Array.isArray(statusData?.changes) ? statusData.changes : [];

  const wrap = document.createElement("div");
  wrap.className = "agent-git-extensions-legend";
  wrap.id = "agent-git-extensions-legend";

  const batches = Array.isArray(agentGitModuleConfig?.commitBatches)
    ? agentGitModuleConfig.commitBatches
    : [];

  const table = document.createElement("table");
  table.className = "agent-git-extensions-table";
  table.setAttribute("aria-label", "Партии коммита и расширения файлов");

  const thead = document.createElement("thead");
  const headRow = document.createElement("tr");
  const thType = document.createElement("th");
  thType.scope = "col";
  thType.textContent = "Тип";
  const thExt = document.createElement("th");
  thExt.scope = "col";
  thExt.textContent = "Расширения";
  const thCount = document.createElement("th");
  thCount.scope = "col";
  thCount.className = "agent-git-extensions-count-col";
  thCount.textContent = "Изменения";
  thCount.title = "Незакоммиченные файлы в этой партии";
  const thLimit = document.createElement("th");
  thLimit.scope = "col";
  thLimit.className = "agent-git-extensions-limit-col";
  thLimit.textContent = "Лимит на 1 файл";
  headRow.append(thType, thExt, thCount, thLimit);
  thead.appendChild(headRow);
  table.appendChild(thead);

  const tbody = document.createElement("tbody");

  if (batches.length) {
    for (const batch of batches) {
      const row = document.createElement("tr");
      row.className = "agent-git-extensions-row";
      const typeCell = document.createElement("th");
      typeCell.scope = "row";
      typeCell.className = "agent-git-extensions-type";
      typeCell.textContent = formatAgentGitCommitBatchDisplayLabel(batch);
      const extCell = document.createElement("td");
      extCell.className = "agent-git-extensions-cell";
      const extList = document.createElement("div");
      extList.className = "agent-git-extensions-list";
      appendAgentGitExtensionTags(extList, batch.extensions, {
        activeCounts: countAgentGitBatchChangesByExtension(batch, changes)
      });
      extCell.appendChild(extList);
      const countCell = document.createElement("td");
      countCell.className = "agent-git-extensions-count";
      const batchChangeCount = countAgentGitChangesInBatch(batch, changes);
      countCell.textContent = String(batchChangeCount);
      if (batchChangeCount === 0) {
        countCell.classList.add("is-zero");
      }
      const limitCell = document.createElement("td");
      limitCell.className = "agent-git-extensions-limit";
      limitCell.textContent = formatAgentGitBatchMaxFileSizeLabel(batch.maxFileSizeMb);
      row.append(typeCell, extCell, countCell, limitCell);
      tbody.appendChild(row);
    }
    appendAgentGitExtensionsOutOfBatchRow(tbody, statusData);
    appendAgentGitExtensionsEmptyFoldersRow(tbody, statusData);
  } else {
    const row = document.createElement("tr");
    row.className = "agent-git-extensions-row";
    const typeCell = document.createElement("th");
    typeCell.scope = "row";
    typeCell.className = "agent-git-extensions-type";
    typeCell.textContent = "Файлы";
    const extCell = document.createElement("td");
    extCell.className = "agent-git-extensions-cell";
    const extList = document.createElement("div");
    extList.className = "agent-git-extensions-list";
    appendAgentGitExtensionTags(extList, AGENT_GIT_FILE_EXTENSIONS, {
      activeCounts: countAgentGitChangesByExtension(changes)
    });
    extCell.appendChild(extList);
    const countCell = document.createElement("td");
    countCell.className = "agent-git-extensions-count";
    const fallbackCount = changes.length;
    countCell.textContent = String(fallbackCount);
    if (fallbackCount === 0) {
      countCell.classList.add("is-zero");
    }
    const limitCell = document.createElement("td");
    limitCell.className = "agent-git-extensions-limit";
    limitCell.textContent = "—";
    row.append(typeCell, extCell, countCell, limitCell);
    tbody.appendChild(row);
  }

  table.appendChild(tbody);

  const tableWrap = document.createElement("div");
  tableWrap.className = "agent-git-extensions-table-wrap";
  tableWrap.appendChild(table);
  wrap.appendChild(tableWrap);

  const extras = document.createElement("p");
  extras.className = "agent-git-extensions-extras";
  extras.textContent = `Также по имени (партия «Конфиги»): ${AGENT_GIT_EXTRA_BASENAMES.join(", ")}`;
  wrap.appendChild(extras);

  agentGitExtensionsLegendNode = wrap;
  return wrap;
}

function syncAgentGitExtensionsLegend(data) {
  const mount = agentGitExtensionsMountNode;
  if (!mount) return;
  mount.replaceChildren();
  agentGitExtensionsLegendNode = null;
  if (!data?.isRepo) {
    mount.classList.add("hidden");
    mount.setAttribute("aria-hidden", "true");
    return;
  }
  mount.classList.remove("hidden");
  mount.removeAttribute("aria-hidden");
  mount.appendChild(ensureAgentGitExtensionsLegend(data));
}

function renderAgentGitMetaPrimary(data) {
  const host = agentGitMetaPrimaryNode || agentGitMetaNode;
  if (!host) return;

  host.replaceChildren();

  if (!data?.isRepo) {
    host.textContent = "Git-репозиторий не найден в корне workspace";
    agentGitExtensionsLegendNode = null;
    return;
  }

  if (data.clean) {
    const status = document.createElement("p");
    status.className = "agent-git-meta-status";
    status.textContent = "Рабочая копия чистая";
    host.appendChild(status);
  } else if (data.filteredClean) {
    const status = document.createElement("p");
    status.className = "agent-git-meta-status";
    status.textContent = `Нет изменений в этих расширениях (всего в git: ${data.totalChangeCount ?? 0})`;
    host.appendChild(status);
  }

}

function formatAgentGitCommitExtensionsDisplay(value) {
  const fallback = AGENT_GIT_FILE_EXTENSIONS.join("\n");
  const text = String(value ?? "").trim();
  if (!text) return fallback;
  if (text.includes("\n")) return text.replace(/\r\n/g, "\n");
  return text
    .split(/[,\s]+/)
    .map((part) => part.trim().replace(/^\./, ""))
    .filter(Boolean)
    .join("\n");
}

function getAgentGitFilterLabel() {
  const active = getAgentGitActiveExtensions();
  const extras = AGENT_GIT_EXTRA_BASENAMES.join(", ");
  return `${active.join(", ")}, ${extras}`;
}
