function getWikilinkTargetFromNodePath(nodePath) {
  const normalized = normalizeMenuNodePath(String(nodePath || "").replace(/\\/g, "/"));
  if (!normalized) return "";
  const parts = normalized.split("/").filter(Boolean);
  if (!parts.length) return "";
  const fileName = parts[parts.length - 1];
  if (isAreaManifestFileName(fileName)) {
    const folderName = parts[parts.length - 2] || "";
    const topicLabel = stripStoragePrefix(folderName) || stripTopicPrefix(folderName);
    if (parts.length > 2) {
      return [...parts.slice(0, -2), topicLabel].filter(Boolean).join("/");
    }
    return topicLabel;
  }
  const baseName = stripTopicPrefix(fileName);
  if (parts.length > 1) {
    return [...parts.slice(0, -1), baseName].join("/");
  }
  return baseName;
}

function normalizeLinkFilePath(relPath) {
  return String(relPath || "").replace(/\\/g, "/").replace(/^\/+/, "");
}

function getLinkTargetFileRelPath(nodePath) {
  const normalized = normalizeMenuNodePath(String(nodePath || "").replace(/\\/g, "/").trim());
  if (!normalized) return "";
  if (/\.md$/i.test(normalized)) return normalized;
  return `${normalized}.md`;
}

function getCurrentEditorLinkBasePath() {
  if (activeWorkspaceTocRelPath) return activeWorkspaceTocRelPath;
  if (activeSystemFile) {
    const normalized = normalizeSystemFileName(activeSystemFile);
    if (isWorkspacePageIndexRelPath(normalized)) return normalized;
    if (normalized === WORKSPACE_PAGE_INDEX_LEGACY_FILE) return "";
    return normalized;
  }
  if (isWorkspacePageIndexRelPath(activePath)) return getWorkspacePageIndexRelPath();
  return getPropsContextPath(activePath) || getResolvedNodePath(activePath) || "";
}

function resolveMarkdownPreviewNodePath() {
  if (activeSystemFile) {
    const normalized = normalizeSystemFileName(activeSystemFile);
    if (normalized === WORKSPACE_PAGE_INDEX_LEGACY_FILE) return "";
    return normalized;
  }
  const apiPath = getActiveNodeApiPath() || activePath || "";
  if (isWorkspacePageIndexRelPath(apiPath)) return getWorkspacePageIndexRelPath();
  return getPropsContextPath() || getActiveTitleEditorPath() || apiPath;
}

function joinWorkspaceRelativePath(baseRel, hrefRel) {
  const stack = baseRel ? normalizeLinkFilePath(baseRel).split("/").filter(Boolean) : [];
  if (stack.length && /\.md$/i.test(stack[stack.length - 1])) {
    stack.pop();
  }
  for (const part of String(hrefRel || "").split("/")) {
    if (part === "..") stack.pop();
    else if (part && part !== ".") stack.push(part);
  }
  return stack.join("/");
}

function resolveMarkdownHrefToWorkspaceRel(href, sourceRel = getCurrentEditorLinkBasePath()) {
  const raw = String(href || "").trim();
  if (!raw || /^https?:\/\//i.test(raw) || /^data:/i.test(raw) || raw.startsWith("/api/")) {
    return null;
  }
  const pathPart = raw.split("#")[0].split("?")[0].trim();
  if (!pathPart) return null;
  if (pathPart.startsWith("/")) {
    return normalizeLinkFilePath(pathPart);
  }
  const normalizedPart = normalizeLinkFilePath(pathPart);
  if (parseStorageLayerRef(normalizedPart)) {
    return normalizedPart;
  }
  if (/^(?:awn-topics|awn-container|awn-repositories|awn-media|awn-databases|awn-data|awn-media-cloud|awn-google-drive)\//i.test(normalizedPart)) {
    return normalizedPart;
  }
  return normalizeLinkFilePath(joinWorkspaceRelativePath(sourceRel, pathPart));
}

function relativizeWorkspacePath(fromRel, toRel) {
  const from = normalizeLinkFilePath(fromRel);
  const to = normalizeLinkFilePath(toRel);
  if (!to) return "";
  if (!from || from === to) return to.split("/").pop() || to;

  const fromParts = from.split("/").filter(Boolean);
  const toParts = to.split("/").filter(Boolean);
  if (fromParts.length && /\.md$/i.test(fromParts[fromParts.length - 1])) {
    fromParts.pop();
  }

  let index = 0;
  while (
    index < fromParts.length &&
    index < toParts.length &&
    fromParts[index].toLowerCase() === toParts[index].toLowerCase()
  ) {
    index += 1;
  }
  const up = fromParts.length - index;
  const relParts = [...Array(up).fill(".."), ...toParts.slice(index)];
  return relParts.join("/") || toParts[toParts.length - 1] || to;
}

function escapeMarkdownLinkLabel(label) {
  return String(label || "")
    .replace(/\\/g, "\\\\")
    .replace(/\[/g, "\\[")
    .replace(/\]/g, "\\]");
}

function buildMarkdownFileLink(nodePath, displayLabel, options = {}) {
  const targetRel = getLinkTargetFileRelPath(nodePath);
  if (!targetRel) return "";
  return buildMarkdownLinkFromWorkspaceRel(targetRel, displayLabel, options);
}

function buildMarkdownLinkFromWorkspaceRel(workspaceRelPath, displayLabel, options = {}) {
  const targetRel = normalizeLinkFilePath(workspaceRelPath);
  if (!targetRel) return "";
  const fromRel = options.fromPath ?? getCurrentEditorLinkBasePath();
  const href = relativizeWorkspacePath(fromRel, targetRel);
  const encodedHref = href
    .split("/")
    .map((segment) => encodeMarkdownPathSegment(segment))
    .join("/");
  const label = escapeMarkdownLinkLabel(
    displayLabel || targetRel.split("/").pop()?.replace(/\.md$/i, "") || targetRel
  );
  return `[${label}](${encodedHref})`;
}

function buildVoiceChatMarkdownLink(workspaceRelPath, displayLabel) {
  const targetRel = normalizeLinkFilePath(workspaceRelPath);
  if (!targetRel) return "";
  const encodedHref = targetRel
    .split("/")
    .map((segment) => encodeMarkdownPathSegment(segment))
    .join("/");
  const cleanLabel = sanitizeVoiceChatDragLabel(displayLabel);
  const label = escapeMarkdownLinkLabel(
    cleanLabel || targetRel.split("/").pop()?.replace(/\.md$/i, "") || targetRel
  );
  return `[${label}](${encodedHref})`;
}

function buildVoiceChatImageMarkdown(workspaceRelPath, displayLabel) {
  const targetRel = normalizeLinkFilePath(workspaceRelPath);
  if (!targetRel) return "";
  const encodedHref = targetRel
    .split("/")
    .map((segment) => encodeMarkdownPathSegment(segment))
    .join("/");
  const cleanLabel = sanitizeVoiceChatDragLabel(displayLabel);
  const alt = escapeMarkdownLinkLabel(
    cleanLabel ||
      targetRel.split("/").pop()?.replace(/\.[^.]+$/i, "") ||
      targetRel
  );
  return `![${alt}](${encodedHref})`;
}

function resolveMediaCardWorkspaceRel(card) {
  const filePath = String(
    card?.dataset?.folderBrowsePath || card?.dataset?.mediaGridPath || ""
  )
    .replace(/\\/g, "/")
    .replace(/^\/+/, "")
    .trim();
  if (!filePath) return "";

  const nodePath =
    card?.dataset?.mediaGridNodePath ||
    card?.closest("[data-topic-node-path]")?.dataset?.topicNodePath ||
    getResolvedNodePath(activePath);

  if (card?.dataset?.mediaGridPath) {
    const memoryKind = activeEntryOverviewContext?.memoryKind || "media";
    return getMediaLibraryItemContextPath(filePath, memoryKind === "assets" ? "assets" : "media", nodePath);
  }

  if (/\/awn-storage\//i.test(filePath) || /^awn-storage\//i.test(filePath)) {
    return normalizeLinkFilePath(filePath);
  }

  return getExternalItemContextPath({ path: filePath }, nodePath);
}

