async function openRepositoryWorkspacePath(workspaceRel, options = {}) {
  const normalized = normalizeLinkFilePath(workspaceRel);
  if (!normalized || !isRepositoryWorkspaceRel(normalized)) return false;

  if (/^awn-repositories\/index\.md$/i.test(normalized)) {
    const folderPath = normalizeCreateParentPath(getFolderBrowseParentPath(normalized));
    const label =
      normalized.split("/").filter(Boolean).pop()?.replace(/\.md$/i, "") ||
      getLabelFromPath(normalized);
    await openFolderBrowseFile(label, normalized, {
      folderPath,
      skipRouteSync: Boolean(options.skipRouteSync)
    });
    return true;
  }

  if (await tryOpenAdoptWorkspaceRel(normalized, options)) return true;

  const repositoryEntry = resolveRepositoryEntryFromWorkspaceRel(normalized);
  if (repositoryEntry) {
    if (repositoryEntry.registered === false) return false;
    await openRepositoryWorkspaceEntry({ ...repositoryEntry, registered: true }, options);
    return true;
  }

  return false;
}

async function tryOpenAdoptWorkspaceRel(targetRel, options = {}) {
  const normalized = normalizeLinkFilePath(targetRel);
  if (!normalized || normalized === ".") return false;
  if (isRepositoryWorkspaceRel(normalized)) {
    const repositoryEntry = resolveRepositoryEntryFromWorkspaceRel(normalized);
    if (repositoryEntry?.registered === false) return false;
    await openRepositoryWorkspaceEntry({ ...repositoryEntry, registered: true }, options);
    return true;
  }
  if (isMediaLibraryWorkspaceRel(normalized)) {
    const mediaEntry = resolveMediaLibraryEntryFromWorkspaceRel(normalized);
    if (mediaEntry?.registered === false) return false;
    await openMediaLibraryWorkspaceEntry({ ...mediaEntry, registered: true }, options);
    return true;
  }
  if (isAwnChannelWorkspaceRel(normalized)) {
    const channelEntry = resolveAwnChannelEntryFromWorkspaceRel(normalized);
    if (channelEntry?.registered === false) return false;
    await openAwnChannelWorkspaceEntry({ ...channelEntry, registered: true }, options);
    return true;
  }
  try {
    const resolved = await fetchChpuResolve(workspaceRelToChpuPath(normalized));
    if (resolved?.kind === "adoptFolder") {
      const folderPath = String(resolved.folderPath || resolved.workspacePath || normalized).replace(
        /\\/g,
        "/"
      );
      if (isRepositoryWorkspaceRel(folderPath)) {
        const repositoryEntry = resolveRepositoryEntryFromWorkspaceRel(folderPath);
        if (repositoryEntry?.registered !== false) {
          await openRepositoryWorkspaceEntry(repositoryEntry, options);
          return true;
        }
        return false;
      }
      const label =
        resolved.title ||
        folderPath.split("/").filter(Boolean).pop() ||
        folderPath;
      await openFolderBrowseFromMenu(label, folderPath, {
        skipRouteSync: Boolean(options.skipRouteSync)
      });
      if (!options.skipRouteSync) {
        syncAppRouteToUrl({ push: true });
      }
      return true;
    }
    if (resolved?.kind === "adoptFile") {
      const filePath = String(resolved.filePath || resolved.workspacePath || normalized).replace(
        /\\/g,
        "/"
      );
      const folderPath = String(
        resolved.folderPath || getFolderBrowseParentPath(filePath)
      ).replace(/\\/g, "/");
      const label = resolved.title || filePath.split("/").pop() || filePath;
      await openFolderBrowseFile(label, filePath, {
        folderPath,
        skipRouteSync: Boolean(options.skipRouteSync)
      });
      if (!options.skipRouteSync) {
        syncAppRouteToUrl({ push: true });
      }
      return true;
    }
    if (resolved?.kind === "awnDataStore" || resolved?.kind === "awnDataRoot") {
      const opened = await openAwnDataRouteFromWorkspacePath(
        resolved.workspacePath || normalized,
        activeWorkspaceId,
        options
      );
      if (opened) {
        if (!options.skipRouteSync) {
          syncAppRouteToUrl({ push: true });
        }
        return true;
      }
    }
  } catch {
    // not an adopt path
  }
  return false;
}

