function parseMarkdownLinkValue(value) {
  const raw = String(value || "").trim();
  const match = raw.match(/^\[((?:\\.|[^\]])*)\]\(([^)#]+)(?:#[^)]*)?\)$/);
  if (!match) return null;
  return {
    label: match[1].replace(/\\([\\[\]])/g, "$1").trim(),
    href: match[2].trim()
  };
}

function resolveMarkdownLinkToNodePath(href, options = {}) {
  const sourceRel = options.sourcePath ?? getCurrentEditorLinkBasePath();
  const targetRel = resolveMarkdownHrefToWorkspaceRel(href, sourceRel);
  if (!targetRel) return null;

  const menu = menuCacheByAgent.get(activeWorkspaceId) || currentMenuData;
  if (menu) {
    const baseTree = { title: getAgentTreeTitle(), ...menu };
    const paths = collectMenuNodePaths(baseTree);
    const exact = paths.find(
      (candidate) =>
        normalizeLinkFilePath(getLinkTargetFileRelPath(candidate)).toLowerCase() === targetRel.toLowerCase()
    );
    if (exact) return exact;
  }

  const wikiTarget = getWikilinkTargetFromNodePath(targetRel);
  if (wikiTarget) {
    const byWiki = resolveWikilinkToNodePath(wikiTarget);
    if (byWiki) return byWiki;
  }

  return null;
}

async function openMarkdownLinkIndexItem(item, options = {}) {
  if (!item) return;

  if (item.systemFile) {
    await selectSystemFile(item.systemFile);
    return;
  }

  if (!item.nodePath) return;

  const preferNavigation = Boolean(options.fromNavigationPreview || options.preferNavigation);
  const preferOverview = Boolean(options.fromNavigationPreview || options.preferOverview);

  if (item.mode === "description" && isTopicManifestPath(item.nodePath)) {
    if (preferNavigation) {
      await openNodeNavigation(getLabelFromPath(item.nodePath), item.nodePath);
    } else {
      await openMarkdownLinkNodePath(item.nodePath, options);
    }
    if (!options.skipRouteSync) {
      syncAppRouteToUrl({ push: true });
    }
    return;
  }

  if (item.mode === "external" && item.externalFile && preferOverview) {
    await selectNodeManifest(getLabelFromPath(item.nodePath), item.nodePath, "external");
    openExternalRecordOverviewFromNavigation({
      path: String(item.externalFile).replace(/\\/g, "/").replace(/\.md$/i, ""),
      title: String(item.externalFile).split("/").pop() || item.externalFile
    });
    return;
  }

  if (item.mode) {
    await selectNodeManifest(getLabelFromPath(item.nodePath), item.nodePath, item.mode);
  } else {
    await openMarkdownLinkNodePath(item.nodePath, options);
  }

  if (item.mode === "external" && item.externalFile) {
    setContentMode("external");
    if (preferOverview) {
      openExternalRecordOverviewFromNavigation({
        path: String(item.externalFile).replace(/\\/g, "/").replace(/\.md$/i, ""),
        title: String(item.externalFile).split("/").pop() || item.externalFile
      });
    } else {
      await openExternalFile(item.externalFile);
    }
  }
}

async function tryOpenMarkdownLinkByWorkspaceRel(targetRel, options = {}) {
  const normalized = normalizeLinkFilePath(targetRel);
  if (!normalized) return false;

  if (isRepositoryWorkspaceRel(normalized)) {
    return openRepositoryWorkspacePath(normalized, options);
  }

  if (isMediaLibraryWorkspaceRel(normalized)) {
    return openMediaLibraryWorkspacePath(normalized, options);
  }

  if (isAwnChannelWorkspaceRel(normalized)) {
    return openAwnChannelWorkspacePath(normalized, options);
  }

  if (/^(?:awn-databases|awn-data)(?:\/|$)/i.test(normalized)) {
    let routePath = normalized;
    if (/\/manifest\.md$/i.test(routePath)) {
      routePath = routePath.replace(/\/manifest\.md$/i, "");
    } else if (/\.md$/i.test(routePath)) {
      routePath = routePath.replace(/\.md$/i, "");
    }
    return openAwnDataRouteFromWorkspacePath(routePath, activeWorkspaceId, options);
  }

  const parsed = parseStorageLayerRef(normalized);
  if (parsed?.relativePath) {
    const manifestPath = resolveOwningManifestRelFromNodePath(normalized);
    if (!manifestPath) return false;
    const label = getLabelFromPath(manifestPath);
    const relPath = String(parsed.relativePath).replace(/\\/g, "/");

    if (parsed.layer === STORAGE_SUBFOLDER_CONTENT) {
      await selectNodeManifest(label, manifestPath, "external");
      if (/\/manifest\.md$/i.test(relPath)) {
        openExternalCategoryOverviewFromNavigation(relPath.replace(/\/manifest\.md$/i, ""));
      } else {
        openExternalRecordOverviewFromNavigation({
          path: relPath.replace(/\.md$/i, ""),
          title: relPath.split("/").pop() || relPath
        });
      }
      return true;
    }

    if (parsed.layer === STORAGE_SUBFOLDER_MEDIA) {
      await selectNodeManifest(label, manifestPath, "media");
      if (/\/manifest\.md$/i.test(relPath)) {
        openMediaCategoryOverviewFromNavigation(relPath.replace(/\/manifest\.md$/i, ""));
      } else if (/\.md$/i.test(relPath)) {
        openMediaEntryOverviewFromNavigation({
          path: relPath,
          title: relPath.split("/").pop() || relPath
        });
      } else {
        openMediaAsset(relPath, manifestPath);
      }
      return true;
    }

    const flatMode = CHPU_SLOT_FOLDER_TO_MODE[parsed.layer];
    if (flatMode && FLAT_STORAGE_SECTION_MODES.has(flatMode)) {
      await selectNodeManifest(label, manifestPath, flatMode);
      if (/\/manifest\.md$/i.test(relPath)) {
        openFlatStorageCategoryOverviewFromNavigation(relPath.replace(/\/manifest\.md$/i, ""), flatMode);
      } else {
        openFlatStorageRecordOverviewFromNavigation(
          { path: relPath.replace(/\.md$/i, ""), title: relPath.split("/").pop() || relPath },
          flatMode
        );
      }
      return true;
    }
  }

  const manifestPath = resolveOwningManifestRelFromNodePath(normalized);
  if (manifestPath && manifestPath !== normalized) {
    const sidecarModes = [
      ["content", "internal"],
      ["tabular", "tabular"],
      ["todo", "todo"]
    ];
    for (const [kind, mode] of sidecarModes) {
      const sidecarPath = normalizeLinkFilePath(resolveNodeSidecarRelPath(manifestPath, kind));
      if (sidecarPath && sidecarPath.toLowerCase() === normalized.toLowerCase()) {
        await selectNodeManifest(getLabelFromPath(manifestPath), manifestPath, mode);
        return true;
      }
    }
  }

  if (/manifest\.md$/i.test(normalized)) {
    const menu = menuCacheByAgent.get(activeWorkspaceId) || currentMenuData;
    if (menu) {
      const paths = collectMenuNodePaths({ title: getAgentTreeTitle(), ...menu });
      const exact = paths.find(
        (candidate) => normalizeLinkFilePath(candidate).toLowerCase() === normalized.toLowerCase()
      );
      if (exact) {
        await openMarkdownLinkNodePath(exact, options);
        return true;
      }
    }
    return false;
  }

  return false;
}

async function tryOpenSameOriginAppUrl(href) {
  let url;
  try {
    url = new URL(href, location.origin);
  } catch {
    return false;
  }
  if (url.origin !== location.origin) return false;

  const route = parseAppRoute(url.pathname);
  if (route.type === "root" || route.type === "legacy") return false;

  if (route.agentId) {
    const selectable = getSelectableAgents();
    if (!selectable.some((agent) => agent.id === route.agentId)) return false;
    if (route.agentId !== activeWorkspaceId) {
      await switchActiveAgent(route.agentId);
    }
  }

  history.pushState(null, "", `${url.pathname}${url.search}${url.hash}`);
  await applyAppRouteFromUrl();
  return true;
}

async function openMarkdownLinkNodePath(nodePath, options = {}) {
  const normalized = normalizeMenuNodePath(nodePath);
  if (!normalized) return;
  const label = getLabelFromPath(normalized);
  if (isTopicManifestPath(normalized)) {
    await openNodeNavigation(label, normalized);
    if (!options.skipRouteSync) {
      syncAppRouteToUrl({ push: true });
    }
    return;
  }
  await openNodeFromMenu(label, normalized, options);
}

async function openMarkdownLinkTarget(href, sourcePath = getCurrentEditorLinkBasePath(), options = {}) {
  const value = String(href || "").trim();
  if (!value) return;

  if (/^https?:\/\//i.test(value)) {
    if (await tryOpenSameOriginAppUrl(value)) return;
    window.open(value, "_blank", "noopener,noreferrer");
    return;
  }

  const targetRel = resolveMarkdownHrefToWorkspaceRel(value, sourcePath);
  if (targetRel && (await tryOpenMarkdownLinkByWorkspaceRel(targetRel, options))) {
    return;
  }

  const nodePath = resolveMarkdownLinkToNodePath(value, { sourcePath });
  if (nodePath) {
    await openMarkdownLinkNodePath(nodePath, options);
    return;
  }

  if (!targetRel) return;

  if (!(markdownLinkIndexCache.items || []).length) {
    await loadMarkdownLinkIndex();
  }

  const indexItem = (markdownLinkIndexCache.items || []).find(
    (item) => normalizeLinkFilePath(item.relPath).toLowerCase() === targetRel.toLowerCase()
  );
  if (indexItem && (indexItem.nodePath || indexItem.systemFile)) {
    await openMarkdownLinkIndexItem(indexItem, options);
    return;
  }

  if (indexItem) {
    await openWorkspaceFilePreviewByRelPath(targetRel, {
      label: indexItem.label || getLabelFromPath(targetRel),
      nodePath: resolveOwningManifestRelFromNodePath(targetRel) || undefined
    });
    return;
  }

  const owningManifest = resolveOwningManifestRelFromNodePath(targetRel);
  const recordManifest = owningManifest || getResolvedNodePath(activePath);
  const record = (propsLibrariesCache.contentRecords || []).find((item) => {
    const recordRel = normalizeLinkFilePath(
      `${getNodeStorageSubfolderPath(recordManifest, "external")}/${item.relativePath}`
    );
    return (
      recordRel.toLowerCase() === targetRel.toLowerCase() ||
      normalizeLinkFilePath(item.relativePath).toLowerCase() === targetRel.toLowerCase() ||
      item.relativePath.replace(/\.md$/i, "").toLowerCase() === targetRel.replace(/\.md$/i, "").toLowerCase()
    );
  });
  if (record && recordManifest) {
    const label = getLabelFromPath(recordManifest);
    if (normalizeMenuNodePath(recordManifest) !== normalizeMenuNodePath(activePath)) {
      await selectNodeManifest(label, recordManifest, "external");
    } else {
      await openNodeMemoryWorkspace(activeLabel || label, activePath);
      setContentMode("external");
    }
    if (options.fromNavigationPreview || options.preferOverview) {
      openExternalRecordOverviewFromNavigation({
        path: record.relativePath.replace(/\.md$/i, ""),
        title: record.label || record.relativePath.split("/").pop() || record.relativePath
      });
    } else {
      await openExternalFile(record.relativePath);
    }
    return;
  }

  const systemName = normalizeSystemFileName(targetRel.split("/").pop() || targetRel);
  if (systemFilesCache.some((file) => normalizeSystemFileName(file.name) === systemName)) {
    await selectSystemFile(systemName);
    return;
  }

  if (await tryOpenAdoptWorkspaceRel(targetRel, options)) {
    return;
  }

  showToast(`Ссылка не найдена: ${value}`, "error");
}

function resolveWikilinkToNodePath(target, alias) {
  const slug = String(target || "").replace(/\\/g, "/").trim();
  if (!slug) return null;

  const menu = menuCacheByAgent.get(activeWorkspaceId) || currentMenuData;
  if (!menu) return null;
  const baseTree = { title: getAgentTreeTitle(), ...menu };
  const paths = collectMenuNodePaths(baseTree);

  const exact = paths.find((candidate) => getWikilinkTargetFromNodePath(candidate) === slug);
  if (exact) return exact;

  const lower = slug.toLowerCase();
  const caseInsensitive = paths.find(
    (candidate) => getWikilinkTargetFromNodePath(candidate).toLowerCase() === lower
  );
  if (caseInsensitive) return caseInsensitive;

  const aliasNorm = String(alias || "").trim();
  if (aliasNorm) {
    const byLabel = paths.find((candidate) => getLabelFromPath(candidate) === aliasNorm);
    if (byLabel) return byLabel;
  }

  const base = slug.includes("/") ? slug.slice(slug.lastIndexOf("/") + 1) : slug;
  const byBase = paths.filter((candidate) => {
    const linkTarget = getWikilinkTargetFromNodePath(candidate);
    const linkBase = linkTarget.includes("/") ? linkTarget.slice(linkTarget.lastIndexOf("/") + 1) : linkTarget;
    return linkBase.toLowerCase() === base.toLowerCase();
  });
  if (byBase.length === 1) return byBase[0];

  return null;
}

function dataTransferHasMenuLink(dataTransfer) {
  if (!dataTransfer?.types) return false;
  const types = [...dataTransfer.types];
  if (types.includes("Files")) return false;
  return types.includes(MENU_LINK_DRAG_MIME) || types.includes("text/plain");
}

function dataTransferHasVoiceChatLink(dataTransfer) {
  if (!dataTransfer?.types) return false;
  const types = [...dataTransfer.types];
  if (types.includes("Files")) return false;
  return types.includes(MENU_LINK_DRAG_MIME);
}

function extractMenuLinkFromDataTransfer(dataTransfer) {
  if (!dataTransfer) return null;
  const raw = dataTransfer.getData(MENU_LINK_DRAG_MIME);
  if (raw) {
    try {
      const payload = JSON.parse(raw);
      if (payload?.path || payload?.markdownLink || payload?.wikilink || payload?.text) return payload;
    } catch {
      // ignore malformed payload
    }
  }
  const plain = String(dataTransfer.getData("text/plain") || "").trim();
  const markdown = parseMarkdownLinkValue(plain);
  if (markdown) {
    return { markdownLink: plain, label: markdown.label, href: markdown.href };
  }
  const match = plain.match(/^\[\[([^\]|#]+)(?:#[^\]|]+)?(?:\|([^\]]+))?\]\]$/);
  if (match) {
    const target = match[1].trim();
    const alias = String(match[2] || "").trim();
    const nodePath = resolveWikilinkToNodePath(target, alias);
    if (nodePath) {
      return {
        path: nodePath,
        label: alias || getLabelFromPath(nodePath),
        wikilink: plain
      };
    }
  }
  if (plain) {
    return { text: plain, markdownLink: plain, label: plain };
  }
  return null;
}

function setMenuLinkDragPayload(event, payload) {
  const linkText = String(payload?.markdownLink || payload?.wikilink || payload?.text || "").trim();
  if (!linkText || !event?.dataTransfer) return false;
  const workspaceRel = resolveVoiceChatWorkspaceRelFromPayload(payload);
  const voiceMarkdownLink =
    String(payload?.voiceMarkdownLink || "").trim() ||
    (workspaceRel ? buildVoiceChatMarkdownLink(workspaceRel, payload?.label || linkText) : linkText);
  event.dataTransfer.effectAllowed = "copy";
  event.dataTransfer.setData(
    MENU_LINK_DRAG_MIME,
    JSON.stringify({ ...payload, markdownLink: linkText, voiceMarkdownLink })
  );
  event.dataTransfer.setData("text/plain", linkText);
  return true;
}

function markVoiceChatDropActive(dataTransfer) {
  queueMicrotask(() => {
    if (dataTransferHasVoiceChatLink(dataTransfer)) {
      document.body.classList.add("is-voice-chat-drop-active");
    }
  });
}

function parseNavBookTocPathFromTitle(title) {
  const raw = String(title || "").trim();
  if (!raw) return "";
  const paren = raw.indexOf(" (");
  return (paren >= 0 ? raw.slice(0, paren) : raw).trim();
}

function buildNavigationTocFileWorkspaceRel(filePath, memoryKind = "external", nodePath = activePath) {
  const rel = String(filePath || "").replace(/\\/g, "/").replace(/^\/+/, "").trim();
  if (!rel) return "";
  const kind = String(memoryKind || "external").trim() || "external";
  if (kind === "external") {
    return getExternalItemContextPath({ path: rel }, nodePath);
  }
  const resolvedNode = getResolvedNodePath(nodePath);
  const storageRel = buildNodeReadContentStoragePath(rel, kind);
  return resolvedNode ? `${resolvedNode}/${storageRel}`.replace(/\/+/g, "/") : storageRel;
}

