  if (title.endsWith(hintSuffix)) {
    return sanitizeVoiceChatDragLabel(title.slice(0, -hintSuffix.length).trim());
  }
  return sanitizeVoiceChatDragLabel(title || filePath.split("/").pop() || filePath);
