function isWorkspaceAgentPreviewApiUrl(url) {
  return String(url || "").includes("/api/agents/workspace-preview");
}

function resolveWorkspaceAgentPreviewMeta(previewMeta = null) {
  const agent = getActiveAgentMeta();
  const candidateUrl = previewMeta?.previewUrl ?? agent?.previewUrl ?? null;
  if (previewMeta?.hasPreview && isWorkspaceAgentPreviewApiUrl(candidateUrl)) {
    return { hasPreview: true, previewUrl: candidateUrl };
  }
  if (agent?.hasPreview && isWorkspaceAgentPreviewApiUrl(candidateUrl)) {
    return { hasPreview: true, previewUrl: candidateUrl };
  }
  return { hasPreview: false, previewUrl: null };
}

function resolveSidebarAgentPreviewMeta(previewMeta = null, { preferWorkspacePreview = false } = {}) {
  const workspacePreview = resolveWorkspaceAgentPreviewMeta(previewMeta);
  if (preferWorkspacePreview && workspacePreview.hasPreview) {
    return workspacePreview;
  }

  const agent = getActiveAgentMeta();
  if (
    agent?.id &&
    agentSliderPlaybackOrder.length > 0 &&
    agentSliderCatalog.loadedForAgentId === agent.id
  ) {
    const slide = agentSliderPlaybackOrder[agentSliderIndex % agentSliderPlaybackOrder.length];
    if (slide?.isWorkspacePreview && slide.previewUrl) {
      return {
        hasPreview: true,
        previewUrl: slide.previewUrl,
        source: "slider"
      };
    }
    if (slide?.mediaFile) {
      return {
        hasPreview: true,
        previewUrl: buildAgentSliderMediaApiUrl(slide.mediaFile, agent.id),
        source: "slider"
      };
    }
  }

  if (workspacePreview.hasPreview) return workspacePreview;
  return { hasPreview: false, previewUrl: null };
}

function syncAgentPreviewSlideCounter() {
  if (!agentPreviewSlideCounterNode) return;
  const agent = getActiveAgentMeta();
  const catalogFiles =
    agent?.id && agentSliderCatalog.loadedForAgentId === agent.id ? getAgentSliderPlaybackSourceSlides() : [];
  const total = catalogFiles.length;
  const showingSlider = agentSliderPlaybackOrder.length > 0 && total > 0;
  if (!showingSlider) {
    agentPreviewSlideCounterNode.classList.add("hidden");
    agentPreviewSlideCounterNode.textContent = "";
    return;
  }
  const playbackIndex =
    ((agentSliderIndex % agentSliderPlaybackOrder.length) + agentSliderPlaybackOrder.length) %
    agentSliderPlaybackOrder.length;
  const currentSlide = agentSliderPlaybackOrder[playbackIndex];
  const catalogIndex = catalogFiles.findIndex(
    (file) =>
      (file.isAvatarSlide && currentSlide?.isAvatarSlide) ||
      file.mediaFile === currentSlide?.mediaFile ||
      file.name === currentSlide?.name
  );
  const currentNum = catalogIndex >= 0 ? catalogIndex + 1 : playbackIndex + 1;
  agentPreviewSlideCounterNode.textContent = `${currentNum} / ${total}`;
  agentPreviewSlideCounterNode.classList.remove("hidden");
}

function buildAgentSliderLightboxGallery() {
  const agentId = agentSliderCatalog.loadedForAgentId || activeWorkspaceId;
  const files = getAgentSliderPlaybackSourceSlides();
  if (!files.length) return null;
  const images = files.map((file) => {
    if (file.isWorkspacePreview && file.previewUrl) {
      return {
        src: appendCacheBuster(appendAgentToApiUrl(file.previewUrl, agentId)),
        alt: file.name || "Превью workspace"
      };
    }
    return {
      src: appendCacheBuster(buildAgentSliderMediaApiUrl(file.mediaFile, agentId)),
      alt: file.name || "Слайд"
    };
  });
  let index = 0;
  if (agentSliderPlaybackOrder.length) {
    const playbackIndex =
      ((agentSliderIndex % agentSliderPlaybackOrder.length) + agentSliderPlaybackOrder.length) %
      agentSliderPlaybackOrder.length;
    const currentSlide = agentSliderPlaybackOrder[playbackIndex];
    const catalogIndex = files.findIndex(
      (file) =>
        (file.isAvatarSlide && currentSlide?.isAvatarSlide) ||
        file.mediaFile === currentSlide?.mediaFile ||
        file.name === currentSlide?.name
    );
    if (catalogIndex >= 0) index = catalogIndex;
  }
  return { images, index };
}

function openAgentPreviewLightbox() {
  const agent = getActiveAgentMeta();
  const hasSlider = Boolean(
    agent?.id &&
      agentSliderPlaybackOrder.length > 0 &&
      agentSliderCatalog.loadedForAgentId === agent.id
  );
  if (hasSlider) {
    const gallery = buildAgentSliderLightboxGallery();
    if (!gallery?.images.length) return;
    ensurePreviewImageLightbox();
    previewLightboxGallery = gallery;
    showPreviewLightboxSlide(gallery.index);
    previewLightboxNode.classList.remove("hidden");
    return;
  }
  const thumb = agentPreviewThumbNode;
  if (!thumb) return;
  const fullSrc = thumb.dataset.fullSrc || thumb.currentSrc || thumb.src;
  if (!fullSrc) return;
  openPreviewImageLightbox(fullSrc, thumb.alt || "", { trigger: thumb });
}

function syncAgentPreview(previewMeta = null, options = {}) {
  const targets = [{ wrap: agentPreviewWrapNode, thumb: agentPreviewThumbNode, primary: true }].filter(
    (target) => target.wrap && target.thumb
  );
  if (!targets.length) return;

  const agent = getActiveAgentMeta();
  const resolvedPreview = resolveSidebarAgentPreviewMeta(previewMeta, options);
  let hasPreview = Boolean(resolvedPreview.hasPreview);
  let previewUrl = resolvedPreview.previewUrl;

  if (previewMeta && isWorkspaceAgentPreviewApiUrl(previewMeta.previewUrl)) {
    updateAgentPreviewCache(previewMeta);
  }

  if (hasPreview && previewUrl && !isBrokenImageSrc(previewUrl, activePath)) {
    syncAgentPreviewPlaceholder({ broken: false });
    const fullSrc = appendCacheBuster(appendAgentToApiUrl(previewUrl));
    const nextSrc = appendMediaThumbToApiUrl(fullSrc, MEDIA_THUMB_MAX_PREVIEW);

    for (const target of targets) {
      const currentSrc = target.thumb.getAttribute("src") || "";
      const srcChanged = currentSrc !== nextSrc;
      const alreadyLoaded = !srcChanged && target.thumb.complete;

      target.wrap.classList.remove("hidden");
      if (srcChanged) target.wrap.classList.remove("is-revealed");

      target.thumb.onerror = () => {
        target.thumb.onerror = null;
        if (
          target.primary &&
          resolvedPreview.source === "slider" &&
          resolveWorkspaceAgentPreviewMeta(previewMeta).hasPreview
        ) {
          syncAgentPreview(previewMeta, { preferWorkspacePreview: true });
          return;
        }
        target.wrap.classList.add("hidden");
        target.wrap.classList.remove("is-revealed");
        target.thumb.removeAttribute("src");
        if (target.primary) syncAgentPreviewPlaceholder({ broken: true });
      };
      target.thumb.onload = () => {
        target.thumb.onerror = null;
        target.wrap.classList.add("is-revealed");
        if (target.primary) syncAgentPreviewPlaceholder({ broken: false });
      };

      target.thumb.dataset.fullSrc = fullSrc;
      if (srcChanged) {
        target.thumb.src = nextSrc;
      } else if (alreadyLoaded && !target.wrap.classList.contains("is-revealed")) {
        target.wrap.classList.add("is-revealed");
      }
    }

    syncAgentPreviewSlideCounter();
    syncAgentPreviewOpenUi();
    maybeRebuildAgentSliderPlayback();
    return;
  }

  for (const target of targets) {
    if (target.primary && getActiveAgentMeta()?.path) {
      target.wrap.classList.remove("hidden");
      target.wrap.classList.remove("is-revealed");
      target.thumb.removeAttribute("src");
      continue;
    }
    target.wrap.classList.add("hidden");
    target.wrap.classList.remove("is-revealed");
    target.thumb.removeAttribute("src");
  }
  syncAgentPreviewPlaceholder({ broken: Boolean(hasPreview && previewUrl) });
  syncAgentPreviewSlideCounter();
  syncAgentPreviewOpenUi();
  maybeRebuildAgentSliderPlayback();
}

