function getAgentTodoSidebarPreviewMarkdown(raw = "") {
  let text = String(raw || "").trim();
  if (!text) return "";

  const dividerMatch = text.match(/^[\t ]*-{3,}[\t ]*$(?:\r?\n|$)/m);
  if (dividerMatch) {
    text = text.slice(0, dividerMatch.index).trim();
  }

  return text;
}

