const AGENT_SLIDER_FOLDER_REF = "awn-media/0-slider/awn-storage/files";
const AGENT_SLIDER_MANIFEST_REF = "awn-media/0-slider/manifest.md";
const LEGACY_AGENT_SLIDER_FOLDER_REFS = new Set([
  "awn-storage/editor/assets/slider",
  "storage/editor/assets/slider",
  "awn-media/slider/awn-storage/assets",
  "awn-media/slider/awn-storage/files"
]);
const AGENT_SLIDER_ROTATE_MS = 12000;

function normalizeAgentSliderFolderPath(folderPath) {
  const normalized = String(folderPath || "")
    .replace(/\\/g, "/")
    .replace(/^\/+/, "")
    .replace(/\/+$/, "");
  if (!normalized || LEGACY_AGENT_SLIDER_FOLDER_REFS.has(normalized.toLowerCase())) {
    return AGENT_SLIDER_FOLDER_REF;
  }
  if (/^awn-media\/(?:0-slider|slider)\/awn-storage\/(?:assets|files)$/i.test(normalized)) {
    return AGENT_SLIDER_FOLDER_REF;
  }
  return normalized;
}

function normalizeAgentSliderManifestPath(manifestPath) {
  const normalized = String(manifestPath || "")
    .replace(/\\/g, "/")
    .replace(/^\/+/, "")
    .trim();
  if (!normalized || LEGACY_AGENT_SLIDER_FOLDER_REFS.has(normalized.toLowerCase())) {
    return AGENT_SLIDER_MANIFEST_REF;
  }
  if (/^awn-media\/(?:0-slider|slider)\/manifest\.md$/i.test(normalized)) {
    return AGENT_SLIDER_MANIFEST_REF;
  }
  return normalized || AGENT_SLIDER_MANIFEST_REF;
}
let agentSliderCatalog = {
  folderPath: AGENT_SLIDER_FOLDER_REF,
  manifestPath: AGENT_SLIDER_MANIFEST_REF,
  files: [],
  loadedForAgentId: null
};
let agentSliderPlaybackOrder = [];
let agentSliderRotateTimer = null;
let agentSliderIndex = 0;

function shuffleAgentSliderFiles(files) {
  const shuffled = files.slice();
  for (let index = shuffled.length - 1; index > 0; index -= 1) {
    const swapIndex = Math.floor(Math.random() * (index + 1));
    [shuffled[index], shuffled[swapIndex]] = [shuffled[swapIndex], shuffled[index]];
  }
  return shuffled;
}

function getAgentSliderCatalogFiles() {
  return Array.isArray(agentSliderCatalog.files) ? agentSliderCatalog.files : [];
}

function buildAgentSliderAvatarSlide() {
  const workspacePreview = resolveWorkspaceAgentPreviewMeta();
  if (!workspacePreview.hasPreview || !workspacePreview.previewUrl) return null;
  return {
    name: "Аватар",
    mediaFile: "",
    isAvatarSlide: true,
    isWorkspacePreview: true,
    previewUrl: workspacePreview.previewUrl
  };
}

function getAgentSliderPlaybackSourceSlides() {
  const files = getAgentSliderCatalogFiles();
  const avatar = buildAgentSliderAvatarSlide();
  if (!avatar) return files;
  return [avatar, ...files];
}

function maybeRebuildAgentSliderPlayback() {
  const agent = getActiveAgentMeta();
  if (!agent?.id || agentSliderCatalog.loadedForAgentId !== agent.id) return;
  const sourceSlides = getAgentSliderPlaybackSourceSlides();
  if (!sourceSlides.length) {
    if (agentSliderPlaybackOrder.length) {
      agentSliderPlaybackOrder = [];
      agentSliderIndex = 0;
      stopAgentSliderRotation();
    }
    return;
  }
  const needsRebuild =
    !agentSliderPlaybackOrder.length ||
    agentSliderPlaybackOrder.length !== sourceSlides.length ||
    Boolean(agentSliderPlaybackOrder[0]?.isAvatarSlide) !== Boolean(sourceSlides[0]?.isAvatarSlide);
  if (needsRebuild) {
    rebuildAgentSliderPlaybackOrder({ resetIndex: !agentSliderPlaybackOrder.length });
    restartAgentSliderRotation();
  }
}

function rebuildAgentSliderPlaybackOrder({ resetIndex = true } = {}) {
  const slides = getAgentSliderPlaybackSourceSlides();
  if (!slides.length) {
    agentSliderPlaybackOrder = [];
    agentSliderIndex = 0;
    return;
  }
  const avatar = slides[0]?.isAvatarSlide ? slides[0] : null;
  const rest = avatar ? slides.slice(1) : slides;
  agentSliderPlaybackOrder = avatar ? [avatar, ...shuffleAgentSliderFiles(rest)] : shuffleAgentSliderFiles(rest);
  if (resetIndex) {
    agentSliderIndex = agentSliderPlaybackOrder.length > 1 ? 1 : 0;
    return;
  }
  if (agentSliderIndex >= agentSliderPlaybackOrder.length) {
    agentSliderIndex = 0;
  }
}

function buildAgentSliderMediaApiUrl(mediaFile, agentId = activeWorkspaceId) {
  let relFile = String(mediaFile || "").replace(/\\/g, "/").replace(/^\/+/, "");
  if (!relFile) return "";
  relFile = relFile.replace(/^slider\//i, "");
  const manifestPath =
    String(agentSliderCatalog.manifestPath || AGENT_SLIDER_MANIFEST_REF).trim() ||
    AGENT_SLIDER_MANIFEST_REF;
  return buildApiUrl(
    "/api/media/file",
    { path: manifestPath, file: relFile, folder: STORAGE_SUBFOLDER_FILES },
    agentId
  );
}

function stopAgentSliderRotation() {
  if (agentSliderRotateTimer) {
    clearInterval(agentSliderRotateTimer);
    agentSliderRotateTimer = null;
  }
}

function restartAgentSliderRotation() {
  stopAgentSliderRotation();
  if (agentSliderPlaybackOrder.length < 2) return;
  agentSliderRotateTimer = setInterval(() => {
    if (agentSliderAvatarHoverActive) return;
    agentSliderIndex = (agentSliderIndex + 1) % agentSliderPlaybackOrder.length;
    if (agentSliderIndex === 0 && agentSliderPlaybackOrder.length > 1) {
      const avatar = agentSliderPlaybackOrder[0]?.isAvatarSlide ? agentSliderPlaybackOrder[0] : null;
      const rest = avatar ? agentSliderPlaybackOrder.slice(1) : agentSliderPlaybackOrder;
      agentSliderPlaybackOrder = avatar
        ? [avatar, ...shuffleAgentSliderFiles(rest)]
        : shuffleAgentSliderFiles(rest);
    }
    syncAgentPreview();
  }, AGENT_SLIDER_ROTATE_MS);
}

async function refreshAgentSliderCatalog(force = false) {
  const agent = getActiveAgentMeta();
  if (!agent?.path) {
    agentSliderCatalog = {
      folderPath: AGENT_SLIDER_FOLDER_REF,
      manifestPath: AGENT_SLIDER_MANIFEST_REF,
      files: [],
      loadedForAgentId: null
    };
    agentSliderPlaybackOrder = [];
    agentSliderIndex = 0;
    stopAgentSliderRotation();
    return agentSliderCatalog;
  }

  if (!force && agentSliderCatalog.loadedForAgentId === agent.id) {
    return agentSliderCatalog;
  }

  try {
    const response = await fetch(buildApiUrl("/api/agents/slider", {}, agent.id));
    if (!response.ok) throw new Error(`Request failed with ${response.status}`);
    const data = await response.json();
    agentSliderCatalog = {
      folderPath: normalizeAgentSliderFolderPath(data.folderPath),
      manifestPath: normalizeAgentSliderManifestPath(data.manifestPath),
      files: Array.isArray(data.files) ? data.files : [],
      loadedForAgentId: agent.id
    };
  } catch {
    agentSliderCatalog = {
      folderPath: AGENT_SLIDER_FOLDER_REF,
      manifestPath: AGENT_SLIDER_MANIFEST_REF,
      files: [],
      loadedForAgentId: agent.id
    };
  }

  rebuildAgentSliderPlaybackOrder({ resetIndex: true });
  restartAgentSliderRotation();
  return agentSliderCatalog;
}

