function normalizeAwnEmoji(value) {
  const text = String(value ?? "").trim();
  if (!text) return "";
  if (typeof Intl !== "undefined" && typeof Intl.Segmenter === "function") {
    const segmenter = new Intl.Segmenter("ru", { granularity: "grapheme" });
    const first = [...segmenter.segment(text)][0];
    return first?.segment || text;
  }
  return [...text][0] || text;
}

function resolveAwnEmoji(source) {
  if (!source) return "";
  if (typeof source === "string") return normalizeAwnEmoji(source);
  const raw =
    source["awn-emoji"] ??
    source.awnEmoji ??
    source.awnProps?.["awn-emoji"] ??
    "";
  return normalizeAwnEmoji(raw);
}

function createPreviewFallbackNode({ emoji = "", fallbackText = "?", emojiClass, initialsClass }) {
  const node = document.createElement("span");
  if (emoji) {
    node.className = emojiClass;
    node.textContent = emoji;
    node.setAttribute("aria-hidden", "true");
  } else {
    node.className = initialsClass;
    node.textContent = fallbackText;
  }
  return node;
}

function resolvePreviewLoadTimeoutMs(imageUrl) {
  const url = String(imageUrl || "").trim();
  if (!url) return PREVIEW_LOAD_TIMEOUT_DEFAULT_MS;
  if (/^https?:\/\//i.test(url)) {
    try {
      const parsed = new URL(url, window.location.origin);
      if (parsed.origin !== window.location.origin) {
        return PREVIEW_LOAD_TIMEOUT_EXTERNAL_MS;
      }
    } catch {
      return PREVIEW_LOAD_TIMEOUT_EXTERNAL_MS;
    }
  }
  return PREVIEW_LOAD_TIMEOUT_DEFAULT_MS;
}

function bindPreviewImageLifecycle(
  img,
  {
    loadingClassTarget = null,
    timeoutMs = PREVIEW_LOAD_TIMEOUT_DEFAULT_MS,
    onSuccess = () => {},
    onFail = () => {}
  } = {}
) {
  let settled = false;
  let timeoutId = 0;

  const clearLoading = () => {
    loadingClassTarget?.classList?.remove("is-preview-loading");
  };

  const settle = (outcome) => {
    if (settled) return;
    settled = true;
    if (timeoutId) window.clearTimeout(timeoutId);
    clearLoading();
    if (outcome === "success") onSuccess(img);
    else onFail(img);
  };

  if (loadingClassTarget && timeoutMs > 0) {
    loadingClassTarget.classList.add("is-preview-loading");
  }

  img.addEventListener(
    "load",
    () => {
      if (img.naturalWidth > 0) settle("success");
      else settle("fail");
    },
    { once: true }
  );
  img.addEventListener("error", () => settle("fail"), { once: true });

  if (timeoutMs > 0) {
    timeoutId = window.setTimeout(() => settle("fail"), timeoutMs);
  }

  return {
    checkAlreadyLoaded() {
      if (!img.complete) return;
      if (img.naturalWidth > 0) settle("success");
      else settle("fail");
    }
  };
}

function mountPreviewOrFallback(container, {
  previewUrl = "",
  emoji = "",
  fallbackText = "?",
  emojiClass,
  initialsClass,
  emptyClass = "",
  nodePath = "",
  iconClass = ""
}) {
  const mountFallback = () => {
    container.replaceChildren();
    if (emoji) {
      container.appendChild(
        createPreviewFallbackNode({ emoji, fallbackText, emojiClass, initialsClass })
      );
      return;
    }
    if (emptyClass) {
      const empty = document.createElement("span");
      empty.className = emptyClass;
      empty.setAttribute("aria-hidden", "true");
      container.appendChild(empty);
      return;
    }
    if (nodePath) {
      const icon = createNodeCoverFallbackElement({
        nodePath,
        emojiClass,
        iconClass
      });
      container.appendChild(icon);
      return;
    }
    container.appendChild(
      createPreviewFallbackNode({ emoji: "", fallbackText, emojiClass, initialsClass })
    );
  };

  if (previewUrl) {
    const img = document.createElement("img");
    img.alt = "";
    img.draggable = false;
    container.replaceChildren();
    container.appendChild(img);
    const lifecycle = bindPreviewImageLifecycle(img, {
      loadingClassTarget: container,
      timeoutMs: resolvePreviewLoadTimeoutMs(previewUrl),
      onFail: () => mountFallback()
    });
    img.src = previewUrl;
    lifecycle.checkAlreadyLoaded();
    return;
  }

  container.classList.remove("is-preview-loading");
  mountFallback();
}

