function isPlatformAgent(agent) {
  const fn = globalThis.isPlatformAgent;
  if (typeof fn === "function" && fn !== isPlatformAgent) {
    return fn(agent);
  }
  return agent?.virtual === true || String(agent?.id || "").trim() === "platform";
}

