function normalizeAwnEmoji(value) {
  const text = String(value ?? "").trim();
  if (!text) return "";
  if (typeof Intl !== "undefined" && typeof Intl.Segmenter === "function") {
    const segmenter = new Intl.Segmenter("ru", { granularity: "grapheme" });
    const first = [...segmenter.segment(text)][0];
    return first?.segment || text;
  }
  return [...text][0] || text;
}

function resolveAgentSelectStatusEmoji(agent) {
  const fromStatus = normalizeAwnEmoji(agent?.awnProps?.["awn-status"] || agent?.status || "");
  if (fromStatus) return fromStatus;
  const fromEmoji = normalizeAwnEmoji(agent?.awnProps?.["awn-emoji"] || "");
  if (fromEmoji) return fromEmoji;
  if (agent?.folderExists === false) return "🔴";
  if (!isAgentRegistryActive(agent)) return "⚪";
  return "🟢";
}

function formatAgentSelectLabel(agent, groupTitle = "") {
  const registryActive = isAgentRegistryActive(agent);
  const name = agent.name || agent.id;
  let label = registryActive ? name : `${name} (выкл.)`;
  if (isPlatformAgent(agent)) {
    label = `${name} — глобальные справочники`;
  }
  if (isOrchestratorAgent(agent)) {
    return `${resolveAgentSelectStatusEmoji(agent)} ★ ${label}`;
  }
  const prefix = String(groupTitle || "").trim();
  const core = prefix ? `${prefix} | ${label}` : label;
  return `${resolveAgentSelectStatusEmoji(agent)} ${core}`;
}

function createAgentSelectOption(agent, groupTitle = "") {
  const option = document.createElement("option");
  option.value = agent.id;
  option.textContent = formatAgentSelectLabel(agent, groupTitle);
  if (isOrchestratorAgent(agent)) {
    option.title = "Оркестратор";
  }
  option.disabled = !isAgentRegistryActive(agent);
  return option;
}

function renderAgentSelectGrouped(agents) {
  const platformAgents = agents.filter(isPlatformAgent);
  const workspaceAgents = agents.filter((agent) => !isPlatformAgent(agent));
  const { orchestrator } = splitLandingOrchestratorAgent(workspaceAgents);
  const { grouped, ungrouped } = buildLandingGroupsLayout(workspaceAgents, landingAgentsGroupsCache);

  for (const agent of platformAgents) {
    agentSelectNode.appendChild(createAgentSelectOption(agent, "Платформа"));
  }

  if (orchestrator) {
    agentSelectNode.appendChild(createAgentSelectOption(orchestrator));
  }

  for (const group of grouped) {
    const groupTitle = group.title || group.id;
    for (const agent of group.agents || []) {
      agentSelectNode.appendChild(createAgentSelectOption(agent, groupTitle));
    }
  }

  for (const agent of ungrouped) {
    agentSelectNode.appendChild(createAgentSelectOption(agent));
  }
}

function renderAgentSelectFlat(agents) {
  for (const agent of agents) {
    agentSelectNode.appendChild(createAgentSelectOption(agent));
  }
}

function renderAgentSelect() {
  if (!agentSelectNode) return;

  const agents = getRegistryAgentsForUi();
  const selectableAgents = getSelectableAgents();
  const previousValue = agentSelectNode.value;
  agentSelectNode.innerHTML = "";

  const placeholderOption = document.createElement("option");
  placeholderOption.value = "";
  placeholderOption.textContent = "— Хранилище (агент) —";
  agentSelectNode.appendChild(placeholderOption);

  if (agents.length === 0) {
    placeholderOption.textContent = "Нет агентов";
    placeholderOption.disabled = true;
    agentSelectNode.disabled = true;
    syncAgentPreview();
    return;
  }

  if (landingAgentsGroupsCache.length > 0) {
    renderAgentSelectGrouped(agents);
  } else {
    renderAgentSelectFlat(agents);
  }

  agentSelectNode.disabled = false;
  const nextValue =
    activeWorkspaceId && selectableAgents.some((agent) => agent.id === activeWorkspaceId)
      ? activeWorkspaceId
      : previousValue && selectableAgents.some((agent) => agent.id === previousValue)
        ? previousValue
        : "";
  agentSelectNode.value = nextValue;
  void refreshAgentSliderCatalog(true).then(() => syncAgentPreview());
  syncIdentityToolbarAvatars(nextValue || activeWorkspaceId);
  refreshAgentsPickerIfOpen();
}

