const HUB_FOCUS_TWIG_LIMIT = 8;

function mapMenuEntryToLandingTopicItem(agent, entry, nodePath) {
  const path = normalizeMenuNodePath(nodePath || entry?.path || entry?.indexPath || "");
  if (!path || path === "_registration.md") return null;
  const name =
    String(entry?.label || entry?.title || getLabelFromPath(path) || "").trim() || getLabelFromPath(path);
  const tags = Array.isArray(entry?.tags) ? entry.tags : [];
  const status = String(entry?.status || "").trim();
  const category = String(entry?.category || "").trim();
  return {
    agentId: agent.id,
    agentName: agent.name || agent.id,
    agentPath: agent.path,
    agentActive: agent.active !== false,
    nodePath: path,
    name,
    awnType: String(entry?.awnType || "").trim(),
    awnProps: {
      "awn-status": status,
      "awn-category": category,
      "awn-tags": tags.join(", ")
    },
    catalogDisplay: {
      "awn-status": status,
      "awn-category": category,
      "awn-tags": tags.join(", ")
    },
    nodePreviewUrl: entry?.previewUrl || null,
    agentPreviewUrl: getRegistryAgentPreviewUrl(agent)
  };
}

function collectLandingHubOrbitTopicsFromMenuNode(
  node,
  agent,
  depth,
  maxDepth,
  parentSectionPath,
  acc,
  seen
) {
  if (!node || depth > maxDepth) return;

  if (depth > 0 && node.indexPath) {
    const topic = mapMenuEntryToLandingTopicItem(agent, node, node.indexPath);
    if (topic && !seen.has(topic.nodePath)) {
      seen.add(topic.nodePath);
      acc.push(topic);
    }
  }

  for (const item of node.items || []) {
    if (!item?.path) continue;
    const topic = mapMenuEntryToLandingTopicItem(agent, item, item.path);
    if (topic && !seen.has(topic.nodePath)) {
      seen.add(topic.nodePath);
      acc.push(topic);
    }
  }

  if (depth >= maxDepth) return;

  for (const section of node.sections || []) {
    if (!section || !shouldShowMenuTreeFolder(section, agent.id)) continue;
    const folderPath = resolveSectionFolderPath(section, parentSectionPath, depth + 1);
    collectLandingHubOrbitTopicsFromMenuNode(
      section,
      agent,
      depth + 1,
      maxDepth,
      folderPath,
      acc,
      seen
    );
  }
}

function collectLandingHubOrbitTopicsFromMenu(menu, agent) {
  const acc = [];
  const seen = new Set();
  if (!menu || menu.workspaceMissing) return acc;

  const walkTree = (node) => {
    if (!node) return;
    collectLandingHubOrbitTopicsFromMenuNode(
      node,
      agent,
      0,
      LANDING_HUB_ORBIT_TOPIC_MAX_DEPTH,
      ".",
      acc,
      seen
    );
  };

  walkTree(getWorkspaceRootMenuTreeNode(menu, agent.id));

  if (menu.containerTree && shouldShowContainerSectionInMenu(agent.id)) {
    walkTree({ title: menu.containerTree.title || "", ...menu.containerTree });
  }

  if (menu.sharedTree && shouldShowSharedSectionInMenu(agent.id)) {
    walkTree({ title: menu.sharedTree.title || "", ...menu.sharedTree });
  }

  return acc;
}

function getLandingHubOrbitTopicItems() {
  return [...globalLandingHubTopicItemsCache].sort((a, b) => {
    const agentCmp = String(a.agentName || a.agentId).localeCompare(String(b.agentName || b.agentId), "ru");
    if (agentCmp !== 0) return agentCmp;
    return String(a.name || a.nodePath).localeCompare(String(b.name || b.nodePath), "ru");
  });
}

async function loadGlobalLandingHubTopicItems() {
  const loadSeq = ++landingHubTopicItemsLoadSeq;
  const agents = getAgentsForLandingGrid().filter((agent) => agent.folderExists !== false);
  try {
    const response = await fetch(
      `/api/agents/menus?maxDepth=${encodeURIComponent(String(LANDING_HUB_ORBIT_MENU_MAX_DEPTH))}`
    );
    if (!response.ok) throw new Error(`menus:${response.status}`);
    const data = await response.json();
    if (loadSeq !== landingHubTopicItemsLoadSeq) return;
    const menus = data?.menus && typeof data.menus === "object" ? data.menus : {};
    globalLandingHubTopicItemsCache = agents.flatMap((agent) => {
      const menu = menus[agent.id];
      if (!menu) return [];
      menuCacheByAgent.set(agent.id, menu);
      return collectLandingHubOrbitTopicsFromMenu(menu, agent);
    });
  } catch {
    if (loadSeq !== landingHubTopicItemsLoadSeq) return;
    globalLandingHubTopicItemsCache = [];
  }
  if (loadSeq !== landingHubTopicItemsLoadSeq) return;
  if (getLandingAgentsView() === "hub") {
    renderAppLandingHub(getLandingHubOrbitTopicItems());
  } else if (getLandingAgentsView() === "orbit") {
    setLandingOrbitFocusCache(getLandingHubOrbitTopicItems());
  }
}

function groupFocusItemsByAgent(items = []) {
  const byAgent = new Map();
  for (const item of items) {
    const agentId = String(item?.agentId || "").trim();
    if (!agentId) continue;
    if (!byAgent.has(agentId)) byAgent.set(agentId, []);
    byAgent.get(agentId).push(item);
  }
  return byAgent;
}




async function renderAppLandingAgents() {
  paintAppLandingHomeImmediate();
  void ensureLandingChunkReady().then(() => {
    void renderAppLandingPlatformSection().catch((error) => {
      console.warn("[landing] platform section render failed", error);
    });
  }).catch((error) => {
    console.warn("[landing] chunk preload for platform failed", error);
  });
  try {
  const gridNode = appLandingAgentsNode || document.getElementById("app-landing-agents");
  if (!gridNode) {
    return;
  }
  gridNode.replaceChildren();

  const agents = getAgentsForLandingGrid();
  if (agents.length === 0) {
    gridNode.classList.remove("is-grouped-layout");
    const empty = document.createElement("p");
    empty.className = "app-landing-empty";
    empty.textContent = "Нет агентов. Нажмите «+ Добавить агента» или «Реестр контекста».";
    gridNode.appendChild(empty);
  } else {
    try {
      await loadLandingAgentsGroups();
    } catch {
      landingAgentsGroupsCache = [];
    }

    const agents = getAgentsForLandingGrid();
    const { orchestrator, rest } = splitLandingOrchestratorAgent(agents);

    if (orchestrator) {
      gridNode.appendChild(renderAppLandingOrchestratorSection(orchestrator));
    }

    const hasGroups = landingAgentsGroupsCache.length > 0;

    if (hasGroups) {
      gridNode.classList.add("is-grouped-layout");
      const { grouped, ungrouped } = buildLandingGroupsLayout(rest, landingAgentsGroupsCache);

      for (const group of grouped) {
        if (!group.agents?.length) continue;
        gridNode.appendChild(renderAppLandingGroupSection(group, { editable: false }));
      }

      if (ungrouped.length || landingAgentsUngroupedCache.backgroundUrl) {
        gridNode.appendChild(
          renderAppLandingGroupSection(
            {
              ...landingAgentsUngroupedCache,
              agents: ungrouped,
              agentIds: ungrouped.map((agent) => agent.id),
              readonly: true
            },
            { editable: false }
          )
        );
      }
    } else {
      gridNode.classList.remove("is-grouped-layout");
      for (const agent of rest) {
        const item = document.createElement("div");
        item.className = "app-landing-agent-item";
        item.setAttribute("role", "listitem");
        item.appendChild(createAppLandingAgentTile(agent));
        gridNode.appendChild(item);
      }
    }
  }
  } catch (error) {
    console.error("[landing] agents list render failed", error);
  } finally {
    void loadGlobalMainItems({ showLoading: true });
    void loadGlobalFlowItems();
    void loadGlobalLandingHubTopicItems();
    syncLandingAgentsViewUi();
    syncAppLandingActiveViewRender();
    renderAgentSelect();
  }
}

