async function saveAgentsRegistryDraft() {
  if (!agentsRegistrySaveBtn) return;
  syncAgentsRegistryOrchestratorFromForm();
  agentsRegistrySaveBtn.disabled = true;
  agentsRegistrySaveBtn.textContent = "Сохраняю...";

  try {
    const response = await fetch("/api/agents/registry", {
      method: "PUT",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        agents: agentsRegistryDraft.map(
          ({ path, environment, default: isDefault, orchestrator: isOrchestrator, active, name, comment }) => ({
            path,
            environment,
            default: isDefault,
            orchestrator: Boolean(isOrchestrator),
            active: active !== false,
            name: name ?? "",
            comment: comment ?? ""
          })
        )
      })
    });
    if (!response.ok) {
      const errorData = await response.json().catch(() => ({}));
      const details = errorData.details ? `: ${errorData.details}` : "";
      throw new Error(`${errorData.error || `Request failed with ${response.status}`}${details}`);
    }

    const data = await response.json();
    await loadAgents();
    const wasOnLanding = appRootNode?.classList.contains("app-landing-view");
    const previousAgentId = activeWorkspaceId;
    if (
      !wasOnLanding &&
      activeWorkspaceId &&
      (!agentsCache.some((agent) => agent.id === activeWorkspaceId) ||
        !getSelectableAgents().some((agent) => agent.id === activeWorkspaceId))
    ) {
      activeWorkspaceId = data.defaultAgentId || getSelectableAgents()[0]?.id || agentsCache[0]?.id || "main";
      localStorage.setItem(ACTIVE_AGENT_STORAGE_KEY, activeWorkspaceId);
      syncAgentToUrl(activeWorkspaceId);
    }
    renderAgentSelect();
    syncAgentPreview();
    closeAgentsRegistryModal();

    if (wasOnLanding) {
      renderAppLandingAgents();
      renderLandingSearchAgents();
    } else if (previousAgentId !== activeWorkspaceId) {
      activePath = null;
      activeLabel = null;
      clearActiveSystemFile();
      clearMediaSidecarEditor();
      showAgentHomeView();
      await loadSystemFiles();
    }
    if (!wasOnLanding && activeWorkspaceId) {
      await refreshMenu();
    }
    showToast("Список агентов сохранён", "success");
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    showToast(message ? `Ошибка сохранения агентов: ${message}` : "Ошибка сохранения агентов", "error");
  } finally {
    agentsRegistrySaveBtn.disabled = false;
    agentsRegistrySaveBtn.textContent = "Сохранить";
  }
}

