const BLOCKED_EXECUTABLE_EXTENSIONS_LABEL = ".exe, .dll, .so, .dylib, .bin, .com, .msi, .scr";

const AWN_QUALITY_FIELD_KEY = "awn-quality";
const AWN_QUALITY_DEFAULT = 4;
const AWN_QUALITY_REVIEW_THRESHOLD = 4;

const AWN_IMPORTANCE_FIELD_KEY = "awn-importance";
const AWN_IMPORTANCE_DEFAULT = 0;
const AWN_IMPORTANCE_HIGH_THRESHOLD = 8;

const AWN_TODO_FIELD_KEY = "awn-todo";
const AWN_NOTE_TODO_STICKER_LEGACY_FIELD_KEY = "awn-note-todo-sticker";
const AWN_TODO_STICKER_LABEL = "Todo";
const DOC_ASIDE_TODO_STICKER_OPEN_KEY = "agentcms.docAside.todoStickerOpen.v1";

function parseAwnQualityValue(raw, fallback = AWN_QUALITY_DEFAULT) {
  const text = String(raw ?? "").trim();
  if (!text) return fallback;
  const parsed = Number(text);
  if (!Number.isFinite(parsed)) return fallback;
  return Math.max(0, Math.min(10, Math.round(parsed)));
}

function getAwnQualityFromPropEntries(entries) {
  const raw = getPropsEntryValueByKey(entries, AWN_QUALITY_FIELD_KEY);
  if (raw === "" || raw == null) return AWN_QUALITY_DEFAULT;
  return parseAwnQualityValue(raw);
}

function getAwnQualityTooltip(value) {
  const normalized = parseAwnQualityValue(value);
  if (normalized <= 0) {
    return "0 — очень низкое качество, нужна существенная доработка с агентом";
  }
  if (normalized < AWN_QUALITY_REVIEW_THRESHOLD) {
    return `${normalized} — ниже нормы (< ${AWN_QUALITY_REVIEW_THRESHOLD}), требует обработки`;
  }
  if (normalized === AWN_QUALITY_REVIEW_THRESHOLD) {
    return `${normalized} — норма, базовый уровень проверки`;
  }
  if (normalized <= 7) {
    return `${normalized} — хорошее качество, критичных доработок не требуется`;
  }
  return `${normalized} — высокое качество, запись проверена хорошо`;
}

function awnQualityNeedsReview(value) {
  return parseAwnQualityValue(value) < AWN_QUALITY_REVIEW_THRESHOLD;
}

function parseAwnImportanceValue(raw, fallback = AWN_IMPORTANCE_DEFAULT) {
  const text = String(raw ?? "").trim();
  if (!text) return fallback;
  const parsed = Number(text);
  if (!Number.isFinite(parsed)) return fallback;
  return Math.max(0, Math.min(10, Math.round(parsed)));
}

function getAwnImportanceTooltip(value) {
  const normalized = parseAwnImportanceValue(value);
  if (normalized <= 0) {
    return "0 — не отмечено, обычный приоритет в поиске";
  }
  if (normalized <= 3) {
    return `${normalized} — немного важнее обычного`;
  }
  if (normalized <= 6) {
    return `${normalized} — заметно важно, агент будет поднимать выше`;
  }
  if (normalized < AWN_IMPORTANCE_HIGH_THRESHOLD) {
    return `${normalized} — очень важно для вас`;
  }
  return `${normalized} — критично важно, максимальный приоритет в поиске`;
}

function awnImportanceIsHigh(value) {
  return parseAwnImportanceValue(value) >= AWN_IMPORTANCE_HIGH_THRESHOLD;
}

function getAwnNoteTodoStickerValue(entries = propsFormEntries) {
  const todo = String(getPropsEntryValueByKey(entries, AWN_TODO_FIELD_KEY) || "").trim();
  if (todo) return todo;
  return String(
    getPropsEntryValueByKey(entries, AWN_NOTE_TODO_STICKER_LEGACY_FIELD_KEY) || ""
  ).trim();
}

