function resetMenuSettingsPopoverPosition() {
  if (!menuSettingsPopoverNode) return;
  for (const prop of ["top", "left", "width", "maxHeight", "overflowY"]) {
    menuSettingsPopoverNode.style.removeProperty(prop);
  }
}

function positionMenuSettingsPopover() {
  const popover = menuSettingsPopoverNode;
  const anchor = menuSettingsBtn?.closest("#menu-settings-wrap") || menuSettingsBtn;
  if (!popover || !anchor || popover.classList.contains("hidden")) return;

  const rect = anchor.getBoundingClientRect();
  const width = Math.min(280, Math.max(Math.round(rect.width), 200));
  const left = Math.round(rect.left + rect.width - width);
  const top = Math.round(rect.bottom + 6);
  const maxHeight = Math.max(120, window.innerHeight - top - 12);

  popover.style.top = `${top}px`;
  popover.style.left = `${left}px`;
  popover.style.width = `${width}px`;
  popover.style.maxHeight = `${maxHeight}px`;
  popover.style.overflowY = "auto";
}

function closeMenuSettingsPopover() {
  menuSettingsPopoverNode?.classList.add("hidden");
  menuSettingsBtn?.setAttribute("aria-expanded", "false");
  resetMenuSettingsPopoverPosition();
}

function toggleMenuSettingsPopover() {
  if (!menuSettingsPopoverNode || !menuSettingsBtn) return;
  const willOpen = menuSettingsPopoverNode.classList.contains("hidden");
  if (willOpen) {
    applyMenuTreeSettingsUi();
    syncMenuPinBranchUi();
    menuSettingsPopoverNode.classList.remove("hidden");
    menuSettingsBtn.setAttribute("aria-expanded", "true");
    positionMenuSettingsPopover();
  } else {
    closeMenuSettingsPopover();
  }
}

function formatMenuTreeSortLabel(sortKey, parentNode, displayLabel = sortKey, agentId = activeWorkspaceId) {
  const label = displayLabel ?? sortKey ?? "";
  const key = String(sortKey || "").trim();
  const settings = getMenuTreeSettings(agentId);
  if (!settings.padSortIndexes || !key) return label;
  const order = Array.isArray(parentNode?.menuOrder) ? parentNode.menuOrder : null;
  if (!order?.length) return label;
  const sortIndex = order.indexOf(key);
  if (sortIndex < 0) return label;
  const width = Math.max(2, String(order.length).length);
  return `${String(sortIndex + 1).padStart(width, "0")} ${label}`;
}

function formatMenuTreeItemLabel(item, parentNode, agentId = activeWorkspaceId) {
  return formatMenuTreeSortLabel(item?.label, parentNode, item?.label, agentId);
}

function getAwnStatusTone(status) {
  const raw = String(status || "").trim().toLowerCase();
  if (raw === "closed" || raw.includes("🔴") || raw.includes("закрыт")) return "closed";
  if (raw === "draft" || raw.includes("🟡") || raw.includes("черновик")) return "draft";
  if (raw === "open" || raw.includes("🟢") || raw.includes("открыт")) return "open";
  if (raw === "none" || raw.includes("⚪") || raw.includes("без статуса")) return "none";
  return "default";
}

function extractAwnStatusEmoji(status) {
  const label = String(status || "").trim();
  if (!label) return "";
  const match = label.match(/^\p{Extended_Pictographic}/u);
  return match ? match[0] : "";
}

function resolveAwnStatusLabel(rawStatus) {
  const raw = String(rawStatus || "").trim();
  if (!raw) return "";
  const options = getMenuAwnStatusOptions();
  const api = awnEnumOptionsApi();
  if (typeof api.resolveEnumDisplayName === "function") {
    return api.resolveEnumDisplayName(raw, options);
  }
  return raw;
}

function resolveAwnStatusPresentation(rawStatus) {
  const raw = String(rawStatus || "").trim();
  if (!raw) {
    return { label: "Без статуса", emoji: "⚪", tone: "none" };
  }
  const label = resolveAwnStatusLabel(raw);
  let emoji = extractAwnStatusEmoji(label);
  if (!emoji) emoji = extractAwnStatusEmoji(raw);
  const tone = getAwnStatusTone(label || raw);
  if (!emoji) {
    const fallbackEmoji = { open: "🟢", draft: "🟡", closed: "🔴", none: "⚪" };
    emoji = fallbackEmoji[tone] || "";
  }
  if (!emoji) return null;
  return { label: label || raw, emoji, tone };
}

function createMenuTreeStatusBadge(status) {
  const presentation = resolveAwnStatusPresentation(status);
  if (!presentation) return null;
  const badge = document.createElement("span");
  badge.className = `menu-tree-status menu-tree-status--${presentation.tone}`;
  badge.textContent = presentation.emoji;
  badge.title = `Статус: ${presentation.label}`;
  badge.setAttribute("aria-label", `Статус: ${presentation.label}`);
  return badge;
}

function populateMenuContextStatusButton(btn, optionKey, optionName) {
  if (!btn) return;
  btn.replaceChildren();
  const badge = createMenuTreeStatusBadge(optionKey);
  const labelText = String(optionName || "")
    .replace(/^\p{Extended_Pictographic}\s*/u, "")
    .trim();
  if (badge) {
    badge.setAttribute("aria-hidden", "true");
    btn.appendChild(badge);
  }
  const label = document.createElement("span");
  label.className = "menu-context-menu-status-text";
  label.textContent = labelText || String(optionName || "").trim();
  btn.appendChild(label);
}

function positionContextMenuSubmenu(submenuItem) {
  const submenu = submenuItem?.querySelector(".menu-context-menu-submenu");
  if (!submenu) return;
  submenu.classList.remove("is-flip-left");
  submenu.style.top = "";
  const rect = submenu.getBoundingClientRect();
  if (rect.right > window.innerWidth - 8) {
    submenu.classList.add("is-flip-left");
  }
  const nextRect = submenu.getBoundingClientRect();
  if (nextRect.bottom > window.innerHeight - 8) {
    const overflow = nextRect.bottom - window.innerHeight + 8;
    submenu.style.top = `${-overflow}px`;
  } else if (nextRect.top < 8) {
    submenu.style.top = `${8 - nextRect.top}px`;
  }
}

function createContextMenuStatusSubmenuListItem(currentStatus = "") {
  const options = getMenuAwnStatusOptions();
  const activeStatus = normalizeEnumDisplayValue(currentStatus, options);

  let activeOptionName = "";
  for (const option of options) {
    const optionKey = resolveAwnEnumOptionKey(option);
    if (optionKey === activeStatus) {
      activeOptionName = resolveAwnEnumOptionName(option);
      break;
    }
  }

  const item = document.createElement("li");
  item.className = "menu-context-menu-item menu-context-menu-item--submenu";
  item.setAttribute("role", "none");

  const trigger = document.createElement("button");
  trigger.type = "button";
  trigger.className = "menu-context-menu-btn menu-context-menu-submenu-trigger";
  trigger.setAttribute("aria-haspopup", "menu");
  trigger.setAttribute("aria-expanded", "false");
  trigger.setAttribute("role", "menuitem");

  const labelSpan = document.createElement("span");
  labelSpan.className = "menu-context-menu-submenu-trigger-label";
  labelSpan.textContent = "Статус";

  const valueSpan = document.createElement("span");
  valueSpan.className = "menu-context-menu-submenu-trigger-value";
  if (activeStatus) {
    const preview = document.createElement("span");
    preview.className = "menu-context-menu-submenu-trigger-preview";
    populateMenuContextStatusButton(preview, activeStatus, activeOptionName);
    valueSpan.appendChild(preview);
  }

  const chevron = document.createElement("span");
  chevron.className = "menu-context-menu-submenu-chevron";
  chevron.setAttribute("aria-hidden", "true");
  chevron.textContent = "›";

  trigger.append(labelSpan, valueSpan, chevron);

  const submenu = document.createElement("ul");
  submenu.className = "menu-context-menu-submenu menu-context-menu-status-list";
  submenu.setAttribute("role", "menu");
  submenu.setAttribute("aria-label", "Статус");

  for (const option of options) {
    const optionKey = resolveAwnEnumOptionKey(option);
    const optionName = resolveAwnEnumOptionName(option);
    const statusItem = document.createElement("li");
    statusItem.setAttribute("role", "none");

    const btn = document.createElement("button");
    btn.type = "button";
    btn.className = "menu-context-menu-status-btn";
    btn.dataset.status = optionKey;
    populateMenuContextStatusButton(btn, optionKey, optionName);
    btn.setAttribute("role", "menuitemradio");
    const isActive = optionKey === activeStatus;
    btn.classList.toggle("is-active", isActive);
    btn.setAttribute("aria-checked", isActive ? "true" : "false");
    statusItem.appendChild(btn);
    submenu.appendChild(statusItem);
  }

  item.append(trigger, submenu);
  item.addEventListener("mouseenter", () => {
    trigger.setAttribute("aria-expanded", "true");
    positionContextMenuSubmenu(item);
  });
  item.addEventListener("mouseleave", () => {
    trigger.setAttribute("aria-expanded", "false");
    submenu.classList.remove("is-flip-left");
    submenu.style.top = "";
  });

  return item;
}

const CONTEXT_MENU_PIN_TOOL_OPTIONS = [
  { key: "toggle-main", pin: "main" },
  { key: "toggle-focus", pin: "focus" }
];

const CONTEXT_MENU_IDEA_TOOL_OPTIONS = [
  { key: "tool-1", name: "Инструмент 1 (idea)" },
  { key: "tool-2", name: "Инструмент 2 (idea)" }
];

function resolveContextMenuNavPinLabel(pin, nodePath) {
  if (pin === "main") {
    return isNodeOnMain(nodePath) ? "Убрать с главной" : "Добавить на главную";
  }
  if (pin === "focus") {
    return isNodeInFocus(nodePath) ? "Убрать из фокуса" : "Добавить в фокус";
  }
  return "";
}

function resolveContextMenuPinNodePath(state) {
  if (!state) return "";
  const menuPath = normalizeMenuNodePath(state.path || "");
  if (menuPath && getMenuContextMenuKind(menuPath)) return menuPath;

  if (state.kind === "awnDataRecord" && state.record) {
    return normalizeMenuNodePath(resolveAwnDataRecordFilePath(state.record, state.viewStore) || "");
  }

  const filePath = String(state.filePath || "").replace(/\\/g, "/").replace(/^\/+/, "");
  if (!filePath) return "";

  const nodePath = state.nodePath || activePath;
  if (state.kind === "flatStorageFile") {
    const memoryKind = state.mode || state.railSlotMemoryKind || resolveResourceContextMemoryKind(state);
    return normalizeMenuNodePath(getFlatStorageItemContextPath(filePath, memoryKind, nodePath));
  }
  if (state.kind === "mediaFile") {
    const memoryKind = state.railSlotMemoryKind || "media";
    return normalizeMenuNodePath(getEntryOverviewItemContextPath(filePath, memoryKind, nodePath));
  }
  if (state.kind === "externalFile") {
    return normalizeMenuNodePath(getExternalItemContextPath({ path: filePath }, nodePath));
  }
  return normalizeMenuNodePath(filePath);
}

