function getMenuAwnStatusOptions() {
  const fieldDef = awnTypesCache?.types?.["awn.base"]?.fields?.["awn-status"];
  const fromSchema = getEnumOptionsForField(fieldDef);
  return fromSchema.length ? fromSchema : MENU_AWN_STATUS_OPTIONS;
}

function enumOptionsIncludeKey(options, key) {
  const normalized = String(key || "").trim();
  if (!normalized) return false;
  return options.some((option) => resolveAwnEnumOptionKey(option) === normalized);
}

function canShowMenuContextStatusPicker(nodePath) {
  const path = normalizeMenuNodePath(getResolvedNodePath(nodePath));
  return Boolean(path && isNodeMdPath(path) && !isPartNodePath(path));
}

function resolveMenuNodeStatus(nodePath, agentId = activeWorkspaceId) {
  const normalized = normalizeMenuNodePath(getResolvedNodePath(nodePath));
  if (!normalized) return "";
  const menu = menuCacheByAgent.get(agentId) || (agentId === activeWorkspaceId ? currentMenuData : null);
  if (!menu) return "";
  const entry = collectAgentMenuFlatEntries(menu, agentId, { includeHiddenSections: true }).find(
    (item) => normalizeMenuNodePath(item.path) === normalized
  );
  return String(entry?.status || "").trim();
}

function upsertAwnStatusInPropsYaml(content, nextStatus) {
  const entries = parsePropsYaml(content || "");
  const normalizedKey = "awn-status";
  const index = entries.findIndex((entry) => normalizePropsKey(entry.key) === normalizedKey);
  const nextEntry = { key: normalizedKey, kind: "string", value: nextStatus };
  if (index >= 0) entries[index] = { ...entries[index], ...nextEntry };
  else entries.push(nextEntry);
  return stringifyPropsYaml(entries);
}

function upsertAwnStatusInMarkdownContent(content, nextStatus) {
  const { frontmatter, body } = splitFrontmatter(content || "");
  const nextFrontmatter = upsertAwnStatusInPropsYaml(frontmatter, nextStatus);
  return joinFrontmatter(nextFrontmatter, body);
}

function readAwnStatusFromMarkdownContent(content) {
  const { frontmatter } = splitFrontmatter(content || "");
  return String(getPropsEntryValueByKey(parsePropsYaml(frontmatter), "awn-status") || "").trim();
}

function upsertAwnNameInPropsYaml(content, nextAwnName) {
  const entries = parsePropsYaml(content || "");
  const normalizedKey = "awn-name";
  const index = entries.findIndex((entry) => normalizePropsKey(entry.key) === normalizedKey);
  const nextEntry = { key: normalizedKey, kind: "string", value: nextAwnName };
  if (index >= 0) entries[index] = { ...entries[index], ...nextEntry };
  else entries.unshift(nextEntry);
  return stringifyPropsYaml(entries);
}

function upsertAwnFlagInPropsYaml(content, flagKey, enabled) {
  const normalizedKey = String(flagKey || "").trim();
  let entries = parsePropsYaml(content || "");
  if (normalizePropsKey(normalizedKey) === AWN_TOPIC_SLOTS_FLEXIBLE_KEY) {
    entries = entries.filter(
      (entry) => normalizePropsKey(entry.key) !== AWN_TOPIC_SLOTS_FLEXIBLE_LEGACY_KEY
    );
  }
  const index = entries.findIndex((entry) => normalizePropsKey(entry.key) === normalizedKey);
  const nextEntry = { key: normalizedKey, kind: "bool", value: Boolean(enabled) };
  if (index >= 0) entries[index] = { ...entries[index], ...nextEntry };
  else entries.push(nextEntry);
  return stringifyPropsYaml(entries);
}

function upsertAwnFocusInPropsYaml(content, enabled) {
  return upsertAwnFlagInPropsYaml(content, "awn-focus", enabled);
}

function upsertAwnMainInPropsYaml(content, enabled) {
  return upsertAwnFlagInPropsYaml(content, "awn-main", enabled);
}

async function saveNodeNavFlagState(nodePath, flagKey, enabled, options = {}) {
  const {
    agentId = activeWorkspaceId,
    confirmRemove = true,
    removeTitle,
    removeMessage,
    unavailableMessage,
    successOn,
    successOff,
    errorMessage
  } = options;
  const nodePathRaw = String(nodePath || "").trim();
  const label = getLabelFromPath(nodePathRaw) || nodePathRaw;
  const agentIdResolved = agentId || activeWorkspaceId;

  if (!enabled && confirmRemove) {
    const confirmed = await askConfirm(removeMessage || `Убрать «${label}»?`, {
      okLabel: removeTitle || "Убрать"
    });
    if (!confirmed) return false;
  }

  const apiPath = getResolvedNodePath(nodePathRaw);
  const canToggle =
    normalizePropsKey(flagKey) === AWN_TOPIC_SLOTS_FLEXIBLE_KEY
      ? canShowNodeOverviewSharedSlotToggle(nodePathRaw)
      : canShowNodeOverviewPinActions(nodePathRaw);
  if (!apiPath || !canToggle) {
    showToast(unavailableMessage || "Доступно только для markdown-записей", "error");
    return false;
  }

  try {
    const getResponse = await fetch(buildApiUrl("/api/file/properties", { path: apiPath }, agentIdResolved));
    if (!getResponse.ok) {
      const errorData = await getResponse.json().catch(() => ({}));
      throw new Error(errorData.error || `Request failed with ${getResponse.status}`);
    }
    const current = await getResponse.json();
    const stampedContent = upsertAwnFlagInPropsYaml(current.content || "", flagKey, enabled);

    const saveResponse = await fetch(buildApiUrl("/api/file/properties", {}, agentIdResolved), {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ path: apiPath, content: stampedContent })
    });
    if (!saveResponse.ok) {
      const errorData = await saveResponse.json().catch(() => ({}));
      const reason = errorData.error || `Request failed with ${saveResponse.status}`;
      const details = errorData.details ? `: ${errorData.details}` : "";
      throw new Error(`${reason}${details}`);
    }

    await refreshAllFocusPanels();
    const activeApi = normalizeMenuNodePath(getResolvedNodePath(activePath) || "");
    const savedApi = normalizeMenuNodePath(apiPath || "");
    if (activeApi && savedApi && activeApi === savedApi) {
      await loadPropertiesForActivePath().catch(() => null);
    }
    updateNodeOverviewHeroActionStates();
    showToast(enabled ? successOn || `«${label}» включено` : successOff || `«${label}» выключено`, "success");
    return true;
  } catch (error) {
    showToast(error?.message || errorMessage || "Не удалось сохранить", "error");
    return false;
  }
}

