async function fetchResourceFileStatus(state) {
  if (!state?.filePath) return String(state?.status || "").trim();

  const cached = String(state.status || "").trim();
  if (cached) return cached;

  const filePath = String(state.filePath || "").replace(/\\/g, "/").replace(/^\/+/, "");
  if (!filePath) return "";

  try {
    if (state.kind === "externalFile") {
      const manifestPath = getActiveNodeApiPath();
      if (!manifestPath) return "";
      const response = await fetch(buildApiUrl("/api/external/file", { path: manifestPath, file: filePath }));
      if (!response.ok) return "";
      const data = await response.json();
      return readAwnStatusFromMarkdownContent(data.content || "");
    }
    if (state.kind === "flatStorageFile" && state.mode) {
      const manifestPath = resolveFlatStorageRecordManifestApiPath(state);
      const folder = getFlatStorageSectionFolderName(state.mode);
      if (!folder || !manifestPath) return "";
      const response = await fetch(
        buildApiUrl("/api/storage/markdown", { path: manifestPath, folder, file: filePath })
      );
      if (!response.ok) return "";
      const data = await response.json();
      return readAwnStatusFromMarkdownContent(data.content || "");
    }
    if (state.kind === "mediaFile") {
      const response = await fetch(buildApiUrl("/api/media/markdown", { path: manifestPath, file: filePath }));
      if (!response.ok) return "";
      const data = await response.json();
      return readAwnStatusFromMarkdownContent(data.content || "");
    }
  } catch {
    return "";
  }
  return "";
}

async function updateResourceFileStatusApi(state, nextStatus) {
  if (!state?.filePath) throw new Error("Не удалось определить файл");

  const filePath = String(state.filePath || "").replace(/\\/g, "/").replace(/^\/+/, "");
  if (!filePath) throw new Error("Не удалось определить файл");

  if (state.kind === "externalFile") {
    const manifestPath = getActiveNodeApiPath();
    if (!manifestPath) throw new Error("Не удалось определить файл");
    const getResponse = await fetch(buildApiUrl("/api/external/file", { path: manifestPath, file: filePath }));
    if (!getResponse.ok) {
      const errorData = await getResponse.json().catch(() => ({}));
      throw new Error(errorData.error || `Request failed with ${getResponse.status}`);
    }
    const current = await getResponse.json();
    const nextContent = upsertAwnStatusInMarkdownContent(current.content || "", nextStatus);
    const saveResponse = await fetch(buildApiUrl("/api/external/file"), {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ path: manifestPath, file: filePath, content: nextContent })
    });
    if (!saveResponse.ok) {
      const errorData = await saveResponse.json().catch(() => ({}));
      throw new Error(errorData.error || `Request failed with ${saveResponse.status}`);
    }
    return saveResponse.json();
  }

  if (state.kind === "flatStorageFile" && state.mode) {
    const manifestPath = resolveFlatStorageRecordManifestApiPath(state);
    const folder = getFlatStorageSectionFolderName(state.mode);
    if (!folder || !manifestPath) throw new Error("Не удалось определить слот");
    const getResponse = await fetch(
      buildApiUrl("/api/storage/markdown", { path: manifestPath, folder, file: filePath })
    );
    if (!getResponse.ok) {
      const errorData = await getResponse.json().catch(() => ({}));
      throw new Error(errorData.error || `Request failed with ${getResponse.status}`);
    }
    const current = await getResponse.json();
    const nextContent = upsertAwnStatusInMarkdownContent(current.content || "", nextStatus);
    const saveResponse = await fetch(buildApiUrl("/api/storage/markdown"), {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ path: manifestPath, folder, file: filePath, content: nextContent })
    });
    if (!saveResponse.ok) {
      const errorData = await saveResponse.json().catch(() => ({}));
      throw new Error(errorData.error || `Request failed with ${saveResponse.status}`);
    }
    return saveResponse.json();
  }

  if (state.kind === "mediaFile") {
    const manifestPath = getWorkspaceStorageManifestApiPath() || getActiveNodeApiPath();
    if (!manifestPath) throw new Error("Не удалось определить файл");
    const getResponse = await fetch(buildApiUrl("/api/media/markdown", { path: manifestPath, file: filePath }));
    if (!getResponse.ok) {
      const errorData = await getResponse.json().catch(() => ({}));
      throw new Error(errorData.error || `Request failed with ${getResponse.status}`);
    }
    const current = await getResponse.json();
    const nextContent = upsertAwnStatusInMarkdownContent(current.content || "", nextStatus);
    const saveResponse = await fetch(buildApiUrl("/api/media/markdown"), {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ path: manifestPath, file: filePath, content: nextContent })
    });
    if (!saveResponse.ok) {
      const errorData = await saveResponse.json().catch(() => ({}));
      throw new Error(errorData.error || `Request failed with ${saveResponse.status}`);
    }
    return saveResponse.json();
  }

  throw new Error("Статус для этого типа элементов пока не поддерживается");
}

async function refreshResourceFileViews(state = resourceContextMenuState) {
  invalidateStorageRootScanCache();
  if (state?.kind === "externalFile") {
    await refreshExternalMemoryCaches();
    rerenderExternalListViewBody();
    if (state.railSlotMemoryKind) {
      await refreshNavigationHubRailSlotTreeForMemoryKind(state.railSlotMemoryKind);
    }
    return;
  }
  if (state?.kind === "flatStorageFile" && state.mode) {
    await reloadFlatStorageFolderMode(state.mode);
    rerenderFlatStorageListViewBody(state.mode);
    if (state.railSlotMemoryKind) {
      await refreshNavigationHubRailSlotTreeForMemoryKind(state.railSlotMemoryKind);
    }
    return;
  }
  if (state?.kind === "mediaFile") {
    await refreshMediaCache();
    renderListViewContent();
    if (state.railSlotMemoryKind) {
      await refreshNavigationHubRailSlotTreeForMemoryKind(state.railSlotMemoryKind || "media");
    }
    return;
  }
  if (state?.kind === "awnDataRecord") {
    await refreshAwnDataRecordMenuViews(state);
  }
}

function refreshEntryOverviewSlotCounterStripsForTopic(topicPath = getResolvedNodePath(activePath)) {
  if (!nodeOverviewContentNode || !topicPath) return;
  const context = activeEntryOverviewContext;
  const escaped = typeof CSS !== "undefined" && CSS.escape ? CSS.escape(topicPath) : topicPath;
  nodeOverviewContentNode
    .querySelectorAll(`.node-entry-overview-slot-counters[data-topic-node-path="${escaped}"]`)
    .forEach((wrap) => refreshEntryOverviewSlotCounterStripCounts(wrap, context, topicPath));
}

async function refreshMemorySectionViews(state = resourceContextMenuState) {
  invalidateStorageRootScanCache();
  const topicPath = getResolvedNodePath(activePath);
  const manifestPath = resolveFlatStorageRecordManifestApiPath(state);
  if (manifestPath) invalidateEntryOverviewSlotCountersCache(manifestPath);
  refreshEntryOverviewSlotCounterStripsForTopic(topicPath);
  const flatMode =
    state?.storageMode ||
    state?.mode ||
    (state?.kind === "flatStorageFile" ? resolveResourceStateMemoryKind(state) : null);
  if (flatMode && (FLAT_STORAGE_SECTION_MODES.has(flatMode) || isFlatEntryOverviewMemoryKind(flatMode))) {
    if (activeContentMode === NODE_ENTRY_OVERVIEW_MODE && nodeOverviewContentNode) {
      await refreshNavigationHubAfterSlotMutation();
      return;
    }
    await reloadFlatStorageFolderMode(flatMode);
    rerenderFlatStorageListViewBody(flatMode);
    await refreshNavigationHubRailSlotTreeForMemoryKind(state?.railSlotMemoryKind || flatMode);
    return;
  }
  if (state?.externalMode) {
    await refreshExternalMemoryCaches();
    rerenderExternalListViewBody();
    await refreshNavigationHubRailSlotTreeForMemoryKind(state.railSlotMemoryKind || "external");
    return;
  }
  if (state?.mediaMode) {
    await refreshMediaCache();
    renderListViewContent();
    await refreshNavigationHubRailSlotTreeForMemoryKind(state.railSlotMemoryKind || "media");
  }
}

async function refreshNavigationHubRailSlotTreeForMemoryKind(memoryKind) {
  if (!memoryKind || activeContentMode !== NODE_ENTRY_OVERVIEW_MODE || !nodeOverviewContentNode) return;

  const hub = nodeOverviewContentNode.querySelector(".node-navigation-hub--split");
  if (!hub) return;

  const details = hub.querySelector(
    `.node-navigation-hub-rail-slot[data-rail-slot-memory-kind="${memoryKind}"]`
  );
  if (!details?.open) return;

  const body = details.querySelector(".node-navigation-hub-rail-slot-body");
  if (!body) return;

  const nodePath = getResolvedNodePath(activePath);
  const slotKey = details.dataset.railSlotId || "";
  if (!slotKey) return;

  const prefetched = {};
  if (memoryKind === "external") {
    prefetched.externalData = await fetchExternalFilesForNavigation(nodePath).catch(() => ({
      exists: false,
      files: [],
      folders: [],
      nonMarkdownFiles: []
    }));
  } else if (memoryKind === "media") {
    prefetched.mediaData = await fetchMediaOverview(nodePath).catch(() => null);
  } else if (memoryKind === "assets") {
    prefetched.assetsData = await fetchMediaLibraryOverview(nodePath, "assets").catch(() => null);
    if (!prefetched.assetsPreview) {
      prefetched.assetsPreview = await fetchNodeOverviewPreview(nodePath).catch(() => null);
    }
  } else if (isFlatEntryOverviewMemoryKind(memoryKind)) {
    prefetched.flatNavigationIndexes = {
      ...(prefetched.flatNavigationIndexes || {}),
      [memoryKind]: await fetchFlatStorageNavigationIndex(nodePath, slotKey).catch(() => null)
    };
  }

  const slotIndex = prepareNavigationHubRailSlotIndex(slotKey, nodePath, prefetched);
  const slot = {
    id: slotKey,
    filled: true,
    label: resolveDataStorageSlotDisplayLabel(slotKey),
    assetsPreview: prefetched.assetsPreview || null
  };
  refreshNavigationHubRailSlotTreeBody(
    body,
    slot,
    slotIndex,
    nodePath,
    buildNavigationHubRailActiveContext(),
    prefetched
  );
}

function closeResourceContextMenu() {
  resourceContextMenuNode?.classList.add("hidden");
  resourceContextMenuState = null;
}

function positionResourceContextMenu(clientX, clientY) {
  if (!resourceContextMenuNode) return;
  resourceContextMenuNode.classList.remove("hidden");
  const rect = resourceContextMenuNode.getBoundingClientRect();
  const maxLeft = Math.max(8, window.innerWidth - rect.width - 8);
  const maxTop = Math.max(8, window.innerHeight - rect.height - 8);
  resourceContextMenuNode.style.left = `${Math.min(clientX, maxLeft)}px`;
  resourceContextMenuNode.style.top = `${Math.min(clientY, maxTop)}px`;
}

function canShowResourceContextStatusPicker(state = resourceContextMenuState) {
  if (!state) return false;
  return (
    state.kind === "memorySection" ||
    state.kind === "externalFile" ||
    state.kind === "flatStorageFile" ||
    state.kind === "mediaFile" ||
    state.kind === "awnDataRecord"
  );
}

function appendResourceContextMenuPickerSections(currentStatus = "", currentTool = "") {
  if (!resourceContextMenuListNode) return false;
  let hadAny = false;
  if (canShowResourceContextStatusPicker() && resourceContextMenuState) {
    resourceContextMenuListNode.appendChild(createContextMenuStatusSubmenuListItem(currentStatus));
    hadAny = true;
  }
  const pinNodePath = resolveContextMenuPinNodePath(resourceContextMenuState);
  if (appendContextMenuToolsSection(resourceContextMenuListNode, pinNodePath, currentTool)) {
    hadAny = true;
  }
  return hadAny;
}

function renderResourceContextMenuItems(kind, currentStatus = "", currentTool = "") {
  if (!resourceContextMenuListNode) return;
  resourceContextMenuListNode.replaceChildren();
  const hadPickers = appendResourceContextMenuPickerSections(currentStatus, currentTool);
  const actions = RESOURCE_CONTEXT_MENU_ACTIONS[kind] || [];
  if (hadPickers && actions.length) {
    appendContextMenuListSeparator(resourceContextMenuListNode);
  }
  for (const action of actions) {
    const item = document.createElement("li");
    item.className = "menu-context-menu-item";
    item.setAttribute("role", "none");

    const btn = document.createElement("button");
    btn.type = "button";
    btn.className = "menu-context-menu-btn";
    btn.dataset.action = action.id;
    btn.textContent = action.label;
    btn.setAttribute("role", "menuitem");
    item.appendChild(btn);
    resourceContextMenuListNode.appendChild(item);
  }
  appendResourceClipboardMenuItems(kind);
}

function openResourceContextMenu(event, state) {
  if (!resourceContextMenuNode || !resourceContextMenuListNode || !state?.kind) return;
  event.preventDefault();
  event.stopPropagation();
  closeMenuContextMenu();

  void (async () => {
    let currentStatus = state.status || "";
    if (state.kind === "memorySection" && state.sectionFolder) {
      currentStatus = await fetchMemorySectionStatus(state.sectionFolder, state);
    } else if (
      state.filePath &&
      (state.kind === "externalFile" || state.kind === "flatStorageFile" || state.kind === "mediaFile")
    ) {
      currentStatus = await fetchResourceFileStatus(state);
    } else if (state.kind === "awnDataRecord") {
      currentStatus = await fetchAwnDataRecordMenuStatus(state);
    }

    const currentTool = String(state.tool || "").trim();
    resourceContextMenuState = { ...state, status: currentStatus, tool: currentTool };
    renderResourceContextMenuItems(state.kind, currentStatus, currentTool);
    positionResourceContextMenu(event.clientX, event.clientY);
  })();
}

async function handleResourceContextMenuToolAction(nextTool) {
  const state = resourceContextMenuState;
  if (!state) return;
  const toolKey = String(nextTool || "").trim();
  if (toolKey === "toggle-main" || toolKey === "toggle-focus") {
    const nodePath = resolveContextMenuPinNodePath(state);
    if (!nodePath || !canShowNodeOverviewPinActions(nodePath)) {
      showToast("Доступно только для markdown-записей", "error");
      return;
    }
    closeResourceContextMenu();
    if (toolKey === "toggle-main") {
      await toggleNodeMain(nodePath);
    } else {
      await toggleNodeFocus(nodePath);
    }
    return;
  }
  const option = CONTEXT_MENU_IDEA_TOOL_OPTIONS.find((item) => item.key === toolKey);
  if (!option) return;
  const currentTool = String(state.tool || "").trim();
  closeResourceContextMenu();
  if (toolKey === currentTool) return;
  showToast(`Инструмент: ${option.name}`, "info");
}

async function handleResourceContextMenuStatusAction(nextStatus) {
  const state = resourceContextMenuState;
  if (!state) return;
  const options = getMenuAwnStatusOptions();
  const normalizedStatus = normalizeEnumDisplayValue(nextStatus, options);
  if (!normalizedStatus || !enumOptionsIncludeKey(options, normalizedStatus)) return;

  const currentStatus = normalizeEnumDisplayValue(state.status || "", options);
  closeResourceContextMenu();
  if (normalizedStatus === currentStatus) return;

  try {
    if (state.kind === "memorySection" && state.sectionFolder) {
      await updateMemorySectionStatusApi(state.sectionFolder, normalizedStatus, state);
      await refreshMemorySectionViews(state);
    } else if (
      state.filePath &&
      (state.kind === "externalFile" || state.kind === "flatStorageFile" || state.kind === "mediaFile")
    ) {
      await updateResourceFileStatusApi(state, normalizedStatus);
      await refreshResourceFileViews(state);
    } else if (state.kind === "awnDataRecord") {
      await updateAwnDataRecordMenuStatusApi(state, normalizedStatus);
      await refreshAwnDataRecordMenuViews(state);
    } else {
      showToast("Статус для этого типа элементов пока не поддерживается", "error");
      return;
    }
    const api = awnEnumOptionsApi();
    const label =
      typeof api.resolveEnumDisplayName === "function"
        ? api.resolveEnumDisplayName(normalizedStatus, options)
        : normalizedStatus;
    showToast(`Статус: ${label}`, "success");
  } catch (error) {
    showToast(`Ошибка статуса: ${error.message}`, "error");
  }
}

