function returnToNodeNavigation() {
  if (!activePath) return;
  setContentMode(NODE_NAVIGATION_MODE);
}

function isEditorDirty() {
  return (
    isEditorSaveTrackingActive() &&
    savedEditorSnapshot !== null &&
    getEditorSavePayload() !== savedEditorSnapshot
  );
}

function confirmDiscardEditorChanges() {
  if (!isEditorDirty()) return true;
  return window.confirm("Есть несохранённые изменения. Закрыть без сохранения?");
}

function captureMemoryEntryCloseTargetView() {
  if (activeContentMode === NODE_ENTRY_OVERVIEW_MODE) {
    return MEMORY_ENTRY_VIEW_OVERVIEW;
  }
  if (isDataHubBundleSlotShellMode() && dataHubBundleEntryView === MEMORY_ENTRY_VIEW_OVERVIEW) {
    return MEMORY_ENTRY_VIEW_OVERVIEW;
  }
  if (activeContentMode === "external" && !activeExternalFilePath) {
    return MEMORY_ENTRY_VIEW_LIST;
  }
  if (isMediaLibraryContentMode() && !isMediaAssetEditing()) {
    return MEMORY_ENTRY_VIEW_LIST;
  }
  if (isFlatStorageSectionMode() && isFlatStorageListMode()) {
    return MEMORY_ENTRY_VIEW_LIST;
  }
  if (lastNonTocEntryOverviewContext) {
    return MEMORY_ENTRY_VIEW_OVERVIEW;
  }
  return MEMORY_ENTRY_VIEW_LIST;
}

function isFlatStorageListShellMode(mode = activeContentMode) {
  return isFlatStorageSectionMode(mode) && isFlatStorageListMode(mode) && !isFlatStorageFileEditing();
}

function resolveFlatStorageMemoryKind(mode = activeContentMode) {
  return mode === "quick-notes" ? "note" : mode;
}

function assignMemoryEntryCloseTargetView(value) {
  memoryEntryCloseTargetView = value === MEMORY_ENTRY_VIEW_LIST ? MEMORY_ENTRY_VIEW_LIST : MEMORY_ENTRY_VIEW_OVERVIEW;
}

function buildEntryOverviewContextFromExternalPath(filePath) {
  const rel = String(filePath || "").replace(/\\/g, "/").replace(/^\/+/, "");
  const relPath = getExternalItemContextPath({ path: rel });
  return {
    relPath,
    memoryKind: "external",
    relativePath: rel,
    title: rel.split("/").pop() || rel,
    entryKind: inferAwnTypeFromRelPath(relPath, { contentMode: "external" }),
    status: ""
  };
}

function buildEntryOverviewContextFromMediaPath(filePath) {
  const rel = String(filePath || "").replace(/\\/g, "/").replace(/^\/+/, "");
  const relPath = getMediaItemContextPath(rel);
  return {
    relPath,
    memoryKind: "media",
    relativePath: rel,
    title: rel.split("/").pop() || rel,
    entryKind: resolveEntryOverviewEntryKindForStoragePath(relPath, rel, "media"),
    status: ""
  };
}

function buildEntryOverviewContextFromFlatPath(filePath, memoryKind) {
  const rel = String(filePath || "").replace(/\\/g, "/").replace(/^\/+/, "");
  const relPath = getFlatStorageItemContextPath(rel, memoryKind);
  return {
    relPath,
    memoryKind,
    relativePath: rel,
    title: rel.split("/").pop() || rel,
    entryKind: resolveEntryOverviewEntryKindForStoragePath(relPath, rel, memoryKind),
    status: ""
  };
}

async function closeExternalFileEditorToTargetView() {
  const targetView = memoryEntryCloseTargetView || MEMORY_ENTRY_VIEW_LIST;
  const closingFile = activeExternalFilePath;
  memoryEntryCloseTargetView = null;
  activeExternalFilePath = null;
  setPropsYamlContent("");
  titleInputNode.value = "";
  syncPropsInputPlaceholder();
  editorViewMode = "preview";

  if (targetView === MEMORY_ENTRY_VIEW_OVERVIEW) {
    syncAppRouteToUrl({ replace: true });
    const context = resolveEntryOverviewContextAfterEditorClose({
      closingFile,
      memoryKind: "external",
      buildFromPath: buildEntryOverviewContextFromExternalPath
    });
    await openEntryOverviewFromNavigation(context);
    return;
  }

  await refreshExternalFileListView();
}

async function closeFlatStorageFileEditorToTargetView() {
  const targetView = memoryEntryCloseTargetView || MEMORY_ENTRY_VIEW_LIST;
  const closingFile = activeFlatStorageFilePath;
  const mode = activeContentMode;
  memoryEntryCloseTargetView = null;
  activeFlatStorageFilePath = null;
  setPropsYamlContent("");
  titleInputNode.value = "";
  syncPropsInputPlaceholder();
  editorViewMode = "preview";

  if (targetView === MEMORY_ENTRY_VIEW_OVERVIEW && closingFile) {
    syncAppRouteToUrl({ replace: true });
    const context = resolveEntryOverviewContextAfterEditorClose({
      closingFile,
      memoryKind: mode,
      buildFromPath: (filePath) => buildEntryOverviewContextFromFlatPath(filePath, mode)
    });
    await openEntryOverviewFromNavigation(context);
    return;
  }

  try {
    await reloadFlatStorageFolderMode(mode);
  } catch {
    // ignore refresh errors after closing editor
  }
  applyModeUi();
  renderListViewContent();
  updateBreadcrumbsForActiveMode();
  syncAppRouteToUrl({ replace: true });
}

async function closeMediaSidecarEditorToTargetView() {
  const targetView = memoryEntryCloseTargetView || MEMORY_ENTRY_VIEW_LIST;
  const sourceFile = activeMediaSidecarSourcePath || activeMediaMarkdownPath;
  memoryEntryCloseTargetView = null;
  clearMediaSidecarEditor();
  setPropsYamlContent("");
  fileContentInputNode.value = "";
  titleInputNode.value = "";
  syncPropsInputPlaceholder();

  if (targetView === MEMORY_ENTRY_VIEW_OVERVIEW && sourceFile) {
    syncAppRouteToUrl({ replace: true });
    const context = resolveEntryOverviewContextAfterEditorClose({
      closingFile: sourceFile,
      memoryKind: "media",
      buildFromPath: buildEntryOverviewContextFromMediaPath
    });
    await openEntryOverviewFromNavigation(context);
    return;
  }

  applyModeUi();
  renderListViewContent();
  updateBreadcrumbsForActiveMode();
  syncAppRouteToUrl({ replace: true });
}

function handleWorkspaceCloseClick() {
  if (!confirmDiscardEditorChanges()) return;

  if (isAwnDatabaseManifestEditing()) {
    void closeAwnDatabaseManifestEditor();
    return;
  }
  if (activeContentMode === AWN_DATA_VIEW_MODE && awnDataViewRecordId && resolveAwnDataViewBackStoreRel()) {
    void navigateAwnDataViewBackToStore();
    return;
  }
  if (isAttachmentSidecarEditing()) {
    void closeAttachmentSidecarEditorToTargetView();
    return;
  }
  if (isMediaAssetEditing()) {
    void closeMediaSidecarEditorToTargetView();
    return;
  }
  if (isExternalFileEditing()) {
    void closeExternalFileEditorToTargetView();
    return;
  }
  if (isFlatStorageFileEditing()) {
    void closeFlatStorageFileEditorToTargetView();
    return;
  }
  if (isFlatStorageListShellMode()) {
    if (getMemoryEntryViewSelectValue() === MEMORY_ENTRY_VIEW_OVERVIEW) {
      openEntryOverviewMemoryTocFromNavigation(resolveFlatStorageMemoryKind());
      return;
    }
    returnToNodeNavigation();
    return;
  }
  if (isDataHubBundleSlotShellMode()) {
    closeDataHubBundleEditor();
    return;
  }
  returnToNodeNavigation();
}

function syncWorkspaceCloseButtonsVisibility() {
  const settingsDomain = getNodeWorkspaceDomain() === NODE_WORKSPACE_DOMAIN_SETTINGS;
  const memorySlotActive = isDataStorageSlotActive("memory");
  const mediaSlotActive = isDataStorageSlotActive("media");
  const scriptsSlotActive = isDataStorageSlotActive("scripts");
  const todoDomain = getNodeWorkspaceDomain() === NODE_WORKSPACE_DOMAIN_TODO;
  const mediaSidecarEditing = isMediaAssetEditing();
  const attachmentSidecarEditing = isAttachmentSidecarEditing();
  const externalEditing = isExternalFileEditing();
  const flatStorageEditing = isFlatStorageFileEditing();
  const flatStorageListShell = isFlatStorageListShellMode();
  const bundleSlotShellMode = isDataHubBundleSlotShellMode();
  const showClose =
    isAwnDatabaseManifestEditing() ||
    (activeContentMode === AWN_DATA_VIEW_MODE && awnDataViewRecordId) ||
    mediaSidecarEditing ||
    attachmentSidecarEditing ||
    externalEditing ||
    flatStorageEditing ||
    flatStorageListShell ||
    (settingsDomain && NODE_SETTINGS_CLOSE_MODES.has(activeContentMode)) ||
    (memorySlotActive && NODE_MEMORY_CLOSE_MODES.has(activeContentMode)) ||
    (mediaSlotActive && isMediaLibraryContentMode()) ||
    (todoDomain && activeContentMode === "todo") ||
    bundleSlotShellMode;
  nodeWorkspaceCloseBtn?.classList.toggle("hidden", !showClose);

  const labelNode = nodeWorkspaceCloseBtn?.querySelector(".workspace-toolbar-btn-label");
  if (labelNode) {
    labelNode.textContent = "Закрыть";
  }
  if (nodeWorkspaceCloseBtn) {
    nodeWorkspaceCloseBtn.title = "Закрыть";
    nodeWorkspaceCloseBtn.setAttribute("aria-label", "Закрыть");
  }
}

