async function buildDqlFromBuilderUi() {
  const conditions = [];
  contentSearchDqlBuilderRows?.querySelectorAll(".content-search-dql-builder-row").forEach((row) => {
    const field = row.querySelector(".dql-b-field")?.value?.trim();
    const op = row.querySelector(".dql-b-op")?.value || "eq";
    const value = row.querySelector(".dql-b-value")?.value ?? "";
    if (!field) return;
    conditions.push({ field, op, value });
  });
  const response = await fetch(buildApiUrl("/api/storage-index/dql-build"), {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      from: contentSearchDqlBuilderFrom?.value?.trim() || "",
      sourceKind: contentSearchDqlBuilderSourceKind?.value?.trim() || "",
      conditions,
      withText: contentSearchDqlBuilderWithText?.value?.trim() || "",
      limit: Number(contentSearchDqlBuilderLimit?.value) || 50
    })
  });
  const data = await response.json();
  if (!response.ok) throw new Error(data.error || data.details || "build failed");
  if (contentSearchDqlInputNode) contentSearchDqlInputNode.value = data.dql || "";
  saveContentSearchDqlDraft(data.dql || "");
  setContentSearchDqlTab("text");
}

async function refreshContentSearchDqlViewsSelect() {
  if (!contentSearchDqlViewsSelect) return;
  const response = await fetch(buildApiUrl("/api/storage-index/dql-views"));
  const data = await response.json().catch(() => ({}));
  if (!response.ok) return;
  const views = Array.isArray(data.views) ? data.views : [];
  contentSearchDqlViewsSelect.replaceChildren();
  const empty = document.createElement("option");
  empty.value = "";
  empty.textContent = views.length ? "— выберите view —" : "нет сохранённых views";
  contentSearchDqlViewsSelect.appendChild(empty);
  for (const view of views) {
    const opt = document.createElement("option");
    opt.value = view.id;
    opt.textContent = view.name || view.id;
    opt.dataset.dql = view.dql || "";
    contentSearchDqlViewsSelect.appendChild(opt);
  }
}

async function saveContentSearchDqlView() {
  const dql = String(contentSearchDqlInputNode?.value || getContentSearchDqlText()).trim();
  if (!dql) return;
  const name = String(contentSearchDqlViewNameInput?.value || "").trim() || "DQL view";
  const response = await fetch(buildApiUrl("/api/storage-index/dql-views"), {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ name, dql })
  });
  const data = await response.json();
  if (!response.ok) throw new Error(data.error || data.details || "save failed");
  await refreshContentSearchDqlViewsSelect();
  if (contentSearchDqlViewNameInput) contentSearchDqlViewNameInput.value = data.view?.name || name;
}

function applyDqlViewParamsClient(dql, params = {}) {
  let out = String(dql || "");
  if (params.limit != null && params.limit !== "") {
    const limitNum = Math.min(500, Math.max(1, Math.floor(Number(params.limit) || 50)));
    out = out.replace(/\bLIMIT\s+\$limit\b/gi, `LIMIT ${limitNum}`);
  }
  for (const [key, rawValue] of Object.entries(params)) {
    if (rawValue == null || rawValue === "") continue;
    if (key === "limit") continue;
    const value = String(rawValue);
    const escaped = key.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
    out = out.replace(new RegExp(`\\$${escaped}\\b`, "g"), value);
    out = out.replace(new RegExp(`\\{\\{\\s*${escaped}\\s*\\}\\}`, "g"), value);
  }
  return out.trim();
}

function loadSelectedContentSearchDqlView() {
  const opt = contentSearchDqlViewsSelect?.selectedOptions?.[0];
  let dql = opt?.dataset?.dql || "";
  const fromParam = contentSearchDqlViewParamFrom?.value?.trim() || "";
  const limitParam = contentSearchDqlViewParamLimit?.value?.trim() || "";
  if (fromParam || limitParam) {
    dql = applyDqlViewParamsClient(dql, {
      ...(fromParam ? { from: fromParam } : {}),
      ...(limitParam ? { limit: limitParam } : {})
    });
  }
  if (!dql || !contentSearchDqlInputNode) return;
  contentSearchDqlInputNode.value = dql;
  saveContentSearchDqlDraft(dql);
  setContentSearchDqlTab("text");
}

async function deleteSelectedContentSearchDqlView() {
  const id = contentSearchDqlViewsSelect?.value;
  if (!id) return;
  const response = await fetch(buildApiUrl("/api/storage-index/dql-views"), {
    method: "DELETE",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ id })
  });
  if (!response.ok) {
    const data = await response.json().catch(() => ({}));
    throw new Error(data.error || data.details || "delete failed");
  }
  await refreshContentSearchDqlViewsSelect();
}

const CONTENT_SEARCH_DEFAULT_SCOPE = "all";
const CONTENT_SEARCH_DEFAULT_MATCH = "relaxed";
const CONTENT_SEARCH_DEFAULT_TYPE = "all";
const CONTENT_SEARCH_SCOPE_LABELS = {
  all: "Везде",
  filename: "Только имя",
  content: "Только текст",
  tags: "Теги"
};
const CONTENT_SEARCH_MATCH_LABELS = {
  relaxed: "Мягкий",
  strict: "Точный"
};
const CONTENT_SEARCH_TYPE_LABELS = {
  all: "Все типы",
  markdown: "Markdown",
  sidecar: "Markdown (sidecar)",
  pdf: "PDF",
  office: "Word / PowerPoint",
  spreadsheet: "Excel / CSV",
  video: "Видео",
  audio: "Аудио",
  image: "Изображения",
  archive: "Архивы",
  config: "YAML / JSON / TXT",
  other: "Прочее"
};
const CONTENT_SEARCH_FIELD_OP_LABELS = {
  eq: "равно",
  contains: "содержит",
  gte: "≥",
  lte: "≤"
};
let contentSearchFieldCatalogCache = null;
let contentSearchFieldCatalogLoading = null;
let contentSearchAdvancedFieldFilters = [];
let contentSearchAdvancedFilterDraft = [];
let contentSearchAdvancedFilterRowSeq = 0;
let contentSearchFieldValuesCache = new Map();
let contentSearchFieldValuesLoading = new Map();
let contentSearchPolicyCache = null;
let contentSearchPolicyLoadPromise = null;

function isContentSearchFiltersPopoverOpen() {
  return Boolean(
    contentSearchFiltersPopoverNode && !contentSearchFiltersPopoverNode.classList.contains("hidden")
  );
}

function syncContentSearchModeToggleUi() {
  const mode = getContentSearchMode();
  contentSearchModeTextBtn?.classList.toggle("is-active", mode === "text");
  contentSearchModeSemanticBtn?.classList.toggle("is-active", mode === "semantic");
  contentSearchModeIdBtn?.classList.toggle("is-active", mode === "id");
  contentSearchModeDqlBtn?.classList.toggle("is-active", mode === "dql");
  contentSearchModeTextBtn?.setAttribute("aria-pressed", mode === "text" ? "true" : "false");
  contentSearchModeSemanticBtn?.setAttribute("aria-pressed", mode === "semantic" ? "true" : "false");
  contentSearchModeIdBtn?.setAttribute("aria-pressed", mode === "id" ? "true" : "false");
  contentSearchModeDqlBtn?.setAttribute("aria-pressed", mode === "dql" ? "true" : "false");
}

function isContentSearchSemanticLayerEnabled() {
  if (!contentSearchPolicyCache?.search?.layers) return true;
  return Boolean(contentSearchPolicyCache.search.layers.semantic?.enabled);
}

function isContentSearchFulltextLayerEnabled() {
  if (!contentSearchPolicyCache?.search?.layers) return true;
  return Boolean(contentSearchPolicyCache.search.layers.fulltext?.enabled);
}

function isContentSearchStorageLayerEnabled() {
  if (!contentSearchPolicyCache?.search?.layers) return true;
  return Boolean(contentSearchPolicyCache.search.layers.storage?.enabled);
}

function getContentSearchHybridScopes() {
  const enabled = Array.isArray(contentSearchPolicyCache?.search?.enabledScopes)
    ? contentSearchPolicyCache.search.enabledScopes
    : ["semantic", "fulltext"];
  if (isContentSearchSemantic()) {
    return enabled.includes("semantic") ? ["semantic"] : [];
  }
  if (enabled.includes("fulltext")) return ["fulltext"];
  return enabled.length ? enabled : [];
}

function formatContentSearchPolicyError(error) {
  const message = String(error?.message || error || "");
  if (message.includes("index_disabled") || message.includes("отключён")) {
    return "Слой поиска отключён в settings.global.yml";
  }
  return message || "Ошибка поиска";
}

async function loadContentSearchPolicy() {
  if (contentSearchPolicyLoadPromise) return contentSearchPolicyLoadPromise;
  contentSearchPolicyLoadPromise = fetch("/api/workspace-index/policy")
    .then(async (response) => {
      const data = await response.json();
      if (!response.ok) throw new Error(data.error || response.statusText);
      contentSearchPolicyCache = data;
      syncContentSearchPolicyUi();
      return data;
    })
    .catch(() => null)
    .finally(() => {
      contentSearchPolicyLoadPromise = null;
    });
  return contentSearchPolicyLoadPromise;
}

function syncContentSearchPolicyUi() {
  const layers = contentSearchPolicyCache?.search?.layers;
  if (!layers) return;

  if (contentSearchModeSemanticBtn) {
    const semanticDisabled = !layers.semantic?.enabled;
    contentSearchModeSemanticBtn.disabled = semanticDisabled;
    contentSearchModeSemanticBtn.classList.toggle("is-disabled", semanticDisabled);
    contentSearchModeSemanticBtn.title = semanticDisabled
      ? "Семантический индекс отключён в settings.global.yml"
      : "Поиск по смыслу";
  }
  if (contentSearchAdvancedOpenBtnNode) {
    const storageDisabled = !layers.storage?.enabled;
    contentSearchAdvancedOpenBtnNode.toggleAttribute("disabled", storageDisabled);
    contentSearchAdvancedOpenBtnNode.title = storageDisabled
      ? "Индекс полей отключён в settings.global.yml"
      : "";
  }
}

function setContentSearchMode(mode) {
  if (!contentSearchModeNode) return;
  let next = mode === "semantic" || mode === "id" ? mode : "text";
  if (next === "semantic" && contentSearchPolicyCache && !isContentSearchSemanticLayerEnabled()) {
    next = "text";
  }
  if (contentSearchModeNode.value === next) {
    syncContentSearchModeToggleUi();
    syncContentSearchPolicyUi();
    return;
  }
  contentSearchModeNode.value = next;
  contentSearchModeNode.dispatchEvent(new Event("change", { bubbles: true }));
}

function getContentSearchFieldCatalogMeta(key, catalog = contentSearchFieldCatalogCache) {
  return (catalog?.fieldCatalogMeta || []).find((item) => item.key === key) || null;
}

function getContentSearchFieldPrimaryVariant(key, catalog = contentSearchFieldCatalogCache) {
  const meta = getContentSearchFieldCatalogMeta(key, catalog);
  return meta?.variants?.[0] || null;
}

function formatContentSearchFieldOptionLabel(key, catalog = contentSearchFieldCatalogCache) {
  const meta = getContentSearchFieldCatalogMeta(key, catalog);
  const variants = meta?.variants || [];
  const title = variants.find((variant) => variant.title)?.title || variants[0]?.title || "";
  if (title) return `${title} · ${key}`;
  if (variants.length > 1) return `${key} · ${variants.length} контекста`;
  return key;
}

function buildContentSearchFieldPickerEntries(catalog = contentSearchFieldCatalogCache) {
  const fields = catalog?.fieldCatalog || [];
  return fields.map((key) => {
    const meta = getContentSearchFieldCatalogMeta(key, catalog);
    const variants = meta?.variants || [];
    const title = variants.find((variant) => variant.title)?.title || variants[0]?.title || "";
    const type = variants[0]?.type || "";
    const label = title ? `${title} · ${key}` : key;
    const haystack = [key, title, type, ...variants.map((variant) => variant.title).filter(Boolean)]
      .join(" ")
      .toLowerCase();
    return { key, title, type, label, haystack };
  });
}

function resolveContentSearchFieldPickerEntry(inputValue, catalog = contentSearchFieldCatalogCache) {
  const raw = String(inputValue || "").trim();
  if (!raw) return null;
  const lower = raw.toLowerCase();
  const entries = buildContentSearchFieldPickerEntries(catalog);
  return (
    entries.find((entry) => entry.key === raw) ||
    entries.find((entry) => entry.label === raw) ||
    entries.find((entry) => entry.title && entry.title.toLowerCase() === lower) ||
    entries.find((entry) => entry.key.toLowerCase() === lower) ||
    entries.find((entry) => entry.haystack.includes(lower)) ||
    null
  );
}

function mountContentSearchFieldPicker(parent, { catalog, selectedKey = "", onChange = null } = {}) {
  const wrap = document.createElement("div");
  wrap.className = "content-search-field-picker";

  const input = document.createElement("input");
  input.type = "search";
  input.className = "content-search-field-picker-input";
  input.autocomplete = "off";
  input.spellcheck = false;
  input.setAttribute("aria-label", "Поле frontmatter");
  input.setAttribute("role", "combobox");
  input.setAttribute("aria-expanded", "false");
  input.setAttribute("aria-autocomplete", "list");

  const hidden = document.createElement("input");
  hidden.type = "hidden";
  hidden.className = "content-search-advanced-field-key";
  hidden.value = selectedKey || "";

  const menu = document.createElement("div");
  menu.className = "content-search-field-picker-menu hidden";
  menu.setAttribute("role", "listbox");

  const entries = buildContentSearchFieldPickerEntries(catalog);
  const hasFields = entries.length > 0;
  input.placeholder = hasFields
    ? "название или ключ…"
    : catalog?.ready
      ? "нет полей в индексе"
      : "пересоберите «Поля»";
  input.disabled = !hasFields || isContentSearchIdMode();

  if (selectedKey) {
    const selected = entries.find((entry) => entry.key === selectedKey);
    input.value = selected?.label || selectedKey;
  }

  function setMenuOpen(open) {
    menu.classList.toggle("hidden", !open);
    input.setAttribute("aria-expanded", open ? "true" : "false");
  }

  function selectEntry(entry) {
    if (!entry) return;
    hidden.value = entry.key;
    input.value = entry.label;
    setMenuOpen(false);
    onChange?.(entry.key);
  }

  function renderMenu(filter = "") {
    if (!hasFields) {
      setMenuOpen(false);
      return;
    }
    const needle = String(filter || "").trim().toLowerCase();
    const items = needle
      ? entries.filter(
          (entry) =>
            entry.haystack.includes(needle) ||
            entry.key.toLowerCase().includes(needle) ||
            entry.title.toLowerCase().includes(needle)
        )
      : entries;
    menu.replaceChildren();
    for (const entry of items.slice(0, 60)) {
      const btn = document.createElement("button");
      btn.type = "button";
      btn.className = "content-search-field-picker-option";
      btn.setAttribute("role", "option");
      btn.dataset.key = entry.key;
      if (entry.title) {
        const titleNode = document.createElement("span");
        titleNode.className = "content-search-field-picker-option-title";
        titleNode.textContent = entry.title;
        const keyNode = document.createElement("span");
        keyNode.className = "content-search-field-picker-option-key";
        keyNode.textContent = entry.key;
        btn.append(titleNode, keyNode);
        if (entry.type) btn.title = entry.type;
      } else {
        const keyNode = document.createElement("span");
        keyNode.className = "content-search-field-picker-option-key";
        keyNode.textContent = entry.key;
        btn.appendChild(keyNode);
      }
      btn.addEventListener("mousedown", (event) => event.preventDefault());
      btn.addEventListener("click", () => selectEntry(entry));
      menu.appendChild(btn);
    }
    setMenuOpen(items.length > 0);
  }

  input.addEventListener("focus", () => renderMenu(input.value));
  input.addEventListener("input", () => {
    hidden.value = "";
    const exact = resolveContentSearchFieldPickerEntry(input.value, catalog);
    if (exact) hidden.value = exact.key;
    renderMenu(input.value);
    if (exact) onChange?.(exact.key);
  });
  input.addEventListener("blur", () => {
    window.setTimeout(() => {
      setMenuOpen(false);
      if (!hidden.value && input.value.trim()) {
        const match = resolveContentSearchFieldPickerEntry(input.value, catalog);
        if (match) selectEntry(match);
      }
    }, 120);
  });
  input.addEventListener("keydown", (event) => {
    if (event.key === "Escape") {
      setMenuOpen(false);
      return;
    }
    if (event.key !== "Enter") return;
    event.preventDefault();
    const match = resolveContentSearchFieldPickerEntry(input.value, catalog);
    if (match) selectEntry(match);
  });

  wrap.append(input, hidden, menu);
  parent.appendChild(wrap);
  return { input, hidden, refreshSelected(key) {
    hidden.value = key || "";
    const selected = entries.find((entry) => entry.key === key);
    input.value = selected?.label || key || "";
  } };
}

function invalidateContentSearchFieldValuesCache(field = "") {
  if (!field) {
    contentSearchFieldValuesCache.clear();
    contentSearchFieldValuesLoading.clear();
    return;
  }
  for (const key of [...contentSearchFieldValuesCache.keys()]) {
    if (key.startsWith(`${field}|`)) contentSearchFieldValuesCache.delete(key);
  }
}

async function ensureContentSearchFieldValues(field, q = "") {
  const fieldKey = String(field || "").trim();
  if (!fieldKey) return [];
  const pathPrefix = getContentSearchPathPrefix();
  const cacheKey = `${fieldKey}|${pathPrefix}|${String(q || "").trim().toLowerCase()}`;
  if (contentSearchFieldValuesCache.has(cacheKey)) {
    return contentSearchFieldValuesCache.get(cacheKey);
  }
  if (contentSearchFieldValuesLoading.has(cacheKey)) {
    return contentSearchFieldValuesLoading.get(cacheKey);
  }
  const job = (async () => {
    try {
      const response = await fetch(
        buildApiUrl("/api/storage-index/field-values", {
          field: fieldKey,
          q: String(q || "").trim(),
          pathPrefix: pathPrefix || undefined,
          limit: "80"
        })
      );
      const data = await response.json();
      if (!response.ok) throw new Error(data.error || data.details || response.statusText);
      const values = Array.isArray(data.values) ? data.values : [];
      contentSearchFieldValuesCache.set(cacheKey, values);
      return values;
    } catch (error) {
      console.warn("content search field values load failed", error);
      return [];
    } finally {
      contentSearchFieldValuesLoading.delete(cacheKey);
    }
  })();
  contentSearchFieldValuesLoading.set(cacheKey, job);
  return job;
}

function mountContentSearchValueInput(parent, { rowId, field = "", value = "", onInput = null } = {}) {
  const wrap = document.createElement("div");
  wrap.className = "content-search-value-picker";

  const input = document.createElement("input");
  input.type = "text";
  input.className = "content-search-advanced-value content-search-advanced-value-input";
  input.placeholder = field ? "значение или выберите…" : "сначала поле";
  input.setAttribute("aria-label", "Значение поля");
  input.value = value || "";
  input.disabled = !field;

  const datalistId = `content-search-field-values-${rowId}`;
  input.setAttribute("list", datalistId);
  const datalist = document.createElement("datalist");
  datalist.id = datalistId;

  let valuesRequestId = 0;
  async function refreshValues(nextField = field, needle = "") {
    const requestId = ++valuesRequestId;
    if (!nextField) {
      datalist.replaceChildren();
      input.disabled = true;
      input.placeholder = "сначала поле";
      return;
    }
    input.disabled = false;
    input.placeholder = "значение или выберите…";
    const values = await ensureContentSearchFieldValues(nextField, needle);
    if (requestId !== valuesRequestId) return;
    datalist.replaceChildren();
    for (const item of values) {
      const option = document.createElement("option");
      option.value = String(item);
      datalist.appendChild(option);
    }
  }

  input.addEventListener("input", () => {
    onInput?.();
    if (field) void refreshValues(field, input.value.trim());
  });
  input.addEventListener("focus", () => {
    if (field) void refreshValues(field, input.value.trim());
  });

  wrap.append(input, datalist);
  parent.appendChild(wrap);
  void refreshValues(field);
  return { input, refreshValues };
}

function createContentSearchAdvancedFilterRow() {
  return {
    id: `csf-${++contentSearchAdvancedFilterRowSeq}`,
    field: "",
    op: "eq",
    value: ""
  };
}

function contentSearchAdvancedRowToClause(row) {
  const field = String(row?.field || "").trim();
  const op = String(row?.op || "").trim();
  const value = String(row?.value ?? "").trim();
  if (!field || !op || value === "") return null;
  const clause = { field };
  if (op === "eq") clause.eq = value;
  else if (op === "contains") clause.contains = value;
  else if (op === "gte") clause.gte = value;
  else if (op === "lte") clause.lte = value;
  else return null;
  return clause;
}

function getContentSearchFieldFilterOp(clause) {
  if (clause?.contains != null) return "contains";
  if (clause?.gte != null) return "gte";
  if (clause?.lte != null) return "lte";
  return "eq";
}

function getContentSearchFieldFilterValue(clause) {
  return clause?.eq ?? clause?.contains ?? clause?.gte ?? clause?.lte ?? "";
}

function getContentSearchFieldFilterLabel(clause, catalog = contentSearchFieldCatalogCache) {
  const op = getContentSearchFieldFilterOp(clause);
  const opLabel = CONTENT_SEARCH_FIELD_OP_LABELS[op] || op;
  const value = getContentSearchFieldFilterValue(clause);
  const title = getContentSearchFieldPrimaryVariant(clause.field, catalog)?.title || "";
  const fieldLabel = title ? `${title} (${clause.field})` : clause.field;
  return `${fieldLabel} ${opLabel} ${value}`;
}

function getContentSearchFieldFilter() {
  const clauses = contentSearchAdvancedFieldFilters
    .map((row) => contentSearchAdvancedRowToClause(row))
    .filter(Boolean);
  return clauses.length ? clauses : null;
}

function hasActiveContentSearchFieldFilter() {
  return Boolean(getContentSearchFieldFilter()?.length);
}

function countActiveContentSearchFilters() {
  let count = 0;
  if (getContentSearchScope() !== CONTENT_SEARCH_DEFAULT_SCOPE) count += 1;
  if (getContentSearchMatch() !== CONTENT_SEARCH_DEFAULT_MATCH) count += 1;
  if (getContentSearchFileType() !== CONTENT_SEARCH_DEFAULT_TYPE) count += 1;
  const fieldClauses = getContentSearchFieldFilter();
  if (fieldClauses?.length) count += fieldClauses.length;
  return count;
}

function syncContentSearchFiltersBadge() {
  const count = countActiveContentSearchFilters();
  contentSearchFiltersBadgeNode?.classList.toggle("hidden", count <= 0);
  contentSearchFiltersBtnNode?.classList.toggle("has-active-filters", count > 0);
  if (contentSearchFiltersBadgeNode && count > 0) {
    contentSearchFiltersBadgeNode.textContent = String(count);
  }
}

function resetContentSearchFieldFilter() {
  contentSearchAdvancedFieldFilters = [];
  contentSearchAdvancedFilterDraft = [];
}

function resetContentSearchFilters() {
  if (contentSearchScopeNode) contentSearchScopeNode.value = CONTENT_SEARCH_DEFAULT_SCOPE;
  if (contentSearchMatchNode) contentSearchMatchNode.value = CONTENT_SEARCH_DEFAULT_MATCH;
  if (contentSearchTypeNode) contentSearchTypeNode.value = CONTENT_SEARCH_DEFAULT_TYPE;
  resetContentSearchFieldFilter();
  updateContentSearchPlaceholder();
  syncContentSearchFiltersUi();
  scheduleContentSearch();
}

function resetContentSearchFilter(key) {
  if (key === "scope" && contentSearchScopeNode) {
    contentSearchScopeNode.value = CONTENT_SEARCH_DEFAULT_SCOPE;
  } else if (key === "match" && contentSearchMatchNode) {
    contentSearchMatchNode.value = CONTENT_SEARCH_DEFAULT_MATCH;
  } else if (key === "type" && contentSearchTypeNode) {
    contentSearchTypeNode.value = CONTENT_SEARCH_DEFAULT_TYPE;
  } else if (key === "fields") {
    resetContentSearchFieldFilter();
  } else if (key.startsWith("field:")) {
    const index = Number(key.slice(6));
    if (Number.isFinite(index) && index >= 0) {
      contentSearchAdvancedFieldFilters.splice(index, 1);
    }
  }
  updateContentSearchPlaceholder();
  syncContentSearchFiltersUi();
  scheduleContentSearch();
}

function renderContentSearchActiveFilters() {
  if (!contentSearchActiveFiltersNode) return;
  contentSearchActiveFiltersNode.replaceChildren();
  contentSearchBarNode?.classList.remove("has-active-filters");
  const chips = [];
  const scope = getContentSearchScope();
  const match = getContentSearchMatch();
  const type = getContentSearchFileType();
  const metaFiltersDisabled = isContentSearchAlternateMode();
  if (!metaFiltersDisabled && scope !== CONTENT_SEARCH_DEFAULT_SCOPE) {
    chips.push({ key: "scope", label: CONTENT_SEARCH_SCOPE_LABELS[scope] || scope });
  }
  if (!metaFiltersDisabled && match !== CONTENT_SEARCH_DEFAULT_MATCH) {
    chips.push({ key: "match", label: CONTENT_SEARCH_MATCH_LABELS[match] || match });
  }
  if (!metaFiltersDisabled && type !== CONTENT_SEARCH_DEFAULT_TYPE) {
    chips.push({ key: "type", label: CONTENT_SEARCH_TYPE_LABELS[type] || type });
  }
  const fieldFilter = getContentSearchFieldFilter();
  fieldFilter?.forEach((clause, index) => {
    chips.push({
      key: `field:${index}`,
      label: getContentSearchFieldFilterLabel(clause)
    });
  });
  if (!chips.length) {
    contentSearchActiveFiltersNode.classList.add("hidden");
    return;
  }
  contentSearchActiveFiltersNode.classList.remove("hidden");
  for (const chip of chips) {
    const btn = document.createElement("button");
    btn.type = "button";
    btn.className = "content-search-filter-chip";
    btn.dataset.filterKey = chip.key;
    btn.title = `Сбросить: ${chip.label}`;
    btn.setAttribute("aria-label", `Сбросить фильтр «${chip.label}»`);
    const label = document.createElement("span");
    label.className = "content-search-filter-chip-label";
    label.textContent = chip.label;
    const close = document.createElement("span");
    close.className = "content-search-filter-chip-x";
    close.setAttribute("aria-hidden", "true");
    close.textContent = "×";
    btn.append(label, close);
    btn.addEventListener("click", (event) => {
      event.stopPropagation();
      resetContentSearchFilter(chip.key);
    });
    contentSearchActiveFiltersNode.appendChild(btn);
  }
  contentSearchBarNode?.classList.toggle("has-active-filters", chips.length > 0);
}

function syncContentSearchAdvancedSummary() {
  if (!contentSearchAdvancedSummaryNode) return;
  const clauses = getContentSearchFieldFilter();
  if (!clauses?.length) {
    contentSearchAdvancedSummaryNode.textContent = "Нет условий по полям";
    return;
  }
  if (clauses.length <= 2) {
    contentSearchAdvancedSummaryNode.textContent = clauses
      .map((clause) => getContentSearchFieldFilterLabel(clause))
      .join("; ");
    return;
  }
  contentSearchAdvancedSummaryNode.textContent = `${clauses.length} условий по полям`;
}

function syncContentSearchFiltersUi() {
  syncContentSearchFiltersBadge();
  syncContentSearchAdvancedSummary();
  renderContentSearchActiveFilters();
  contentSearchFiltersPopoverNode?.classList.toggle("is-semantic", isContentSearchSemantic());
  contentSearchAdvancedOpenBtnNode?.toggleAttribute("disabled", isContentSearchIdMode());
}

if (typeof window !== "undefined") {
  window.invalidateContentSearchFieldCatalog = invalidateContentSearchFieldCatalog;
}

function positionContentSearchFiltersPopover() {
  const popover = contentSearchFiltersPopoverNode;
  const anchor = contentSearchFiltersBtnNode;
  if (!popover || !anchor || popover.classList.contains("hidden")) return;
  const rect = anchor.getBoundingClientRect();
  const width = Math.min(320, Math.max(260, Math.round(rect.width + 200)));
  const left = Math.min(
    Math.max(12, Math.round(rect.right - width)),
    Math.max(12, window.innerWidth - width - 12)
  );
  const top = Math.round(rect.bottom + 8);
  const maxHeight = Math.max(160, window.innerHeight - top - 12);
  popover.style.top = `${top}px`;
  popover.style.left = `${left}px`;
  popover.style.width = `${width}px`;
  popover.style.maxHeight = `${maxHeight}px`;
  popover.style.overflowY = "auto";
}

function closeContentSearchFiltersPopover() {
  contentSearchFiltersPopoverNode?.classList.add("hidden");
  contentSearchFiltersBtnNode?.setAttribute("aria-expanded", "false");
}

function isContentSearchAdvancedFilterModalOpen() {
  return Boolean(contentSearchAdvancedModalNode && !contentSearchAdvancedModalNode.classList.contains("hidden"));
}

function syncContentSearchAdvancedFilterDraftFromDom() {
  if (!contentSearchAdvancedRowsNode) return;
  const next = [];
  for (const rowNode of contentSearchAdvancedRowsNode.querySelectorAll(".content-search-advanced-row")) {
    const fieldInput = rowNode.querySelector(".content-search-field-picker-input");
    const hiddenField = rowNode.querySelector(".content-search-advanced-field-key");
    let field = hiddenField?.value || "";
    if (!field && fieldInput?.value) {
      const match = resolveContentSearchFieldPickerEntry(fieldInput.value);
      field = match?.key || "";
      if (match && hiddenField) hiddenField.value = match.key;
    }
    const op = rowNode.querySelector(".content-search-advanced-op")?.value || "eq";
    const value = rowNode.querySelector(".content-search-advanced-value")?.value ?? "";
    next.push({
      id: rowNode.dataset.rowId || createContentSearchAdvancedFilterRow().id,
      field,
      op,
      value
    });
  }
  contentSearchAdvancedFilterDraft = next;
}

function renderContentSearchAdvancedFilterRows(catalog = contentSearchFieldCatalogCache) {
  if (!contentSearchAdvancedRowsNode) return;
  contentSearchAdvancedRowsNode.replaceChildren();
  const rows = contentSearchAdvancedFilterDraft.length
    ? contentSearchAdvancedFilterDraft
    : [createContentSearchAdvancedFilterRow()];
  contentSearchAdvancedFilterDraft = rows;

  for (const row of rows) {
    const rowNode = document.createElement("div");
    rowNode.className = "content-search-advanced-row";
    rowNode.dataset.rowId = row.id;
    rowNode.setAttribute("role", "listitem");

    const fieldLabel = document.createElement("label");
    fieldLabel.className = "content-search-advanced-cell content-search-advanced-cell--field";
    const fieldCaption = document.createElement("span");
    fieldCaption.className = "content-search-advanced-cell-label";
    fieldCaption.textContent = "Поле";
    fieldLabel.appendChild(fieldCaption);
    let valueControl = null;
    const fieldPicker = mountContentSearchFieldPicker(fieldLabel, {
      catalog,
      selectedKey: row.field,
      onChange: (fieldKey) => {
        syncContentSearchAdvancedFilterDraftFromDom();
        valueControl?.refreshValues(fieldKey, "");
      }
    });

    const opLabel = document.createElement("label");
    opLabel.className = "content-search-advanced-cell content-search-advanced-cell--op";
    const opCaption = document.createElement("span");
    opCaption.className = "content-search-advanced-cell-label";
    opCaption.textContent = "Условие";
    const opSelect = document.createElement("select");
    opSelect.className = "content-search-advanced-op content-search-filter-control";
    opSelect.setAttribute("aria-label", "Условие фильтра");
    opSelect.innerHTML = `
      <option value="eq">равно</option>
      <option value="contains">содержит</option>
      <option value="gte">≥ (число/дата)</option>
      <option value="lte">≤ (число/дата)</option>
    `;
    opSelect.value = row.op || "eq";
    opLabel.append(opCaption, opSelect);

    const valueLabel = document.createElement("label");
    valueLabel.className = "content-search-advanced-cell content-search-advanced-cell--value";
    const valueCaption = document.createElement("span");
    valueCaption.className = "content-search-advanced-cell-label";
    valueCaption.textContent = "Значение";
    valueLabel.appendChild(valueCaption);
    valueControl = mountContentSearchValueInput(valueLabel, {
      rowId: row.id,
      field: row.field,
      value: row.value,
      onInput: () => syncContentSearchAdvancedFilterDraftFromDom()
    });

    const removeBtn = document.createElement("button");
    removeBtn.type = "button";
    removeBtn.className = "content-search-advanced-remove-btn";
    removeBtn.setAttribute("aria-label", "Удалить условие");
    removeBtn.textContent = "×";
    removeBtn.disabled = rows.length <= 1;
    removeBtn.addEventListener("click", () => {
      syncContentSearchAdvancedFilterDraftFromDom();
      if (contentSearchAdvancedFilterDraft.length <= 1) {
        contentSearchAdvancedFilterDraft = [createContentSearchAdvancedFilterRow()];
      } else {
        contentSearchAdvancedFilterDraft = contentSearchAdvancedFilterDraft.filter((item) => item.id !== row.id);
      }
      renderContentSearchAdvancedFilterRows(catalog);
    });

    opSelect.addEventListener("change", () => syncContentSearchAdvancedFilterDraftFromDom());
    fieldPicker.input.addEventListener("input", () => syncContentSearchAdvancedFilterDraftFromDom());

    rowNode.append(fieldLabel, opLabel, valueLabel, removeBtn);
    contentSearchAdvancedRowsNode.appendChild(rowNode);
  }
}

function openContentSearchAdvancedFilterModal() {
  if (!contentSearchAdvancedModalNode || isContentSearchIdMode()) return;
  closeContentSearchFiltersPopover();
  contentSearchAdvancedFilterDraft = contentSearchAdvancedFieldFilters.length
    ? contentSearchAdvancedFieldFilters.map((row) => ({
        id: row.id || createContentSearchAdvancedFilterRow().id,
        field: row.field || "",
        op: row.op || "eq",
        value: row.value || ""
      }))
    : [createContentSearchAdvancedFilterRow()];
  contentSearchAdvancedModalNode.classList.remove("hidden");
  document.body.classList.add("modal-open");
  void ensureContentSearchFieldCatalog(!contentSearchFieldCatalogCache?.fieldCatalog?.length).then((catalog) => {
    renderContentSearchAdvancedFilterRows(catalog || contentSearchFieldCatalogCache);
  });
  contentSearchAdvancedApplyBtnNode?.focus();
}

function closeContentSearchAdvancedFilterModal() {
  contentSearchAdvancedModalNode?.classList.add("hidden");
  if (!document.querySelector(".modal-overlay:not(.hidden)")) {
    document.body.classList.remove("modal-open");
  }
}

function applyContentSearchAdvancedFilters() {
  syncContentSearchAdvancedFilterDraftFromDom();
  contentSearchAdvancedFieldFilters = contentSearchAdvancedFilterDraft
    .map((row) => ({
      id: row.id,
      field: String(row.field || "").trim(),
      op: String(row.op || "eq").trim(),
      value: String(row.value ?? "").trim()
    }))
    .filter((row) => row.field && row.op && row.value !== "");
  closeContentSearchAdvancedFilterModal();
  syncContentSearchFiltersUi();
  scheduleContentSearch();
}

function resetContentSearchAdvancedFilterDraft() {
  contentSearchAdvancedFilterDraft = [createContentSearchAdvancedFilterRow()];
  renderContentSearchAdvancedFilterRows(contentSearchFieldCatalogCache);
}

function addContentSearchAdvancedFilterRow() {
  syncContentSearchAdvancedFilterDraftFromDom();
  contentSearchAdvancedFilterDraft.push(createContentSearchAdvancedFilterRow());
  renderContentSearchAdvancedFilterRows(contentSearchFieldCatalogCache);
}

function invalidateContentSearchFieldCatalog() {
  contentSearchFieldCatalogCache = null;
  contentSearchFieldCatalogLoading = null;
  invalidateContentSearchFieldValuesCache();
}

async function ensureContentSearchFieldCatalog(force = false) {
  const cached = contentSearchFieldCatalogCache;
  if (!force && cached?.fieldCatalog?.length) return cached;
  if (contentSearchFieldCatalogLoading) return contentSearchFieldCatalogLoading;
  contentSearchFieldCatalogLoading = (async () => {
    try {
      const response = await fetch(buildApiUrl("/api/storage-index/field-catalog"));
      const data = await response.json();
      if (!response.ok) throw new Error(data.error || data.details || response.statusText);
      contentSearchFieldCatalogCache = {
        ready: Boolean(data.ready),
        builtAt: data.builtAt || null,
        fieldCatalog: Array.isArray(data.fieldCatalog) ? data.fieldCatalog : [],
        fieldCatalogMeta: Array.isArray(data.fieldCatalogMeta) ? data.fieldCatalogMeta : []
      };
      if (isContentSearchAdvancedFilterModalOpen()) {
        renderContentSearchAdvancedFilterRows(contentSearchFieldCatalogCache);
      }
      return contentSearchFieldCatalogCache;
    } catch (error) {
      console.warn("content search field catalog load failed", error);
      if (isContentSearchAdvancedFilterModalOpen()) {
        renderContentSearchAdvancedFilterRows({ ready: false, fieldCatalog: [], fieldCatalogMeta: [] });
      }
      return null;
    } finally {
      contentSearchFieldCatalogLoading = null;
    }
  })();
  return contentSearchFieldCatalogLoading;
}

function toggleContentSearchFiltersPopover() {
  if (!contentSearchFiltersPopoverNode || !contentSearchFiltersBtnNode) return;
  const willOpen = contentSearchFiltersPopoverNode.classList.contains("hidden");
  if (willOpen) {
    setContentSearchHelpOpen(false);
    contentSearchFiltersPopoverNode.classList.remove("hidden");
    contentSearchFiltersBtnNode.setAttribute("aria-expanded", "true");
    positionContentSearchFiltersPopover();
    syncContentSearchAdvancedSummary();
    return;
  }
  closeContentSearchFiltersPopover();
}

function updateContentSearchFiltersState() {
  const idMode = isContentSearchIdMode();
  const semanticMode = isContentSearchSemantic();
  contentSearchBarNode?.classList.toggle("content-search-bar--semantic", semanticMode);
  contentSearchBarNode?.classList.toggle("content-search-bar--id", idMode);
  for (const node of [contentSearchScopeNode, contentSearchMatchNode, contentSearchTypeNode]) {
    if (node) node.disabled = semanticMode || idMode;
  }
  contentSearchFiltersBtnNode?.toggleAttribute("disabled", idMode);
  contentSearchAdvancedOpenBtnNode?.toggleAttribute(
    "disabled",
    idMode || (contentSearchPolicyCache && !isContentSearchStorageLayerEnabled())
  );
  syncContentSearchModeToggleUi();
  syncContentSearchFiltersUi();
  syncContentSearchPolicyUi();
}

function loadContentSearchPathScope() {
  try {
    const raw = sessionStorage.getItem(CONTENT_SEARCH_PATH_SCOPE_KEY);
    if (!raw) return { pathPrefix: "", label: "", kind: "all", sourcePath: "" };
    const parsed = JSON.parse(raw);
    const pathPrefix = String(parsed?.pathPrefix || "").replace(/\\/g, "/").replace(/^\/+/, "").replace(/\/+$/, "");
    if (!pathPrefix) return { pathPrefix: "", label: "", kind: "all", sourcePath: "" };
    return {
      pathPrefix,
      label: String(parsed?.label || pathPrefix.split("/").pop() || pathPrefix),
      kind: String(parsed?.kind || "folder"),
      sourcePath: String(parsed?.sourcePath || "")
    };
  } catch {
    return { pathPrefix: "", label: "", kind: "all", sourcePath: "" };
  }
}

function saveContentSearchPathScope(scope) {
  contentSearchPathScope = scope || { pathPrefix: "", label: "", kind: "all", sourcePath: "" };
  try {
    if (contentSearchPathScope.pathPrefix) {
      sessionStorage.setItem(CONTENT_SEARCH_PATH_SCOPE_KEY, JSON.stringify(contentSearchPathScope));
    } else {
      sessionStorage.removeItem(CONTENT_SEARCH_PATH_SCOPE_KEY);
    }
  } catch {
    // ignore storage errors
  }
  renderContentSearchPathScope();
  updateContentSearchPlaceholder();
}

function getContentSearchPathPrefix() {
  return String(contentSearchPathScope?.pathPrefix || "")
    .replace(/\\/g, "/")
    .replace(/^\/+/, "")
    .replace(/\/+$/, "");
}

function clearContentSearchPathScope() {
  saveContentSearchPathScope({ pathPrefix: "", label: "", kind: "all", sourcePath: "" });
  scheduleContentSearch();
}

function renderContentSearchPathScope() {
  if (!contentSearchPathScopeNode || !contentSearchPathScopeLabelNode) return;
  const pathPrefix = getContentSearchPathPrefix();
  const active = Boolean(pathPrefix);
  contentSearchPathScopeNode.classList.toggle("is-empty", !active);
  contentSearchPathScopeNode.classList.toggle("is-active", active);
  contentSearchPathScopeLabelNode.textContent = active
    ? contentSearchPathScope.label || pathPrefix.split("/").pop() || pathPrefix
    : "";
  contentSearchPathScopeNode.title = active
    ? `Искать только в: ${pathPrefix}`
    : "Перетащите тему из меню, чтобы ограничить область поиска";
  contentSearchPathScopeClearNode?.classList.toggle("hidden", !active);
}

function deriveSearchPathScopeFromResolve(payload, fallbackLabel = "") {
  if (!payload || payload.error) return null;
  if (payload.topic?.folderPath && payload.topic.folderPath !== ".") {
    return {
      pathPrefix: String(payload.topic.folderPath).replace(/\\/g, "/").replace(/^\/+/, "").replace(/\/+$/, ""),
      label: payload.topic.title || fallbackLabel || payload.topic.folderPath.split("/").pop(),
      kind: "topic",
      sourcePath: payload.inputPath || payload.topic.manifestPath || ""
    };
  }
  if (payload.area?.folderPath && payload.area.folderPath !== ".") {
    return {
      pathPrefix: String(payload.area.folderPath).replace(/\\/g, "/").replace(/^\/+/, "").replace(/\/+$/, ""),
      label: payload.area.title || fallbackLabel || payload.area.folderPath.split("/").pop(),
      kind: "area",
      sourcePath: payload.inputPath || payload.area.manifestPath || ""
    };
  }
  const inputPath = String(payload.inputPath || "").replace(/\\/g, "/").replace(/^\/+/, "").replace(/\/+$/, "");
  if (!inputPath) return null;
  const folderPath = inputPath.includes("/") ? inputPath.slice(0, inputPath.lastIndexOf("/")) : "";
  if (!folderPath) return null;
  return {
    pathPrefix: folderPath,
    label: fallbackLabel || folderPath.split("/").pop() || folderPath,
    kind: "folder",
    sourcePath: inputPath
  };
}

async function resolveContentSearchPathScopeFromMenuPayload(payload) {
  if (!payload) return null;
  const folderPath = String(payload.folderPath || "").replace(/\\/g, "/").replace(/^\/+/, "").replace(/\/+$/, "");
  if (folderPath && folderPath !== ".") {
    return {
      pathPrefix: folderPath,
      label: payload.label || folderPath.split("/").pop() || folderPath,
      kind: payload.source === "adopt-folder" ? "area" : "folder",
      sourcePath: payload.path || folderPath
    };
  }
  const nodePath = String(payload.path || "").replace(/\\/g, "/").replace(/^\/+/, "");
  if (!nodePath) return null;
  const response = await fetch(buildApiUrl("/api/agent/resolve-path", { path: nodePath }));
  if (!response.ok) throw new Error(`resolve-path failed with ${response.status}`);
  const data = await response.json();
  return deriveSearchPathScopeFromResolve(data, payload.label || "");
}

async function applyContentSearchPathScopeFromMenuPayload(payload) {
  const scope = await resolveContentSearchPathScopeFromMenuPayload(payload);
  if (!scope?.pathPrefix) {
    showToast("Не удалось определить область поиска", "error");
    return;
  }
  saveContentSearchPathScope(scope);
  scheduleContentSearch();
  showToast(`Поиск ограничен: ${scope.label}`, "success");
}

function bindContentSearchPathScopeDrop() {
  if (!contentSearchPathScopeNode || contentSearchPathScopeNode.dataset.dropBound === "1") return;
  contentSearchPathScopeNode.dataset.dropBound = "1";

  contentSearchPathScopeNode.addEventListener("dragover", (event) => {
    if (!dataTransferHasMenuLink(event.dataTransfer)) return;
    event.preventDefault();
    event.dataTransfer.dropEffect = "copy";
    contentSearchPathScopeNode.classList.add("is-drop-target");
  });

  contentSearchPathScopeNode.addEventListener("dragleave", (event) => {
    if (event.currentTarget.contains(event.relatedTarget)) return;
    contentSearchPathScopeNode.classList.remove("is-drop-target");
  });

  contentSearchPathScopeNode.addEventListener("drop", (event) => {
    if (!dataTransferHasMenuLink(event.dataTransfer)) return;
    event.preventDefault();
    event.stopPropagation();
    contentSearchPathScopeNode.classList.remove("is-drop-target");
    const payload = extractMenuLinkFromDataTransfer(event.dataTransfer);
    if (!payload) return;
    void applyContentSearchPathScopeFromMenuPayload(payload);
  });

  contentSearchPathScopeClearNode?.addEventListener("click", (event) => {
    event.preventDefault();
    event.stopPropagation();
    clearContentSearchPathScope();
  });
}

function getContentSearchScope() {
  const scope = contentSearchScopeNode?.value || "all";
  if (scope === "filename" || scope === "content" || scope === "all") return scope;
  if (scope === "tags" && !contentSearchScopeNode?.selectedOptions?.[0]?.disabled) return scope;
  return "all";
}

function getContentSearchFileType() {
  return contentSearchTypeNode?.value || "all";
}

function getContentSearchMatch() {
  const match = contentSearchMatchNode?.value || "relaxed";
  return match === "strict" ? "strict" : "relaxed";
}

function isContentSearchHelpOpen() {
  return Boolean(contentSearchHelpPopoverNode && !contentSearchHelpPopoverNode.classList.contains("hidden"));
}

function setContentSearchHelpOpen(open) {
  if (!contentSearchHelpPopoverNode || !contentSearchHelpBtnNode) return;
  contentSearchHelpPopoverNode.classList.toggle("hidden", !open);
  contentSearchHelpBtnNode.setAttribute("aria-expanded", open ? "true" : "false");
}

function toggleContentSearchHelp() {
  if (!isContentSearchHelpOpen()) {
    closeContentSearchFiltersPopover();
  }
  setContentSearchHelpOpen(!isContentSearchHelpOpen());
}

function getContentSearchMinLength(scope = getContentSearchScope()) {
  if (isContentSearchDqlMode()) return 0;
  if (isContentSearchSemantic()) return 2;
  if (isContentSearchIdMode()) return 1;
  return scope === "filename" || scope === "all" ? 1 : 2;
}

function parseContentSearchIdQuery(query) {
  const raw = String(query || "").trim();
  const match = raw.match(/^#?(\d+)$/);
  if (!match) return null;
  const id = Number(match[1]);
  if (!Number.isFinite(id) || id <= 0 || !Number.isInteger(id)) return null;
  return id;
}

function updateContentSearchPlaceholder() {
  if (!contentSearchInputNode) return;
  const pathPrefix = getContentSearchPathPrefix();
  const scopeLabel = pathPrefix ? contentSearchPathScope.label || "теме" : "";
  if (isContentSearchIdMode()) {
    contentSearchInputNode.placeholder = pathPrefix
      ? `awn-id в «${scopeLabel}», напр. 1847…`
      : "awn-id записи: 1847 или #1847…";
    return;
  }
  if (isContentSearchDqlMode()) {
    contentSearchInputNode.placeholder = "DQL — кнопка DQL или Enter открывает редактор…";
    contentSearchInputNode.readOnly = true;
    return;
  }
  contentSearchInputNode.readOnly = false;
  if (isContentSearchSemantic()) {
    contentSearchInputNode.placeholder = pathPrefix
      ? `Поиск по смыслу в «${scopeLabel}»…`
      : "Поиск по смыслу по всему workspace…";
    return;
  }
  const scope = getContentSearchScope();
  if (scope === "filename") {
    contentSearchInputNode.placeholder = pathPrefix
      ? `Поиск по имени в «${scopeLabel}»…`
      : "Поиск по имени файла...";
    return;
  }
  if (scope === "content") {
    contentSearchInputNode.placeholder = pathPrefix
      ? `Поиск по тексту в «${scopeLabel}»…`
      : "Поиск по тексту внутри файлов...";
    return;
  }
  if (scope === "tags") {
    contentSearchInputNode.placeholder = pathPrefix
      ? `Поиск по тегам в «${scopeLabel}»…`
      : "Поиск по тэгам...";
    return;
  }
  contentSearchInputNode.placeholder = pathPrefix
    ? `Найти в «${scopeLabel}»…`
    : "Найти файл или текст...";
}

function getSearchResultTitle(item) {
  if (item?.titleName) return item.titleName;
  if (item?.awnName) {
    const fileStem = String(item.fileName || item.externalFile || item.filePath || "")
      .split("/")
      .pop()
      .replace(/\.(sidecar\.)?md$/i, "")
      .replace(/\.[^./]+$/i, "");
    return resolveNodeDisplayName(item.awnName, fileStem);
  }
  return getSearchResultDisplayName(item);
}

function getSearchResultDisplayName(item) {
  return (
    item?.titleName ||
    item?.displayName ||
    (item?.externalFile ? String(item.externalFile).split("/").pop() : "") ||
    (item?.filePath ? String(item.filePath).split("/").pop() : "") ||
    item?.source ||
    "Файл"
  );
}

function getSearchResultLocationHint(item) {
  if (item?.locationHint) return item.locationHint;
  if (item?.startLine != null && Number.isFinite(Number(item.startLine))) {
    const start = Number(item.startLine);
    const end =
      item.endLine != null && Number.isFinite(Number(item.endLine)) ? Number(item.endLine) : start;
    if (end > start) return `L${start}-${end}`;
    return `L${start}`;
  }
  if (item?.systemFile) return "Системный файл workspace";
  return item?.filePath || item?.nodePath || "";
}

function scrollToSearchResultLine(line) {
  const lineNo = Number(line);
  if (!Number.isFinite(lineNo) || lineNo < 1) return;
  const attempt = () => scrollEditorToLine(lineNo - 1);
  requestAnimationFrame(attempt);
  setTimeout(attempt, 120);
  setTimeout(attempt, 450);
}

function buildContentSearchResultItem(item, query, { showAgent = false, showFileType = true } = {}) {
  const btn = document.createElement("button");
  btn.type = "button";
  btn.className = "content-search-item";
  btn.setAttribute("role", "option");

  const body = document.createElement("div");
  body.className = "content-search-item-body";

  const media = document.createElement("div");
  media.className = "content-search-item-media";
  if (item.previewUrl) {
    const img = document.createElement("img");
    img.className = "content-search-item-preview";
    img.src = item.previewUrl;
    img.alt = "";
    img.loading = "lazy";
    media.appendChild(img);
  } else if (item.emoji) {
    media.classList.add("is-emoji");
    media.textContent = item.emoji;
  } else {
    media.classList.add("is-placeholder");
    media.textContent = String(item.kindLabel || item.fileTypeLabel || "•").slice(0, 1);
  }
  body.appendChild(media);

  const main = document.createElement("div");
  main.className = "content-search-item-main";

  const titleRow = document.createElement("div");
  titleRow.className = "content-search-item-title";

  const titleNode = document.createElement("span");
  titleNode.className = "content-search-item-name";
  titleNode.textContent = getSearchResultTitle(item);
  titleRow.appendChild(titleNode);

  const badges = document.createElement("span");
  badges.className = "content-search-item-badges";

  if (showAgent && (item.agentName || item.agentId)) {
    const agentBadge = document.createElement("span");
    agentBadge.className = "content-search-item-badge content-search-item-badge--agent";
    agentBadge.textContent = item.agentName || item.agentId;
    badges.appendChild(agentBadge);
  }

  if (item.kindLabel) {
    const kindBadge = document.createElement("span");
    kindBadge.className = "content-search-item-badge content-search-item-badge--kind";
    kindBadge.textContent = item.kindLabel;
    badges.appendChild(kindBadge);
  }

  if (item.fileTypeLabel && showFileType) {
    const typeBadge = document.createElement("span");
    typeBadge.className = "content-search-item-badge content-search-item-badge--type";
    typeBadge.textContent = item.fileTypeLabel;
    badges.appendChild(typeBadge);
  }

  if (item.matchKindLabel) {
    const matchBadge = document.createElement("span");
    matchBadge.className = "content-search-item-badge content-search-item-badge--match";
    matchBadge.textContent = item.matchKindLabel;
    badges.appendChild(matchBadge);
  } else if (item.matchCount > 1) {
    const badge = document.createElement("span");
    badge.className = "content-search-item-badge";
    badge.textContent = String(item.matchCount);
    badges.appendChild(badge);
  }

  if (badges.childElementCount) titleRow.appendChild(badges);
  main.appendChild(titleRow);

  const fileRow = document.createElement("div");
  fileRow.className = "content-search-item-file";
  const fileParts = [item.fileName || getSearchResultDisplayName(item)].filter(Boolean);
  fileRow.textContent = fileParts.join(" · ");
  main.appendChild(fileRow);

  const metaNode = document.createElement("div");
  metaNode.className = "content-search-item-meta";
  metaNode.textContent = getSearchResultLocationHint(item);
  main.appendChild(metaNode);

  const pathNode = document.createElement("div");
  pathNode.className = "content-search-item-path";
  pathNode.textContent = item.pathBreadcrumb || item.systemFile || item.filePath || item.nodePath || "";
  main.appendChild(pathNode);

  const snippetText = item.snippet;
  const titleText = getSearchResultTitle(item);
  if (snippetText && snippetText !== titleText && snippetText !== item.fileName) {
    const snippetNode = document.createElement("div");
    snippetNode.className = "content-search-item-snippet";
    snippetNode.innerHTML = highlightSearchSnippet(snippetText, query);
    main.appendChild(snippetNode);
  }

  body.appendChild(main);
  btn.appendChild(body);
  return btn;
}

function hideContentSearchResults() {
  setContentSearchLoading(false);
  contentSearchResultsNode?.classList.add("hidden");
  contentSearchInputNode?.setAttribute("aria-expanded", "false");
}

function buildContentSearchLoadingMarkup() {
  return `<div class="content-search-loading" role="status" aria-live="polite">
    <span class="content-search-loading-spinner" aria-hidden="true"></span>
    <span class="content-search-loading-text">Ищем…</span>
  </div>`;
}

function setContentSearchLoading(loading) {
  const active = Boolean(loading);
  contentSearchSpinnerNode?.classList.toggle("hidden", !active);
  contentSearchBarNode?.classList.toggle("is-loading", active);
  contentSearchInputNode?.setAttribute("aria-busy", active ? "true" : "false");
}

function renderContentSearchLoading() {
  if (!contentSearchResultsNode) return;
  contentSearchResultsNode.innerHTML = buildContentSearchLoadingMarkup();
  contentSearchResultsNode.classList.remove("hidden");
  contentSearchInputNode?.setAttribute("aria-expanded", "true");
}

function setLandingSearchLoading(loading) {
  const active = Boolean(loading);
  appLandingSearchSpinnerNode?.classList.toggle("hidden", !active);
  appLandingSearchBarNode?.classList.toggle("is-loading", active);
  appLandingSearchInputNode?.setAttribute("aria-busy", active ? "true" : "false");
}

function renderLandingSearchLoading() {
  if (!appLandingSearchResultsNode) return;
  appLandingSearchResultsNode.innerHTML = buildContentSearchLoadingMarkup();
  appLandingSearchResultsNode.classList.remove("hidden");
  appLandingSearchInputNode?.setAttribute("aria-expanded", "true");
}

function highlightSearchSnippet(snippet, query) {
  const escaped = String(query || "").replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  if (!escaped) return snippet;
  const regex = new RegExp(`(${escaped})`, "gi");
  return String(snippet || "").replace(regex, "<mark>$1</mark>");
}

function renderContentSearchResults(data) {
  if (!contentSearchResultsNode) return;
  setContentSearchLoading(false);
  const query = data?.query || "";
  const scope = data?.scope || getContentSearchScope();
  const results = Array.isArray(data?.results) ? data.results : [];
  const minLength = getContentSearchMinLength(scope);

  contentSearchResultsNode.innerHTML = "";

  if (data?.invalidId && isContentSearchIdMode()) {
    contentSearchResultsNode.innerHTML =
      `<div class="content-search-hint">Введите число awn-id, напр. <code>1847</code> или <code>#1847</code></div>`;
    contentSearchResultsNode.classList.remove("hidden");
    contentSearchInputNode?.setAttribute("aria-expanded", "true");
    return;
  }

  if (data?.notFound && isContentSearchIdMode()) {
    const agentLabel = getActiveAgentMeta()?.name || activeWorkspaceId || "текущем";
    const idLabel = data?.id != null ? `#${data.id}` : query;
    contentSearchResultsNode.innerHTML = `<div class="content-search-hint is-warning">Запись с awn-id <code>${escapeHtml(String(idLabel))}</code> не найдена в workspace «${escapeHtml(agentLabel)}». Проверьте выбранное хранилище в шапке: id привязан к файлу с полем <code>awn-id</code> в frontmatter (не к номеру в списке каналов, если он другой).</div>`;
    contentSearchResultsNode.classList.remove("hidden");
    contentSearchInputNode?.setAttribute("aria-expanded", "true");
    return;
  }

  if (data?.policyError) {
    contentSearchResultsNode.innerHTML = `<div class="content-search-hint is-warning">${escapeHtml(data.policyError)}</div>`;
    contentSearchResultsNode.classList.remove("hidden");
    contentSearchInputNode?.setAttribute("aria-expanded", "true");
    return;
  }

  if (query.length < minLength) {
    const hint = isContentSearchIdMode()
      ? "Введите awn-id (число)"
      : minLength === 1
        ? "Введите текст для поиска"
        : "Введите минимум 2 символа";
    contentSearchResultsNode.innerHTML = `<div class="content-search-hint">${hint}</div>`;
    contentSearchResultsNode.classList.remove("hidden");
    contentSearchInputNode?.setAttribute("aria-expanded", "true");
    return;
  }

  if (results.length === 0) {
    const pathPrefix = getContentSearchPathPrefix();
    const scopeHint = pathPrefix
      ? `<div class="content-search-hint">В «${escapeHtml(contentSearchPathScope.label || pathPrefix)}» ничего не найдено</div>`
      : "";
    contentSearchResultsNode.innerHTML = `${scopeHint}<div class="content-search-empty">Ничего не найдено</div>`;
    contentSearchResultsNode.classList.remove("hidden");
    contentSearchInputNode?.setAttribute("aria-expanded", "true");
    return;
  }

  for (const item of results) {
    const btn = buildContentSearchResultItem(item, query, {
      showFileType: getContentSearchFileType() === "all"
    });
    btn.addEventListener("click", () => {
      void openContentSearchResult(item);
    });
    contentSearchResultsNode.appendChild(btn);
  }

  contentSearchResultsNode.classList.remove("hidden");
  contentSearchInputNode?.setAttribute("aria-expanded", "true");
}

async function fetchContentSearch(
  query,
  scope = getContentSearchScope(),
  fileType = getContentSearchFileType(),
  match = getContentSearchMatch(),
  pathPrefix = getContentSearchPathPrefix()
) {
  const params = { q: query, scope, fileType, match, limit: 30 };
  if (pathPrefix) params.pathPrefix = pathPrefix;
  const response = await fetch(buildApiUrl("/api/search", params));
  if (!response.ok) throw new Error(`Request failed with ${response.status}`);
  return response.json();
}

function mapSemanticSearchResults(data) {
  const results = Array.isArray(data?.results) ? data.results : [];
  return {
    query: data?.query || "",
    mode: "semantic",
    scope: "semantic",
    results: results.map((row) => {
      const filePath = String(row.path || row.filePath || "").replace(/\\/g, "/");
      const fileName = filePath.split("/").pop() || filePath;
      return {
        filePath,
        fileName,
        displayName: row.displayName || fileName,
        locationHint: row.locationHint || filePath,
        pathBreadcrumb: filePath,
        snippet: row.snippet || "",
        startLine: row.startLine ?? null,
        endLine: row.endLine ?? null,
        matchKindLabel: row.score != null ? `≈ ${row.score}` : "смысл",
        kindLabel: "Смысл"
      };
    }),
    total: data?.total ?? results.length
  };
}

async function fetchContentSearchSemantic(query, limit = 30, pathPrefix = getContentSearchPathPrefix()) {
  if (contentSearchPolicyCache && !isContentSearchSemanticLayerEnabled()) {
    throw new Error("Семантический индекс отключён в settings.global.yml");
  }
  const params = { q: query, limit };
  if (pathPrefix) params.pathPrefix = pathPrefix;
  const response = await fetch(buildApiUrl("/api/search/semantic", params));
  const data = await response.json().catch(() => ({}));
  if (!response.ok) {
    throw new Error(data.message || data.error || `Request failed with ${response.status}`);
  }
  return mapSemanticSearchResults(data);
}

function mapHybridSearchResults(data, query = "") {
  const hits = Array.isArray(data?.hits) ? data.hits : [];
  return {
    query: data?.query || query,
    mode: "hybrid",
    scope: Array.isArray(data?.scopes) ? data.scopes.join("+") : "hybrid",
    results: hits.map((row) => {
      const filePath = String(row.path || "").replace(/\\/g, "/");
      const fileName = filePath.split("/").pop() || filePath;
      const sources = Array.isArray(row.sources) ? row.sources.join(" + ") : "";
      return {
        filePath,
        fileName,
        displayName: row.title || fileName,
        locationHint: row.locationHint || filePath,
        pathBreadcrumb: filePath,
        snippet: row.snippet || "",
        startLine: row.startLine ?? null,
        endLine: row.endLine ?? null,
        matchKindLabel: row.score != null ? `≈ ${row.score}` : sources || "hybrid",
        kindLabel: sources.includes("semantic") ? "Смысл" : "Текст"
      };
    }),
    total: data?.hitCount ?? hits.length,
    filterPathCount: data?.filterPathCount ?? null
  };
}

function mapStorageFieldSearchResults(data, where, query = "") {
  const clauses = Array.isArray(where) ? where : where ? [where] : [];
  const results = Array.isArray(data?.results) ? data.results : [];
  return {
    query,
    mode: "fields",
    scope: "fields",
    results: results.map((row) => {
      const filePath = String(row.path || "").replace(/\\/g, "/");
      const fileName = filePath.split("/").pop() || filePath;
      const parts = clauses.map((clause) => {
        const field = clause?.field || "";
        const entry = field ? row.fields?.[field] : null;
        const value =
          entry != null && typeof entry === "object" && "value" in entry ? entry.value : entry;
        const title = entry != null && typeof entry === "object" ? entry.title : "";
        const type = entry != null && typeof entry === "object" ? entry.type : "";
        const label = title || field;
        return title
          ? `${label}: ${value ?? "—"}${type ? ` · ${type}` : ""}`
          : `${field}: ${value ?? "—"}`;
      });
      const snippet = parts.filter(Boolean).join(" · ") || "совпадение по полям";
      return {
        filePath,
        fileName,
        displayName: fileName.replace(/\.(sidecar\.)?md$/i, "") || fileName,
        locationHint: filePath,
        pathBreadcrumb: filePath,
        snippet,
        matchKindLabel: "поле",
        kindLabel: "Поле"
      };
    }),
    total: data?.total ?? results.length
  };
}

async function fetchContentSearchHybrid(
  query,
  { where = null, scopes = ["fulltext"], pathPrefix = getContentSearchPathPrefix(), limit = 30 } = {}
) {
  const response = await fetch(buildApiUrl("/api/search/hybrid"), {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      query,
      where: where || undefined,
      scopes,
      pathPrefix: pathPrefix || undefined,
      limit,
      includeSnippets: true
    })
  });
  const data = await response.json();
  if (!response.ok) throw new Error(data.error || data.details || `Request failed with ${response.status}`);
  return mapHybridSearchResults(data, query);
}

function mapDqlSearchResults(data, dql) {
  const mode = String(data?.mode || "dql-query");
  if (mode === "dql-hybrid" && Array.isArray(data?.hybrid?.hits)) {
    return {
      query: dql,
      mode: "dql-hybrid",
      scope: "dql",
      results: data.hybrid.hits.map((hit) => ({
        filePath: hit.path,
        canonicalPath: hit.path,
        displayName: hit.title || hit.path,
        snippet: hit.snippet || "",
        matchKindLabel: (hit.sources || []).join("+") || "hybrid",
        kindLabel: "DQL+TEXT"
      })),
      total: data.hybrid.hitCount ?? data.hybrid.hits.length,
      dqlMeta: { engine: data.engine, filterTotal: data.total }
    };
  }
  const rows = Array.isArray(data?.results) ? data.results : [];
  return {
    query: dql,
    mode: mode === "dql-group" ? "dql-group" : "dql",
    scope: "dql",
    results: rows.map((row) => {
      if (row.groupKey != null) {
        return {
          filePath: row.samplePath || "",
          displayName: `${row.groupField}=${row.groupKey}`,
          snippet: `${row.aggregate || "count"}: ${row.value} (${row.count})`,
          matchKindLabel: "group",
          kindLabel: "DQL"
        };
      }
      const name = row.fields?.["awn-name"]?.value ?? row.fields?.["awn-name"] ?? row.path;
      return {
        filePath: row.path,
        canonicalPath: row.path,
        displayName: String(name || row.path || ""),
        snippet: row.path || "",
        matchKindLabel: data.engine || "dql",
        kindLabel: "DQL"
      };
    }),
    total: data?.total ?? rows.length
  };
}

function getContentSearchDqlParams() {
  const params = {};
  const from = contentSearchDqlViewParamFrom?.value?.trim();
  const limit = contentSearchDqlViewParamLimit?.value?.trim();
  if (from) params.from = from;
  if (limit) params.limit = limit;
  return params;
}

async function fetchContentSearchDql(dql, pathPrefix = getContentSearchPathPrefix()) {
  const scope = pathPrefix ? String(pathPrefix).replace(/\\/g, "/").replace(/^\/+/, "") : "";
  const response = await fetch(buildApiUrl("/api/storage-index/query"), {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      dql,
      pathPrefix: scope || undefined,
      scopePrefix: scope || undefined,
      enforceScope: Boolean(scope),
      dqlParams: getContentSearchDqlParams(),
      limit: 100
    })
  });
  const data = await response.json();
  if (!response.ok) throw new Error(data.error || data.details || `Request failed with ${response.status}`);
  return mapDqlSearchResults(data, dql);
}

async function fetchContentSearchByFields(
  where,
  pathPrefix = getContentSearchPathPrefix(),
  limit = 30
) {
  const response = await fetch(buildApiUrl("/api/storage-index/query"), {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      where,
      pathPrefix: pathPrefix || undefined,
      limit
    })
  });
  const data = await response.json();
  if (!response.ok) throw new Error(data.error || data.details || `Request failed with ${response.status}`);
  return mapStorageFieldSearchResults(data, where);
}

async function fetchContentSearchById(query) {
  const id = parseContentSearchIdQuery(query);
  if (!id) {
    return { query, mode: "id", scope: "id", results: [], total: 0, invalidId: true };
  }
  const response = await fetch(buildApiUrl("/api/workspace-id/resolve", { id: String(id) }));
  const data = await response.json().catch(() => ({}));
  if (!response.ok) {
    throw new Error(data.error || data.details || `Request failed with ${response.status}`);
  }
  if (data.ok === false && !data.path && !(Array.isArray(data.paths) && data.paths.length)) {
    return {
      query,
      mode: "id",
      scope: "id",
      id,
      results: [],
      total: 0,
      notFound: true
    };
  }
  const paths = Array.isArray(data.paths) && data.paths.length ? data.paths : data.path ? [data.path] : [];
  return {
    query,
    mode: "id",
    scope: "id",
    id,
    duplicate: Boolean(data.duplicate) || paths.length > 1,
    results: paths.map((filePath) => {
      const normalized = String(filePath || "").replace(/\\/g, "/");
      const fileName = normalized.split("/").pop() || normalized;
      return {
        filePath: normalized,
        fileName,
        displayName: fileName.replace(/\.(sidecar\.)?md$/i, "") || `#${id}`,
        locationHint: normalized,
        pathBreadcrumb: normalized,
        snippet:
          paths.length > 1
            ? `awn-id ${id} · ${paths.length} записей с этим id`
            : `awn-id: ${id}`,
        matchKindLabel: `#${id}`,
        kindLabel: "ID",
        awnId: id
      };
    }),
    total: paths.length
  };
}

function scheduleContentSearch() {
  if (!contentSearchInputNode) return;
  const query = contentSearchInputNode.value.trim();
  const scope = getContentSearchScope();
  const fileType = getContentSearchFileType();
  const match = getContentSearchMatch();
  const fieldWhere = getContentSearchFieldFilter();
  const hasFieldFilter = Boolean(fieldWhere);
  const minLength = getContentSearchMinLength(scope);
  clearTimeout(contentSearchTimer);
  const requestId = ++contentSearchRequestId;

  const dqlText = isContentSearchDqlMode() ? getContentSearchDqlText() : "";
  if (!query && !hasFieldFilter && !dqlText) {
    setContentSearchLoading(false);
    hideContentSearchResults();
    return;
  }

  setContentSearchLoading(false);
  contentSearchTimer = setTimeout(async () => {
    if (isContentSearchDqlMode()) {
      if (!dqlText) {
        hideContentSearchResults();
        return;
      }
      setContentSearchLoading(true);
      renderContentSearchLoading();
      try {
        const data = await fetchContentSearchDql(dqlText);
        if (requestId !== contentSearchRequestId) return;
        renderContentSearchResults(data);
      } catch (error) {
        if (requestId !== contentSearchRequestId) return;
        setContentSearchLoading(false);
        contentSearchResultsNode.innerHTML = `<div class="content-search-empty">${escapeHtml(formatContentSearchPolicyError(error))}</div>`;
        contentSearchResultsNode.classList.remove("hidden");
      }
      return;
    }

    if (!hasFieldFilter && query.length < minLength) {
      renderContentSearchResults({ query, scope, fileType, match, results: [] });
      return;
    }

    setContentSearchLoading(true);
    renderContentSearchLoading();

    try {
      let data;
      if (isContentSearchIdMode()) {
        data = await fetchContentSearchById(query);
      } else if (hasFieldFilter && query.length >= 2) {
        const scopes = getContentSearchHybridScopes();
        if (!scopes.length) {
          renderContentSearchResults({
            query,
            scope,
            fileType,
            match,
            results: [],
            policyError: "Все слои hybrid-поиска отключены в settings.global.yml"
          });
          return;
        }
        data = await fetchContentSearchHybrid(query, { where: fieldWhere, scopes });
      } else if (hasFieldFilter) {
        if (contentSearchPolicyCache && !isContentSearchStorageLayerEnabled()) {
          renderContentSearchResults({
            query,
            scope,
            fileType,
            match,
            results: [],
            policyError: "Индекс полей отключён в settings.global.yml"
          });
          return;
        }
        data = await fetchContentSearchByFields(fieldWhere);
      } else if (isContentSearchSemantic()) {
        data = await fetchContentSearchSemantic(query);
      } else {
        data = await fetchContentSearch(query, scope, fileType, match);
      }
      if (requestId !== contentSearchRequestId) return;
      renderContentSearchResults(data);
    } catch (error) {
      if (requestId !== contentSearchRequestId) return;
      setContentSearchLoading(false);
      contentSearchResultsNode.innerHTML = `<div class="content-search-empty">${escapeHtml(formatContentSearchPolicyError(error))}</div>`;
      contentSearchResultsNode.classList.remove("hidden");
    }
  }, 280);
}

async function openWorkspaceSearchResultByMeta(result = {}) {
  if (!result || typeof result !== "object") return false;

  if (result.systemFile) {
    await selectSystemFile(result.systemFile, { skipRouteSync: true, edit: false });
    return true;
  }

  const nodePath = String(result.nodePath || "")
    .replace(/\\/g, "/")
    .replace(/^\/+/, "");
  if (!nodePath) return false;

  const label =
    result.label ||
    result.titleName ||
    getSearchResultTitle(result) ||
    getLabelFromPath(nodePath);
  const mode = String(result.mode || "").trim();
  const externalFile = String(result.externalFile || "")
    .replace(/\\/g, "/")
    .replace(/^\/+/, "");

  if (mode === "external" && externalFile) {
    await selectNodeManifest(getLabelFromPath(nodePath), nodePath, "external", { skipRouteSync: true });
    openExternalRecordOverviewFromNavigation({
      path: externalFile.replace(/\.md$/i, ""),
      title: externalFile.split("/").pop() || externalFile
    });
    return true;
  }

  if (mode === "media" && externalFile) {
    await selectNodeManifest(getLabelFromPath(nodePath), nodePath, "media", { skipRouteSync: true });
    if (/\.md$/i.test(externalFile)) {
      openMediaEntryOverviewFromNavigation({
        path: externalFile,
        title: externalFile.split("/").pop() || externalFile
      });
    } else {
      openMediaAsset(externalFile, nodePath);
    }
    return true;
  }

  if (mode && FLAT_STORAGE_SECTION_MODES.has(mode) && externalFile) {
    await selectNodeManifest(getLabelFromPath(nodePath), nodePath, mode, { skipRouteSync: true });
    const rel = externalFile.replace(/\.md$/i, "");
    openFlatStorageRecordOverviewFromNavigation(
      { path: rel, title: rel.split("/").pop() || rel },
      mode
    );
    return true;
  }

  if (mode === "description") {
    await openNodeFromMenu(label, nodePath, { skipRouteSync: true });
    return true;
  }

  const sidecarModes = new Set(["internal", "todo", "roadmap", "tabular", "configs", "env", "log", "node-preview"]);
  if (mode && sidecarModes.has(mode)) {
    await selectNodeManifest(label, nodePath, mode, { skipRouteSync: true });
    return true;
  }

  if (
    isNodeManifestPath(nodePath) ||
    isTopicManifestPath(nodePath) ||
    isAreaManifestFileName(nodePath.split("/").pop() || "")
  ) {
    await openNodeFromMenu(label, nodePath, { skipRouteSync: true });
    return true;
  }

  return false;
}

async function tryOpenContentSearchQueryDirect(query) {
  const normalized = String(query || "")
    .replace(/\\/g, "/")
    .trim()
    .replace(/^\/+/, "");
  if (!normalized) return false;
  const looksLikePath =
    normalized.includes("/") ||
    /\.(md|ya?ml|csv|json|txt|env|sidecar\.md)$/i.test(normalized) ||
    /^\.agent-cms\//i.test(normalized);
  if (!looksLikePath) return false;

  try {
    hideContentSearchResults();
    contentSearchInputNode?.blur();
    await openWorkspaceFilePreviewByRelPath(normalized, {
      label: getLabelFromPath(normalized)
    });
    syncAppRouteToUrl({ push: true });
    return true;
  } catch {
    return false;
  }
}

async function openWorkspaceFilePreviewByRelPath(filePath, result = {}) {
  hideHomeView();
  const normalizedPath = String(filePath || "").replace(/\\/g, "/");
  if (!normalizedPath) throw new Error("Путь к файлу пустой");

  if (
    result &&
    (result.systemFile || result.nodePath || result.externalFile || result.mode)
  ) {
    if (await openWorkspaceSearchResultByMeta(result)) return;
  }

  if (await tryOpenMarkdownLinkByWorkspaceRel(normalizedPath)) return;

  let resolved = null;
  try {
    resolved = await fetchChpuResolve(workspaceRelToChpuPath(normalizedPath));
  } catch {
    resolved = null;
  }

  if (resolved?.kind === "unknown") {
    throw new Error("Файл не найден");
  }

  if (resolved?.kind === "systemFile") {
    await selectSystemFile(resolved.systemFile, { skipRouteSync: true, edit: false });
    return;
  }

  if (resolved?.kind === "record") {
    const topicEntry = await resolveChpuTopicEntry(resolved);
    if (!topicEntry?.path) throw new Error("Тема не найдена");
    const contentMode = resolved.contentMode || getChpuMemoryKindForSlotFolder(resolved.slotFolder);
    const label = topicEntry.label || getLabelFromPath(topicEntry.path);
    await selectNodeManifest(label, topicEntry.path, contentMode, { skipRouteSync: true });
    await openEntryOverviewFromResolvedRecord(resolved, contentMode);
    return;
  }

  if (resolved?.kind === "manifest") {
    const topicEntry = await resolveChpuTopicEntry(resolved);
    if (!topicEntry?.path) throw new Error("Тема не найдена");
    await openNodeFromMenu(
      result.label || topicEntry.label || getLabelFromPath(topicEntry.path),
      topicEntry.path,
      { skipRouteSync: true }
    );
    return;
  }

  if (resolved?.kind === "file" && resolved.fileRelPath) {
    const fileRel = String(resolved.fileRelPath).replace(/\\/g, "/");
    if (isRepositoryWorkspaceRel(fileRel)) {
      await openRepositoryWorkspacePath(fileRel, { skipRouteSync: true });
      return;
    }
    if (isNodeManifestPath(fileRel) || isTopicManifestPath(fileRel)) {
      await openNodeFromMenu(getLabelFromPath(fileRel), fileRel, { skipRouteSync: true });
      return;
    }
    if (await tryOpenMarkdownLinkByWorkspaceRel(fileRel)) return;
  }

  if (result.systemFile) {
    await selectSystemFile(result.systemFile, { skipRouteSync: true, edit: false });
    return;
  }

  if (result.nodePath && result.mode === "external" && result.externalFile) {
    const label = getLabelFromPath(result.nodePath);
    await selectNodeManifest(label, result.nodePath, "external", { skipRouteSync: true });
    openExternalRecordOverviewFromNavigation({
      path: String(result.externalFile).replace(/\\/g, "/").replace(/^\/+/, "").replace(/\.md$/i, ""),
      title: String(result.externalFile).split("/").pop() || result.externalFile
    });
    return;
  }

  if (result.nodePath && result.mode === "media" && result.externalFile) {
    const label = getLabelFromPath(result.nodePath);
    await selectNodeManifest(label, result.nodePath, "media", { skipRouteSync: true });
    openMediaEntryOverviewFromNavigation({
      path: String(result.externalFile).replace(/\\/g, "/").replace(/^\/+/, ""),
      title: String(result.externalFile).split("/").pop() || result.externalFile
    });
    return;
  }

  if (result.nodePath && result.mode && FLAT_STORAGE_SECTION_MODES.has(result.mode) && result.externalFile) {
    const label = getLabelFromPath(result.nodePath);
    await selectNodeManifest(label, result.nodePath, result.mode, { skipRouteSync: true });
    const rel = String(result.externalFile).replace(/\\/g, "/").replace(/^\/+/, "");
    openFlatStorageRecordOverviewFromNavigation(
      { path: rel.replace(/\.md$/i, ""), title: rel.split("/").pop() || rel },
      result.mode
    );
    return;
  }

  if (result.nodePath && normalizedPath === String(result.nodePath).replace(/\\/g, "/")) {
    await openNodeFromMenu(getLabelFromPath(result.nodePath), result.nodePath, { skipRouteSync: true });
    return;
  }

  if (result.nodePath && isNodeManifestPath(normalizedPath)) {
    await openNodeFromMenu(getLabelFromPath(result.nodePath), result.nodePath, { skipRouteSync: true });
    return;
  }

  if (resolved) {
    await applyChpuResolvedRoute(resolved);
    return;
  }

  throw new Error("Не удалось открыть файл");
}

async function openContentSearchResult(result, { agentId = null } = {}) {
  if (!result) return;

  if (agentId && agentId !== activeWorkspaceId) {
    await switchActiveAgent(agentId);
  }

  hideContentSearchResults();
  hideLandingSearchResults();
  contentSearchInputNode?.blur();
  appLandingSearchInputNode?.blur();

  if (result.systemFile) {
    await selectSystemFile(result.systemFile, { edit: false });
    syncAppRouteToUrl({ push: true });
    return;
  }

  const filePath = String(result.filePath || result.canonicalPath || result.nodePath || "").replace(
    /\\/g,
    "/"
  );
  if (!filePath && !result.systemFile) return;

  try {
    await openWorkspaceFilePreviewByRelPath(filePath, {
      ...result,
      label: getSearchResultTitle(result)
    });
    scrollToSearchResultLine(result.startLine);
    syncAppRouteToUrl({ push: true });
  } catch (error) {
    showToast(`Не удалось открыть файл: ${error.message}`, "error");
  }
}

function getLandingSearchScope() {
  const scope = appLandingSearchScopeNode?.value || "all";
  if (scope === "filename" || scope === "content" || scope === "all") return scope;
  return "all";
}

function getLandingSearchMinLength(scope = getLandingSearchScope()) {
  return scope === "filename" || scope === "all" ? 1 : 2;
}

function updateLandingSearchPlaceholder() {
  if (!appLandingSearchInputNode) return;
  const scope = getLandingSearchScope();
  if (scope === "filename") {
    appLandingSearchInputNode.placeholder = "Поиск по имени файла...";
    return;
  }
  if (scope === "content") {
    appLandingSearchInputNode.placeholder = "Поиск по тексту внутри файлов...";
    return;
  }
  if (scope === "tags") {
    appLandingSearchInputNode.placeholder = "Поиск по тэгам...";
    return;
  }
  appLandingSearchInputNode.placeholder = "Найти файл или текст...";
}

function hideLandingSearchResults() {
  setLandingSearchLoading(false);
  appLandingSearchResultsNode?.classList.add("hidden");
  appLandingSearchInputNode?.setAttribute("aria-expanded", "false");
}

function readLandingSearchSelectedAgentIdsFromStorage(allIds) {
  try {
    const raw = localStorage.getItem(LANDING_SEARCH_AGENTS_KEY);
    if (!raw) return null;
    const saved = JSON.parse(raw);
    if (!Array.isArray(saved)) return null;
    return allIds.filter((id) => saved.includes(id));
  } catch {
    return null;
  }
}

function getLandingSearchSelectedAgentIds() {
  const agents = getAgentsForLandingGrid();
  const allIds = agents.map((agent) => agent.id);
  const fromStorage = readLandingSearchSelectedAgentIdsFromStorage(allIds);
  if (fromStorage !== null) return fromStorage;
  return agents.filter(isAgentRegistryActive).map((agent) => agent.id);
}

function saveLandingSearchSelectedAgentIds(ids) {
  localStorage.setItem(LANDING_SEARCH_AGENTS_KEY, JSON.stringify(ids));
}

function setLandingSearchAgentsPanelOpen(open) {
  if (!appLandingSearchAgentsPanelNode || !appLandingSearchAgentsBtnNode) return;
  appLandingSearchAgentsPanelNode.classList.toggle("hidden", !open);
  appLandingSearchAgentsBtnNode.setAttribute("aria-expanded", open ? "true" : "false");
  appLandingSearchAgentsBtnNode.classList.toggle("is-open", open);
}

function updateLandingSearchAgentsSummary() {
  if (!appLandingSearchAgentsSummaryNode) return;
  const agents = getAgentsForLandingGrid();
  const selected = getLandingSearchSelectedAgentIds();
  if (agents.length === 0) {
    appLandingSearchAgentsSummaryNode.textContent = "Нет агентов";
    return;
  }
  if (selected.length === 0) {
    appLandingSearchAgentsSummaryNode.textContent = "Выберите…";
    return;
  }
  if (selected.length === agents.length) {
    appLandingSearchAgentsSummaryNode.textContent = "Все агенты";
    return;
  }
  if (selected.length === 1) {
    const agent = agents.find((item) => item.id === selected[0]);
    appLandingSearchAgentsSummaryNode.textContent = agent?.name || selected[0];
    return;
  }
  appLandingSearchAgentsSummaryNode.textContent = `${selected.length} из ${agents.length}`;
}

function setLandingSearchAgentSelection(ids) {
  saveLandingSearchSelectedAgentIds(ids);
  renderLandingSearchAgents();
  updateLandingSearchAgentsSummary();
  scheduleLandingSearch();
}

function renderLandingSearchAgents() {
  if (!appLandingSearchAgentsNode) return;
  appLandingSearchAgentsNode.replaceChildren();

  const agents = getAgentsForLandingGrid();
  if (agents.length === 0) {
    const empty = document.createElement("p");
    empty.className = "app-landing-search-empty-agents";
    empty.textContent = "Нет агентов в реестре";
    appLandingSearchAgentsNode.appendChild(empty);
    updateLandingSearchAgentsSummary();
    return;
  }

  const selected = new Set(getLandingSearchSelectedAgentIds());

  for (const agent of agents) {
    const registryActive = isAgentRegistryActive(agent);
    const label = document.createElement("label");
    label.className = `app-landing-search-agent-option${registryActive ? "" : " is-inactive"}`;
    label.title = registryActive ? agent.path || agent.id : "Агент выключен в реестре";

    const checkbox = document.createElement("input");
    checkbox.type = "checkbox";
    checkbox.checked = selected.has(agent.id);
    checkbox.addEventListener("change", () => {
      const next = new Set(getLandingSearchSelectedAgentIds());
      if (checkbox.checked) next.add(agent.id);
      else next.delete(agent.id);
      saveLandingSearchSelectedAgentIds([...next]);
      updateLandingSearchAgentsSummary();
      scheduleLandingSearch();
    });

    const copy = document.createElement("span");
    copy.className = "app-landing-search-agent-option-copy";

    const nameNode = document.createElement("span");
    nameNode.className = "app-landing-search-agent-name";
    nameNode.textContent = agent.name || agent.id;
    copy.appendChild(nameNode);

    if (agent.id !== (agent.name || "")) {
      const idNode = document.createElement("span");
      idNode.className = "app-landing-search-agent-id";
      idNode.textContent = agent.id;
      copy.appendChild(idNode);
    }

    label.appendChild(checkbox);
    label.appendChild(copy);
    appLandingSearchAgentsNode.appendChild(label);
  }

  updateLandingSearchAgentsSummary();
}

function renderLandingSearchResults(data) {
  if (!appLandingSearchResultsNode) return;
  setLandingSearchLoading(false);
  const query = data?.query || "";
  const scope = data?.scope || getLandingSearchScope();
  const results = Array.isArray(data?.results) ? data.results : [];
  const minLength = getLandingSearchMinLength(scope);
  const selectedCount = getLandingSearchSelectedAgentIds().length;

  appLandingSearchResultsNode.innerHTML = "";

  if (selectedCount === 0) {
    appLandingSearchResultsNode.innerHTML =
      `<div class="content-search-hint">Выберите хотя бы одного агента</div>`;
    appLandingSearchResultsNode.classList.remove("hidden");
    appLandingSearchInputNode?.setAttribute("aria-expanded", "true");
    return;
  }

  if (query.length < minLength) {
    const hint =
      minLength === 1 ? "Введите текст для поиска" : "Введите минимум 2 символа";
    appLandingSearchResultsNode.innerHTML = `<div class="content-search-hint">${hint}</div>`;
    appLandingSearchResultsNode.classList.remove("hidden");
    appLandingSearchInputNode?.setAttribute("aria-expanded", "true");
    return;
  }

  if (results.length === 0) {
    appLandingSearchResultsNode.innerHTML = `<div class="content-search-empty">Ничего не найдено</div>`;
    appLandingSearchResultsNode.classList.remove("hidden");
    appLandingSearchInputNode?.setAttribute("aria-expanded", "true");
    return;
  }

  for (const item of results) {
    const btn = buildContentSearchResultItem(item, query, { showAgent: true, showFileType: true });
    btn.addEventListener("click", () => {
      void openContentSearchResult(item, { agentId: item.agentId });
    });
    appLandingSearchResultsNode.appendChild(btn);
  }

  appLandingSearchResultsNode.classList.remove("hidden");
  appLandingSearchInputNode?.setAttribute("aria-expanded", "true");
}

async function fetchLandingGlobalSearch(query, scope = getLandingSearchScope()) {
  const agentIds = getLandingSearchSelectedAgentIds();
  const params = { q: query, scope, limit: 50 };
  if (agentIds.length) params.agents = agentIds.join(",");
  const response = await fetch(buildApiUrl("/api/search/global", params));
  if (!response.ok) throw new Error(`Request failed with ${response.status}`);
  return response.json();
}

function isLandingSearchEnabled() {
  return LANDING_SEARCH_ENABLED && !appLandingSearchInputNode?.disabled;
}

function scheduleLandingSearch() {
  if (!isLandingSearchEnabled() || !appLandingSearchInputNode) return;
  const query = appLandingSearchInputNode.value.trim();
  const scope = getLandingSearchScope();
  const minLength = getLandingSearchMinLength(scope);
  clearTimeout(landingSearchTimer);
  const requestId = ++landingSearchRequestId;

  if (!query) {
    setLandingSearchLoading(false);
    hideLandingSearchResults();
    return;
  }

  setLandingSearchLoading(false);
  landingSearchTimer = setTimeout(async () => {
    if (query.length < minLength || getLandingSearchSelectedAgentIds().length === 0) {
      renderLandingSearchResults({ query, scope, results: [] });
      return;
    }

    setLandingSearchLoading(true);
    renderLandingSearchLoading();

    try {
      const data = await fetchLandingGlobalSearch(query, scope);
      if (requestId !== landingSearchRequestId) return;
      renderLandingSearchResults(data);
    } catch {
      if (requestId !== landingSearchRequestId) return;
      setLandingSearchLoading(false);
      appLandingSearchResultsNode.innerHTML = `<div class="content-search-empty">Ошибка поиска</div>`;
      appLandingSearchResultsNode.classList.remove("hidden");
    }
  }, 280);
}

function showToast(message, type = "", duration = 1600) {
  toastNode.textContent = message;
  toastNode.classList.toggle("is-multiline", String(message || "").includes("\n"));
  toastNode.classList.remove("success", "error", "show");
  if (type) toastNode.classList.add(type);
  if (toastTimer) clearTimeout(toastTimer);
  toastNode.classList.add("show");
  toastTimer = setTimeout(() => {
    toastNode.classList.remove("show");
  }, Math.max(1200, Number(duration) || 1600));
}

function askConfirm(message, { okLabel = "Удалить", cancelLabel = "Отмена", title = "", hint = "", icon = "⚠️", variant = "danger" } = {}) {
  if (confirmTitleNode) confirmTitleNode.textContent = title || "Подтверждение";
  if (confirmMessageNode) {
    confirmMessageNode.textContent = message;
    confirmMessageNode.classList.toggle("is-preformatted", String(message || "").includes("\n"));
  }
  confirmCancelBtn.classList.remove("hidden");
  if (confirmHintNode) {
    confirmHintNode.textContent = hint;
    confirmHintNode.classList.toggle("hidden", !hint);
  }
  if (confirmIconNode) confirmIconNode.textContent = icon;
  confirmOkBtn.textContent = okLabel;
  confirmCancelBtn.textContent = cancelLabel;
  if (confirmModalCardNode) {
    confirmModalCardNode.classList.remove("is-danger", "is-warning", "is-info");
    confirmModalCardNode.classList.add(`is-${variant}`);
  }
  confirmModalNode.classList.remove("hidden");
  return new Promise((resolve) => {
    pendingConfirmResolve = resolve;
  });
}

function showAlertDialog(message, { title = "Сообщение", hint = "", okLabel = "Закрыть", icon = "ℹ️", variant = "info" } = {}) {
  if (confirmTitleNode) confirmTitleNode.textContent = title;
  if (confirmMessageNode) {
    confirmMessageNode.textContent = message;
    confirmMessageNode.classList.toggle("is-preformatted", String(message || "").includes("\n"));
  }
  if (confirmHintNode) {
    confirmHintNode.textContent = hint;
    confirmHintNode.classList.toggle("hidden", !hint);
  }
  if (confirmIconNode) confirmIconNode.textContent = icon;
  confirmOkBtn.textContent = okLabel;
  confirmCancelBtn.classList.add("hidden");
  if (confirmModalCardNode) {
    confirmModalCardNode.classList.remove("is-danger", "is-warning", "is-info");
    confirmModalCardNode.classList.add(`is-${variant}`);
  }
  confirmModalNode.classList.remove("hidden");
  return new Promise((resolve) => {
    pendingConfirmResolve = () => resolve(true);
  });
}

function closeConfirm(result) {
  confirmModalNode.classList.add("hidden");
  confirmOkBtn.textContent = "Удалить";
  confirmCancelBtn.textContent = "Отмена";
  confirmCancelBtn.classList.remove("hidden");
  if (confirmMessageNode) confirmMessageNode.classList.remove("is-preformatted");
  if (confirmTitleNode) confirmTitleNode.textContent = "Подтверждение";
  if (confirmHintNode) {
    confirmHintNode.textContent = "";
    confirmHintNode.classList.add("hidden");
  }
  if (confirmIconNode) confirmIconNode.textContent = "⚠️";
  if (confirmModalCardNode) {
    confirmModalCardNode.classList.remove("is-warning", "is-info");
    confirmModalCardNode.classList.add("is-danger");
  }
  if (pendingConfirmResolve) {
    pendingConfirmResolve(result);
    pendingConfirmResolve = null;
  }
}

function formatCreateParentLabel(parentPath) {
  if (!parentPath || parentPath === ".") return getAgentTreeTitle();
  const parts = String(parentPath).split("/").filter(Boolean);
  return parts[parts.length - 1] || parentPath;
}

function resolveCreateTargetParentPath(baseParentPath, agentId = getCreateModalAgentId()) {
  const normalized = normalizeCreateParentPath(baseParentPath || ".");
  if (isServiceNodePath(normalized)) return normalized;
  if (isAgentContainerNodePath(normalized)) return normalized;
  if (!shouldUseContainerCreateTarget(agentId)) return normalized;

  const gitRoot = getGitRepoRootForMenuPath(normalized, agentId);
  const effectiveGitRoot = gitRoot ?? (normalized === "." ? "." : null);
  if (effectiveGitRoot !== null && hasContainerForGitRoot(effectiveGitRoot, agentId)) {
    const containerRel = getNestedContainerRelForGitRoot(effectiveGitRoot, agentId);
    if (containerRel && !isMenuPathInsideGitRepoContainer(normalized, effectiveGitRoot, agentId)) {
      if (normalized === effectiveGitRoot || (effectiveGitRoot === "." && normalized === ".")) {
        return containerRel;
      }
      if (effectiveGitRoot !== "." && normalized.startsWith(`${effectiveGitRoot}/`)) {
        const containerFolder = getActiveAgentContainerFolder(agentId);
        const tail = normalized.slice(effectiveGitRoot.length + 1);
        if (tail && tail !== containerFolder && !tail.startsWith(`${containerFolder}/`)) {
          return `${containerRel}/${tail}`.replace(/\\/g, "/");
        }
      }
    }
  }

  return normalized;
}

function isMenuRenderInServiceTree(parentEl) {
  return Boolean(
    parentEl?.closest?.(".menu-service-section, .menu-shared-section, .menu-container-section")
  );
}

function resolveServiceTreeFolderPath(folderPath, agentId = activeWorkspaceId) {
  const raw = String(folderPath || "").replace(/\\/g, "/").trim();
  if (!raw || raw === ".") return ".";
  if (isServiceNodePath(raw)) return raw;
  const serviceFolder = getActiveAgentKitFolder(agentId);
  if (!serviceFolder) return raw;
  return `${serviceFolder}/${raw}`.replace(/\/+/g, "/");
}

function resolveContainerTreeFolderPath(folderPath, agentId = activeWorkspaceId) {
  const raw = String(folderPath || "").replace(/\\/g, "/").trim();
  if (!raw || raw === ".") return ".";
  if (isAgentContainerNodePath(raw)) return raw;
  const containerFolder = getActiveAgentContainerFolder(agentId);
  if (!containerFolder) return raw;
  const segments = raw.split("/").filter(Boolean);
  if (segments.includes(containerFolder)) return raw;
  return `${containerFolder}/${raw}`.replace(/\/+/g, "/");
}

function resolveSharedTreeFolderPath(folderPath, agentId = activeWorkspaceId) {
  const raw = String(folderPath || "").replace(/\\/g, "/").trim();
  if (!raw || raw === ".") return ".";
  if (isAgentSharedNodePath(raw)) return raw;
  const sharedFolder = getActiveAgentSharedFolder(agentId);
  if (!sharedFolder) return raw;
  return `${sharedFolder}/${raw}`.replace(/\/+/g, "/");
}

function getCreateFolderParentPath(folderPath) {
  const normalized = normalizeCreateParentPath(folderPath || ".");
  if (!normalized || normalized === ".") return ".";
  const parts = normalized.split("/").filter(Boolean);
  if (parts.length <= 1) return ".";
  return parts.slice(0, -1).join("/");
}

const ADOPT_REQUIRES_AREA_PARENT_MESSAGE =
  "Подхват возможен только если непосредственный родитель — область с manifest.md (тип «область»).";

const ADOPT_TOPIC_HAS_SUBFOLDERS_MESSAGE =
  "Папку с вложенными подпапками нельзя подхватить как тему — используйте «Подхватить (область)» или уберите вложенные папки.";

function resolveAdoptValidationFolderPath(folderPath, agentId = getCreateModalAgentId()) {
  let normalized = normalizeCreateParentPath(folderPath || ".");
  if (!normalized || normalized === ".") return normalized;
  if (getMenuTreeNodeByFolderPath(normalized, agentId)) return normalized;

  const kit = getActiveAgentKitFolder(agentId);
  if (kit && normalized !== kit && !normalized.startsWith(`${kit}/`)) {
    const prefixed = normalizeCreateParentPath(resolveServiceTreeFolderPath(normalized, agentId));
    if (getMenuTreeNodeByFolderPath(prefixed, agentId)) return prefixed;
    normalized = prefixed;
  }

  const container = getActiveAgentContainerFolder(agentId);
  if (container && normalized !== container && !normalized.startsWith(`${container}/`)) {
    const segments = normalized.split("/").filter(Boolean);
    if (!segments.includes(container)) {
      const prefixed = normalizeCreateParentPath(resolveContainerTreeFolderPath(normalized, agentId));
      if (getMenuTreeNodeByFolderPath(prefixed, agentId)) return prefixed;
    }
  }

  return normalized;
}

function folderPathLooksLikeAreaTreeNode(folderPath, agentId = getCreateModalAgentId()) {
  const normalized = normalizeCreateParentPath(folderPath || ".");
  if (!normalized || normalized === ".") return false;
  const node = getMenuTreeNodeByFolderPath(normalized, agentId);
  if (node?.indexPath) {
    const indexPath = normalizeMenuNodePath(node.indexPath);
    if (isTopicManifestPath(indexPath)) return false;
    if (isAreaNodePath(indexPath)) return true;
  }
  if (node?.awnTreeType) {
    const declared = normalizeDeclaredManifestTreeType(node.awnTreeType);
    if (declared === "topic") return false;
    if (declared === "area" || declared === "workspace") return true;
  }
  const manifestRel = `${normalized}/${AREA_MANIFEST_FILE}`.replace(/\\/g, "/");
  if (isTopicManifestPath(manifestRel)) return false;
  return isAreaNodePath(manifestRel);
}

function isCreateAdoptParentArea(folderPath, agentId = getCreateModalAgentId()) {
  const folder = resolveAdoptValidationFolderPath(folderPath, agentId);
  const parent = getCreateFolderParentPath(folder);
  if (!parent || parent === ".") return false;
  const parentResolved = resolveAdoptValidationFolderPath(parent, agentId);
  return folderPathLooksLikeAreaTreeNode(parentResolved, agentId);
}

function validateCreateAdoptType(type, folderPath, agentId = getCreateModalAgentId()) {
  if (type !== "manifest" && type !== "topic-manifest") return null;
  if (!isCreateAdoptParentArea(folderPath, agentId)) {
    return ADOPT_REQUIRES_AREA_PARENT_MESSAGE;
  }
  return null;
}

async function adoptTargetFolderHasSubfolders(folderPath, agentId = activeWorkspaceId) {
  const normalized = resolveAdoptValidationFolderPath(folderPath, agentId);
  if (!normalized || normalized === ".") return false;
  try {
    const response = await fetch(
      buildApiUrl("/api/workspace/folder/browse", { folderPath: normalized }, agentId)
    );
    if (!response.ok) return false;
    const data = await response.json();
    return (data.folders?.length ?? 0) > 0;
  } catch {
    return false;
  }
}

function shouldOfferAreaAdopt(node, agentId = activeWorkspaceId) {
  if (!node || node.indexPath) return false;
  const folderPath = String(node.folderPath || "").trim();
  if (!folderPath) return false;
  if (isPlatformDataMenuFolderPath(folderPath)) return false;
  return true;
}

function resolveCreateModalParentPath(parentPath, options = {}) {
  const agentId = options.agentId || getCreateModalAgentId();
  const raw = String(options.folderPath || parentPath || ".").trim();
  if (options.inContainerTree || options.menuParentEl?.closest?.(".menu-container-section")) {
    return normalizeCreateParentPath(resolveContainerTreeFolderPath(raw, agentId));
  }
  if (options.inSharedTree || options.menuParentEl?.closest?.(".menu-shared-section")) {
    return normalizeCreateParentPath(resolveSharedTreeFolderPath(raw, agentId));
  }
  if (options.inServiceTree || options.menuParentEl?.closest?.(".menu-service-section")) {
    return normalizeCreateParentPath(resolveServiceTreeFolderPath(raw, agentId));
  }
  return normalizeCreateParentPath(raw);
}

function getMenuTreeNodeByFolderPath(folderPath, agentId = getCreateModalAgentId()) {
  const menu = menuCacheByAgent.get(agentId) || (agentId === activeWorkspaceId ? currentMenuData : null);
  if (!menu) return null;
  const normalized = normalizeCreateParentPath(folderPath || ".");
  if (normalized === ".") {
    return {
      hasGitSelf: Boolean(menu.hasGitSelf),
      hasObsidianSelf: Boolean(menu.hasObsidianSelf),
      hasAgentSelf: Boolean(menu.hasAgentSelf),
      hasGit: Boolean(menu.hasGitSelf),
      hasObsidian: Boolean(menu.hasObsidianSelf),
      hasAgent: Boolean(menu.hasAgentSelf)
    };
  }

  const menuRoot = { title: getAgentTreeTitle(agentId), ...menu };
  let hit = findMenuTreeNodeByFolderPath(menuRoot, normalized, ".", 0);
  if (hit?.node) return hit.node;

  if (menu.serviceTree) {
    hit = findMenuTreeNodeByFolderPath({ title: "", ...menu.serviceTree }, normalized, ".", 0);
    if (hit?.node) return hit.node;
  }

  if (menu.containerTree) {
    hit = findMenuTreeNodeByFolderPath({ title: "", ...menu.containerTree }, normalized, ".", 0);
    if (hit?.node) return hit.node;
  }

  if (menu.sharedTree) {
    hit = findMenuTreeNodeByFolderPath({ title: "", ...menu.sharedTree }, normalized, ".", 0);
    if (hit?.node) return hit.node;
  }

  return null;
}

function hasNestedContainerInFolder(folderPath, agentId = activeWorkspaceId) {
  const normalized = normalizeCreateParentPath(folderPath || ".");
  if (!normalized || normalized === ".") {
    return isAgentContainerFolderPresent(agentId);
  }
  const node = getMenuTreeNodeByFolderPath(normalized, agentId);
  return Boolean(node?.containerTree);
}

function getNestedContainerManifestPathForFolder(folderPath, agentId = activeWorkspaceId) {
  if (!hasNestedContainerInFolder(folderPath, agentId)) return null;
  const normalized = normalizeCreateParentPath(folderPath || ".");
  const node = getMenuTreeNodeByFolderPath(normalized, agentId);
  const manifestPath = node?.containerTree?.indexPath;
  if (manifestPath) return normalizeMenuNodePath(manifestPath);
  const containerRel = getNestedContainerRelForGitRoot(normalized === "." ? "." : normalized, agentId);
  return containerRel ? `${containerRel}/${AREA_MANIFEST_FILE}`.replace(/\\/g, "/") : null;
}

function isGitRepoMenuFolder(folderPath, agentId = getCreateModalAgentId()) {
  return Boolean(getMenuTreeNodeByFolderPath(folderPath, agentId)?.hasGitSelf);
}

function getGitRepoRootForMenuPath(folderPath, agentId = getCreateModalAgentId()) {
  const normalized = normalizeCreateParentPath(folderPath || ".");
  const parts = normalized === "." ? [] : normalized.split("/").filter(Boolean);
  for (let len = parts.length; len >= 0; len -= 1) {
    const prefix = len === 0 ? "." : parts.slice(0, len).join("/");
    const node = getMenuTreeNodeByFolderPath(prefix, agentId);
    if (node?.hasGitSelf) return prefix;
  }
  return null;
}

function isGitRepoLooseFilePath(nodePath, agentId = activeWorkspaceId) {
  const normalized = normalizeMenuNodePath(nodePath);
  if (!normalized) return false;
  const base = normalized.split("/").filter(Boolean).pop() || "";
  if (isAreaManifestFileName(base)) return false;
  if (base.toLowerCase() === "sort.json") return false;
  if (isReadStateServiceFileName(base)) return false;
  const parentFolder = normalized.includes("/")
    ? normalized.slice(0, normalized.lastIndexOf("/"))
    : ".";
  if (!parentFolder || parentFolder === ".") return false;
  return isGitRepoMenuFolder(parentFolder, agentId);
}

function isGitRepoLooseMdPath(nodePath, agentId = activeWorkspaceId) {
  const normalized = normalizeMenuNodePath(nodePath);
  if (!normalized || !/\.md$/i.test(normalized)) return false;
  return isGitRepoLooseFilePath(normalized, agentId);
}

function isGitRepoLooseMdEditing() {
  return isGitRepoLooseMdPath(activePath);
}

function isPlainServiceStyleOpen() {
  if (activeSystemFile) return true;
  if (activeWorkspaceTocRelPath) return true;
  if (isAgentSystemFileEditing()) return true;
  return isGitRepoLooseFilePath(activePath) && !isGitRepoLooseMdEditing();
}

function isServiceStyleContentOpen() {
  return Boolean(activeSystemFile) || isGitRepoLooseFilePath(activePath) || isAgentSystemFileEditing();
}

function getServiceStyleContentLabel() {
  if (activeSystemFile) return activeSystemFile;
  if (activeWorkspaceTocRelPath) return activeWorkspaceTocRelPath;
  if (isAgentSystemFileEditing()) {
    return activePath.split("/").filter(Boolean).pop() || activePath;
  }
  if (isGitRepoLooseFilePath(activePath)) {
    return activePath.split("/").filter(Boolean).pop() || activePath;
  }
  return "";
}

function getNestedContainerRelForGitRoot(gitRootRel, agentId = getCreateModalAgentId()) {
  const containerFolder = getActiveAgentContainerFolder(agentId);
  if (!containerFolder) return null;
  if (!gitRootRel || gitRootRel === ".") return containerFolder;
  return `${gitRootRel}/${containerFolder}`.replace(/\\/g, "/");
}

function hasContainerForGitRoot(gitRootRel, agentId = getCreateModalAgentId()) {
  if (!gitRootRel || gitRootRel === ".") {
    return isAgentContainerFolderPresent(agentId);
  }
  const node = getMenuTreeNodeByFolderPath(gitRootRel, agentId);
  return Boolean(node?.containerTree);
}

function isMenuPathInsideGitRepoContainer(relPath, gitRepoRootRel = ".", agentId = getCreateModalAgentId()) {
  const containerFolder = getActiveAgentContainerFolder(agentId);
  if (!containerFolder) return false;
  const normalized = normalizeCreateParentPath(relPath || ".");
  const gitRoot =
    gitRepoRootRel === "."
      ? ""
      : String(gitRepoRootRel || "")
          .replace(/\\/g, "/")
          .replace(/\/$/, "");

  if (!gitRoot) {
    return normalized === containerFolder || normalized.startsWith(`${containerFolder}/`);
  }
  if (normalized === gitRoot) return false;
  if (normalized === `${gitRoot}/${containerFolder}`) return true;
  return normalized.startsWith(`${gitRoot}/${containerFolder}/`);
}

