function getDefaultSystemFileScaffoldContent(name) {
  const normalized = normalizeSystemFileName(name);
  const fromStore = systemFileTemplatesByTarget[normalized];
  if (fromStore?.body) {
    return fromStore.body;
  }
  if (normalized === "AGENTS.md") {
    return "# Agent\n\n> Инструкции для LLM-агента.\n";
  }
  if (normalized === "AUTH.md") {
    return "# AUTH\n\n> Доступы, права и аутентификация workspace.\n";
  }
  if (normalized === "BOOTSTRAP.md") {
    return "# Bootstrap\n\n> Первичная настройка и загрузка workspace.\n";
  }
  if (normalized === "ONBOARDING.md") {
    return "# Onboarding\n\n> Первое знакомство с workspace: кто вы, кто агент, с чего начать.\n";
  }
  if (normalized === "SKILL.md") {
    return RECOMMENDED_SKILL_MD_TEMPLATE;
  }
  if (normalized === ROOT_SYSTEM_NOTE_FILE) {
    return "# NOTE\n\n> Быстрая заметка workspace.\n\n";
  }
  if (normalized === ROOT_SYSTEM_TODO_FILE) {
    return "# TODO\n\n- [ ] \n";
  }
  if (normalized === "README.md") {
    return "# README\n\n> Описание workspace.\n";
  }
  return "";
}

