function toggleFolderCollapsed(folderPath, agentId = activeWorkspaceId) {
  const normalizedPath = normalizeFolderPath(folderPath);
  if (!normalizedPath || normalizedPath === ".") return;
  const collapsedFolders = getAgentCollapsedFolders(agentId);
  if (collapsedFolders.has(normalizedPath)) {
    void expandMenuFolderWithLazyLoad(normalizedPath, agentId);
    return;
  }
  collapsedFolders.add(normalizedPath);
  saveCollapsedFoldersByAgent();
  applyMenuFolderCollapsedUi(normalizedPath, agentId);
}

function applyMenuFolderCollapsedUi(normalizedPath, agentId = activeWorkspaceId, options = {}) {
  const menu = menuCacheByAgent.get(agentId) || (agentId === activeWorkspaceId ? currentMenuData : null);
  const patched = menu
    ? withPreservedMenuTreePreviews(agentId, () =>
        withPreservedMenuScroll(() => patchFolderCollapsedState(normalizedPath, agentId, options))
      )
    : false;
  if (!patched && menu) {
    withPreservedMenuScroll(() => renderMenu(menu, agentId, { menuOnly: true }));
  }
  if (agentId === activeWorkspaceId) {
    updateActiveButton();
    syncMenuCollapseAllButton();
  }
}

async function expandMenuFolderWithLazyLoad(folderPath, agentId = activeWorkspaceId) {
  const normalizedPath = normalizeFolderPath(folderPath);
  if (!normalizedPath || normalizedPath === ".") return;
  try {
    await ensureMenuBranchLoaded(normalizedPath, agentId);
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    showToast(`Не удалось загрузить ветку: ${message}`, "error");
    return;
  }
  const collapsedFolders = getAgentCollapsedFolders(agentId);
  collapsedFolders.delete(normalizedPath);
  saveCollapsedFoldersByAgent();

  const menu = menuCacheByAgent.get(agentId) || (agentId === activeWorkspaceId ? currentMenuData : null);
  const patched = menu
    ? withPreservedMenuTreePreviews(agentId, () =>
        withPreservedMenuScroll(() => {
          if (patchFolderCollapsedState(normalizedPath, agentId, { forceRebuild: true })) {
            const sectionEl = findMenuSectionByFolderPath(normalizedPath, agentId);
            const childrenNode = sectionEl?.querySelector(":scope > .tree-children");
            if (menuTreeChildrenNodeHasRenderedContent(childrenNode)) return true;
          }
          return patchMenuTreeAtFolder(normalizedPath, agentId);
        })
      )
    : false;

  if (!patched && menu) {
    withPreservedMenuScroll(() => renderMenu(menu, agentId, { menuOnly: true }));
  }

  if (agentId === activeWorkspaceId) {
    updateActiveButton();
    syncMenuCollapseAllButton();
  }
}

function getMenuBranchLoadInFlight(agentId = activeWorkspaceId) {
  let map = menuBranchLoadInFlightByAgent.get(agentId);
  if (!map) {
    map = new Map();
    menuBranchLoadInFlightByAgent.set(agentId, map);
  }
  return map;
}

function isMenuFolderLazyExpandable(node) {
  return Boolean(node?.menuDepthLimited);
}

function getMenuFolderExpandMeta(
  node,
  agentId = activeWorkspaceId,
  parentSectionPath = ".",
  depth = 0,
  sectionFolderPath = null
) {
  const folderPath = sectionFolderPath ?? resolveSectionFolderPath(node, parentSectionPath, depth);
  const visibleChildren = getVisibleMenuChildren(node, agentId, parentSectionPath, depth);
  const repoServiceItems = filterRepoServiceItemsForMenuSection(getMenuRepoServiceItems(node), folderPath);
  const isGitRepoMenuNode = Boolean(node.hasGitSelf && depth > 0);
  const nestedContainerTree =
    !isGitRepoMenuNode && depth > 0 && node.containerTree ? node.containerTree : null;
  const nestedContainerPrefix = nestedContainerTree
    ? `${folderPath}/${getActiveAgentContainerFolder(agentId)}`.replace(/\/+/g, "/")
    : "";
  const nestedContainerChildren = nestedContainerTree
    ? getVisibleMenuChildren({ title: "", ...nestedContainerTree }, agentId, nestedContainerPrefix, depth + 1)
    : [];
  const hasNestedContainer = nestedContainerChildren.length > 0;
  const hasNonContainer = visibleChildren.length > 0;
  const hasRepoService = repoServiceItems.length > 0;
  const depthLimited = Boolean(node.menuDepthLimited) || isMenuTreeDepthAtLimit(depth, agentId);
  const lazyExpandable = isMenuFolderLazyExpandable(node);
  const canExpandChildren =
    lazyExpandable || (!depthLimited && !isMenuTreeDepthAtLimit(depth + 1, agentId));
  const hasActualChildren = hasNestedContainer || hasNonContainer || hasRepoService;
  const hasContent = isGitRepoMenuNode
    ? getGitRepoMenuHasContent(node, agentId, folderPath, depth)
    : lazyExpandable
      ? true
      : canExpandChildren && hasActualChildren;

  return {
    sectionFolderPath: folderPath,
    visibleChildren,
    repoServiceItems,
    isGitRepoMenuNode,
    nestedContainerTree,
    nestedContainerPrefix,
    nestedContainerChildren,
    hasNestedContainer,
    hasNonContainer,
    hasRepoService,
    canExpandChildren,
    hasContent
  };
}

function setMenuBranchLoading(folderPath, agentId = activeWorkspaceId, isLoading = false) {
  const normalized = normalizeMenuPatchFolderPath(folderPath, agentId);
  const section = findMenuSectionByFolderPath(normalized, agentId);
  if (!section) return;
  section.classList.toggle("is-menu-branch-loading", isLoading);
  const toggleBtn = section.querySelector(".folder-toggle-btn");
  if (toggleBtn) toggleBtn.disabled = isLoading;
}

function findMenuBranchNodeByFolderPath(menu, folderPath, agentId = activeWorkspaceId) {
  const target = normalizeMenuPatchFolderPath(folderPath, agentId);
  if (!menu || !target || target === ".") return null;
  const hit = findMenuTreeNodeByFolderPath(
    { title: getAgentTreeTitle(agentId), ...menu },
    target,
    ".",
    0
  );
  return hit?.node ?? null;
}

function applyMenuBranchPayload(menu, folderPath, branchPayload, agentId = activeWorkspaceId) {
  const normalized = normalizeMenuPatchFolderPath(folderPath, agentId);
  const node = findMenuBranchNodeByFolderPath(menu, normalized, agentId);
  if (!node || !branchPayload) return false;
  const preserved = {
    title: branchPayload.title || node.title,
    folderPath: node.folderPath || normalized,
    status: branchPayload.status ?? node.status ?? null,
    color: branchPayload.color ?? node.color ?? null,
    tags: branchPayload.tags ?? node.tags ?? [],
    category: branchPayload.category ?? node.category ?? null,
    hasPreview: branchPayload.hasPreview ?? node.hasPreview ?? false,
    previewUrl: branchPayload.previewUrl ?? node.previewUrl ?? null
  };
  Object.assign(node, branchPayload, preserved, { menuDepthLimited: false });
  return true;
}

async function fetchMenuBranch(folderPath, agentId = activeWorkspaceId) {
  const { maxDepth } = getMenuTreeSettings(agentId);
  const response = await fetch(
    buildApiUrl(
      "/api/menu/branch",
      {
        folderPath,
        maxDepth: String(maxDepth),
        branchDepth: String(MENU_LAZY_BOOTSTRAP_DEPTH)
      },
      agentId
    )
  );
  if (!response.ok) {
    const errorData = await response.json().catch(() => ({}));
    throw new Error(errorData.details || errorData.error || `Request failed with ${response.status}`);
  }
  return stripPlatformDataFoldersFromMenu(await response.json());
}

async function ensureMenuBranchLoaded(folderPath, agentId = activeWorkspaceId) {
  const normalized = normalizeMenuPatchFolderPath(folderPath, agentId);
  const menu = menuCacheByAgent.get(agentId) || (agentId === activeWorkspaceId ? currentMenuData : null);
  if (!menu) return;
  const branch = getMenuBranchForFolder(menu, normalized, agentId);
  const node = branch?.node ?? getMenuTreeNodeByFolderPath(normalized, agentId);
  if (!node || !isMenuFolderLazyExpandable(node)) return;

  const inFlight = getMenuBranchLoadInFlight(agentId);
  if (inFlight.has(normalized)) {
    await inFlight.get(normalized);
    return;
  }

  const loadPromise = (async () => {
    if (!menu) throw new Error("Кэш меню пуст — обновите дерево");
    setMenuBranchLoading(normalized, agentId, true);
    let branchPayload;
    try {
      branchPayload = await fetchMenuBranch(normalized, agentId);
      await refreshMenuRuntimeFlagsCache(agentId);
      enrichMenuRuntimeFromCache(branchPayload, agentId);
    } finally {
      setMenuBranchLoading(normalized, agentId, false);
    }
    if (!applyMenuBranchPayload(menu, normalized, branchPayload, agentId)) {
      throw new Error("Не найден узел в кэше меню — обновите дерево");
    }
    menuCacheByAgent.set(agentId, menu);
    if (agentId === activeWorkspaceId) {
      currentMenuData = menu;
      invalidateMenuDisplayLabelMap();
    }
  })();

  inFlight.set(normalized, loadPromise);
  try {
    await loadPromise;
  } finally {
    inFlight.delete(normalized);
  }
}

function sanitizeCollapsedFolderPaths(agentId = activeWorkspaceId) {
  const collapsedFolders = getAgentCollapsedFolders(agentId);
  if (collapsedFolders.delete(".")) {
    saveCollapsedFoldersByAgent();
  }
}

function getMenuTreeFolderPaths(agentId = activeWorkspaceId) {
  if (!currentMenuData) return [];
  const agentTitle = getAgentTreeTitle(agentId);
  const baseTree = { title: agentTitle, ...currentMenuData };
  const folderPaths = collectFolderPaths(baseTree);
  if (currentMenuData.serviceTree) {
    collectFolderPaths({ title: "", ...currentMenuData.serviceTree }, "", folderPaths);
  }
  if (currentMenuData.containerTree) {
    collectFolderPaths({ title: "", ...currentMenuData.containerTree }, "", folderPaths);
  }
  return Array.from(folderPaths).filter((path) => path !== ".");
}

function isMenuTreeFullyCollapsed(agentId = activeWorkspaceId) {
  const paths = getMenuTreeFolderPaths(agentId);
  const collapsedFolders = getAgentCollapsedFolders(agentId);
  if (paths.length === 0) {
    return isServiceTreeCollapsed() && isSharedTreeCollapsed();
  }
  return (
    paths.every((path) => collapsedFolders.has(path)) &&
    isServiceTreeCollapsed() &&
    isSharedTreeCollapsed()
  );
}

function syncMenuCollapseAllButton() {
  if (!menuCollapseAllBtn) return;
  const enabled =
    menuViewMode === "tree" && !menuSearchQuery.trim().length && Boolean(currentMenuData);
  menuCollapseAllBtn.disabled = !enabled;
  if (!enabled) {
    menuCollapseAllBtn.classList.remove("is-expand-all");
    return;
  }
  const fullyCollapsed = isMenuTreeFullyCollapsed();
  menuCollapseAllBtn.classList.toggle("is-expand-all", fullyCollapsed);
  menuCollapseAllBtn.title = fullyCollapsed ? "Развернуть все ветки" : "Свернуть все ветки";
  menuCollapseAllBtn.setAttribute(
    "aria-label",
    fullyCollapsed ? "Развернуть все ветки" : "Свернуть все ветки"
  );
}

function expandAllMenuTreeBranches(agentId = activeWorkspaceId) {
  if (!currentMenuData || !isMenuTreeLayoutMode() || menuSearchQuery.trim()) return;

  getAgentCollapsedFolders(agentId).clear();
  localStorage.setItem("agentcms.serviceTree.collapsed.v1", "0");
  localStorage.setItem("agentcms.sharedTree.collapsed.v1", "0");
  localStorage.setItem("agentcms.containerTree.collapsed.v1", "0");
  saveCollapsedFoldersByAgent();

  const host = getMenuTreeHost(agentId);
  if (host && canIncrementalMenuPatch()) {
    withPreservedMenuTreePreviews(agentId, () => {
      withPreservedMenuScroll(() => {
        host.querySelectorAll(".menu-section[data-menu-folder]").forEach((sectionEl) => {
          const folderPath = sectionEl.dataset.menuFolder || ".";
          if (folderPath === ".") return;
          const childrenNode = sectionEl.querySelector(":scope > .tree-children");
          syncFolderToggleUi(sectionEl, false, resolveMenuSectionHasContent(sectionEl, agentId));
          if (childrenNode && menuTreeChildrenNodeHasRenderedContent(childrenNode)) {
            childrenNode.hidden = false;
            return;
          }
          patchFolderCollapsedState(folderPath, agentId);
        });
        syncReservedMenuSectionsCollapsedUi(agentId, currentMenuData);
      });
    });
    updateActiveButton();
    syncMenuCollapseAllButton();
    return;
  }

  withPreservedMenuScroll(() => renderMenu(currentMenuData, agentId, { menuOnly: true }));
  updateActiveButton();
  syncMenuCollapseAllButton();
}

function collapseAllMenuTreeBranches(agentId = activeWorkspaceId) {
  if (!currentMenuData || !isMenuTreeLayoutMode() || menuSearchQuery.trim()) return;

  const folderPaths = getMenuTreeFolderPaths(agentId);
  const collapsedFolders = getAgentCollapsedFolders(agentId);
  for (const folderPath of folderPaths) {
    collapsedFolders.add(folderPath);
  }
  localStorage.setItem("agentcms.serviceTree.collapsed.v1", "1");
  localStorage.setItem("agentcms.sharedTree.collapsed.v1", "1");
  localStorage.setItem("agentcms.containerTree.collapsed.v1", "1");
  saveCollapsedFoldersByAgent();

  const host = getMenuTreeHost(agentId);
  if (host && canIncrementalMenuPatch()) {
    withPreservedMenuTreePreviews(agentId, () => {
      withPreservedMenuScroll(() => {
        host.querySelectorAll(".menu-section[data-menu-folder]").forEach((sectionEl) => {
          const folderPath = sectionEl.dataset.menuFolder || ".";
          if (folderPath === ".") return;
          const childrenNode = sectionEl.querySelector(":scope > .tree-children");
          syncFolderToggleUi(sectionEl, true, resolveMenuSectionHasContent(sectionEl, agentId));
          if (childrenNode) childrenNode.hidden = true;
        });
        syncReservedMenuSectionsCollapsedUi(agentId, currentMenuData);
      });
    });
    updateActiveButton();
    syncMenuCollapseAllButton();
    return;
  }

  withPreservedMenuScroll(() => renderMenu(currentMenuData, agentId, { menuOnly: true }));
  updateActiveButton();
  syncMenuCollapseAllButton();
}

function toggleCollapseAllMenuTreeBranches() {
  if (isMenuTreeFullyCollapsed()) {
    expandAllMenuTreeBranches();
  } else {
    collapseAllMenuTreeBranches();
  }
}

function findModeGroup(modeId) {
  return getAllModeGroups().find((group) => group.modes.some((mode) => mode.id === modeId)) || null;
}

function isGraphModeActive() {
  return activeContentMode === "graph" && Boolean(activePath) && !activeSystemFile;
}

function isMindmapModeActive() {
  return activeContentMode === NODE_MINDMAP_MODE && Boolean(activePath) && !activeSystemFile;
}

function isNodeCanvasViewMode() {
  return isGraphModeActive() || isMindmapModeActive();
}

function applyContentModeState(mode, options = {}) {
  if (mode === "quick-notes") mode = "note";
  if (mode === "graph") return false;
  if (
    isRepositoryWorkspacePath(activePath) &&
    mode !== NODE_NAVIGATION_MODE &&
    mode !== NODE_OVERVIEW_MODE &&
    mode !== "description" &&
    mode !== FOLDER_BROWSE_MODE &&
    mode !== FOLDER_BROWSE_FILE_MODE
  ) {
    mode = NODE_NAVIGATION_MODE;
  }
  const group = findModeGroup(mode);
  const modeDef = group?.modes.find((item) => item.id === mode);
  if (modeDef?.disabled) return false;
  if (mode === "graph" && !activePath) {
    showToast("Выберите тему в дереве слева", "info");
    return false;
  }
  if (isMemoryDriverModeBlockedForActivePath(mode)) {
    mode = NODE_NAVIGATION_MODE;
  }
  if (mode === "topic-schema" && !isTopicSchemaModeAvailable()) {
    mode = "description";
  }

  activeContentMode = mode;
  if (mode !== NODE_ENTRY_OVERVIEW_MODE) {
    activeEntryOverviewContext = null;
    resetEntryOverviewSearch();
  }
  if (isFlatStorageListMode(mode)) {
    activeStorageFolderExists = false;
  }
  if (!isMediaLibraryContentMode(mode)) {
    clearMediaSidecarEditor();
    setMediaBulkUploadPanelOpen(false);
  }
  if (mode !== "external") {
    activeExternalFilePath = null;
    activeExternalSectionFolder = null;
  }
  if (!isFlatStorageSectionMode(mode)) {
    activeFlatStorageFilePath = null;
  }
  for (const flatMode of FLAT_STORAGE_SECTION_MODES) {
    if (mode !== flatMode) activeFlatStorageSectionFolder[flatMode] = null;
  }
  if (isFlatStorageListMode(mode) || mode === "tabular") {
    editorViewMode = "preview";
  }
  if ((mode === "todo" || mode === "roadmap") && WYSIWYG_EDITOR_ENABLED) {
    editorViewMode = "wysiwyg";
  }
  if (
    mode === NODE_OVERVIEW_MODE ||
    mode === NODE_NAVIGATION_MODE ||
    mode === FOLDER_BROWSE_MODE ||
    mode === AWN_DATA_VIEW_MODE ||
    mode === NODE_ENTRY_OVERVIEW_MODE ||
    mode === NODE_DISCUSSION_MODE
  ) {
    nodeSettingsViewActive = false;
    nodeMemoryViewActive = false;
  } else if (NODE_SETTINGS_MODE_IDS.has(mode)) {
    nodeSettingsViewActive = true;
    nodeMemoryViewActive = false;
  } else if (NODE_MEMORY_MODE_IDS.has(mode)) {
    nodeMemoryViewActive = true;
    nodeSettingsViewActive = false;
  } else {
    if (nodeSettingsViewActive && !isNodeSettingsSelectMode(mode)) {
      nodeSettingsViewActive = false;
    }
    if (nodeMemoryViewActive && !isNodeMemorySelectMode(mode)) {
      nodeMemoryViewActive = false;
    }
  }
  if (mode !== AWN_DATA_VIEW_MODE && !awnDataManifestEditReturnRel) {
    awnDataViewStoreRel = "";
    awnDataManifestEditReturnRecordId = "";
    awnDataViewStoreCache = null;
    awnDataViewRecordId = "";
    awnDataViewRecordCache = null;
    awnDataViewSectionId = "__all__";
    awnDataViewSchemaDraft = "";
    syncAwnDataViewDomRefs(null);
  }
  syncNodeSettingsModeSelect();
  syncNodeMemoryModeSelect();
  if (!options.skipWorkspaceUi) {
    applyNodeWorkspaceViewUi();
  }
  return true;
}

function revealAwnDatabaseManifestEditorShell() {
  hideContentLoading({ force: true });
  finishAwnDataViewStoreLoading();
  nodeOverviewBlockNode?.classList.add("hidden");
  nodeOverviewBlockNode?.classList.remove("is-awn-databases-view", "is-folder-browse", "is-entry-overview");
  editorSurfaceNode?.classList.remove("hidden");
  docSlabMainNode?.classList.remove("is-content-loading");
}

function applyAwnDatabaseEditorPropertiesFromContent(rawContent, nodePath = getResolvedNodePath(activePath)) {
  const normalized = String(nodePath || "").replace(/\\/g, "/").replace(/^\/+/, "");
  if (isAwnDatabaseCsvRecordContentPath(normalized)) {
    setPropsYamlContent("", { skipRender: true });
    return;
  }
  if (!isAwnDatabaseManifestPath(normalized) && !isAwnDatabaseRecordContentPath(normalized)) {
    return;
  }
  const { frontmatter } = splitFrontmatter(String(rawContent || ""));
  setPropsYamlContent(frontmatter, { skipRender: true });
}

function setContentMode(mode) {
  if (isGitRepoLooseMdEditing() && mode !== "internal") return;
  if (!applyContentModeState(mode)) return;
  activeDataStorageAllItems = false;
  syncAppRouteToUrl({ replace: true });
  void applyContentModeChange();
}

async function applyContentModeChange() {
  if (isProjectSettingsMode()) {
    applyModeUi();
    await loadProjectSettingsContent();
    syncEditorLineNumbers();
    syncChannelLiveUpdates();
    return;
  }
  if (activePath) {
    const deferInitialModeUi =
      activeContentMode === "topic-schema" ||
      activeContentMode === "configs" ||
      activeContentMode === PROJECT_SETTINGS_MODE;
    if (!deferInitialModeUi) {
      applyModeUi();
    }
    await loadContentByMode();
    if (activeContentMode === NODE_ENTRY_OVERVIEW_MODE && activeEntryOverviewContext) {
      await renderEntryOverview();
    }
    syncEditorLineNumbers();
  } else {
    applyModeUi();
  }
  syncChannelLiveUpdates();
}

function isMediaSidecarEditing() {
  return isMediaLibraryContentMode() && Boolean(activeMediaSidecarPath);
}

function isCurrentModeWithoutContentEditor() {
  if (isAttachmentSidecarEditing()) return false;
  if (activeSystemFile) return false;
  return (
    activeContentMode === NODE_OVERVIEW_MODE ||
    activeContentMode === NODE_NAVIGATION_MODE ||
    activeContentMode === FOLDER_BROWSE_MODE ||
    activeContentMode === AWN_DATA_VIEW_MODE ||
    activeContentMode === NODE_ENTRY_OVERVIEW_MODE ||
    activeContentMode === NODE_DISCUSSION_MODE ||
    activeContentMode === NODE_JOURNAL_MODE ||
    activeContentMode === "node-preview" ||
    activeContentMode === "topic-schema" ||
    activeContentMode === "configs" ||
    activeContentMode === PROJECT_SETTINGS_MODE ||
    (isMediaLibraryContentMode() && !isMediaAssetEditing() && !isFlatStorageFileEditing())
  );
}

function getFlatStorageListContentCacheMode(mode = activeContentMode) {
  return mode === "quick-notes" ? "note" : mode;
}

function getListViewRawContent() {
  if (isMediaLibraryContentMode() && !isMediaAssetEditing()) {
    return modeContentCache[activeContentMode] || "";
  }
  if (activeContentMode === "external" && !isExternalFileEditing()) {
    return modeContentCache.external || "";
  }
  if (isFlatStorageListMode() && !isFlatStorageFileEditing()) {
    const cacheMode = getFlatStorageListContentCacheMode();
    return modeContentCache[cacheMode] || modeContentCache[activeContentMode] || "";
  }
  return fileContentInputNode.value || "";
}

function isCurrentModeReadOnly() {
  if (activeSystemFile) return false;
  const externalEditing = activeContentMode === "external" && Boolean(activeExternalFilePath);
  const mediaSidecarEditing = isMediaAssetEditing();
  return (
    (activeContentMode === "external" && !externalEditing) ||
    (activeContentMode === "tabular" && !isTabularSourceEditing()) ||
    (isFlatStorageListMode() && !isFlatStorageFileEditing()) ||
    activeContentMode === NODE_DISCUSSION_MODE ||
    (isMediaLibraryContentMode() && !mediaSidecarEditing) ||
    activeContentMode === "scripts" ||
    activeContentMode === NODE_OVERVIEW_MODE ||
    activeContentMode === NODE_NAVIGATION_MODE ||
    activeContentMode === FOLDER_BROWSE_MODE ||
    activeContentMode === NODE_DISCUSSION_MODE ||
    activeContentMode === NODE_JOURNAL_MODE ||
    activeContentMode === "node-preview" ||
    activeContentMode === "graph"
  );
}

function isCurrentModeTitleEditable() {
  const externalEditing = activeContentMode === "external" && Boolean(activeExternalFilePath);
  const mediaSidecarEditing = isMediaAssetEditing();
  return (
    activeContentMode === "description" ||
    externalEditing ||
    mediaSidecarEditing ||
    isFlatStorageFileEditing()
  );
}

function isNodeDeleteAvailable() {
  if (!activePath || activeSystemFile) return false;
  if (activeContentMode !== "description") return false;
  if (isAgentRootIndexPath(getActiveNodeApiPath())) return false;
  if (isAgentSystemRootIndexPath(getActiveNodeApiPath())) return false;
  return true;
}

function isExternalFileEditingOrOpening() {
  return (
    activeContentMode === "external" &&
    (Boolean(activeExternalFilePath) || Boolean(pendingDirectExternalFile))
  );
}

function isCurrentModeListTemplate() {
  if (activeSystemFile) return false;
  const externalEditing = isExternalFileEditingOrOpening();
  const mediaSidecarEditing = isMediaAssetEditing();
  const flatStorageEditing = isFlatStorageFileEditing();
  return (
    activeContentMode === "internal" ||
    activeContentMode === "todo" ||
    activeContentMode === "roadmap" ||
    (activeContentMode === "external" && !externalEditing) ||
    (activeContentMode === "tabular" && !isTabularSourceEditing()) ||
    (isFlatStorageListMode() && !flatStorageEditing) ||
    (isMediaLibraryContentMode() && !mediaSidecarEditing)
  );
}

function getNodeFolderPath(nodePath) {
  if (isNodeManifestPath(nodePath)) return getFolderPathFromManifest(nodePath);
  const parts = String(nodePath || "").split("/").filter(Boolean);
  if (parts.length === 0) return "";
  return parts.slice(0, -1).join("/");
}

function getNodeStoragePrefix(nodePath) {
  return getNamedStorageSlotDirRel(getResolvedNodePath(nodePath));
}

function getNodeStorageSubfolderPath(nodePath, subfolderOrMode) {
  let folder = getStorageSubfolderForMode(subfolderOrMode) || String(subfolderOrMode || "").trim();
  const resolvedPath = getResolvedNodePath(nodePath);
  if (folder === STORAGE_SUBFOLDER_MEDIA && isHubWorkspaceFilesSlotPage(resolvedPath)) {
    folder = STORAGE_SUBFOLDER_FILES;
  }
  const slotDir = getNamedStorageSlotDirRel(resolvedPath);
  return slotDir ? `${slotDir}/${folder}` : `${getNodeStoragePrefix(resolvedPath)}/${folder}`;
}

function getEnvBreadcrumbPath(nodePath) {
  return getNodeDisplayPath(nodePath);
}

function parsePartFolderManifestRel(nodePath) {
  const normalized = String(nodePath || "").replace(/\\/g, "/");
  const match = normalized.match(/^(.*\/)?_Parts\/([^/]+)\/([^/]+\.(?:node|x)\.md)$/i);
  if (!match || !isAreaManifestFileName(match[3])) return null;
  const prefix = match[1] || "";
  const partName = match[2];
  return {
    dir: `${prefix}_Parts/${partName}`,
    partName,
    manifestName: match[3]
  };
}

function resolvePartFolderSidecarBaseRel(nodePath) {
  const parsed = parsePartFolderManifestRel(nodePath);
  if (!parsed) return null;
  const stem = parsed.manifestName.replace(MANIFEST_MD_RE, "");
  return `${parsed.dir}/${stem}.x`;
}

function getManifestContainerDirRel(relPath) {
  const normalized = String(relPath || "").replace(/\\/g, "/");
  const slash = normalized.lastIndexOf("/");
  if (slash < 0) return "";
  return normalized.slice(0, slash);
}

function getStorageContainerPrefixRel(relPath) {
  const normalized = String(relPath || "").replace(/\\/g, "/").replace(/^\/+/, "");
  if (!normalized) return "";
  const marker = `/${STORAGE_ROOT_FOLDER}/`;
  const idx = normalized.toLowerCase().indexOf(marker.toLowerCase());
  if (idx >= 0) {
    return normalized.slice(0, idx);
  }
  return getManifestContainerDirRel(normalized);
}

function getManifestNamedSlotKey(relPath) {
  const normalized = String(relPath || "").replace(/\\/g, "/");
  const base = normalized.slice(normalized.lastIndexOf("/") + 1);
  if (isAreaManifestFileName(base)) {
    const dir = getManifestContainerDirRel(normalized);
    if (!dir) return "";
    return dir.slice(dir.lastIndexOf("/") + 1);
  }
  return "";
}

function getNamedStorageSlotDirRel(relPath) {
  const ownerRel = resolveOwningManifestRelFromNodePath(relPath);
  const containerDir = getManifestContainerDirRel(ownerRel);
  if (!containerDir) return STORAGE_ROOT_FOLDER;
  return `${containerDir}/${STORAGE_ROOT_FOLDER}`;
}

function getNamedStorageBundleDirRel(relPath) {
  const ownerRel = resolveOwningManifestRelFromNodePath(relPath);
  return getManifestContainerDirRel(ownerRel);
}

function getNamedStorageBundleRel(relPath, bundleFileName) {
  return `${getNamedStorageBundleDirRel(relPath)}/${bundleFileName}`;
}

function getWorkspaceFolderStorageKey() {
  const agent = getActiveAgentMeta();
  const agentPath = String(agent?.path || "").trim();
  if (!agentPath) return "";
  const parts = agentPath.replace(/\\/g, "/").split("/").filter(Boolean);
  return parts[parts.length - 1] || "";
}

function getManifestStorageKey(relPath) {
  return getManifestNamedSlotKey(relPath);
}

function buildStorageLayerRef(contextRelPath, layerFolder, relativePath) {
  const rel = String(relativePath || "").replace(/\\/g, "/").replace(/^\/+/, "");
  if (!rel || rel.includes("..")) return "";
  const layer = getStorageSubfolderForMode(layerFolder) || String(layerFolder || "").trim();
  if (!layer) return "";
  const slotDir = getNamedStorageSlotDirRel(contextRelPath);
  if (!slotDir) return "";
  return `${slotDir}/${layer}/${rel}`;
}

function parseStorageLayerRef(workspaceRelPath) {
  const normalized = String(workspaceRelPath || "").replace(/\\/g, "/").replace(/^\/+/, "");
  if (!normalized || normalized.includes("..")) return null;

  let containerPrefix = "";
  let layer = "";
  let relativePath = "";

  const storageRootPattern = getStorageRootPathAlternationPattern();
  const rootMatch = normalized.match(
    new RegExp(`^${storageRootPattern}/([^/]+)/(.+)$`, "i")
  );
  if (rootMatch) {
    layer = getStorageSubfolderForMode(rootMatch[1]) || rootMatch[1];
    relativePath = rootMatch[2];
  } else {
    const match = normalized.match(
      new RegExp(`^(.*?)/${storageRootPattern}/([^/]+)/(.+)$`, "i")
    );
    if (!match) return null;
    containerPrefix = String(match[1] || "").replace(/\/$/, "");
    layer = getStorageSubfolderForMode(match[2]) || match[2];
    relativePath = match[3];
  }
  if (!layer || !relativePath) return null;

  const manifestRel = containerPrefix ? `${containerPrefix}/${MANIFEST_FILE}` : MANIFEST_FILE;

  return {
    workspacePath: normalized,
    slotDir: containerPrefix ? `${containerPrefix}/${STORAGE_ROOT_FOLDER}` : STORAGE_ROOT_FOLDER,
    slotKey: containerPrefix ? containerPrefix.slice(containerPrefix.lastIndexOf("/") + 1) : "",
    layer,
    relativePath,
    manifestCandidates: [manifestRel]
  };
}

function pickManifestRelFromStorageLayerRef(parsed) {
  if (!parsed?.manifestCandidates?.length) return null;
  const preferred = parsed.manifestCandidates.find(
    (candidate) =>
      candidate.split("/").pop()?.toLowerCase() === `${parsed.slotKey.toLowerCase()}.md`
  );
  return preferred || parsed.manifestCandidates[0];
}

function parseStorageAssetsRef(workspaceRelPath) {
  const parsed = parseStorageLayerRef(workspaceRelPath);
  if (!parsed || parsed.layer !== STORAGE_SUBFOLDER_ASSETS) return null;
  return {
    manifestRelPath: pickManifestRelFromStorageLayerRef(parsed),
    mediaFile: parsed.relativePath,
    workspacePath: parsed.workspacePath,
    slotDir: parsed.slotDir
  };
}

function resolveOwningManifestRelFromNodePath(nodePath) {
  const normalized = String(nodePath || "").replace(/\\/g, "/").replace(/^\/+/, "");
  if (!normalized) return "";
  const base = normalized.split("/").filter(Boolean).pop() || "";
  // Section/category readmes under awn-storage/(main|media)/…/manifest.md share the
  // parent page assets slot — same as regular content records.
  const isNestedSectionReadme =
    isAreaManifestFileName(base) &&
    /\/(?:awn-storage|storage)\/(?:main|memory|content|media)\//i.test(normalized);
  if (isAreaManifestFileName(base) && !isNestedSectionReadme) return normalized;
  const storageMarkerIdx = findStorageRootMarkerIndex(normalized);
  if (storageMarkerIdx >= 0) {
    const prefix = normalized.slice(0, storageMarkerIdx).replace(/\/$/, "");
    return prefix ? `${prefix}/${MANIFEST_FILE}` : MANIFEST_FILE;
  }
  return normalized;
}

function listStorageAssetsRefPathCandidates(workspaceRelPath, contextManifestRelPath) {
  const normalized = String(workspaceRelPath || "").replace(/\\/g, "/").replace(/^\/+/, "");
  if (!normalized || normalized.includes("..")) return [];

  const context = resolveOwningManifestRelFromNodePath(contextManifestRelPath || MANIFEST_FILE);
  const rawContext = String(contextManifestRelPath || MANIFEST_FILE)
    .replace(/\\/g, "/")
    .replace(/^\/+/, "");

  const candidates = [];
  const seen = new Set();
  const add = (value, { first = false } = {}) => {
    const item = String(value || "").replace(/\\/g, "/").replace(/^\/+/, "");
    if (!item || item.includes("..") || seen.has(item)) return;
    seen.add(item);
    if (first) candidates.unshift(item);
    else candidates.push(item);
  };

  if (isStorageRootRelativePath(normalized)) {
    const containerDir = getManifestContainerDirRel(context);
    if (containerDir) add(`${containerDir}/${normalized}`, { first: true });
    if (/(?:\/awn-storage\/|\/storage\/)(?:main|memory|content)\//i.test(rawContext)) {
      const legacyNested = `${containerDir}/awn-storage/main/awn-storage/${stripStorageRootPrefix(normalized)}`;
      add(legacyNested, { first: false });
      const legacyNestedContent = `${containerDir}/awn-storage/content/awn-storage/${stripStorageRootPrefix(normalized)}`;
      add(legacyNestedContent);
      const legacyNestedOld = `${containerDir}/storage/content/storage/${stripStorageRootPrefix(normalized)}`;
      add(legacyNestedOld);
    }
  }

  if (/^assets\//i.test(normalized)) {
    const slotDir = getNamedStorageSlotDirRel(context);
    if (slotDir) add(`${slotDir}/${normalized}`, { first: true });
  }

  add(normalized);
  return candidates;
}

const STORAGE_SUBFOLDER_MEMORY = "main";
