function parseMediaSections(text) {
  const lines = String(text || "").split("\n");
  const sections = [];
  let current = null;
  for (const rawLine of lines) {
    const line = rawLine.trim();
    if (!line) continue;
    if (line.startsWith("## ")) {
      if (current) sections.push(current);
      current = { title: line.slice(3).trim(), items: [] };
      continue;
    }
    if (line.startsWith("- ")) {
      if (!current) current = { title: "Файлы", items: [] };
      current.items.push(line.slice(2).trim());
    }
  }
  if (current) sections.push(current);
  return sections;
}

function parseFlatListItems(text) {
  return String(text || "")
    .split("\n")
    .map((line) => line.trim())
    .filter(Boolean);
}

function normalizeMediaSectionManifestEntry(item) {
  return {
    path: String(item?.path || "").replace(/\\/g, "/"),
    displayName: String(item?.displayName || "").trim(),
    status: String(item?.status || "").trim()
  };
}

function stripSectionManifestsFromMediaGroups(groups) {
  const cleaned = {};
  for (const [groupName, groupItems] of Object.entries(groups || {})) {
    if (!Array.isArray(groupItems)) continue;
    const items = groupItems.filter(
      (item) => item.isFolder || !isSectionReadmePath(String(item.path || ""))
    );
    if (items.length > 0) cleaned[groupName] = items;
  }
  return cleaned;
}

function extractSectionManifestsFromMediaGroups(groups) {
  const manifests = [];
  for (const groupItems of Object.values(groups || {})) {
    if (!Array.isArray(groupItems)) continue;
    for (const item of groupItems) {
      if (item.isFolder || !isSectionReadmePath(String(item.path || ""))) continue;
      manifests.push(normalizeMediaSectionManifestEntry(item));
    }
  }
  return manifests;
}

function buildMediaFilesCacheFromContent(text) {
  const sections = parseMediaSections(text);
  const groups = {};
  const sectionManifests = [];

  for (const section of sections) {
    const items = [];
    for (const rawItem of section.items) {
      const normalized = normalizeListItem(rawItem);
      if (!normalized.isFolder && isSectionReadmePath(normalized.path)) {
        sectionManifests.push(normalizeMediaSectionManifestEntry({ path: normalized.path }));
        continue;
      }
      const segments = normalized.path.split("/").filter(Boolean);
      const name = normalized.isFolder
        ? segments[segments.length - 1] || normalized.path.replace(/\/$/, "")
        : segments[segments.length - 1] || normalized.path;
      const ext = normalized.isFolder
        ? ""
        : (name.includes(".") ? `.${name.split(".").pop().toLowerCase()}` : "");

      items.push({
        path: normalized.path,
        name,
        group: section.title,
        isFolder: normalized.isFolder,
        size: 0,
        ext
      });
    }
    if (items.length > 0) groups[section.title] = items;
  }

  return { groups, sectionManifests };
}

function syncMediaFilesCache(content, groups, sectionManifests) {
  if (groups && typeof groups === "object" && Object.keys(groups).length > 0) {
    mediaFilesCache = stripSectionManifestsFromMediaGroups(groups);
    mediaSectionManifests = Array.isArray(sectionManifests) && sectionManifests.length > 0
      ? sectionManifests.map(normalizeMediaSectionManifestEntry)
      : extractSectionManifestsFromMediaGroups(groups);
    return;
  }
  const built = buildMediaFilesCacheFromContent(content || "");
  mediaFilesCache = built.groups;
  mediaSectionManifests = built.sectionManifests;
}

function normalizeListItem(rawItem) {
  const clean = String(rawItem || "")
    .trim()
    .replace(/^[-*]\s+/, "")
    .replace(/^📁\s+/, "")
    .replace(/^📄\s+/, "");
  return {
    path: clean,
    isFolder: clean.endsWith("/")
  };
}

function computeGraphNodeDegrees(edges) {
  const degrees = new Map();
  for (const edge of edges) {
    degrees.set(edge.from, (degrees.get(edge.from) || 0) + 1);
    degrees.set(edge.to, (degrees.get(edge.to) || 0) + 1);
  }
  return degrees;
}

function buildGraphAdjacency(edges) {
  const adjacency = new Map();
  const link = (from, to) => {
    if (!adjacency.has(from)) adjacency.set(from, new Set());
    adjacency.get(from).add(to);
  };
  for (const edge of edges) {
    link(edge.from, edge.to);
    link(edge.to, edge.from);
  }
  return adjacency;
}

function buildGraphParentChildMaps(linkElements) {
  const parentsByChild = new Map();
  const childrenByParent = new Map();
  for (const line of linkElements) {
    const from = line.from;
    const to = line.to;
    if (!parentsByChild.has(to)) parentsByChild.set(to, new Set());
    parentsByChild.get(to).add(from);
    if (!childrenByParent.has(from)) childrenByParent.set(from, new Set());
    childrenByParent.get(from).add(to);
  }
  return { parentsByChild, childrenByParent };
}

/** Предки и потомки совпадений по дереву меню (рёбра parent → child). */
function expandGraphSearchHighlightIds(matchedIds, linkElements) {
  const highlighted = new Set(matchedIds);
  if (!highlighted.size) return highlighted;

  const { parentsByChild, childrenByParent } = buildGraphParentChildMaps(linkElements);

  const upQueue = [...highlighted];
  while (upQueue.length) {
    const id = upQueue.shift();
    for (const parentId of parentsByChild.get(id) || []) {
      if (highlighted.has(parentId)) continue;
      highlighted.add(parentId);
      upQueue.push(parentId);
    }
  }

  const downQueue = [...matchedIds];
  while (downQueue.length) {
    const id = downQueue.shift();
    for (const childId of childrenByParent.get(id) || []) {
      if (highlighted.has(childId)) continue;
      highlighted.add(childId);
      downQueue.push(childId);
    }
  }

  return highlighted;
}

function getObsidianGraphLayoutSize(nodeCount, containerWidth, containerHeight, fullViewport) {
  const spread = Math.max(880, Math.sqrt(Math.max(nodeCount, 1)) * (fullViewport ? 118 : 102));
  const width = fullViewport
    ? Math.max(spread, containerWidth || 920)
    : Math.max(920, Math.min(1800, Math.max(containerWidth || 920, spread)));
  const height = fullViewport
    ? Math.max(spread * 0.92, containerHeight || 560)
    : Math.max(520, Math.min(980, Math.max(400 + nodeCount * 10, spread * 0.88)));
  return { width, height };
}

function getGraphLayoutSpreadScale(nodeCount, showPreviews = false) {
  const previewBoost = showPreviews ? 1.42 : 1;
  const densityBoost = 1 + Math.min(1.35, Math.sqrt(Math.max(nodeCount, 1)) * 0.058);
  return previewBoost * densityBoost;
}

function estimateGraphNodeLayoutExtent(node, degrees, showPreviews = false) {
  const layout = getGraphPreviewCardLayout(node, showPreviews);
  const radius = getGraphNodeRadius(node, degrees, showPreviews);
  const subLineCount = (node?.graphSubLabel ? 1 : 0) + resolveGraphNodeCardMetaLines(node).length;
  const labelDepth = 14 + subLineCount * 11;
  const titleLen = String(node?.label || "").trim().length;

  if (layout) {
    return {
      rx: layout.cardW / 2 + 10,
      ry: layout.cardH / 2 + labelDepth + 8
    };
  }

  return {
    rx: Math.max(radius + 6, Math.min(96, 16 + titleLen * 3.4)),
    ry: radius + labelDepth + 4
  };
}

function separateGraphLayoutOverlaps(sim, showPreviews = false, maxPasses = 24) {
  const { nodes, centerIds, degrees, width, height } = sim;
  if (nodes.length < 2) return;

  const cx = width / 2;
  const cy = height / 2;
  const gap = showPreviews ? 14 : 9;

  for (let pass = 0; pass < maxPasses; pass += 1) {
    let totalPush = 0;

    for (let i = 0; i < nodes.length; i += 1) {
      for (let j = i + 1; j < nodes.length; j += 1) {
        const a = nodes[i];
        const b = nodes[j];
        if (centerIds.has(a.id) && centerIds.has(b.id)) continue;

        const ea = estimateGraphNodeLayoutExtent(a, degrees, showPreviews);
        const eb = estimateGraphNodeLayoutExtent(b, degrees, showPreviews);
        let dx = b.x - a.x;
        let dy = b.y - a.y;
        const dist = Math.hypot(dx, dy) || 0.01;
        dx /= dist;
        dy /= dist;

        const need =
          Math.max(ea.rx + eb.rx, (ea.ry + eb.ry) * 0.92) + gap +
          (a.isSatelliteRoot || b.isSatelliteRoot ? 6 : 0);
        if (dist >= need) continue;

        const push = ((need - dist) / 2) * 0.94;
        totalPush += push;
        if (!centerIds.has(a.id) && !a.pinned) {
          a.x -= dx * push;
          a.y -= dy * push;
        }
        if (!centerIds.has(b.id) && !b.pinned) {
          b.x += dx * push;
          b.y += dy * push;
        }
      }
    }

    for (const node of nodes) {
      if (centerIds.has(node.id) || node.pinned) continue;
      node.x += (cx - node.x) * 0.0035;
      node.y += (cy - node.y) * 0.0035;
    }

    if (totalPush < 0.35 && pass > 5) break;
  }
}

function computeGraphLayoutBounds(nodes, degrees, padding = 64, showPreviews = false) {
  let minX = Infinity;
  let minY = Infinity;
  let maxX = -Infinity;
  let maxY = -Infinity;
  for (const node of nodes) {
    const radius = getGraphNodeRadius(node, degrees, showPreviews);
    minX = Math.min(minX, node.x - radius - padding);
    minY = Math.min(minY, node.y - radius - padding);
    maxX = Math.max(maxX, node.x + radius + padding);
    maxY = Math.max(maxY, node.y + radius + padding);
  }
  return {
    minX,
    minY,
    width: Math.max(maxX - minX, 160),
    height: Math.max(maxY - minY, 160)
  };
}

const OBSIDIAN_GRAPH_SATELLITE_ROOT_IDS = [
  "service-root",
  "container-root",
  "repositories-root",
  "awn-databases-root",
  "media-libraries-root",
  "channels-root"
];

function computeGraphWarmupSteps(nodeCount) {
  return Math.min(300, Math.max(110, 64 + Math.round(Math.sqrt(Math.max(nodeCount, 1)) * 18)));
}

function assignObsidianGraphInitialLayout(sim, { showPreviews = false } = {}) {
  const { nodes, nodeById, edges, width, height } = sim;
  const cx = width / 2;
  const cy = height / 2;
  const root = nodeById.get("agent-root");
  if (!root) return;

  const spreadScale = getGraphLayoutSpreadScale(nodes.length, showPreviews);

  const strongKids = new Map();
  const weakKids = new Map();
  for (const node of nodes) {
    strongKids.set(node.id, []);
    weakKids.set(node.id, []);
  }
  for (const edge of edges) {
    const bucket = edge.weak ? weakKids : strongKids;
    if (!bucket.has(edge.from)) bucket.set(edge.from, []);
    bucket.get(edge.from).push(edge.to);
  }

  const placed = new Set();
  const place = (node, x, y) => {
    node.x = x;
    node.y = y;
    placed.add(node.id);
  };

  place(root, cx, cy);

  const minDim = Math.min(width, height);
  const satelliteRing = Math.max(280, minDim * 0.38) * spreadScale;

  OBSIDIAN_GRAPH_SATELLITE_ROOT_IDS.forEach((id, index) => {
    const node = nodeById.get(id);
    if (!node) return;
    const angle = (index / OBSIDIAN_GRAPH_SATELLITE_ROOT_IDS.length) * Math.PI * 2 - Math.PI / 2;
    place(node, cx + Math.cos(angle) * satelliteRing, cy + Math.sin(angle) * satelliteRing);
  });

  const rootStrong = (strongKids.get(root.id) || []).filter((id) => !placed.has(id));
  const innerRing = satelliteRing * 0.56;
  rootStrong.forEach((id, i) => {
    const node = nodeById.get(id);
    if (!node) return;
    const angle = (i / Math.max(rootStrong.length, 1)) * Math.PI * 2 - Math.PI / 2;
    place(node, cx + Math.cos(angle) * innerRing, cy + Math.sin(angle) * innerRing);
  });

  const layoutWeakFan = (parentId, baseDist = 108) => {
    const parent = nodeById.get(parentId);
    if (!parent) return;
    const kids = (weakKids.get(parentId) || []).filter((id) => !placed.has(id));
    if (!kids.length) return;
    const baseAngle = Math.atan2(parent.y - cy, parent.x - cx);
    const perRow = showPreviews ? 6 : 8;
    const span = Math.min(Math.PI * 1.35, kids.length * (showPreviews ? 0.24 : 0.19) + 0.48);
    const rowStep = (showPreviews ? 78 : 58) * Math.max(1, spreadScale * 0.82);
    const scaledBase = baseDist * spreadScale;

    kids.forEach((id, i) => {
      const node = nodeById.get(id);
      if (!node) return;
      const row = Math.floor(i / perRow);
      const col = i % perRow;
      const colsInRow = Math.min(perRow, kids.length - row * perRow);
      const t = colsInRow === 1 ? 0.5 : col / (colsInRow - 1);
      const angle = baseAngle - span / 2 + t * span;
      const dist = scaledBase + row * rowStep + col * (showPreviews ? 6 : 4);
      place(node, parent.x + Math.cos(angle) * dist, parent.y + Math.sin(angle) * dist);
    });
  };

  for (const satId of OBSIDIAN_GRAPH_SATELLITE_ROOT_IDS) layoutWeakFan(satId, 112);

  const queue = [root.id];
  while (queue.length) {
    const parentId = queue.shift();
    const parent = nodeById.get(parentId);
    if (!parent) continue;
    const kids = (strongKids.get(parentId) || []).filter((id) => !placed.has(id));
    if (!kids.length) continue;

    const parentAngle = Math.atan2(parent.y - cy, parent.x - cx);
    const span = Math.min(Math.PI * 1.28, kids.length * (showPreviews ? 0.44 : 0.38) + 0.36);
    const siblingBoost = kids.length * (showPreviews ? 16 : 11);
    const linkLen =
      (parentId === root.id ? 124 : 88 + Math.min(kids.length * 4, 56) + siblingBoost * 0.35) *
      spreadScale;

    kids.forEach((id, i) => {
      const node = nodeById.get(id);
      if (!node) return;
      const t = kids.length === 1 ? 0.5 : i / (kids.length - 1);
      const angle = parentAngle - span / 2 + t * span;
      const stagger = (i % 2) * (showPreviews ? 18 : 12);
      place(
        node,
        parent.x + Math.cos(angle) * (linkLen + stagger),
        parent.y + Math.sin(angle) * (linkLen + stagger)
      );
      queue.push(id);
    });
  }

  for (const node of nodes) {
    if (placed.has(node.id)) continue;
    const angle = (node.depth || 0) * 0.85 + placed.size * 0.11;
    const r = satelliteRing * (1.08 + (placed.size % 6) * 0.035);
    place(node, cx + Math.cos(angle) * r, cy + Math.sin(angle) * r);
  }
}

function createObsidianGraphSimulation(nodes, edges, width, height, options = {}) {
  const showPreviews = Boolean(options.showPreviews);
  const centerIds = new Set(["root", "agent-root"]);
  const degrees = computeGraphNodeDegrees(edges);
  const positioned = nodes.map((node) => ({
    ...node,
    x: width / 2,
    y: height / 2,
    vx: 0,
    vy: 0,
    pinned: centerIds.has(node.id),
    floatPhase: Math.random() * Math.PI * 2,
    floatRadius: 0.75 + Math.random() * 0.55
  }));

  const nodeById = new Map(positioned.map((node) => [node.id, node]));

  const sim = {
    nodes: positioned,
    nodeById,
    edges,
    width,
    height,
    centerIds,
    degrees,
    phase: "settling",
    alpha: 1,
    floatTime: 0
  };
  assignObsidianGraphInitialLayout(sim, { showPreviews });
  separateGraphLayoutOverlaps(sim, showPreviews, showPreviews ? 28 : 22);
  return sim;
}

function clampGraphNodeVelocity(node, maxSpeed) {
  const speed = Math.hypot(node.vx, node.vy);
  if (speed <= maxSpeed) return;
  const scale = maxSpeed / speed;
  node.vx *= scale;
  node.vy *= scale;
}

function warmUpObsidianGraphSimulation(sim, steps) {
  const total = steps ?? computeGraphWarmupSteps(sim.nodes.length);
  sim.phase = "settling";
  for (let step = 0; step < total; step += 1) {
    sim.alpha = Math.max(0.07, 1 - step / Math.max(total - 1, 1));
    tickObsidianGraphSimulation(sim);
  }
  sim.alpha = 0.38;
  sim.phase = "settling";
  for (let polish = 0; polish < 48; polish += 1) {
    tickObsidianGraphSimulation(sim);
    if (sim.phase === "idle") break;
  }
  for (const node of sim.nodes) {
    node.vx = 0;
    node.vy = 0;
  }
  sim.phase = "idle";
  sim.alpha = 0.11;
  sim.floatTime = 0;
}

function tickObsidianGraphSimulation(sim) {
  const { nodes, nodeById, edges, width, height, centerIds, degrees } = sim;

  if (sim.phase === "settling") {
    sim.alpha *= 0.968;
    if (sim.alpha < 0.04) {
      sim.phase = "idle";
      sim.alpha = 0.11;
      sim.floatTime = 0;
    }
  } else {
    sim.floatTime += 1;
  }

  const forceAlpha = sim.phase === "idle" ? 0.17 : sim.alpha;
  if (forceAlpha < 0.0004 && sim.phase !== "idle") return false;

  sim._forceTick = (sim._forceTick || 0) + 1;
  const skipRepulse =
    sim.phase === "idle" && nodes.length > 90 && sim._forceTick % 2 === 0;

  const repulsionStrength = (3200 + nodes.length * 12) * forceAlpha;
  const maxVelocity = sim.phase === "idle" ? 1.08 : 2.55;
  const repulseCutoff =
    nodes.length > 45
      ? Math.min(360, Math.max(200, 170 + Math.sqrt(nodes.length) * 9))
      : Infinity;

  if (!skipRepulse) {
  for (let i = 0; i < nodes.length; i += 1) {
    for (let j = i + 1; j < nodes.length; j += 1) {
      const a = nodes[i];
      const b = nodes[j];
      let dx = b.x - a.x;
      let dy = b.y - a.y;
      let dist = Math.hypot(dx, dy) || 0.01;
      if (dist > repulseCutoff) continue;
      const weight = (degrees.get(a.id) || 1) + (degrees.get(b.id) || 1);
      const repulse = (repulsionStrength * weight) / (dist * dist);
      dx = (dx / dist) * repulse;
      dy = (dy / dist) * repulse;
      if (!centerIds.has(a.id) && !a.pinned) {
        a.vx -= dx;
        a.vy -= dy;
      }
      if (!centerIds.has(b.id) && !b.pinned) {
        b.vx += dx;
        b.vy += dy;
      }
    }
  }
  }

  for (const edge of edges) {
    const source = nodeById.get(edge.from);
    const target = nodeById.get(edge.to);
    if (!source || !target) continue;
    let dx = target.x - source.x;
    let dy = target.y - source.y;
    let dist = Math.hypot(dx, dy) || 0.01;
    const ideal = edge.weak ? 132 : 96;
    const spring = edge.weak ? 0.008 : 0.018;
    let pull = (dist - ideal) * spring * forceAlpha;
    pull = Math.max(-1.8, Math.min(1.8, pull));
    dx = (dx / dist) * pull;
    dy = (dy / dist) * pull;
    if (!centerIds.has(source.id) && !source.pinned) {
      source.vx += dx;
      source.vy += dy;
    }
    if (!centerIds.has(target.id) && !target.pinned) {
      target.vx -= dx;
      target.vy -= dy;
    }
  }

  for (const node of nodes) {
    if (centerIds.has(node.id)) {
      node.x = width / 2;
      node.y = height / 2;
      node.vx = 0;
      node.vy = 0;
      continue;
    }
    if (node.pinned) {
      node.vx = 0;
      node.vy = 0;
      continue;
    }
    node.vx += (width / 2 - node.x) * 0.0011 * forceAlpha;
    node.vy += (height / 2 - node.y) * 0.0011 * forceAlpha;

    if (sim.phase === "idle") {
      const drift = node.floatRadius || 1;
      const t = sim.floatTime * 0.014;
      node.vx += Math.cos(t * drift + node.floatPhase) * 0.014;
      node.vy += Math.sin(t * drift * 1.08 + node.floatPhase * 1.17) * 0.014;
    }

    node.vx *= sim.phase === "idle" ? 0.88 : 0.76;
    node.vy *= sim.phase === "idle" ? 0.88 : 0.76;
    clampGraphNodeVelocity(node, maxVelocity);
    node.x += node.vx;
    node.y += node.vy;
  }

  return true;
}

function reheatObsidianGraphSimulation(sim, alpha = 0.42) {
  sim.phase = "settling";
  sim.alpha = Math.max(sim.alpha, alpha);
  sim.floatTime = 0;
}

function updateAllGraphVisuals(nodeById, nodeElements, linkElements) {
  for (const [nodeId, nodeState] of nodeElements.entries()) {
    const node = nodeById.get(nodeId);
    if (!node) continue;
    const labelOffset = getGraphNodeLabelYOffset(
      nodeState.radius,
      nodeState.previewCardH || nodeState.previewSize,
      nodeState.labelSubLineCount || 0
    );
    if (nodeState.glow) {
      nodeState.glow.setAttribute("cx", String(node.x));
      nodeState.glow.setAttribute("cy", String(node.y));
    }
    nodeState.circle.setAttribute("cx", String(node.x));
    nodeState.circle.setAttribute("cy", String(node.y));
    if (nodeState.dotIdLabel) {
      nodeState.dotIdLabel.setAttribute("x", String(node.x));
      nodeState.dotIdLabel.setAttribute("y", String(node.y - nodeState.radius - 5));
    }
    if (nodeState.dotStatusMark) {
      const mx = node.x + nodeState.radius * 0.78;
      const my = node.y + nodeState.radius * 0.78;
      nodeState.dotStatusMark.setAttribute("cx", String(mx));
      nodeState.dotStatusMark.setAttribute("cy", String(my));
    }
    if (nodeState.dotStatusEmoji) {
      const mx = node.x + nodeState.radius * 0.78;
      const my = node.y + nodeState.radius * 0.78;
      nodeState.dotStatusEmoji.setAttribute("x", String(mx));
      nodeState.dotStatusEmoji.setAttribute("y", String(my + 0.5));
    }
    if (nodeState.previewGroup) {
      const cardW = nodeState.previewCardW || nodeState.previewSize;
      const cardH = nodeState.previewCardH || nodeState.previewSize;
      nodeState.previewGroup.setAttribute(
        "transform",
        `translate(${node.x - cardW / 2} ${node.y - cardH / 2})`
      );
    }
    if (nodeState.glyph) {
      nodeState.glyph.setAttribute("x", String(node.x));
      nodeState.glyph.setAttribute("y", String(node.y));
    }
    nodeState.label.setAttribute("x", String(node.x));
    nodeState.label.setAttribute("y", String(node.y + labelOffset));
    nodeState.label.querySelectorAll("tspan").forEach((tspan) => {
      tspan.setAttribute("x", String(node.x));
    });
  }
  for (const line of linkElements) {
    const from = nodeById.get(line.from);
    const to = nodeById.get(line.to);
    if (!from || !to) continue;
    line.el.setAttribute("x1", String(from.x));
    line.el.setAttribute("y1", String(from.y));
    line.el.setAttribute("x2", String(to.x));
    line.el.setAttribute("y2", String(to.y));
  }
}

function nodeMatchesGraphSearch(node, query) {
  const q = String(query || "").trim().toLowerCase();
  if (!q) return false;
  const haystack = [
    node?.label,
    node?.graphSubLabel,
    node?.graphAwnId,
    node?.nodePath,
    node?.filePath,
    node?.id
  ]
    .map((part) => String(part || "").toLowerCase())
    .filter(Boolean);
  return haystack.some((part) => part.includes(q));
}

function getGraphNodePreviewSize(node, showPreviews = false) {
  if (!showPreviews || !node.previewUrl) return 0;
  const nodePath = node.nodePath || node.filePath || "";
  if (isBrokenImageSrc(node.previewUrl, nodePath)) return 0;
  return isGraphFolderLikeType(node.type) ? 60 : 54;
}

function hasGraphPreviewTopMetaBar(node) {
  const statusRaw = String(node?.graphStatus || "").trim();
  const awnId = normalizeAwnIdDisplayValue(node?.graphAwnId || "");
  return Boolean(statusRaw || awnId);
}

function getGraphPreviewTopBarHeight(cardW) {
  return Math.max(16, Math.round(cardW * 0.22));
}

function getGraphPreviewCardLayout(node, showPreviews = false) {
  const cardW = getGraphNodePreviewSize(node, showPreviews);
  if (!cardW) return null;
  const topBarH = hasGraphPreviewTopMetaBar(node) ? getGraphPreviewTopBarHeight(cardW) : 0;
  const imageH = cardW;
  const cardH = topBarH + imageH;
  return { cardW, topBarH, imageH, cardH };
}

function resolveGraphPreviewPathKey(scopePrefix, pathParts, endIndexInclusive) {
  const rel = pathParts.slice(0, endIndexInclusive + 1).join("/");
  if (!rel) return "";
  return scopePrefix ? `${scopePrefix}/${rel}` : rel;
}

function resolveGraphFolderPreviewUrl(previewByDisplayPath, scopePrefix, pathParts, endIndexInclusive) {
  if (!previewByDisplayPath?.size) return null;
  const scopedKey = resolveGraphPreviewPathKey(scopePrefix, pathParts, endIndexInclusive);
  const plainKey = pathParts.slice(0, endIndexInclusive + 1).join("/");
  return previewByDisplayPath.get(scopedKey) || previewByDisplayPath.get(plainKey) || null;
}

function getGraphPreviewChromeBarHeight(previewSize) {
  return getGraphPreviewTopBarHeight(previewSize);
}

function markGraphNodePreviewMissing(group, nodeState, node, degrees) {
  if (!group || !nodeState || group.classList.contains("preview-missing")) return;
  group.classList.remove("has-preview");
  group.classList.add("preview-missing");
  if (nodeState.previewGroup) {
    nodeState.previewGroup.setAttribute("visibility", "hidden");
  }
  nodeState.circle.removeAttribute("visibility");
  const fallbackRadius = getGraphNodeRadius(node, degrees, false);
  nodeState.radius = fallbackRadius;
  nodeState.previewSize = 0;
  if (!nodeState.glow) {
    const glow = document.createElementNS("http://www.w3.org/2000/svg", "circle");
    glow.setAttribute("cx", String(node.x));
    glow.setAttribute("cy", String(node.y));
    glow.setAttribute(
      "class",
      `external-graph-glow ${node.type}${node.isSatelliteRoot ? " is-satellite-root" : ""}`.trim()
    );
    group.insertBefore(glow, group.firstChild);
    nodeState.glow = glow;
  }
  nodeState.glow.setAttribute("r", String(fallbackRadius + 7));
  nodeState.circle.setAttribute("r", String(fallbackRadius));
  if (nodeState.glyph) {
    nodeState.glyph.removeAttribute("visibility");
    nodeState.glyph.setAttribute("y", String(node.y));
  }
}

function getGraphNodeRadius(node, degrees, showPreviews = false) {
  const layout = getGraphPreviewCardLayout(node, showPreviews);
  if (layout) return layout.cardH / 2 + 3;
  const degree = degrees.get(node.id) || 1;
  if (node.id === "root" || node.id === "agent-root") return 5 + Math.min(4, degree * 0.35);
  if (node.isSatelliteRoot) return 11 + Math.min(3, Math.sqrt(degree) * 0.35);
  if (resolveGraphNodeGlyph(node)) return 7 + Math.min(2.5, Math.sqrt(degree) * 0.45);
  if (isGraphFolderLikeType(node.type)) return 4 + Math.min(3, Math.sqrt(degree) * 0.9);
  return 3 + Math.min(2.5, Math.sqrt(degree) * 0.65);
}

function resolveGraphPreviewUrl(node) {
  if (!node?.previewUrl) return "";
  return appendMediaThumbToApiUrl(
    appendCacheBuster(appendAgentToApiUrl(node.previewUrl)),
    MEDIA_THUMB_MAX_GRID
  );
}

function sanitizeGraphDomId(value) {
  return String(value || "node").replace(/[^a-zA-Z0-9_-]/g, "-");
}

function attachGraphControlHandlers(controlsHost, getViewportContext) {
  if (!controlsHost) return () => {};

  if (controlsHost._graphControlHandler) {
    controlsHost.removeEventListener("click", controlsHost._graphControlHandler);
    controlsHost._graphControlHandler = null;
  }

  const handler = (event) => {
    const button = event.target.closest("[data-action]");
    if (!button) return;
    const ctx = getViewportContext();
    if (!ctx?.wrap?.isConnected) return;

    const { svg, state, fitToView, applyTransform } = ctx;
    const rect = svg.getBoundingClientRect();
    const cx = rect.width / 2;
    const cy = rect.height / 2;

    if (button.dataset.action === "reset") {
      fitToView();
      return;
    }

    const factor = button.dataset.action === "zoom-in" ? 1.15 : 0.87;
    const nextScale = Math.min(3.2, Math.max(0.18, state.scale * factor));
    state.tx = cx - ((cx - state.tx) * nextScale) / state.scale;
    state.ty = cy - ((cy - state.ty) * nextScale) / state.scale;
    state.scale = nextScale;
    applyTransform();
  };

  controlsHost._graphControlHandler = handler;
  controlsHost.addEventListener("click", handler);
  return () => {
    controlsHost.removeEventListener("click", handler);
    if (controlsHost._graphControlHandler === handler) {
      controlsHost._graphControlHandler = null;
    }
  };
}

function attachObsidianGraphViewport(
  wrap,
  svg,
  viewport,
  sim,
  nodeElements,
  linkElements,
  degrees,
  showPreviews = false,
  controlsHost = null
) {
  const positioned = sim.nodes;
  const nodeById = sim.nodeById;
  let layoutBounds = computeGraphLayoutBounds(positioned, degrees, 64, showPreviews);
  let hasAutoFitted = false;
  let rafId = 0;

  const state = {
    scale: 1,
    tx: 0,
    ty: 0,
    panning: false,
    panStartX: 0,
    panStartY: 0,
    panOriginTx: 0,
    panOriginTy: 0,
    draggingNode: null,
    dragOffsetX: 0,
    dragOffsetY: 0,
    dragMoved: false,
    dragStartX: 0,
    dragStartY: 0
  };

  const applyTransform = () => {
    viewport.setAttribute("transform", `translate(${state.tx} ${state.ty}) scale(${state.scale})`);
  };

  const fitToView = () => {
    layoutBounds = computeGraphLayoutBounds(positioned, degrees, 72, showPreviews);
    const rect = svg.getBoundingClientRect();
    if (!rect.width || !rect.height) return;
    const padding = 56;
    const scaleX = (rect.width - padding * 2) / layoutBounds.width;
    const scaleY = (rect.height - padding * 2) / layoutBounds.height;
    state.scale = Math.min(Math.max(Math.min(scaleX, scaleY), 0.22), 1.55);
    state.tx = (rect.width - layoutBounds.width * state.scale) / 2 - layoutBounds.minX * state.scale;
    state.ty = (rect.height - layoutBounds.height * state.scale) / 2 - layoutBounds.minY * state.scale;
    applyTransform();
  };

  const clientToGraph = (clientX, clientY) => {
    const rect = svg.getBoundingClientRect();
    return {
      x: (clientX - rect.left - state.tx) / state.scale,
      y: (clientY - rect.top - state.ty) / state.scale
    };
  };

  const refreshGraphVisuals = () => {
    updateAllGraphVisuals(nodeById, nodeElements, linkElements);
  };

  const runSimulationFrame = () => {
    if (!wrap.isConnected) return;
    tickObsidianGraphSimulation(sim);
    refreshGraphVisuals();

    if (!hasAutoFitted && sim.phase === "idle") {
      fitToView();
      hasAutoFitted = true;
      wrap.classList.remove("is-entering", "is-simulating");
      wrap.classList.add("is-settled");
    }

    rafId = requestAnimationFrame(runSimulationFrame);
  };

  wrap.classList.add("is-simulating", "is-entering");
  warmUpObsidianGraphSimulation(sim);
  sim.phase = "settling";
  sim.alpha = 0.48;
  sim.floatTime = 0;
  refreshGraphVisuals();
  fitToView();
  hasAutoFitted = true;
  wrap.classList.remove("is-entering");
  wrap.classList.add("is-settled");
  rafId = requestAnimationFrame(runSimulationFrame);

  let searchQuery = "";

  const clearFocus = () => {
    wrap.classList.remove("is-focusing");
    for (const group of nodeElements.values()) group.el.classList.remove("highlighted");
    for (const line of linkElements) line.el.classList.remove("highlighted");
  };

  const focusNode = (nodeId) => {
    const neighbors = buildGraphAdjacency(
      linkElements.map((line) => ({ from: line.from, to: line.to }))
    );
    const related = new Set([nodeId, ...(neighbors.get(nodeId) || [])]);
    wrap.classList.add("is-focusing");
    for (const [id, group] of nodeElements.entries()) {
      group.el.classList.toggle("highlighted", related.has(id));
    }
    for (const line of linkElements) {
      line.el.classList.toggle(
        "highlighted",
        related.has(line.from) && related.has(line.to)
      );
    }
  };

  const applySearchQuery = (query) => {
    searchQuery = String(query || "");
    const q = searchQuery.trim();
    if (!q) {
      clearFocus();
      return;
    }
    const matched = new Set();
    for (const node of positioned) {
      if (nodeMatchesGraphSearch(node, q)) matched.add(node.id);
    }
    wrap.classList.add("is-focusing");
    if (!matched.size) {
      for (const group of nodeElements.values()) group.el.classList.remove("highlighted");
      for (const line of linkElements) line.el.classList.remove("highlighted");
      return;
    }
    const highlighted = expandGraphSearchHighlightIds(matched, linkElements);
    for (const [id, group] of nodeElements.entries()) {
      group.el.classList.toggle("highlighted", highlighted.has(id));
    }
    for (const line of linkElements) {
      line.el.classList.toggle(
        "highlighted",
        highlighted.has(line.from) && highlighted.has(line.to)
      );
    }
  };

  const restoreFocusAfterHover = () => {
    if (searchQuery.trim()) applySearchQuery(searchQuery);
    else clearFocus();
  };

  wrap.addEventListener("wheel", (event) => {
    event.preventDefault();
    const rect = svg.getBoundingClientRect();
    const mx = event.clientX - rect.left;
    const my = event.clientY - rect.top;
    const factor = event.deltaY > 0 ? 0.92 : 1.08;
    const nextScale = Math.min(3.2, Math.max(0.18, state.scale * factor));
    state.tx = mx - ((mx - state.tx) * nextScale) / state.scale;
    state.ty = my - ((my - state.ty) * nextScale) / state.scale;
    state.scale = nextScale;
    applyTransform();
  }, { passive: false });

  svg.addEventListener("mousedown", (event) => {
    if (event.button !== 0) return;
    const targetGroup = event.target.closest?.(".external-graph-node");
    if (targetGroup) {
      const nodeId = targetGroup.dataset.nodeId;
      const node = positioned.find((entry) => entry.id === nodeId);
      if (!node) return;
      const point = clientToGraph(event.clientX, event.clientY);
      state.draggingNode = node;
      state.dragOffsetX = node.x - point.x;
      state.dragOffsetY = node.y - point.y;
      state.dragMoved = false;
      state.dragStartX = event.clientX;
      state.dragStartY = event.clientY;
      if (!sim.centerIds.has(node.id)) node.pinned = true;
      wrap.classList.add("is-dragging-node");
      bindPointerTracking();
      event.preventDefault();
      return;
    }
    state.panning = true;
    state.panStartX = event.clientX;
    state.panStartY = event.clientY;
    state.panOriginTx = state.tx;
    state.panOriginTy = state.ty;
    wrap.classList.add("is-panning");
    bindPointerTracking();
  });

  const onMouseMove = (event) => {
    if (state.draggingNode) {
      if (
        !state.dragMoved &&
        Math.hypot(event.clientX - state.dragStartX, event.clientY - state.dragStartY) > 4
      ) {
        state.dragMoved = true;
      }
      const point = clientToGraph(event.clientX, event.clientY);
      state.draggingNode.x = point.x + state.dragOffsetX;
      state.draggingNode.y = point.y + state.dragOffsetY;
      refreshGraphVisuals();
      return;
    }
    if (!state.panning) return;
    state.tx = state.panOriginTx + (event.clientX - state.panStartX);
    state.ty = state.panOriginTy + (event.clientY - state.panStartY);
    applyTransform();
  };

  const endInteraction = () => {
    if (state.draggingNode && !sim.centerIds.has(state.draggingNode.id)) {
      state.draggingNode.pinned = false;
      reheatObsidianGraphSimulation(sim);
    }
    state.panning = false;
    state.draggingNode = null;
    wrap.classList.remove("is-panning", "is-dragging-node");
    window.removeEventListener("mousemove", onMouseMove);
    window.removeEventListener("mouseup", onMouseUp);
  };

  const onMouseUp = () => {
    if (state.dragMoved) wrap.dataset.graphDragged = "true";
    endInteraction();
  };

  const bindPointerTracking = () => {
    window.addEventListener("mousemove", onMouseMove);
    window.addEventListener("mouseup", onMouseUp);
  };

  svg.addEventListener("dblclick", (event) => {
    if (event.target.closest?.(".external-graph-node")) return;
    fitToView();
  });

  for (const [nodeId, group] of nodeElements.entries()) {
    group.el.addEventListener("mouseenter", () => {
      if (searchQuery.trim()) return;
      focusNode(nodeId);
    });
    group.el.addEventListener("mouseleave", restoreFocusAfterHover);
  }

  const getViewportContext = () =>
    wrap.isConnected ? { wrap, svg, state, fitToView, applyTransform } : null;

  const detachControls = attachGraphControlHandlers(controlsHost, getViewportContext);

  if (!controlsHost) {
    const controls = document.createElement("div");
    controls.className = "external-graph-controls";
    controls.innerHTML = `
      <button type="button" class="external-graph-control-btn" data-action="zoom-in" title="Приблизить">+</button>
      <button type="button" class="external-graph-control-btn" data-action="zoom-out" title="Отдалить">−</button>
      <button type="button" class="external-graph-control-btn" data-action="reset" title="Сбросить вид">⟲</button>
    `;
    attachGraphControlHandlers(controls, getViewportContext);
    wrap.appendChild(controls);
  }

  const observer = new MutationObserver(() => {
    if (!wrap.isConnected) {
      detachControls();
      observer.disconnect();
    }
  });
  observer.observe(wrap.parentElement || document.body, { childList: true });

  return {
    setSearchQuery: applySearchQuery,
    getSearchQuery: () => searchQuery,
    clearFocus,
    focusNode
  };
}

function buildGraphDataFromExternalFiles(items) {
  const nodes = [
    { id: "root", label: STORAGE_SUBFOLDER_CONTENT, filePath: null, type: "folder", depth: 0 }
  ];
  const edges = [];
  const folderIds = new Set(["root"]);
  const fileIdsByParent = new Map();

  function ensureFolder(folderPath) {
    if (!folderPath || folderPath === ".") return "root";
    const parts = folderPath.split("/").filter(Boolean);
    let parentId = "root";
    let builtPath = "";
    for (let i = 0; i < parts.length; i += 1) {
      builtPath = builtPath ? `${builtPath}/${parts[i]}` : parts[i];
      const folderId = `folder:${builtPath}`;
      if (!folderIds.has(folderId)) {
        nodes.push({
          id: folderId,
          label: getMemorySectionDisplayLabel(builtPath) || parts[i],
          filePath: null,
          folderPath: builtPath,
          type: "folder",
          depth: i + 1
        });
        edges.push({ from: parentId, to: folderId });
        folderIds.add(folderId);
      }
      parentId = folderId;
    }
    return `folder:${folderPath}`;
  }

  for (const folder of externalFoldersCache) {
    const folderPath = String(folder.path || "").replace(/\\/g, "/").replace(/\/$/, "");
    if (folderPath) ensureFolder(folderPath);
  }

  for (const item of items) {
    const parentPath = item.parent && item.parent !== "." ? item.parent : ".";
    const parentId = ensureFolder(parentPath === "." ? null : parentPath);
    const fileId = `file:${item.path}`;
    const depth = parentPath && parentPath !== "." ? parentPath.split("/").filter(Boolean).length + 1 : 1;
    nodes.push({
      id: fileId,
      label: item.title,
      filePath: item.path,
      type: "file",
      depth,
      previewUrl: item.previewUrl || null
    });
    edges.push({ from: parentId, to: fileId });
    if (!fileIdsByParent.has(parentPath)) fileIdsByParent.set(parentPath, []);
    fileIdsByParent.get(parentPath).push(fileId);
  }

  for (const group of fileIdsByParent.values()) {
    if (group.length < 2 || group.length > 8) continue;
    for (let i = 0; i < group.length - 1; i += 1) {
      edges.push({ from: group[i], to: group[i + 1], weak: true });
    }
  }

  return { nodes, edges };
}

function buildGraphDataFromNode() {
  const nodeLabel = activeLabel || getLabelFromPath(activePath) || "Тема";
  const nodes = [{ id: "root", label: nodeLabel, type: "folder", depth: 0 }];
  const edges = [];

  for (const group of getNodeGraphModeGroups()) {
    const hubId = `hub:${group.id}`;
    nodes.push({
      id: hubId,
      label: group.title,
      type: "folder",
      depth: 1
    });
    edges.push({ from: "root", to: hubId });

    for (const mode of group.modes) {
      const modeNodeId = `mode:${mode.id}`;
      nodes.push({
        id: modeNodeId,
        label: mode.label,
        type: "file",
        depth: 2,
        modeId: mode.id,
        disabled: Boolean(mode.disabled)
      });
      edges.push({ from: hubId, to: modeNodeId });
    }
  }

  return { nodes, edges };
}

