function renderGraphCanvas(container, graph, options = {}) {
  const {
    ariaLabel = "Граф",
    fullViewport = false,
    showPreviews = false,
    controlsHost = null,
    isNodeActive = () => false,
    isNodeClickable = (node) => Boolean(node.filePath || (node.modeId && !node.disabled)),
    onNodeClick = () => {},
    onViewportReady = null
  } = options;

  const ns = "http://www.w3.org/2000/svg";
  const nodeCount = graph.nodes.length;
  const containerWidth = container.clientWidth || listViewContentNode?.clientWidth || 920;
  const containerHeight = container.clientHeight || 0;
  const { width, height } = getObsidianGraphLayoutSize(
    nodeCount,
    containerWidth,
    containerHeight,
    fullViewport
  );

  const wrap = document.createElement("div");
  wrap.className = "external-graph-wrap node-graph-wrap";
  if (options.markdownDepth) {
    wrap.dataset.rmmMarkdownDepth = normalizeAgentRoadmapMapDepth(options.markdownDepth);
  }
  const canvasTheme = getAgentGraphSettings().canvasTheme;
  wrap.classList.add(canvasTheme === "light" ? "is-light" : "is-dark");
  if (showPreviews) wrap.classList.add("external-graph-wrap--previews");
  appendCosmicGraphBackground(wrap);

  const svg = document.createElementNS(ns, "svg");
  svg.setAttribute("class", "external-graph-canvas");
  svg.setAttribute("role", "img");
  svg.setAttribute("aria-label", ariaLabel);
  svg.setAttribute("width", "100%");
  svg.setAttribute("height", "100%");

  const sim = createObsidianGraphSimulation(graph.nodes, graph.edges, width, height, { showPreviews });
  const positioned = sim.nodes;
  const degrees = sim.degrees;
  const nodeById = sim.nodeById;

  const viewport = document.createElementNS(ns, "g");
  viewport.setAttribute("class", "external-graph-viewport");

  const defs = document.createElementNS(ns, "defs");
  viewport.appendChild(defs);

  const linksLayer = document.createElementNS(ns, "g");
  linksLayer.setAttribute("class", "external-graph-links");
  const linkElements = [];

  for (const edge of graph.edges) {
    const from = nodeById.get(edge.from);
    const to = nodeById.get(edge.to);
    if (!from || !to) continue;
    const line = document.createElementNS(ns, "line");
    line.setAttribute("x1", String(from.x));
    line.setAttribute("y1", String(from.y));
    line.setAttribute("x2", String(to.x));
    line.setAttribute("y2", String(to.y));
    line.setAttribute(
      "class",
      edge.weak ? "external-graph-link external-graph-link-weak" : "external-graph-link"
    );
    line.dataset.from = edge.from;
    line.dataset.to = edge.to;
    linksLayer.appendChild(line);
    linkElements.push({ el: line, from: edge.from, to: edge.to });
  }
  viewport.appendChild(linksLayer);

  const nodesLayer = document.createElementNS(ns, "g");
  nodesLayer.setAttribute("class", "external-graph-nodes");
  const nodeElements = new Map();

  for (const node of positioned) {
    const previewLayout = getGraphPreviewCardLayout(node, showPreviews);
    const previewSize = previewLayout?.cardW || 0;
    const radius = getGraphNodeRadius(node, degrees, showPreviews);
    const isActive = isNodeActive(node);
    const isDisabled = Boolean(node.disabled);
    const clickable = !isDisabled && isNodeClickable(node);

    const graphGlyph = resolveGraphNodeGlyph(node);
    const group = document.createElementNS(ns, "g");
    group.dataset.nodeId = node.id;
    group.setAttribute(
      "class",
      `external-graph-node${isActive ? " active" : ""}${isDisabled ? " disabled" : ""}${previewSize ? " has-preview" : ""}${showPreviews && !previewSize ? " preview-missing" : ""}${node.isSatelliteRoot ? " is-satellite-root" : ""}${graphGlyph ? " has-glyph" : ""}`.trim()
    );
    group.style.cursor = clickable ? "pointer" : "grab";

    let glow = null;
    if (!previewSize) {
      glow = document.createElementNS(ns, "circle");
      glow.setAttribute("cx", String(node.x));
      glow.setAttribute("cy", String(node.y));
      glow.setAttribute("r", String(radius + (node.isSatelliteRoot ? 9 : 7)));
      glow.setAttribute(
        "class",
        `external-graph-glow ${node.type}${node.isSatelliteRoot ? " is-satellite-root" : ""}${isActive ? " active" : ""}`.trim()
      );
      group.appendChild(glow);
    }

    let previewFrame = null;
    let previewImage = null;
    let previewGroup = null;
    const circle = document.createElementNS(ns, "circle");
    circle.setAttribute("cx", String(node.x));
    circle.setAttribute("cy", String(node.y));
    circle.setAttribute("r", String(radius));
    circle.setAttribute(
      "class",
      `external-graph-dot ${node.type}${node.isSatelliteRoot ? " is-satellite-root" : ""}${isActive ? " active" : ""}`.trim()
    );

    let glyph = null;
    if (graphGlyph) {
      glyph = document.createElementNS(ns, "text");
      glyph.setAttribute("x", String(node.x));
      glyph.setAttribute("y", String(node.y));
      glyph.setAttribute("text-anchor", "middle");
      glyph.setAttribute("dominant-baseline", "central");
      glyph.setAttribute(
        "class",
        `external-graph-glyph ${node.type}${node.isSatelliteRoot ? " is-satellite-root" : ""}`.trim()
      );
      glyph.textContent = graphGlyph;
      if (previewSize) glyph.setAttribute("visibility", "hidden");
      group.appendChild(glyph);
    }

    if (previewLayout) {
      circle.setAttribute("visibility", "hidden");
      const { cardW, topBarH, imageH, cardH } = previewLayout;
      const imageY = topBarH;
      const clipId = `graph-preview-${sanitizeGraphDomId(node.id)}`;
      const clipPath = document.createElementNS(ns, "clipPath");
      clipPath.setAttribute("id", clipId);
      const clipShape = document.createElementNS(ns, "rect");
      clipShape.setAttribute("x", "0");
      clipShape.setAttribute("y", String(imageY));
      clipShape.setAttribute("width", String(cardW));
      clipShape.setAttribute("height", String(imageH));
      clipShape.setAttribute("rx", isGraphFolderLikeType(node.type) ? "6" : "4");
      clipPath.appendChild(clipShape);
      defs.appendChild(clipPath);

      previewGroup = document.createElementNS(ns, "g");
      previewGroup.setAttribute("class", "external-graph-preview-group");
      previewGroup.setAttribute(
        "transform",
        `translate(${node.x - cardW / 2} ${node.y - cardH / 2})`
      );

      const haloPad = 6;
      const haloRx = isGraphFolderLikeType(node.type) ? 8 : 6;
      const previewHalo = document.createElementNS(ns, "rect");
      previewHalo.setAttribute("x", String(-haloPad));
      previewHalo.setAttribute("y", String(-haloPad));
      previewHalo.setAttribute("width", String(cardW + haloPad * 2));
      previewHalo.setAttribute("height", String(cardH + haloPad * 2));
      previewHalo.setAttribute("rx", String(haloRx));
      previewHalo.setAttribute(
        "class",
        `external-graph-preview-halo ${node.type}${node.isSatelliteRoot ? " is-satellite-root" : ""}${isActive ? " active" : ""}`.trim()
      );
      previewGroup.appendChild(previewHalo);

      appendGraphNodePreviewMeta(previewGroup, ns, node, cardW, topBarH);

      previewFrame = document.createElementNS(ns, "rect");
      previewFrame.setAttribute("x", "0");
      previewFrame.setAttribute("y", String(imageY));
      previewFrame.setAttribute("width", String(cardW));
      previewFrame.setAttribute("height", String(imageH));
      previewFrame.setAttribute("rx", isGraphFolderLikeType(node.type) ? "6" : "4");
      previewFrame.setAttribute(
        "class",
        `external-graph-preview-media-bg external-graph-preview-frame ${node.type}${isActive ? " active" : ""}`.trim()
      );
      previewGroup.appendChild(previewFrame);

      previewImage = document.createElementNS(ns, "image");
      previewImage.setAttribute("x", "0");
      previewImage.setAttribute("y", String(imageY));
      previewImage.setAttribute("href", resolveGraphPreviewUrl(node));
      previewImage.setAttribute("width", String(cardW));
      previewImage.setAttribute("height", String(imageH));
      previewImage.setAttribute("clip-path", `url(#${clipId})`);
      previewImage.setAttribute("preserveAspectRatio", "none");
      previewImage.setAttribute("class", "external-graph-preview-image");
      previewGroup.appendChild(previewImage);

      group.appendChild(previewGroup);
    }

    group.appendChild(circle);

    const dotMeta = !previewSize ? appendGraphNodeDotMeta(group, ns, node, node.x, node.y, radius, circle) : null;

    const { label, labelTitle, labelSub, labelOffset, labelSubLineCount } = appendGraphNodeLabel(
      group,
      ns,
      node,
      node.x,
      node.y,
      radius,
      previewLayout?.cardH || 0
    );

    const lines = linkElements.filter((line) => line.from === node.id || line.to === node.id);
    const nodeState = {
      el: group,
      glow,
      circle,
      glyph,
      label,
      labelTitle,
      labelSub,
      labelOffset,
      labelSubLineCount,
      radius,
      previewSize: previewLayout?.cardW || 0,
      previewCardW: previewLayout?.cardW || 0,
      previewCardH: previewLayout?.cardH || 0,
      previewTopBarH: previewLayout?.topBarH || 0,
      previewImageH: previewLayout?.imageH || 0,
      previewBarH: previewLayout?.topBarH || 0,
      previewGroup,
      previewFrame,
      previewImage,
      dotIdLabel: dotMeta?.dotIdLabel || null,
      dotStatusMark: dotMeta?.dotStatusMark || null,
      dotStatusEmoji: dotMeta?.dotStatusEmoji || null,
      lines
    };

    if (previewImage) {
      previewImage.addEventListener(
        "load",
        () => {
          previewImage.classList.add("is-loaded");
        },
        { once: true }
      );
      previewImage.addEventListener(
        "error",
        () => markGraphNodePreviewMissing(group, nodeState, node, degrees),
        { once: true }
      );
    }

    nodeElements.set(node.id, nodeState);

    group.addEventListener("mouseenter", () => {
      group.classList.add("hovered");
    });
    group.addEventListener("mouseleave", () => {
      group.classList.remove("hovered");
    });

    if (clickable) {
      group.addEventListener("click", (event) => {
        if (wrap.dataset.graphDragged === "true") {
          wrap.dataset.graphDragged = "false";
          return;
        }
        event.stopPropagation();
        onNodeClick(node);
      });
    }

    nodesLayer.appendChild(group);
  }

  viewport.appendChild(nodesLayer);
  svg.appendChild(viewport);
  wrap.appendChild(svg);
  container.appendChild(wrap);

  const graphViewportApi = attachObsidianGraphViewport(
    wrap,
    svg,
    viewport,
    sim,
    nodeElements,
    linkElements,
    degrees,
    showPreviews,
    controlsHost
  );
  if (typeof onViewportReady === "function") {
    onViewportReady(graphViewportApi, wrap);
  }
}

function renderNodeGraphView() {
  if (!graphViewContentNode) return;
  graphViewContentNode.innerHTML = "";
  const render = () => {
    const graph = buildGraphDataFromNode();
    renderGraphCanvas(graphViewContentNode, graph, {
      ariaLabel: "Граф пространства",
      isNodeActive: (node) => Boolean(node.modeId && node.modeId === activeContentMode),
      isNodeClickable: (node) => Boolean(node.modeId && !node.disabled),
      onNodeClick: (node) => {
        setContentMode(node.modeId);
      }
    });
  };
  requestAnimationFrame(render);
}

