function getMediaStorageContextPath(nodePath = activePath) {
  const manifestBase = getResolvedNodePath(nodePath);
  if (!manifestBase) return "";
  return getNodeStorageSubfolderPath(manifestBase, "media");
}

function resolveMediaAssetContextPath(nodePath = activePath) {
  const manifestPath = resolveManifestPathForNodeApi(getResolvedNodePath(nodePath));

  if (activeContentMode === NODE_ENTRY_OVERVIEW_MODE && activeEntryOverviewContext) {
    if (
      activeEntryOverviewContext.memoryKind === "media" ||
      activeEntryOverviewContext.memoryKind === "assets"
    ) {
      return manifestPath;
    }
    if (!isEntryOverviewMemoryTocRoot(activeEntryOverviewContext)) {
      const relPath = String(activeEntryOverviewContext.relPath || "").replace(/\\/g, "/");
      if (/\.md$/i.test(relPath)) return relPath;
      return manifestPath;
    }
  }

  return getPropsContextPath(nodePath) || manifestPath || getUploadStorageContextPath();
}

function buildMediaAssetUrl(filePath, nodePath = activePath, options = {}) {
  if (!nodePath || !filePath) return "";
  if (shouldUseFlexibleSlotAssetUrls(nodePath)) {
    return buildFlexibleSlotWorkspaceAssetUrl(filePath, nodePath, options);
  }
  const manifestBase = getResolvedNodePath(nodePath);
  const memoryKind =
    options.memoryKind ||
    (activeEntryOverviewContext?.memoryKind
      ? resolveMediaLibraryBrowseMode(activeEntryOverviewContext.memoryKind, nodePath)
      : activeContentMode === "assets"
        ? "assets"
        : resolveMediaLibraryBrowseMode(activeContentMode, nodePath));
  const flatMemoryKind = resolveEntryOverviewStorageMemoryKind(
    {
      memoryKind,
      relPath: activeEntryOverviewContext?.relPath,
      relativePath: String(filePath || "")
    },
    nodePath
  );
  const params = {
    path: resolveManifestPathForNodeApi(manifestBase),
    contextPath: resolveMediaAssetContextPath(nodePath),
    file: normalizeMarkdownImageFileRef(filePath)
  };
  const libraryFolder = isFlatEntryOverviewMemoryKind(flatMemoryKind)
    ? getFlatStorageSectionFolderName(flatMemoryKind)
    : getMediaLibraryStorageSubfolder(memoryKind);
  if (libraryFolder && libraryFolder !== STORAGE_SUBFOLDER_MEDIA) params.folder = libraryFolder;
  if (options.thumb) {
    params.thumb = "1";
    params.max = String(options.max ?? MEDIA_THUMB_MAX_DEFAULT);
  }
  return buildApiUrl("/api/media/file", params);
}

const MEDIA_THUMB_MAX_SMALL = 160;
const MEDIA_THUMB_MAX_DEFAULT = 320;
const MEDIA_THUMB_MAX_GRID = 480;
const MEDIA_THUMB_MAX_PREVIEW = 800;
const MEDIA_THUMB_MAX_AVATAR = 640;

function buildMediaThumbUrl(filePath, nodePath = activePath, max = MEDIA_THUMB_MAX_DEFAULT) {
  return buildMediaAssetUrl(filePath, nodePath, { thumb: true, max });
}

function resolveMediaAssetCacheBustToken(itemOrPath) {
  if (itemOrPath && typeof itemOrPath === "object") {
    const updatedAt = itemOrPath.updatedAt || itemOrPath.mtime || null;
    if (updatedAt) return String(updatedAt);
    const path = String(itemOrPath.path || "").trim();
    if (itemOrPath.size != null && path) return `${path}::${itemOrPath.size}`;
    if (path) return path;
  }
  const path = typeof itemOrPath === "string" ? itemOrPath.trim() : "";
  return path;
}

function appendMediaCacheBuster(url, itemOrPath) {
  if (!url) return url;
  const token = resolveMediaAssetCacheBustToken(itemOrPath);
  if (!token) return url;
  return appendCacheBuster(url, token);
}

function appendMediaThumbToApiUrl(url, max = MEDIA_THUMB_MAX_DEFAULT) {
  const raw = String(url || "").trim();
  if (!raw) return raw;
  if (/[?&]thumb=1(?:&|$)/.test(raw)) return raw;

  try {
    const parsed = new URL(raw, window.location.origin);
    const pathname = parsed.pathname.replace(/\/+$/, "");
    if (
      !pathname.endsWith("/api/media/file") &&
      !pathname.endsWith("/api/preview/image") &&
      !pathname.endsWith("/api/agents/workspace-preview")
    ) {
      return raw;
    }
    parsed.searchParams.set("thumb", "1");
    parsed.searchParams.set("max", String(max));
    const relative = `${parsed.pathname}${parsed.search}`;
    return raw.startsWith("http") ? parsed.toString() : relative;
  } catch {
    const joiner = raw.includes("?") ? "&" : "?";
    return `${raw}${joiner}thumb=1&max=${encodeURIComponent(String(max))}`;
  }
}

function encodeMarkdownPathSegment(segment) {
  const value = String(segment || "");
  if (!value) return value;
  try {
    return encodeURIComponent(decodeURIComponent(value));
  } catch {
    return encodeURIComponent(value);
  }
}

function encodeMarkdownUrlDestination(url) {
  const raw = String(url || "").trim();
  if (!raw) return raw;
  if (/^https?:\/\//i.test(raw) || /^data:/i.test(raw) || raw.startsWith("/api/")) {
    return raw.replace(/ /g, "%20");
  }
  return raw
    .split("/")
    .map((segment) => encodeMarkdownPathSegment(segment))
    .join("/");
}

function normalizeMarkdownLinkDestinations(markdown) {
  let normalized = String(markdown || "").replace(/!\[([^\]]*)\]\s+\(/g, "![$1](");
  normalized = normalized.replace(/(!?\[[^\]]*\])\(([^)\n]+)\)/g, (match, prefix, url) => {
    const trimmed = String(url || "").trim();
    if (!trimmed || /\s".*"$/.test(url)) return match;
    const encoded = encodeMarkdownUrlDestination(trimmed);
    return encoded === trimmed ? match : `${prefix}(${encoded})`;
  });
  return normalized;
}

function compactDataUriPayload(uri) {
  const raw = String(uri || "").trim();
  const match = raw.match(/^(data:image\/[a-zA-Z0-9+.-]+;base64,)([\s\S]*)$/i);
  if (!match) return raw;
  const compact = `${match[1]}${match[2].replace(/\s+/g, "")}`;
  if (!/^data:image\/[a-zA-Z0-9+.-]+;base64,[A-Za-z0-9+/=]+$/i.test(compact)) return raw;
  return compact;
}

function normalizeEmbeddedDataUriMarkdown(markdown) {
  let source = String(markdown || "");

  source = source.replace(
    /!\[([^\]]*)\]\(\s*(data:image\/[a-zA-Z0-9+.-]+;base64,)([\s\S]*?)\)/gi,
    (match, alt, prefix, body) => {
      const compact = compactDataUriPayload(`${prefix}${body}`);
      return compact.startsWith("data:image/") ? `![${alt}](${compact})` : match;
    }
  );

  source = source.replace(
    /<img\b([^>]*?)\bsrc=(["'])\s*(data:image\/[a-zA-Z0-9+.-]+;base64,)([\s\S]*?)\2([^>]*)>/gi,
    (match, before, quote, prefix, body, after) => {
      const compact = compactDataUriPayload(`${prefix}${body}`);
      if (!compact.startsWith("data:image/")) return match;
      return `<img${before}src=${quote}${compact}${quote}${after}>`;
    }
  );

  source = source.replace(
    /(?:^|\n)\s*(data:image\/[a-zA-Z0-9+.-]+;base64,[A-Za-z0-9+/=\s]+)\s*(?=\n|$)/gi,
    (match, uri) => {
      const compact = compactDataUriPayload(uri);
      if (!compact.startsWith("data:image/")) return match;
      return `\n![](${compact})\n`;
    }
  );

  return source;
}

function buildDocumentRelativeStorageRef(layerFolder, relativePath, nodePath) {
  const fromPath = getMarkdownAssetSourcePath(nodePath);
  const contextPath = getPropsContextPath(nodePath) || getUploadStorageContextPath();
  if (!contextPath || !fromPath) return "";
  const targetWorkspacePath = buildStorageLayerRef(contextPath, layerFolder, relativePath);
  if (!targetWorkspacePath) return "";
  const href = relativizeWorkspacePath(fromPath, targetWorkspacePath);
  if (!href) return "";
  return href
    .split("/")
    .map((segment) => encodeMarkdownPathSegment(segment))
    .join("/");
}

function buildMarkdownAttachmentRef(relativeAssetsPath, _nodePath) {
  const raw = String(relativeAssetsPath || "").trim();
  if (!raw) return "";
  const subdir = /attachments/i.test(raw)
    ? ATTACHMENTS_ASSETS_SUBDIR
    : /preview/i.test(raw)
      ? PREVIEW_ASSETS_SUBDIR
      : PASTED_ASSETS_SUBDIR;
  const canonical = toCanonicalAssetsUploadRef(raw, subdir);
  return formatInlineAssetPathForEditor(canonical) || canonical;
}

function getUploadStorageContextPath() {
  if (activeSystemFile) {
    return getAgentWorkspaceRootManifestPath();
  }
  return getPropsContextPath() || getActiveNodeApiPath() || getResolvedNodePath(activePath);
}

function getUploadManifestRelPath() {
  return getUploadStorageContextPath();
}

function toCanonicalAssetsUploadRef(value, assetsSubdir = PASTED_ASSETS_SUBDIR) {
  const raw = String(value || "").trim().replace(/\\/g, "/");
  if (!raw) return "";

  if (STORAGE_ASSETS_PATH_PREFIX_RE.test(raw)) {
    return normalizeNodeAssetsStorageRef(raw);
  }

  const directAssets = parseStorageAssetsRef(raw);
  if (directAssets?.workspacePath) {
    return normalizeNodeAssetsStorageRef(directAssets.workspacePath);
  }

  if (/^https?:\/\//i.test(raw) || /^data:/i.test(raw) || raw.startsWith("/api/")) {
    return raw;
  }

  const contextPath = getUploadStorageContextPath();
  if (!contextPath) return normalizeNodeAssetsStorageRef(raw) || raw;

  if (/^assets\//i.test(raw)) {
    const rel = raw.replace(/^assets\//i, "");
    const slash = rel.indexOf("/");
    if (slash > 0) {
      const subdir = rel.slice(0, slash);
      const fileName = rel.slice(slash + 1);
      if (
        (subdir === PASTED_ASSETS_SUBDIR ||
          subdir === PREVIEW_ASSETS_SUBDIR ||
          subdir === ATTACHMENTS_ASSETS_SUBDIR) &&
        fileName
      ) {
        return buildAssetsUploadRef(contextPath, subdir, fileName);
      }
    }
  }

  if (/^(pasted|preview|attachments)\//i.test(raw)) {
    const slash = raw.indexOf("/");
    const subdir = raw.slice(0, slash);
    const fileName = raw.slice(slash + 1);
    if (fileName) return buildAssetsUploadRef(contextPath, subdir, fileName);
  }

  const sourceRel = getMarkdownAssetSourcePath();
  const workspaceRel = resolveMarkdownHrefToWorkspaceRel(raw, sourceRel);
  if (workspaceRel) {
    const resolvedAssets = parseStorageAssetsRef(workspaceRel);
    if (resolvedAssets?.workspacePath) {
      return normalizeNodeAssetsStorageRef(resolvedAssets.workspacePath);
    }
  }

  const fileName = raw.includes("/") ? raw.split("/").pop() : raw;
  if (!fileName) return normalizeNodeAssetsStorageRef(raw) || raw;

  let subdir = assetsSubdir;
  if (/\/preview\//i.test(raw) || /^preview\//i.test(raw)) {
    subdir = PREVIEW_ASSETS_SUBDIR;
  } else if (/\/pasted\//i.test(raw) || /^pasted\//i.test(raw)) {
    subdir = PASTED_ASSETS_SUBDIR;
  } else if (/\/attachments\//i.test(raw) || /^attachments\//i.test(raw)) {
    subdir = ATTACHMENTS_ASSETS_SUBDIR;
  }

  return buildAssetsUploadRef(contextPath, subdir, fileName);
}

function isStorageLayerEditorPath(relPath) {
  const normalized = String(relPath || "").replace(/\\/g, "/");
  if (!normalized) return false;
  if (normalized.includes(`/${STORAGE_ROOT_FOLDER}/`) || normalized.includes(`/${LEGACY_STORAGE_ROOT_FOLDER}/`)) return true;
  if (normalized.endsWith(`/${BUNDLE_CONTENT_FILE}`)) return true;
  if (normalized.endsWith(`/${BUNDLE_TABULAR_FILE}`)) return true;
  return false;
}

function getMarkdownAssetSourcePath(nodePath) {
  if (activeSystemFile) {
    return getAgentWorkspaceRootManifestPath();
  }
  const propsContext = String(getPropsContextPath() || "").replace(/\\/g, "/").replace(/^\/+/, "");
  const explicit = String(nodePath || "").replace(/\\/g, "/").replace(/^\/+/, "");

  if (
    explicit &&
    (explicit.includes(`/${STORAGE_ROOT_FOLDER}/`) || explicit.includes(`/${LEGACY_STORAGE_ROOT_FOLDER}/`))
  ) {
    return resolveOwningManifestRelFromNodePath(explicit);
  }
  if (propsContext) return resolveOwningManifestRelFromNodePath(propsContext);

  const raw = String(nodePath || getResolvedNodePath(activePath) || "")
    .replace(/\\/g, "/")
    .replace(/^\/+/, "");
  return resolveOwningManifestRelFromNodePath(raw);
}

function isLoadableImageDisplayUrl(src) {
  const raw = String(src || "").trim();
  if (!raw) return false;
  if (/^https?:\/\//i.test(raw) || /^data:/i.test(raw)) return true;
  return raw.startsWith("/api/");
}

function resolveStorageAssetsRefToApiUrl(assetsRef, contextManifestRelPath = "") {
  if (!assetsRef?.manifestRelPath || !assetsRef.mediaFile) return "";
  const ownerManifest = String(contextManifestRelPath || assetsRef.manifestRelPath || "").trim();
  const params = {
    path: assetsRef.manifestRelPath,
    file: normalizeMarkdownImageFileRef(assetsRef.mediaFile)
  };
  if (ownerManifest) params.contextPath = ownerManifest;
  return appendAgentToApiUrl(buildApiUrl("/api/media/file", params));
}

function normalizeMarkdownImageFileRef(fileRef) {
  const raw = String(fileRef || "").trim().replace(/\\/g, "/");
  if (!raw) return "";
  const stack = [];
  for (const part of raw.split("/")) {
    if (part === "..") stack.pop();
    else if (part && part !== ".") stack.push(part);
  }
  return stack.join("/");
}

function parseMarkdownImageApiUrl(src) {
  const raw = String(src || "").trim();
  if (!raw.startsWith("/api/")) return null;
  try {
    const parsed = new URL(raw, window.location.origin);
    const pathname = parsed.pathname.replace(/\/+$/, "");
    if (!pathname.endsWith("/api/media/file")) return null;
    const path = decodeURIComponent(parsed.searchParams.get("path") || "").trim();
    const contextPath = decodeURIComponent(parsed.searchParams.get("contextPath") || "").trim();
    const file = normalizeMarkdownImageFileRef(decodeURIComponent(parsed.searchParams.get("file") || ""));
    if (!path || !file) return null;
    return { path, contextPath: contextPath || path, file };
  } catch {
    return null;
  }
}

function resolveStorageLayerMediaRefToApiUrl(layerRef, contextManifestRelPath = "") {
  if (!layerRef?.manifestRelPath || !layerRef.relativePath || !layerRef.layer) return "";
  const fileRef =
    layerRef.layer === STORAGE_SUBFOLDER_ASSETS
      ? layerRef.relativePath
      : `${layerRef.layer}/${layerRef.relativePath}`;
  const ownerManifest = String(contextManifestRelPath || layerRef.manifestRelPath || "").trim();
  const params = {
    path: layerRef.manifestRelPath,
    file: normalizeMarkdownImageFileRef(fileRef)
  };
  if (ownerManifest) params.contextPath = ownerManifest;
  return appendAgentToApiUrl(buildApiUrl("/api/media/file", params));
}

function listMarkdownImageFileRefCandidates(fileRef, linkBasePath, contextManifestRelPath) {
  const normalized = normalizeMarkdownImageFileRef(fileRef);
  if (!normalized) return [];

  const candidates = [];
  const seen = new Set();
  const add = (value) => {
    const item = normalizeMarkdownImageFileRef(value);
    if (!item || seen.has(item)) return;
    seen.add(item);
    candidates.push(item);
  };

  add(normalized);
  const basename = normalized.split("/").pop();
  if (basename && basename !== normalized) add(basename);
  if (basename) {
    add(`${STORAGE_SUBFOLDER_MEDIA}/${basename}`);
    add(`${STORAGE_SUBFOLDER_CONTENT}/${basename}`);
    add(`${STORAGE_SUBFOLDER_ASSETS}/${PASTED_ASSETS_SUBDIR}/${basename}`);
    if (!normalized.includes("/")) add(basename);
  }

  const workspaceRel = resolveMarkdownHrefToWorkspaceRel(normalized, linkBasePath);
  if (workspaceRel) {
    const layerParsed = parseStorageLayerRef(workspaceRel);
    if (layerParsed) {
      if (layerParsed.layer === STORAGE_SUBFOLDER_ASSETS) add(layerParsed.relativePath);
      else add(`${layerParsed.layer}/${layerParsed.relativePath}`);
    }
    add(workspaceRel);
  }

  const slotDir = getNamedStorageSlotDirRel(contextManifestRelPath);
  if (slotDir && basename) {
    add(`${slotDir}/${STORAGE_SUBFOLDER_MEDIA}/${basename}`);
    add(`${slotDir}/${STORAGE_SUBFOLDER_ASSETS}/${PASTED_ASSETS_SUBDIR}/${basename}`);
    add(`${slotDir}/${STORAGE_SUBFOLDER_CONTENT}/${basename}`);
  }

  return candidates;
}

function resolveWorkspaceImageToApiUrl(fileRef, nodePath, options = {}) {
  const contextManifest = getMarkdownAssetSourcePath(nodePath);
  const linkBase = options.linkBase || getCurrentEditorLinkBasePath() || contextManifest;
  const manifestPath = resolveManifestPathForNodeApi(getResolvedNodePath(nodePath) || contextManifest);
  const contextPath = resolveMediaAssetContextPath(nodePath);
  if (!manifestPath) return "";

  const candidates = listMarkdownImageFileRefCandidates(fileRef, linkBase, contextManifest);
  for (const candidate of candidates) {
    const assetsRef = parseStorageAssetsRef(candidate);
    if (assetsRef) {
      const url = resolveStorageAssetsRefToApiUrl(assetsRef, contextManifest);
      if (url) return url;
    }

    const layerParsed = parseStorageLayerRef(candidate);
    if (layerParsed) {
      const url = resolveStorageLayerMediaRefToApiUrl(
        {
          manifestRelPath: pickManifestRelFromStorageLayerRef(layerParsed),
          layer: layerParsed.layer,
          relativePath: layerParsed.relativePath
        },
        contextManifest
      );
      if (url) return url;
    }
  }

  const fallbackFile = candidates[0];
  if (!fallbackFile) return "";
  return appendAgentToApiUrl(
    buildApiUrl("/api/media/file", {
      path: manifestPath,
      contextPath,
      file: fallbackFile
    })
  );
}

function isBrokenImageSrc(src, nodePath) {
  const trimmed = String(src || "").trim();
  if (!trimmed || trimmed === BROKEN_IMAGE_PLACEHOLDER_SRC) return false;
  if (/^https?:\/\//i.test(trimmed) || /^data:/i.test(trimmed)) return false;
  const resolved = resolveMarkdownAssetSrc(trimmed, nodePath);
  return !isLoadableImageDisplayUrl(resolved);
}

function createBrokenImagePlaceholder({ label = "Изображение не найдено", className = "" } = {}) {
  const img = document.createElement("img");
  img.src = BROKEN_IMAGE_PLACEHOLDER_SRC;
  img.alt = label;
  img.title = label;
  img.draggable = false;
  img.className = ["broken-image-placeholder", className].filter(Boolean).join(" ");
  return img;
}

function applyBrokenImagePlaceholder(img, label = "Изображение не найдено") {
  if (!(img instanceof HTMLImageElement) || img.dataset.brokenPlaceholder === "1") return;
  const currentSrc = img.getAttribute("src") || "";
  if (
    currentSrc &&
    currentSrc !== BROKEN_IMAGE_PLACEHOLDER_SRC &&
    !img.dataset.originalSrc
  ) {
    img.dataset.originalSrc = currentSrc;
  }
  img.dataset.brokenPlaceholder = "1";
  img.src = BROKEN_IMAGE_PLACEHOLDER_SRC;
  img.alt = label || img.alt || "Изображение не найдено";
  img.title = img.alt;
  img.classList.add("broken-image-placeholder", "markdown-image-missing");
}

function bindMarkdownPreviewImageFallback(img, nodePath) {
  if (!(img instanceof HTMLImageElement)) return;
  const src = img.getAttribute("data-original-src") || img.getAttribute("src") || "";
  if (!src || src === BROKEN_IMAGE_PLACEHOLDER_SRC) return;
  if (!img.dataset.originalSrc && src) img.dataset.originalSrc = src;

  const resolved = resolveMarkdownAssetSrc(src, nodePath);
  if (isLoadableImageDisplayUrl(resolved)) {
    const displayUrl = appendAgentToApiUrl(resolved);
    if (img.getAttribute("src") !== displayUrl) img.src = displayUrl;
    img.classList.remove("broken-image-placeholder", "markdown-image-missing");
    delete img.dataset.brokenPlaceholder;
    img.addEventListener("error", () => applyBrokenImagePlaceholder(img), { once: true });
    return;
  }

  const sourcePath = getMarkdownAssetSourcePath(nodePath);
  if (isBrokenImageSrc(src, sourcePath)) {
    applyBrokenImagePlaceholder(img);
    return;
  }
  img.addEventListener("error", () => applyBrokenImagePlaceholder(img), { once: true });
}

function resolveMarkdownAssetSrc(src, nodePath) {
  const raw = String(src || "").trim();
  if (!raw) return raw;
  if (/^https?:\/\//i.test(raw) || /^data:/i.test(raw)) return raw;

  if (raw.startsWith("/api/")) {
    const apiRef = parseMarkdownImageApiUrl(raw);
    if (apiRef) {
      const repaired = resolveWorkspaceImageToApiUrl(apiRef.file, nodePath);
      if (repaired) return repaired;
    }
    return appendAgentToApiUrl(raw);
  }

  const relFile = normalizeMarkdownImageFileRef(raw.replace(/\\/g, "/"));
  const sourceRel = getMarkdownAssetSourcePath(nodePath);
  const linkBase = getCurrentEditorLinkBasePath() || sourceRel;
  if (isStorageRootRelativePath(relFile) || /^assets\//i.test(relFile)) {
    for (const candidate of listStorageAssetsRefPathCandidates(relFile, sourceRel)) {
      const contextualRef = parseStorageAssetsRef(candidate);
      const contextualUrl = resolveStorageAssetsRefToApiUrl(contextualRef, sourceRel);
      if (contextualUrl) return contextualUrl;
    }
  }

  if (/^assets\//i.test(relFile) || /^(pasted|preview|attachments)\//i.test(relFile)) {
    const subdir = /preview/i.test(relFile)
      ? PREVIEW_ASSETS_SUBDIR
      : /attachments/i.test(relFile)
        ? ATTACHMENTS_ASSETS_SUBDIR
        : PASTED_ASSETS_SUBDIR;
    const canonical = toCanonicalAssetsUploadRef(relFile, subdir);
    if (canonical) {
      const shortAssetsRef = parseStorageAssetsRef(canonical);
      const shortUrl = resolveStorageAssetsRefToApiUrl(shortAssetsRef, sourceRel);
      if (shortUrl) return shortUrl;
    }
  }

  const assetsRef = parseStorageAssetsRef(relFile);
  const directUrl = resolveStorageAssetsRefToApiUrl(assetsRef, sourceRel);
  if (directUrl) return directUrl;

  const layerRef = parseStorageLayerRef(relFile);
  if (layerRef?.layer === STORAGE_SUBFOLDER_MEDIA || layerRef?.layer === STORAGE_SUBFOLDER_CONTENT) {
    const layerUrl = resolveStorageLayerMediaRefToApiUrl(
      {
        manifestRelPath: pickManifestRelFromStorageLayerRef(layerRef),
        layer: layerRef.layer,
        relativePath: layerRef.relativePath
      },
      sourceRel
    );
    if (layerUrl) return layerUrl;
  }

  const workspaceRel = resolveMarkdownHrefToWorkspaceRel(relFile, linkBase);
  if (workspaceRel) {
    const docAssetsRef = parseStorageAssetsRef(workspaceRel);
    const docUrl = resolveStorageAssetsRefToApiUrl(docAssetsRef, sourceRel);
    if (docUrl) return docUrl;

    const docLayerRef = parseStorageLayerRef(workspaceRel);
    if (docLayerRef?.layer === STORAGE_SUBFOLDER_MEDIA || docLayerRef?.layer === STORAGE_SUBFOLDER_CONTENT) {
      const docLayerUrl = resolveStorageLayerMediaRefToApiUrl(
        {
          manifestRelPath: pickManifestRelFromStorageLayerRef(docLayerRef),
          layer: docLayerRef.layer,
          relativePath: docLayerRef.relativePath
        },
        sourceRel
      );
      if (docLayerUrl) return docLayerUrl;
    }
  }

  const fallbackUrl = resolveWorkspaceImageToApiUrl(relFile, nodePath, { linkBase });
  if (fallbackUrl) return fallbackUrl;

  return raw;
}

function getAttachmentAltText(fileName) {
  const base = String(fileName || "image").split("/").pop() || "image";
  const dot = base.lastIndexOf(".");
  const alt = dot > 0 ? base.slice(0, dot) : base;
  return alt.replace(/[[\]]/g, "").trim() || "image";
}

function buildMarkdownImageSnippet(relativeFile, altText, nodePath, workspaceRef = "") {
  const canonical = toCanonicalAssetsUploadRef(workspaceRef || relativeFile, PASTED_ASSETS_SUBDIR);
  if (!canonical || /^\/api\//.test(canonical)) return "";
  const ref = formatInlineAssetPathForEditor(canonical);
  if (!ref) return "";
  const alt = String(altText || getAttachmentAltText(relativeFile)).replace(/[[\]]/g, "");
  return `\n![${alt}](${ref})\n`;
}

function getImageAttachmentExtension(file) {
  const mime = String(file?.type || "").toLowerCase();
  const name = String(file?.name || "").toLowerCase();
  if (mime === "image/png" || name.endsWith(".png")) return ".png";
  if (mime === "image/gif" || name.endsWith(".gif")) return ".gif";
  if (mime === "image/webp" || name.endsWith(".webp")) return ".webp";
  if (mime === "image/heic" || mime === "image/heif" || name.endsWith(".heic") || name.endsWith(".heif")) {
    return ".heic";
  }
  if (mime === "image/jpeg" || /\.jpe?g$/.test(name)) return ".jpg";
  return ".png";
}

function sanitizeAttachmentRecordSlug(text) {
  let name = String(text || "")
    .trim()
    .replace(/\\/g, "/")
    .split("/")
    .pop()
    .replace(/\.(sidecar\.)?md$/i, "")
    .replace(/\s+/g, " ");
  name = name.replace(/[^\w.\- ()[\]а-яА-ЯёЁ]/gi, "-").replace(/-+/g, "-").replace(/^-|-$/g, "");
  if (name.length > 48) name = name.slice(0, 48).replace(/-+$/g, "");
  return name || "";
}

function getInlineAttachmentRecordSlug() {
  let label = "";
  if (activeExternalFilePath) {
    label = getLabelFromPath(activeExternalFilePath) || activeExternalFilePath.split("/").pop() || "";
  } else if (activeMediaMarkdownPath) {
    label = getLabelFromPath(activeMediaMarkdownPath) || activeMediaMarkdownPath.split("/").pop() || "";
  } else if (activeMediaSidecarSourcePath) {
    label = activeMediaSidecarSourcePath.split("/").pop() || "";
  } else if (activeMediaSidecarPath) {
    label = activeMediaSidecarPath.split("/").pop() || "";
  } else if (titleInputNode?.value?.trim()) {
    label = titleInputNode.value.trim();
  } else if (activeLabel) {
    label = activeLabel;
  } else if (activePath) {
    label = getLabelFromPath(activePath);
  }
  return sanitizeAttachmentRecordSlug(label) || "note";
}

function buildAttachmentTimestamp() {
  return new Date().toISOString().replace(/[-:T.Z]/g, "").slice(0, 14);
}

function buildInlineAttachmentFileName(file, recordSlug = getInlineAttachmentRecordSlug()) {
  const ext = getImageAttachmentExtension(file);
  const stamp = buildAttachmentTimestamp();
  const slug = sanitizeAttachmentRecordSlug(recordSlug) || "note";
  return `${slug}-${stamp}${ext}`;
}

function buildPastedAttachmentFileName(file) {
  const ext = getImageAttachmentExtension(file);
  return `${buildAttachmentTimestamp()}${ext}`;
}

function getAttachmentStorageExtension(file) {
  const name = String(file?.name || "").toLowerCase();
  if (ATTACHMENTS_IMAGE_EXT_RE.test(name)) {
    return getImageAttachmentExtension(file);
  }
  const dot = name.lastIndexOf(".");
  return dot > 0 ? name.slice(dot) : "";
}

function buildAttachmentsStorageFileName(file) {
  const original = String(file?.name || "file");
  const ext = getAttachmentStorageExtension(file);
  const base = ext && original.toLowerCase().endsWith(ext.toLowerCase())
    ? original.slice(0, -ext.length)
    : original.replace(/\.[^.]+$/, "");
  const slug = transliterateDisplayToSlug(base) || "file";
  return `${slug}-${buildAttachmentTimestamp()}${ext}`;
}

async function normalizeImageAttachmentFile(file, { pasted = false } = {}) {
  if (!file) return file;
  const header = new Uint8Array(await file.slice(0, 16).arrayBuffer());
  let ext = "";
  let mime = String(file.type || "").toLowerCase();

  if (header[0] === 0x89 && header[1] === 0x50 && header[2] === 0x4e && header[3] === 0x47) {
    ext = ".png";
    mime = "image/png";
  } else if (header[0] === 0xff && header[1] === 0xd8 && header[2] === 0xff) {
    ext = ".jpg";
    mime = "image/jpeg";
  } else if (header.length >= 6) {
    const gifHeader = String.fromCharCode(...header.slice(0, 6));
    if (gifHeader === "GIF87a" || gifHeader === "GIF89a") {
      ext = ".gif";
      mime = "image/gif";
    }
  }
  if (!ext && header.length >= 12) {
    const riff = String.fromCharCode(...header.slice(0, 4));
    const webp = String.fromCharCode(...header.slice(8, 12));
    if (riff === "RIFF" && webp === "WEBP") {
      ext = ".webp";
      mime = "image/webp";
    }
  }
  if (!ext && header.length >= 12 && String.fromCharCode(...header.slice(4, 8)) === "ftyp") {
    ext = ".heic";
    mime = "image/heic";
  }
  if (!ext) return file;

  const currentName = String(file.name || "");
  if (currentName.toLowerCase().endsWith(ext) && mime === String(file.type || "").toLowerCase()) {
    return file;
  }
  const baseName = (pasted ? buildPastedAttachmentFileName : buildInlineAttachmentFileName)({ type: mime }).replace(
    /\.[^.]+$/,
    ""
  );
  return new File([file], `${baseName}${ext}`, { type: mime });
}

const WYSIWYG_ALLOWED_IMAGE_MIME_TYPES = new Set([
  "image/jpeg",
  "image/png",
  "image/gif",
  "image/webp",
  "image/svg+xml"
]);
const WYSIWYG_ALLOWED_IMAGE_EXT_RE = /\.(jpe?g|png|gif|webp|svg)$/i;
const WYSIWYG_BLOCKED_IMAGE_MIME_TYPES = new Set([
  "image/heic",
  "image/heif",
  "image/avif",
  "image/tiff",
  "image/bmp",
  "image/x-ms-bmp"
]);
const WYSIWYG_BLOCKED_IMAGE_EXT_RE =
  /\.(heic|heif|avif|tiff?|bmp|cr2|nef|arw|dng|orf|rw2|pef|srw|raf|3fr|fff|mrw|x3f|raw)$/i;
const HEIC_FTYP_BRANDS = new Set(["heic", "heix", "hevc", "hevx", "mif1", "msf1"]);
const AVIF_FTYP_BRANDS = new Set(["avif", "avis"]);

function isWysiwygAllowedImageFileSync(fileOrBlob) {
  if (!fileOrBlob) return false;
  const mime = String(fileOrBlob.type || "").toLowerCase();
  const name = String(fileOrBlob.name || "").toLowerCase();
  if (WYSIWYG_ALLOWED_IMAGE_MIME_TYPES.has(mime)) return true;
  return WYSIWYG_ALLOWED_IMAGE_EXT_RE.test(name);
}

function isWysiwygBlockedImageFileSync(fileOrBlob) {
  if (!fileOrBlob || isWysiwygAllowedImageFileSync(fileOrBlob)) return false;
  const mime = String(fileOrBlob.type || "").toLowerCase();
  const name = String(fileOrBlob.name || "").toLowerCase();
  if (WYSIWYG_BLOCKED_IMAGE_MIME_TYPES.has(mime)) return true;
  return WYSIWYG_BLOCKED_IMAGE_EXT_RE.test(name);
}

async function isWysiwygBlockedImageFile(fileOrBlob) {
  if (isWysiwygBlockedImageFileSync(fileOrBlob)) return true;
  if (isWysiwygAllowedImageFileSync(fileOrBlob)) return false;
  if (!fileOrBlob || typeof fileOrBlob.slice !== "function") return false;
  try {
    const header = new Uint8Array(await fileOrBlob.slice(0, 12).arrayBuffer());
    if (header.length >= 2 && header[0] === 0x42 && header[1] === 0x4d) return true;
    if (header.length >= 4) {
      const tiffLe = header[0] === 0x49 && header[1] === 0x49 && header[2] === 0x2a;
      const tiffBe = header[0] === 0x4d && header[1] === 0x4d && header[2] === 0x00 && header[3] === 0x2a;
      if (tiffLe || tiffBe) return true;
    }
    if (header.length >= 12 && String.fromCharCode(...header.slice(4, 8)) === "ftyp") {
      const brand = String.fromCharCode(...header.slice(8, 12)).toLowerCase();
      if (HEIC_FTYP_BRANDS.has(brand) || AVIF_FTYP_BRANDS.has(brand)) return true;
    }
  } catch {
    return false;
  }
  return false;
}

function showWysiwygBlockedImageToast() {
  showToast(
    "Этот формат изображения нельзя вставлять в визуальный редактор (HEIC, AVIF, TIFF, BMP, RAW). Используйте JPG, PNG, GIF, WebP или SVG.",
    "error"
  );
}

function isAllowedMarkdownAttachmentImage(file) {
  if (!file) return false;
  const mime = String(file.type || "").toLowerCase();
  const name = String(file.name || "").toLowerCase();
  const extOk = /\.(jpe?g|png|gif|webp|heic|heif)$/.test(name);
  if (!extOk && mime && !mime.startsWith("image/")) return false;
  if (!mime) return extOk;
  return (
    mime === "image/jpeg" ||
    mime === "image/png" ||
    mime === "image/gif" ||
    mime === "image/webp" ||
    mime === "image/heic" ||
    mime === "image/heif"
  );
}

function dataTransferHasImage(dataTransfer) {
  if (!dataTransfer) return false;
  const files = dataTransfer.files ? [...dataTransfer.files] : [];
  if (files.some((file) => isAllowedMarkdownAttachmentImage(file))) return true;
  const types = dataTransfer.types ? [...dataTransfer.types] : [];
  return types.includes("Files");
}

function extractImageFileFromDataTransfer(dataTransfer) {
  if (!dataTransfer) return null;
  const items = dataTransfer.items ? [...dataTransfer.items] : [];
  for (const item of items) {
    if (item.kind !== "file") continue;
    const file = item.getAsFile();
    if (file && isAllowedMarkdownAttachmentImage(file)) return file;
  }
  const files = dataTransfer.files ? [...dataTransfer.files] : [];
  for (const file of files) {
    if (isAllowedMarkdownAttachmentImage(file)) return file;
  }
  return null;
}

function canPasteMarkdownAttachment() {
  if (!activePath && !activeSystemFile) return false;
  if (activeSystemFile) {
    if (!isSystemFileEditing()) return false;
    if (!isSystemFileMd(activeSystemFile)) return false;
  }
  if (isCurrentModeReadOnly()) return false;
  if (isCurrentModeListTemplate()) return false;
  if (editorViewMode === "preview") return false;
  return true;
}

function insertTextAtEditorCursor(text) {
  const snippet = String(text || "");
  if (!snippet || !fileContentInputNode) return;
  return withPreservedEditorScroll(() => {
    const saved = lastSourceEditorSelection;
    const start =
      saved?.start ?? fileContentInputNode.selectionStart ?? fileContentInputNode.value.length;
    const end = saved?.end ?? fileContentInputNode.selectionEnd ?? start;
    const before = fileContentInputNode.value.slice(0, start);
    const after = fileContentInputNode.value.slice(end);
    fileContentInputNode.value = `${before}${snippet}${after}`;
    const cursor = start + snippet.length;
    fileContentInputNode.selectionStart = cursor;
    fileContentInputNode.selectionEnd = cursor;
    lastSourceEditorSelection = { start: cursor, end: cursor };
    fileContentInputNode.dispatchEvent(new Event("input", { bubbles: true }));
    fileContentInputNode.focus({ preventScroll: true });
  });
}

function notifyMarkdownLinkRewrite(linkRewrite) {
  const linksUpdated = Number(linkRewrite?.linksUpdated) || 0;
  const filesUpdated = Number(linkRewrite?.filesUpdated) || 0;
  if (!linksUpdated) return;
  const filesPart = filesUpdated ? ` в ${filesUpdated} файлах` : "";
  showToast(`Обновлено markdown-ссылок: ${linksUpdated}${filesPart}`, "success");
}

function canInsertDocContentBlocks() {
  if (!activePath || activeSystemFile) return false;
  if (isCurrentModeReadOnly()) return false;
  if (isCurrentModeListTemplate()) return false;
  if (editorViewMode === "preview") return false;
  if (editorSurfaceNode?.classList.contains("hidden")) return false;
  return true;
}

function markdownOffsetFromLineCol(markdown, line, col) {
  const lines = String(markdown || "").split("\n");
  const lineIdx = Math.max(1, Number(line) || 1) - 1;
  let offset = 0;
  for (let i = 0; i < lineIdx && i < lines.length; i += 1) {
    offset += lines[i].length + 1;
  }
  const column = Math.max(1, Number(col) || 1);
  const lineText = lines[lineIdx] || "";
  offset += Math.min(column - 1, lineText.length);
  return offset;
}

function markdownOffsetToLineCol(markdown, offset) {
  const text = String(markdown || "");
  const lines = text.split("\n");
  const target = Math.max(0, Math.min(offset, text.length));
  let walked = 0;
  for (let i = 0; i < lines.length; i += 1) {
    const lineText = lines[i];
    const lineEnd = walked + lineText.length;
    if (target <= lineEnd) {
      return { line: i + 1, col: target - walked + 1 };
    }
    walked = lineEnd + 1;
    if (target === walked) {
      return { line: i + 2, col: 1 };
    }
  }
  const lastLine = Math.max(1, lines.length);
  const lastLen = lines[lastLine - 1]?.length || 0;
  return { line: lastLine, col: lastLen + 1 };
}

function isWysiwygOffsetSelection(selection) {
  if (!Array.isArray(selection) || selection.length < 2) return false;
  return (
    Number.isFinite(selection[0]) &&
    Number.isFinite(selection[1]) &&
    !Array.isArray(selection[0])
  );
}

function isMarkdownLineColSelection(selection) {
  if (!Array.isArray(selection) || selection.length < 2) return false;
  return Array.isArray(selection[0]) && Array.isArray(selection[1]);
}

function cloneWysiwygMarkdownSelection(selection) {
  if (!Array.isArray(selection) || selection.length < 2) return null;
  const first = selection[0];
  const second = selection[1];
  if (Array.isArray(first) && Array.isArray(second)) {
    return [
      [first[0], first[1]],
      [second[0], second[1]]
    ];
  }
  if (Number.isFinite(first) && Number.isFinite(second)) {
    return [first, second];
  }
  return null;
}

function captureWysiwygMarkdownSelection() {
  const editor = wysiwygEditorInstance;
  if (!editor) return;
  const cloned = cloneWysiwygMarkdownSelection(editor.getSelection?.());
  if (cloned) lastWysiwygMarkdownSelection = cloned;
}

function rememberPendingWysiwygInsertSelection() {
  const editor = wysiwygEditorInstance;
  if (!editor) return;
  const cloned = cloneWysiwygMarkdownSelection(editor.getSelection?.());
  if (cloned) pendingWysiwygInsertSelection = cloned;
}

function setWysiwygCursorAtMarkdownOffset(markdown, offset) {
  const editor = wysiwygEditorInstance;
  if (!editor) return;
  const pos = markdownOffsetToLineCol(String(markdown || ""), offset);
  const mdStart = [pos.line, pos.col];
  const mdEnd = [pos.line, pos.col];

  const applySelection = () => {
    try {
      if (editor.isWysiwygMode?.() && typeof editor.convertPosToMatchEditorMode === "function") {
        const ww = editor.convertPosToMatchEditorMode(mdStart, mdEnd, "wysiwyg");
        if (Array.isArray(ww) && ww.length >= 2 && Number.isFinite(ww[0]) && Number.isFinite(ww[1])) {
          editor.setSelection(ww[0], ww[1]);
          lastWysiwygMarkdownSelection = [ww[0], ww[1]];
          getWysiwygProseMirrorRoot()?.focus({ preventScroll: true });
          return;
        }
      }
      editor.setSelection(mdStart, mdEnd);
      lastWysiwygMarkdownSelection = [mdStart, mdEnd];
      getWysiwygProseMirrorRoot()?.focus({ preventScroll: true });
    } catch {
      // ignore stale selection after setMarkdown
    }
  };

  applySelection();
  requestAnimationFrame(applySelection);
}

function captureSourceEditorSelection() {
  if (!fileContentInputNode) return;
  lastSourceEditorSelection = {
    start: fileContentInputNode.selectionStart ?? fileContentInputNode.value.length,
    end:
      fileContentInputNode.selectionEnd ??
      fileContentInputNode.selectionStart ??
      fileContentInputNode.value.length
  };
}

function captureEditorInsertSelection() {
  if (editorViewMode === "wysiwyg" && wysiwygEditorInstance) {
    rememberPendingWysiwygInsertSelection();
    captureWysiwygMarkdownSelection();
    return;
  }
  captureSourceEditorSelection();
}

function getWysiwygMarkdownSelectionForInsert(editor) {
  if (pendingWysiwygInsertSelection) {
    const pending = pendingWysiwygInsertSelection;
    pendingWysiwygInsertSelection = null;
    return pending;
  }
  const current = editor.getSelection?.();
  const cloned = cloneWysiwygMarkdownSelection(current);
  if (cloned) {
    lastWysiwygMarkdownSelection = cloned;
    return cloned;
  }
  return lastWysiwygMarkdownSelection;
}

function bindWysiwygSelectionCapture() {
  const pm = getWysiwygProseMirrorRoot();
  if (!pm || pm.dataset.awnSelectionBound === "1") return;
  pm.dataset.awnSelectionBound = "1";
  const capture = () => {
    if (editorViewMode !== "wysiwyg") return;
    captureWysiwygMarkdownSelection();
  };
  pm.addEventListener("keyup", capture);
  pm.addEventListener("mouseup", capture);
  pm.addEventListener("focus", capture);
}

function bindWysiwygLinkNavigation() {
  const pm = getWysiwygProseMirrorRoot();
  if (!pm || pm.dataset.awnLinkNavBound === "1") return;
  pm.dataset.awnLinkNavBound = "1";
  pm.addEventListener("click", (event) => {
    if (editorViewMode !== "wysiwyg") return;
    if (!(event.metaKey || event.ctrlKey)) return;
    const link = event.target.closest("a[href]");
    if (!link) return;
    const href = String(link.getAttribute("href") || "").trim();
    if (!href || href.startsWith("#") || /^https?:\/\//i.test(href) || /^mailto:/i.test(href)) {
      return;
    }
    event.preventDefault();
    event.stopPropagation();
    void openMarkdownLinkTarget(href, getCurrentEditorLinkBasePath());
  });
}

function bindEditorAsideInsertControl(node) {
  if (!node || node.dataset.awnInsertBound === "1") return;
  node.dataset.awnInsertBound = "1";
  node.addEventListener(
    "mousedown",
    (event) => {
      event.preventDefault();
      captureEditorInsertSelection();
    },
    true
  );
}

function setupEditorAsideSelectionCapture() {
  const panel = document.getElementById("yaml-form-panel");
  if (!panel || panel.dataset.selectionCaptureBound === "1") return;
  panel.dataset.selectionCaptureBound = "1";
  panel.addEventListener(
    "mousedown",
    (event) => {
      if (!canInsertDocContentBlocks()) return;
      if (
        event.target.closest(
          ".doc-block-btn, .awn-wysiwyg-link-picker-item, .menu-item[data-path], .menu-card-body[data-path]"
        )
      ) {
        captureEditorInsertSelection();
      }
    },
    true
  );
}

function getEditorScrollSnapshot() {
  const ta = fileContentInputNode;
  const wysiwygScrollEl = getWysiwygScrollElement();
  const workspaceBody = document.querySelector(".workspace-body");
  return {
    textareaScrollTop: ta?.scrollTop ?? 0,
    wysiwygScrollTop: wysiwygScrollEl?.scrollTop ?? 0,
    workspaceScrollTop: workspaceBody?.scrollTop ?? 0,
    pageScrollTop: window.scrollY || 0
  };
}

function restoreEditorScrollSnapshot(snapshot) {
  if (!snapshot) return;
  const ta = fileContentInputNode;
  const wysiwygScrollEl = getWysiwygScrollElement();
  const workspaceBody = document.querySelector(".workspace-body");
  if (ta) ta.scrollTop = snapshot.textareaScrollTop;
  if (wysiwygScrollEl) wysiwygScrollEl.scrollTop = snapshot.wysiwygScrollTop;
  if (workspaceBody) workspaceBody.scrollTop = snapshot.workspaceScrollTop;
  if (Math.abs((window.scrollY || 0) - snapshot.pageScrollTop) > 1) {
    window.scrollTo(0, snapshot.pageScrollTop);
  }
}

function withPreservedEditorScroll(action) {
  const snapshot = getEditorScrollSnapshot();
  const result = action();
  restoreEditorScrollSnapshot(snapshot);
  requestAnimationFrame(() => restoreEditorScrollSnapshot(snapshot));
  return result;
}

function scheduleDocOutlineRefresh() {
  if (getDocAsideTab() !== "outline") return;
  requestAnimationFrame(() => renderDocOutline());
}

function resolveWysiwygMarkdownSelection(markdown, selection) {
  const text = String(markdown || "");
  if (!Array.isArray(selection) || selection.length < 2) {
    return { start: text.length, end: text.length };
  }

  const first = selection[0];
  const second = selection[1];
  if (Number.isFinite(first) && Number.isFinite(second) && !Array.isArray(first)) {
    const start = Math.max(0, Math.min(first, text.length));
    const end = Math.max(start, Math.min(second, text.length));
    return { start, end };
  }

  if (Array.isArray(first) && Array.isArray(second)) {
    const start = markdownOffsetFromLineCol(text, first[0], first[1]);
    const end = markdownOffsetFromLineCol(text, second[0], second[1]);
    return {
      start: Math.max(0, Math.min(start, text.length)),
      end: Math.max(start, Math.min(end, text.length))
    };
  }

  return { start: text.length, end: text.length };
}

function insertMarkdownAtWysiwygCursor(snippet) {
  const editor = wysiwygEditorInstance;
  if (!editor) return false;
  const text = String(snippet || "");
  if (!text) return false;

  return withPreservedEditorScroll(() => {
    const selection = getWysiwygMarkdownSelectionForInsert(editor);
    const pm = getWysiwygProseMirrorRoot();
    pm?.focus({ preventScroll: true });

    const insertAtMarkdownOffsets = (start, end) => {
      const current = String(editor.getMarkdown() || "");
      const safeStart = Math.max(0, Math.min(start, current.length));
      const safeEnd = Math.max(safeStart, Math.min(end, current.length));
      const prepared = prepareDocBlockInsertSnippet(text, safeStart, current);
      const next = `${current.slice(0, safeStart)}${prepared}${current.slice(safeEnd)}`;
      editor.setMarkdown(normalizeWysiwygImportedMarkdown(next), false);
      syncSourceFromWysiwygEditor();
      const exported = normalizeWysiwygExportedMarkdown(editor.getMarkdown());
      setWysiwygCursorAtMarkdownOffset(exported, safeStart + prepared.length);
      return true;
    };

    if (isWysiwygOffsetSelection(selection)) {
      try {
        editor.setSelection(selection[0], selection[1]);
      } catch {
        // Selection may be stale after aside click — marker insert still attempts current range.
      }
      editor.insertText(WYSIWYG_INSERT_MARKER);
      const markdown = String(editor.getMarkdown() || "");
      const markerIndex = markdown.indexOf(WYSIWYG_INSERT_MARKER);
      if (markerIndex >= 0) {
        return insertAtMarkdownOffsets(markerIndex, markerIndex + WYSIWYG_INSERT_MARKER.length);
      }
    }

    if (isMarkdownLineColSelection(selection)) {
      const current = String(editor.getMarkdown() || "");
      const { start, end } = resolveWysiwygMarkdownSelection(current, selection);
      return insertAtMarkdownOffsets(start, end);
    }

    const current = String(editor.getMarkdown() || "");
    return insertAtMarkdownOffsets(current.length, current.length);
  });
}

function ensureDocBlockInsertTrailingBlankLine(snippet) {
  let text = String(snippet || "");
  if (!text) return "";
  if (!text.endsWith("\n")) text += "\n";
  if (!text.endsWith("\n\n")) text += "\n";
  return text;
}

function normalizeDocBlockTemplateSnippet(snippet) {
  let text = String(snippet || "").replace(/^\n+/, "");
  return ensureDocBlockInsertTrailingBlankLine(text);
}

/** Палитра md-blocks: одна новая строка перед блоком (только если курсор в середине строки), без пустой строки сверху. */
function prepareDocBlockInsertSnippet(snippet, insertOffset, documentText) {
  let text = normalizeDocBlockTemplateSnippet(snippet);
  const offset = Math.max(0, Number(insertOffset) || 0);
  const before = String(documentText || "").slice(0, offset);
  if (before.length && !before.endsWith("\n")) {
    text = `\n${text}`;
  }
  return text;
}

function resolveDocBlockSnippet(blockOrText) {
  if (typeof blockOrText === "string") return blockOrText;
  const raw = blockOrText?.template ?? blockOrText?.text ?? "";
  return typeof raw === "string" ? raw : "";
}

function insertMarkdownAtEditorCursor(text) {
  const snippet = resolveDocBlockSnippet(text);
  if (!String(snippet || "").trim()) return false;
  if (!(canInsertDocContentBlocks() || canPasteMarkdownAttachment())) {
    showToast("Вставка доступна только в режиме редактирования", "error");
    return false;
  }

  if (editorViewMode === "wysiwyg" && wysiwygEditorInstance) {
    try {
      if (!insertMarkdownAtWysiwygCursor(snippet)) throw new Error("insert failed");
      syncSaveButtonLamp();
      scheduleDocOutlineRefresh();
      return true;
    } catch {
      showToast("Не удалось вставить блок в WYSIWYG", "error");
      return false;
    }
  }

  return withPreservedEditorScroll(() => {
    const saved = lastSourceEditorSelection;
    const start =
      saved?.start ?? fileContentInputNode.selectionStart ?? fileContentInputNode.value.length;
    const end = saved?.end ?? fileContentInputNode.selectionEnd ?? start;
    const doc = fileContentInputNode.value;
    const prepared = prepareDocBlockInsertSnippet(snippet, start, doc);
    const before = doc.slice(0, start);
    const after = doc.slice(end);
    fileContentInputNode.value = `${before}${prepared}${after}`;
    const cursor = start + prepared.length;
    fileContentInputNode.selectionStart = cursor;
    fileContentInputNode.selectionEnd = cursor;
    lastSourceEditorSelection = { start: cursor, end: cursor };
    fileContentInputNode.dispatchEvent(new Event("input", { bubbles: true }));
    fileContentInputNode.focus({ preventScroll: true });
    scheduleDocOutlineRefresh();
    return true;
  });
}

const HIGHLIGHT_TONE_SET = new Set(["yellow", "red", "green", "blue", "gray", "orange", "purple"]);
const HIGHLIGHT_TONE_OPTIONS = [
  { tone: "yellow", label: "Жёлтый" },
  { tone: "red", label: "Красный" },
  { tone: "green", label: "Зелёный" },
  { tone: "blue", label: "Синий" },
  { tone: "gray", label: "Серый" },
  { tone: "orange", label: "Оранжевый" },
  { tone: "purple", label: "Фиолетовый" }
];
const HIGHLIGHT_MARKDOWN_REGEX = /==(?:\{([a-z]+)\})?([^=\n][^=]*?)==/gi;
const HIGHLIGHT_HTML_MARK_REGEX = /<mark\b[^>]*>([\s\S]*?)<\/mark>/gi;
const ESCAPED_HIGHLIGHT_MARKDOWN_REGEX = /\\==(?:\{([a-z]+)\})?([^=\\][^=]*?)\\==/gi;
let editorHighlightTone = "yellow";
let wysiwygHighlightToolbarRefs = null;

function normalizeHighlightTone(tone) {
  const value = String(tone || "yellow").toLowerCase();
  return HIGHLIGHT_TONE_SET.has(value) ? value : "yellow";
}

function buildHighlightMarkdown(inner, tone = "yellow") {
  const text = String(inner ?? "");
  const safeTone = normalizeHighlightTone(tone);
  if (safeTone === "yellow") return `==${text}==`;
  return `=={${safeTone}}${text}==`;
}

function stripHighlightMarkdown(segment) {
  return String(segment || "").replace(HIGHLIGHT_MARKDOWN_REGEX, (match, tone, inner) => inner);
}

function findHighlightRemovalRange(markdown, start, end) {
  const text = String(markdown || "");
  const s = Math.max(0, Math.min(start, text.length));
  const e = Math.max(s, Math.min(end, text.length));

  if (s < e) {
    const slice = text.slice(s, e);
    const stripped = stripHighlightMarkdown(slice);
    if (stripped !== slice) {
      return { start: s, end: e, replacement: stripped };
    }
  }

  const re = /==(?:\{([a-z]+)\})?([^=\n][^=]*?)==/gi;
  let match;
  while ((match = re.exec(text))) {
    const mStart = match.index;
    const mEnd = match.index + match[0].length;
    const inner = match[2];
    const overlaps = s < e ? s < mEnd && e > mStart : s > mStart && s < mEnd;
    if (!overlaps) continue;
    if (s < e && s >= mStart && e <= mEnd) {
      return { start: mStart, end: mEnd, replacement: inner };
    }
    if (s === e && s > mStart && s < mEnd) {
      return { start: mStart, end: mEnd, replacement: inner };
    }
  }
  return null;
}

function replaceWysiwygMarkdownRange(start, end, replacement) {
  const editor = wysiwygEditorInstance;
  if (!editor) return false;
  return withPreservedEditorScroll(() => {
    const current = String(editor.getMarkdown() || "");
    const safeStart = Math.max(0, Math.min(start, current.length));
    const safeEnd = Math.max(safeStart, Math.min(end, current.length));
    const repl = String(replacement ?? "");
    const next = `${current.slice(0, safeStart)}${repl}${current.slice(safeEnd)}`;
    editor.setMarkdown(normalizeWysiwygImportedMarkdown(next), false);
    syncSourceFromWysiwygEditor();
    const exported = normalizeWysiwygExportedMarkdown(editor.getMarkdown());
    setWysiwygCursorAtMarkdownOffset(exported, safeStart + repl.length);
    syncSaveButtonLamp();
    return true;
  });
}

function captureWysiwygHighlightSelection() {
  const editor = wysiwygEditorInstance;
  if (!editor || editorViewMode !== "wysiwyg") return;
  const text = String(editor.getSelectedText?.() || "");
  const selection = cloneWysiwygMarkdownSelection(editor.getSelection?.());
  if (!text && !selection) return;
  lastWysiwygHighlightCapture = { text, selection };
  captureWysiwygMarkdownSelection();
}

function applyWysiwygHighlightReplacement(tone = editorHighlightTone) {
  const editor = wysiwygEditorInstance;
  if (!editor) return false;

  const safeTone = normalizeHighlightTone(tone);
  setEditorHighlightTone(safeTone);

  const captured = lastWysiwygHighlightCapture;
  const selectedText = String(captured?.text || editor.getSelectedText?.() || "").trim();
  const inner = selectedText || "текст";
  const wrapped = buildHighlightMarkdown(inner, safeTone);

  if (captured?.selection) {
    pendingWysiwygInsertSelection = captured.selection;
    lastWysiwygMarkdownSelection = captured.selection;
  }

  const ok = insertMarkdownAtWysiwygCursor(wrapped);
  if (ok) {
    lastWysiwygHighlightCapture = null;
    scheduleDocOutlineRefresh();
  }
  return ok;
}

function mapMarkdownOutsideFencedCode(markdown, mapper) {
  const text = String(markdown || "");
  const fenceRe = /(^|\n)(`{3,}|~{3,})([^\n]*)\n([\s\S]*?)\n\2(?=\n|$)/g;
  let result = "";
  let lastIndex = 0;
  let match;
  while ((match = fenceRe.exec(text)) !== null) {
    const chunkStart = match.index + match[1].length;
    result += mapper(text.slice(lastIndex, chunkStart));
    result += text.slice(chunkStart, fenceRe.lastIndex);
    lastIndex = fenceRe.lastIndex;
  }
  result += mapper(text.slice(lastIndex));
  return result;
}

function buildHighlightMarkdownFromParts(tone, inner) {
  const safeTone = normalizeHighlightTone(tone);
  const text = String(inner ?? "");
  return safeTone === "yellow" ? `==${text}==` : `=={${safeTone}}${text}==`;
}

function restoreEscapedHighlightMarkdown(markdown) {
  return mapMarkdownOutsideFencedCode(markdown, (segment) =>
    segment.replace(ESCAPED_HIGHLIGHT_MARKDOWN_REGEX, (match, tone, inner) =>
      buildHighlightMarkdownFromParts(tone, inner)
    )
  );
}

function convertHighlightMarkdownToHtml(markdown) {
  return mapMarkdownOutsideFencedCode(markdown, (segment) =>
    segment.replace(HIGHLIGHT_MARKDOWN_REGEX, (match, tone, inner) => {
      const toneClass = normalizeHighlightTone(tone);
      return `<mark class="md-highlight md-highlight--${toneClass}">${inner}</mark>`;
    })
  );
}

function convertHighlightHtmlToMarkdown(content) {
  return String(content || "").replace(HIGHLIGHT_HTML_MARK_REGEX, (match, inner) => {
    const toneMatch = match.match(/\bmd-highlight--([a-z]+)\b/i);
    return buildHighlightMarkdownFromParts(toneMatch?.[1], inner);
  });
}

function buildToastUiHighlightCustomHTMLRenderer() {
  return {
    htmlInline: {
      mark(node, { entering }) {
        return entering
          ? { type: "openTag", tagName: "mark", attributes: node.attrs || {} }
          : { type: "closeTag", tagName: "mark" };
      }
    }
  };
}

function getWysiwygEditorSourceMarkdown() {
  const raw =
    activeSystemFile && systemFileHasEditableFrontmatter(activeSystemFile)
      ? getSystemFileWysiwygBodyMarkdown()
      : fileContentInputNode?.value || "";
  return String(raw || "");
}

function getEditorSelectionSlice() {
  if (editorViewMode === "wysiwyg" && wysiwygEditorInstance) {
    const editor = wysiwygEditorInstance;
    const current = String(editor.getMarkdown() || "");
    const selection =
      cloneWysiwygMarkdownSelection(editor.getSelection?.()) || lastWysiwygMarkdownSelection;
    const { start, end } = resolveWysiwygMarkdownSelection(current, selection);
    return { text: current.slice(start, end), start, end };
  }
  if (!fileContentInputNode) return { text: "", start: 0, end: 0 };
  const start =
    fileContentInputNode.selectionStart ??
    lastSourceEditorSelection?.start ??
    fileContentInputNode.value.length;
  const end = fileContentInputNode.selectionEnd ?? lastSourceEditorSelection?.end ?? start;
  return { text: fileContentInputNode.value.slice(start, end), start, end };
}

function replaceEditorSelectionText(replacement) {
  const snippet = String(replacement || "");
  if (!snippet) return false;
  if (!canInsertDocContentBlocks()) {
    showToast("Выделение доступно только в режиме редактирования", "error");
    return false;
  }

  if (editorViewMode === "wysiwyg" && wysiwygEditorInstance) {
    return insertMarkdownAtWysiwygCursor(snippet);
  }

  return withPreservedEditorScroll(() => {
    const saved = lastSourceEditorSelection;
    const start =
      saved?.start ?? fileContentInputNode.selectionStart ?? fileContentInputNode.value.length;
    const end = saved?.end ?? fileContentInputNode.selectionEnd ?? start;
    const before = fileContentInputNode.value.slice(0, start);
    const after = fileContentInputNode.value.slice(end);
    fileContentInputNode.value = `${before}${snippet}${after}`;
    const cursor = start + snippet.length;
    fileContentInputNode.selectionStart = cursor;
    fileContentInputNode.selectionEnd = cursor;
    lastSourceEditorSelection = { start: cursor, end: cursor };
    fileContentInputNode.dispatchEvent(new Event("input", { bubbles: true }));
    fileContentInputNode.focus({ preventScroll: true });
    syncSaveButtonLamp();
    return true;
  });
}

function setEditorHighlightTone(tone) {
  const safeTone = normalizeHighlightTone(tone);
  editorHighlightTone = safeTone;
  const swatch =
    wysiwygHighlightToolbarRefs?.menuSwatch ||
    wysiwygHighlightToolbarRefs?.swatch ||
    wysiwygHighlightToolbarRefs?.menuBtn?.querySelector(".awn-wysiwyg-highlight-swatch");
  if (swatch) {
    swatch.className = `awn-wysiwyg-highlight-swatch awn-wysiwyg-highlight-swatch--${safeTone}`;
  }
}

function removeEditorTextHighlight() {
  if (!canInsertDocContentBlocks()) {
    showToast("Выделение доступно только в режиме редактирования", "error");
    return false;
  }

  if (editorViewMode === "wysiwyg" && wysiwygEditorInstance) {
    const editor = wysiwygEditorInstance;
    const current = String(editor.getMarkdown() || "");
    const selection =
      cloneWysiwygMarkdownSelection(lastWysiwygHighlightCapture?.selection) ||
      cloneWysiwygMarkdownSelection(editor.getSelection?.()) ||
      lastWysiwygMarkdownSelection;
    const { start, end } = resolveWysiwygMarkdownSelection(current, selection);
    const span = findHighlightRemovalRange(current, start, end);
    if (!span) {
      showToast("Нет подсветки в выделении", "error");
      return false;
    }
    const ok = replaceWysiwygMarkdownRange(span.start, span.end, span.replacement);
    if (ok) {
      lastWysiwygHighlightCapture = null;
      scheduleDocOutlineRefresh();
    } else {
      showToast("Не удалось снять выделение", "error");
    }
    return ok;
  }

  const doc = fileContentInputNode?.value || "";
  const { start, end } = getEditorSelectionSlice();
  const span = findHighlightRemovalRange(doc, start, end);
  if (!span) {
    showToast("Нет подсветки в выделении", "error");
    return false;
  }

  const ok = withPreservedEditorScroll(() => {
    const before = doc.slice(0, span.start);
    const after = doc.slice(span.end);
    fileContentInputNode.value = `${before}${span.replacement}${after}`;
    const cursor = span.start + span.replacement.length;
    fileContentInputNode.selectionStart = cursor;
    fileContentInputNode.selectionEnd = cursor;
    lastSourceEditorSelection = { start: cursor, end: cursor };
    fileContentInputNode.dispatchEvent(new Event("input", { bubbles: true }));
    fileContentInputNode.focus({ preventScroll: true });
    syncSaveButtonLamp();
    return true;
  });
  if (ok) scheduleDocOutlineRefresh();
  return ok;
}

function applyEditorTextHighlight(tone = editorHighlightTone) {
  const safeTone = normalizeHighlightTone(tone);
  setEditorHighlightTone(safeTone);

  if (editorViewMode === "wysiwyg") {
    if (!wysiwygEditorInstance) {
      showToast("WYSIWYG-редактор ещё загружается", "error");
      return false;
    }
    const ok = applyWysiwygHighlightReplacement(safeTone);
    if (!ok) {
      showToast("Не удалось выделить текст", "error");
    }
    return ok;
  }

  const { text } = getEditorSelectionSlice();
  const wrapped = buildHighlightMarkdown(text || "текст", safeTone);
  const ok = replaceEditorSelectionText(wrapped);
  if (ok) {
    scheduleDocOutlineRefresh();
  }
  return ok;
}

function closeWysiwygHighlightPopover() {
  const popover = wysiwygHighlightToolbarRefs?.popover;
  const menuBtn = wysiwygHighlightToolbarRefs?.menuBtn;
  popover?.classList.add("hidden");
  menuBtn?.setAttribute("aria-expanded", "false");
}

function buildWysiwygHighlightToolbarItem() {
  const wrap = document.createElement("div");
  wrap.className = "awn-wysiwyg-highlight-toolbar";

  const mainBtn = document.createElement("button");
  mainBtn.type = "button";
  mainBtn.className = "awn-wysiwyg-highlight-main-btn";
  mainBtn.title = "Выделить текст";
  mainBtn.setAttribute("aria-label", "Выделить текст");
  mainBtn.innerHTML = `
    <span class="awn-wysiwyg-highlight-icon" aria-hidden="true">
      <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
        <path d="m9 11-6 6v3h3l6-6" />
        <path d="m22 12-4.6 4.6a2 2 0 0 1-2.8 0l-5.2-5.2a2 2 0 0 1 0-2.8L14 4" />
      </svg>
    </span>
  `;

  const menuBtn = document.createElement("button");
  menuBtn.type = "button";
  menuBtn.className = "awn-wysiwyg-highlight-menu-btn";
  menuBtn.title = "Цвет выделения";
  menuBtn.setAttribute("aria-label", "Цвет выделения");
  menuBtn.setAttribute("aria-haspopup", "menu");
  menuBtn.setAttribute("aria-expanded", "false");
  menuBtn.innerHTML = `
    <span class="awn-wysiwyg-highlight-swatch awn-wysiwyg-highlight-swatch--yellow" aria-hidden="true"></span>
    <svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
      <path d="M4 6l4 4 4-4" />
    </svg>
  `;

  const popover = document.createElement("div");
  popover.className = "awn-wysiwyg-highlight-popover hidden";
  popover.setAttribute("role", "menu");
  popover.setAttribute("aria-label", "Цвет выделения");
  popover.innerHTML = `${HIGHLIGHT_TONE_OPTIONS.map(
    ({ tone, label }) => `
      <button
        type="button"
        class="awn-wysiwyg-highlight-tone-btn"
        role="menuitem"
        data-highlight-tone="${tone}"
        title="${label}"
        aria-label="${label}"
      >
        <span class="awn-wysiwyg-highlight-tone-swatch awn-wysiwyg-highlight-tone-swatch--${tone}"></span>
      </button>
    `
  ).join("")}
    <button
      type="button"
      class="awn-wysiwyg-highlight-clear-btn"
      role="menuitem"
      title="Снять выделение"
      aria-label="Снять выделение"
    >Снять выделение</button>`;

  wrap.append(mainBtn, menuBtn, popover);

  const bindHighlightToolbar = () => {
    if (wrap.dataset.awnBound === "1") return;
    wrap.dataset.awnBound = "1";

    const captureSelection = (event) => {
      event.preventDefault();
      event.stopPropagation();
      captureWysiwygHighlightSelection();
    };

    mainBtn.addEventListener("pointerdown", captureSelection, true);
    menuBtn.addEventListener("pointerdown", captureSelection, true);
    popover.addEventListener("pointerdown", captureSelection, true);

    mainBtn.addEventListener("click", () => {
      applyEditorTextHighlight(editorHighlightTone);
    });

    menuBtn.addEventListener("click", (event) => {
      event.stopPropagation();
      const shouldOpen = popover.classList.contains("hidden");
      closeWysiwygHighlightPopover();
      if (shouldOpen) {
        popover.classList.remove("hidden");
        menuBtn.setAttribute("aria-expanded", "true");
      }
    });

    popover.addEventListener("click", (event) => {
      const clearBtn = event.target.closest(".awn-wysiwyg-highlight-clear-btn");
      if (clearBtn) {
        removeEditorTextHighlight();
        closeWysiwygHighlightPopover();
        return;
      }
      const toneBtn = event.target.closest(".awn-wysiwyg-highlight-tone-btn");
      if (!toneBtn) return;
      applyEditorTextHighlight(toneBtn.dataset.highlightTone || "yellow");
      closeWysiwygHighlightPopover();
    });
  };

  const clearBtn = popover.querySelector(".awn-wysiwyg-highlight-clear-btn");

  wysiwygHighlightToolbarRefs = {
    wrap,
    mainBtn,
    menuBtn,
    popover,
    clearBtn,
    menuSwatch: menuBtn.querySelector(".awn-wysiwyg-highlight-swatch")
  };

  return {
    name: "awnHighlight",
    el: wrap,
    onMounted: () => {
      bindHighlightToolbar();
    },
    onUpdated: ({ disabled }) => {
      mainBtn.disabled = Boolean(disabled);
      menuBtn.disabled = Boolean(disabled);
      popover.querySelectorAll(".awn-wysiwyg-highlight-tone-btn").forEach((btn) => {
        btn.disabled = Boolean(disabled);
      });
      if (wysiwygHighlightToolbarRefs?.clearBtn) {
        wysiwygHighlightToolbarRefs.clearBtn.disabled = Boolean(disabled);
      }
      if (disabled) closeWysiwygHighlightPopover();
    }
  };
}

async function uploadMediaAttachment(
  file,
  {
    nodePath = getAttachmentUploadNodePath(),
    subdir = null,
    inlinePaste = false,
    pastedNaming = false,
    fileName: preferredFileName = null,
    libraryFolder = null,
    mediaMode = null
  } = {}
) {
  if (!file) return null;
  const resolvedNodePath = nodePath || getAttachmentUploadNodePath();
  if (!resolvedNodePath) {
    throw new Error(activeSystemFile ? "Не удалось определить workspace для служебного файла" : "Сначала откройте тему");
  }
  const usePastedNaming = inlinePaste || pastedNaming;
  const resolvedMediaMode = mediaMode || activeContentMode;
  const effectiveSubdir = inlinePaste
    ? PASTED_ASSETS_SUBDIR
    : subdir ??
      (isMediaLibraryContentMode(resolvedMediaMode) || isNavigationHubRailSlotCreateActive()
        ? activeMediaSectionFolder || getActiveMediaSectionParentForCreate()
        : null);
  const normalizedFile = await normalizeImageAttachmentFile(file, { pasted: usePastedNaming });
  const data = await readFileAsBase64(normalizedFile);
  const uploadManifestPath = getUploadStorageContextPath();
  const uploadNodePath =
    (isMediaLibraryContentMode(resolvedMediaMode) || isNavigationHubRailSlotCreateActive()
      ? getSlotRecordCreateManifestApiPath()
      : "") ||
    getOverviewNodeApiPath(resolvedNodePath) ||
    resolveManifestPathForNodeApi(getResolvedNodePath(resolvedNodePath) || resolvedNodePath);
  const response = await fetch(buildApiUrl("/api/media/file"), {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      path: uploadNodePath,
      contextPath: uploadManifestPath,
      data,
      fileName:
        preferredFileName ||
        normalizedFile.name ||
        (usePastedNaming
          ? buildPastedAttachmentFileName(normalizedFile)
          : buildInlineAttachmentFileName(normalizedFile)),
      mimeType: normalizedFile.type,
      subdir: effectiveSubdir || undefined,
      createSubdir: Boolean(effectiveSubdir),
      libraryFolder:
        libraryFolder ||
        (isMediaLibraryContentMode(resolvedMediaMode) ? getMediaLibraryStorageSubfolder(resolvedMediaMode) : undefined)
    })
  });
  if (!response.ok) {
    const errorData = await response.json().catch(() => ({}));
    const details = errorData.details ? `: ${errorData.details}` : "";
    throw new Error(`${errorData.error || `Request failed with ${response.status}`}${details}`);
  }
  return response.json();
}

