function normalizeAgentSettingsFieldGroupsClient(fieldGroups = []) {
  return (Array.isArray(fieldGroups) ? fieldGroups : [])
    .filter((group) => group && group.id)
    .map((group) => ({
      id: String(group.id),
      name: group.name || group.title || group.id,
      description: String(group.description || "").trim(),
      subgroups: (Array.isArray(group.subgroups) ? group.subgroups : [])
        .filter((item) => item && item.id)
        .map((item) => ({
          id: String(item.id),
          name: item.name || item.title || item.id,
          description: String(item.description || "").trim(),
          sort: Number(item.sort) || 0,
          defaultOpen: Boolean(item.defaultOpen),
          disabled: Boolean(item.disabled)
        }))
        .sort((a, b) => a.sort - b.sort || a.id.localeCompare(b.id, "ru"))
    }));
}

const agentSettingsSchemaCacheByScope = new Map();
const agentSettingsSchemaLoadPromises = new Map();

function resolveAgentSettingsSchemaScope(manifestPath = getNodeSettingsManifestPath()) {
  if (isProjectSettingsGlobalScope(manifestPath)) return "global";
  if (isProjectSettingsIntegrationsSettingsScope(manifestPath)) return "integrations";
  if (isProjectSettingsUserSettingsScope(manifestPath)) return "user";
  return "local";
}

async function loadAgentSettingsSchemaBundle(options = {}) {
  const scope = options.scope || resolveAgentSettingsSchemaScope(options.manifestPath);
  if (!options.force && agentSettingsSchemaCacheByScope.has(scope)) {
    const cached = agentSettingsSchemaCacheByScope.get(scope);
    if (Object.keys(cached?.settingsFields || {}).length) return cached;
    agentSettingsSchemaCacheByScope.delete(scope);
  }
  if (!options.force && agentSettingsSchemaLoadPromises.has(scope)) {
    return agentSettingsSchemaLoadPromises.get(scope);
  }

  const loadPromise = (async () => {
    const resolveFallbackAgentSettingsSchemaPayload = async () => {
      if (!awnTypesCache?.types) await loadAwnTypes(activeWorkspaceId);
      const typeId =
        scope === "global"
          ? "awn.settings.platform"
          : scope === "user"
            ? "awn.settings.user"
            : scope === "integrations"
              ? "awn.settings.integrations"
              : "awn.settings.workspace";
      const typeDef = mergeClientTypeDefinition(typeId);
      return {
        scope,
        typeId: typeDef?.id || typeId,
        settingsFields: mergeAgentSettingsSchemaFields(typeDef?.fields || {}),
        settingsFieldGroups: normalizeAgentSettingsFieldGroupsClient(typeDef?.fieldGroups || [])
      };
    };

    const response = await fetch(buildApiUrl("/api/agent/settings-schema", { scope }));
    if (response.ok) {
      const data = await response.json();
      const settingsFields = mergeAgentSettingsSchemaFields(data.fields || {});
      if (Object.keys(settingsFields).length) {
        return storeAgentSettingsSchemaCacheEntry(scope, {
          scope,
          typeId:
            data.type ||
            (scope === "global"
              ? "awn.settings.platform"
              : scope === "user"
                ? "awn.settings.user"
                : scope === "integrations"
                  ? "awn.settings.integrations"
                  : "awn.settings.workspace"),
          settingsFields,
          settingsFieldGroups: normalizeAgentSettingsFieldGroupsClient(data.fieldGroups || [])
        });
      }
    }
    return storeAgentSettingsSchemaCacheEntry(scope, await resolveFallbackAgentSettingsSchemaPayload());
  })();

  agentSettingsSchemaLoadPromises.set(scope, loadPromise);
  try {
    return await loadPromise;
  } finally {
    agentSettingsSchemaLoadPromises.delete(scope);
  }
}

function buildSettingsFieldGroupsFromFields(schemaFields = {}) {
  const keys = Object.keys(schemaFields);
  const order = getSchemaEditorGroupOrder(schemaFields, keys);
  return order.map((groupId) => ({
    id: groupId,
    name:
      groupId === PROJECT_SETTINGS_UNGROUPED_GROUP_ID
        ? PROJECT_SETTINGS_UNGROUPED_GROUP_LABEL
        : groupId
  }));
}

function resolveNodeSettingsGroupLabel(groupId, fieldGroups = []) {
  if (groupId === PROJECT_SETTINGS_UNGROUPED_GROUP_ID) return PROJECT_SETTINGS_UNGROUPED_GROUP_LABEL;
  const hit = (fieldGroups || []).find((group) => group && group.id === groupId);
  if (hit?.name) return hit.name;
  if (hit?.title) return hit.title;
  return groupId;
}

function resolveProjectSettingsGroupDescription(groupId, fieldGroups = []) {
  const hit = (fieldGroups || []).find((group) => group && group.id === groupId);
  return String(hit?.description || "").trim();
}

const NODE_SETTINGS_SUBGROUP_OPEN_STORAGE_KEY = "agent-cms:project-settings-subgroup-open.v1";

function resolvePropsFieldSubgroupId(key, fieldDef = getPropsFieldDef(key)) {
  const explicit = fieldDef?.subgroup;
  return explicit ? String(explicit) : "";
}

function getNodeSettingsFieldSubgroups(fieldGroups = [], groupId = "") {
  const hit = (fieldGroups || []).find((group) => group && group.id === groupId);
  return Array.isArray(hit?.subgroups) ? hit.subgroups : [];
}

function buildNodeSettingsFieldSubgroupsFromFields(schemaFields = {}, groupId = "", entries = []) {
  const order = [];
  const byId = new Map();
  for (const entry of entries) {
    const fieldDef = schemaFields[entry.key];
    if (resolvePropsFieldGroupId(entry.key, fieldDef) !== groupId) continue;
    const subgroupId = resolvePropsFieldSubgroupId(entry.key, fieldDef);
    if (!subgroupId) continue;
    if (!byId.has(subgroupId)) {
      byId.set(subgroupId, {
        id: subgroupId,
        name: subgroupId,
        description: "",
        defaultOpen: order.length === 0,
        sort: order.length
      });
      order.push(subgroupId);
    }
  }
  return order.map((id) => byId.get(id));
}

function resolveNodeSettingsFieldSubgroups(
  fieldGroups = [],
  groupId = "",
  schemaFields = {},
  entries = []
) {
  const fromSchema = getNodeSettingsFieldSubgroups(fieldGroups, groupId);
  if (fromSchema.length) return fromSchema;
  return buildNodeSettingsFieldSubgroupsFromFields(schemaFields, groupId, entries);
}

function findNodeSettingsSubgroupDef(subgroupId, subgroupDefs = []) {
  return (subgroupDefs || []).find((item) => item && item.id === subgroupId) || null;
}

function resolveNodeSettingsSubgroupLabel(subgroupId, subgroupDefs = []) {
  const hit = findNodeSettingsSubgroupDef(subgroupId, subgroupDefs);
  return hit?.name || hit?.title || subgroupId;
}

function resolveNodeSettingsSubgroupDescription(subgroupId, subgroupDefs = []) {
  const hit = findNodeSettingsSubgroupDef(subgroupId, subgroupDefs);
  return String(hit?.description || "").trim();
}

function buildNodeSettingsSubgroupStorageKey(groupId, subgroupId) {
  const scope = getNodeSettingsManifestPath() || "unknown";
  return `${scope}:${groupId}:${subgroupId}`;
}

function loadNodeSettingsSubgroupOpenState() {
  try {
    const raw = readStorageItem(NODE_SETTINGS_SUBGROUP_OPEN_STORAGE_KEY);
    if (!raw) return {};
    const parsed = JSON.parse(raw);
    return parsed && typeof parsed === "object" ? parsed : {};
  } catch {
    return {};
  }
}

function saveNodeSettingsSubgroupOpenState(storageKey, isOpen) {
  if (!storageKey) return;
  const state = loadNodeSettingsSubgroupOpenState();
  state[storageKey] = Boolean(isOpen);
  try {
    localStorage.setItem(NODE_SETTINGS_SUBGROUP_OPEN_STORAGE_KEY, JSON.stringify(state));
  } catch {
    // ignore quota / private mode
  }
}

function isNodeSettingsSubgroupDisabled(subgroupDef = {}) {
  return Boolean(subgroupDef?.disabled);
}

function resolveNodeSettingsSubgroupOpen(groupId, subgroupDef = {}) {
  if (isNodeSettingsSubgroupDisabled(subgroupDef)) return false;
  const storageKey = buildNodeSettingsSubgroupStorageKey(groupId, subgroupDef.id);
  const state = loadNodeSettingsSubgroupOpenState();
  if (storageKey in state) return Boolean(state[storageKey]);
  return Boolean(subgroupDef.defaultOpen);
}

function createNodeSettingsSubgroupAccordion(subgroupDef, entries, schemaFields, groupId, subgroupDefs = []) {
  const disabled = isNodeSettingsSubgroupDisabled(subgroupDef);
  const section = document.createElement("details");
  section.className = "node-settings-subgroup-accordion";
  if (disabled) section.classList.add("is-disabled");
  section.dataset.subgroupId = subgroupDef.id;
  section.dataset.groupId = groupId;
  section.open = resolveNodeSettingsSubgroupOpen(groupId, subgroupDef);
  section.addEventListener("toggle", () => {
    if (disabled) {
      section.open = false;
      return;
    }
    saveNodeSettingsSubgroupOpenState(
      buildNodeSettingsSubgroupStorageKey(groupId, subgroupDef.id),
      section.open
    );
  });

  const summary = document.createElement("summary");
  summary.className = "node-settings-subgroup-accordion-summary";
  if (disabled) {
    summary.setAttribute("aria-disabled", "true");
    summary.title = "Пока недоступно в Voice Shell";
  }

  const summaryMain = document.createElement("span");
  summaryMain.className = "node-settings-subgroup-accordion-summary-main";

  const title = document.createElement("span");
  title.className = "node-settings-subgroup-accordion-title";
  title.textContent = resolveNodeSettingsSubgroupLabel(subgroupDef.id, subgroupDefs);
  summaryMain.appendChild(title);

  const hint = resolveNodeSettingsSubgroupDescription(subgroupDef.id, subgroupDefs);
  if (hint) {
    const hintNode = document.createElement("span");
    hintNode.className = "node-settings-subgroup-accordion-hint";
    hintNode.textContent = hint;
    summaryMain.appendChild(hintNode);
  }

  summary.appendChild(summaryMain);

  const count = document.createElement("span");
  count.className = "node-settings-subgroup-accordion-count";
  count.textContent = String(entries.length);
  summary.appendChild(count);

  const chevronWrap = document.createElement("span");
  chevronWrap.className = "node-settings-subgroup-accordion-chevron";
  chevronWrap.setAttribute("aria-hidden", "true");
  const chevron = document.createElement("span");
  chevron.className = "nav-book-toc-folder-chevron";
  chevronWrap.appendChild(chevron);
  summary.appendChild(chevronWrap);

  section.appendChild(summary);

  const body = document.createElement("div");
  body.className = "node-settings-subgroup-accordion-body";
  for (const entry of entries) {
    body.append(createNodeSettingsFieldRow(entry, schemaFields[entry.key]));
  }
  section.appendChild(body);
  return section;
}

function appendNodeSettingsGroupFields(fieldsNode, entries, schemaFields, { groupId, fieldGroups = [] }) {
  const entriesInGroup = entries.filter(
    (entry) => resolvePropsFieldGroupId(entry.key, schemaFields[entry.key]) === groupId
  );
  const subgroupDefs = resolveNodeSettingsFieldSubgroups(fieldGroups, groupId, schemaFields, entriesInGroup);
  fieldsNode.classList.toggle("has-settings-subgroups", Boolean(subgroupDefs.length));
  if (!subgroupDefs.length) {
    for (const entry of entriesInGroup) {
      fieldsNode.append(createNodeSettingsFieldRow(entry, schemaFields[entry.key]));
    }
    return entriesInGroup.length;
  }

  const subgroupIds = new Set(subgroupDefs.map((item) => item.id));
  const bySubgroup = new Map(subgroupDefs.map((item) => [item.id, []]));
  const ungrouped = [];
  for (const entry of entriesInGroup) {
    const subgroupId = resolvePropsFieldSubgroupId(entry.key, schemaFields[entry.key]);
    if (!subgroupId || !subgroupIds.has(subgroupId)) {
      ungrouped.push(entry);
      continue;
    }
    bySubgroup.get(subgroupId).push(entry);
  }

  let rendered = 0;
  for (const entry of ungrouped) {
    fieldsNode.append(createNodeSettingsFieldRow(entry, schemaFields[entry.key]));
    rendered += 1;
  }
  for (const subgroupDef of subgroupDefs) {
    const subgroupEntries = bySubgroup.get(subgroupDef.id) || [];
    if (!subgroupEntries.length) continue;
    fieldsNode.append(
      createNodeSettingsSubgroupAccordion(subgroupDef, subgroupEntries, schemaFields, groupId, subgroupDefs)
    );
    rendered += subgroupEntries.length;
  }
  return rendered;
}

