const REGISTRY_QUERY_PRESETS_SETTINGS_KEY = "registry-query-presets";

async function fetchRegistryQueryCommentByIdMap(agentId = activeWorkspaceId) {
  try {
    const response = await fetch(buildApiUrl("/api/agent/registry-queries", {}, agentId));
    if (!response.ok) return null;
    const payload = await response.json();
    const queries = Array.isArray(payload?.catalog?.queries) ? payload.catalog.queries : [];
    const map = new Map();
    for (const row of queries) {
      const id = String(row?.id || "").trim();
      if (!id) continue;
      map.set(id, String(row?.comment || "").trim());
    }
    return map.size ? map : null;
  } catch {
    return null;
  }
}

function enrichRegistryQueryPresetItems(items, commentById = null) {
  if (!Array.isArray(items)) return items;
  return items.map((item) => {
    if (!item || typeof item !== "object") return item;
    const about = String(item.about || item.description || item.comment || "").trim();
    if (about) {
      return about === item.about ? item : { ...item, about };
    }
    const id = String(item.id || "").trim();
    const fromCatalog = id && commentById ? commentById.get(id) : "";
    if (fromCatalog) return { ...item, about: fromCatalog };
    return item;
  });
}

async function enrichWorkspaceSettingsRegistryQueryPresets(settings, agentId = activeWorkspaceId) {
  if (!settings || typeof settings !== "object") return settings;
  const presets = settings[REGISTRY_QUERY_PRESETS_SETTINGS_KEY];
  if (!Array.isArray(presets) || !presets.length) return settings;
  const commentById = await fetchRegistryQueryCommentByIdMap(agentId);
  return {
    ...settings,
    [REGISTRY_QUERY_PRESETS_SETTINGS_KEY]: enrichRegistryQueryPresetItems(presets, commentById)
  };
}

async function loadNodeSettingsForManifest(nodePath, options = {}) {
  const manifestPath = getNodeSettingsManifestPath(nodePath);
  if (!manifestPath) return null;

  if (!options.force) {
    const cached = nodeSettingsCacheByManifest.get(manifestPath);
    if (cached) return cached;
  }

  const schemaManifestPath = isProjectSettingsAgentSettingsScope(manifestPath)
    ? getAgentWorkspaceRootManifestPath()
    : manifestPath;
  let data;
  let settingsFieldGroups = null;
  if (isProjectSettingsMode() && isProjectSettingsGlobalScope(manifestPath)) {
    const response = await fetch(buildApiUrl("/api/platform/settings-global"));
    if (!response.ok) throw new Error(`Request failed with ${response.status}`);
    data = await response.json();
  } else if (isProjectSettingsMode() && isProjectSettingsLocalScope(manifestPath)) {
    const response = await fetch(buildApiUrl("/api/workspace/settings"));
    if (!response.ok) throw new Error(`Request failed with ${response.status}`);
    data = await response.json();
  } else if (isProjectSettingsMode() && isProjectSettingsIntegrationsSettingsScope(manifestPath)) {
    const response = await fetch(buildApiUrl("/api/integrations/settings"));
    if (!response.ok) throw new Error(`Request failed with ${response.status}`);
    data = await response.json();
  } else if (isProjectSettingsMode() && isProjectSettingsUserSettingsScope(manifestPath)) {
    const response = await fetch(buildApiUrl("/api/user/settings"));
    if (!response.ok) throw new Error(`Request failed with ${response.status}`);
    data = await response.json();
  } else {
    data = await loadNodeConfig(manifestPath, { force: true });
  }

  let state = parseNodeSettingsState(data.content || "");
  let settingsFields = {};
  if (isProjectSettingsAgentSettingsScope(manifestPath)) {
    const schemaBundle = await loadAgentSettingsSchemaBundle({
      force: options.force,
      manifestPath,
      scope: resolveAgentSettingsSchemaScope(manifestPath)
    });
    settingsFields = schemaBundle.settingsFields;
    settingsFieldGroups = schemaBundle.settingsFieldGroups;
    if (data.settings && typeof data.settings === "object") {
      const mergeNormalizedSettings =
        isProjectSettingsGlobalScope(manifestPath) ||
        isProjectSettingsLocalScope(manifestPath) ||
        isProjectSettingsIntegrationsSettingsScope(manifestPath) ||
        isProjectSettingsUserSettingsScope(manifestPath);
      if (mergeNormalizedSettings) {
        let mergedSettings = data.settings;
        if (isProjectSettingsLocalScope(manifestPath)) {
          mergedSettings = await enrichWorkspaceSettingsRegistryQueryPresets(mergedSettings);
        }
        state = {
          ...state,
          entries: NodeConfigBundle.settingsObjectToEntries(mergedSettings)
        };
      }
    }
    state.entries = buildNodeSettingsEntriesFromSchema(state.entries, settingsFields);
    if (isProjectSettingsGlobalScope(manifestPath) && data.meta) {
      state.entries = applyPlatformMetaToReadonlyEntries(state.entries, settingsFields, data.meta);
    }
  } else {
    const mergeSettingsFields = mergeTopicSchemaSettingsFields;
    try {
      const schemaCache = await loadTopicSchemaForManifest(schemaManifestPath, { force: options.force });
      settingsFields = mergeSettingsFields(schemaCache?.awnSchema?.settings?.fields || {});
      state.entries = buildNodeSettingsEntriesFromSchema(state.entries, settingsFields);
    } catch {
      state.entries = buildNodeSettingsEntriesFromSchema(state.entries, {});
    }
  }
  const payload = {
    manifestPath,
    configPath: data.path || "",
    settingsPath: data.path || "",
    exists: Boolean(data.exists),
    settingsScope: isProjectSettingsGlobalScope(manifestPath)
      ? "global"
      : isProjectSettingsLocalScope(manifestPath)
        ? "local"
        : isProjectSettingsIntegrationsSettingsScope(manifestPath)
          ? "integrations"
          : isProjectSettingsUserSettingsScope(manifestPath)
            ? "user"
            : "node",
    platformMeta: data.meta || null,
    settingsFields,
    settingsFieldGroups,
    ...state
  };
  nodeSettingsCacheByManifest.set(manifestPath, payload);
  if (isProjectSettingsMode()) {
    setProjectSettingsScopeStatusFromCache(manifestPath, payload);
  }
  return payload;
}

function formatNodeSettingsFieldLabel(key, fieldDef) {
  const displayName = getFieldDefDisplayName(fieldDef, key);
  if (displayName && displayName !== key) return displayName;
  const suffix = String(key || "")
    .replace(/^field_/i, "")
    .replace(/[_-]+/g, " ")
    .trim();
  if (suffix && /^field_/i.test(key)) return `Поле ${suffix}`;
  return displayName || key || "Поле";
}

function resolveNodeSettingsFieldDescription(fieldDef) {
  return coerceSettingsTextValue(fieldDef?.description || "", "").trim();
}

function createNodeSettingsFieldDescriptionNode(fieldDef) {
  const text = resolveNodeSettingsFieldDescription(fieldDef);
  if (!text) return null;

  const wrap = document.createElement("div");
  wrap.className = "node-config-field-description";

  const paragraph = document.createElement("p");
  paragraph.className = "node-config-field-description-text";
  paragraph.textContent = text;
  wrap.append(paragraph);
  return wrap;
}

function createNodeSettingsFieldRow(entry, fieldDef) {
  const readonly = isProjectSettingsReadonlyField(fieldDef);
  const locked = readonly || isProjectSettingsLockedField(fieldDef);
  const meta = { ...getNodeSettingsFieldMeta(entry.key, fieldDef), locked };
  const typeId = resolveFieldTypeId(fieldDef?.type || "awn.field.string");
  const displayLabel = formatNodeSettingsFieldLabel(entry.key, fieldDef);
  const entryKind = fieldDefToEntryKind(fieldDef);

  const row = document.createElement("div");
  row.className = "node-config-field-row node-config-field-row--compact";
  if (readonly) row.classList.add("is-readonly");
  else if (locked) row.classList.add("is-readonly");
  const settingsWidget = resolvePropsFieldWidget(entry.key, fieldDef);
  const isCompactChoiceWidget = ["enum-checkbox", "select-multiple", "radio"].includes(settingsWidget);
  if (
    (entryKind === "array" && !isCompactChoiceWidget) ||
    isFileFieldTypeId(fieldDef?.type) ||
    fieldTypeIs(typeId, "text") ||
    ["textarea", "code", "json", "object", "repeater"].includes(settingsWidget)
  ) {
    row.classList.add("is-tall");
  }
  row.dataset.configRowKey = entry.key;

  const head = document.createElement("div");
  head.className = "node-config-field-head";

  const label = buildFieldLabelElement(displayLabel, {
    tag: "label",
    className: "node-config-field-label",
    typeId,
    key: entry.key,
    required: meta.required,
    title: meta.hint
      ? `${entry.key} — ${meta.hint}`
      : fieldDef?.description
        ? `${entry.key} — ${fieldDef.description}`
        : entry.key
  });

  const hideFieldKey =
    readonly ||
    locked ||
    String(entry.key || "").startsWith("awn-id-") ||
    String(entry.key || "").startsWith("sys-");

  const labelWrap = document.createElement("div");
  labelWrap.className = "node-config-field-label-wrap";
  labelWrap.append(label);
  if (!hideFieldKey) {
    const keyCode = document.createElement("code");
    keyCode.className = "node-config-field-key";
    keyCode.textContent = entry.key;
    keyCode.title = "Ключ в awn_settings";
    labelWrap.append(keyCode);
  }
  head.append(labelWrap);

  const valueControl = createPropsFormValueControl(entry, meta);
  valueControl.classList.add("node-config-field-value");

  const descriptionNode = createNodeSettingsFieldDescriptionNode(fieldDef);
  if (descriptionNode) {
    row.classList.add("has-field-description");
    row.append(descriptionNode, head, valueControl);
  } else {
    row.append(head, valueControl);
  }

  return row;
}

function readNodeSettingsEntryFromRow(row, cacheOverride = null) {
  const key = row?.dataset?.configRowKey || "";
  const cache = cacheOverride || getNodeSettingsCache();
  const fieldDef = cache?.settingsFields?.[key];
  const base =
    (cache?.entries || []).find((entry) => entry.key === key) ||
    (fieldDef
      ? { key, kind: fieldDefToEntryKind(fieldDef), value: fieldDefDefaultValue(fieldDef), fieldDef }
      : { key, kind: "string", value: "" });
  const valueWrap = row?.querySelector('.props-form-value-wrap[data-field="value"]');
  if (!valueWrap) return { ...base, key };
  const entry = fieldDef
    ? { ...base, kind: fieldDefToEntryKind(fieldDef), fieldDef }
    : { ...base };
  const widget = valueWrap.dataset.widget || resolvePropsFieldWidget(key, fieldDef);
  return applyPropsFormWidgetValue(
    { ...entry, key },
    readPropsFormValueFromControl(valueWrap),
    widget
  );
}

function syncNodeSettingsCacheFromDom(cache = getNodeSettingsCache()) {
  const fieldsNode = getNodeSettingsFieldsContainer();
  if (!cache || !fieldsNode) return cache;
  const schemaFields = cache.settingsFields || {};
  const entryMap = new Map((cache.entries || []).map((entry) => [entry.key, entry]));
  fieldsNode.querySelectorAll(".node-config-field-row").forEach((row) => {
    const entry = readNodeSettingsEntryFromRow(row, cache);
    if (!entry.key || !schemaFields[entry.key]) return;
    if (isProjectSettingsReadonlyField(schemaFields[entry.key])) return;
    entryMap.set(
      entry.key,
      normalizeNodeSettingsEntryValue(entry, schemaFields[entry.key])
    );
  });
  cache.entries = buildNodeSettingsEntriesFromSchema(Array.from(entryMap.values()), schemaFields);
  return cache;
}

function renderNodeSettingsEditor(cache = getNodeSettingsCache()) {
  const fieldsNode = getNodeSettingsFieldsContainer();
  const emptyNode = getNodeSettingsEmptyContainer();
  if (!fieldsNode || !emptyNode) return;

  cache = hydrateNodeSettingsCacheFromAgentSchemaCache(cache);

  fieldsNode.replaceChildren();
  fieldsNode.classList.remove("has-settings-subgroups");

  const schemaFields = cache?.settingsFields || {};
  const schemaKeys = Object.keys(schemaFields);
  if (!schemaKeys.length) {
    emptyNode.classList.remove("hidden");
    emptyNode.textContent = isProjectSettingsAgentSettingsScope(cache?.manifestPath)
      ? "Схема настроек не найдена — проверьте platform.yml / workspace.yml / user.yml в awn-system/types/settings/."
      : "Полей пока нет — добавьте их во вкладке «Настройки» в редакторе схемы полей.";
    return;
  }

  let entries = buildNodeSettingsEntriesFromSchema(cache?.entries || [], schemaFields);
  if (isProjectSettingsGlobalScope(cache?.manifestPath) && cache?.platformMeta) {
    entries = applyPlatformMetaToReadonlyEntries(entries, schemaFields, cache.platformMeta);
  }
  cache.entries = entries;

  if (!entries.length) {
    emptyNode.classList.remove("hidden");
    return;
  }
  emptyNode.classList.add("hidden");

  const fieldGroups =
    Array.isArray(cache?.settingsFieldGroups) && cache.settingsFieldGroups.length
      ? cache.settingsFieldGroups
      : buildSettingsFieldGroupsFromFields(schemaFields);
  const groupOrder = mergeSettingsGroupOrder(
    getSchemaEditorGroupOrder(schemaFields, entries.map((entry) => entry.key)),
    fieldGroups
  );
  const useSidebarAgentTabs =
    isProjectSettingsMode() && isProjectSettingsAgentSettingsScope(cache?.manifestPath);
  const useTabbedGroups = isProjectSettingsMode() && groupOrder.length > 1 && !useSidebarAgentTabs;

  if (useSidebarAgentTabs) {
    projectSettingsGroupTabsNode?.classList.add("hidden");
    projectSettingsGroupTabsNode?.replaceChildren();
    if (!projectSettingsActiveGroupId || !groupOrder.includes(projectSettingsActiveGroupId)) {
      projectSettingsActiveGroupId = groupOrder[0];
    }
    syncProjectSettingsConfigGroupLead(cache);
    const rendered = appendNodeSettingsGroupFields(fieldsNode, entries, schemaFields, {
      groupId: projectSettingsActiveGroupId,
      fieldGroups
    });
    if (!rendered) {
      emptyNode.textContent = "В этой группе пока нет полей.";
      emptyNode.classList.remove("hidden");
    }
    return;
  }

  if (useTabbedGroups) {
    if (!projectSettingsActiveGroupId || !groupOrder.includes(projectSettingsActiveGroupId)) {
      projectSettingsActiveGroupId = groupOrder[0];
    }
    if (projectSettingsGroupTabsNode) {
      projectSettingsGroupTabsNode.replaceChildren();
      projectSettingsGroupTabsNode.classList.remove("hidden");
      for (const groupId of groupOrder) {
        const tab = document.createElement("button");
        tab.type = "button";
        tab.className = "project-settings-group-tab";
        tab.dataset.groupId = groupId;
        tab.setAttribute("role", "tab");
        tab.setAttribute("aria-selected", groupId === projectSettingsActiveGroupId ? "true" : "false");
        tab.classList.toggle("is-active", groupId === projectSettingsActiveGroupId);
        tab.textContent = resolveNodeSettingsGroupLabel(groupId, fieldGroups);
        tab.addEventListener("click", () => {
          projectSettingsActiveGroupId = groupId;
          renderNodeSettingsEditor(cache);
        });
        projectSettingsGroupTabsNode.append(tab);
      }
    }
    const rendered = appendNodeSettingsGroupFields(fieldsNode, entries, schemaFields, {
      groupId: projectSettingsActiveGroupId,
      fieldGroups
    });
    if (!rendered) {
      emptyNode.textContent = "В этой группе пока нет полей.";
      emptyNode.classList.remove("hidden");
    }
    return;
  }

  projectSettingsGroupTabsNode?.classList.add("hidden");
  projectSettingsGroupTabsNode?.replaceChildren();

  for (const entry of entries) {
    fieldsNode.append(createNodeSettingsFieldRow(entry, schemaFields[entry.key]));
  }
}

function handleNodeConfigFieldsInput() {
  if (!isNodeConfigEditorMode() && !isProjectSettingsMode()) return;
  syncNodeSettingsCacheFromDom();
  syncSaveButtonLamp();
  syncProjectSettingsSaveButtonState();
}

async function saveNodeSettingsContent() {
  const manifestPath = getNodeSettingsManifestPath();
  if (!manifestPath) throw new Error("Конфигурация доступна только для тем с bundle");
  const cache = syncNodeSettingsCacheFromDom();
  if (!cache) throw new Error("Конфигурация не загружена");

  const useProjectSettingsApi =
    isProjectSettingsMode() && isProjectSettingsAgentSettingsScope(manifestPath);
  if (!useProjectSettingsApi) {
    const fresh = await loadNodeConfig(manifestPath, { force: true });
    const freshState = parseNodeSettingsState(fresh.content || "");
    cache.awnUi = freshState.awnUi;
    cache.defaultLandingMode = freshState.defaultLandingMode;
  }
  const content = useProjectSettingsApi
    ? buildSettingsYamlFromState(cache, cache?.settingsFields || {})
    : buildNodeConfigYamlFromState(cache);
  const saveUrl = useProjectSettingsApi
    ? isProjectSettingsGlobalScope(manifestPath)
      ? buildApiUrl("/api/platform/settings-global")
      : isProjectSettingsUserSettingsScope(manifestPath)
        ? buildApiUrl("/api/user/settings")
        : isProjectSettingsIntegrationsSettingsScope(manifestPath)
          ? buildApiUrl("/api/integrations/settings")
          : buildApiUrl("/api/workspace/settings")
    : buildApiUrl("/api/file/node-config");
  const saveBody = useProjectSettingsApi
    ? JSON.stringify({ content })
    : JSON.stringify({ path: manifestPath, content });
  const response = await fetch(saveUrl, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: saveBody
  });
  if (!response.ok) {
    const errorData = await response.json().catch(() => ({}));
    const reason = errorData.error || `Request failed with ${response.status}`;
    const details = errorData.details ? `: ${errorData.details}` : "";
    throw new Error(`${reason}${details}`);
  }

  const data = await response.json();
  cache.exists = Boolean(data.exists);
  cache.configPath = data.path || cache.configPath;
  cache.settingsPath = data.path || cache.settingsPath;
  const nextState = parseNodeSettingsState(data.content || content);
  cache.headerComment = nextState.headerComment;
  cache.entries = buildNodeSettingsEntriesFromSchema(
    nextState.entries,
    cache.settingsFields || {}
  );
  cache.awnUi = nextState.awnUi || cache.awnUi || {};
  cache.defaultLandingMode = nextState.defaultLandingMode;
  cache.awnSchemaYaml = nextState.awnSchemaYaml;
  if (!useProjectSettingsApi) {
    setCachedNodeConfig(manifestPath, {
      path: data.path || cache.configPath,
      content: data.content || content,
      exists: Boolean(data.exists),
      defaultLandingMode: nextState.defaultLandingMode
    });
    modeContentCache.configs = data.content || content;
    syncNodeDefaultLandingBtn();
  }
  renderNodeSettingsEditor(cache);
  if (isProjectSettingsMode()) {
    if (cache.settingsScope === "user") {
      applyUserSettingsFromCache(cache);
    }
    setProjectSettingsScopeStatusFromCache(manifestPath, cache);
    renderProjectSettingsScopeList();
    renderProjectSettingsPage(cache);
  }
  return data;
}

function getTopicSchemaManifestPath(nodePath = getResolvedNodePath(activePath)) {
  const normalized = String(nodePath || "").replace(/\\/g, "/");
  if (isAwnDatabaseManifestPath(normalized)) return normalized;
  if (isAwnDatabaseEditableRecordPath(normalized)) {
    const storeRel = resolveAwnDataStoreRelFromRecordPath(normalized);
    if (storeRel) return `awn-databases/${storeRel}/manifest.md`.replace(/\/+/g, "/");
  }
  if (activeContentMode === AWN_DATA_VIEW_MODE && awnDataViewStoreRel) {
    const storeRel = String(awnDataViewStoreRel).replace(/\\/g, "/").replace(/^\/+|\/+$/g, "");
    if (storeRel) return `awn-databases/${storeRel}/manifest.md`.replace(/\/+/g, "/");
  }
  if (isAgentRootIndexPath(normalized)) return normalized;
  if (isAreaNodePath(normalized)) return normalized;
  if (isTopicManifestPath(normalized)) return normalized;
  return resolveTopicManifestFromBundlePath(normalized);
}

function isTopicSchemaModeAvailable(nodePath = getResolvedNodePath(activePath)) {
  return Boolean(getTopicSchemaManifestPath(nodePath));
}

function resolveSchemaSlotKeyForContext() {
  if (activeContentMode === NODE_ENTRY_OVERVIEW_MODE) {
    return getDataStorageSlotKeyForEntryView(NODE_ENTRY_OVERVIEW_MODE);
  }
  return getDataStorageSlotForMode()?.key || null;
}

function resolveAwnSchemaTargetForType(typeName, slotKey = null) {
  const resolvedSlotKey = slotKey || resolveSchemaSlotKeyForContext();
  if (resolvedSlotKey && typeof TopicSchemaSlotSpecs !== "undefined") {
    const bySlot = TopicSchemaSlotSpecs.resolveTopicSchemaTargetIdForAwnType(resolvedSlotKey, typeName);
    if (bySlot) return bySlot;
  }
  const normalized =
    typeof TopicSchemaSlotSpecs !== "undefined"
      ? TopicSchemaSlotSpecs.normalizeAwnContentTypeName(typeName)
      : typeName;
  if (normalized === "awn.hub.topic.area" || typeName === "awn.area") return "area";
  if (normalized === "awn.hub.topic.ws" || typeName === "awn.workspace") return "workspace";
  if (normalized === "awn.content.category" || typeName === "awn.media.category") {
    return resolvedSlotKey === "media" ? "slot_media_category" : "slot_memory_category";
  }
  if (normalized === "awn.content.record" || typeName === "awn.record") {
    return resolvedSlotKey === "media" ? "slot_media_record" : "slot_memory";
  }
  if (normalized === "awn.annotation.sidecar" || typeName === "awn.sidecar") {
    if (resolvedSlotKey === "media") return "slot_media";
    if (resolvedSlotKey && typeof TopicSchemaSlotSpecs !== "undefined") {
      return TopicSchemaSlotSpecs.resolveTopicSchemaTargetId(resolvedSlotKey, { contentKind: "sidecar" });
    }
  }
  if (normalized === normalizeAwnTypeName("awn.content.category")) {
    return "category";
  }
  if (
    normalized === normalizeAwnTypeName("awn.content.record") ||
    normalized === normalizeAwnTypeName("awn.content.record-lite") ||
    normalized === normalizeAwnTypeName("awn.content.record-csv")
  ) {
    return "record";
  }
  if (normalized === normalizeAwnTypeName("awn.annotation.sidecar")) {
    return "sidecar";
  }
  const dbType = String(typeName || "");
  if (
    dbType.startsWith("awn.database.frame.") ||
    dbType.startsWith("awn.hub.database.frame.") ||
    /^awn\.hub\.database\.(single|group|collection|taxonomy-collection)$/.test(dbType)
  ) {
    return "frame";
  }
  return "topic";
}

function resolveAwnSchemaTargetForContext(nodePath = getResolvedNodePath(activePath)) {
  const resolvedPath =
    nodePath != null && nodePath !== ""
      ? String(nodePath).replace(/\\/g, "/")
      : getResolvedNodePath(activePath);
  if (isAwnDatabaseSchemaContext(resolvedPath)) {
    if (isAwnDatabaseManifestPath(resolvedPath)) return "frame";
    const declared = getPropsEntryValueByKey(propsFormEntries, "awn-type");
    return resolveAwnDatabaseSchemaTargetForElementType(declared, resolvedPath);
  }
  if (isWorkspaceSchemaContext(resolvedPath)) return "workspace";
  if (isAreaSchemaContext(resolvedPath)) return "area";

  const typeName = resolveAwnTypeForContext(nodePath);
  const slotKey = resolveSchemaSlotKeyForContext();
  if (slotKey && typeof TopicSchemaSlotSpecs !== "undefined") {
    const bySlot = TopicSchemaSlotSpecs.resolveTopicSchemaTargetIdForAwnType(slotKey, typeName);
    if (bySlot) return bySlot;
  }
  if (typeName === "awn.media.category") return "slot_media_category";
  if (typeName === "awn.record.category" || typeName === "awn.content.category") {
    return slotKey === "media" ? "slot_media_category" : "slot_memory_category";
  }
  if (slotKey) {
    if (typeName === "awn.sidecar" && slotKey === "media") return "slot_media";
    if (typeName === "awn.file" && slotKey === "repository") return "slot_repository";
    if (typeName === "awn.record" || typeName === "awn.content.record") {
      const slotTarget = resolveStorageSlotSchemaTargetId(slotKey);
      if (slotTarget) return slotTarget;
    }
  }
  return resolveAwnSchemaTargetForType(typeName, slotKey);
}

function getTopicSchemaCacheKey(manifestPath, contentPath = "") {
  const manifest = String(manifestPath || "").replace(/\\/g, "/");
  const content = String(contentPath || "").replace(/\\/g, "/").replace(/^\/+/, "");
  return content ? `${manifest}\0${content}` : manifest;
}

function isTopicSchemaStorageContentPath(relPath) {
  const normalized = String(relPath || "").replace(/\\/g, "/").replace(/^\/+/, "");
  if (!normalized) return false;
  if (/\/awn-storage\/[^/]+\/.+/i.test(normalized)) return true;
  if (activeContentMode === NODE_ENTRY_OVERVIEW_MODE && activeEntryOverviewContext?.relativePath) {
    return !isEntryOverviewMemoryTocRoot(activeEntryOverviewContext);
  }
  return false;
}

function getSchemaContentPathForContext(nodePath = activePath) {
  const ctx = getPropsContextPath(nodePath);
  const normalized = String(ctx || "").replace(/\\/g, "/").replace(/^\/+/, "");
  if (!normalized) return "";
  if (isTopicSchemaStorageContentPath(normalized)) return normalized;
  return "";
}

function resolveTopicSchemaCacheContentPath(contentPath = undefined) {
  if (contentPath !== undefined) {
    return String(contentPath || "").replace(/\\/g, "/").replace(/^\/+/, "");
  }
  if (activeContentMode === "topic-schema") {
    return "";
  }
  return getSchemaContentPathForContext();
}

function getTopicSchemaCache(manifestPath = getTopicSchemaManifestPath(), contentPath = undefined) {
  const schemaContentPath = resolveTopicSchemaCacheContentPath(contentPath);
  const cacheKey = getTopicSchemaCacheKey(manifestPath, schemaContentPath);
  if (!cacheKey) return null;
  return topicSchemaCacheByManifest.get(cacheKey) || null;
}

function hasTopicSchemaCacheForContext(manifestPath = getTopicSchemaManifestPath(), contentPath = undefined) {
  const normalizedManifest = String(manifestPath || "").replace(/\\/g, "/");
  if (!normalizedManifest) return false;
  return Boolean(getTopicSchemaCache(normalizedManifest, contentPath));
}

function resolveOverviewSchemaContentPath(context = activeEntryOverviewContext) {
  const relPath = String(context?.relPath || getPropsContextPath() || "")
    .replace(/\\/g, "/")
    .replace(/^\/+/, "");
  if (!relPath || isEntryOverviewMemoryTocRoot(context)) return "";
  if (isTopicSchemaStorageContentPath(relPath)) return relPath;
  return "";
}

function resolveActiveOverviewSchemaCache(context = activeEntryOverviewContext) {
  const manifestPath = getTopicSchemaManifestPath();
  if (!manifestPath) return null;
  const propsPath = getPropsContextPath();
  if (isAwnDatabaseSchemaContext(manifestPath) || isAwnDatabaseSchemaContext(propsPath)) {
    const contentPath = getSchemaContentPathForContext();
    const contentCache = getTopicSchemaCache(manifestPath, contentPath);
    if (contentCache) return contentCache;
    return getTopicSchemaCache(manifestPath, "");
  }
  if (activeContentMode === NODE_ENTRY_OVERVIEW_MODE && context?.relPath && manifestPath) {
    const contentPath = resolveOverviewSchemaContentPath(context);
    if (contentPath) {
      const contentCache = getTopicSchemaCache(manifestPath, contentPath);
      if (contentCache) return contentCache;
    }
    const topicCache = getTopicSchemaCache(manifestPath, "");
    if (topicCache) return topicCache;
  }
  const contentPath = getSchemaContentPathForContext();
  if (contentPath) {
    const contentCache = getTopicSchemaCache(manifestPath, contentPath);
    if (contentCache) return contentCache;
  }
  return getTopicSchemaCache(manifestPath, "");
}

function resolveActivePropsSchemaCache(context = activeEntryOverviewContext) {
  const manifestPath = getTopicSchemaManifestPath();
  if (!manifestPath) return null;
  const propsPath = getPropsContextPath();
  if (isAwnDatabaseSchemaContext(manifestPath) || isAwnDatabaseSchemaContext(propsPath)) {
    const contentPath = getSchemaContentPathForContext();
    return getTopicSchemaCache(manifestPath, contentPath);
  }
  if (activeContentMode === NODE_ENTRY_OVERVIEW_MODE && context?.relPath) {
    const contentPath = resolveOverviewSchemaContentPath(context);
    if (contentPath) {
      const contentCache = getTopicSchemaCache(manifestPath, contentPath);
      if (contentCache) return contentCache;
    }
  }
  const contentPath = getSchemaContentPathForContext();
  if (contentPath) {
    const contentCache = getTopicSchemaCache(manifestPath, contentPath);
    if (contentCache) return contentCache;
  }
  return getTopicSchemaCache(manifestPath, "");
}

function resolveOverviewSchemaTargetForContext(context = activeEntryOverviewContext) {
  if (activeContentMode === NODE_ENTRY_OVERVIEW_MODE && context) {
    const entryKind = normalizeAwnTypeName(
      context.entryKind === "awn.media.asset"
        ? "awn.annotation.sidecar"
        : context.entryKind || "awn.content.record"
    );
    const slotKey = getDataStorageSlotKeyForEntryView(NODE_ENTRY_OVERVIEW_MODE);
    return resolveAwnSchemaTargetForType(entryKind, slotKey);
  }
  return resolveAwnSchemaTargetForContext();
}

function getTopicSchemaSavePayload() {
  const cache = getTopicSchemaCache();
  if (!cache) return null;
  const manifestPath = getTopicSchemaManifestPath();
  syncActiveTopicSchemaTargetFromDom();
  syncTopicSchemaFieldsFromDom(cache, topicSchemaActiveTarget);
  return compactTopicSchemaForContext(cache.awnSchema, manifestPath);
}

async function loadWorkspaceSchemaForAgentRoot(nodePath, options = {}) {
  const manifestPath = String(nodePath || "").replace(/\\/g, "/");
  const cacheKey = getTopicSchemaCacheKey(manifestPath, "");

  if (!options.force) {
    const cached = topicSchemaCacheByManifest.get(cacheKey);
    if (cached) return cached;
  }

  const inflight = topicSchemaLoadPromises.get(cacheKey);
  if (inflight) return inflight;

  const promise = (async () => {
    const response = await fetch(buildApiUrl("/api/file/workspace-schema", { path: manifestPath, mode: "layers" }));
    if (!response.ok) throw new Error(`Request failed with ${response.status}`);
    const data = await response.json();
    if (!awnTypesCache?.types) {
      await loadAwnTypes(activeWorkspaceId);
    }
    const fieldRegistry = awnTypesCache?.fieldRegistry || {};
    const parsedLayers = parseTopicSchemaLayersFromApi(data);
    const workspaceAwnSchema = sanitizeTopicSchemaFieldKeys(
      stripAwnSchemaToContextLevel(
        parsedLayers.workspaceAwnSchema ||
          normalizeTopicSchemaState(data.workspaceAwnSchema || data.awnSchema),
        "workspace"
      )
    );
    const payload = {
      manifestPath,
      contentPath: "",
      configPath: data.schemaPath || SCHEMA_MOD_FILE,
      configExists: Boolean(data.schemaExists),
      schemaPath: data.schemaPath || SCHEMA_MOD_FILE,
      schemaExists: Boolean(data.schemaExists),
      isWorkspaceSchema: true,
      awnSchema: workspaceAwnSchema,
      workspaceAwnSchema,
      topicAwnSchema: emptyTopicSchemaState(),
      areaAwnSchema: emptyTopicSchemaState(),
      effectiveAwnSchema: workspaceAwnSchema,
      sectionAwnSchema: null,
      sectionChain: [],
      baseTypes: {},
      merged: {},
      fieldRegistry
    };
    enrichTopicSchemaCacheFromTypes(payload);
    topicSchemaCacheByManifest.set(cacheKey, payload);
    return payload;
  })();

  topicSchemaLoadPromises.set(cacheKey, promise);
  try {
    return await promise;
  } finally {
    if (topicSchemaLoadPromises.get(cacheKey) === promise) {
      topicSchemaLoadPromises.delete(cacheKey);
    }
  }
}

async function loadTopicSchemaForManifest(nodePath, options = {}) {
  const normalized = String(nodePath || "").replace(/\\/g, "/");
  if (isWorkspaceSchemaContext(normalized)) {
    return loadWorkspaceSchemaForAgentRoot(normalized, options);
  }

  const preliminaryContentPath =
    options.contentPath !== undefined
      ? String(options.contentPath || "").replace(/\\/g, "/").replace(/^\/+/, "")
      : options.topicOnly === true || activeContentMode === "topic-schema"
        ? ""
        : getSchemaContentPathForContext(nodePath);
  const preliminaryManifest =
    (isTopicManifestPath(normalized) || isNodeManifestPath(normalized) ? normalized : null) ||
    getTopicSchemaManifestPath(nodePath) ||
    resolveTopicManifestFromBundlePath(normalized);
  if (
    preliminaryManifest &&
    (isAwnDatabaseSchemaContext(preliminaryManifest) ||
      (preliminaryContentPath && isAwnDatabaseEditableRecordPath(preliminaryContentPath)))
  ) {
    return loadAwnDatabaseTopicSchemaForManifest(preliminaryManifest, {
      contentPath: preliminaryContentPath,
      force: options.force
    });
  }

  const manifestPath =
    (isTopicManifestPath(normalized) || isNodeManifestPath(normalized) ? normalized : null) ||
    getTopicSchemaManifestPath(nodePath) ||
    resolveTopicManifestFromBundlePath(normalized);
  if (!manifestPath) return null;

  const contentPath = (() => {
    if (options.contentPath !== undefined) {
      return String(options.contentPath || "").replace(/\\/g, "/").replace(/^\/+/, "");
    }
    if (options.topicOnly === true || activeContentMode === "topic-schema") return "";
    return getSchemaContentPathForContext(nodePath);
  })();
  const cacheKey = getTopicSchemaCacheKey(manifestPath, contentPath);

  if (!options.force) {
    const cached = topicSchemaCacheByManifest.get(cacheKey);
    if (cached) return cached;
  }

  const inflight = topicSchemaLoadPromises.get(cacheKey);
  if (inflight) return inflight;

  const promise = (async () => {
    const query = { path: manifestPath, mode: "layers" };
    if (contentPath) query.contentPath = contentPath;
    const response = await fetch(buildApiUrl("/api/file/topic-schema", query));
    if (!response.ok) throw new Error(`Request failed with ${response.status}`);
    const data = await response.json();
    if (!awnTypesCache?.types) {
      await loadAwnTypes(activeWorkspaceId);
    }
    const fieldRegistry = awnTypesCache?.fieldRegistry || {};
    const parsedLayers = parseTopicSchemaLayersFromApi(data);
    const topicAwnSchema = isAreaSchemaContext(manifestPath)
      ? emptyTopicSchemaState()
      : parsedLayers.topicAwnSchema;
    const areaAwnSchema = isAreaSchemaContext(manifestPath)
      ? parsedLayers.areaAwnSchema || emptyTopicSchemaState()
      : parsedLayers.areaAwnSchema;
    const contextSchema = resolveContextSchemaFromParsedLayers(parsedLayers, {
      manifestPath,
      contentPath: contentPath || ""
    });
    const editableSchema = sanitizeTopicSchemaFieldKeys(
      stripAwnSchemaToContextLevel(contextSchema, getSchemaContextLevel(manifestPath))
    );
    const effectiveAwnSchema = contextSchema;
    const payload = {
      manifestPath,
      contentPath: contentPath || "",
      configPath: data.schemaPath || data.configPath || "",
      configExists: Boolean(data.schemaExists ?? data.configExists),
      awnSchema: editableSchema,
      effectiveAwnSchema,
      topicAwnSchema,
      areaAwnSchema,
      workspaceAwnSchema: parsedLayers.workspaceAwnSchema,
      sectionAwnSchema: parsedLayers.sectionAwnSchema,
      sectionChain: parsedLayers.sectionChain,
      baseTypes: {},
      merged: {},
      fieldRegistry
    };
    enrichTopicSchemaCacheFromTypes(payload);
    topicSchemaCacheByManifest.set(cacheKey, payload);
    return payload;
  })();

  topicSchemaLoadPromises.set(cacheKey, promise);
  try {
    return await promise;
  } finally {
    if (topicSchemaLoadPromises.get(cacheKey) === promise) {
      topicSchemaLoadPromises.delete(cacheKey);
    }
  }
}

function getTopicSchemaRegistryEntries(cache = getTopicSchemaCache()) {
  const registry = cache?.fieldRegistry || awnTypesCache?.fieldRegistry || {};
  return Object.entries(registry)
    .filter(([id]) => id.startsWith("awn.field."))
    .map(([id, def]) => ({
      id,
      name: def?.name || def?.label || id,
      sort: Number(def?.sort) || 0,
      group: def?.group || "misc",
      widget: def?.widget || "",
      description: def?.description || ""
    }));
}

function compareFieldRegistryEntries(a, b) {
  const sortA = Number(a?.sort) || 0;
  const sortB = Number(b?.sort) || 0;
  if (sortA !== sortB) return sortA - sortB;
  const canonicalA = normalizeCanonicalFieldTypeId(a?.id || "");
  const canonicalB = normalizeCanonicalFieldTypeId(b?.id || "");
  const depthA = canonicalA.split(".").length;
  const depthB = canonicalB.split(".").length;
  if (depthA !== depthB) return depthA - depthB;
  return canonicalA.localeCompare(canonicalB, "ru");
}

