function resolveFieldRegistryEntryId(typeId, byId) {
  const candidates = [];
  const push = (value) => {
    const id = String(value || "").trim();
    if (!id || candidates.includes(id)) return;
    candidates.push(id);
  };

  push(resolveFieldTypeId(typeId));
  push(normalizeCanonicalFieldTypeId(typeId));
  for (const id of [...candidates]) {
    if (id.startsWith("awn.") && !id.startsWith("awn.field.")) {
      push(`awn.field.${id.slice("awn.".length)}`);
    }
    if (id.startsWith("awn.field.")) {
      push(`awn.${id.slice("awn.field.".length)}`);
    }
  }

  for (const id of candidates) {
    if (byId.has(id)) return id;
  }
  return candidates[0] || resolveFieldTypeId(typeId);
}

function getFieldTypeSelectGroups(registryEntries = []) {
  const byId = new Map(registryEntries.map((entry) => [entry.id, entry]));
  const used = new Set();
  const apiGroups = awnTypesCache?.fieldGroups;
  if (Array.isArray(apiGroups) && apiGroups.length) {
    const groups = [];
    for (const group of apiGroups) {
      const entries = [];
      for (const field of group.fields || []) {
        const resolved = resolveFieldRegistryEntryId(field.id, byId);
        if (!byId.has(resolved) || used.has(resolved)) continue;
        entries.push(byId.get(resolved));
        used.add(resolved);
      }
      if (entries.length) {
        entries.sort(compareFieldRegistryEntries);
        const label = group.title || group.id;
        groups.push({ label, entries });
      }
    }
    const rest = registryEntries.filter((entry) => !used.has(entry.id));
    rest.sort(compareFieldRegistryEntries);
    if (rest.length) groups.push({ label: "Другие", entries: rest });
    return groups;
  }

  const groups = [];

  for (const spec of FIELD_TYPE_SELECT_GROUPS) {
    const entries = [];
    for (const typeId of spec.types) {
      const resolved = resolveFieldRegistryEntryId(typeId, byId);
      if (!byId.has(resolved) || used.has(resolved)) continue;
      entries.push(byId.get(resolved));
      used.add(resolved);
    }
    if (entries.length) {
      groups.push({ label: spec.label, entries });
    }
  }

  const rest = registryEntries.filter((entry) => !used.has(entry.id));
  rest.sort(compareFieldRegistryEntries);
  if (rest.length) groups.push({ label: "Другие", entries: rest });

  return groups;
}

function populateFieldTypeSelect(select, registryEntries, selectedTypeId = "awn.field.string") {
  if (!select) return;
  select.replaceChildren();
  const byId = new Map(registryEntries.map((entry) => [entry.id, entry]));

  for (const group of getFieldTypeSelectGroups(registryEntries)) {
    const optgroup = document.createElement("optgroup");
    optgroup.label = group.label;
    for (const entry of group.entries) {
      const option = document.createElement("option");
      option.value = entry.id;
      option.textContent = getFieldTypeOptionLabel(entry.id, entry.name);
      optgroup.appendChild(option);
    }
    select.appendChild(optgroup);
  }

  const resolved = resolveFieldRegistryEntryId(selectedTypeId || "awn.field.string", byId);
  select.value = resolved;
  if (select.value !== resolved && resolved) {
    const legacy = document.createElement("option");
    legacy.value = resolved;
    legacy.textContent = getFieldTypeOptionLabel(resolved, byId.get(resolved)?.name || resolved);
    legacy.selected = true;
    select.prepend(legacy);
  }
}

function getTopicSchemaCustomFieldKeys(target = topicSchemaActiveTarget, cache = getTopicSchemaCache()) {
  if (!cache) return [];
  let keys = Object.keys(cache.awnSchema?.[target]?.fields || {});
  keys = keys.filter((key) => isTopicSchemaCustomFieldKey(key, target));
  if (target !== "settings") return keys;
  return keys.filter((key) => !ExternalFileMask.isBuiltinSettingsSchemaKey(key));
}

function topicSchemaTargetHasCustomFields(targetId, cache = getTopicSchemaCache()) {
  return getTopicSchemaCustomFieldKeys(targetId, cache).length > 0;
}

const TOPIC_SCHEMA_FIELD_PLACEMENT = "editor-body";

function getTopicSchemaLayoutSettingKeys() {
  return ["group", "sort"];
}

function normalizeTopicSchemaCustomFieldDef(fieldDef) {
  if (!fieldDef || typeof fieldDef !== "object") return fieldDef;
  return { ...fieldDef, placement: TOPIC_SCHEMA_FIELD_PLACEMENT };
}

function getTopicSchemaPendingGroup(target = topicSchemaActiveTarget) {
  return String(topicSchemaPendingGroupByTarget[target] || "").trim();
}

function setTopicSchemaPendingGroup(value, target = topicSchemaActiveTarget) {
  const trimmed = String(value || "").trim();
  if (trimmed) topicSchemaPendingGroupByTarget[target] = trimmed;
  else delete topicSchemaPendingGroupByTarget[target];
}

function resolveTopicSchemaTargetContentKind(targetId) {
  const target = String(targetId || "").trim();
  if (!target) return "";
  if (target === "record-csv") return "record-csv";
  if (typeof TopicSchemaSlotSpecs !== "undefined") {
    const spec = TopicSchemaSlotSpecs.findTopicSchemaTargetSpecById(target);
    if (spec?.contentKind) return spec.contentKind;
  }
  return "";
}

function schemaEditorTargetSupportsFieldGroups(targetId) {
  const contentKind = resolveTopicSchemaTargetContentKind(targetId);
  if (
    typeof TopicSchemaSlotSpecs !== "undefined" &&
    TopicSchemaSlotSpecs.topicSchemaContentKindSupportsFieldGroups
  ) {
    return TopicSchemaSlotSpecs.topicSchemaContentKindSupportsFieldGroups(contentKind);
  }
  return contentKind !== "record-csv";
}

function resolveSchemaEditorContextTarget(root = topicSchemaPanelNode) {
  const storeTarget = String(root?._awnDataStoreSchemaCache?.activeTarget || "").trim();
  if (storeTarget) return storeTarget;
  if (root?.classList?.contains("node-entry-overview-section-schema")) {
    return String(root._sectionSchemaCache?.activeTarget || "").trim();
  }
  return normalizeTopicSchemaActiveTarget(topicSchemaActiveTarget);
}

function collectSchemaEditorGroupNames(fields = {}, target = topicSchemaActiveTarget) {
  const names = new Set();
  const keys = Object.keys(fields || {});
  for (const groupId of getSchemaEditorGroupOrder(fields, keys)) {
    if (groupId && groupId !== "content") names.add(groupId);
  }
  const pending = getTopicSchemaPendingGroup(target);
  if (pending) names.add(pending);
  return [...names].sort((a, b) => a.localeCompare(b, "ru"));
}

function sortSchemaEditorFieldKeys(keys, fields = {}) {
  return [...keys].sort((a, b) => comparePropsFieldSchemaOrder(a, b, fields));
}

function resolveSchemaEditorGroupLabel(groupId) {
  const id = String(groupId || "").trim();
  if (!id || id === "content") return "";
  const known = getActivePropsFieldGroups().find((group) => group.id === id);
  if (known?.name && known.name !== id) return known.name;
  return id;
}

function getSchemaEditorGroupOrder(fields = {}, keys = []) {
  const sortedKeys = sortSchemaEditorFieldKeys(keys, fields);
  const groups = [];
  const seen = new Set();
  for (const key of sortedKeys) {
    const groupId = resolvePropsFieldGroupId(key, fields[key]);
    if (seen.has(groupId)) continue;
    seen.add(groupId);
    groups.push(groupId);
  }
  return groups;
}

function applySchemaEditorGroupOrder(fields, keys, groups) {
  let baseSort = 10;
  for (const groupId of groups) {
    const groupKeys = sortSchemaEditorFieldKeys(keys, fields).filter(
      (key) => resolvePropsFieldGroupId(key, fields[key]) === groupId
    );
    groupKeys.forEach((key, index) => {
      if (!fields[key]) return;
      fields[key].sort = baseSort + index;
    });
    baseSort += 100;
  }
}

function moveSchemaEditorGroup(fields, keys, groupId, direction) {
  if (!fields) return false;
  const groups = getSchemaEditorGroupOrder(fields, keys);
  const index = groups.indexOf(groupId);
  if (index < 0) return false;
  const swapIndex = direction === "up" ? index - 1 : index + 1;
  if (swapIndex < 0 || swapIndex >= groups.length) return false;
  [groups[index], groups[swapIndex]] = [groups[swapIndex], groups[index]];
  applySchemaEditorGroupOrder(fields, keys, groups);
  return true;
}

function renameSchemaEditorGroup(fields, keys, groupId, nextName, target = "") {
  const trimmed = String(nextName || "").trim();
  if (!trimmed || trimmed === groupId) return false;
  for (const key of keys) {
    const def = fields[key];
    if (!def) continue;
    if (resolvePropsFieldGroupId(key, def) === groupId) {
      def.group = trimmed;
    }
  }
  if (target && getTopicSchemaPendingGroup(target) === groupId) {
    setTopicSchemaPendingGroup(trimmed, target);
  }
  return true;
}

function createTopicSchemaGroupHeader(groupId, { groupIndex = 0, groupCount = 1 } = {}) {
  const normalized = String(groupId || "content").trim() || "content";
  const label = resolveSchemaEditorGroupLabel(normalized);
  if (!label) return null;

  const header = document.createElement("div");
  header.className = "topic-schema-group-header";
  header.dataset.group = normalized;

  const actions = document.createElement("div");
  actions.className = "topic-schema-group-header-actions";

  const upBtn = document.createElement("button");
  upBtn.type = "button";
  upBtn.className = "topic-schema-group-sort-btn";
  upBtn.dataset.schemaAction = "group-move-up";
  upBtn.dataset.schemaGroup = normalized;
  upBtn.textContent = "↑";
  upBtn.title = "Переместить раздел выше";
  upBtn.disabled = groupIndex <= 0;

  const downBtn = document.createElement("button");
  downBtn.type = "button";
  downBtn.className = "topic-schema-group-sort-btn";
  downBtn.dataset.schemaAction = "group-move-down";
  downBtn.dataset.schemaGroup = normalized;
  downBtn.textContent = "↓";
  downBtn.title = "Переместить раздел ниже";
  downBtn.disabled = groupIndex >= groupCount - 1;

  const renameBtn = document.createElement("button");
  renameBtn.type = "button";
  renameBtn.className = "topic-schema-group-rename-btn";
  renameBtn.dataset.schemaAction = "group-rename";
  renameBtn.dataset.schemaGroup = normalized;
  renameBtn.textContent = "✎";
  renameBtn.title = "Переименовать раздел (все поля в группе)";

  actions.append(upBtn, downBtn, renameBtn);

  const caption = document.createElement("span");
  caption.className = "topic-schema-group-header-label";
  caption.textContent = label;
  caption.title = `Раздел «${label}» — свойство group у полей`;

  header.append(actions, caption);
  return header;
}

function appendSchemaEditorGroupHeader(container, groupId, state, meta = {}) {
  const normalized = String(groupId || "content").trim() || "content";
  if (state.lastGroup === normalized) return;
  state.lastGroup = normalized;
  const header = createTopicSchemaGroupHeader(normalized, meta);
  if (header) container.appendChild(header);
}

function syncTopicSchemaPendingGroupHint(root = topicSchemaPanelNode) {
  root?.querySelectorAll(".topic-schema-pending-group-hint-wrap").forEach((node) => node.remove());
  const footer =
    root?.querySelector(".topic-schema-footer") ||
    document.querySelector("#topic-schema-panel .topic-schema-footer");
  if (!footer) return;

  const target = resolveSchemaEditorContextTarget(root);
  const supportsFieldGroups = schemaEditorTargetSupportsFieldGroups(target);
  const pendingGroup = supportsFieldGroups ? getTopicSchemaPendingGroup(target) : "";
  const sectionBtn = footer.querySelector(".topic-schema-add-section-btn");
  if (sectionBtn) {
    sectionBtn.disabled = !supportsFieldGroups;
    sectionBtn.classList.toggle("is-disabled", !supportsFieldGroups);
    sectionBtn.title = supportsFieldGroups
      ? ""
      : "CSV-колонки без разделов — только плоский список полей";
  }
  if (!supportsFieldGroups) {
    if (getTopicSchemaPendingGroup(target)) resetTopicSchemaPendingGroup(target);
    closeTopicSchemaSectionEditor(root);
    return;
  }
  sectionBtn?.classList.toggle("is-active", Boolean(pendingGroup));
  if (!pendingGroup) return;

  const wrap = document.createElement("span");
  wrap.className = "topic-schema-pending-group-hint-wrap";
  if (target) wrap.dataset.schemaTarget = target;

  const hint = document.createElement("span");
  hint.className = "topic-schema-pending-group-hint is-active";
  hint.textContent = `Раздел «${pendingGroup}» — новые поля попадут сюда`;

  const resetBtn = document.createElement("button");
  resetBtn.type = "button";
  resetBtn.className = "topic-schema-pending-group-reset";
  resetBtn.title = "Сбросить раздел";
  resetBtn.setAttribute("aria-label", "Сбросить раздел");
  resetBtn.textContent = "×";
  wrap.append(hint, resetBtn);

  footer.insertBefore(wrap, footer.firstChild);
}

function syncAllTopicSchemaPendingGroupHints() {
  const roots = new Set();
  if (topicSchemaPanelNode) roots.add(topicSchemaPanelNode);
  document.querySelectorAll(".node-entry-overview-section-schema").forEach((node) => roots.add(node));
  for (const root of roots) syncTopicSchemaPendingGroupHint(root);
}

function resolveTopicSchemaPanelRootForTarget(target, preferredRoot = null) {
  if (preferredRoot) return preferredRoot;
  if (String(target || "").startsWith("slot_")) {
    for (const panel of document.querySelectorAll(".node-entry-overview-section-schema")) {
      if (panel._sectionSchemaCache?.activeTarget === target) return panel;
    }
    return document.querySelector(".node-entry-overview-section-schema");
  }
  return topicSchemaPanelNode;
}

function closeTopicSchemaSectionEditor(root) {
  root?.querySelector(".topic-schema-pending-group-editor")?.remove();
}

function applyTopicSchemaPendingGroup(target, rawValue, root = null) {
  const trimmed = String(rawValue || "").trim();
  setTopicSchemaPendingGroup(trimmed, target);
  syncAllTopicSchemaPendingGroupHints();
  closeTopicSchemaSectionEditor(resolveTopicSchemaPanelRootForTarget(target, root));
  if (trimmed) {
    showToast(`Раздел «${trimmed}» активен — нажмите «+ Поле»`, "info");
  }
}

function beginTopicSchemaSectionEdit(root, target) {
  if (!root || !target) return;
  if (!schemaEditorTargetSupportsFieldGroups(target)) return;
  const footer = root.querySelector(".topic-schema-footer");
  if (!footer) return;

  closeTopicSchemaSectionEditor(root);

  const editor = document.createElement("div");
  editor.className = "topic-schema-pending-group-editor";
  editor.dataset.schemaTarget = target;

  const input = document.createElement("input");
  input.type = "text";
  input.className = "topic-schema-inline-input topic-schema-pending-group-input";
  input.placeholder = "Название раздела для новых полей";
  input.value = getTopicSchemaPendingGroup(target);
  input.spellcheck = false;

  const applyBtn = document.createElement("button");
  applyBtn.type = "button";
  applyBtn.className = "topic-schema-pending-group-apply";
  applyBtn.textContent = "OK";

  const clearBtn = document.createElement("button");
  clearBtn.type = "button";
  clearBtn.className = "topic-schema-pending-group-clear";
  clearBtn.textContent = "Сброс";
  clearBtn.title = "Новые поля без раздела";

  const cancelBtn = document.createElement("button");
  cancelBtn.type = "button";
  cancelBtn.className = "topic-schema-pending-group-cancel";
  cancelBtn.textContent = "×";
  cancelBtn.title = "Отмена";

  const commit = () => applyTopicSchemaPendingGroup(target, input.value, root);
  const clear = () => applyTopicSchemaPendingGroup(target, "", root);

  applyBtn.addEventListener("click", (event) => {
    event.preventDefault();
    event.stopPropagation();
    commit();
  });
  clearBtn.addEventListener("click", (event) => {
    event.preventDefault();
    event.stopPropagation();
    clear();
  });
  cancelBtn.addEventListener("click", (event) => {
    event.preventDefault();
    event.stopPropagation();
    closeTopicSchemaSectionEditor(root);
  });
  input.addEventListener("keydown", (event) => {
    if (event.key === "Enter") {
      event.preventDefault();
      commit();
    }
    if (event.key === "Escape") {
      event.preventDefault();
      closeTopicSchemaSectionEditor(root);
    }
  });

  editor.append(input, applyBtn, clearBtn, cancelBtn);
  const sectionBtn = footer.querySelector(".topic-schema-add-section-btn");
  footer.insertBefore(editor, sectionBtn || footer.firstChild);
  input.focus();
  input.select();
}

function resetTopicSchemaPendingGroup(target = topicSchemaActiveTarget) {
  if (!getTopicSchemaPendingGroup(target)) return;
  setTopicSchemaPendingGroup("", target);
  syncAllTopicSchemaPendingGroupHints();
}

function addTopicSchemaSection(target = topicSchemaActiveTarget, root = null) {
  if (!schemaEditorTargetSupportsFieldGroups(target)) return;
  beginTopicSchemaSectionEdit(resolveTopicSchemaPanelRootForTarget(target, root), target);
}

function moveTopicSchemaEditorGroup(target, groupId, direction) {
  const cache = getTopicSchemaCache();
  const fields = cache?.awnSchema?.[target]?.fields;
  if (!fields) return;
  const keys = getTopicSchemaCustomFieldKeys(target, cache);
  if (!moveSchemaEditorGroup(fields, keys, groupId, direction)) return;
  renderTopicSchemaEditor();
  syncSaveButtonLamp();
}

function renameTopicSchemaEditorGroup(target, groupId, fieldsRoot = topicSchemaFieldsNode) {
  beginTopicSchemaGroupRename(groupId, target, fieldsRoot);
}

function closeTopicSchemaGroupRenameEditors(root) {
  if (!root) return;
  root.querySelectorAll(".topic-schema-group-rename-editor").forEach((node) => node.remove());
  root.querySelectorAll(".topic-schema-group-header-label.is-hidden-during-rename").forEach((node) => {
    node.classList.remove("is-hidden-during-rename");
  });
}

function beginTopicSchemaGroupRename(groupId, target, fieldsRoot, { onCommit } = {}) {
  if (!groupId || !target || !fieldsRoot) return;
  closeTopicSchemaGroupRenameEditors(fieldsRoot);

  const header = fieldsRoot.querySelector(
    `.topic-schema-group-header[data-group="${CSS.escape(groupId)}"]`
  );
  if (!header) return;

  const labelNode = header.querySelector(".topic-schema-group-header-label");
  labelNode?.classList.add("is-hidden-during-rename");

  const editor = document.createElement("div");
  editor.className = "topic-schema-group-rename-editor";

  const input = document.createElement("input");
  input.type = "text";
  input.className = "topic-schema-inline-input topic-schema-group-rename-input";
  input.value = groupId;
  input.placeholder = "Название раздела";
  input.spellcheck = false;

  const applyBtn = document.createElement("button");
  applyBtn.type = "button";
  applyBtn.className = "topic-schema-group-rename-apply";
  applyBtn.textContent = "OK";

  const cancelBtn = document.createElement("button");
  cancelBtn.type = "button";
  cancelBtn.className = "topic-schema-group-rename-cancel";
  cancelBtn.textContent = "×";
  cancelBtn.title = "Отмена";

  const finish = () => closeTopicSchemaGroupRenameEditors(fieldsRoot);

  const commit = () => {
    const trimmed = String(input.value || "").trim();
    finish();
    if (!trimmed || trimmed === groupId) return;

    if (typeof onCommit === "function") {
      onCommit(trimmed);
      return;
    }

    const cache = getTopicSchemaCache();
    const fields = cache?.awnSchema?.[target]?.fields;
    if (!fields) return;
    const keys = getTopicSchemaCustomFieldKeys(target, cache);
    if (!renameSchemaEditorGroup(fields, keys, groupId, trimmed, target)) return;
    renderTopicSchemaEditor();
    syncSaveButtonLamp();
    showToast(`Раздел переименован в «${trimmed}»`, "success");
  };

  applyBtn.addEventListener("click", (event) => {
    event.preventDefault();
    event.stopPropagation();
    commit();
  });
  cancelBtn.addEventListener("click", (event) => {
    event.preventDefault();
    event.stopPropagation();
    finish();
  });
  input.addEventListener("keydown", (event) => {
    if (event.key === "Enter") {
      event.preventDefault();
      commit();
    }
    if (event.key === "Escape") {
      event.preventDefault();
      finish();
    }
  });

  editor.append(input, applyBtn, cancelBtn);
  header.appendChild(editor);
  input.focus();
  input.select();
}

function buildTopicSchemaFieldDefaults(index = 1, target = topicSchemaActiveTarget) {
  const defaults = {
    type: "awn.field.string",
    name: "",
    placement: TOPIC_SCHEMA_FIELD_PLACEMENT,
    sort: index * 10
  };
  const pending = schemaEditorTargetSupportsFieldGroups(target) ? getTopicSchemaPendingGroup(target) : "";
  if (pending) defaults.group = pending;
  return defaults;
}

function topicSchemaFieldHasAdvancedSettings(fieldDef) {
  if (!fieldDef || typeof fieldDef !== "object") return false;
  const typeId = resolveFieldTypeId(fieldDef.type || "awn.field.string");
  const allowedSettings = new Set([
    "type",
    "title",
    "name",
    ...getFieldTypeSettingsKeys(typeId),
    ...getTopicSchemaLayoutSettingKeys()
  ]);
  for (const [propKey, value] of Object.entries(fieldDef)) {
    if (!allowedSettings.has(propKey)) continue;
    if (shouldPersistFieldDefSetting(propKey, value, fieldDef)) return true;
  }
  return false;
}

function topicSchemaSlotHasCustomFields(slot, cache = getTopicSchemaCache()) {
  return (slot?.tabs || []).some((tab) => topicSchemaTargetHasCustomFields(tab.id, cache));
}

function topicSchemaTabGroupHasCustomFields(group, cache = getTopicSchemaCache()) {
  if (group?.coreTabs?.length) {
    return group.coreTabs.some((tab) => topicSchemaTargetHasCustomFields(tab.id, cache));
  }
  if (group?.slots?.length) {
    return group.slots.some((slot) => topicSchemaSlotHasCustomFields(slot, cache));
  }
  return false;
}

function isTopicSchemaCustomFieldKey(key, target = "") {
  const normalized = normalizePropsKey(key);
  if (!normalized || isAwnFieldKey(normalized)) return false;
  if (target === "settings" && ExternalFileMask.isBuiltinSettingsSchemaKey(normalized)) return false;
  return true;
}

function normalizeTopicSchemaCustomFieldKey(key) {
  return String(key || "").trim();
}

function sanitizeTopicSchemaTargetFieldKeys(fields, target = "") {
  const next = {};
  for (const [key, def] of Object.entries(fields || {})) {
    const normalizedKey = normalizeTopicSchemaCustomFieldKey(key);
    if (!isTopicSchemaCustomFieldKey(normalizedKey, target)) continue;
    if (!Object.prototype.hasOwnProperty.call(next, normalizedKey)) next[normalizedKey] = def;
  }
  return next;
}

function sanitizeTopicSchemaFieldKeys(awnSchema) {
  const normalized = normalizeTopicSchemaState(awnSchema);
  for (const { id } of getTopicSchemaTargetSpecs()) {
    if (normalized[id]?.fields) {
      normalized[id].fields = sanitizeTopicSchemaTargetFieldKeys(normalized[id].fields, id);
    }
  }
  if (normalized.sidecar?.fields) {
    normalized.sidecar.fields = sanitizeTopicSchemaTargetFieldKeys(normalized.sidecar.fields, "slot_media");
  }
  return normalized;
}

function defaultTopicSchemaFieldKeyForTarget(_target, index) {
  return `field-${index}`;
}

function getTopicSchemaFieldKeyHint(_target) {
  return { placeholder: "ключ", title: "Ключ поля" };
}

function normalizeTopicSchemaActiveTarget(target = topicSchemaActiveTarget) {
  const resolved = String(target || "").trim();
  if (isWorkspaceSchemaContext()) {
    return resolved === "settings" ? "settings" : "workspace";
  }
  if (isAreaSchemaContext()) {
    return resolved === "settings" ? "settings" : "area";
  }
  if (resolved === "workspace" || resolved === "area") return "topic";
  return resolved || "topic";
}

function resolveActiveTopicSchemaTarget() {
  const activeTab = topicSchemaTargetTabsNode?.querySelector(
    ".topic-schema-target-tab.is-active[data-target]"
  );
  const fromDom = String(activeTab?.dataset.target || "").trim();
  return normalizeTopicSchemaActiveTarget(fromDom || topicSchemaActiveTarget);
}

function syncActiveTopicSchemaTargetFromDom() {
  const resolved = resolveActiveTopicSchemaTarget();
  if (resolved) topicSchemaActiveTarget = resolved;
  return topicSchemaActiveTarget;
}

function ensureTopicSchemaTargetFieldsBucket(cache, target) {
  if (!cache?.awnSchema) return null;
  const existing = cache.awnSchema[target];
  if (!existing || typeof existing !== "object") {
    cache.awnSchema[target] = { fields: {} };
    return cache.awnSchema[target].fields;
  }
  if (!existing.fields || typeof existing.fields !== "object") {
    existing.fields = {};
    return existing.fields;
  }
  if (existing.fields === cache.awnSchema.workspace?.fields && target !== "workspace") {
    existing.fields = { ...existing.fields };
  }
  if (existing.fields === cache.awnSchema.topic?.fields && target !== "topic") {
    existing.fields = { ...existing.fields };
  }
  if (existing.fields === cache.awnSchema.area?.fields && target !== "area") {
    existing.fields = { ...existing.fields };
  }
  if (existing.fields === cache.awnSchema.settings?.fields && target !== "settings") {
    existing.fields = { ...existing.fields };
  }
  return existing.fields;
}

function compactTopicSchemaForContext(awnSchema, manifestPath = getTopicSchemaManifestPath()) {
  const level = getSchemaContextLevel(manifestPath);
  return sanitizeTopicSchemaFieldKeys(
    stripAwnSchemaToContextLevel(normalizeTopicSchemaState(awnSchema), level)
  );
}

function getTopicSchemaTargetSpecsForEditor() {
  if (isWorkspaceSchemaContext()) {
    return getTopicSchemaTargetSpecs().filter((spec) => spec.id === "workspace" || spec.id === "settings");
  }
  if (isAreaSchemaContext()) {
    return getTopicSchemaTargetSpecs().filter((spec) => spec.id === "area" || spec.id === "settings");
  }
  return getTopicSchemaTargetSpecs();
}

function addTopicSchemaField(target = syncActiveTopicSchemaTargetFromDom()) {
  const cache = getTopicSchemaCache();
  if (!cache) return;
  const resolvedTarget = String(target || "").trim();
  if (!resolvedTarget) return;
  topicSchemaActiveTarget = resolvedTarget;
  syncTopicSchemaFieldsFromDom(cache, resolvedTarget);
  const fields = ensureTopicSchemaTargetFieldsBucket(cache, resolvedTarget);
  if (!fields) return;
  let index = 1;
  let key = defaultTopicSchemaFieldKeyForTarget(target, index);
  while (fields[key]) {
    index += 1;
    key = defaultTopicSchemaFieldKeyForTarget(target, index);
  }
  fields[key] = buildTopicSchemaFieldDefaults(index, resolvedTarget);
  renderTopicSchemaEditor();
  syncSaveButtonLamp();
  syncTopicSchemaPendingGroupHint();
  const keyInput = topicSchemaFieldsNode?.querySelector(`[data-schema-key="${CSS.escape(key)}"]`);
  keyInput?.focus();
  keyInput?.select();
}

function removeTopicSchemaField(target, key) {
  if (target === "settings" && ExternalFileMask.isBuiltinSettingsSchemaKey(key)) return;
  const cache = getTopicSchemaCache();
  if (!cache?.awnSchema?.[target]?.fields) return;
  delete cache.awnSchema[target].fields[key];
  setTopicSchemaFieldExpanded(target, key, false);
  renderTopicSchemaEditor();
  syncSaveButtonLamp();
}

function reorderTopicSchemaFields(target, key, direction) {
  const cache = getTopicSchemaCache();
  if (!cache?.awnSchema?.[target]?.fields) return;
  const fields = cache.awnSchema[target].fields;
  const keys = Object.keys(fields);
  const index = keys.indexOf(key);
  if (index < 0) return;
  const nextIndex = direction === "up" ? index - 1 : index + 1;
  if (nextIndex < 0 || nextIndex >= keys.length) return;
  keys.splice(index, 1);
  keys.splice(nextIndex, 0, key);
  const reordered = {};
  for (const fieldKey of keys) {
    reordered[fieldKey] = fields[fieldKey];
  }
  cache.awnSchema[target].fields = reordered;
  renderTopicSchemaEditor();
  syncSaveButtonLamp();
}

function normalizeTopicSchemaFieldKeyForTarget(key) {
  return normalizeTopicSchemaCustomFieldKey(key);
}

function renameTopicSchemaField(target, oldKey, newKey) {
  if (target === "settings" && ExternalFileMask.isBuiltinSettingsSchemaKey(oldKey)) return;
  const cache = getTopicSchemaCache();
  if (!cache?.awnSchema?.[target]?.fields || oldKey === newKey) return;
  const fields = cache.awnSchema[target].fields;
  let trimmed = normalizeTopicSchemaFieldKeyForTarget(newKey);
  if (!trimmed || (trimmed !== oldKey && fields[trimmed])) return;
  fields[trimmed] = fields[oldKey];
  delete fields[oldKey];
  if (isTopicSchemaFieldExpanded(target, oldKey)) {
    setTopicSchemaFieldExpanded(target, oldKey, false);
    setTopicSchemaFieldExpanded(target, trimmed, true);
  }
}

function getTopicSchemaTargetFieldCount(targetId, cache = getTopicSchemaCache()) {
  return getTopicSchemaCustomFieldKeys(targetId, cache).length;
}

function createTopicSchemaTargetTabButton(spec, cache = getTopicSchemaCache()) {
  const { id, group, slotKey, contentKind, label, fullLabel, isDefault } = spec;
  const btn = document.createElement("button");
  btn.type = "button";
  btn.className = "topic-schema-target-tab";
  if (group === "core" || group === "settings") btn.classList.add("topic-schema-target-tab--core");
  if (group === "slot") btn.classList.add("topic-schema-target-tab--slot");
  if (group === "slot-meta") btn.classList.add("topic-schema-target-tab--slot-meta");
  if (group === "slot-sidecar") btn.classList.add("topic-schema-target-tab--slot-sidecar");
  if (isDefault) btn.classList.add("topic-schema-target-tab--default");
  if (slotKey) btn.dataset.slotKey = slotKey;
  if (contentKind) btn.dataset.contentKind = contentKind;
  btn.dataset.target = id;
  btn.setAttribute("role", "tab");
  btn.setAttribute("aria-selected", id === topicSchemaActiveTarget ? "true" : "false");
  btn.classList.toggle("is-active", id === topicSchemaActiveTarget);
  const configured = topicSchemaTargetHasCustomFields(id, cache);
  btn.classList.toggle("is-configured", configured);
  const fieldCount = getTopicSchemaTargetFieldCount(id, cache);
  const typeName = getTopicSchemaTargetTypeName(id) || AWN_SCHEMA_TARGET_TYPE_NAMES[id];
  const tabLabel = label || getTopicSchemaTargetLabel(id);
  btn.replaceChildren();
  const mark = document.createElement("span");
  mark.className = "topic-schema-target-tab-mark";
  mark.classList.toggle("is-filled", configured);
  mark.classList.toggle("is-empty", !configured);
  mark.setAttribute("aria-hidden", "true");
  btn.appendChild(mark);
  const labelNode = document.createElement("span");
  labelNode.className = "topic-schema-target-tab-label";
  labelNode.textContent = tabLabel;
  btn.appendChild(labelNode);
  const countNode = document.createElement("span");
  countNode.className = "topic-schema-target-tab-count";
  countNode.textContent = String(fieldCount);
  countNode.setAttribute("aria-hidden", "true");
  btn.appendChild(countNode);
  const countLabel = fieldCount === 1 ? "1 поле" : fieldCount >= 2 && fieldCount <= 4 ? `${fieldCount} поля` : `${fieldCount} полей`;
  if (fullLabel || typeName) {
    btn.title = [fullLabel || getTopicSchemaTargetLabel(id), typeName, countLabel]
      .filter(Boolean)
      .join(" · ");
  } else {
    btn.title = `${tabLabel} · ${countLabel}`;
  }
  return btn;
}

function renderTopicSchemaTargetTabs(cache = getTopicSchemaCache()) {
  if (!topicSchemaTargetTabsNode) return;
  topicSchemaTargetTabsNode.replaceChildren();

  if (isWorkspaceSchemaContext()) {
    topicSchemaTargetTabsNode.append(
      createTopicSchemaTargetTabButton(
        { id: "workspace", label: "Workspace", typeName: "awn.hub.topic.ws", group: "core" },
        cache
      ),
      createTopicSchemaTargetTabButton(
        { id: "settings", label: "Настройки", typeName: "awn.settings", group: "settings" },
        cache
      )
    );
    return;
  }

  if (isAreaSchemaContext()) {
    topicSchemaTargetTabsNode.append(
      createTopicSchemaTargetTabButton(
        { id: "area", label: "Область", typeName: "awn.hub.topic.area", group: "core" },
        cache
      ),
      createTopicSchemaTargetTabButton(
        { id: "settings", label: "Настройки", typeName: "awn.settings", group: "settings" },
        cache
      )
    );
    return;
  }

  const manifestPath = getTopicSchemaManifestPath(activePath);
  const sharedSlotMode = isTopicSharedSlotActiveForNode(manifestPath || activePath);
  const groups =
    typeof TopicSchemaSlotSpecs !== "undefined" && TopicSchemaSlotSpecs.buildTopicSchemaTargetTabGroups
      ? TopicSchemaSlotSpecs.buildTopicSchemaTargetTabGroups({
          sharedSlotMode,
          flexibleSlotLabel: TOPIC_SHARED_SLOT_RAIL_LABEL
        })
      : null;

  if (!groups) {
    topicSchemaTargetTabsNode.append(
      ...getTopicSchemaTargetSpecsForEditor().map((spec) => createTopicSchemaTargetTabButton(spec, cache))
    );
    return;
  }

  for (const group of groups) {
    const section = document.createElement("section");
    section.className = "topic-schema-target-tab-group";
    section.dataset.tabGroup = group.id;
    section.classList.toggle("is-configured", topicSchemaTabGroupHasCustomFields(group, cache));

    const heading = document.createElement("div");
    heading.className = "topic-schema-target-tab-group-label";
    const groupConfigured = topicSchemaTabGroupHasCustomFields(group, cache);
    const groupMark = document.createElement("span");
    groupMark.className = "topic-schema-target-group-mark";
    groupMark.classList.toggle("is-filled", groupConfigured);
    groupMark.classList.toggle("is-empty", !groupConfigured);
    groupMark.setAttribute("aria-hidden", "true");
    heading.appendChild(groupMark);
    heading.append(document.createTextNode(group.label));
    section.appendChild(heading);

    const body = document.createElement("div");
    body.className = "topic-schema-target-tab-group-body";

    if (group.id === "core" && group.coreTabs) {
      const row = document.createElement("div");
      row.className = "topic-schema-target-tab-row topic-schema-target-tab-row--core";
      for (const tab of group.coreTabs) {
        row.appendChild(createTopicSchemaTargetTabButton(tab, cache));
      }
      body.appendChild(row);
    } else if (group.slots) {
      for (const slot of group.slots) {
        const row = document.createElement("div");
        row.className = "topic-schema-target-tab-row";
        row.classList.toggle("is-configured", topicSchemaSlotHasCustomFields(slot, cache));

        const slotLabel = document.createElement("span");
        slotLabel.className = "topic-schema-target-slot-label";
        slotLabel.textContent = slot.label;
        row.appendChild(slotLabel);

        const tabs = document.createElement("div");
        tabs.className = "topic-schema-target-slot-tabs";
        tabs.setAttribute("role", "presentation");
        for (const tab of slot.tabs) {
          tabs.appendChild(createTopicSchemaTargetTabButton(tab, cache));
        }
        row.appendChild(tabs);
        body.appendChild(row);
      }
    }

    section.appendChild(body);
    topicSchemaTargetTabsNode.appendChild(section);
  }
}

function renderTopicSchemaBaseFields(cache = getTopicSchemaCache()) {
  if (!topicSchemaBaseFieldsNode) return;
  const target = topicSchemaActiveTarget;
  const base = resolveTopicSchemaBaseType(target, cache);
  const titleNode = topicSchemaPanelNode?.querySelector(".topic-schema-base-title");
  const typeName = getTopicSchemaTargetTypeName(target) || AWN_SCHEMA_TARGET_TYPE_NAMES[target];
  if (titleNode) {
    const label = getTopicSchemaTargetLabel(target);
    titleNode.textContent = typeName
      ? `Базовые поля · ${label} (${typeName})`
      : "Базовые поля (read-only)";
  }
  if (!base?.fields) {
    topicSchemaBaseFieldsNode.textContent = "—";
    return;
  }
  const fieldEntries = { ...base.fields };
  if (target === "settings") {
    fieldEntries[ExternalFileMask.AWN_MASK_FILE_KEY] = ExternalFileMask.AWN_MASK_FILE_FIELD_DEF;
  }
  const parts = Object.entries(fieldEntries).map(([key, def]) => {
    const title = def?.title ? ` (${def.title})` : "";
    const typeLabel = getAwnFieldTypeLabel(def?.type);
    return `${key}${title} · ${typeLabel}`;
  });
  topicSchemaBaseFieldsNode.textContent = parts.join(" · ") || "—";
}

function syncTopicSchemaSettingsToggleButton(btn, expanded) {
  if (!btn) return;
  btn.setAttribute("aria-expanded", expanded ? "true" : "false");
  btn.classList.toggle("is-expanded", expanded);
  if (!btn.querySelector(".topic-schema-settings-toggle-label")) {
    btn.replaceChildren();
    const label = document.createElement("span");
    label.className = "topic-schema-settings-toggle-label";
    label.textContent = "Настройки";
    const chevron = document.createElement("span");
    chevron.className = "topic-schema-settings-toggle-chevron";
    chevron.setAttribute("aria-hidden", "true");
    btn.append(label, chevron);
  }
}

function createTopicSchemaSettingsToggleButton({ expanded = false, hasAdvancedSettings = false, schemaKey = "" } = {}) {
  const settingsBtn = document.createElement("button");
  settingsBtn.type = "button";
  settingsBtn.className = "topic-schema-settings-toggle";
  settingsBtn.dataset.schemaAction = "toggle-settings";
  if (schemaKey) settingsBtn.dataset.schemaKey = schemaKey;
  settingsBtn.title = hasAdvancedSettings
    ? "Расширенные настройки (заполнены)"
    : "Расширенные настройки";
  settingsBtn.classList.toggle("is-configured", hasAdvancedSettings);
  syncTopicSchemaSettingsToggleButton(settingsBtn, expanded);
  return settingsBtn;
}

function createTopicSchemaSortButton(action, key, { disabled = false, title = "" } = {}) {
  const button = document.createElement("button");
  button.type = "button";
  button.className = "topic-schema-sort-btn";
  button.dataset.schemaAction = action;
  button.dataset.schemaKey = key;
  button.textContent = action === "move-up" ? "↑" : "↓";
  button.title = title;
  button.disabled = disabled;
  return button;
}

function createTopicSchemaGroupSelect(fieldDef, schemaKey, fields = {}, target = topicSchemaActiveTarget) {
  const select = document.createElement("select");
  select.className = "topic-schema-inline-select topic-schema-inline-select--group";
  select.dataset.schemaKey = schemaKey;
  select.dataset.schemaField = "group";
  select.title = "Раздел — переместить поле в другую секцию";

  const rawGroup = String(fieldDef?.group || "").trim();
  const current = !rawGroup || rawGroup === "content" ? "" : rawGroup;
  const names = collectSchemaEditorGroupNames(fields, target).filter((name) => name !== "content");
  if (current && !names.includes(current)) names.push(current);
  names.sort((a, b) => a.localeCompare(b, "ru"));

  const addOption = (value, label, selected = false) => {
    const option = document.createElement("option");
    option.value = value;
    option.textContent = label;
    option.selected = selected;
    select.appendChild(option);
  };

  addOption("", "Основное", current === "");
  for (const name of names) {
    addOption(name, name, name === current);
  }

  return select;
}

function applySchemaEditorFieldGroupMove(fields, fieldKey, groupValue) {
  const fieldDef = fields?.[fieldKey];
  if (!fieldDef) return;
  const trimmed = String(groupValue || "").trim();
  if (!trimmed || trimmed === "content") delete fieldDef.group;
  else fieldDef.group = trimmed;

  const targetGroupId = resolvePropsFieldGroupId(fieldKey, fieldDef);
  let maxSort = 0;
  for (const key of Object.keys(fields || {})) {
    if (key === fieldKey) continue;
    if (resolvePropsFieldGroupId(key, fields[key]) !== targetGroupId) continue;
    maxSort = Math.max(maxSort, Number(fields[key]?.sort) || 0);
  }
  fieldDef.sort = maxSort + 1;
}

function restoreTopicSchemaFieldRowUiAfterRerender(activeKey, target = topicSchemaActiveTarget) {
  if (!activeKey || !isTopicSchemaFieldExpanded(target, activeKey)) return;
  setTopicSchemaFieldExpanded(target, activeKey, true);
  const nextRow = topicSchemaFieldsNode?.querySelector(
    `[data-schema-row-key="${CSS.escape(activeKey)}"]`
  );
  if (!nextRow) return;
  nextRow.classList.add("is-settings-open");
  nextRow.querySelector(".topic-schema-field-settings")?.classList.remove("is-collapsed");
  const toggle = nextRow.querySelector('[data-schema-action="toggle-settings"]');
  if (toggle) syncTopicSchemaSettingsToggleButton(toggle, true);
}

function getTopicSchemaScrollRoot(root = topicSchemaPanelNode) {
  const panel = root?.closest(".topic-schema-panel") || root || topicSchemaPanelNode;
  if (panel && !panel.classList.contains("hidden")) {
    const docSlab = panel.closest(".doc-slab-content");
    if (docSlab?.querySelector(":scope > .doc-slab-main > .topic-schema-panel:not(.hidden)")) {
      return docSlab;
    }
  }
  const fieldsNode = panel?.querySelector?.(":scope > .topic-schema-fields");
  return fieldsNode || panel;
}

function preserveTopicSchemaScrollDuring(callback, root = topicSchemaPanelNode) {
  const scrollRoot = getTopicSchemaScrollRoot(root);
  const scrollTop = scrollRoot?.scrollTop ?? 0;
  callback();
  if (!scrollRoot) return;
  requestAnimationFrame(() => {
    scrollRoot.scrollTop = scrollTop;
  });
}

function syncTopicSchemaFieldRowSortUi(row, index, total) {
  const up = row.querySelector('[data-schema-action="move-up"]');
  const down = row.querySelector('[data-schema-action="move-down"]');
  if (up) up.disabled = index <= 0;
  if (down) down.disabled = index >= total - 1;
}

function syncTopicSchemaFieldRowGroupSelect(row, fieldDef, key, fields, target) {
  const groupSelect = row.querySelector('[data-schema-field="group"]');
  if (!groupSelect) return;
  const rawGroup = String(fieldDef?.group || "").trim();
  const current = !rawGroup || rawGroup === "content" ? "" : rawGroup;
  const names = collectSchemaEditorGroupNames(fields, target).filter((name) => name !== "content");
  if (current && !names.includes(current)) names.push(current);
  names.sort((a, b) => a.localeCompare(b, "ru"));

  const selected = groupSelect.value;
  groupSelect.replaceChildren();
  const addOption = (value, label) => {
    const option = document.createElement("option");
    option.value = value;
    option.textContent = label;
    groupSelect.appendChild(option);
  };
  addOption("", "Основное");
  for (const name of names) addOption(name, name);
  groupSelect.value = names.includes(current) || current === "" ? current : selected;
}

function reorderTopicSchemaFieldsInDom(cache = getTopicSchemaCache()) {
  if (!topicSchemaFieldsNode) return false;
  const target = topicSchemaActiveTarget;
  const supportsFieldGroups = schemaEditorTargetSupportsFieldGroups(target);
  const fields = cache?.awnSchema?.[target]?.fields || {};
  const keys = sortSchemaEditorFieldKeys(getTopicSchemaCustomFieldKeys(target, cache), fields);
  if (!keys.length) return false;

  const rowByKey = new Map();
  topicSchemaFieldsNode.querySelectorAll(".topic-schema-field-row").forEach((row) => {
    const key = String(row.dataset.schemaRowKey || "").trim();
    if (key) rowByKey.set(key, row);
  });
  if (keys.some((key) => !rowByKey.has(key))) return false;

  const groupOrder = supportsFieldGroups ? getSchemaEditorGroupOrder(fields, keys) : [];
  const groupState = { lastGroup: null };
  const scrollRoot = getTopicSchemaScrollRoot();
  const scrollTop = scrollRoot?.scrollTop ?? 0;

  topicSchemaFieldsNode.replaceChildren();
  keys.forEach((key, index) => {
    const fieldDef = fields[key] || {};
    if (supportsFieldGroups) {
      const groupId = resolvePropsFieldGroupId(key, fieldDef);
      appendSchemaEditorGroupHeader(topicSchemaFieldsNode, groupId, groupState, {
        groupIndex: groupOrder.indexOf(groupId),
        groupCount: groupOrder.length
      });
    }
    const row = rowByKey.get(key);
    syncTopicSchemaFieldRowSortUi(row, index, keys.length);
    if (supportsFieldGroups) syncTopicSchemaFieldRowGroupSelect(row, fieldDef, key, fields, target);
    topicSchemaFieldsNode.appendChild(row);
  });

  if (scrollRoot) scrollRoot.scrollTop = scrollTop;
  return true;
}

