async function appendEntryOverviewSectionSchemaPanel(container, context) {
  if (!isEntryOverviewCategoryContext(context)) return;
  const params = resolveSectionSchemaParams(context);
  if (!params) return;

  const panel = createEntryOverviewSectionSchemaPanel(context);
  panel.querySelector(".topic-schema-base-fields").textContent = "Загрузка…";
  const fold = wrapEntryOverviewSectionSchemaFold(panel, params);
  const propFolds = container.querySelectorAll(
    ".node-overview-awn-props-fold, .node-overview-custom-props-fold, .node-overview-settings-props-fold"
  );
  const anchor =
    (propFolds.length ? propFolds[propFolds.length - 1] : null) ||
    container.querySelector(".node-navigation-hero-main");
  if (anchor) anchor.insertAdjacentElement("afterend", fold);
  else container.appendChild(fold);

  const editorSeq = ++sectionSchemaEditorSeq;
  try {
    const cache = await loadSectionSchemaForEntry(context);
    if (editorSeq !== sectionSchemaEditorSeq) return;
    cache.entryKind = context.entryKind;
    cache.memoryKind = context.memoryKind || "external";
    panel._sectionSchemaCache = cache;
    panel._sectionSchemaParams = params;
    bindSectionSchemaPanelEvents(panel, cache, context);
    renderSectionSchemaEditor(panel, cache);
  } catch (error) {
    if (editorSeq !== sectionSchemaEditorSeq) return;
    panel.querySelector(".topic-schema-base-fields").textContent = `Ошибка: ${error.message}`;
  }
}

function isAwnFieldKey(key) {
  return /^awn-/i.test(String(key || "").trim());
}

function isWsFieldKey(key) {
  return /^ws-/i.test(String(key || "").trim());
}

function isAreaFieldKey(key) {
  return /^area-/i.test(String(key || "").trim());
}

function isTopicFieldKey(key) {
  const trimmed = String(key || "").trim();
  return /^topic-/i.test(trimmed) && !/^topic-setting-/i.test(trimmed);
}

function normalizeWorkspaceSchemaFieldKey(key) {
  return normalizeTopicSchemaCustomFieldKey(key);
}

function normalizeAreaSchemaFieldKey(key) {
  return normalizeTopicSchemaCustomFieldKey(key);
}

function normalizeTopicSchemaFieldKey(key) {
  return normalizeTopicSchemaCustomFieldKey(key);
}

function normalizeSettingsSchemaFieldKey(key) {
  return normalizeTopicSchemaCustomFieldKey(key);
}

function isTopicSettingFieldKey(key) {
  return /^topic-setting-/i.test(String(key || "").trim());
}

function isWsSettingFieldKey(key) {
  return /^ws-setting-/i.test(String(key || "").trim());
}

function isAreaSettingFieldKey(key) {
  return /^area-setting-/i.test(String(key || "").trim());
}

function normalizeTopicSettingSchemaFieldKey(key) {
  return normalizeSettingsSchemaFieldKey(key);
}

function isSlotCustomFieldKey(key) {
  return /^x-/i.test(String(key || "").trim());
}

function isSettingsPropKeyInRawSchema(key, cache = resolveActiveOverviewSchemaCache()) {
  const normalized = normalizePropsKey(key);
  if (!normalized) return false;
  return Object.prototype.hasOwnProperty.call(cache?.awnSchema?.settings?.fields || {}, normalized);
}

function isSettingsPropKeyForSchemaLevel(key, nodePath = getResolvedNodePath(activePath), levelOverride = null) {
  const normalized = normalizePropsKey(key);
  if (!normalized) return false;
  if (isSettingsPropKeyInRawSchema(normalized)) return true;
  const level = levelOverride || getSchemaContextLevel(nodePath);
  if (level === "workspace") return isWsSettingFieldKey(normalized);
  if (level === "area") return isAreaSettingFieldKey(normalized);
  return isTopicSettingFieldKey(normalized);
}

function isCustomPropKeyForSchemaLevel(key, nodePath = getResolvedNodePath(activePath)) {
  const normalized = normalizePropsKey(key);
  if (!normalized || isAwnFieldKey(normalized)) return false;
  if (isOverviewSettingsFieldKey(normalized, nodePath)) return false;
  if (isForeignLayerCustomPropKey(normalized, nodePath)) return false;
  return isOverviewCustomFieldDefinedInSchema(normalized, nodePath);
}

function isCustomFieldDefinedInSchemaTarget(key, target, cache) {
  const normalized = normalizePropsKey(key);
  if (!normalized || !cache?.awnSchema?.[target]?.fields) return false;
  return Object.prototype.hasOwnProperty.call(cache.awnSchema[target].fields, normalized);
}

function isForeignLayerCustomPropKey(key, nodePath = getResolvedNodePath(activePath)) {
  const normalized = normalizePropsKey(key);
  if (!normalized || isAwnFieldKey(normalized)) return false;
  const customFields = getOverviewCustomSchemaLayerFields(nodePath);
  if (Object.prototype.hasOwnProperty.call(customFields, normalized)) return false;

  const cache = resolveActiveOverviewSchemaCache();
  const currentTarget = resolveOverviewSchemaTargetForNode(nodePath);
  if (cache?.awnSchema && currentTarget) {
    for (const target of ["workspace", "area", "topic"]) {
      if (target === currentTarget) continue;
      if (isCustomFieldDefinedInSchemaTarget(normalized, target, cache)) return true;
    }
  }

  const level = getSchemaContextLevel(nodePath);
  if (isWsFieldKey(normalized) && level !== "workspace") return true;
  if (isAreaFieldKey(normalized) && level !== "area") return true;
  if (isTopicFieldKey(normalized) && level !== "topic") return true;
  if (isSlotCustomFieldKey(normalized)) return false;
  return false;
}

function isForeignLayerSettingsPropKey(key, nodePath = getResolvedNodePath(activePath)) {
  const normalized = normalizePropsKey(key);
  if (!normalized) return false;
  return (
    (isWsSettingFieldKey(normalized) ||
      isAreaSettingFieldKey(normalized) ||
      isTopicSettingFieldKey(normalized)) &&
    !isSettingsPropKeyForSchemaLevel(normalized, nodePath)
  );
}

function stripAwnSchemaToContextLevel(awnSchema, level) {
  const normalized = normalizeTopicSchemaState(awnSchema);
  const result = emptyTopicSchemaState();
  if (level === "workspace") {
    if (normalized.workspace?.fields && Object.keys(normalized.workspace.fields).length) {
      result.workspace = { fields: { ...normalized.workspace.fields } };
    }
  } else if (level === "area") {
    if (normalized.area?.fields && Object.keys(normalized.area.fields).length) {
      result.area = { fields: { ...normalized.area.fields } };
    }
  } else {
    if (normalized.topic?.fields && Object.keys(normalized.topic.fields).length) {
      result.topic = { fields: { ...normalized.topic.fields } };
    }
    for (const { id } of getTopicSchemaTargetSpecs()) {
      if (id === "workspace" || id === "area" || id === "topic" || id === "settings") continue;
      const fields = normalized[id]?.fields;
      if (fields && Object.keys(fields).length) {
        result[id] = { fields: { ...fields } };
      }
    }
    if (normalized.sidecar?.fields && Object.keys(normalized.sidecar.fields).length) {
      result.sidecar = { fields: { ...normalized.sidecar.fields } };
    }
  }
  const settingsFields = normalized.settings?.fields || {};
  if (Object.keys(settingsFields).length) {
    result.settings = { fields: { ...settingsFields } };
  }
  return result;
}

function normalizeSlotSchemaFieldKey(key) {
  const trimmed = String(key || "").trim();
  if (!trimmed || isAwnFieldKey(trimmed)) return trimmed;
  return trimmed;
}

function isSchemaDefinedFieldKey(key) {
  return (
    isAwnFieldKey(key) ||
    isWsFieldKey(key) ||
    isAreaFieldKey(key) ||
    isTopicFieldKey(key) ||
    isTopicSettingFieldKey(key) ||
    isWsSettingFieldKey(key) ||
    isAreaSettingFieldKey(key) ||
    isSlotCustomFieldKey(key)
  );
}

function resolveOverviewSchemaTargetForNode(nodePath = getResolvedNodePath(activePath)) {
  const overviewContext =
    activeContentMode === NODE_ENTRY_OVERVIEW_MODE ? activeEntryOverviewContext : null;
  if (activeContentMode === NODE_ENTRY_OVERVIEW_MODE && overviewContext) {
    return resolveOverviewSchemaTargetForContext(overviewContext);
  }
  return resolveAwnSchemaTargetForContext(nodePath);
}

function getOverviewSchemaLookupTargets(
  nodePath = getResolvedNodePath(activePath),
  context = activeContentMode === NODE_ENTRY_OVERVIEW_MODE ? activeEntryOverviewContext : null
) {
  const primary = resolveOverviewSchemaTargetForNode(nodePath);
  const targets = primary ? [primary] : [];

  const slotKey =
    activeContentMode === NODE_ENTRY_OVERVIEW_MODE && context
      ? getDataStorageSlotKeyForEntryView(NODE_ENTRY_OVERVIEW_MODE)
      : resolveSchemaSlotKeyForContext(nodePath);

  if (slotKey && typeof TopicSchemaSlotSpecs !== "undefined" && primary) {
    const spec = TopicSchemaSlotSpecs.findTopicSchemaTargetSpecById(primary);
    if (spec?.contentKind === "record") {
      const categoryTarget = TopicSchemaSlotSpecs.resolveTopicSchemaTargetId(slotKey, {
        contentKind: "category"
      });
      if (categoryTarget && !targets.includes(categoryTarget)) targets.push(categoryTarget);
    } else if (spec?.contentKind === "sidecar") {
      const categoryTarget = TopicSchemaSlotSpecs.resolveTopicSchemaTargetId(slotKey, {
        contentKind: "category"
      });
      if (categoryTarget && !targets.includes(categoryTarget)) targets.push(categoryTarget);
    }
  }

  return targets;
}

function collectOverviewCustomFieldsForTargets(cache, targets = []) {
  if (!cache || !Array.isArray(targets) || !targets.length) return {};
  const result = {};
  for (const target of targets) {
    const layers = [
      getTopicSchemaCustomFieldsForTarget(target, cache),
      cache.sectionAwnSchema?.[target]?.fields || {},
      cache.topicAwnSchema?.[target]?.fields || {}
    ];
    for (const fields of layers) {
      for (const [key, def] of Object.entries(fields)) {
        if (!result[key]) result[key] = def;
      }
    }
  }
  return result;
}

function getOverviewCustomSchemaLayerFields(nodePath = getResolvedNodePath(activePath)) {
  const overviewContext =
    activeContentMode === NODE_ENTRY_OVERVIEW_MODE ? activeEntryOverviewContext : null;
  const cache = resolveActiveOverviewSchemaCache(overviewContext);
  if (!cache) return {};
  return collectOverviewCustomFieldsForTargets(
    cache,
    getOverviewSchemaLookupTargets(nodePath, overviewContext)
  );
}

function getOverviewSettingsSchemaFieldsFromCache(context = null, nodePath = getResolvedNodePath(activePath)) {
  const cache = resolveActiveOverviewSchemaCache(context);
  const allFields = cache?.awnSchema?.settings?.fields || {};
  const filtered = {};
  for (const [key, def] of Object.entries(allFields)) {
    if (isSettingsPropKeyForSchemaLevel(key, nodePath)) filtered[key] = def;
  }
  return filtered;
}

function getOverviewSchemaFieldDef(key, nodePath = getResolvedNodePath(activePath)) {
  const normalized = normalizePropsKey(key);
  if (!normalized) return null;

  const cache = resolveActiveOverviewSchemaCache();
  if (cache?.awnSchema) {
    for (const target of getOverviewSchemaLookupTargets(nodePath)) {
      const targetField = cache.awnSchema[target]?.fields?.[normalized];
      if (targetField) return targetField;
    }
    if (isOverviewSettingsFieldKey(normalized, nodePath)) {
      const settingsField = cache.awnSchema.settings?.fields?.[normalized];
      if (settingsField) return settingsField;
    }
  }

  if (isOverviewSettingsFieldKey(normalized, nodePath)) {
    return getActiveSettingsTypeDef()?.fields?.[normalized] || null;
  }

  return findPropsFieldDefInTopicSchemaTargets(normalized, cache) || getPropsFieldDef(normalized);
}

function isOverviewSettingsFieldKey(key, nodePath = getResolvedNodePath(activePath)) {
  const normalized = normalizePropsKey(key);
  if (!normalized) return false;
  const settingsFields = getOverviewSettingsSchemaFieldsFromCache(null, nodePath);
  if (Object.prototype.hasOwnProperty.call(settingsFields, normalized)) return true;
  if (isOverviewCustomSchemaFieldKey(normalized, nodePath)) return false;
  return isSettingsPropKeyForSchemaLevel(normalized, nodePath);
}

function isOverviewCustomSchemaFieldKey(key, nodePath = getResolvedNodePath(activePath)) {
  const normalized = normalizePropsKey(key);
  if (!normalized || isAwnFieldKey(normalized)) return false;
  const customFields = getOverviewCustomSchemaLayerFields(nodePath);
  return Object.prototype.hasOwnProperty.call(customFields, normalized);
}

function isOverviewExcludedPropKey(key) {
  const normalized = normalizePropsKey(key);
  return Boolean(normalized && OVERVIEW_EXCLUDED_PROP_KEYS.has(normalized));
}

function isOverviewAwnMetaItemKey(key, nodePath = getResolvedNodePath(activePath)) {
  const normalized = normalizePropsKey(key);
  if (!normalized || isOverviewExcludedPropKey(normalized)) return false;
  if (isOverviewSettingsFieldKey(normalized, nodePath)) return false;
  return isAwnFieldKey(normalized);
}

function isOverviewCustomMetaItemForContext(item, nodePath = getResolvedNodePath(activePath)) {
  const key = normalizePropsKey(item?.key);
  if (!key || isOverviewExcludedPropKey(key)) return false;
  if (isOverviewSettingsFieldKey(key, nodePath) && !isOverviewCustomSchemaFieldKey(key, nodePath)) return false;
  if (isOverviewAwnMetaItemKey(key)) return false;
  if (isForeignLayerCustomPropKey(key, nodePath)) return false;
  if (isForeignLayerSettingsPropKey(key, nodePath)) return false;
  return true;
}

function isOverviewSettingsFieldDefinedInSchema(key, nodePath = getResolvedNodePath(activePath)) {
  const normalized = normalizePropsKey(key);
  if (!normalized) return false;
  const schemaFields = getOverviewSettingsSchemaFieldsFromCache(null, nodePath);
  return Object.prototype.hasOwnProperty.call(schemaFields, normalized);
}

function isOverviewCustomFieldDefinedInSchema(key, nodePath = getResolvedNodePath(activePath)) {
  const normalized = normalizePropsKey(key);
  if (!normalized) return false;
  const customFields = getOverviewCustomSchemaLayerFields(nodePath);
  return Object.prototype.hasOwnProperty.call(customFields, normalized);
}

function isNodeOverviewMetaItemInSchema(item, nodePath = getResolvedNodePath(activePath)) {
  if (item?.inSchema === true) return true;
  if (item?.inSchema === false) return false;
  const key = normalizePropsKey(item?.key);
  if (!key) return false;
  if (isOverviewSettingsFieldKey(key, nodePath)) {
    return isOverviewSettingsFieldDefinedInSchema(key, nodePath);
  }
  if (isCustomPropKeyForSchemaLevel(key, nodePath) || isSlotCustomFieldKey(key)) {
    return isOverviewCustomFieldDefinedInSchema(key, nodePath);
  }
  return isPropsFieldDefinedInActiveSchema(key, { fieldDef: item?.fieldDef });
}

function isNodeOverviewMetaItemFilled(item) {
  if (!item) return false;
  const display = String(item.value ?? "").trim();
  if (display && display !== "—") return true;
  return Boolean(String(item.rawValue ?? "").trim());
}

function orderOverviewMetaItemsBySchema(items = [], schemaKeys = []) {
  const map = new Map();
  for (const item of items) {
    const key = normalizePropsKey(item?.key);
    if (key) map.set(key, item);
  }
  const schemaKeySet = new Set(
    (Array.isArray(schemaKeys) ? schemaKeys : [])
      .map((key) => normalizePropsKey(key))
      .filter(Boolean)
  );
  const ordered = [];
  const seen = new Set();
  for (const key of schemaKeys) {
    const normalized = normalizePropsKey(key);
    if (!normalized || seen.has(normalized) || !map.has(normalized)) continue;
    seen.add(normalized);
    ordered.push(map.get(normalized));
  }
  const orphanItems = [];
  for (const item of items) {
    const normalized = normalizePropsKey(item?.key);
    if (!normalized || seen.has(normalized)) continue;
    seen.add(normalized);
    if (schemaKeySet.has(normalized)) continue;
    orphanItems.push(item);
  }
  orphanItems.sort((a, b) => String(a.key).localeCompare(String(b.key), "ru"));
  return [...ordered, ...orphanItems];
}

function getOverviewSettingsSchemaFieldKeys(
  schemaFields = getOverviewSettingsSchemaFieldsFromCache(),
  nodePath = getResolvedNodePath(activePath)
) {
  if (!schemaFields || typeof schemaFields !== "object") return [];
  return Object.keys(schemaFields).filter((key) => {
    if (HIDDEN_PROPS_FIELD_KEYS.has(key)) return false;
    if (OVERVIEW_EXCLUDED_PROP_KEYS.has(key)) return false;
    if (!shouldIncludePropsFieldKey(key)) return false;
    if (!isSettingsPropKeyForSchemaLevel(key, nodePath)) return false;
    return true;
  });
}

function shouldIncludeOverviewCustomSchemaFieldKey(key, nodePath = getResolvedNodePath(activePath)) {
  if (HIDDEN_PROPS_FIELD_KEYS.has(key)) return false;
  if (OVERVIEW_EXCLUDED_PROP_KEYS.has(key)) return false;
  if (!shouldIncludePropsFieldKey(key)) return false;
  if (isAwnFieldKey(key)) return false;
  return isOverviewCustomSchemaFieldKey(key, nodePath);
}

function getOverviewCustomSchemaFieldKeys(nodePath = getResolvedNodePath(activePath)) {
  const overviewContext =
    activeContentMode === NODE_ENTRY_OVERVIEW_MODE ? activeEntryOverviewContext : null;
  const cache = resolveActiveOverviewSchemaCache(overviewContext);
  const targets = getOverviewSchemaLookupTargets(nodePath, overviewContext);
  const customFields = getOverviewCustomSchemaLayerFields(nodePath);

  const acceptKey = (key) => shouldIncludeOverviewCustomSchemaFieldKey(key, nodePath);

  const hasSectionLayer =
    Boolean(cache?.sectionAwnSchema) ||
    (Array.isArray(cache?.sectionChain) && cache.sectionChain.length > 0);

  if (hasSectionLayer && cache) {
    const ordered = [];
    const seen = new Set();

    for (const target of targets) {
      const topicFields = cache.topicAwnSchema?.[target]?.fields || {};
      const localFields = cache.sectionAwnSchema?.[target]?.fields || {};
      const localKeySet = new Set(Object.keys(localFields));

      for (const key of Object.keys(topicFields)) {
        if (!customFields[key] || localKeySet.has(key) || !acceptKey(key) || seen.has(key)) continue;
        seen.add(key);
        ordered.push(key);
      }
      for (const key of Object.keys(localFields)) {
        if (!acceptKey(key) || seen.has(key)) continue;
        seen.add(key);
        ordered.push(key);
      }
    }
    for (const key of Object.keys(customFields)) {
      if (!acceptKey(key) || seen.has(key)) continue;
      seen.add(key);
      ordered.push(key);
    }
    return ordered;
  }

  return Object.keys(customFields).filter((key) => acceptKey(key));
}

function isOrphanPropsFieldKey(key, nodePath = getPropsContextPath()) {
  const entryKey = normalizePropsKey(key);
  if (entryKey === "awn-preview" || entryKey === "awn-attachments" || entryKey === "awn-materials") {
    return false;
  }
  if (entryKey && HIDDEN_PROPS_FIELD_KEYS.has(entryKey)) return false;
  if (!entryKey) return true;
  return !isPropsFieldDefinedInSchema(entryKey, nodePath);
}

function isPropsFieldDefinedInSchema(key, nodePath = getPropsContextPath()) {
  const normalized = normalizePropsKey(key);
  if (!normalized) return false;
  if (getPropsFieldDef(normalized)) return true;
  if (isOverviewCustomFieldDefinedInSchema(normalized, nodePath)) return true;
  if (isOverviewSettingsFieldDefinedInSchema(normalized, nodePath)) return true;
  return false;
}

const PROPS_ASIDE_ORPHAN_GROUP_ID = "orphan";

function collectPropsAsideOrphanItems(asideItems = [], nodePath = getPropsContextPath()) {
  const renderedKeys = new Set(
    asideItems.map(({ entry }) => normalizePropsKey(entry?.key)).filter(Boolean)
  );
  const orphans = [];
  for (let index = 0; index < propsFormEntries.length; index += 1) {
    const entry = propsFormEntries[index];
    const key = normalizePropsKey(entry?.key);
    if (!key) continue;
    if (renderedKeys.has(key)) continue;
    if (isPropsHiddenStorageKey(key)) continue;
    if (!shouldIncludePropsFieldKey(key, nodePath)) continue;
    if (isPropsAsideDedicatedBlockField(key)) continue;
    if (isPropsFieldDefinedInSchema(key, nodePath)) continue;
    orphans.push({ entry, index });
  }
  const typeDef = getActiveAwnTypeDef();
  const fields = typeDef?.fields || {};
  orphans.sort((a, b) => comparePropsFieldSchemaOrder(a.entry.key, b.entry.key, fields));
  return orphans;
}

function decoratePropsAsideOrphanRow(row) {
  row.classList.add("is-schema-undefined");
  const hint = "Свойство не определено в схеме";
  row.title = row.title ? `${row.title} · ${hint}` : hint;
}

function isEditorCustomPropsFieldKey(key, nodePath = getPropsContextPath()) {
  return shouldRenderPropsFieldInEditorBody(key);
}

function isEditorCustomPropsFieldInSchema(key, entry = null, nodePath = getPropsContextPath()) {
  const normalized = normalizePropsKey(key);
  if (!normalized) return false;
  return Boolean(getPropsFieldDef(normalized));
}

function ensureEditorCustomPropsSchemaEntries(nodePath = getPropsContextPath()) {
  return ensurePropsSchemaEntriesForPlacement(PROPS_PLACEMENT_EDITOR_BODY);
}

function collectEditorCustomPropsItems(nodePath = getPropsContextPath()) {
  return collectPropsFormItemsForPlacement(PROPS_PLACEMENT_EDITOR_BODY);
}

function getPropsFormFieldContainers() {
  const containers = [];
  if (propsFormFieldsNode) containers.push(propsFormFieldsNode);
  if (editorCustomPropsFieldsNode) containers.push(editorCustomPropsFieldsNode);
  return containers;
}

function shouldShowEditorCustomPropsBar() {
  if (!editorCustomPropsBarNode || !editorCustomPropsFieldsNode) return false;
  if (propsRawYamlVisible) return false;
  if (!isDocAsideAvailable()) return false;
  return isDocAsidePropsTabAvailable() || Boolean(activeSystemFile);
}

function sanitizeEditorCustomPropsCssToken(value) {
  return String(value || "text")
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9_-]+/g, "-")
    .replace(/^-+|-+$/g, "") || "text";
}

function decorateEditorCustomPropsFormRow(row, entry) {
  const key = normalizePropsKey(entry?.key);
  if (!key) return;
  if (!isEditorCustomPropsFieldInSchema(key, entry)) {
    row.classList.add("is-schema-undefined");
    row.title = "Свойство не определено в схеме";
  }
  const fieldDef = getPropsFieldDef(key);
  const widget = resolvePropsFieldWidget(key, fieldDef);
  const typeId = normalizeCanonicalFieldTypeId(fieldDef?.type || "");
  const widgetToken = sanitizeEditorCustomPropsCssToken(widget);
  row.dataset.fieldWidget = widget;
  row.classList.add(`editor-custom-props-field--widget-${widgetToken}`);
  if (typeId) {
    row.dataset.fieldType = typeId;
    row.classList.add(
      `editor-custom-props-field--type-${sanitizeEditorCustomPropsCssToken(typeId.replace(/^awn\./, "").replace(/\./g, "-"))}`
    );
  }
}

function sortPropsFieldKeys(keys) {
  const list = [...keys];
  const standardKeys = getStandardPropsFieldKeys();
  return list.sort((a, b) => {
    const aNorm = String(a || "").toLowerCase();
    const bNorm = String(b || "").toLowerCase();
    const aBase = standardKeys.indexOf(aNorm);
    const bBase = standardKeys.indexOf(bNorm);
    const aAwn = isAwnFieldKey(aNorm);
    const bAwn = isAwnFieldKey(bNorm);
    const aWs = isWsFieldKey(aNorm);
    const bWs = isWsFieldKey(bNorm);
    if (aBase !== -1 && bBase !== -1) return aBase - bBase;
    if (aBase !== -1) return -1;
    if (bBase !== -1) return 1;
    if (aAwn && !bAwn) return -1;
    if (!aAwn && bAwn) return 1;
    if (aAwn && bAwn) return aNorm.localeCompare(bNorm);
    if (aWs && !bWs) return -1;
    if (!aWs && bWs) return 1;
    if (aWs && bWs) return aNorm.localeCompare(bNorm);
    return aNorm.localeCompare(bNorm);
  });
}

function sortPropsEntries(entries) {
  const drafts = entries.filter((entry) => !entry?.key);
  const keyed = dedupePropsEntriesByKey(entries).filter((entry) => entry?.key);
  const order = sortPropsFieldKeys(keyed.map((entry) => entry.key));
  const map = new Map(keyed.map((entry) => [entry.key, entry]));
  const result = [];
  for (const key of order) {
    if (map.has(key)) result.push(map.get(key));
  }
  for (const entry of keyed) {
    if (!order.includes(entry.key)) result.push(entry);
  }
  return [...result, ...drafts];
}

function dedupePropsEntriesByKey(entries) {
  const map = new Map();
  const drafts = [];
  for (const entry of entries || []) {
    if (!entry?.key) {
      drafts.push(entry);
      continue;
    }
    const key = normalizePropsKey(entry.key);
    if (!key) continue;
    map.set(key, { ...entry, key });
  }
  return [...map.values(), ...drafts];
}

function isRecordCategoryContentPath(nodePath) {
  const normalized = String(nodePath || "").replace(/\\/g, "/");
  if (
    (normalized.toLowerCase().endsWith("/_registration.md") ||
      normalized.toLowerCase().endsWith("/_reg-info.md")) &&
    /\/content\//i.test(normalized)
  ) {
    return true;
  }
  return (
    /\/awn-storage\/categories\/content\/[^/]+\.md$/i.test(normalized) ||
    /\/content\/categories\/[^/]+\.md$/i.test(normalized)
  );
}

function isMediaCategoryContentPath(nodePath) {
  const normalized = String(nodePath || "").replace(/\\/g, "/");
  if (
    (normalized.toLowerCase().endsWith("/_registration.md") ||
      normalized.toLowerCase().endsWith("/_reg-info.md")) &&
    /\/media\//i.test(normalized)
  ) {
    return true;
  }
  return /\/media\/categories\/[^/]+\.md$/i.test(normalized);
}

function getPropsContextPath(nodePath = activePath) {
  const manifestBase = getResolvedNodePath(activePath);
  const explicitPath = getResolvedNodePath(nodePath);

  if (activeContentMode === AWN_DATA_VIEW_MODE && awnDataViewStoreRel) {
    if (explicitPath && explicitPath !== manifestBase) return explicitPath;
    const recordPath = awnDataViewRecordCache
      ? resolveAwnDataRecordFilePath(awnDataViewRecordCache, awnDataViewStoreCache)
      : "";
    if (recordPath) return recordPath;
    const storeRel = String(awnDataViewStoreRel).replace(/\\/g, "/").replace(/^\/+|\/+$/g, "");
    if (storeRel) return `awn-databases/${storeRel}/manifest.md`.replace(/\/+/g, "/");
  }

  if (activeContentMode === NODE_ENTRY_OVERVIEW_MODE && activeEntryOverviewContext?.relPath) {
    return activeEntryOverviewContext.relPath;
  }

  if (manifestBase && activeContentMode === "external" && activeExternalFilePath) {
    const rel = String(activeExternalFilePath).replace(/\\/g, "/").replace(/^\/+/, "");
    return buildExternalMemoryFileRef(manifestBase, rel) || `${getExternalMemoryRootRel(manifestBase)}/${rel}`.replace(/\/+/g, "/");
  }

  if (manifestBase && isFlatStorageFileEditing()) {
    const rel = String(activeFlatStorageFilePath || "").replace(/\\/g, "/").replace(/^\/+/, "");
    return `${getNodeStorageSubfolderPath(manifestBase, getFlatStorageSectionFolderName(activeContentMode))}/${rel}`.replace(
      /\/+/g,
      "/"
    );
  }

  if (manifestBase && isMediaLibraryContentMode() && activeMediaMarkdownPath) {
    const rel = String(activeMediaMarkdownPath).replace(/\\/g, "/").replace(/^\/+/, "");
    const subfolder = getMediaLibraryStorageSubfolder();
    return `${getNodeStorageSubfolderPath(manifestBase, subfolder)}/${rel}`.replace(/\/+/g, "/");
  }

  if (manifestBase && isMediaLibraryContentMode() && (activeMediaSidecarSourcePath || activeMediaSidecarPath)) {
    const sourceRel = String(activeMediaSidecarSourcePath || "").replace(/\\/g, "/").replace(/^\/+/, "");
    const sidecarRel = sourceRel
      ? getMediaSidecarPath(sourceRel)
      : String(activeMediaSidecarPath || "").replace(/\\/g, "/").replace(/^\/+/, "");
    const subfolder = getMediaLibraryStorageSubfolder();
    return `${getNodeStorageSubfolderPath(manifestBase, subfolder)}/${sidecarRel}`.replace(/\/+/g, "/");
  }

  if (manifestBase && activeContentMode === "internal") {
    return resolveNodeSidecarRelPath(manifestBase, "content");
  }

  if (manifestBase && activeContentMode === "tabular" && isTabularSourceEditing()) {
    return resolveNodeSidecarRelPath(manifestBase, "tabular");
  }

  return getResolvedNodePath(nodePath) || manifestBase || "";
}

function normalizeAwnTypeName(typeName) {
  const raw = String(typeName || "").trim();
  if (!raw) return "";
  const shortAliases = {
    area: "awn.hub.topic.area",
    topic: "awn.hub.topic",
    workspace: "awn.hub.topic.ws",
    ws: "awn.hub.topic.ws",
    record: "awn.content.record",
    service: "service"
  };
  const normalized = /^awn\./i.test(raw) ? raw : shortAliases[raw.toLowerCase()] || raw;
  const legacyToCanonical = {
    "awn.record": "awn.content.record",
    "awn.record.category": "awn.content.category",
    "awn.sidecar": "awn.annotation.sidecar",
    "awn.media.category": "awn.content.category",
    "awn.topic": "awn.hub.topic",
    "awn.area": "awn.hub.topic.area",
    "awn.workspace": "awn.hub.topic.ws",
    "awn.database.record": "awn.content.record",
    "awn.database.record-lite": "awn.content.record-lite",
    "awn.database.record-csv": "awn.content.record-csv",
    "awn.database.category": "awn.content.category",
    "awn.database.content.record": "awn.content.record",
    "awn.database.content.record-lite": "awn.content.record-lite",
    "awn.database.content.record-csv": "awn.content.record-csv",
    "awn.database.content.category": "awn.content.category",
    "awn.database.element.record": "awn.content.record",
    "awn.database.element.record-lite": "awn.content.record-lite",
    "awn.database.element.record-csv": "awn.content.record-csv",
    "awn.database.element.category": "awn.content.category",
    "awn.database.element.sidecar": "awn.annotation.sidecar",
    "awn.database.content.sidecar": "awn.annotation.sidecar",
    "awn.page": "awn.hub.base",
    "awn.page.base": "awn.hub.base",
    "awn.hub.ws": "awn.hub.topic.ws",
    "awn.hub.area": "awn.hub.topic.area",
    "awn.hub.section": "awn.hub.topic.section"
  };
  const mapped = legacyToCanonical[normalized] || normalized;
  if (mapped.startsWith("awn.page.")) {
    return mapped.replace(/^awn\.page\./, "awn.hub.");
  }
  return mapped;
}

function getPropertiesApiPath() {
  const manifestPath = getActiveNodeApiPath();
  if (!manifestPath) return "";

  if (
    activeContentMode === "description" ||
    activeContentMode === NODE_OVERVIEW_MODE ||
    activeContentMode === NODE_NAVIGATION_MODE ||
    activeContentMode === NODE_ENTRY_OVERVIEW_MODE
  ) {
    if (activeContentMode === NODE_ENTRY_OVERVIEW_MODE && activeEntryOverviewContext?.relPath) {
      return activeEntryOverviewContext.relPath;
    }
    return manifestPath;
  }

  if (activeContentMode === "external" && activeExternalFilePath) {
    return getPropsContextPath();
  }

  if (isFlatStorageFileEditing()) {
    return getPropsContextPath();
  }

  if (isMediaAssetEditing()) {
    return getPropsContextPath();
  }

  return getPropsContextPath() || manifestPath;
}

function countManifestFolderDepthUnderContainer(normalized, containerFolder = getActiveAgentContainerFolder()) {
  const container = String(containerFolder || CONTAINER_FOLDER_DEFAULT).replace(/\\/g, "/").replace(/^\/+|\/+$/g, "");
  if (!container) return null;
  const marker = `${container}/`;
  const idx = normalized.toLowerCase().indexOf(marker.toLowerCase());
  if (idx < 0) return null;
  const after = normalized.slice(idx + marker.length);
  const segments = after.split("/").filter(Boolean);
  if (!segments.length) return 0;
  const last = segments[segments.length - 1].toLowerCase();
  if (last === "manifest.md") return Math.max(0, segments.length - 1);
  return segments.length;
}

function countManifestFolderDepthFromWorkspaceRoot(normalized) {
  const parts = String(normalized || "").replace(/\\/g, "/").replace(/^\/+/, "").split("/").filter(Boolean);
  if (!parts.length) return 0;
  const last = parts[parts.length - 1].toLowerCase();
  if (last === "manifest.md") return Math.max(0, parts.length - 1);
  return parts.length;
}

function getManifestTreeFolderDepth(normalized) {
  const path = String(normalized || "").replace(/\\/g, "/").replace(/^\/+/, "");
  if (isServiceNodePath(path)) {
    const kitFolder = getActiveAgentKitFolder();
    const rel = path.slice(kitFolder.length + 1).replace(/^\//, "");
    const segments = rel.split("/").filter(Boolean);
    if (!segments.length) return 0;
    const last = segments[segments.length - 1].toLowerCase();
    if (last === "manifest.md") return Math.max(0, segments.length - 1);
    return segments.length;
  }
  const containerFolder = getActiveAgentContainerFolder();
  if (containerFolder && path.startsWith(`${containerFolder}/`)) {
    const depth = countManifestFolderDepthUnderContainer(path, containerFolder);
    if (depth !== null) return depth;
  }
  return countManifestFolderDepthFromWorkspaceRoot(path);
}

const CONTENT_AWN_TYPE_NAMES = new Set([
  "awn.content.record",
  "awn.content.record-lite",
  "awn.content.record-csv",
  "awn.content.category",
  "awn.annotation.sidecar",
  "awn.content.base",
  "awn.record",
  "awn.record.category",
  "awn.sidecar"
]);

function isContentAwnTypeName(typeName) {
  const normalized = normalizeAwnTypeName(typeName);
  return Boolean(normalized && CONTENT_AWN_TYPE_NAMES.has(normalized));
}

function isAwnStorageSlotContentPath(normalized) {
  return /\/(?:awn-storage|storage)\/[^/]+\/.+/i.test(String(normalized || "").replace(/\\/g, "/"));
}

function inferContentTypeFromStoragePath(normalized, fileNameLower = "") {
  const lower = fileNameLower || String(normalized || "").split("/").filter(Boolean).pop()?.toLowerCase() || "";
  if (lower.endsWith(".sidecar.md")) return normalizeAwnTypeName("awn.annotation.sidecar");
  if (lower === "manifest.md") return normalizeAwnTypeName("awn.content.category");
  if (!/\.md$/i.test(lower) && !isPlainTextFlatStorageRecordPath(normalized)) {
    return normalizeAwnTypeName("awn.media.asset");
  }
  return normalizeAwnTypeName("awn.content.record");
}

function mergeClientTypeDefinition(typeName) {
  const normalized = normalizeAwnTypeName(typeName);
  if (!normalized || !awnTypesCache?.types) return null;

  const types = awnTypesCache.types;
  const cached = types[normalized];

  const mergeFields = (name, visited = new Set()) => {
    const key = normalizeAwnTypeName(name);
    if (!key || visited.has(key)) return {};
    visited.add(key);
    const def = types[key];
    if (!def) return {};
    let fields = def.extends ? mergeFields(def.extends, visited) : {};
    if (def.fields && typeof def.fields === "object") {
      for (const [fieldKey, patch] of Object.entries(def.fields)) {
        fields[fieldKey] = { ...(fields[fieldKey] || {}), ...patch };
      }
    }
    return fields;
  };

  const mergeForm = (name, visited = new Set()) => {
    const key = normalizeAwnTypeName(name);
    if (!key || visited.has(key)) return null;
    visited.add(key);
    const def = types[key];
    if (!def) return null;
    let form = def.extends ? mergeForm(def.extends, visited) : null;
    if (def.form && typeof def.form === "object") {
      form = { ...(form || {}), ...def.form };
    }
    return form;
  };

  const fields = mergeFields(normalized);
  const form = mergeForm(normalized);
  if (!cached && !Object.keys(fields).length) return null;

  return {
    ...(cached || {}),
    id: normalized,
    name: cached?.name || normalized,
    kind: cached?.kind || "type",
    form: form || cached?.form || null,
    fieldGroups: resolveTypeFieldGroups(normalized) || cached?.fieldGroups || null,
    fields: Object.keys(fields).length ? fields : cached?.fields ? { ...cached.fields } : {}
  };
}

function normalizeContentTypeCustomFields(customFields, inheritedFields = {}) {
  const inheritedKeys = new Set(Object.keys(inheritedFields || {}));
  const normalized = {};
  for (const [key, def] of Object.entries(customFields || {})) {
    let name = String(key || "").trim();
    if (!name) continue;
    if (name.startsWith("awn-") && !inheritedKeys.has(name)) {
      const plain = name.slice(4);
      if (plain && !inheritedKeys.has(plain)) name = plain;
    }
    if (!Object.prototype.hasOwnProperty.call(normalized, name)) normalized[name] = def;
  }
  return normalized;
}

function buildContentTypeDef(resolvedType, target, cache) {
  const canonicalTypeDef = mergeClientTypeDefinition(resolvedType);
  const inheritedFields = canonicalTypeDef?.fields || {};
  const customFields = cache
    ? normalizeContentTypeCustomFields(getTopicSchemaCustomFieldsForTarget(target, cache), inheritedFields)
    : {};
  let fieldGroups =
    resolveTypeFieldGroups(resolvedType) || canonicalTypeDef?.fieldGroups || null;
  if (cache?.isAwnDatabaseSchema) {
    const tabGroups = resolveAwnDatabaseSchemaFieldGroups(cache, target);
    if (tabGroups?.length) {
      const inheritedIds = new Set((fieldGroups || []).map((group) => String(group?.id || "")));
      const extraTabGroups = tabGroups.filter((group) => group?.id && !inheritedIds.has(String(group.id)));
      fieldGroups = [...(fieldGroups || []), ...extraTabGroups];
    }
  }

  if (canonicalTypeDef?.fields) {
    return {
      name: resolvedType,
      kind: canonicalTypeDef.kind || "type",
      fields: { ...inheritedFields, ...customFields },
      form: canonicalTypeDef.form,
      fieldGroups
    };
  }

  const merged = cache ? resolveTopicSchemaMergedType(target, cache) : null;
  if (merged?.fields && Object.keys(merged.fields).length) {
    return {
      name: merged.name || resolvedType,
      kind: merged.kind || "type",
      fields: merged.fields,
      form: merged.form || canonicalTypeDef?.form,
      fieldGroups: fieldGroups || merged.fieldGroups
    };
  }

  if (!canonicalTypeDef) return null;
  return { name: resolvedType, ...canonicalTypeDef, fieldGroups };
}

function resolveAwnDatabaseSchemaFieldGroups(cache, target) {
  const tabs = cache?.awnSchema?.[target]?.tabs;
  if (tabs && typeof tabs === "object" && Object.keys(tabs).length) {
    return Object.entries(tabs)
      .map(([id, def]) => ({
        id: String(id),
        name: String(def?.title || def?.name || id).trim() || id,
        collapsed: Boolean(def?.collapsed),
        sort: Number(def?.sort) || 0
      }))
      .sort((left, right) => left.sort - right.sort || left.name.localeCompare(right.name, "ru"))
      .map(({ id, name, collapsed }) => ({ id, name, collapsed }));
  }
  return null;
}

function inferAwnTypeFromRelPath(relPath, options = {}) {
  const normalized = String(relPath || "").replace(/\\/g, "/").replace(/^\/+/, "");
  if (!normalized) return "awn.file";
  const fileName = normalized.split("/").filter(Boolean).pop() || "";
  const lower = fileName.toLowerCase();

  if (lower.endsWith(".sidecar.md")) return normalizeAwnTypeName("awn.annotation.sidecar");
  if (isMediaCategoryContentPath(normalized)) return normalizeAwnTypeName("awn.content.category");
  if (isRecordCategoryContentPath(normalized)) return normalizeAwnTypeName("awn.content.category");
  if (isSectionReadmePath(normalized) && /\/media\//i.test(normalized)) {
    return normalizeAwnTypeName("awn.content.category");
  }
  if (isSectionReadmePath(normalized) && /\/content\//i.test(normalized)) {
    return normalizeAwnTypeName("awn.content.category");
  }

  if (
    isAwnStorageSlotContentPath(normalized) ||
    (options.contentMode === "external" && /\/(?:awn-storage|storage)\//i.test(normalized))
  ) {
    return inferContentTypeFromStoragePath(normalized, lower);
  }

  const flatStorageModes = ["inbox", "note", "references", "templates", "base", "notebooklm", "task-queue", "agent-task-queue"];
  const isFlatStorageContentFile =
    flatStorageModes.includes(options.contentMode) ||
    flatStorageModes.some((mode) => new RegExp(`/(?:awn-storage|storage)/${mode}/`, "i").test(normalized));
  if (isFlatStorageContentFile && !isNodeManifestPath(normalized)) {
    if (isSectionReadmePath(normalized)) return normalizeAwnTypeName("awn.content.category");
    if (/\.md$/i.test(lower)) return normalizeAwnTypeName("awn.content.record");
    if (isPlainTextFlatStorageRecordPath(normalized)) return normalizeAwnTypeName("awn.content.record");
    return normalizeAwnTypeName("awn.media.asset");
  }

  const isStorageContentFile =
    options.contentMode === "external" ||
    /\/(?:awn-storage|storage)\/(?:main|memory|content)\//i.test(normalized);
  if (isStorageContentFile && !isNodeManifestPath(normalized)) {
    return normalizeAwnTypeName("awn.content.record");
  }

  if (/^(?:awn-databases|awn-data)\/.+\/awn-storage\/data\//i.test(normalized)) {
    const declared = getDeclaredManifestTreeType(normalized);
    if (declared) return normalizeAwnTypeName(declared);
    if (/\/manifest\.md$/i.test(normalized)) return normalizeAwnTypeName("awn.content.category");
    return normalizeAwnTypeName("awn.content.record");
  }

  if (/^(?:awn-databases|awn-data)\/.+\/manifest\.md$/i.test(normalized)) {
    const declared = getDeclaredManifestTreeType(normalized);
    if (declared) return normalizeAwnTypeName(declared);
    const fromForm = getPropsEntryValueByKey(propsFormEntries, "awn-type");
    if (fromForm) return normalizeAwnTypeName(fromForm);
    const storeRel = resolveAwnDataStoreRelFromManifestPath(normalized);
    const store =
      findAwnDataStoreInPayload(menuAwnDataStoresLastPayload, storeRel) ||
      (String(awnDataViewStoreCache?.relPath || "")
        .replace(/\\/g, "/")
        .replace(/^\/+|\/+$/g, "") === storeRel
        ? awnDataViewStoreCache
        : null);
    const kind = String(store?.kind || "").trim().toLowerCase();
    if (kind === "group") return normalizeAwnTypeName("awn.database.group");
    if (kind === "single") return normalizeAwnTypeName("awn.database.single");
    if (kind === "collection") return normalizeAwnTypeName("awn.database.collection");
    return normalizeAwnTypeName("awn.database.collection");
  }

  if (isNodeManifestPath(normalized)) {
    if (options.isAgentRoot || isAgentRootIndexPath(normalized)) return normalizeAwnTypeName("awn.hub.topic.ws");
    if (options.isContainerRoot || isAgentContainerRootIndexPath(normalized)) {
      return normalizeAwnTypeName("awn.hub.topic.area");
    }
    if (options.isSharedRoot || isAgentSharedRootIndexPath(normalized)) {
      return normalizeAwnTypeName("awn.hub.topic.area");
    }
    if (isAgentSystemRootIndexPath(normalized)) return normalizeAwnTypeName("awn.hub.topic.area");
    if (isSystemReferenceManifestPath(normalized)) {
      return /\/(?:awn-)?taxonomies\/[^/]+\/manifest\.md$/i.test(normalized) ||
        /\/catalog\/[^/]+\/manifest\.md$/i.test(normalized)
        ? "catalog"
        : "service-doc";
    }

    const declared = getDeclaredManifestTreeType(normalized);
    if (declared === "topic") return normalizeAwnTypeName("awn.hub.topic");
    if (declared === "area") return normalizeAwnTypeName("awn.hub.topic.area");

    if (isTopicManifestPath(normalized)) return normalizeAwnTypeName("awn.hub.topic");
    if (isAreaNodePath(normalized)) return normalizeAwnTypeName("awn.hub.topic.area");
    const containerFolder = options.containerFolder || getActiveAgentContainerFolder();
    const folderDepth = countManifestFolderDepthUnderContainer(normalized, containerFolder);
    if (folderDepth !== null) {
      return folderDepth >= 2
        ? normalizeAwnTypeName("awn.hub.topic")
        : normalizeAwnTypeName("awn.hub.topic.area");
    }
    return countManifestFolderDepthFromWorkspaceRoot(normalized) >= 2
      ? normalizeAwnTypeName("awn.hub.topic")
      : normalizeAwnTypeName("awn.hub.topic.area");
  }

  return normalizeAwnTypeName("awn.content.record");
}

function resolveAwnTypeForContext(nodePath = activePath) {
  const manifestPath = String(getResolvedNodePath(nodePath) || "").replace(/\\/g, "/");
  const propsTarget = String(getPropertiesApiPath() || manifestPath).replace(/\\/g, "/");
  const typeOptions = {
    contentMode: activeContentMode,
    containerFolder: getActiveAgentContainerFolder(),
    isAgentRoot: isAgentRootIndexPath(manifestPath),
    isContainerRoot: isAgentContainerRootIndexPath(manifestPath),
    isSharedRoot: isAgentSharedRootIndexPath(manifestPath)
  };

  if (propsTarget && propsTarget !== manifestPath) {
    return inferAwnTypeFromRelPath(propsTarget, typeOptions);
  }

  return inferAwnTypeFromRelPath(manifestPath, typeOptions);
}

/** Не подниматься к awn.base за группами — у content свой набор секций формы. */
const DOMAIN_FIELD_GROUP_BOUNDARY_TYPES = new Set(["awn.content.base"]);

function mergeResolvedTypeFieldGroups(groupLists) {
  const byId = new Map();
  const order = [];
  for (const groups of groupLists) {
    if (!Array.isArray(groups)) continue;
    for (const group of groups) {
      if (!group?.id) continue;
      const id = String(group.id);
      if (!byId.has(id)) order.push(id);
      byId.set(id, {
        id,
        name: group.name || group.title || byId.get(id)?.name || id,
        description: group.description || byId.get(id)?.description || "",
        collapsed:
          group.collapsed !== undefined ? Boolean(group.collapsed) : Boolean(byId.get(id)?.collapsed),
        subgroups: Array.isArray(group.subgroups)
          ? group.subgroups
          : Array.isArray(byId.get(id)?.subgroups)
            ? byId.get(id).subgroups
            : []
      });
    }
  }
  return order.length ? order.map((id) => byId.get(id)) : null;
}

function resolveTypeFieldGroups(typeName) {
  const chain = [];
  let current = normalizeAwnTypeName(typeName);
  const visited = new Set();
  while (current && !visited.has(current)) {
    visited.add(current);
    chain.push(current);
    if (DOMAIN_FIELD_GROUP_BOUNDARY_TYPES.has(current)) break;
    const def = awnTypesCache?.types?.[current];
    current = def?.extends ? normalizeAwnTypeName(def.extends) : null;
  }

  const groupLists = [];
  for (let index = chain.length - 1; index >= 0; index -= 1) {
    const def = awnTypesCache?.types?.[chain[index]];
    if (Array.isArray(def?.fieldGroups) && def.fieldGroups.length) {
      groupLists.push(def.fieldGroups);
    }
  }
  return mergeResolvedTypeFieldGroups(groupLists);
}

function getActiveAwnTypeDef(typeName = null) {
  let resolvedType = normalizeAwnTypeName(typeName || resolveAwnTypeForContext());

  // When no specific typeName is requested, prefer the declared awn-type from frontmatter
  // (path inference returns generic "awn.topic", but frontmatter may say "awn.hub.topic.agent")
  if (!typeName) {
    if (activeContentMode === NODE_ENTRY_OVERVIEW_MODE && activeEntryOverviewContext?.entryKind) {
      resolvedType =
        activeEntryOverviewContext.entryKind === "awn.media.asset"
          ? normalizeAwnTypeName("awn.annotation.sidecar")
          : normalizeAwnTypeName(activeEntryOverviewContext.entryKind);
    } else if (isMediaSidecarEditing()) {
      resolvedType = normalizeAwnTypeName("awn.annotation.sidecar");
    } else {
      const declared = getPropsEntryValueByKey(propsFormEntries, "awn-type");
      if (declared) {
        const normalized = normalizeAwnTypeName(declared);
        if (normalized) resolvedType = normalized;
      }
    }
  }

  const overviewContext =
    activeContentMode === NODE_ENTRY_OVERVIEW_MODE ? activeEntryOverviewContext : null;
  const cache = resolveActivePropsSchemaCache(overviewContext);
  const slotKey = resolveSchemaSlotKeyForContext();
  const target = typeName
    ? resolveAwnSchemaTargetForType(resolvedType, slotKey)
    : activeContentMode === NODE_ENTRY_OVERVIEW_MODE
      ? resolveOverviewSchemaTargetForContext(overviewContext)
      : resolveAwnSchemaTargetForContext();

  return buildContentTypeDef(resolvedType, target, cache);
}

function getActiveSettingsTypeDef(overviewContext = null) {
  const context =
    overviewContext ??
    (activeContentMode === NODE_ENTRY_OVERVIEW_MODE ? activeEntryOverviewContext : null);
  const cache = resolveActiveOverviewSchemaCache(context);
  const merged = cache ? resolveTopicSchemaMergedType("settings", cache) : null;
  const settingsTypeName = normalizeAwnTypeName("awn.settings");
  if (merged?.fields) {
    const baseTypeDef = awnTypesCache?.types?.[settingsTypeName];
    return {
      name: merged.name || settingsTypeName,
      kind: merged.kind || baseTypeDef?.kind || "type",
      fields: merged.fields
    };
  }
  const baseTypeDef = awnTypesCache?.types?.[settingsTypeName];
  if (!baseTypeDef) return null;
  return { name: settingsTypeName, ...baseTypeDef };
}

// Returns fields defined in typeId that are NOT inherited from its parent type.
// Used to show only the "own" custom fields in the node overview form.
function getTypeOwnFields(typeId) {
  if (!typeId || !awnTypesCache?.types) return {};
  const typeDef = awnTypesCache.types[typeId];
  if (!typeDef?.fields) return {};

  const parentId = typeDef.extends;
  const parentFields = parentId && awnTypesCache.types[parentId]?.fields ? awnTypesCache.types[parentId].fields : {};

  const own = {};
  for (const [key, fieldDef] of Object.entries(typeDef.fields)) {
    if (!parentFields[key]) own[key] = fieldDef;
  }
  return own;
}

function getExternalRecordTypeDef() {
  const slotKey = getDataStorageSlotForMode("external")?.key || "memory";
  const target = resolveAwnSchemaTargetForType("awn.content.record", slotKey);
  const manifestPath = getExternalListSchemaManifestPath();
  const cache = manifestPath ? getTopicSchemaCache(manifestPath) : null;
  return buildContentTypeDef("awn.content.record", target, cache);
}

function getExternalTableSchemaColumns() {
  const typeDef = getExternalRecordTypeDef();
  const standardKeys = getStandardPropsFieldKeys();
  if (!typeDef?.fields) {
    return standardKeys
      .filter((key) => !HIDDEN_PROPS_FIELD_KEYS.has(key))
      .map((key) => ({
        key,
        label: getPropsFieldMeta(key).label,
        fieldDef: null,
        typeId: null
      }));
  }

  const columns = [];
  const seen = new Set();
  const orderedKeys = [
    ...standardKeys,
    ...getTypeSchemaFieldKeys(typeDef).filter((key) => !standardKeys.includes(key))
  ];

  for (const key of orderedKeys) {
    if (seen.has(key) || HIDDEN_PROPS_FIELD_KEYS.has(key)) continue;
    const fieldDef = typeDef.fields[key];
    if (!fieldDef && !standardKeys.includes(key)) continue;
    seen.add(key);
    columns.push({
      key,
      label: fieldDef?.title || getPropsFieldMeta(key).label || key,
      fieldDef: fieldDef || null,
      typeId: fieldDef ? resolveFieldTypeId(fieldDef.type || "awn.field.string") : null
    });
  }

  return columns;
}

function getExternalListSortOptions() {
  const seen = new Set(["path", EXTERNAL_TABLE_FILE_COLUMN_KEY]);
  const options = [
    { key: "path", label: "Путь" },
    { key: EXTERNAL_TABLE_FILE_COLUMN_KEY, label: "Название" }
  ];
  for (const column of getExternalTableSchemaColumns()) {
    if (seen.has(column.key) || column.key === "awn-preview") continue;
    seen.add(column.key);
    options.push({ key: column.key, label: column.label });
  }
  return options.length > 1 ? options : EXTERNAL_LIST_SORT_OPTIONS;
}

