function isLegacyAttachmentsWithPreviewType(fieldDef) {
  const raw = String(fieldDef?.type || "").trim();
  return /awn\.field\.file\.(one|many)\.with-preview$/i.test(raw);
}

function isPropsAttachmentsField(key, fieldDef = getPropsFieldDef(key)) {
  if (normalizePropsKey(key) === "awn-attachments") return true;
  if (!fieldDef) return false;
  if (String(fieldDef.widget || "").trim() === "attachments") return true;
  if (isLegacyAttachmentsWithPreviewType(fieldDef)) return true;
  const typeId = normalizeCanonicalFieldTypeId(fieldDef.type || "");
  const scope = String(fieldDef.scope || "").trim();
  return scope === "attachments" && fieldTypeIs(typeId, "file.many");
}

function isPropsPreviewWidgetField(key, fieldDef = getPropsFieldDef(key)) {
  return resolvePropsFieldWidget(key, fieldDef) === "preview";
}

function isPropsMaterialsWidgetField(key, fieldDef = getPropsFieldDef(key)) {
  return resolvePropsFieldWidget(key, fieldDef) === "materials";
}

function isPropsAsideDedicatedBlockField(key, fieldDef = getPropsFieldDef(key)) {
  if (!isPropsAsideHeroField(key, fieldDef)) return false;
  const widget = resolvePropsFieldWidget(key, fieldDef);
  return widget === "preview" || widget === "attachments" || widget === "materials" || widget === "url";
}

function isAttachmentsFieldStorageMany(fieldDef = null) {
  if (!fieldDef) return true;
  if (isLegacyAttachmentsWithPreviewType(fieldDef)) {
    return /awn\.field\.file\.many\.with-preview$/i.test(String(fieldDef.type || "").trim());
  }
  const typeId = normalizeCanonicalFieldTypeId(fieldDef.type || "");
  if (fieldTypeIs(typeId, "file.one")) return false;
  return isFieldTypeMany(typeId) || fieldDef.storage === "array";
}

function findPropsAsideHeroFieldEntry(
  widget,
  { defaultKind = "string", defaultValue = "", fallbackKey = "" } = {}
) {
  const typeDef = getActiveAwnTypeDef();
  const fields = typeDef?.fields || {};
  const keys = Object.keys(fields).sort((a, b) => comparePropsFieldSchemaOrder(a, b, fields));
  for (const key of keys) {
    const def = fields[key];
    if (!isPropsAsideHeroField(key, def)) continue;
    if (resolvePropsFieldWidget(key, def) !== widget) continue;
    const index = propsFormEntries.findIndex((entry) => normalizePropsKey(entry.key) === key);
    if (index >= 0) return { entry: propsFormEntries[index], index, key };
    const kind =
      widget === "attachments"
        ? isAttachmentsFieldStorageMany(def)
          ? "array"
          : "string"
        : widget === "materials"
          ? "bool"
          : defaultKind;
    const value =
      widget === "attachments"
        ? isAttachmentsFieldStorageMany(def)
          ? []
          : ""
        : widget === "materials"
          ? false
          : defaultValue;
    return { entry: { key, kind, value }, index: -1, key };
  }
  if (fallbackKey && isPropsAsideHeroField(fallbackKey)) {
    const def = getPropsFieldDef(fallbackKey);
    if (def && resolvePropsFieldWidget(fallbackKey, def) === widget) {
      const index = propsFormEntries.findIndex((entry) => normalizePropsKey(entry.key) === fallbackKey);
      if (index >= 0) return { entry: propsFormEntries[index], index, key: fallbackKey };
      return {
        entry: {
          key: fallbackKey,
          kind: widget === "attachments" ? "array" : widget === "materials" ? "bool" : defaultKind,
          value: widget === "attachments" ? [] : widget === "materials" ? false : defaultValue
        },
        index: -1,
        key: fallbackKey
      };
    }
  }
  return null;
}

function isBooleanFieldTypeId(typeId) {
  const normalized = normalizeCanonicalFieldTypeId(typeId);
  return normalized === "awn.boolean";
}

function isEnumFieldTypeId(typeId) {
  const api = awnEnumOptionsApi();
  if (typeof api.isEnumFieldTypeId === "function") return api.isEnumFieldTypeId(typeId);
  return fieldTypeIs(typeId, "choice.one");
}

function isArrayFieldTypeId(typeId) {
  const api = awnEnumOptionsApi();
  if (typeof api.isArrayFieldTypeId === "function") return api.isArrayFieldTypeId(typeId);
  return fieldTypeIs(typeId, "choice.many") || fieldTypeIs(typeId, "array");
}

function resolveFieldWidget(fieldDef, registryEntry = null) {
  const api = awnEnumOptionsApi();
  if (typeof api.resolveFieldWidget === "function") {
    return api.resolveFieldWidget(fieldDef, registryEntry);
  }
  return String(fieldDef?.widget || registryEntry?.widget || "").trim();
}

function getFieldDefDisplayName(fieldDef, fallbackKey = "") {
  const api = awnEnumOptionsApi();
  if (typeof api.getFieldDefDisplayName === "function") {
    return api.getFieldDefDisplayName(fieldDef, fallbackKey);
  }
  return String(fieldDef?.name ?? fieldDef?.title ?? fallbackKey ?? "").trim();
}

function getFieldTypeOptionLabel(typeId, name = "") {
  const id = resolveFieldTypeId(typeId);
  const registry = awnTypesCache?.fieldRegistry || {};
  const canonicalId = normalizeCanonicalFieldTypeId(id);
  const entry =
    registry[id] ||
    registry[canonicalId] ||
    registry[`awn.field.${canonicalId.replace(/^awn\./, "")}`];
  const rawLabel = String(name || entry?.name || entry?.description || id).trim();
  const label = rawLabel === id && entry?.description ? entry.description : rawLabel;
  const icon = entry?.icon || entry?.emoji || resolveFieldLabelIcon(id);
  return icon ? `${icon} ${label}` : label;
}

function isAwnEnumFieldType(typeId) {
  return isEnumFieldTypeId(typeId);
}

function getFieldDefSchemaProperties() {
  return awnTypesCache?.fieldDefSchema?.properties || {};
}

function getFieldTypeSettingsKeys(typeId) {
  const registry = awnTypesCache?.fieldRegistry || {};
  const entry = registry[resolveFieldTypeId(typeId)];
  if (Array.isArray(entry?.settings) && entry.settings.length) {
    return entry.settings.filter(
      (key) => key !== "type" && key !== "title" && key !== "name" && key !== "items"
    );
  }
  if (isChoiceOneFieldTypeId(typeId)) {
    return ["description", "hint", "required", "locked", "widget", "default", "enum"];
  }
  if (isChoiceManyFieldTypeId(typeId)) {
    return ["description", "hint", "required", "locked", "widget", "default", "enum"];
  }
  if (resolveFieldTypeId(typeId) === "awn.null") {
    return ["description", "hint", "locked"];
  }
  return ["description", "hint", "required", "locked", "format", "default"];
}

function getFieldTypeSettingPropDef(propKey) {
  return getFieldDefSchemaProperties()[propKey] || { title: propKey };
}

function isFieldDefBooleanSetting(propKey, propDef = getFieldTypeSettingPropDef(propKey)) {
  const typeId = resolveFieldTypeId(propDef?.type || "");
  return propKey === "required" || propKey === "locked" || typeId === "awn.boolean";
}

function formatFieldDefSettingValue(propKey, value) {
  const api = awnEnumOptionsApi();
  if (propKey === "enum" || propKey === "items") {
    if (propKey === "enum" && Array.isArray(value)) {
      if (typeof api.formatEnumOptionsCompactText === "function") {
        return api.formatEnumOptionsCompactText(value);
      }
    }
    return Array.isArray(value) ? value.join(", ") : String(value || "");
  }
  if (isFieldDefBooleanSetting(propKey)) {
    return value ? "true" : "false";
  }
  if (value === null || value === undefined) return "";
  return String(value);
}

function parseFieldDefSettingValue(propKey, propDef, rawValue) {
  const api = awnEnumOptionsApi();
  if (propKey === "enum") {
    if (Array.isArray(rawValue)) return rawValue;
    if (typeof api.parseEnumOptionsFromCompactText === "function") {
      return api.parseEnumOptionsFromCompactText(rawValue);
    }
    return String(rawValue || "")
      .split(",")
      .map((item) => item.trim())
      .filter(Boolean);
  }
  if (propKey === "items") {
    const next = String(rawValue || "").trim();
    return next ? resolveFieldTypeId(next) : "";
  }
  if (propKey === "sort") {
    const next = String(rawValue ?? "").trim();
    if (!next) return "";
    const num = Number(next);
    return Number.isFinite(num) ? num : "";
  }
  if (isFieldDefBooleanSetting(propKey, propDef)) {
    if (typeof rawValue === "boolean") return rawValue;
    const normalized = String(rawValue || "").trim().toLowerCase();
    return normalized === "1" || normalized === "true" || normalized === "yes" || normalized === "on";
  }
  return String(rawValue ?? "").trim();
}

function shouldPersistFieldDefSetting(propKey, value, fieldDef = null) {
  if (propKey === "widget") {
    const widget = String(value ?? "").trim();
    if (!widget || !fieldDef) return Boolean(widget);
    const typeId = resolveFieldTypeId(fieldDef.type || "");
    const api = awnEnumOptionsApi();
    const defaultWidget = api.DEFAULT_FIELD_WIDGET?.[typeId] || "";
    return Boolean(widget && widget !== defaultWidget);
  }
  if (propKey === "enum") {
    const api = awnEnumOptionsApi();
    if (Array.isArray(value) && typeof api.normalizeEnumOptions === "function") {
      return api.normalizeEnumOptions(value).length > 0;
    }
    return Array.isArray(value) && value.length > 0;
  }
  if (propKey === "items") return Boolean(String(value || "").trim());
  if (propKey === "sort") return value !== "" && value !== null && value !== undefined;
  if (isFieldDefBooleanSetting(propKey)) return value === true;
  return String(value ?? "").trim().length > 0;
}

function createTopicSchemaEnumOptionsControl(fieldDef, schemaKey) {
  const wrap = document.createElement("div");
  wrap.className = "topic-schema-enum-options";
  wrap.dataset.schemaKey = schemaKey;
  wrap.dataset.schemaField = "enum";

  const api = awnEnumOptionsApi();
  let optionRows =
    typeof api.normalizeEnumOptions === "function"
      ? api.normalizeEnumOptions(fieldDef?.enum || [])
      : Array.isArray(fieldDef?.enum)
        ? [...fieldDef.enum]
        : [];

  const readRowsFromDom = () => {
    const next = [];
    wrap.querySelectorAll(".topic-schema-enum-options-row").forEach((row) => {
      const key = String(row.querySelector('[data-enum-part="key"]')?.value || "").trim();
      const name = String(row.querySelector('[data-enum-part="name"]')?.value || "").trim();
      if (!key && !name) return;
      next.push({ key: key || name, name: name || key });
    });
    return next;
  };

  wrap.readEnumOptions = readRowsFromDom;

  const renderRows = () => {
    wrap.replaceChildren();
    const hint = document.createElement("p");
    hint.className = "topic-schema-enum-options-hint";
    hint.textContent = "key — значение в YAML, name — подпись в UI";
    wrap.appendChild(hint);

    const list = document.createElement("div");
    list.className = "topic-schema-enum-options-list";
    const rows = optionRows.length ? optionRows : [{ key: "", name: "" }];

    for (const option of rows) {
      const row = document.createElement("div");
      row.className = "topic-schema-enum-options-row";

      const keyInput = document.createElement("input");
      keyInput.type = "text";
      keyInput.className = "topic-schema-inline-input";
      keyInput.placeholder = "key";
      keyInput.value = option.key || "";
      keyInput.dataset.enumPart = "key";
      keyInput.spellcheck = false;

      const nameInput = document.createElement("input");
      nameInput.type = "text";
      nameInput.className = "topic-schema-inline-input";
      nameInput.placeholder = "name";
      nameInput.value = option.name || "";
      nameInput.dataset.enumPart = "name";

      row.append(keyInput, nameInput);
      list.appendChild(row);
    }

    const addBtn = document.createElement("button");
    addBtn.type = "button";
    addBtn.className = "topic-schema-enum-options-add";
    addBtn.textContent = "+ Вариант";
    addBtn.addEventListener("click", () => {
      optionRows = readRowsFromDom();
      optionRows.push({ key: "", name: "" });
      renderRows();
      const row = wrap.closest(".topic-schema-field-row");
      if (row) readTopicSchemaFieldFromRow(row);
    });

    wrap.append(list, addBtn);
  };

  renderRows();
  return wrap;
}

function createTopicSchemaSettingControl(propKey, propDef, fieldDef, schemaKey) {
  const label = document.createElement("label");
  label.className = "topic-schema-setting";
  label.dataset.schemaField = propKey;

  const caption = document.createElement("span");
  caption.className = "topic-schema-setting-label";
  caption.textContent = propDef?.title || propKey;
  if (propDef?.description) caption.title = propDef.description;

  let control;
  if (isFieldDefBooleanSetting(propKey, propDef)) {
    control = document.createElement("input");
    control.type = "checkbox";
    control.checked = Boolean(fieldDef?.[propKey]);
  } else if (propDef?.type === "awn.text" || propKey === "description") {
    control = document.createElement("textarea");
    control.rows = 2;
    control.value = formatFieldDefSettingValue(propKey, fieldDef?.[propKey]);
  } else if (propKey === "items") {
    control = document.createElement("select");
    populateFieldTypeSelect(control, getTopicSchemaRegistryEntries(), fieldDef?.items || "awn.field.string");
  } else if (propKey === "enum") {
    control = createTopicSchemaEnumOptionsControl(fieldDef, schemaKey);
    delete label.dataset.schemaField;
    label.append(caption, control);
    return label;
  } else if (propKey === "placement") {
    control = document.createElement("select");
    const placementOptions = [
      ["editor-body", "Над текстом (editor-body)"],
      ["aside-body", "Панель свойств (aside-body)"],
      ["aside-hero", "Панель · медиа (aside-hero)"],
      ["title-bar", "Шапка (title-bar)"],
      ["hidden", "Скрыто (hidden)"]
    ];
    for (const [value, text] of placementOptions) {
      const option = document.createElement("option");
      option.value = value;
      option.textContent = text;
      control.append(option);
    }
    control.value = String(fieldDef?.placement || "editor-body");
  } else if (propKey === "group") {
    const listId = `topic-schema-group-list-${schemaKey}`;
    control = document.createElement("input");
    control.type = "text";
    control.className = "topic-schema-inline-input";
    control.placeholder = "content или Строки, Текст, Медиа…";
    const groupValue = String(fieldDef?.group || "").trim();
    control.value = groupValue === "content" ? "" : groupValue;
    control.setAttribute("list", listId);
    const cache = getTopicSchemaCache();
    const activeTarget = normalizeTopicSchemaActiveTarget(topicSchemaActiveTarget);
    const fields = cache?.awnSchema?.[activeTarget]?.fields || {};
    const datalist = document.createElement("datalist");
    datalist.id = listId;
    for (const name of collectSchemaEditorGroupNames(fields, activeTarget)) {
      const option = document.createElement("option");
      option.value = name;
      datalist.append(option);
    }
    label.append(caption, control, datalist);
    control.dataset.schemaKey = schemaKey;
    control.dataset.schemaField = propKey;
    return label;
  } else if (propKey === "sort") {
    control = document.createElement("input");
    control.type = "number";
    control.step = "1";
    control.value = String(fieldDef?.sort ?? "");
    control.placeholder = "0";
  } else if (propKey === "widget") {
    control = document.createElement("select");
    const typeId = resolveFieldTypeId(fieldDef?.type || "");
    const registry = awnTypesCache?.fieldRegistry || {};
    const widgetOptions = isChoiceOneFieldTypeId(typeId)
      ? [
          ["select", "Select (выпадающий список)"],
          ["radio", "Radio (кнопки)"]
        ]
      : isChoiceManyFieldTypeId(typeId)
        ? [
            ["checkbox", "Checkbox (флажки)"],
            ["select-multiple", "Select multiple (множественный выбор)"]
          ]
        : [];
    for (const [value, text] of widgetOptions) {
      const option = document.createElement("option");
      option.value = value;
      option.textContent = text;
      control.append(option);
    }
    control.value = resolveFieldWidget(fieldDef, registry[typeId]);
  } else if (propKey === "scope") {
    control = document.createElement("select");
    const scopeOptions = [
      ["topic", "Текущий топик"],
      ["area", "Текущая область"],
      ["system", "Вся система"]
    ];
    const currentScope = migrateLegacyFileScope(fieldDef?.scope);
    for (const [value, label] of scopeOptions) {
      const option = document.createElement("option");
      option.value = value;
      option.textContent = label;
      control.append(option);
    }
    control.value = currentScope;
  } else if (propKey === "accept") {
    control = document.createElement("input");
    control.type = "text";
    control.value = formatFieldDefSettingValue(propKey, fieldDef?.[propKey]);
    control.placeholder = ".pdf, .png, image/*";
  } else {
    control = document.createElement("input");
    control.type = "text";
    control.value = formatFieldDefSettingValue(propKey, fieldDef?.[propKey]);
    if (propDef?.description) control.placeholder = propDef.description;
  }

  control.dataset.schemaKey = schemaKey;
  control.dataset.schemaField = propKey;
  label.append(caption, control);
  return label;
}

function appendTopicSchemaFieldSettings(host, fieldDef, schemaKey, { expanded = false } = {}) {
  const settingsHost = document.createElement("div");
  settingsHost.className = "topic-schema-field-settings";
  const settingKeys = getFieldTypeSettingsKeys(fieldDef?.type);
  const layoutKeys = getTopicSchemaLayoutSettingKeys();
  if (!settingKeys.length && !layoutKeys.length) {
    settingsHost.classList.add("is-empty");
    host.appendChild(settingsHost);
    return settingsHost;
  }

  if (!expanded) settingsHost.classList.add("is-collapsed");

  for (const propKey of settingKeys) {
    settingsHost.appendChild(
      createTopicSchemaSettingControl(
        propKey,
        getFieldTypeSettingPropDef(propKey),
        fieldDef,
        schemaKey
      )
    );
  }
  for (const propKey of layoutKeys) {
    settingsHost.appendChild(
      createTopicSchemaSettingControl(
        propKey,
        {
          title:
            propKey === "placement"
              ? "Зона UI"
              : propKey === "group"
                ? "Группа"
                : "Порядок",
          description:
            propKey === "placement"
              ? "Где показывать поле в редакторе"
              : propKey === "group"
                ? "Раздел (group) — заголовок-разделитель между полями в editor-body"
                : "Сортировка внутри зоны и группы"
        },
        fieldDef,
        schemaKey
      )
    );
  }
  host.appendChild(settingsHost);
  return settingsHost;
}

function getAwnFieldTypeLabel(typeId) {
  const registry = awnTypesCache?.fieldRegistry || {};
  const entry = registry[resolveFieldTypeId(typeId)];
  return entry?.name || entry?.label || typeId || "—";
}

function getTypeSchemaFieldKeys(typeDef) {
  if (!typeDef?.fields) return [];
  return Object.keys(typeDef.fields);
}

function getPropsFieldDef(key) {
  const normalized = normalizePropsKey(key);
  if (!normalized) return null;
  const typeDef = getActiveAwnTypeDef();
  const fromActive = typeDef?.fields?.[normalized];
  if (fromActive) return fromActive;

  const resolvedType = normalizeAwnTypeName(
    getPropsEntryValueByKey(propsFormEntries, "awn-type") || resolveAwnTypeForContext()
  );
  const cachedType = resolvedType ? awnTypesCache?.types?.[resolvedType] : null;
  const fromCache = cachedType?.fields?.[normalized];
  if (fromCache) return fromCache;

  return findPropsFieldDefInTopicSchemaTargets(normalized);
}

function findPropsFieldDefInTopicSchemaTargets(key, cache = resolveActiveOverviewSchemaCache()) {
  const normalized = normalizePropsKey(key);
  if (!normalized || !cache) return null;

  const overviewContext =
    activeContentMode === NODE_ENTRY_OVERVIEW_MODE ? activeEntryOverviewContext : null;
  const targets = getOverviewSchemaLookupTargets(getResolvedNodePath(activePath), overviewContext);

  for (const target of targets) {
    const fromCustom = cache.awnSchema?.[target]?.fields?.[normalized];
    if (fromCustom) return fromCustom;
    const fromSection = cache.sectionAwnSchema?.[target]?.fields?.[normalized];
    if (fromSection) return fromSection;
    const merged = resolveTopicSchemaMergedType(target, cache);
    if (merged?.fields?.[normalized]) return merged.fields[normalized];
  }
  return null;
}

function isPropsFieldDefinedInActiveSchema(key, options = {}) {
  if (options.fieldDef) return true;
  const overviewContext =
    options.context ??
    (activeContentMode === NODE_ENTRY_OVERVIEW_MODE ? activeEntryOverviewContext : null);
  const cache = resolveActiveOverviewSchemaCache(overviewContext);
  const normalized = normalizePropsKey(key);
  if (!normalized) return false;
  if (findPropsFieldDefInTopicSchemaTargets(normalized, cache)) return true;
  return Boolean(getPropsFieldDef(normalized));
}

function resolvePropsFieldDefForOverview(key, entry = null, nodePath = getResolvedNodePath(activePath)) {
  if (entry?.fieldDef) return entry.fieldDef;

  const normalized = normalizePropsKey(key);
  if (!normalized) return null;

  const fromSchemaCache = getOverviewSchemaFieldDef(normalized, nodePath);
  if (fromSchemaCache) return fromSchemaCache;

  const cache = resolveActiveOverviewSchemaCache();
  if (cache) {
    const preferredTarget = resolveOverviewSchemaTargetForNode(nodePath);
    const preferred = resolveTopicSchemaMergedType(preferredTarget, cache)?.fields?.[normalized];
    if (preferred) return preferred;
    const fromTargets = findPropsFieldDefInTopicSchemaTargets(normalized, cache);
    if (fromTargets) return fromTargets;
  }

  return getPropsFieldDef(normalized);
}

function getPropsFieldOverviewLabel(key, entry = null, nodePath = getResolvedNodePath(activePath)) {
  const normalized = normalizePropsKey(key);
  if (!normalized) return { key: String(key || "").trim(), label: "" };

  const fieldDef = resolvePropsFieldDefForOverview(normalized, entry, nodePath);
  let label = "";
  if (fieldDef) {
    label = getFieldDefDisplayName(fieldDef, normalized);
  } else if (PROPS_FIELD_META[normalized]?.label) {
    label = PROPS_FIELD_META[normalized].label;
  } else {
    const meta = getPropsFieldMeta(normalized);
    if (meta?.label && meta.label !== normalized) label = meta.label;
  }

  if (label && label.trim().toLowerCase() === normalized.toLowerCase()) label = "";
  return { key: normalized, label: label.trim() };
}

function formatPropsOverviewEnumValue(rawValue, fieldDef) {
  if (!fieldDef) return null;
  const options = getEnumOptionsForField(fieldDef);
  if (!options.length) return null;

  const api = awnEnumOptionsApi();
  const raw = String(rawValue ?? "").trim();
  if (!raw) return null;

  const resolveOptionLabel = (storedKey) => {
    const normalizedKey = normalizeEnumDisplayValue(storedKey, options);
    for (const option of options) {
      const optionKey = typeof api.enumOptionKey === "function" ? api.enumOptionKey(option) : option;
      if (optionKey !== normalizedKey) continue;
      return typeof api.enumOptionName === "function" ? api.enumOptionName(option) : String(option);
    }
    return null;
  };

  if (Array.isArray(rawValue)) {
    const labels = rawValue.map((part) => resolveOptionLabel(part)).filter(Boolean);
    return labels.length ? labels.join(", ") : null;
  }

  return resolveOptionLabel(raw);
}

function isPropsFieldLocked(key, fieldDef = getPropsFieldDef(key)) {
  return Boolean(fieldDef?.locked);
}

function getPropsFieldMetaFromSchema(key) {
  const fieldDef = getPropsFieldDef(key);
  if (!fieldDef) return null;
  const typeId = resolveFieldTypeId(fieldDef.type || "awn.field.string");
  return {
    label: formatSchemaDisplayTitle(getFieldDefDisplayName(fieldDef, key), { typeId, key }),
    hint: fieldDef.hint || fieldDef.description || "",
    format: fieldDef.format || "",
    required: Boolean(fieldDef.required),
    locked: isPropsFieldLocked(key, fieldDef),
    typeId,
    enum: Array.isArray(fieldDef.enum) ? fieldDef.enum : null,
    fieldDef
  };
}

function fieldDefToEntryKind(fieldDef) {
  const typeId = normalizeCanonicalFieldTypeId(fieldDef?.type || "awn.field.string");
  if (hasStructuredObjectFieldProperties(fieldDef)) return "object";
  const registry = awnTypesCache?.fieldRegistry || {};
  const registryEntry =
    registry[fieldDef?.type || ""] ||
    registry[typeId] ||
    registry[`awn.field.${typeId.replace(/^awn\./, "")}`];
  if (registryEntry?.storage) return registryEntry.storage;
  if (registryEntry?.kind && registryEntry.kind !== "field") return registryEntry.kind;
  if (fieldTypeIs(typeId, "number")) return "number";
  if (isBooleanFieldTypeId(typeId)) return "bool";
  if (isArrayFieldTypeId(typeId)) return "array";
  if (typeId === "awn.null") return "null";
  return "string";
}

function fieldDefDefaultValue(fieldDef) {
  if (fieldDef?.default !== undefined) {
    const kind = fieldDefToEntryKind(fieldDef);
    if (kind === "array") {
      return Array.isArray(fieldDef.default) ? [...fieldDef.default] : [];
    }
    if (kind === "bool") {
      return Boolean(fieldDef.default);
    }
    if (kind === "number") {
      return Number(fieldDef.default) || 0;
    }
    if (kind === "null") {
      return null;
    }
    if (kind === "object") {
      return fieldDef.default && typeof fieldDef.default === "object" && !Array.isArray(fieldDef.default)
        ? { ...fieldDef.default }
        : {};
    }
    return coerceSettingsTextValue(fieldDef.default, "");
  }
  const kind = fieldDefToEntryKind(fieldDef);
  if (kind === "array") return [];
  if (kind === "bool") return false;
  if (kind === "null") return null;
  if (kind === "object") return {};
  return "";
}

const HIDDEN_PROPS_FIELD_KEYS = new Set(["title", "awn-owner"]);
const TITLE_BAR_HIDDEN_PROP_KEYS = new Set(["awn-name", "awn-description"]);

function isTitleBarHiddenPropKey(key) {
  return TITLE_BAR_HIDDEN_PROP_KEYS.has(normalizePropsKey(key));
}

function isPropsHiddenStorageKey(key) {
  const normalized = normalizePropsKey(key);
  return Boolean(normalized && (HIDDEN_PROPS_FIELD_KEYS.has(normalized) || isTitleBarHiddenPropKey(normalized)));
}

function stripTitleBarKeysFromVisibleEntries(entries) {
  return (entries || []).filter((entry) => !isTitleBarHiddenPropKey(entry?.key));
}

function shouldStorePropsFieldInVisibleEntries(key, fieldDef = getSchemaPropsFieldDef(key)) {
  if (isPropsHiddenStorageKey(key)) return false;
  if (!shouldIncludePropsFieldKey(key)) return false;
  if (isPropsFieldHiddenBySchema(key, fieldDef)) return false;
  const placement = getPropsFieldPlacement(key, fieldDef);
  return placement === "aside-body" || placement === PROPS_PLACEMENT_EDITOR_BODY;
}

function remapLegacyCustomPropEntriesForSchema(entries, typeDef) {
  const schemaFields = typeDef?.fields && typeof typeDef.fields === "object" ? typeDef.fields : {};
  const schemaKeys = new Set(Object.keys(schemaFields));
  if (!schemaKeys.size) return entries;

  const result = [];
  const migrated = new Map();

  for (const entry of normalizePropsEntries(entries)) {
    const key = normalizePropsKey(entry?.key);
    if (!key) {
      result.push(entry);
      continue;
    }
    if (key.startsWith("awn-") && !schemaKeys.has(key)) {
      const plain = key.slice(4);
      if (plain && schemaKeys.has(plain) && !isAwnFieldKey(plain)) {
        if (!migrated.has(plain)) migrated.set(plain, { ...entry, key: plain });
        continue;
      }
    }
    result.push(entry);
  }

  for (const [plain, entry] of migrated) {
    const index = result.findIndex((item) => normalizePropsKey(item?.key) === plain);
    if (index < 0) {
      result.push(entry);
      continue;
    }
    const existing = result[index];
    const existingValue = String(getPropsEntryDisplayValue(existing) ?? "").trim();
    const nextValue = String(getPropsEntryDisplayValue(entry) ?? "").trim();
    if (!existingValue && nextValue) result[index] = entry;
  }

  return result;
}

function migrateLegacyVisualizationPropsEntries(entries) {
  const list = normalizePropsEntries(entries);
  const byKey = new Map(list.map((entry) => [normalizePropsKey(entry?.key), entry]));
  if (byKey.has("awn-viz-mindmap")) return list;

  const legacySuffixes = ["enabled", "type", "color", "size", "layout-independent", "direction"];
  const hasLegacy = legacySuffixes.some((suffix) => byKey.has(`awn-mindmap-${suffix}`));
  if (!hasLegacy) return list;

  const value = {};
  for (const suffix of legacySuffixes) {
    const legacy = byKey.get(`awn-mindmap-${suffix}`);
    if (!legacy) continue;
    if (legacy.kind === "bool") value[suffix] = Boolean(legacy.value);
    else if (legacy.kind === "number") value[suffix] = legacy.value;
    else value[suffix] = String(getPropsEntryDisplayValue(legacy) ?? "").trim();
  }

  const legacyKeys = new Set(legacySuffixes.map((suffix) => `awn-mindmap-${suffix}`));
  const filtered = list.filter((entry) => !legacyKeys.has(normalizePropsKey(entry?.key)));
  filtered.push({ key: "awn-viz-mindmap", kind: "object", value });
  return filtered;
}

function applyTypeSchemaToEntries(entries, typeName = null) {
  const typeDef = getActiveAwnTypeDef(typeName);
  if (!typeDef?.fields) return sortPropsEntries(entries);

  const normalizedEntries = migrateLegacyVisualizationPropsEntries(
    remapLegacyCustomPropEntriesForSchema(entries, typeDef)
  );

  const map = new Map();
  for (const entry of normalizePropsEntries(normalizedEntries)) {
    if (entry?.key) map.set(entry.key, entry);
  }

  const standardKeys = getStandardPropsFieldKeys();
  const orderedKeys = [
    ...standardKeys,
    ...getTypeSchemaFieldKeys(typeDef).filter((key) => !standardKeys.includes(key))
  ];

  const result = [];
  const seen = new Set();
  for (const key of orderedKeys) {
    if (seen.has(key) || isPropsHiddenStorageKey(key)) continue;
    if (!shouldStorePropsFieldInVisibleEntries(key, typeDef.fields[key])) continue;
    seen.add(key);

    const existing = map.get(key);
    if (existing) {
      const fieldDef = typeDef.fields[key];
      let entry = { ...existing };
      if (fieldDef) {
        entry.fieldDef = fieldDef;
        entry.kind = fieldDefToEntryKind(fieldDef);
      }
      if (entry.kind === "array" && !Array.isArray(entry.value)) {
        entry = {
          ...entry,
          value: String(entry.value ?? "")
            .split(",")
            .map((item) => item.trim())
            .filter(Boolean)
        };
      }
      if (Array.isArray(fieldDef?.enum) && fieldDef.enum.length) {
        const api = awnEnumOptionsApi();
        if (isArrayFieldTypeId(fieldDef.type)) {
          const source = Array.isArray(entry.value)
            ? entry.value
            : String(getPropsEntryDisplayValue(entry) || "")
                .split(",")
                .map((item) => item.trim())
                .filter(Boolean);
          const nextValue =
            typeof api.normalizeArrayStoredKeys === "function"
              ? api.normalizeArrayStoredKeys(source, fieldDef.enum)
              : source;
          entry = { ...entry, kind: "array", value: nextValue };
        } else {
          const raw = Array.isArray(entry.value)
            ? getPropsEntryDisplayValue(entry)
            : String(entry.value ?? "");
          const normalized = normalizeEnumDisplayValue(raw, fieldDef.enum);
          if (normalized !== raw) {
            entry = { ...entry, kind: "string", value: normalized };
          }
        }
      }
      result.push(entry);
      continue;
    }

    const fieldDef = typeDef.fields[key];
    if (!fieldDef && standardKeys.includes(key)) {
      result.push({ key, kind: "string", value: "" });
      continue;
    }
    if (!fieldDef) continue;

    result.push({
      key,
      kind: fieldDefToEntryKind(fieldDef),
      value: fieldDefDefaultValue(fieldDef),
      fieldDef
    });
  }

  for (const entry of normalizedEntries) {
    if (!entry?.key || seen.has(entry.key) || isPropsHiddenStorageKey(entry.key)) continue;
    const fieldDef = typeDef.fields[entry.key];
    result.push(fieldDef ? { ...entry, fieldDef, kind: fieldDefToEntryKind(fieldDef) } : entry);
  }
  for (const entry of normalizedEntries) {
    if (!entry?.key) result.push({ key: "", kind: entry.kind || "string", value: entry.value ?? "" });
  }

  return sortPropsEntries(result);
}

const PROPS_KEY_CANONICAL_ALIASES = {
  "awn-title": "awn-name",
  "awn-desc": "awn-description",
  "awn-created": "awn-create",
  "awn-updated": "awn-update",
  tags: "awn-tags",
  tag: "awn-tags"
};

function normalizePropsKey(key) {
  const raw = String(key || "").trim();
  if (!raw) return raw;

  let normalized = raw;
  const upperLegacy = raw.match(/^AWN-([A-Z0-9_-]+)$/);
  if (upperLegacy) {
    normalized = `awn-${upperLegacy[1].toLowerCase().replace(/_/g, "-")}`;
  } else if (/^awn-/i.test(raw)) {
    normalized = raw.toLowerCase();
  }

  return PROPS_KEY_CANONICAL_ALIASES[normalized] || normalized;
}

function getPropsFieldMeta(key) {
  const normalized = normalizePropsKey(key);
  if (!normalized) {
    return { label: "Свойство", hint: "" };
  }
  const schemaMeta = getPropsFieldMetaFromSchema(normalized);
  if (schemaMeta) return schemaMeta;
  const override = PROPS_FIELD_META[normalized];
  if (override) {
    return { ...override, typeId: null, fieldDef: null };
  }
  return { label: normalized, hint: "", typeId: "awn.field.string", fieldDef: null };
}

function isStandardPropsFieldKey(key) {
  const normalized = normalizePropsKey(key);
  return Boolean(normalized && getStandardPropsFieldKeys().includes(normalized));
}

function mergePropsEntryValues(existing, incoming) {
  if (!existing) return incoming;
  const existingKey = normalizePropsKey(existing.key);
  const incomingKey = normalizePropsKey(incoming.key);
  const shouldMergeArrays =
    existingKey === "awn-tags" ||
    existing.kind === "array" ||
    incoming.kind === "array" ||
    Array.isArray(existing.value) ||
    Array.isArray(incoming.value);
  if (!shouldMergeArrays) return incoming;

  const toList = (entry) => {
    if (Array.isArray(entry.value)) return entry.value.map(String).filter(Boolean);
    const text = String(getPropsEntryDisplayValue(entry) || "").trim();
    if (!text || text === "[]") return [];
    if (text.startsWith("[") && text.endsWith("]")) {
      return text
        .slice(1, -1)
        .split(",")
        .map((item) => item.trim().replace(/^['"]|['"]$/g, ""))
        .filter(Boolean);
    }
    return text
      .split(",")
      .map((item) => item.trim())
      .filter(Boolean);
  };

  const merged = [...new Set([...toList(existing), ...toList(incoming)])];
  return {
    ...existing,
    key: existingKey || existing.key,
    kind: "array",
    value: merged
  };
}

function normalizePropsEntries(entries) {
  const map = new Map();
  for (const entry of entries) {
    if (!entry?.key) continue;
    const key = normalizePropsKey(entry.key);
    const next = { ...entry, key };
    const prev = map.get(key);
    map.set(key, prev ? mergePropsEntryValues(prev, next) : next);
  }
  return [...map.values()];
}

const OVERVIEW_EXCLUDED_PROP_KEYS = new Set(["awn-preview", "awn-web-url", "awn-attachments", "awn-materials"]);

function ensureAwnContextDefaults(entries) {
  const map = new Map();
  for (const entry of entries) {
    if (entry?.key) map.set(entry.key, entry);
  }

  const existingType = normalizeAwnTypeName(map.get("awn-type")?.value);
  const nextType = existingType || normalizeAwnTypeName(resolveAwnTypeForContext(activePath));
  if (nextType) {
    map.set("awn-type", { key: "awn-type", kind: "string", value: nextType });
  }

  return [...map.values()];
}

function findPropsEntryByKey(entries, key) {
  const normalizedKey = normalizePropsKey(key);
  return (entries || []).find((item) => normalizePropsKey(item.key) === normalizedKey) || null;
}

function readPropsEntryBoolean(entry) {
  if (!entry || entry.kind === "null") return false;
  if (entry.kind === "bool") return Boolean(entry.value);
  const text = String(entry.value ?? "").trim().toLowerCase();
  return text === "true" || text === "yes" || text === "1" || text === "да";
}

function getPropsEntryBooleanValue(entries, key) {
  return readPropsEntryBoolean(findPropsEntryByKey(entries, key));
}

function migrateRuntimeLoadPropEntries(entries) {
  const list = normalizePropsEntries(entries);
  const legacyEntry = findPropsEntryByKey(list, "awn-runtime-load");
  const alwaysEntry = findPropsEntryByKey(list, "awn-runtime-load-always");
  if (!legacyEntry && !alwaysEntry) return list;

  let always = false;
  if (alwaysEntry) {
    always = readPropsEntryBoolean(alwaysEntry);
  } else if (legacyEntry) {
    const raw = String(legacyEntry.kind === "bool" ? legacyEntry.value : legacyEntry.value ?? "")
      .trim()
      .toLowerCase();
    always = raw === "session-start" || raw === "true" || raw === "yes" || raw === "1" || raw === "да";
  }

  const filtered = list.filter((entry) => {
    const key = normalizePropsKey(entry?.key);
    return key !== "awn-runtime-load" && key !== "awn-runtime-load-always";
  });
  filtered.push({ key: "awn-runtime-load-always", kind: "bool", value: always });
  return filtered;
}

function migrateLegacyTaxonomyPropsEntries(entries) {
  const list = [...(entries || [])];
  const byKey = new Map(list.map((entry) => [normalizePropsKey(entry?.key), entry]));
  if (byKey.has("awn-taxonomy")) return list;

  const taxonomyValue = {};
  const legacyCategory = byKey.get("awn-category");
  if (legacyCategory) {
    taxonomyValue.category = normalizeTaxonomyEntryValue(legacyCategory.value, "one");
  }
  const legacyColor = byKey.get("awn-color");
  if (legacyColor) {
    taxonomyValue.color = normalizeTaxonomyEntryValue(legacyColor.value, "many");
  }
  if (!Object.keys(taxonomyValue).length) return list;

  const filtered = list.filter(
    (entry) => !["awn-category", "awn-color"].includes(normalizePropsKey(entry?.key))
  );
  filtered.push({ key: "awn-taxonomy", kind: "taxonomy", value: taxonomyValue });
  return filtered;
}

function absorbPropsYamlEntries(entries) {
  const normalized = migrateRuntimeLoadPropEntries(
    migrateLegacyTaxonomyPropsEntries(normalizePropsEntries(entries))
  );
  const hidden = [];
  const visible = [];
  for (const entry of normalized) {
    const key = normalizePropsKey(entry?.key);
    if (key && isPropsHiddenStorageKey(key)) hidden.push({ ...entry, key });
    else visible.push(entry);
  }
  propsFormHiddenEntries = dedupePropsEntriesByKey(hidden);
  propsFormEntries = ensureStandardPropsEntries(ensureAwnContextDefaults(visible));
}

function mergePropsFormEntries() {
  const hiddenKeys = new Set(
    propsFormHiddenEntries.map((entry) => normalizePropsKey(entry?.key)).filter(Boolean)
  );
  const visible = propsFormEntries.filter((entry) => {
    const key = normalizePropsKey(entry?.key);
    if (!key) return true;
    if (isPropsHiddenStorageKey(key)) return false;
    if (hiddenKeys.has(key)) return false;
    return true;
  });
  return dedupePropsEntriesByKey([...propsFormHiddenEntries, ...visible]);
}

function ensureStandardPropsEntries(entries) {
  if (awnTypesCache?.types) {
    return applyTypeSchemaToEntries(entries);
  }

  const map = new Map();
  for (const entry of normalizePropsEntries(entries)) {
    if (entry?.key) map.set(entry.key, entry);
  }
  const result = [];
  const standardKeys = getStandardPropsFieldKeys();
  for (const key of standardKeys) {
    if (HIDDEN_PROPS_FIELD_KEYS.has(key)) continue;
    result.push(map.get(key) || { key, kind: "string", value: "" });
  }
  for (const entry of entries) {
    if (!entry?.key || standardKeys.includes(entry.key)) continue;
    if (HIDDEN_PROPS_FIELD_KEYS.has(entry.key)) continue;
    result.push(entry);
  }
  for (const entry of entries) {
    if (!entry?.key) result.push({ key: "", kind: entry.kind || "string", value: entry.value ?? "" });
  }
  return sortPropsEntries(result);
}

function formatYamlScalar(value) {
  const text = String(value ?? "");
  if (!text || /[:#\[\]{}&,*?"']|^\s|\s$/.test(text)) {
    return `"${text.replace(/\\/g, "\\\\").replace(/"/g, '\\"')}"`;
  }
  return text;
}

function unescapeYamlDoubleQuotedString(text) {
  return String(text)
    .replace(/\\"/g, '"')
    .replace(/\\\\/g, "\\")
    .replace(/\\n/g, "\n")
    .replace(/\\r/g, "\r")
    .replace(/\\t/g, "\t");
}

function normalizeYamlDisplayString(value) {
  const text = String(value ?? "").trim();
  if (!text || !text.includes("\\")) return text;
  if (text.includes('\\"') || text.includes("\\\\")) {
    return unescapeYamlDoubleQuotedString(text);
  }
  return text;
}

function parseYamlScalarValue(raw) {
  let value = String(raw ?? "").trim();
  if (!value) return "";

  if (value[0] === '"') {
    try {
      return JSON.parse(value);
    } catch {
      if (value.endsWith('"') && value.length >= 2) {
        return unescapeYamlDoubleQuotedString(value.slice(1, -1));
      }
      const end = value.indexOf('"', 1);
      if (end > 0) return value.slice(1, end);
      return value.slice(1);
    }
  }

  if (value[0] === "'") {
    if (value.endsWith("'") && value.length >= 2) {
      return value.slice(1, -1).replace(/''/g, "'");
    }
    const end = value.indexOf("'", 1);
    if (end > 0) return value.slice(1, end);
    return value.slice(1);
  }

  const commentAt = value.search(/\s#/);
  if (commentAt >= 0) value = value.slice(0, commentAt).trim();
  return normalizeYamlDisplayString(value);
}

function parsePropsYaml(text) {
  const lines = String(text || "").replace(/^\uFEFF/, "").split(/\r?\n/);
  const entries = [];
  let index = 0;

  while (index < lines.length) {
    const line = lines[index];
    if (!line.trim() || line.trim().startsWith("#")) {
      index += 1;
      continue;
    }

    const match = line.match(/^(\s*)([^:]+):\s*(.*)$/);
    if (!match || match[1].length > 0) {
      index += 1;
      continue;
    }

    const key = normalizePropsKey(match[2].trim());
    const rest = match[3];

    if (key === "awn-taxonomy" && rest === "") {
      const parsed = parsePropsYamlTaxonomyBlock(lines, index + 1);
      entries.push({ key, kind: "taxonomy", value: parsed.value });
      index = parsed.nextIndex;
      continue;
    }

    if (isAwnNestedObjectPropsKey(key) && rest === "") {
      const parsed = parsePropsYamlObjectBlock(lines, index + 1);
      entries.push({ key, kind: "object", value: parsed.value });
      index = parsed.nextIndex;
      continue;
    }

    if (rest === "|" || rest === ">") {
      const folded = rest === ">";
      const blockLines = [];
      index += 1;
      while (index < lines.length) {
        const nextLine = lines[index];
        if (!nextLine.trim()) {
          if (blockLines.length) {
            blockLines.push("");
            index += 1;
            continue;
          }
          break;
        }
        if (/^[^\s#].*:/.test(nextLine)) break;
        if (!/^\s/.test(nextLine)) break;
        blockLines.push(nextLine.replace(/^\s+/, ""));
        index += 1;
      }
      const value = folded
        ? blockLines.join(" ").replace(/[ \t]+/g, " ").trim()
        : blockLines.join("\n").replace(/\n+$/, "");
      entries.push({ key, kind: "string", value });
      continue;
    }

    if (rest === "") {
      const items = [];
      index += 1;
      while (index < lines.length && /^\s+-\s?/.test(lines[index])) {
        items.push(lines[index].replace(/^\s+-\s?/, "").trim().replace(/^["']|["']$/g, ""));
        index += 1;
      }
      if (items.length) {
        entries.push({ key, kind: "array", value: items });
        continue;
      }
      entries.push({ key, kind: "string", value: "" });
      continue;
    }

    if (rest.startsWith("[") && rest.endsWith("]")) {
      const inner = rest.slice(1, -1).trim();
      const value = inner
        ? inner.split(",").map((part) => part.trim().replace(/^["']|["']$/g, ""))
        : [];
      entries.push({ key, kind: "array", value });
      index += 1;
      continue;
    }

    if (rest === "true" || rest === "false") {
      entries.push({ key, kind: "bool", value: rest === "true" });
      index += 1;
      continue;
    }

    if (rest === "null" || rest === "~") {
      entries.push({ key, kind: "null", value: null });
      index += 1;
      continue;
    }

    if (/^-?\d+(?:\.\d+)?$/.test(rest) && !/^\d+\.\d+\.\d+(?:[-+].*)?$/.test(rest)) {
      entries.push({ key, kind: "number", value: Number(rest) });
      index += 1;
      continue;
    }

    entries.push({ key, kind: "string", value: String(parseYamlScalarValue(rest) ?? "") });
    index += 1;
  }

  return entries;
}

function stringifyPropsYaml(entries) {
  const lines = [];
  for (const entry of sortPropsEntries(entries)) {
    if (!entry.key) continue;
    if (entry.kind === "array") {
      const items = Array.isArray(entry.value) ? entry.value : [];
      if (!items.length) {
        lines.push(`${entry.key}: []`);
      } else if (items.length === 1) {
        lines.push(`${entry.key}: ${formatYamlScalar(items[0])}`);
      } else {
        lines.push(`${entry.key}:`);
        for (const item of items) {
          lines.push(`  - ${formatYamlScalar(item)}`);
        }
      }
      continue;
    }
    if (entry.kind === "bool") {
      lines.push(`${entry.key}: ${entry.value ? "true" : "false"}`);
      continue;
    }
    if (entry.kind === "number") {
      if (normalizePropsKey(entry.key) === "awn-id") {
        const idValue = normalizeAwnIdDisplayValue(entry.value);
        if (idValue) lines.push(`${entry.key}: ${idValue}`);
        continue;
      }
      lines.push(`${entry.key}: ${entry.value}`);
      continue;
    }
    if (entry.kind === "null") {
      lines.push(`${entry.key}: null`);
      continue;
    }
    if (entry.kind === "taxonomy") {
      const obj =
        entry.value && typeof entry.value === "object" && !Array.isArray(entry.value) ? entry.value : {};
      lines.push(...stringifyPropsYamlNestedMapping(entry.key, obj));
      continue;
    }
    if (entry.kind === "object") {
      const obj =
        entry.value && typeof entry.value === "object" && !Array.isArray(entry.value) ? entry.value : {};
      lines.push(...stringifyPropsYamlNestedMapping(entry.key, obj));
      continue;
    }
    lines.push(`${entry.key}: ${formatYamlScalar(entry.value ?? "")}`);
  }
  return lines.join("\n");
}

function formatPropsDatetimeLocalValue(value) {
  const raw = String(value ?? "").trim();
  if (!raw) return "";
  const date = new Date(raw);
  if (Number.isNaN(date.getTime())) return raw;
  const pad = (part) => String(part).padStart(2, "0");
  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}T${pad(date.getHours())}:${pad(date.getMinutes())}`;
}

function getPropsEntryDisplayValue(entry) {
  if (MODULE_GIT_COMMIT_EXTENSIONS_FIELD_KEYS.has(entry.key)) {
    return formatAgentGitCommitExtensionsDisplay(entry.value);
  }
  if (entry.kind === "array") {
    const values = Array.isArray(entry.value)
      ? entry.value
      : String(entry.value ?? "")
          .split(",")
          .map((item) => item.trim())
          .filter(Boolean);
    return values.join(", ");
  }
  if (entry.kind === "bool") {
    return entry.value ? "true" : "false";
  }
  if (entry.kind === "null") {
    return "";
  }
  if (entry.kind === "number") {
    return String(entry.value);
  }
  return coerceSettingsTextValue(entry.value, "");
}

function applyFormValueToEntry(entry, rawValue) {
  const trimmed = String(rawValue ?? "").trim();
  if (entry.kind === "array") {
    return {
      ...entry,
      value: trimmed ? trimmed.split(",").map((part) => part.trim()).filter(Boolean) : []
    };
  }
  if (entry.kind === "bool") {
    return { ...entry, value: trimmed === "true" };
  }
  if (entry.kind === "number") {
    if (normalizePropsKey(entry.key) === "awn-id" && trimmed === "") {
      return { ...entry, value: "" };
    }
    return { ...entry, value: trimmed === "" ? 0 : Number(trimmed) };
  }
  if (entry.kind === "null") {
    return { ...entry, value: null };
  }
  if (entry.kind === "taxonomy") {
    if (rawValue && typeof rawValue === "object" && !Array.isArray(rawValue)) {
      return { ...entry, kind: "taxonomy", value: rawValue };
    }
    if (!trimmed) return { ...entry, kind: "taxonomy", value: {} };
    try {
      const parsed = JSON.parse(trimmed);
      return {
        ...entry,
        kind: "taxonomy",
        value: parsed && typeof parsed === "object" && !Array.isArray(parsed) ? parsed : {}
      };
    } catch {
      return { ...entry, kind: "taxonomy", value: entry.value ?? {} };
    }
  }
  if (entry.kind === "object") {
    if (rawValue && typeof rawValue === "object" && !Array.isArray(rawValue)) {
      return { ...entry, kind: "object", value: rawValue };
    }
    if (!trimmed) return { ...entry, kind: "object", value: {} };
    try {
      const parsed = JSON.parse(trimmed);
      return {
        ...entry,
        kind: "object",
        value: parsed && typeof parsed === "object" && !Array.isArray(parsed) ? parsed : {}
      };
    } catch {
      return { ...entry, kind: "object", value: entry.value ?? {} };
    }
  }
  return { ...entry, kind: "string", value: rawValue };
}

function syncYamlFromPropsForm() {
  propsInputNode.value = stringifyPropsYaml(mergePropsFormEntries());
}

function canEditPropsForm() {
  if (activeSystemFile) return true;
  if (!isEditorSaveTrackingActive()) return false;
  return isStorageSlotMarkdownRecordEditing() || activeContentMode === "description";
}

function isPropsFormReadOnly() {
  return !canEditPropsForm();
}

function getDocAsideTab() {
  const saved = readStorageItem(DOC_ASIDE_TAB_STORAGE_KEY);
  if (saved === "outline" || saved === "blocks" || saved === "links" || saved === "props") return saved;
  return "outline";
}

function isDocAsideAvailable() {
  if (!activePath || isPlainServiceStyleOpen()) return false;
  if (activeContentMode === NODE_DISCUSSION_MODE || activeContentMode === NODE_JOURNAL_MODE) return false;
  if (!isEditorSaveTrackingActive()) return false;
  if (isCurrentModeWithoutContentEditor()) return false;
  if (isCurrentModeListTemplate()) return false;
  if (activeContentMode === "configs" || activeContentMode === "env") return false;
  return true;
}

function isDocAsideOutlineTabAvailable() {
  return isDocAsideAvailable();
}

function isDocAsidePropsTabAvailable() {
  if (isGitRepoLooseMdEditing()) return false;
  if (isAwnDatabaseCsvRecordContentPath(getResolvedNodePath(activePath))) return false;
  return activeContentMode === "description" || isStorageSlotMarkdownRecordEditing();
}

function isDocAsideEditorToolsTabAvailable() {
  return canInsertDocContentBlocks();
}

function getDocAsideTabAvailability() {
  return {
    outlinePanelAvailable: isDocAsideOutlineTabAvailable(),
    propsPanelAvailable: isDocAsidePropsTabAvailable(),
    editorToolsPanelAvailable: isDocAsideEditorToolsTabAvailable()
  };
}

function resolveDocAsideTab(
  tab,
  { outlineAvailable = true, propsAvailable = true, editorToolsAvailable = true } = {}
) {
  const order = ["outline", "props", "blocks", "links"];
  const preferred = order.includes(tab) ? tab : "outline";
  const availability = {
    outline: outlineAvailable,
    props: propsAvailable,
    blocks: editorToolsAvailable,
    links: editorToolsAvailable
  };
  if (availability[preferred]) return preferred;
  return order.find((id) => availability[id]) || "outline";
}

function syncDocAsideTabButton(btn, available, disabledHint = "") {
  if (!btn) return;
  if (!btn.dataset.defaultTitle) {
    btn.dataset.defaultTitle = btn.title || btn.textContent?.trim() || "";
  }
  btn.disabled = !available;
  btn.classList.toggle("is-disabled", !available);
  btn.setAttribute("aria-disabled", available ? "false" : "true");
  btn.title = available ? btn.dataset.defaultTitle : disabledHint || btn.dataset.defaultTitle;
}

function setDocAsideTab(tab) {
  const availability = getDocAsideTabAvailability();
  const next = resolveDocAsideTab(tab, {
    outlineAvailable: availability.outlinePanelAvailable,
    propsAvailable: availability.propsPanelAvailable,
    editorToolsAvailable: availability.editorToolsPanelAvailable
  });
  localStorage.setItem(DOC_ASIDE_TAB_STORAGE_KEY, next);
  syncDocAsideUi(availability);
}

function slugifyHeadingText(text) {
  const base = String(text || "")
    .trim()
    .toLowerCase()
    .replace(/[^\p{L}\p{N}\s-]/gu, "")
    .replace(/\s+/g, "-")
    .replace(/-+/g, "-")
    .replace(/^-|-$/g, "");
  return base || "section";
}

function parseMarkdownHeadings(markdown) {
  const lines = String(markdown || "").split(/\r?\n/);
  const headings = [];
  const slugCounts = new Map();
  let inFence = false;
  let fenceChar = "";

  for (let i = 0; i < lines.length; i += 1) {
    const line = lines[i];
    const fenceMatch = line.match(/^(`{3,}|~{3,})/);
    if (fenceMatch) {
      const ch = fenceMatch[1][0];
      if (!inFence) {
        inFence = true;
        fenceChar = ch;
      } else if (ch === fenceChar) {
        inFence = false;
      }
      continue;
    }
    if (inFence) continue;

    const match = line.match(/^(#{1,6})\s+(.+?)\s*#*\s*$/);
    if (!match) continue;

    const level = match[1].length;
    const text = match[2]
      .replace(/!\[[^\]]*]\([^)]+\)/g, "")
      .replace(/\[([^\]]+)]\([^)]+\)/g, "$1")
      .replace(/`([^`]+)`/g, "$1")
      .replace(/\*\*|__|\*|_|~~/g, "")
      .trim();
    if (!text) continue;

    const baseSlug = slugifyHeadingText(text);
    const seen = slugCounts.get(baseSlug) || 0;
    slugCounts.set(baseSlug, seen + 1);
    const slug = seen ? `${baseSlug}-${seen + 1}` : baseSlug;

    headings.push({
      level,
      text,
      line: i + 1,
      slug,
      index: headings.length
    });
  }

  return headings;
}

function getDocOutlineMarkdownSource() {
  if (editorViewMode === "wysiwyg" && wysiwygEditorInstance) {
    return normalizeWysiwygExportedMarkdown(wysiwygEditorInstance.getMarkdown());
  }
  return fileContentInputNode?.value || "";
}

function scrollEditorToLine(lineIndexZeroBased) {
  const ta = fileContentInputNode;
  if (!ta || lineIndexZeroBased < 0) return;
  const lines = ta.value.split("\n");
  let pos = 0;
  for (let i = 0; i < lineIndexZeroBased && i < lines.length; i += 1) {
    pos += lines[i].length + 1;
  }
  ta.focus({ preventScroll: true });
  ta.setSelectionRange(pos, pos);
  const styles = getComputedStyle(ta);
  const lineHeight = Number.parseFloat(styles.lineHeight) || 22;
  ta.scrollTop = Math.max(0, lineIndexZeroBased * lineHeight - ta.clientHeight / 3);
  syncEditorLineNumbersScroll();
}

function scrollToDocHeading(heading) {
  if (!heading) return;
  if (editorViewMode === "preview") {
    const target =
      fileContentPreviewNode?.querySelector(`#${CSS.escape(heading.slug)}`) ||
      fileContentPreviewNode?.querySelectorAll("h1,h2,h3,h4,h5,h6")?.[heading.index];
    target?.scrollIntoView({ behavior: "smooth", block: "start" });
    return;
  }
  if (editorViewMode === "source") {
    scrollEditorToLine(heading.line - 1);
    return;
  }
  if (editorViewMode === "wysiwyg" && wysiwygEditorInstance) {
    const md = getDocOutlineMarkdownSource();
    const offset = markdownOffsetFromLineCol(md, heading.line, 1);
    setWysiwygCursorAtMarkdownOffset(md, offset);
    return;
  }
}

function renderDocOutline() {
  if (!docOutlineContentNode) return;
  const headings = parseMarkdownHeadings(getDocOutlineMarkdownSource());
  docOutlineContentNode.innerHTML = "";

  if (!headings.length) {
    const empty = document.createElement("p");
    empty.className = "doc-outline-empty";
    empty.textContent = "Заголовков H1–H6 пока нет";
    docOutlineContentNode.appendChild(empty);
    return;
  }

  const nav = document.createElement("nav");
  nav.className = "doc-outline-nav";
  nav.setAttribute("aria-label", "Оглавление документа");
  const list = document.createElement("ul");
  list.className = "doc-outline-list";

  for (const heading of headings) {
    const item = document.createElement("li");
    item.className = `doc-outline-item doc-outline-h${heading.level}`;
    const btn = document.createElement("button");
    btn.type = "button";
    btn.className = "doc-outline-link";
    btn.title = `${heading.text} (H${heading.level})`;
    btn.dataset.level = String(heading.level);
    btn.textContent = heading.text;
    btn.addEventListener("click", () => scrollToDocHeading(heading));
    item.appendChild(btn);
    list.appendChild(item);
  }

  nav.appendChild(list);
  docOutlineContentNode.appendChild(nav);
}

function getDocContentBlockGroups() {
  const groups = awnTypesCache?.blockGroups;
  if (Array.isArray(groups) && groups.length) return groups;
  return DOC_CONTENT_BLOCK_GROUPS_FALLBACK;
}

function renderDocContentBlocks() {
  if (!docBlocksContentNode) return;
  docBlocksContentNode.replaceChildren();

  if (!canInsertDocContentBlocks()) {
    const empty = document.createElement("p");
    empty.className = "doc-blocks-empty";
    empty.textContent = "Блоки доступны в режиме редактирования Markdown.";
    docBlocksContentNode.appendChild(empty);
    return;
  }

  for (const group of getDocContentBlockGroups()) {
    const section = document.createElement("section");
    section.className = "doc-blocks-group";
    section.setAttribute("aria-label", group.title);

    const title = document.createElement("h3");
    title.className = "doc-blocks-group-title";
    title.textContent = group.title;
    section.appendChild(title);

    const list = document.createElement("ul");
    list.className = "doc-blocks-list";

    for (const block of group.blocks) {
      const item = document.createElement("li");
      const btn = document.createElement("button");
      btn.type = "button";
      btn.className = "doc-block-btn";
      const blockLabel = block.label || block.name || block.id;
      btn.title = block.description || blockLabel;

      const head = document.createElement("span");
      head.className = "doc-block-btn-head";

      const iconText = resolveDocBlockIcon(block);
      if (iconText) {
        const icon = document.createElement("span");
        const markerTypeClass = resolveDocMarkerBlockIconTypeClass(block.id);
        icon.className = markerTypeClass
          ? `doc-block-btn-icon type-icon type-${markerTypeClass}`
          : "doc-block-btn-icon";
        icon.textContent = iconText;
        icon.setAttribute("aria-hidden", "true");
        head.appendChild(icon);
      }

      const label = document.createElement("span");
      label.className = "doc-block-btn-label";
      label.textContent = blockLabel;
      head.appendChild(label);

      const desc = document.createElement("span");
      desc.className = "doc-block-btn-desc";
      desc.textContent = block.description || "";

      btn.append(head, desc);
      bindEditorAsideInsertControl(btn);
      btn.addEventListener("click", (event) => {
        event.preventDefault();
        const snippet = resolveDocBlockSnippet(block);
        insertMarkdownAtEditorCursor(snippet);
      });

      item.appendChild(btn);
      list.appendChild(item);
    }

    section.appendChild(list);
    docBlocksContentNode.appendChild(section);
  }
}

function getLinkLibraryScopeFolder(nodePath) {
  const resolved = normalizeMenuNodePath(getResolvedNodePath(nodePath));
  const topicManifest = getTopicSchemaManifestPath(resolved);
  const anchor = topicManifest || resolved;
  if (!anchor) return ".";
  return normalizeFolderPath(getFolderPathFromManifest(anchor) || ".");
}

function getLinkLibraryScopeLabel(nodePath) {
  const topicManifest = getTopicSchemaManifestPath(nodePath);
  if (topicManifest) {
    return getLabelFromPath(topicManifest) || stripAgentContentPrefixFromRelPath(getFolderPathFromManifest(topicManifest));
  }
  const folder = getLinkLibraryScopeFolder(nodePath);
  if (!folder || folder === ".") return getAgentTreeTitle();
  return stripAgentContentPrefixFromRelPath(folder);
}

async function loadMarkdownLinkIndex(options = {}) {
  const force = options.force === true;
  if (!activeWorkspaceId) {
    invalidateMarkdownLinkIndexCache();
    return markdownLinkIndexCache;
  }

  if (
    !force &&
    markdownLinkIndexCache.agentId === activeWorkspaceId &&
    markdownLinkIndexCache.items.length
  ) {
    return markdownLinkIndexCache;
  }

  if (
    !force &&
    markdownLinkIndexCache.loading &&
    markdownLinkIndexCache.promise &&
    markdownLinkIndexCache.agentId === activeWorkspaceId
  ) {
    return markdownLinkIndexCache.promise;
  }

  const agentId = activeWorkspaceId;
  markdownLinkIndexCache.loading = true;
  markdownLinkIndexCache.agentId = agentId;

  markdownLinkIndexCache.promise = fetch(buildApiUrl("/api/agent/markdown-index"))
    .then((response) => {
      if (!response.ok) throw new Error(`HTTP ${response.status}`);
      return response.json();
    })
    .then((data) => {
      if (markdownLinkIndexCache.agentId !== agentId) return markdownLinkIndexCache;
      markdownLinkIndexCache.items = Array.isArray(data.items) ? data.items : [];
      markdownLinkIndexCache.groups = Array.isArray(data.groups) ? data.groups : [];
      markdownLinkIndexCache.awnTypes = Array.isArray(data.awnTypes) ? data.awnTypes : [];
      markdownLinkFlatLibraryCache = null;
      markdownLinkFlatLibraryCacheKey = "";
      return markdownLinkIndexCache;
    })
    .catch((error) => {
      if (markdownLinkIndexCache.agentId === agentId) {
        markdownLinkIndexCache.items = [];
        markdownLinkIndexCache.groups = [];
      }
      console.warn("Failed to load markdown link index:", error);
      return markdownLinkIndexCache;
    })
    .finally(() => {
      markdownLinkIndexCache.loading = false;
      markdownLinkIndexCache.promise = null;
    });

  return markdownLinkIndexCache.promise;
}

function invalidateMarkdownLinkIndexCache() {
  markdownLinkIndexCache = {
    agentId: null,
    items: [],
    groups: [],
    loading: false,
    promise: null
  };
  markdownLinkFlatLibraryCache = null;
  markdownLinkFlatLibraryCacheKey = "";
}

function getWorkspaceRelParentDir(relPath) {
  const parts = normalizeLinkFilePath(relPath).split("/").filter(Boolean);
  if (parts.length <= 1) return "";
  parts.pop();
  return parts.join("/");
}

function mapIndexItemToLibraryItem(item) {
  return {
    relPath: item.relPath,
    label: item.label,
    fileName: item.fileName,
    awnType: item.awnType || "awn.file",
    awnTypeLabel: item.awnTypeLabel || item.kindLabel || "Файл",
    kindLabel: item.awnTypeLabel || item.kindLabel || "Файл",
    locationHint: item.locationHint,
    displayPath: item.locationHint || item.relPath,
    group: item.group,
    groupLabel: item.groupLabel,
    nodePath: item.nodePath,
    externalFile: item.externalFile,
    mode: item.mode,
    systemFile: item.systemFile,
    path: item.nodePath,
    markdownLink: buildMarkdownLinkFromWorkspaceRel(item.relPath, item.label)
  };
}

function isDocLinkRegistryNoise(item) {
  const base = String(item.fileName || item.relPath || "")
    .split("/")
    .pop()
    .toLowerCase();
  return base === "_reg-info.md" || base === "_reginfo.md" || base === "_registration.md";
}

function shouldShowDocLinkItemByDefault(item) {
  if (String(docLinksSearchQuery || "").trim()) return true;
  if (item.awnType === "service") return false;
  if (isDocLinkRegistryNoise(item)) return false;
  if (item.awnType === "awn.memory") return false;
  return true;
}

function filterVisibleDocLinkItems(items) {
  return items.filter(shouldShowDocLinkItemByDefault);
}

function formatDocLinkLibraryPresentation(item) {
  const relPath = normalizeLinkFilePath(item.relPath || getLinkTargetFileRelPath(item.path) || item.path || "");
  const fileName = item.fileName || relPath.split("/").pop() || relPath;
  const menuTitle = item.nodePath ? resolveMenuEntryLabel(item.nodePath, item.label) : "";
  const title = menuTitle || item.label || fileName.replace(/\.md$/i, "");
  const typeLabel = item.awnTypeLabel || item.kindLabel || "Файл";
  const insertHref = extractMarkdownLinkHref(getMarkdownLinkForLibraryItem(item)) || fileName;
  const menuPath =
    item.nodePath && (item.awnType === "awn.topic" || item.awnType === "awn.area")
      ? stripAgentContentPrefixFromRelPath(stripVaultPrefixFromRelPath(getNodeDisplayPath(item.nodePath)))
      : "";
  return { title, fileName, typeLabel, insertHref, menuPath };
}

function getMarkdownLinkForLibraryItem(item) {
  if (item.relPath) return buildMarkdownLinkFromWorkspaceRel(item.relPath, item.label);
  if (item.path) return buildMarkdownFileLink(item.path, item.label);
  return item.markdownLink || item.wikilink || "";
}

function sortDocLinkItemsByMenuOrder(items) {
  const menu = menuCacheByAgent.get(activeWorkspaceId) || currentMenuData;
  if (!menu) {
    return [...items].sort((a, b) =>
      String(a.label || "").localeCompare(String(b.label || ""), "ru")
    );
  }

  const order = new Map();
  let index = 0;
  for (const entry of collectAgentMenuFlatEntries(menu, activeWorkspaceId, { includeHiddenSections: true })) {
    const path = normalizeMenuNodePath(entry.path);
    if (path && !order.has(path)) order.set(path, index++);
  }

  return [...items].sort((a, b) => {
    const aPath = a.nodePath ? normalizeMenuNodePath(a.nodePath) : "";
    const bPath = b.nodePath ? normalizeMenuNodePath(b.nodePath) : "";
    const aRank = aPath && order.has(aPath) ? order.get(aPath) : null;
    const bRank = bPath && order.has(bPath) ? order.get(bPath) : null;
    if (aRank != null && bRank != null && aRank !== bRank) return aRank - bRank;
    if (aRank != null && bRank == null) return -1;
    if (aRank == null && bRank != null) return 1;
    return String(a.label || "").localeCompare(String(b.label || ""), "ru");
  });
}

function collectMarkdownLinkLibraryGroups() {
  const currentPath = normalizeLinkFilePath(getCurrentEditorLinkBasePath());
  const currentDir = getWorkspaceRelParentDir(currentPath);
  const activeScope = getLinkLibraryScopeFolder(activePath);
  const sourceItems = (markdownLinkIndexCache.items || [])
    .filter(
      (item) =>
        normalizeLinkFilePath(item.relPath).toLowerCase() !== currentPath.toLowerCase()
    )
    .map(mapIndexItemToLibraryItem);

  const sameFolder = [];
  const sameTopic = [];
  const grouped = Object.fromEntries(AWN_LINK_TYPE_GROUP_ORDER.map(({ id }) => [id, []]));
  const used = new Set();

  for (const item of sourceItems) {
    const parentDir = getWorkspaceRelParentDir(item.relPath);
    const inSameFolder = Boolean(currentDir && parentDir === currentDir);
    const inSameScope =
      Boolean(item.nodePath && activeScope && getLinkLibraryScopeFolder(item.nodePath) === activeScope);
    if (inSameFolder) {
      sameFolder.push(item);
      used.add(item.relPath);
    } else if (inSameScope) {
      sameTopic.push(item);
      used.add(item.relPath);
    }
  }

  for (const item of sourceItems) {
    if (used.has(item.relPath)) continue;
    const typeKey = AWN_LINK_TYPE_GROUP_ORDER.some(({ id }) => id === item.awnType)
      ? item.awnType
      : "awn.file";
    grouped[typeKey].push(item);
  }

  const sorter = (a, b) => String(a.label || "").localeCompare(String(b.label || ""), "ru");
  sameFolder.sort(sorter);
  sameTopic.sort(sorter);
  grouped["awn.topic"] = sortDocLinkItemsByMenuOrder(grouped["awn.topic"] || []);
  for (const { id } of AWN_LINK_TYPE_GROUP_ORDER) {
    if (id === "awn.topic") continue;
    grouped[id].sort(sorter);
  }

  return {
    sameFolder,
    sameTopic,
    grouped,
    scopeLabel: getLinkLibraryScopeLabel(activePath),
    currentDir
  };
}

function getFlatMarkdownLinkLibraryItems(options = {}) {
  const force = options.force === true;
  const cacheKey = `${activeWorkspaceId || ""}:${getCurrentEditorLinkBasePath()}:${(markdownLinkIndexCache.items || []).length}`;
  if (!force && markdownLinkFlatLibraryCache && markdownLinkFlatLibraryCacheKey === cacheKey) {
    return markdownLinkFlatLibraryCache;
  }

  let items;
  if ((markdownLinkIndexCache.items || []).length) {
    const { sameFolder, sameTopic, grouped } = collectMarkdownLinkLibraryGroups();
    items = [
      ...sameFolder,
      ...sameTopic,
      ...AWN_LINK_TYPE_GROUP_ORDER.flatMap(({ id }) => grouped[id] || [])
    ];
  } else {
    const menuGroups = collectDocLinkLibraryGroups();
    items = [...menuGroups.currentTopic, ...menuGroups.otherTopics];
  }

  markdownLinkFlatLibraryCache = items;
  markdownLinkFlatLibraryCacheKey = cacheKey;
  return items;
}

function buildDocLinkLibrarySearchHaystack(item) {
  return [
    item.label,
    item.fileName,
    item.awnType,
    item.awnTypeLabel,
    item.kindLabel,
    item.locationHint,
    item.displayPath,
    item.relPath,
    item.path,
    item.groupLabel,
    item.markdownLink,
    item.wikilink
  ]
    .filter(Boolean)
    .join(" ")
    .toLowerCase();
}

function isDocLinkLibraryEntry(entry) {
  if (!entry?.path || entry.isSystemFile) return false;
  const path = normalizeMenuNodePath(entry.path);
  return Boolean(path && isNodeMdPath(path));
}

function collectDocLinkLibraryGroups() {
  const menu = menuCacheByAgent.get(activeWorkspaceId) || currentMenuData;
  if (!menu || !activePath) {
    return { currentTopic: [], otherTopics: [], scopeLabel: "" };
  }

  const allEntries = collectAgentMenuFlatEntries(menu, activeWorkspaceId, { includeHiddenSections: true });
  const activeResolved = normalizeMenuNodePath(getResolvedNodePath(activePath));
  const activeScope = getLinkLibraryScopeFolder(activePath);
  const currentTopic = [];
  const otherTopics = [];

  for (const entry of allEntries) {
    if (!isDocLinkLibraryEntry(entry)) continue;
    const path = normalizeMenuNodePath(entry.path);
    if (!path || path === activeResolved) continue;

    const item = {
      path,
      label: entry.label || getLabelFromPath(path),
      displayPath: entry.displayPath || getNodeDisplayPath(path),
      wikilink: buildMarkdownFileLink(path, entry.label),
      markdownLink: buildMarkdownFileLink(path, entry.label),
      color: entry.color || null
    };

    if (getLinkLibraryScopeFolder(path) === activeScope) {
      currentTopic.push(item);
    } else {
      otherTopics.push(item);
    }
  }

  const sorter = (a, b) => String(a.label || "").localeCompare(String(b.label || ""), "ru");
  currentTopic.sort(sorter);
  otherTopics.sort(sorter);

  return {
    currentTopic,
    otherTopics,
    scopeLabel: getLinkLibraryScopeLabel(activePath)
  };
}

function bindDocLinkLibraryItem(btn, item) {
  btn.draggable = true;
  btn.addEventListener("dragstart", (event) => {
    event.stopPropagation();
    const markdownLink = getMarkdownLinkForLibraryItem(item);
    if (!markdownLink) {
      event.preventDefault();
      return;
    }
    event.dataTransfer.effectAllowed = "copy";
    event.dataTransfer.setData(
      MENU_LINK_DRAG_MIME,
      JSON.stringify({
        path: item.path || item.nodePath || "",
        label: item.label,
        wikilink: markdownLink,
        markdownLink
      })
    );
    event.dataTransfer.setData("text/plain", markdownLink);
    btn.classList.add("is-dragging-menu-link");
  });
  btn.addEventListener("dragend", () => {
    btn.classList.remove("is-dragging-menu-link");
  });
}

function filterDocLinkLibraryItems(items, query = docLinksSearchQuery) {
  const q = String(query || "").trim().toLowerCase();
  if (!q) return items;
  return items.filter((item) => buildDocLinkLibrarySearchHaystack(item).includes(q));
}

function ensureDocLinksSearchUi() {
  const scroll = docLinksContentNode?.parentElement;
  if (!scroll) return;

  let wrap = scroll.querySelector(".doc-links-search-wrap");
  if (!wrap) {
    wrap = document.createElement("div");
    wrap.className = "doc-links-search-wrap";

    const input = document.createElement("input");
    input.type = "search";
    input.id = "doc-links-search";
    input.className = "doc-links-search";
    input.placeholder = "Название, путь, awn-тип…";
    input.autocomplete = "off";
    input.spellcheck = false;
    input.value = docLinksSearchQuery;
    input.addEventListener("input", () => {
      docLinksSearchQuery = input.value;
      renderDocLinksLibrary({ preserveSearchFocus: true });
    });
    input.addEventListener("keydown", (event) => {
      event.stopPropagation();
    });

    const hint = document.createElement("p");
    hint.className = "doc-links-search-hint";
    hint.textContent = "Перетащите в редактор. Группы сворачиваются — состояние запоминается.";

    wrap.appendChild(input);
    wrap.appendChild(hint);
    scroll.insertBefore(wrap, docLinksContentNode);
  }

  docLinksSearchInputNode = wrap.querySelector("#doc-links-search") || docLinksSearchInputNode;
  const hintNode = wrap.querySelector(".doc-links-search-hint");
  if (hintNode) {
    hintNode.textContent = "Перетащите в редактор. Группы сворачиваются — состояние запоминается.";
  }
}

function syncDocLinksSearchUi({ disabled = false } = {}) {
  ensureDocLinksSearchUi();
  if (!docLinksSearchInputNode) return;
  docLinksSearchInputNode.disabled = disabled;
  if (docLinksSearchInputNode.value !== docLinksSearchQuery) {
    docLinksSearchInputNode.value = docLinksSearchQuery;
  }
  syncDocLinksSearchResultsHint();
}

function syncDocLinksSearchResultsHint() {
  const wrap = docLinksContentNode?.parentElement?.querySelector(".doc-links-search-wrap");
  const hintNode = wrap?.querySelector(".doc-links-search-hint");
  if (!hintNode) return;
  const query = String(docLinksSearchQuery || "").trim();
  if (!query) {
    hintNode.textContent =
      "Перетащите в редактор. Группы сворачиваются — состояние запоминается.";
    return;
  }
  const matchCount = docLinksContentNode?.querySelectorAll(".doc-link-btn").length || 0;
  const groupCount = docLinksContentNode?.querySelectorAll(".doc-links-accordion").length || 0;
  if (!matchCount) {
    hintNode.textContent = `Поиск «${query}» — совпадений нет. Служебные файлы тоже ищутся.`;
    return;
  }
  hintNode.textContent = `Поиск «${query}» — ${matchCount} в ${groupCount} группах. Перетащите в редактор.`;
}

function loadDocLinksAccordionState() {
  try {
    const raw = readStorageItem(DOC_LINKS_ACCORDION_STORAGE_KEY);
    if (!raw) return {};
    const parsed = JSON.parse(raw);
    return parsed && typeof parsed === "object" ? parsed : {};
  } catch {
    return {};
  }
}

function saveDocLinksAccordionState(groupId, isOpen) {
  if (!groupId) return;
  const state = loadDocLinksAccordionState();
  state[groupId] = Boolean(isOpen);
  try {
    localStorage.setItem(DOC_LINKS_ACCORDION_STORAGE_KEY, JSON.stringify(state));
  } catch {
    // ignore quota / private mode
  }
}

function resolveDocLinksAccordionOpen(groupId, { forceOpen = false } = {}) {
  if (forceOpen) return true;
  const state = loadDocLinksAccordionState();
  if (Object.prototype.hasOwnProperty.call(state, groupId)) {
    return Boolean(state[groupId]);
  }
  return DOC_LINKS_ACCORDION_DEFAULT_OPEN.has(groupId);
}

function appendDocLinkLibraryList(parent, items) {
  const list = document.createElement("ul");
  list.className = "doc-links-list";

  for (const item of items) {
    const li = document.createElement("li");
    const btn = document.createElement("button");
    btn.type = "button";
    btn.className = "doc-link-btn";
    const presentation = formatDocLinkLibraryPresentation(item);
    btn.title = `${presentation.title}\n${presentation.typeLabel} · ${presentation.fileName}\n→ ${presentation.insertHref}`;

    const title = document.createElement("span");
    title.className = "doc-link-btn-title";
    title.textContent = presentation.title;

    const meta = document.createElement("span");
    meta.className = "doc-link-btn-meta";
    meta.textContent = presentation.menuPath
      ? `${presentation.typeLabel} · ${presentation.menuPath}`
      : `${presentation.typeLabel} · ${presentation.fileName}`;

    const insert = document.createElement("span");
    insert.className = "doc-link-btn-insert";
    insert.textContent = `→ ${presentation.insertHref}`;

    btn.append(title, meta, insert);
    applyNodeColorVars(btn, item.color);
    bindDocLinkLibraryItem(btn, item);

    li.appendChild(btn);
    list.appendChild(li);
  }

  parent.appendChild(list);
  return list;
}

function appendDocLinkLibraryAccordionGroup(
  parent,
  { id, title, hint, icon, items, emptyText, forceOpen = false }
) {
  const section = document.createElement("details");
  section.className = "doc-links-accordion";
  section.dataset.groupId = id;
  section.open = resolveDocLinksAccordionOpen(id, { forceOpen });

  section.addEventListener("toggle", () => {
    saveDocLinksAccordionState(id, section.open);
  });

  const summary = document.createElement("summary");
  summary.className = "doc-links-accordion-summary";

  if (icon) {
    const iconNode = document.createElement("span");
    iconNode.className = "doc-links-accordion-icon";
    iconNode.textContent = icon;
    iconNode.setAttribute("aria-hidden", "true");
    summary.appendChild(iconNode);
  }

  const summaryMain = document.createElement("span");
  summaryMain.className = "doc-links-accordion-summary-main";

  const titleRow = document.createElement("span");
  titleRow.className = "doc-links-accordion-title";
  titleRow.textContent = title;
  summaryMain.appendChild(titleRow);

  if (hint) {
    const hintNode = document.createElement("span");
    hintNode.className = "doc-links-accordion-hint";
    hintNode.textContent = hint;
    summaryMain.appendChild(hintNode);
  }

  summary.appendChild(summaryMain);

  const count = document.createElement("span");
  count.className = "doc-links-accordion-count";
  count.textContent = String(items.length);
  summary.appendChild(count);

  section.appendChild(summary);

  const body = document.createElement("div");
  body.className = "doc-links-accordion-body";

  if (!items.length) {
    const empty = document.createElement("p");
    empty.className = "doc-links-empty";
    empty.textContent = emptyText;
    body.appendChild(empty);
  } else {
    appendDocLinkLibraryList(body, items);
  }

  section.appendChild(body);
  parent.appendChild(section);
}

function appendDocLinkLibraryGroup(parent, sectionSpec) {
  appendDocLinkLibraryAccordionGroup(parent, sectionSpec);
}

function renderDocLinksLibrary(options = {}) {
  if (!docLinksContentNode) return;

  const editable = canInsertDocContentBlocks();
  syncDocLinksSearchUi({ disabled: !editable });
  docLinksContentNode.replaceChildren();

  if (!editable) {
    docLinksSearchQuery = "";
    syncDocLinksSearchUi({ disabled: true });
    const empty = document.createElement("p");
    empty.className = "doc-links-empty";
    empty.textContent = "Ссылки доступны в режиме редактирования Markdown (Source).";
    docLinksContentNode.appendChild(empty);
    return;
  }

  const requestId = ++renderDocLinksLibraryRequestId;
  const loading = document.createElement("p");
  loading.className = "doc-links-empty";
  loading.textContent = "Загрузка индекса markdown…";
  docLinksContentNode.appendChild(loading);

  loadMarkdownLinkIndex().then(() => {
    if (requestId !== renderDocLinksLibraryRequestId || !docLinksContentNode) return;
    renderDocLinksLibraryContent(options);
  });
}

function renderDocLinksLibraryContent(options = {}) {
  if (!docLinksContentNode) return;

  docLinksContentNode.replaceChildren();
  const hasQuery = Boolean(String(docLinksSearchQuery || "").trim());
  const forceOpen = hasQuery;
  const useIndex = (markdownLinkIndexCache.items || []).length > 0;

  if (useIndex) {
    const { sameFolder, sameTopic, grouped, scopeLabel, currentDir } = collectMarkdownLinkLibraryGroups();
    const sections = [];
    const filteredSameFolder = filterDocLinkLibraryItems(filterVisibleDocLinkItems(sameFolder));
    const filteredSameTopic = filterDocLinkLibraryItems(filterVisibleDocLinkItems(sameTopic));

    if (!hasQuery || filteredSameFolder.length) {
      sections.push({
        id: "nearby-folder",
        icon: "📂",
        title: "Эта папка",
        hint: currentDir
          ? stripAgentContentPrefixFromRelPath(currentDir)
          : "Файлы в той же директории",
        items: filteredSameFolder,
        emptyText: hasQuery ? "В этой папке нет совпадений." : "В этой папке нет других .md для ссылки."
      });
    }

    if (!hasQuery || filteredSameTopic.length) {
      sections.push({
        id: "nearby-topic",
        icon: "🧭",
        title: "Эта тема",
        hint: scopeLabel ? `Область: ${scopeLabel}` : "Другие файлы той же темы",
        items: filteredSameTopic,
        emptyText: hasQuery ? "В этой теме нет совпадений." : "В теме нет других .md в соседних папках."
      });
    }

    for (const { id, label, hint, icon } of AWN_LINK_TYPE_GROUP_ORDER) {
      const filtered = filterDocLinkLibraryItems(filterVisibleDocLinkItems(grouped[id] || []));
      if (hasQuery && !filtered.length) continue;
      const sectionTitle =
        id === "awn.topic"
          ? `Темы · ${getActiveAgentLabel() || activeWorkspaceId || "агент"}`
          : label;
      const sectionHint =
        id === "awn.topic" ? "Как в меню слева — только темы агента" : hint || "";
      sections.push({
        id,
        icon: icon || "📄",
        title: sectionTitle,
        hint: sectionHint,
        items: filtered,
        emptyText: hasQuery ? `В «${sectionTitle}» нет совпадений.` : `Нет элементов типа ${id}.`
      });
    }

    const visibleSections = sections.filter((section) => section.items.length > 0);
    const totalMatches = visibleSections.reduce((sum, section) => sum + section.items.length, 0);

    if (hasQuery && !totalMatches) {
      const empty = document.createElement("p");
      empty.className = "doc-links-empty";
      empty.textContent = "Ничего не найдено.";
      docLinksContentNode.appendChild(empty);
    } else {
      if (hasQuery && totalMatches) {
        const summary = document.createElement("p");
        summary.className = "doc-links-results-summary";
        const groupWord =
          visibleSections.length === 1
            ? "1 группе"
            : visibleSections.length >= 2 && visibleSections.length <= 4
              ? `${visibleSections.length} группах`
              : `${visibleSections.length} группах`;
        summary.textContent = `Найдено ${totalMatches} в ${groupWord}`;
        docLinksContentNode.appendChild(summary);
      }

      for (const section of visibleSections) {
        appendDocLinkLibraryAccordionGroup(docLinksContentNode, { ...section, forceOpen });
      }

      if (!docLinksContentNode.childElementCount) {
        const empty = document.createElement("p");
        empty.className = "doc-links-empty";
        empty.textContent = "В workspace пока нет markdown-файлов для ссылки.";
        docLinksContentNode.appendChild(empty);
      }
    }
  } else {
    const { currentTopic, otherTopics, scopeLabel } = collectDocLinkLibraryGroups();
    const filteredCurrent = filterDocLinkLibraryItems(currentTopic);
    const filteredOther = filterDocLinkLibraryItems(otherTopics);

    if (hasQuery && !filteredCurrent.length && !filteredOther.length) {
      const empty = document.createElement("p");
      empty.className = "doc-links-empty";
      empty.textContent = "Ничего не найдено.";
      docLinksContentNode.appendChild(empty);
    } else {
      const visibleCount = (filteredCurrent.length ? 1 : 0) + (filteredOther.length ? 1 : 0);
      const totalMatches = filteredCurrent.length + filteredOther.length;
      if (hasQuery && totalMatches) {
        const summary = document.createElement("p");
        summary.className = "doc-links-results-summary";
        summary.textContent = `Найдено ${totalMatches} в ${visibleCount} группах`;
        docLinksContentNode.appendChild(summary);
      }

      if (filteredCurrent.length) {
        appendDocLinkLibraryAccordionGroup(docLinksContentNode, {
          id: "menu-current-topic",
          icon: "📂",
          title: "Текущая тема",
          hint: scopeLabel ? `Область: ${scopeLabel}` : "",
          items: filteredCurrent,
          emptyText: "В текущей теме нет других записей для ссылки.",
          forceOpen
        });
      }

      if (filteredOther.length) {
        appendDocLinkLibraryAccordionGroup(docLinksContentNode, {
          id: "menu-other-topics",
          icon: "🗺",
          title: "Другие темы",
          hint: "Темы из остальных разделов агента",
          items: filteredOther,
          emptyText: "Других тем для ссылки пока нет.",
          forceOpen
        });
      }
    }
  }

  syncDocLinksSearchResultsHint();

  if (options.preserveSearchFocus && docLinksSearchInputNode) {
    docLinksSearchInputNode.focus();
    const end = docLinksSearchInputNode.value.length;
    docLinksSearchInputNode.setSelectionRange(end, end);
  }
}

function formatMiniDocPathHint(relativePath) {
  const rel = String(relativePath || "").replace(/^\/+/, "");
  const containerDir = activePath ? getNamedStorageBundleDirRel(getResolvedNodePath(activePath)) : "";
  const fullPath = containerDir ? `${containerDir}/${rel}` : `{тема}/${rel}`;
  return `<code>${fullPath}</code>`;
}

