function renderEditorCustomPropsBar() {
  if (!editorCustomPropsBarNode || !editorCustomPropsFieldsNode) return;

  editorCustomPropsFieldsNode.replaceChildren();
  const showBar = shouldShowEditorCustomPropsBar();
  if (!showBar) {
    editorCustomPropsBarNode.classList.add("hidden");
    return;
  }

  const manifestPath = getTopicSchemaManifestPath();
  if (manifestPath && !hasTopicSchemaCacheForContext(manifestPath)) {
    void ensureTopicSchemaForActiveContext().then(() => {
      if (shouldShowEditorCustomPropsBar() && !propsRawYamlVisible) renderEditorCustomPropsBar();
    });
    editorCustomPropsBarNode.classList.add("hidden");
    return;
  }

  const nodePath = getPropsContextPath();
  const userItems = collectEditorCustomPropsItems(nodePath);

  if (!userItems.length) {
    editorCustomPropsBarNode.classList.add("hidden");
    return;
  }

  editorCustomPropsBarNode.classList.remove("hidden");
  const readOnly = isPropsFormReadOnly();
  editorCustomPropsFieldsNode.classList.toggle("is-readonly", readOnly);
  const collapseState = loadEditorCustomPropsCollapseState();
  const groupedItems = groupEditorCustomPropsItems(userItems);
  const hasMultipleGroups = groupedItems.length > 1;
  syncEditorCustomPropsRootToggle({
    fieldCount: userItems.length,
    rootCollapsed: collapseState.root,
    showBulkToggle: hasMultipleGroups
  });

  if (readOnly) {
    const list = document.createElement("div");
    list.className = "props-preview-list props-preview-list--compact editor-custom-props-preview";
    for (const group of groupedItems) {
      appendEditorCustomPropsGroupSection(list, group, {
        readOnly: true,
        collapsible: hasMultipleGroups,
        collapsed: Boolean(collapseState.groups[group.id])
      });
    }
    editorCustomPropsFieldsNode.appendChild(list);
    updateEditorCustomPropsBulkToggleLabel();
    return;
  }

  const needsPropsLibrary = userItems.some(({ entry }) => {
    const widget = resolvePropsFieldWidget(entry.key, getPropsFieldDef(entry.key));
    return propsFieldWidgetNeedsLibrary(widget);
  });
  if (needsPropsLibrary && !isPropsLibrariesReadyForActiveNode()) {
    void ensurePropsLibrariesLoaded().then(() => {
      if (shouldShowEditorCustomPropsBar() && !propsRawYamlVisible) renderEditorCustomPropsBar();
    });
  }

  for (const group of groupedItems) {
    appendEditorCustomPropsGroupSection(editorCustomPropsFieldsNode, group, {
      readOnly: false,
      collapsible: hasMultipleGroups,
      collapsed: Boolean(collapseState.groups[group.id])
    });
  }
  updateEditorCustomPropsBulkToggleLabel();
}

function renderPropsForm() {
  propsFormEntries = ensureStandardPropsEntries(propsFormEntries);
  syncPropsPanelTitleFromSchema();
  renderEditorCustomPropsBar();
  if (!propsFormFieldsNode) return;
  if (!shouldRenderPropsFormNow()) {
    propsFormFieldsNode.replaceChildren();
    return;
  }
  renderPropsPreviewBlock();
  renderPropsWebUrlBlock();
  renderPropsAttachmentsBlock();
  renderPropsMaterialsBlock();
  propsFormFieldsNode.innerHTML = "";
  const readOnly = isPropsFormReadOnly();
  propsFormFieldsNode.classList.toggle("is-readonly", readOnly);

  if (!propsFormEntries.length) {
    const empty = document.createElement("p");
    empty.className = "props-form-empty";
    empty.textContent = readOnly
      ? "Свойств пока нет."
      : "Свойств пока нет — добавьте поле или откройте YAML.";
    propsFormFieldsNode.appendChild(empty);
    return;
  }

  const asideItems = collectPropsFormItemsForPlacement("aside-body");
  const orphanItems = collectPropsAsideOrphanItems(asideItems);
  const collapseState = loadPropsGroupCollapseState();

  const appendPropsAsideOrphanGroup = (container, items, { readOnly: readOnlyMode = false } = {}) => {
    if (!items.length || !container) return;

    const group = document.createElement("section");
    group.className = "props-form-group props-form-group--orphan props-form-group--collapsible";
    group.dataset.group = PROPS_ASIDE_ORPHAN_GROUP_ID;
    const defaultCollapsed = true;
    const collapsed =
      Object.prototype.hasOwnProperty.call(collapseState, PROPS_ASIDE_ORPHAN_GROUP_ID)
        ? Boolean(collapseState[PROPS_ASIDE_ORPHAN_GROUP_ID])
        : defaultCollapsed;
    group.classList.toggle("is-collapsed", collapsed);

    const header = document.createElement("button");
    header.type = "button";
    header.className = "props-form-group-toggle";
    header.setAttribute("aria-expanded", String(!collapsed));

    const caret = createPropsFormGroupCaretElement();
    const title = document.createElement("span");
    title.className = "props-form-group-title";
    title.textContent = "Вне схемы";
    const count = document.createElement("span");
    count.className = "props-form-group-count";
    count.textContent = String(items.length);
    header.append(caret, title, count);

    const groupBody = document.createElement("div");
    groupBody.className = "props-form-group-body";
    for (const { entry, index } of items) {
      if (readOnlyMode) {
        const meta = getPropsFieldMeta(entry.key);
        const displayValue = getPropsEntryDisplayValue(entry);
        const field = document.createElement("div");
        field.className = "props-preview-field props-preview-field--compact";
        field.dataset.index = String(index);
        decoratePropsAsideOrphanRow(field);
        const label = buildPropsFieldKeyLabelElement(entry.key, meta, {
          tag: "span",
          className: "props-preview-label props-preview-label--with-key"
        });
        const value = document.createElement("span");
        value.className = "props-preview-value";
        value.textContent = displayValue.trim() ? displayValue : "—";
        value.classList.toggle("is-empty", !displayValue.trim());
        field.append(label, value);
        groupBody.appendChild(field);
      } else {
        const row = createPropsFormFieldRow(entry, index, { showFieldKey: true, editorCompact: true });
        decoratePropsAsideOrphanRow(row);
        groupBody.appendChild(row);
      }
    }

    header.addEventListener("click", () => {
      const nowCollapsed = !group.classList.contains("is-collapsed");
      group.classList.toggle("is-collapsed", nowCollapsed);
      header.setAttribute("aria-expanded", String(!nowCollapsed));
      savePropsGroupCollapseState(PROPS_ASIDE_ORPHAN_GROUP_ID, nowCollapsed);
    });

    group.append(header, groupBody);
    container.appendChild(group);
  };

  if (readOnly) {
    const list = document.createElement("div");
    list.className = "props-preview-list props-preview-list--compact";

    for (const { entry, index } of asideItems) {
      const meta = getPropsFieldMeta(entry.key);
      const displayValue = getPropsEntryDisplayValue(entry);

      const field = document.createElement("div");
      field.className = "props-preview-field props-preview-field--compact";
      field.dataset.index = String(index);
      field.title = entry.key || "";

      const label = buildFieldLabelElement(meta.label || entry.key || "—", {
        tag: "span",
        className: "props-preview-label",
        typeId: meta.typeId || meta.fieldDef?.type,
        key: entry.key,
        title: entry.key || ""
      });

      const value = document.createElement("span");
      value.className = "props-preview-value";
      value.textContent = displayValue.trim() ? displayValue : "—";
      value.classList.toggle("is-empty", !displayValue.trim());

      field.append(label, value);
      list.appendChild(field);
    }
    if (!list.childElementCount && !orphanItems.length) {
      const empty = document.createElement("p");
      empty.className = "props-form-empty props-form-empty--editor-custom-hint";
      empty.textContent = "Свойств в панели пока нет.";
      propsFormFieldsNode.appendChild(empty);
    } else {
      if (list.childElementCount) propsFormFieldsNode.appendChild(list);
      appendPropsAsideOrphanGroup(propsFormFieldsNode, orphanItems, { readOnly: true });
    }
    return;
  }

  const appendPropsFieldGroup = (groupDef, items, { collapsible = false } = {}) => {
    if (!items.length) return;

    const group = document.createElement("section");
    group.className = "props-form-group";

    const title = groupDef?.name || null;
    const groupId = groupDef?.id || null;

    const groupBody = document.createElement("div");
    groupBody.className = "props-form-group-body";
    for (const { entry, index } of items) {
      groupBody.appendChild(createPropsFormFieldRow(entry, index));
    }

    if (collapsible && title) {
      group.classList.add("props-form-group--collapsible");
      const defaultCollapsed = Boolean(groupDef?.collapsed);
      const collapsed =
        groupId && Object.prototype.hasOwnProperty.call(collapseState, groupId)
          ? Boolean(collapseState[groupId])
          : defaultCollapsed;

      const header = document.createElement("button");
      header.type = "button";
      header.className = "props-form-group-toggle";
      header.setAttribute("aria-expanded", String(!collapsed));

      const caret = createPropsFormGroupCaretElement();
      const titleEl = document.createElement("span");
      titleEl.className = "props-form-group-title";
      titleEl.textContent = formatSchemaDisplayTitle(title, { replaceMarker: false });
      const countEl = document.createElement("span");
      countEl.className = "props-form-group-count";
      countEl.textContent = String(items.length);
      header.append(caret, titleEl, countEl);

      group.classList.toggle("is-collapsed", collapsed);
      group.appendChild(header);
      group.appendChild(groupBody);

      header.addEventListener("click", () => {
        const nowCollapsed = !group.classList.contains("is-collapsed");
        group.classList.toggle("is-collapsed", nowCollapsed);
        header.setAttribute("aria-expanded", String(!nowCollapsed));
        savePropsGroupCollapseState(groupId, nowCollapsed);
      });
    } else {
      if (title) {
        const groupTitle = document.createElement("h4");
        groupTitle.className = "props-form-group-title";
        groupTitle.textContent = formatSchemaDisplayTitle(title, { replaceMarker: false });
        group.appendChild(groupTitle);
      }
      group.appendChild(groupBody);
    }

    propsFormFieldsNode.appendChild(group);
  };

  const needsPropsLibrary = asideItems.some(({ entry }) => {
    const widget = resolvePropsFieldWidget(entry.key, getPropsFieldDef(entry.key));
    return propsFieldWidgetNeedsLibrary(widget);
  });
  if (needsPropsLibrary && !isPropsLibrariesReadyForActiveNode() && shouldRenderPropsFormNow()) {
    void ensurePropsLibrariesLoaded().then(() => {
      if (shouldRenderPropsFormNow() && !propsRawYamlVisible) renderPropsForm();
    });
  }

  const groupDefs = getActivePropsFieldGroups();
  const grouped = new Map();
  for (const item of asideItems) {
    const gid = resolvePropsFieldGroupId(item.entry.key, getPropsFieldDef(item.entry.key));
    if (!grouped.has(gid)) grouped.set(gid, []);
    grouped.get(gid).push(item);
  }

  const firstGroupId = groupDefs[0]?.id;
  const hasMultipleGroups = grouped.size > 1;
  const renderedGroups = new Set();
  for (const groupDef of groupDefs) {
    const items = grouped.get(groupDef.id);
    if (!items || !items.length) continue;
    renderedGroups.add(groupDef.id);
    if (!hasMultipleGroups || groupDef.id === firstGroupId) {
      appendPropsFieldGroup({ ...groupDef, name: null }, items, { collapsible: false });
    } else {
      appendPropsFieldGroup(groupDef, items, { collapsible: true });
    }
  }
  for (const [gid, items] of grouped) {
    if (renderedGroups.has(gid) || !items.length) continue;
    appendPropsFieldGroup({ id: gid, name: null }, items, { collapsible: false });
  }

  appendPropsAsideOrphanGroup(propsFormFieldsNode, orphanItems);

  if (!asideItems.length && !orphanItems.length) {
    const empty = document.createElement("p");
    empty.className = "props-form-empty props-form-empty--editor-custom-hint";
    empty.textContent = readOnly
      ? "Свойств в панели пока нет."
      : "Поля с placement aside-body — здесь. Пользовательские поля по умолчанию — над текстом.";
    propsFormFieldsNode.appendChild(empty);
  }

  syncRuntimePropsFormVisibility();
  syncDocAsideTodoStickerPreview();
}

function isTopicOnlyPropsFieldKey(key) {
  return normalizePropsKey(key) === AWN_TOPIC_SLOTS_FLEXIBLE_KEY;
}

function shouldIncludePropsFieldKey(key, contextPath = getPropsContextPath()) {
  if (isTopicOnlyPropsFieldKey(key)) {
    return isTopicManifestPath(contextPath);
  }
  return true;
}

const PROPS_FIELD_WIDGET_FALLBACKS = {
  "awn-focus": "boolean",
  "awn-main": "boolean",
  "awn-slots-flexible": "boolean",
  "awn-runtime-cron": "runtime-schedule-type",
  "awn-runtime-reminder": "boolean",
  "awn-runtime-heartbeat": "boolean",
  "awn-runtime-commands": "boolean",
  "awn-runtime-load-always": "boolean"
};

const DEDICATED_FIELD_TYPE_WIDGETS = new Set([
  "preview",
  "attachments",
  "materials",
  "cron-schedule",
  "lookup-one",
  "lookup-many",
  "stars",
  "importance",
  "object-group"
]);

const DEDICATED_FIELD_TYPE_SUFFIX_WIDGETS = {
  "file.image.for-preview": "preview",
  "string.cron-schedule": "cron-schedule",
  "date.time": "time",
  "duration": "duration",
  "text.code": "code",
  "string.secret": "secret",
  "object": "object",
  "repeater": "repeater",
  "json": "json",
  "coordinates": "coordinates",
  "lookup.one": "lookup-one",
  "lookup.many": "lookup-many",
  taxonomy: "taxonomy",
  "materials": "materials",
  "array": "array",
  "number.stars": "stars",
  "number.importance": "importance"
};

const LEGACY_LOOKUP_TYPE_SOURCES = {
  "string.catalog-status": "statuses",
  "string.catalog-category": "categories",
  "string.catalog-users": "users",
  "string.catalog-priorities": "priorities",
  "string.catalog-colors": "colors",
  "array.catalog-tags": "tags"
};

const LEGACY_LOOKUP_ONE_WIDGETS = new Set([
  "catalog-category",
  "catalog-status",
  "catalog-users",
  "catalog-priorities",
  "catalog-colors"
]);

function resolveLookupSource(fieldDef) {
  const explicit = String(fieldDef?.source || fieldDef?.catalog || "").trim();
  if (explicit) return explicit;
  const typeId = normalizeCanonicalFieldTypeId(fieldDef?.type || "");
  const suffix = typeId.replace(/^awn\./, "");
  return LEGACY_LOOKUP_TYPE_SOURCES[suffix] || "";
}

function isLookupColorField(fieldDef) {
  return resolveLookupSource(fieldDef) === "colors" || fieldDef?.["value-kind"] === "color";
}

function isLookupOneWidget(widget) {
  return widget === "lookup-one" || LEGACY_LOOKUP_ONE_WIDGETS.has(widget);
}

function isLookupManyWidget(widget) {
  return widget === "lookup-many" || widget === "catalog-tags";
}

function isLookupFieldWidget(widget) {
  return isLookupOneWidget(widget) || isLookupManyWidget(widget);
}

function resolveDedicatedFieldTypeWidget(typeId, registryEntry = null) {
  const widget = String(registryEntry?.widget || "").trim();
  if (widget && DEDICATED_FIELD_TYPE_WIDGETS.has(widget)) return widget;

  const canonical = normalizeCanonicalFieldTypeId(typeId);
  const suffix = canonical.replace(/^awn\./, "");
  if (DEDICATED_FIELD_TYPE_SUFFIX_WIDGETS[suffix]) {
    return DEDICATED_FIELD_TYPE_SUFFIX_WIDGETS[suffix];
  }
  return null;
}

function resolveSchemaPropsWidget(fieldDef) {
  if (!fieldDef) return null;
  const typeId = normalizeCanonicalFieldTypeId(fieldDef.type || "");
  const registry = awnTypesCache?.fieldRegistry || {};
  const registryEntry =
    registry[fieldDef.type] ||
    registry[typeId] ||
    registry[`awn.field.${typeId.replace(/^awn\./, "")}`];
  const fromType = resolveDedicatedFieldTypeWidget(typeId, registryEntry);
  if (fromType) return fromType;

  // Legacy: widget + catalog on primitive types (старые схемы до awn.field.lookup.*)
  const widget = String(fieldDef.widget || "").trim();
  const catalog = String(fieldDef.catalog || fieldDef.source || "").trim();
  if (widget === "catalog-lookup" && catalog) {
    const arrayCatalogs = new Set(["tags"]);
    return arrayCatalogs.has(catalog) ? "lookup-many" : "lookup-one";
  }
  if (widget === "catalog-tags") return "lookup-many";
  if (LEGACY_LOOKUP_ONE_WIDGETS.has(widget)) return "lookup-one";
  if (widget === "cron-schedule") return "cron-schedule";
  if (widget === "preview") return "preview";
  if (widget === "attachments") return "attachments";
  if (widget) return widget;
  return null;
}

function resolvePropsFieldWidget(key, fieldDef = getPropsFieldDef(key)) {
  const normalized = normalizePropsKey(key);
  if (MODULE_GIT_COMMIT_EXTENSIONS_FIELD_KEYS.has(normalized)) return "textarea";
  if (normalized === "awn-runtime-cron") return "runtime-schedule-type";
  if (isPropsAttachmentsField(key, fieldDef)) return "attachments";
  if (hasStructuredObjectFieldProperties(fieldDef, normalized)) return "object-group";
  const fromSchema = resolveSchemaPropsWidget(fieldDef);
  if (fromSchema) return fromSchema;
  if (!fieldDef && PROPS_FIELD_WIDGET_FALLBACKS[normalized]) {
    return PROPS_FIELD_WIDGET_FALLBACKS[normalized];
  }

  const typeId = normalizeCanonicalFieldTypeId(fieldDef?.type || "");
  const registry = awnTypesCache?.fieldRegistry || {};
  const registryEntry = registry[typeId] || registry[fieldDef?.type || ""];
  const dedicatedWidget = resolveDedicatedFieldTypeWidget(typeId, registryEntry);
  if (dedicatedWidget) return dedicatedWidget;

  const widget = resolveFieldWidget(fieldDef, registryEntry);
  if (widget === "attachments") return "attachments";

  if (isTaxonomyFieldTypeId(typeId)) return "taxonomy";
  if (isLookupOneFieldTypeId(typeId)) return "lookup-one";
  if (isLookupManyFieldTypeId(typeId)) return "lookup-many";
  if (isChoiceOneFieldTypeId(typeId)) {
    if (widget === "radio") return "radio";
    return "select";
  }
  if (isBooleanFieldTypeId(typeId) || widget === "toggle") return "boolean";
  if (isRelationFieldTypeId(typeId) || widget === "relation" || widget === "link") return "relation";
  if (fieldTypeIs(typeId, "string.link") || widget === "path") return "path";
  if (fieldTypeIs(typeId, "file.image.for-preview")) return "preview";
  if (isLegacyAttachmentsWithPreviewType(fieldDef)) return "attachments";
  if (fieldTypeIs(typeId, "materials")) return "materials";
  if (fieldTypeIs(typeId, "file.image.one") || widget === "image") return "image";
  if (isFileFieldTypeId(typeId) || widget === "file") return "file";
  if (fieldTypeIs(typeId, "text") || widget === "textarea") return "textarea";
  if (fieldTypeIs(typeId, "string.url") || widget === "url") return "url";
  if (fieldTypeIs(typeId, "string.email") || widget === "email") return "email";
  if (fieldTypeIs(typeId, "string.phone") || widget === "tel") return "tel";
  if (fieldTypeIs(typeId, "string.password") || widget === "password") return "password";
  if (fieldTypeIs(typeId, "string.slug") || widget === "slug") return "slug";
  if (fieldTypeIs(typeId, "string.color") || widget === "color") return "color";
  if (fieldTypeIs(typeId, "date")) return "date";
  if (fieldTypeIs(typeId, "date.datetime")) return "datetime";
  if (fieldTypeIs(typeId, "date.time")) return "time";
  if (fieldTypeIs(typeId, "duration")) return "duration";
  if (fieldTypeIs(typeId, "text.code")) return "code";
  if (fieldTypeIs(typeId, "string.secret")) return "secret";
  if (fieldTypeIs(typeId, "json")) return "json";
  if (
    registryEntry?.storage === "object" &&
    resolveRepeaterItemPropertyDefs(fieldDef, normalized).length
  ) {
    return "object-group";
  }
  if (fieldTypeIs(typeId, "object")) return "object";
  if (fieldTypeIs(typeId, "repeater")) return "repeater";
  if (fieldTypeIs(typeId, "coordinates")) return "coordinates";
  if (fieldTypeIs(typeId, "number.stars")) return "stars";
  if (fieldTypeIs(typeId, "number.importance")) return "importance";
  if (fieldTypeIs(typeId, "number")) return "number";
  if (fieldTypeIs(typeId, "array") || widget === "tags") return "array";
  if (isChoiceManyFieldTypeId(typeId)) {
    if (widget === "select-multiple") {
      return getEnumOptionsForField(fieldDef).length ? "select-multiple" : "array";
    }
    if (widget === "checkbox") {
      return getEnumOptionsForField(fieldDef).length ? "enum-checkbox" : "array";
    }
    return getEnumOptionsForField(fieldDef).length ? "enum-checkbox" : "array";
  }
  return PROPS_FIELD_WIDGET_FALLBACKS[normalized] || "text";
}

function getAgentCatalogPreset(preset) {
  const definition = findTaxonomyDefinitionForCatalogPreset(preset);
  if (!definition) {
    return { exists: false, title: preset, items: [], groups: null };
  }
  const items = definition.items || [];
  return {
    exists: true,
    title: definition.name || preset,
    items,
    groups: getCatalogGroups({ items })
  };
}

function getCatalogGroups(catalog) {
  if (catalog?.groups?.global || catalog?.groups?.agent) {
    return catalog.groups;
  }
  const items = catalog?.items || [];
  return {
    global: { title: "Общие", items: items.filter((item) => item.scope !== "agent") },
    agent: { title: "Агент", items: items.filter((item) => item.scope === "agent") }
  };
}

function appendPropsFormCatalogTagOptions(list, items, selected, locked) {
  for (const item of items) {
    const label = document.createElement("label");
    label.className = "props-form-tag-option";
    const checkbox = document.createElement("input");
    checkbox.type = "checkbox";
    checkbox.value = item.id;
    checkbox.checked = selected.has(item.id);
    checkbox.disabled = locked;
    const caption = document.createElement("span");
    caption.textContent = getTaxonomyItemDisplayName(item) || `#${item.id}`;
    label.append(checkbox, caption);
    list.appendChild(label);
  }
}

function appendPropsFormSelectOption(select, value, label, { selected = false } = {}) {
  const option = document.createElement("option");
  option.value = value;
  option.textContent = label;
  option.selected = selected;
  select.appendChild(option);
}

function appendPropsFormSelectGroup(select, label, items, currentValue) {
  if (!items.length) return;
  const group = document.createElement("optgroup");
  group.label = label;
  for (const item of items) {
    const option = document.createElement("option");
    option.value = item.wikilink || item.value || item.id || "";
    option.textContent = item.label || item.id || "—";
    if (item.color) option.dataset.color = item.color;
    if (currentValue && option.value === currentValue) option.selected = true;
    group.appendChild(option);
  }
  select.appendChild(group);
}

function createPropsFormCatalogMissingNote(text = "Справочник не создан") {
  const note = document.createElement("p");
  note.className = "props-form-catalog-missing";
  note.textContent = text;
  return note;
}

function createPropsFormValueWrap(widget) {
  const wrap = document.createElement("div");
  wrap.className = "props-form-value-wrap";
  wrap.dataset.widget = widget;
  wrap.dataset.field = "value";
  return wrap;
}

function normalizeExternalWebUrl(rawValue) {
  const raw = String(rawValue || "").trim();
  if (!raw) return "";
  if (/^https?:\/\//i.test(raw)) return raw;
  return "";
}

const PROPS_FORM_EXTERNAL_URL_OPEN_ICON =
  '<svg class="props-form-url-open-icon" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M15 3h6v6M10 14 21 3M18 13v6a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h6" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg>';

function syncPropsFormUrlOpenButton(openBtn, rawValue) {
  if (!openBtn || openBtn.dataset.locked === "1") return;
  const url = normalizeExternalWebUrl(rawValue);
  openBtn.disabled = !url;
  openBtn.dataset.url = url;
  openBtn.title = url ? `Открыть: ${url}` : "Введите URL (https://…)";
}

function appendPropsFormUrlOpenButton(wrap, input, { locked = false } = {}) {
  const row = document.createElement("div");
  row.className = "props-form-url-input-row";

  const openBtn = document.createElement("button");
  openBtn.type = "button";
  openBtn.className = "props-form-url-open-btn";
  openBtn.setAttribute("aria-label", "Открыть ссылку в новом окне");
  openBtn.innerHTML = PROPS_FORM_EXTERNAL_URL_OPEN_ICON;

  openBtn.addEventListener("click", (event) => {
    event.preventDefault();
    const url = normalizeExternalWebUrl(openBtn.dataset.url || input.value);
    if (!url) return;
    window.open(url, "_blank", "noopener,noreferrer");
  });

  const sync = () => syncPropsFormUrlOpenButton(openBtn, input.value);
  input.addEventListener("input", sync);
  input.addEventListener("change", sync);

  if (locked) {
    openBtn.disabled = true;
    openBtn.dataset.locked = "1";
    openBtn.title = "Поле только для чтения";
  } else {
    sync();
  }

  row.append(input, openBtn);
  wrap.classList.add("props-form-value-wrap--url");
  wrap.appendChild(row);
}

function bindPropsFormLockedState(control, locked) {
  if (!control || !locked) return;
  if (control instanceof HTMLSelectElement || control instanceof HTMLTextAreaElement) {
    control.disabled = true;
  } else if (control.type === "checkbox") {
    control.disabled = true;
  } else {
    control.readOnly = true;
  }
  control.classList.add("is-locked");
}

