const CATALOG_PRESET_TO_TAXONOMY_KEYS = {
  categories: ["category", "categories"],
  colors: ["color", "colors"],
  tags: ["tags"],
  priorities: ["priorities"],
  statuses: ["statuses"],
  users: ["users"]
};

function findTaxonomyDefinitionForCatalogPreset(preset, agentId = activeWorkspaceId) {
  const keys = CATALOG_PRESET_TO_TAXONOMY_KEYS[preset] || [String(preset || "").trim().toLowerCase()];
  const definitions = getAgentTaxonomyDefinitions(agentId);
  for (const definition of definitions) {
    const key = String(definition?.key || "").trim().toLowerCase();
    const slug = String(definition?.slug || "").trim().toLowerCase();
    if (keys.some((needle) => needle === key || needle === slug)) {
      return definition;
    }
  }
  return null;
}

function readPropsFormTaxonomyValue(wrap) {
  const value = {};
  for (const section of wrap.querySelectorAll("[data-taxonomy-key]")) {
    const key = String(section.dataset.taxonomyKey || "").trim();
    if (!key) continue;
    const cardinality = String(section.dataset.taxonomyCardinality || "one").trim();
    if (cardinality === "many") {
      const selected = [...section.querySelectorAll('input[type="checkbox"]:checked')]
        .map((input) => input.value)
        .filter(Boolean);
      const extra = section.querySelector(".props-form-tags-extra");
      const extraTags = String(extra?.value || "")
        .split(",")
        .map((item) => item.trim().replace(/^#+/, ""))
        .filter(Boolean);
      const merged = [...new Set([...selected, ...extraTags])];
      if (merged.length) value[key] = merged;
      continue;
    }
    const select = section.querySelector("select");
    const selected = String(select?.value || "").trim();
    if (selected) value[key] = selected;
  }
  return value;
}

function applyTaxonomyItemToPropsEntry(taxonomyKey, cardinality, itemId) {
  const index = propsFormEntries.findIndex((entry) => normalizePropsKey(entry.key) === "awn-taxonomy");
  if (index < 0 || !itemId) return;

  const entry = propsFormEntries[index];
  const value =
    entry?.kind === "taxonomy" && entry.value && typeof entry.value === "object" && !Array.isArray(entry.value)
      ? { ...entry.value }
      : {};

  if (cardinality === "many") {
    const current = normalizeTaxonomyEntryValue(value[taxonomyKey], "many");
    if (!current.includes(itemId)) value[taxonomyKey] = [...current, itemId];
  } else {
    value[taxonomyKey] = itemId;
  }

  propsFormEntries[index] = { ...entry, kind: "taxonomy", value };
}

function getTaxonomyItemPlainName(item) {
  return String(item?.name || item?.label || "").trim() || String(item?.id || "").trim();
}

function getTaxonomyItemDisplayName(item) {
  const withTree = String(item?.label ?? "").trim();
  if (withTree) return withTree;
  return getTaxonomyItemPlainName(item);
}

function getTaxonomyItemStoredId(item) {
  return String(item?.id || "").trim();
}

function buildTaxonomyParentSelectItems(items) {
  const list = Array.isArray(items) ? items.filter((item) => item?.id) : [];
  const ids = new Set(list.map((item) => item.id));
  const byParent = new Map();
  for (const item of list) {
    const pid = String(item.parent || "").trim();
    const parentKey = pid && ids.has(pid) ? pid : "";
    if (!byParent.has(parentKey)) byParent.set(parentKey, []);
    byParent.get(parentKey).push(item);
  }
  const sortSiblings = (arr) =>
    [...arr].sort((a, b) =>
      getTaxonomyItemPlainName(a).localeCompare(getTaxonomyItemPlainName(b), "ru")
    );
  const result = [];
  const walk = (parentKey, depth) => {
    for (const item of sortSiblings(byParent.get(parentKey) || [])) {
      const indent = depth > 0 ? `${"— ".repeat(depth)}` : "";
      result.push({ id: item.id, label: `${indent}${getTaxonomyItemPlainName(item)}` });
      walk(item.id, depth + 1);
    }
  };
  walk("", 0);
  for (const item of list) {
    if (!result.some((entry) => entry.id === item.id)) {
      result.push({ id: item.id, label: getTaxonomyItemPlainName(item) });
    }
  }
  return result;
}

async function submitPropsTaxonomyAdd(definition, payload) {
  const raw = typeof payload === "string" ? { code: payload } : payload || {};
  const name = String(raw.name ?? raw.title ?? "").trim();
  const codeSource = String(raw.code ?? raw.id ?? "").trim();
  const id = normalizeTaxonomyRecordCode(codeSource || name);
  if (!id) throw new Error("Некорректный код — латиница, цифры или дефис");
  const storeRel = String(definition?.storeRel || "").trim();
  if (!storeRel) throw new Error("Справочник не найден");
  const displayName = name || id;
  const parent = String(raw.parent ?? "").trim();

  const response = await fetch(buildApiUrl("/api/awn-databases/records", {}, activeWorkspaceId), {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      store: storeRel,
      id,
      name: displayName,
      title: displayName,
      parent
    })
  });
  const data = await response.json().catch(() => ({}));
  if (!response.ok) {
    throw new Error(data.details || data.error || `HTTP ${response.status}`);
  }

  applyTaxonomyItemToPropsEntry(definition.key, definition.cardinality, id);
  syncYamlFromPropsForm();
  invalidateAgentTaxonomiesCache(activeWorkspaceId);
  await loadAgentTaxonomies(activeWorkspaceId, { force: true });
  if (getDocAsideTab() === "props" && !propsRawYamlVisible) renderPropsForm();
  showToast(`Добавлено в справочник: ${displayName}`, "success");
  return data;
}

