async function saveEntryOverviewAttachmentsOrder(context, paths) {
  if (!context?.relativePath) throw new Error("Не удалось определить запись");

  const rawBody = await fetchEntryOverviewBody(context);
  const { frontmatter, body } = splitFrontmatter(rawBody);
  const entries = parsePropsYaml(frontmatter);
  const key = "awn-attachments";
  const index = entries.findIndex((entry) => normalizePropsKey(entry.key) === key);
  const base = index >= 0 ? entries[index] : { key, kind: "array", value: [] };
  const nextEntry = { ...base, key, kind: "array", value: paths };
  if (index >= 0) entries[index] = nextEntry;
  else entries.push(nextEntry);
  const nextContent = joinFrontmatter(stringifyPropsYaml(entries), body);

  if (context.memoryKind === "external") {
    const response = await fetch(buildApiUrl("/api/external/file"), {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        path: getActiveNodeApiPath(),
        file: context.relativePath,
        content: nextContent
      })
    });
    if (!response.ok) {
      const errorData = await response.json().catch(() => ({}));
      throw new Error(errorData.error || `Request failed with ${response.status}`);
    }
    await refreshExternalMemoryCaches();
    return;
  }

  if (context.memoryKind === "media" && /\.md$/i.test(context.relativePath)) {
    const response = await fetch(buildApiUrl("/api/media/markdown"), {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        path: getActiveNodeApiPath(),
        file: context.relativePath,
        content: nextContent
      })
    });
    if (!response.ok) {
      const errorData = await response.json().catch(() => ({}));
      throw new Error(errorData.error || `Request failed with ${response.status}`);
    }
    await refreshMediaCache();
    return;
  }

  if (isFlatEntryOverviewMemoryKind(context.memoryKind)) {
    const response = await fetch(buildApiUrl("/api/storage/markdown"), {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        path: getActiveNodeApiPath(),
        folder: getFlatStorageSectionFolderName(context.memoryKind),
        file: context.relativePath,
        content: nextContent
      })
    });
    if (!response.ok) {
      const errorData = await response.json().catch(() => ({}));
      throw new Error(errorData.error || `Request failed with ${response.status}`);
    }
    await reloadFlatStorageFolderMode(context.memoryKind);
    return;
  }

  throw new Error("Сортировка недоступна для этого типа записи");
}

async function applyPropsAttachmentsOrder(list, paths, options = {}) {
  const { wrap, persist = "form", context } = options;
  if (wrap) {
    syncPropsAttachmentsHiddenInput(wrap, paths);
    syncPropsAttachmentsEntryFromWrap(wrap);
  }
  if (persist !== "entryOverview" || !context) return;
  await saveEntryOverviewAttachmentsOrder(context, paths);
}

function setupPropsAttachmentsListSort(list, options = {}) {
  if (!list || options.sortable === false) return;
  if (list.dataset.sortBound === "1") return;
  list.dataset.sortBound = "1";
  list.classList.add("is-attachments-sortable");

  list.addEventListener("dragstart", (event) => {
    const handle = event.target.closest(".props-form-attachment-sort-handle");
    if (!handle) return;
    const item = handle.closest(".props-form-attachment-sort-row");
    if (!item) {
      event.preventDefault();
      return;
    }
    propsAttachmentSortDragItem = item;
    item.classList.add("is-dragging");
    event.dataTransfer.effectAllowed = "move";
    event.dataTransfer.setData("text/plain", item.dataset.path || "");
  });

  list.addEventListener("dragover", (event) => {
    if (!propsAttachmentSortDragItem) return;
    event.preventDefault();
    event.dataTransfer.dropEffect = "move";
    const targetItem = event.target.closest(".props-form-attachment-sort-row");
    if (!targetItem || targetItem === propsAttachmentSortDragItem) return;
    const rect = targetItem.getBoundingClientRect();
    const insertBefore = event.clientY < rect.top + rect.height / 2;
    if (insertBefore) list.insertBefore(propsAttachmentSortDragItem, targetItem);
    else list.insertBefore(propsAttachmentSortDragItem, targetItem.nextSibling);
  });

  list.addEventListener("drop", async (event) => {
    event.preventDefault();
    if (!propsAttachmentSortDragItem) return;
    propsAttachmentSortDragItem.classList.remove("is-dragging");
    propsAttachmentSortDragItem = null;
    const paths = getPropsAttachmentPathsFromList(list);
    try {
      await applyPropsAttachmentsOrder(list, paths, options);
      if (options.persist === "entryOverview") {
        showToast("Порядок вложений сохранён", "success");
      }
    } catch (error) {
      showToast(`Не удалось сохранить порядок: ${error.message}`, "error");
    }
  });

  list.addEventListener("dragend", () => {
    if (!propsAttachmentSortDragItem) return;
    propsAttachmentSortDragItem.classList.remove("is-dragging");
    propsAttachmentSortDragItem = null;
  });
}

function buildAttachmentMarkdownSnippet(path, { mode = "embed", label = "" } = {}) {
  const canonical = toCanonicalAssetsUploadRef(path, ATTACHMENTS_ASSETS_SUBDIR);
  if (!canonical) return "";
  const href = formatAttachmentPathForVariant(canonical);
  const fileName = canonical.split("/").pop() || "file";
  const displayLabel =
    String(label || "").trim() ||
    getAttachmentDisplayLabelFromPath(path) ||
    getAttachmentAltText(fileName);
  const safeLabel = displayLabel.replace(/[[\]]/g, "");
  if (mode === "embed" && ATTACHMENTS_IMAGE_EXT_RE.test(fileName)) {
    return `\n![${safeLabel}](${href})\n`.trim();
  }
  return `[${safeLabel}](${href})`;
}

function resolveAttachmentMediaRelPath(path) {
  const raw = String(path || "").trim().replace(/\\/g, "/");
  if (!raw) return "";
  const storageRef = normalizeNodeAssetsStorageRef(raw);
  if (STORAGE_ASSETS_PATH_PREFIX_RE.test(storageRef)) {
    return stripStorageAssetsPrefix(storageRef).replace(/^assets\//i, "assets/");
  }
  if (/^assets\//i.test(raw)) return raw.replace(/^\/+/, "");
  if (/^attachments\//i.test(raw)) return `${STORAGE_SUBFOLDER_ASSETS}/${raw.replace(/^\/+/, "")}`;
  return stripStorageAssetsPrefix(storageRef).replace(/^assets\//i, "assets/") || raw.replace(/^assets\//i, "");
}

const attachmentSidecarMetaCache = new Map();
let attachmentSidecarModalPath = null;

function invalidateAttachmentSidecarMeta(path) {
  attachmentSidecarMetaCache.delete(String(path || ""));
}

function getAttachmentDisplayLabelFromPath(path, meta = null) {
  const fromMeta = String(meta?.name || "").trim();
  if (fromMeta) return fromMeta;
  const cached = attachmentSidecarMetaCache.get(String(path || ""));
  if (cached?.name) return cached.name;
  const fileName = String(path || "").split("/").pop() || "";
  return getAttachmentAltText(fileName);
}

function buildAttachmentSidecarApiParams(mediaRel) {
  return {
    path: resolveManifestPathForNodeApi(getResolvedNodePath(activePath)),
    contextPath: getUploadStorageContextPath(),
    file: mediaRel
  };
}

function buildTopicMediaSidecarApiParams(mediaFilePath, nodePath = activePath, options = {}) {
  const manifestPath = resolveManifestPathForNodeApi(getResolvedNodePath(nodePath));
  const params = {
    path: manifestPath,
    contextPath: manifestPath,
    file: String(mediaFilePath || "").replace(/\\/g, "/")
  };
  if (options.create) params.create = "1";
  const title = String(options.title || "").trim();
  if (title) params.title = title;
  return params;
}

function buildDefaultMediaSidecarContent(sourceFilePath) {
  const fileName = String(sourceFilePath || "").split("/").pop() || "Медиа";
  const dot = fileName.lastIndexOf(".");
  const base = dot > 0 ? fileName.slice(0, dot) : fileName;
  const safeName = String(base || "Медиа").trim() || "Медиа";
  const quotedName = /[:#\[\]{}&,*?]|^\s|\s$/.test(safeName)
    ? `"${safeName.replace(/\\/g, "\\\\").replace(/"/g, '\\"')}"`
    : safeName;
  return `---\nawn-type: awn.annotation.sidecar\nawn-name: ${quotedName}\n---\n\n`;
}

async function fetchAttachmentSidecarMeta(path) {
  const key = String(path || "");
  if (attachmentSidecarMetaCache.has(key)) {
    return attachmentSidecarMetaCache.get(key);
  }
  const mediaRel = resolveAttachmentMediaRelPath(path);
  if (!mediaRel) return null;
  if (!getUploadStorageContextPath()) return null;
  try {
    const response = await fetch(
      buildApiUrl("/api/media/sidecar", buildAttachmentSidecarApiParams(mediaRel))
    );
    if (!response.ok) return null;
    const data = await response.json();
    const entries = parsePropsYaml(splitFrontmatter(data.content || "").frontmatter);
    const meta = {
      name: getPropsEntryValueByKey(entries, "awn-name"),
      description: getPropsEntryValueByKey(entries, "awn-description"),
      mediaRel,
      sourceFile: data.sourceFile || mediaRel,
      content: data.content || "",
      exists: Boolean(data.exists)
    };
    attachmentSidecarMetaCache.set(key, meta);
    return meta;
  } catch {
    return null;
  }
}

function buildAttachmentSidecarContent(originalFileName, existingContent = "") {
  const now = new Date().toISOString();
  const displayName = String(originalFileName || "").trim();
  if (existingContent.trim()) {
    const { frontmatter, body } = splitFrontmatter(existingContent);
    const entries = parsePropsYaml(frontmatter);
    const map = new Map(entries.map((entry) => [entry.key, entry]));
    if (displayName) {
      map.set("awn-name", { key: "awn-name", kind: "string", value: displayName });
    }
    if (!map.has("awn-type")) {
      map.set("awn-type", { key: "awn-type", kind: "string", value: "awn.sidecar" });
    }
    if (!map.has("awn-create")) {
      map.set("awn-create", { key: "awn-create", kind: "string", value: now });
    }
    map.set("awn-update", { key: "awn-update", kind: "string", value: now });
    return joinFrontmatter(stringifyPropsYaml([...map.values()]), body);
  }
  const lines = [
    "awn-type: awn.sidecar",
    displayName ? `awn-name: ${formatYamlScalar(displayName)}` : 'awn-name: ""',
    'awn-description: ""',
    `awn-create: ${now}`,
    `awn-update: ${now}`
  ];
  return joinFrontmatter(lines.join("\n"), "");
}

async function ensureAttachmentSidecar(path, originalFileName) {
  const mediaRel = resolveAttachmentMediaRelPath(path);
  if (!mediaRel || !getUploadStorageContextPath()) return;
  try {
    const response = await fetch(
      buildApiUrl("/api/media/sidecar", buildAttachmentSidecarApiParams(mediaRel))
    );
    const data = response.ok ? await response.json() : null;
    if (data?.exists && data.content?.trim()) {
      invalidateAttachmentSidecarMeta(path);
      return;
    }
    const content = buildAttachmentSidecarContent(originalFileName, data?.content || "");
    const saveResponse = await fetch(buildApiUrl("/api/media/sidecar"), {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ ...buildAttachmentSidecarApiParams(mediaRel), content })
    });
    if (!saveResponse.ok) {
      throw new Error("Failed to save sidecar");
    }
    invalidateAttachmentSidecarMeta(path);
  } catch {
    // Sidecar is optional metadata — upload still succeeds.
  }
}

async function saveAttachmentSidecarProps(path, { name, description }) {
  const mediaRel = resolveAttachmentMediaRelPath(path);
  if (!mediaRel || !getUploadStorageContextPath()) throw new Error("Не удалось определить путь");

  let existingContent = "";
  const response = await fetch(
    buildApiUrl("/api/media/sidecar", buildAttachmentSidecarApiParams(mediaRel))
  );
  if (response.ok) {
    const data = await response.json();
    existingContent = data.content || "";
  }

  const { frontmatter, body } = splitFrontmatter(existingContent);
  const entries = parsePropsYaml(frontmatter);
  const map = new Map(entries.map((entry) => [entry.key, entry]));
  map.set("awn-type", { key: "awn-type", kind: "string", value: "awn.sidecar" });
  map.set("awn-name", { key: "awn-name", kind: "string", value: String(name || "").trim() });
  map.set("awn-description", {
    key: "awn-description",
    kind: "string",
    value: String(description || "").trim()
  });
  if (!map.has("awn-create")) {
    map.set("awn-create", { key: "awn-create", kind: "string", value: new Date().toISOString() });
  }
  map.set("awn-update", { key: "awn-update", kind: "string", value: new Date().toISOString() });
  const content = joinFrontmatter(stringifyPropsYaml([...map.values()]), body);

  const saveResponse = await fetch(buildApiUrl("/api/media/sidecar"), {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ ...buildAttachmentSidecarApiParams(mediaRel), content })
  });
  if (!saveResponse.ok) {
    const errorData = await saveResponse.json().catch(() => ({}));
    throw new Error(errorData.error || `Request failed with ${saveResponse.status}`);
  }
  invalidateAttachmentSidecarMeta(path);
}

