function readPropsFormValueFromControl(valueWrap) {
  const widget = valueWrap?.dataset?.widget || "text";
  if (widget === "preview") {
    const hidden = valueWrap.querySelector(".props-form-preview-value");
    return hidden?.value ?? "";
  }
  if (widget === "attachments") {
    return getPropsAttachmentsPathsFromWrap(valueWrap).join(", ");
  }
  if (widget === "enum-checkbox") {
    return [...valueWrap.querySelectorAll('input[type="checkbox"]:checked')]
      .map((input) => input.value)
      .filter(Boolean)
      .join(", ");
  }
  if (widget === "select-multiple") {
    return [...valueWrap.querySelectorAll("select option:checked")]
      .map((option) => option.value)
      .filter(Boolean)
      .join(", ");
  }
  if (widget === "radio") {
    const checked = valueWrap.querySelector('input[type="radio"]:checked');
    return checked?.value ?? "";
  }
  if (widget === "boolean") {
    const checkbox = valueWrap.querySelector('input[type="checkbox"]');
    return checkbox?.checked ? "true" : "false";
  }
  if (widget === "runtime-schedule-type") {
    const select = valueWrap.querySelector("select");
    return select?.value ?? "";
  }
  if (widget === "taxonomy") {
    return readPropsFormTaxonomyValue(valueWrap);
  }
  if (widget === "object-group") {
    return readPropsFormObjectGroupValue(valueWrap);
  }
  if (isLookupManyWidget(widget)) {
    const fromCheckboxes = [...valueWrap.querySelectorAll('input[type="checkbox"]:checked')]
      .map((input) => input.value)
      .filter(Boolean);
    const extra = valueWrap.querySelector(".props-form-tags-extra");
    const extraTags = String(extra?.value || "")
      .split(",")
      .map((item) => item.trim().replace(/^#+/, ""))
      .filter(Boolean);
    return [...new Set([...fromCheckboxes, ...extraTags])].join(", ");
  }
  if (widget === "relation" || widget === "link") {
    const select = valueWrap.querySelector("select");
    const manual = valueWrap.querySelector("[data-link-manual]");
    const manualValue = String(manual?.value || "").trim();
    const selectValue = String(select?.value || "").trim();
    return manualValue || selectValue;
  }
  if (widget === "path") {
    const input = valueWrap.querySelector(".props-form-ws-path-value, .props-form-value");
    return String(input?.value || "").trim();
  }
  if (widget === "file") {
    if (valueWrap.dataset.fileMultiple === "1") {
      const hidden = valueWrap.querySelector(".props-form-file-value");
      const raw = String(hidden?.value || "").trim();
      if (!raw) return [];
      try {
        const parsed = JSON.parse(raw);
        return Array.isArray(parsed) ? parsed : [];
      } catch {
        return raw
          .split(",")
          .map((item) => item.trim())
          .filter(Boolean);
      }
    }
    const select = valueWrap.querySelector("select");
    const manual = valueWrap.querySelector("[data-file-manual]");
    const hidden = valueWrap.querySelector(".props-form-file-value");
    const manualValue = String(manual?.value || "").trim();
    const selectValue = String(select?.value || "").trim();
    const hiddenValue = String(hidden?.value || "").trim();
    return manualValue || selectValue || hiddenValue;
  }
  if (isLookupOneWidget(widget) && valueWrap.querySelector(".props-form-color-custom")) {
    const custom = valueWrap.querySelector(".props-form-color-custom");
    const customValue = String(custom?.value || "").trim();
    if (customValue) return customValue;
    const select = valueWrap.querySelector("select");
    return String(select?.value || "").trim();
  }
  if (widget === "cron-schedule") {
    const mode = valueWrap.querySelector(".props-form-cron-mode")?.value;
    if (mode && mode !== "custom") {
      return buildCronScheduleExpression(readPropsFormCronScheduleState(valueWrap));
    }
    const input = valueWrap.querySelector(".props-form-cron-expression");
    return String(input?.value || "").trim();
  }
  if (widget === "coordinates") {
    const latInput = valueWrap.querySelector(".props-form-value--coordinates-lat");
    const lngInput = valueWrap.querySelector(".props-form-value--coordinates-lng");
    return formatCoordinatesFieldValue({
      lat: latInput?.value ?? "",
      lng: lngInput?.value ?? ""
    });
  }
  if (widget === "stars") {
    const hidden = valueWrap.querySelector(".props-form-stars-value");
    return String(hidden?.value ?? "").trim();
  }
  if (widget === "importance") {
    const hidden = valueWrap.querySelector(".props-form-importance-value");
    return String(hidden?.value ?? "").trim();
  }
  if (widget === "repeater" && valueWrap.querySelector(".props-form-repeater-items")) {
    return readPropsFormRepeaterValue(valueWrap);
  }
  if (widget === "select" || widget === "lookup-one" || isLookupOneWidget(widget)) {
    const select = valueWrap.querySelector("select");
    return select?.value ?? "";
  }
  const control = valueWrap.querySelector(".props-form-value, textarea.props-form-value");
  return control?.value ?? "";
}

function syncRuntimePropsFormVisibility() {
  if (!propsFormFieldsNode) return;
  const scheduleRow = propsFormFieldsNode.querySelector('[data-prop-key="awn-runtime-cron-schedule"]');
  if (!scheduleRow) return;

  const scheduleType = getRuntimeScheduleTypeFromForm();
  const isRecurring = scheduleType === "recurring";
  const isScheduled = scheduleType === "scheduled";

  scheduleRow.classList.toggle("hidden", !isRecurring && !isScheduled);

  const scheduleWrap = scheduleRow.querySelector(".props-form-value-wrap--cron-schedule");
  const recurringShell = scheduleWrap?.querySelector(".props-form-runtime-recurring");
  const scheduledShell = scheduleWrap?.querySelector(".props-form-runtime-scheduled");
  recurringShell?.classList.toggle("hidden", !isRecurring);
  scheduledShell?.classList.toggle("hidden", !isScheduled);
}

function createPropsFormFieldRow(entry, index, { showFieldKey = false, editorCompact = false } = {}) {
  const meta = getPropsFieldMeta(entry.key);
  const normalizedKey = normalizePropsKey(entry.key);
  const fieldWidget = resolvePropsFieldWidget(entry.key, meta.fieldDef);
  const isPreviewField = fieldWidget === "preview";
  const isTaxonomyField = fieldWidget === "taxonomy";
  const isObjectGroupField = fieldWidget === "object-group";
  const isAttachmentsField = normalizedKey === "awn-attachments";
  const isCronScheduleField = normalizedKey === "awn-runtime-cron-schedule";
  const row = document.createElement("div");
  row.className = "props-form-row props-form-field props-form-field--compact";
  if (isPreviewField) row.classList.add("props-form-field--preview");
  if (isTaxonomyField) row.classList.add("props-form-field--taxonomy");
  if (isAttachmentsField) row.classList.add("props-form-field--attachments");
  if (isCronScheduleField) row.classList.add("props-form-field--cron-schedule");
  if (isObjectGroupField) row.classList.add("props-form-field--object-group");
  row.dataset.index = String(index);
  if (entry.key) row.dataset.propKey = entry.key;

  const head = document.createElement("div");
  head.className = "props-form-field-head";

  if (entry.key && !isPreviewField && !isCronScheduleField && !isTaxonomyField && !isObjectGroupField) {
    const label = showFieldKey
      ? buildPropsFieldKeyLabelElement(entry.key, meta, { required: meta.required })
      : buildFieldLabelElement(meta.label || entry.key, {
          tag: "label",
          className: "props-form-field-label",
          typeId: meta.typeId || meta.fieldDef?.type,
          key: entry.key,
          required: meta.required
        });
    if (!showFieldKey) {
      bindPropsFormFieldLabelInteractions(label, entry.key, meta);
    }
    head.appendChild(label);
  } else if (!entry.key) {
    const keyInput = document.createElement("input");
    keyInput.type = "text";
    keyInput.className = "props-form-key-input";
    keyInput.placeholder = "ключ";
    keyInput.value = "";
    keyInput.dataset.field = "key";
    head.appendChild(keyInput);
  }

  const valueControl = createPropsFormValueControl(entry, meta, { editorCompact });
  if (isPreviewField || isCronScheduleField || isTaxonomyField || isObjectGroupField) {
    row.append(valueControl);
  } else {
    row.append(head, valueControl);
  }

  const needsTaxonomies =
    activeWorkspaceId &&
    !getAgentTaxonomiesCache(activeWorkspaceId) &&
    (isLookupFieldWidget(fieldWidget) || fieldWidget === "taxonomy");
  if (needsTaxonomies) {
    void loadAgentTaxonomies(activeWorkspaceId);
  }

  return row;
}

function setPropsYamlContent(content, { preserveRawMode = false, skipRender = false } = {}) {
  propsInputNode.value = content || "";
  absorbPropsYamlEntries(parsePropsYaml(content || ""));
  if (!preserveRawMode) {
    syncYamlFromPropsForm();
    propsRawYamlVisible = false;
    propsInputNode.classList.add("hidden");
    setPropsYamlToggleLabel("Показать YAML");
  }
  if (skipRender) {
    syncTitleDescriptionFromNode(getActiveTitleEditorPath());
    syncTitleIdFromNode(getActiveTitleEditorPath());
    return;
  }
  if (shouldRenderPropsFormNow()) {
    renderPropsForm();
  } else {
    renderEditorCustomPropsBar();
    if (propsFormFieldsNode) {
      // Панель «Свойства» не отрисована — очищаем DOM, чтобы save не прочитал устаревшие поля другой темы.
      propsFormFieldsNode.replaceChildren();
    }
  }
  syncTitleDescriptionFromNode(getActiveTitleEditorPath());
  syncTitleIdFromNode(getActiveTitleEditorPath());
}

function isPropsFormDomMounted() {
  if (propsRawYamlVisible) return false;
  return getPropsFormFieldContainers().some(
    (container) => container.querySelectorAll(".props-form-row").length > 0
  );
}

function readPropsFormRowEntry(row, baseEntry) {
  const index = Number(row.dataset.index);
  const keyInput = row.querySelector('[data-field="key"]');
  const valueWrap = row.querySelector('.props-form-value-wrap[data-field="value"]');
  const valueInput = row.querySelector('input[data-field="value"]:not([data-link-manual])');
  const keyCode = row.querySelector(".props-form-field-key");
  const base = baseEntry || { kind: "string", value: "" };
  const key = normalizePropsKey(
    keyInput
      ? keyInput.value.trim()
      : (row.dataset.propKey || keyCode?.textContent || base.key || "").trim()
  );
  let entry = { ...base, key };
  const fieldDef = getPropsFieldDef(key);
  if (fieldDef) {
    entry.kind = fieldDefToEntryKind(fieldDef);
  }
  if (valueWrap) {
    const widget = valueWrap.dataset.widget || "";
    entry = applyPropsFormWidgetValue(entry, readPropsFormValueFromControl(valueWrap), widget);
    entry.key = key;
  } else if (valueInput) {
    entry = applyFormValueToEntry(entry, valueInput.value);
    entry.key = key;
  }
  return { index, entry };
}

function readPropsFormIntoEntries() {
  const rows = getPropsFormFieldContainers().flatMap((container) =>
    container ? [...container.querySelectorAll(".props-form-row")] : []
  );

  let nextEntries = propsFormEntries.map((entry) => ({ ...entry }));

  for (const row of rows) {
    const index = Number(row.dataset.index);
    const base =
      Number.isFinite(index) && index >= 0
        ? nextEntries[index] || propsFormEntries[index] || { kind: "string", value: "" }
        : { kind: "string", value: "" };
    const { entry } = readPropsFormRowEntry(row, base);
    if (Number.isFinite(index) && index >= 0) {
      while (nextEntries.length <= index) {
        nextEntries.push({ key: "", kind: "string", value: "" });
      }
      nextEntries[index] = entry;
    } else if (entry.key || getPropsEntryDisplayValue(entry).trim()) {
      nextEntries.push(entry);
    }
  }

  propsFormEntries = mergePropsPreviewIntoEntries(nextEntries);
  propsFormEntries = mergePropsWebUrlIntoEntries(propsFormEntries);
  propsFormEntries = mergePropsAttachmentsIntoEntries(propsFormEntries);
  propsFormEntries = mergePropsMaterialsIntoEntries(propsFormEntries);
}

function mergePropsAsideHeroBlocksIntoEntries(entries = propsFormEntries) {
  let next = mergePropsPreviewIntoEntries(entries);
  next = mergePropsWebUrlIntoEntries(next);
  next = mergePropsAttachmentsIntoEntries(next);
  next = mergePropsMaterialsIntoEntries(next);
  return normalizePropsEntriesAssetRefs(next);
}

function togglePropsRawYaml() {
  if (isPropsFormReadOnly()) return;
  if (propsRawYamlVisible) {
    absorbPropsYamlEntries(parsePropsYaml(propsInputNode.value || ""));
    propsRawYamlVisible = false;
    propsInputNode.classList.add("hidden");
    setPropsYamlToggleLabel("Показать YAML");
    propsYamlToggleBtn?.classList.remove("active");
    renderPropsForm();
    return;
  }

  readPropsFormIntoEntries();
  syncYamlFromPropsForm();
  propsRawYamlVisible = true;
  propsInputNode.classList.remove("hidden");
  setPropsYamlToggleLabel("Скрыть YAML");
  propsYamlToggleBtn?.classList.add("active");
}

function splitFrontmatter(raw = "") {
  const text = String(raw).replace(/^\uFEFF/, "");
  const match = text.match(/^---\r?\n([\s\S]*?)\r?\n---(?:\r?\n|$)([\s\S]*)$/);
  if (!match) return { frontmatter: "", body: text };
  return {
    frontmatter: match[1],
    body: match[2].replace(/^\r?\n?/, "")
  };
}

function joinFrontmatter(frontmatter, body) {
  const fm = String(frontmatter ?? "").trim();
  const mdBody = String(body ?? "");
  if (!fm) return mdBody;
  if (!mdBody) return `---\n${fm}\n---\n`;
  return `---\n${fm}\n---\n\n${mdBody}`;
}

function refreshSystemFileFrontmatterCacheFromSource() {
  if (!activeSystemFile || !systemFileHasEditableFrontmatter(activeSystemFile)) {
    systemFileFrontmatterCache = "";
    return;
  }
  systemFileFrontmatterCache = splitFrontmatter(fileContentInputNode?.value || "").frontmatter;
}

function getSystemFileWysiwygBodyMarkdown() {
  refreshSystemFileFrontmatterCacheFromSource();
  return splitFrontmatter(fileContentInputNode?.value || "").body;
}

function joinSystemFileWysiwygBodyWithFrontmatter(bodyMarkdown) {
  if (!activeSystemFile || !systemFileHasEditableFrontmatter(activeSystemFile)) {
    return String(bodyMarkdown ?? "");
  }
  return joinFrontmatter(systemFileFrontmatterCache, bodyMarkdown);
}

function stripDefaultManifestHeading(body, titleHint = "") {
  let text = String(body ?? "");
  if (!text.trim()) return text;

  const lines = text.replace(/^\uFEFF/, "").split("\n");
  let index = 0;
  while (index < lines.length && !lines[index].trim()) index += 1;
  if (index >= lines.length) return text;

  const headingMatch = lines[index].trim().match(/^#\s+(.+)$/);
  if (!headingMatch) return text;

  const title = String(titleHint || "").trim();
  if (title) {
    const headingText = headingMatch[1].trim().replace(/^["']|["']$/g, "");
    if (headingText.localeCompare(title, "ru", { sensitivity: "accent" }) !== 0) {
      return text;
    }
  }

  lines.splice(index, 1);
  while (index < lines.length && !lines[index].trim()) {
    lines.splice(index, 1);
  }
  return lines.join("\n");
}

function applyNodeManifestBody(rawContent) {
  const { frontmatter, body } = splitFrontmatter(rawContent || "");
  const titleHint =
    getNodeDisplayTitleFromFrontmatter(activePath, frontmatter) ||
    titleInputNode?.value?.trim() ||
    "";
  fileContentInputNode.value = stripDefaultManifestHeading(body, titleHint);
}

function normalizePropsEntriesAssetRefs(entries) {
  return entries.map((entry) => {
    const key = normalizePropsKey(entry.key);
    if (key === "awn-preview") {
      const raw = getPropsEntryValueByKey([entry], key);
      const normalized = formatInlineAssetPathForEditor(
        toCanonicalAssetsUploadRef(raw, PREVIEW_ASSETS_SUBDIR)
      );
      return normalized ? applyFormValueToEntry(entry, normalized) : entry;
    }
    if (key === "awn-attachments" && entry.kind === "array") {
      const paths = parsePropsAttachmentsValue(entry);
      const normalized = paths
        .map((itemPath) => normalizeAttachmentRefForCompare(itemPath) || itemPath)
        .filter(Boolean);
      return { ...entry, value: normalized };
    }
    return entry;
  });
}

function flushPropsYamlFromFormBeforeSave() {
  syncDescriptionIntoAwnDescriptionProp();
  if (propsRawYamlVisible) {
    absorbPropsYamlEntries(parsePropsYaml(propsInputNode.value || ""));
  } else if (isPropsFormDomMounted()) {
    readPropsFormIntoEntries();
    propsFormEntries = normalizePropsEntriesAssetRefs(propsFormEntries);
  } else {
    propsFormEntries = mergePropsAsideHeroBlocksIntoEntries(propsFormEntries);
  }
  syncYamlFromPropsForm();
}

function buildNodeManifestContent() {
  if (isAwnDatabaseCsvRecordContentPath(getResolvedNodePath(activePath))) {
    return fileContentInputNode.value || "";
  }
  syncDisplayNameIntoAwnNameProp(activePath);
  syncDescriptionIntoAwnDescriptionProp(activePath);
  flushPropsYamlFromFormBeforeSave();
  return joinFrontmatter(propsInputNode.value, fileContentInputNode.value);
}

async function ensureTopicSchemaForActiveContext(options = {}) {
  const manifestPath = getTopicSchemaManifestPath();
  const contentPath =
    options.contentPath !== undefined
      ? String(options.contentPath || "").replace(/\\/g, "/").replace(/^\/+/, "")
      : getSchemaContentPathForContext();
  if (!manifestPath) return null;
  if (
    isAwnDatabaseSchemaContext(manifestPath) ||
    (contentPath && isAwnDatabaseEditableRecordPath(contentPath))
  ) {
    return loadAwnDatabaseTopicSchemaForManifest(manifestPath, {
      contentPath,
      force: options.force === true
    }).catch(() => null);
  }
  if (!contentPath) {
    const shouldLoadManifestSchema =
      activeContentMode === "topic-schema" ||
      activeContentMode === NODE_OVERVIEW_MODE ||
      activeContentMode === NODE_NAVIGATION_MODE ||
      isNodeSettingsSelectMode(activeContentMode) ||
      isWorkspaceSchemaContext(manifestPath) ||
      isAreaSchemaContext(manifestPath);
    if (shouldLoadManifestSchema) {
      return loadTopicSchemaForManifest(manifestPath, {
        topicOnly: true,
        force: options.force === true
      }).catch(() => null);
    }
    return null;
  }
  return loadTopicSchemaForManifest(manifestPath, {
    contentPath,
    force: options.force === true
  }).catch(() => null);
}

function applyExternalFileContentUi(rawContent) {
  return applyStorageFileContentUi(rawContent, { mode: "external" });
}

function applyMediaSidecarContentUi(rawContent) {
  return applyStorageFileContentUi(rawContent, { mode: "media" });
}

async function applyStorageFileContentUi(rawContent, { mode = "external" } = {}) {
  await Promise.all([
    loadAwnTypes(activeWorkspaceId).catch(() => null),
    ensureTopicSchemaForActiveContext()
  ]);
  const { frontmatter, body } = splitFrontmatter(rawContent);
  if (mode === "external") {
    const recordPath = activeExternalFilePath || activeFlatStorageFilePath;
    const titleHint =
      getNodeDisplayTitleFromFrontmatter(recordPath, frontmatter) ||
      titleInputNode?.value?.trim() ||
      "";
    setPropsYamlContent(frontmatter);
    fileContentInputNode.value = stripDefaultManifestHeading(body, titleHint);
    if (shouldRefreshPropsFormFromYaml()) {
      absorbPropsYamlEntries(parsePropsYaml(propsInputNode.value || ""));
      syncYamlFromPropsForm();
      renderPropsForm();
    }
    return;
  }
  if (mode === "flat-plain") {
    setPropsYamlContent("");
    fileContentInputNode.value = rawContent || "";
    return;
  }
  setPropsYamlContent(frontmatter);
  fileContentInputNode.value = body;
  if (shouldRefreshPropsFormFromYaml()) {
    absorbPropsYamlEntries(parsePropsYaml(propsInputNode.value || ""));
    syncYamlFromPropsForm();
    renderPropsForm();
  }
  if (editorViewMode === "preview") {
    renderPreviewFromEditor();
  }
}

