async function createSlotRecordFileWithMask(fileMask, displayName = "", folderOverride = null, options = {}) {
  const folder = folderOverride || getActiveSlotRecordCreateFolder();
  if (!folder) throw new Error("No active storage slot");
  const createMode = getActiveSlotRecordCreateMode();
  const parentFolder = getActiveSlotRecordCreateParentFolder(createMode, folder);
  const requestBody = {
    path: getSlotRecordCreateManifestApiPath(),
    folder,
    fileMask
  };
  const title = String(displayName || "").trim();
  if (title) {
    requestBody.title = title;
    requestBody.displayName = title;
  }
  const descriptionFields = buildCreateMemoryDescriptionFields(options.description);
  if (descriptionFields) requestBody.fields = descriptionFields;
  if (parentFolder) requestBody.parent = parentFolder;
  const response = await fetch(buildApiUrl("/api/storage/file/create"), {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(requestBody)
  });
  if (!response.ok) {
    const errorData = await response.json().catch(() => ({}));
    const reason = errorData.error || `Request failed with ${response.status}`;
    const details = errorData.details ? `: ${errorData.details}` : "";
    throw new Error(`${reason}${details}`);
  }
  return response.json();
}

async function createSlotRecordFile(displayName, slug, folderOverride = null, options = {}) {
  const folder = folderOverride || getActiveSlotRecordCreateFolder();
  if (!folder) throw new Error("No active storage slot");
  const createMode = getActiveSlotRecordCreateMode();
  const parentFolder = getActiveSlotRecordCreateParentFolder(createMode, folder);
  const requestBody = {
    path: getSlotRecordCreateManifestApiPath(),
    folder,
    title: displayName,
    displayName,
    slug
  };
  const descriptionFields = buildCreateMemoryDescriptionFields(options.description);
  if (descriptionFields) requestBody.fields = descriptionFields;
  if (parentFolder) requestBody.parent = parentFolder;
  const fileExtension = getCreateMemoryFileExtension();
  if (fileExtension) requestBody.fileExtension = fileExtension;
  const response = await fetch(buildApiUrl("/api/storage/file/create"), {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(requestBody)
  });
  if (!response.ok) {
    const errorData = await response.json().catch(() => ({}));
    const reason = errorData.error || `Request failed with ${response.status}`;
    const details = errorData.details ? `: ${errorData.details}` : "";
    throw new Error(`${reason}${details}`);
  }
  return response.json();
}

/** @deprecated use createSlotRecordFile */
async function createExternalMemoryFileWithMask(fileMask, displayName = "") {
  return createSlotRecordFileWithMask(fileMask, displayName, "main");
}

/** @deprecated use createSlotRecordFile */
async function createExternalMemoryFile(displayName, slug) {
  return createSlotRecordFile(displayName, slug, "main");
}

async function createExternalMemory() {
  if (!canCreateSlotRecordNow()) return;

  if (shouldUseCreateMemoryMaskFlow()) {
    setCreateMemoryModalBusy(true);
    createMemoryOkBtn.textContent = "Создаю...";
    try {
      const data = await createSlotRecordFileWithMask(
        activeCreateMemoryMask,
        getCreateMemoryMaskName(),
        null,
        { description: createMemoryDescriptionInputNodes[0]?.value?.trim() || "" }
      );
      persistCreateMemoryAfterChoice();
      persistCreateMemoryFormatChoice();
      const openForEdit = shouldOpenCreatedMemoryForEdit();
      closeCreateMemoryModal();
      await refreshAfterExternalWorkspaceCreate({ openForEdit });
      if (data.file && openForEdit) {
        await openCreatedExternalMemoryForEdit(data.file);
      }
      showToast("Запись создана", "success");
    } catch (error) {
      showToast(error?.message || "Ошибка создания записи", "error");
    } finally {
      setCreateMemoryModalBusy(false);
      createMemoryOkBtn.textContent = "Создать";
    }
    return;
  }

  const items = getCreateMemoryItems();
  if (!items.length) {
    showToast("Введите хотя бы одно название", "error");
    return;
  }

  setCreateMemoryModalBusy(true);
  let created = 0;
  let lastFile = null;
  let lastCreateError = null;

  try {
    for (let index = 0; index < items.length; index += 1) {
      const { displayName, slug, description } = items[index];
      createMemoryOkBtn.textContent =
        items.length === 1 ? "Создаю..." : `Создаю ${index + 1} из ${items.length}...`;
      try {
        const data = await createSlotRecordFile(displayName, slug, null, { description });
        created += 1;
        lastFile = data.file;
      } catch (error) {
        lastCreateError = error;
        // continue with remaining titles
      }
    }

    if (created > 0) {
      persistCreateMemoryAfterChoice();
      persistCreateMemoryFormatChoice();
      const openForEdit = shouldOpenCreatedMemoryForEdit();
      closeCreateMemoryModal();
      await refreshAfterExternalWorkspaceCreate({ openForEdit });
      if (lastFile && openForEdit) {
        await openCreatedExternalMemoryForEdit(lastFile);
      }
    }

    if (created === items.length) {
      showToast(
        created === 1 ? "Запись создана" : `Создано записей: ${created}`,
        "success"
      );
    } else if (created > 0) {
      showToast(`Создано ${created} из ${items.length}`, "error");
    } else {
      showToast(lastCreateError?.message || "Ошибка создания записей", "error");
    }
  } finally {
    setCreateMemoryModalBusy(false);
    createMemoryOkBtn.textContent = "Создать";
  }
}

let createSectionTargetMode = "external";
let createSectionParentFolder = null;

function getActiveMediaSectionParentForCreate() {
  if (navigationHubRailSlotCreateState && isMediaLibraryContentMode(navigationHubRailSlotCreateState.targetMode)) {
    return navigationHubRailSlotCreateState.parentFolder ?? null;
  }
  if (!isStorageSectionsPanelVisible()) return null;
  if (activeMediaSectionFolder) return activeMediaSectionFolder;
  const route = parseAppRoute(location.pathname);
  if (route.view === activeContentMode && route.mediaSectionPath) {
    return route.mediaSectionPath;
  }
  return null;
}

function buildCreatedMediaSectionPath(parentFolder, sectionName, sectionPathFromApi = "") {
  const apiPath = String(sectionPathFromApi || "").trim().replace(/\\/g, "/").replace(/\/$/, "");
  if (apiPath) return apiPath;
  const section = String(sectionName || "").trim().replace(/\\/g, "/").replace(/\/$/, "");
  if (!section) return "";
  const parent = String(parentFolder || "").trim().replace(/\\/g, "/").replace(/\/$/, "");
  return parent ? `${parent}/${section}` : section;
}

function openCreateSectionModal(targetMode = "external", { entryOverviewContext = null } = {}) {
  if (!activePath) return;
  if (targetMode === "external") {
    const fromEntryOverview =
      entryOverviewContext || (isEntryOverviewExternalMemory() ? activeEntryOverviewContext : null);
    if (fromEntryOverview) {
      beginEntryOverviewExternalCreate(fromEntryOverview);
    } else if (!canCreateExternalSectionNow()) {
      return;
    }
  } else if (isMediaLibraryContentMode(targetMode)) {
    const entryOverviewMediaSlot =
      activeContentMode === NODE_ENTRY_OVERVIEW_MODE &&
      activeEntryOverviewContext &&
      getEntryOverviewBrowseUploadTargetMode(activeEntryOverviewContext) === targetMode;
    if (
      !isNavigationHubRailSlotCreateActive(targetMode) &&
      !entryOverviewMediaSlot &&
      (activeContentMode !== targetMode || isMediaAssetEditing())
    ) {
      return;
    }
  } else if (FLAT_STORAGE_SECTION_MODES.has(targetMode)) {
    if (
      !isNavigationHubRailSlotCreateActive(targetMode) &&
      !isEntryOverviewHubChannelFlatSlotActive(activeEntryOverviewContext, targetMode) &&
      activeContentMode !== targetMode
    ) {
      return;
    }
  } else {
    return;
  }
  createSectionTargetMode = targetMode;
  renameSectionState = null;
  renameMenuNodeState = null;
  renameExternalFileState = null;
  renameAwnDataRecordState = null;
  createSectionParentFolder =
    isMediaLibraryContentMode(targetMode)
      ? getActiveMediaSectionParentForCreate()
      : targetMode === "external"
        ? getActiveExternalSectionParentForCreate()
        : FLAT_STORAGE_SECTION_MODES.has(targetMode)
          ? getActiveFlatStorageSectionParentForCreate(targetMode)
          : null;
  const modalMessage = createSectionModalNode?.querySelector(".modal-message");
  if (modalMessage) {
    modalMessage.textContent =
      createSectionParentFolder
        ? `Создать подраздел в «${createSectionParentFolder}»`
        : "Создать раздел";
  }
  createSectionNameInputNode.value = "";
  if (createSectionDescriptionInputNode) createSectionDescriptionInputNode.value = "";
  createSectionSlugController?.reset();
  syncCreateSectionAfterRadiosFromStorage();
  syncCreateSectionAfterFieldsetVisibility();
  createSectionModalNode.classList.remove("hidden");
  createSectionNameInputNode.focus();
  syncDisplayNameLengthHint(createSectionNameInputNode);
}

function closeCreateSectionModal() {
  createSectionModalNode.classList.add("hidden");
  createSectionNameInputNode.value = "";
  if (createSectionDescriptionInputNode) createSectionDescriptionInputNode.value = "";
  createSectionSlugController?.reset();
  syncDisplayNameLengthHint(createSectionNameInputNode);
  createSectionParentFolder = null;
  renameSectionState = null;
  renameMenuNodeState = null;
  renameExternalFileState = null;
  renameAwnDataRecordState = null;
  resetCreateSectionModalLabels();
  createSectionOkBtn.textContent = "Создать";
  syncCreateSectionAfterFieldsetVisibility();
  endNavigationHubRailSlotCreate();
}

async function createWorkspaceSection() {
  if (!activePath) return;
  if (createSectionTargetMode === "external") {
    if (!canCreateExternalSectionNow()) return;
  } else if (isMediaLibraryContentMode(createSectionTargetMode)) {
    const entryOverviewMediaSlot =
      activeContentMode === NODE_ENTRY_OVERVIEW_MODE &&
      activeEntryOverviewContext &&
      getEntryOverviewBrowseUploadTargetMode(activeEntryOverviewContext) === createSectionTargetMode;
    if (
      !isNavigationHubRailSlotCreateActive(createSectionTargetMode) &&
      !entryOverviewMediaSlot &&
      (activeContentMode !== createSectionTargetMode || isMediaAssetEditing())
    ) {
      return;
    }
  } else if (FLAT_STORAGE_SECTION_MODES.has(createSectionTargetMode)) {
    if (
      !isNavigationHubRailSlotCreateActive(createSectionTargetMode) &&
      !isEntryOverviewHubChannelFlatSlotActive(activeEntryOverviewContext, createSectionTargetMode) &&
      activeContentMode !== createSectionTargetMode
    ) {
      return;
    }
  } else {
    return;
  }
  const displayName = createSectionNameInputNode.value.trim();
  const slug = createSectionSlugController?.getSlug() || "";
  if (!displayName) {
    showToast("Введите название раздела", "error");
    return;
  }
  if (!slug) {
    showToast("Введите slug (имя папки)", "error");
    return;
  }

  createSectionOkBtn.disabled = true;
  createSectionCancelBtn.disabled = true;
  for (const radio of createSectionAfterRadios) radio.disabled = true;
  createSectionOkBtn.textContent = "Создаю...";

  const isMediaLibraryTarget = isMediaLibraryContentMode(createSectionTargetMode);
  const isFlatStorageTarget = FLAT_STORAGE_SECTION_MODES.has(createSectionTargetMode);
  const apiPath = isFlatStorageTarget
    ? "/api/storage/section/create"
    : isMediaLibraryTarget
      ? "/api/media/section/create"
      : "/api/external/section/create";

  try {
    const mediaParentFolder = isMediaLibraryTarget
      ? createSectionParentFolder || getActiveMediaSectionParentForCreate()
      : null;
    const externalParentFolder =
      createSectionTargetMode === "external"
        ? createSectionParentFolder || getActiveExternalSectionParentForCreate()
        : null;
    const flatStorageParentFolder = isFlatStorageTarget
      ? createSectionParentFolder || getActiveFlatStorageSectionParentForCreate(createSectionTargetMode)
      : null;
    const requestBody = {
      path: getSlotRecordCreateManifestApiPath(),
      title: displayName,
      displayName,
      slug
    };
    const sectionDescription = readTrimmedDescriptionInput(createSectionDescriptionInputNode);
    if (sectionDescription) requestBody.description = sectionDescription;
    if (isMediaLibraryTarget && mediaParentFolder) {
      requestBody.parent = mediaParentFolder;
    }
    if (isMediaLibraryTarget) {
      const libraryFolder = getMediaLibraryStorageSubfolder(createSectionTargetMode);
      if (libraryFolder !== STORAGE_SUBFOLDER_MEDIA) requestBody.folder = libraryFolder;
    }
    if (createSectionTargetMode === "external" && externalParentFolder) {
      requestBody.parent = externalParentFolder;
    }
    if (isFlatStorageTarget) {
      requestBody.folder = getFlatStorageSectionFolderName(createSectionTargetMode);
      if (flatStorageParentFolder) requestBody.parent = flatStorageParentFolder;
    }
    const response = await fetch(buildApiUrl(apiPath), {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(requestBody)
    });
    const data = await response.json().catch(() => ({}));
    if (!response.ok) {
      const reason = data.error || `Request failed with ${response.status}`;
      const details = data.details ? `: ${data.details}` : "";
      throw new Error(`${reason}${details}`);
    }

    persistCreateSectionAfterChoice();
    closeCreateSectionModal();
    const openForEdit = shouldOpenCreatedSectionForEdit();
    const createdReadme = String(data.readme || "").trim();
    const railCreateActive = isNavigationHubRailSlotCreateActive();
    const createdMediaSectionPath = isMediaLibraryTarget
      ? buildCreatedMediaSectionPath(mediaParentFolder, data.section, data.sectionPath)
      : "";
    const createdExternalSectionPath =
      createSectionTargetMode === "external"
        ? buildCreatedMediaSectionPath(externalParentFolder, data.section, data.sectionPath)
        : "";
    const createdFlatStorageSectionPath = isFlatStorageTarget
      ? buildCreatedMediaSectionPath(flatStorageParentFolder, data.section, data.sectionPath)
      : "";
    const fromEntryOverview =
      activeContentMode === NODE_ENTRY_OVERVIEW_MODE && Boolean(activeEntryOverviewContext);
    const createdSectionPathForEdit =
      createdExternalSectionPath ||
      createdMediaSectionPath ||
      createdFlatStorageSectionPath ||
      String(data.sectionPath || "").trim();

    if (fromEntryOverview) {
      await refreshAfterExternalWorkspaceCreate({ openForEdit });
    } else if (railCreateActive) {
      await refreshNavigationHubAfterSlotMutation();
    } else {
      await loadContentByMode({
        preserveMediaSectionFolder: createdMediaSectionPath || mediaParentFolder,
        preserveExternalSectionFolder: createdExternalSectionPath || externalParentFolder,
        preserveFlatStorageSectionFolder: createdFlatStorageSectionPath || flatStorageParentFolder
      });
    }
    if (createdMediaSectionPath) {
      activeMediaSectionFolder = createdMediaSectionPath;
      mediaViewMode = "all";
      if (mediaViewSelectNode) mediaViewSelectNode.value = "all";
      if (!fromEntryOverview) {
        rerenderMediaListViewBody();
        syncAppRouteToUrl({ push: true });
      }
    }
    if (createdExternalSectionPath) {
      activeExternalSectionFolder = createdExternalSectionPath;
      if (!fromEntryOverview) {
        rerenderExternalListViewBody();
        syncAppRouteToUrl({ push: true });
      }
    }
    if (createdFlatStorageSectionPath && isFlatStorageTarget) {
      activeFlatStorageSectionFolder[createSectionTargetMode] = createdFlatStorageSectionPath;
      if (!fromEntryOverview) {
        rerenderFlatStorageListViewBody(createSectionTargetMode);
        syncAppRouteToUrl({ push: true });
      }
    }
    if (openForEdit && createdReadme) {
      await openCreatedSectionForEdit(createSectionTargetMode, {
        sectionPath: createdSectionPathForEdit,
        readme: createdReadme
      });
    }
    showToast("Раздел создан", "success");
  } catch (error) {
    showToast(`Ошибка создания раздела: ${error.message}`, "error");
  } finally {
    createSectionOkBtn.disabled = false;
    createSectionCancelBtn.disabled = false;
    for (const radio of createSectionAfterRadios) radio.disabled = false;
    createSectionOkBtn.textContent = "Создать";
  }
}

