function resolveEntryOverviewPreviewHeadingTarget(preview, heading) {
  if (!preview || !heading) return null;
  const slug = String(heading.slug || "").trim();
  const domHeadings = [...preview.querySelectorAll("h1,h2,h3,h4,h5,h6")];

  if (slug) {
    const bySlug = preview.querySelector(`#${CSS.escape(slug)}`);
    if (bySlug) return bySlug;
    const slugLower = slug.toLowerCase();
    const byIdMatch = domHeadings.find((el) => String(el.id || "").toLowerCase() === slugLower);
    if (byIdMatch) return byIdMatch;
  }

  const index = Number(heading.index);
  if (Number.isFinite(index) && index >= 0 && index < domHeadings.length) {
    return domHeadings[index];
  }

  const normalizedText = normalizeMarkdownHeadingCompareText(heading.text || "");
  if (normalizedText) {
    const byText = domHeadings.find(
      (el) => normalizeMarkdownHeadingCompareText(el.textContent || "") === normalizedText
    );
    if (byText) return byText;
  }

  const looseText = String(heading.text || "")
    .replace(/[^\p{L}\p{N}\s]/gu, " ")
    .trim()
    .toLowerCase();
  if (looseText.length >= 3) {
    const byPartial = domHeadings.find((el) =>
      String(el.textContent || "")
        .replace(/[^\p{L}\p{N}\s]/gu, " ")
        .trim()
        .toLowerCase()
        .includes(looseText)
    );
    if (byPartial) return byPartial;
  }

  return null;
}

function prepareEntryOverviewDocumentMarkdown(rawMarkdown, heroTitle = "") {
  const { body } = splitFrontmatter(String(rawMarkdown || ""));
  return stripLeadingDuplicateMarkdownHeading(stripAwnDescCallouts(body).trim(), heroTitle).trim();
}

function stripLeadingDuplicateMarkdownHeading(markdown, heroTitle) {
  const titleNorm = normalizeMarkdownHeadingCompareText(heroTitle);
  if (!titleNorm) return String(markdown || "");

  const lines = String(markdown || "").split(/\r?\n/);
  let index = 0;
  while (index < lines.length && !lines[index].trim()) index += 1;
  if (index >= lines.length) return String(markdown || "");

  const firstLine = lines[index].trim();
  const atxMatch = firstLine.match(/^(#{1,6})\s+(.+)$/);
  if (atxMatch) {
    const level = atxMatch[1].length;
    const headingText = atxMatch[2].replace(/\s+#+\s*$/, "").trim();
    if (level === 1 && normalizeMarkdownHeadingCompareText(headingText) === titleNorm) {
      index += 1;
      while (index < lines.length && !lines[index].trim()) index += 1;
      return lines.slice(index).join("\n");
    }
    return String(markdown || "");
  }

  if (index + 1 < lines.length && /^=+\s*$/.test(lines[index + 1].trim())) {
    if (normalizeMarkdownHeadingCompareText(firstLine) === titleNorm) {
      index += 2;
      while (index < lines.length && !lines[index].trim()) index += 1;
      return lines.slice(index).join("\n");
    }
  }

  return String(markdown || "");
}

function getOverviewDescription(rawManifest, entries) {
  const fromEntries =
    getPropsEntryValueByKey(entries, "awn-description") ||
    getPropsEntryValueByKey(entries, "summary");
  if (fromEntries) return fromEntries;

  const { frontmatter, body } = splitFrontmatter(rawManifest);
  if (frontmatter.trim()) {
    const fromFrontmatter =
      getYamlScalarFromFrontmatter(frontmatter, "awn-description") ||
      getYamlScalarFromFrontmatter(frontmatter, "AWN-DESC") ||
      getYamlScalarFromFrontmatter(frontmatter, "summary") ||
      getPropsEntryValueByKey(parsePropsYaml(frontmatter), "awn-description") ||
      getPropsEntryValueByKey(parsePropsYaml(frontmatter), "summary");
    if (fromFrontmatter) return fromFrontmatter;
  }

  return extractAwnDescFromBody(body);
}

