function createOverviewAccordionSection(
  groupId,
  title,
  contentNode,
  { defaultOpen = true, disabled = false, lockOpen = false, summaryAside = null } = {}
) {
  const details = document.createElement("details");
  details.className = "node-overview-fold";
  if (disabled) details.classList.add("is-disabled");
  if (lockOpen) details.classList.add("is-lock-open");

  const accordionState = loadOverviewAccordionState();

  const summary = document.createElement("summary");
  summary.className = "node-overview-fold-head";

  if (disabled) {
    details.open = false;
    summary.setAttribute("aria-disabled", "true");
    summary.title = "Раздел временно отключён";
  } else if (lockOpen) {
    details.open = true;
  } else {
    details.open = accordionState[groupId] !== undefined ? Boolean(accordionState[groupId]) : defaultOpen;
  }

  const titleSpan = document.createElement("span");
  titleSpan.className = "node-overview-fold-title";
  if (title instanceof Node) {
    titleSpan.appendChild(title);
  } else {
    titleSpan.textContent = String(title || "");
  }

  const chevron = document.createElement("span");
  chevron.className = "node-overview-fold-chevron";
  chevron.setAttribute("aria-hidden", "true");

  summary.append(titleSpan);
  if (summaryAside) summary.appendChild(summaryAside);
  summary.append(chevron);

  const body = document.createElement("div");
  body.className = "node-overview-fold-body";
  body.appendChild(contentNode);

  details.append(summary, body);
  details.addEventListener("toggle", () => {
    if (disabled) {
      details.open = false;
      return;
    }
    if (lockOpen) {
      details.open = true;
      return;
    }
    saveOverviewAccordionOpenState(groupId, details.open);
  });

  return details;
}

