function buildNodeSettingsSlotStatuses({
  nodePath = getResolvedNodePath(activePath),
  descriptionRaw = "",
  configContent = null
} = {}) {
  const hasDescription = getNodeDescriptionHasContent(descriptionRaw);
  const configCache = getCachedNodeConfig(nodePath);
  const configText = configContent ?? configCache?.content ?? modeContentCache.configs ?? "";
  const hasConfigs = Boolean(String(configText).trim());
  const hasTopicSchemaFilled = configHasTopicSchemaFields();

  const slots = [
    { id: "description", label: "Бриф, контекст и инструкция", filled: hasDescription, modeId: "description" }
  ];
  if (isTopicSchemaModeAvailable(nodePath)) {
    slots.push({
      id: "topic-schema",
      label: getTopicSchemaModeDisplayLabel(),
      filled: hasTopicSchemaFilled,
      modeId: "topic-schema"
    });
  }
  slots.push({ id: "configs", label: "Настройки", filled: hasConfigs, modeId: "configs" });
  return slots;
}

function buildNodeMemorySlotStatuses({
  isArea = false,
  slotsDisabled = false,
  internalData = null,
  externalData = null,
  tabularData = null,
  mediaData = null,
  todoData = null,
  memorySummary = null
} = {}) {
  const drivers = memorySummary?.drivers || {};
  const hasInternal =
    Boolean(String(internalData?.content || "").trim()) ||
    Boolean(drivers.internal?.exists && Number(drivers.internal.charCount) > 0);

  if (isArea) {
    return [
      {
        id: "internal",
        label: "Однофайловая",
        filled: hasInternal,
        modeId: "internal"
      }
    ];
  }

  const externalFiles = externalData?.files || [];
  const hasExternal =
    externalFiles.length > 0 ||
    Boolean(drivers.external?.exists && Number(drivers.external.count) > 0);
  const tabularRows = Math.max(
    Number(tabularData?.rowCount) || 0,
    Number(drivers.tabular?.rowCount) || 0
  );
  const hasTabular = tabularRows > 0;
  const hasMedia = Boolean(mediaData?.exists && Number(mediaData.files) > 0);
  const hasTodo = Boolean(String(todoData?.content || "").trim());

  if (slotsDisabled) {
    const liteSpecs = [
      hasExternal
        ? { id: "external", label: TOPIC_SHARED_SLOT_EXTERNAL_TITLE, filled: true, modeId: "external" }
        : null,
      hasInternal ? { id: "internal", label: "Однофайловая", filled: true, modeId: "internal" } : null,
      hasTabular ? { id: "tabular", label: "Табличная", filled: true, modeId: "tabular" } : null,
      hasTodo ? { id: "todo", label: "TODO", filled: true, modeId: "todo" } : null
    ].filter(Boolean);
    return liteSpecs;
  }

  const filledById = {
    external: hasExternal,
    internal: hasInternal,
    tabular: hasTabular,
    media: hasMedia
  };

  return [
    ...NODE_OVERVIEW_SLOT_MEMORY_SPECS.map((spec) => ({
      ...spec,
      filled: Boolean(filledById[spec.id])
    })),
    { id: "todo", label: "TODO", filled: hasTodo, modeId: "todo" }
  ];
}

