function buildNodeNavigationMemoryCounterSlots({
  isArea = false,
  internalData = null,
  externalData = null,
  tabularData = null,
  mediaData = null,
  todoData = null,
  memorySummary = null
} = {}) {
  const memorySlots = buildNodeMemorySlotStatuses({
    isArea,
    internalData,
    externalData,
    tabularData,
    mediaData,
    todoData,
    memorySummary
  });
  if (!memorySlots.length) return [];

  const drivers = memorySummary?.drivers || {};
  const externalFiles = externalData?.files || [];
  const externalCount = Math.max(externalFiles.length, Number(drivers.external?.count) || 0);
  const tabularCount = Math.max(Number(tabularData?.rowCount) || 0, Number(drivers.tabular?.rowCount) || 0);
  const mediaCount = Number(mediaData?.files) || 0;
  const todoLines = String(todoData?.content || "")
    .split("\n")
    .map((line) => line.trim())
    .filter(Boolean);

  const countById = {
    external: externalCount,
    internal: (() => {
      if (isArea) {
        const chars = String(internalData?.content || "").trim().length;
        if (chars > 0) return chars;
        return Number(drivers.internal?.charCount) || 0;
      }
      return memorySlots.find((slot) => slot.id === "internal")?.filled ? 1 : 0;
    })(),
    tabular: tabularCount,
    media: mediaCount,
    todo: todoLines.length
  };

  return memorySlots.map((slot) => {
    const count = Number(countById[slot.id]) || 0;
    const filled = Boolean(slot.filled);
    let title = filled ? `${slot.label}: ${count}` : `${slot.label}: пусто`;
    if (isArea && slot.id === "internal" && filled) {
      title = `${slot.label}: ${count.toLocaleString("ru-RU")} симв.`;
    }
    return { ...slot, count, tone: "", title };
  });
}

async function fetchFolderViewSummary(manifestPath, folder, agentId = activeWorkspaceId) {
  if (!manifestPath || !folder) return { exists: false, files: 0, subfolders: 0 };
  try {
    const response = await fetch(
      buildApiUrl("/api/folder/view", { path: manifestPath, folder }, agentId)
    );
    if (!response.ok) return { exists: false, files: 0, subfolders: 0 };
    const data = await response.json();
    return {
      exists: Boolean(data.exists),
      files: Number(data.files) || 0,
      subfolders: Number(data.subfolders) || 0
    };
  } catch {
    return { exists: false, files: 0, subfolders: 0 };
  }
}

function getFlatStorageSlotSummaryCount(slotKey, summary) {
  if (slotKey === "repository") return Number(summary?.subfolders) || 0;
  return Number(summary?.files) || 0;
}

async function fetchFlatStorageSectionSummary(manifestPath, slotKey) {
  const folders = getStorageFolderNamesForSlotKey(slotKey);
  if (!folders.length) return { exists: false, files: 0, subfolders: 0 };
  const summaries = await Promise.all(
    folders.map((folder) => fetchFolderViewSummary(manifestPath, folder))
  );
  return {
    exists: summaries.some((summary) => summary.exists),
    files: summaries.reduce((sum, summary) => sum + getFlatStorageSlotSummaryCount(slotKey, summary), 0),
    subfolders: summaries.reduce((sum, summary) => sum + (Number(summary.subfolders) || 0), 0)
  };
}

