function buildNavigationHeroDatesPanel(meta, nodePath = activePath, options = {}) {
  recordNodeLastViewed(nodePath);

  const createdIso = meta?.manifest?.createdAt || meta?.folder?.createdAt;
  const modifiedIso = pickLatestIso(
    meta?.manifest?.updatedAt,
    meta?.folder?.updatedAt,
    meta?.props?.updatedAt
  );
  const lastViewedIso = getNodeLastViewedIso(nodePath);

  const quality = getAwnQualityFromPropEntries(options.propEntries || []);
  const rows = [
    ...(options.showHeroQuality !== false
      ? [
          {
            kind: "quality",
            label: getAwnQualityTooltip(quality),
            value: `★ ${quality}/10`,
            qualityValue: quality
          }
        ]
      : []),
    { kind: "created", label: "Создан", value: createdIso ? formatNodeMetaDateTime(createdIso) : null },
    { kind: "modified", label: "Изменён", value: modifiedIso ? formatNodeMetaDateTime(modifiedIso) : null },
    {
      kind: "viewed",
      label: "Последний просмотр",
      value: lastViewedIso ? formatNodeMetaDateTime(lastViewedIso) : null
    }
  ];

  const panel = document.createElement("div");
  panel.className = "node-navigation-hero-meta node-navigation-hero-dates";
  panel.setAttribute("role", "group");
  panel.setAttribute("aria-label", "Качество и даты записи");
  for (const row of rows) {
    if (options.hideEmpty && !String(row.value ?? "").trim()) continue;
    appendNavigationHeroMetaRow(panel, row);
  }
  return panel;
}

function buildNavigationHeroMetaPanel(meta, nodePath = activePath, options = {}) {
  const panel = buildNavigationHeroDatesPanel(meta, nodePath);
  if (options.showWorkspaceMarkers !== false) {
    appendNavigationHeroWorkspaceMarkerSlots(panel, nodePath);
  }
  return panel;
}

