function collectNavigationFolderAncestors(filePath, memoryKind = null) {
  const segments = String(filePath || "").split("/").filter(Boolean);
  if (segments.length <= 1) return [];
  segments.pop();
  const paths = [];
  let built = "";
  for (const segment of segments) {
    built = built ? `${built}/${segment}` : segment;
    if (!shouldHideNavigationInfrastructureFolder(built, memoryKind)) paths.push(built);
  }
  return paths;
}

function isNavigationFolderRegistered(folderPath, folderLabels) {
  return folderLabels.has(String(folderPath || "").replace(/\/$/, ""));
}

function navigationTreePathContainsHiddenFolder(filePath, memoryKind = null) {
  const parts = String(filePath || "").replace(/\\/g, "/").split("/").filter(Boolean);
  if (parts.length <= 1) return false;
  parts.pop();
  let built = "";
  for (const segment of parts) {
    built = built ? `${built}/${segment}` : segment;
    if (shouldHideNavigationInfrastructureFolder(built, memoryKind)) return true;
  }
  return false;
}

function buildNavigationPathTree(items, folderLabels = new Map(), memoryKind = null) {
  const root = { label: "", folderPath: "", folders: new Map(), files: [] };
  for (const item of items) {
    if (navigationTreePathContainsHiddenFolder(item.path, memoryKind)) continue;
    const segments = String(item.path || "").split("/").filter(Boolean);
    if (!segments.length) continue;
    segments.pop();
    let cursor = root;
    let builtPath = "";
    for (const segment of segments) {
      builtPath = builtPath ? `${builtPath}/${segment}` : segment;
      if (shouldHideNavigationInfrastructureFolder(builtPath, memoryKind)) continue;
      if (!cursor.folders.has(segment)) {
        cursor.folders.set(segment, {
          label: folderLabels.get(builtPath) || segment,
          folderPath: builtPath,
          folders: new Map(),
          files: []
        });
      } else if (folderLabels.has(builtPath)) {
        cursor.folders.get(segment).label = folderLabels.get(builtPath);
      }
      cursor = cursor.folders.get(segment);
    }
    cursor.files.push(item);
  }
  return root;
}

