function buildAttachmentsHoverTooltip(paths) {
  const normalized = (Array.isArray(paths) ? paths : [])
    .map((path) => String(path || "").trim())
    .filter(Boolean);
  if (!normalized.length) return "";

  const labels = normalized
    .map((path) => getAttachmentDisplayLabelFromPath(path))
    .filter(Boolean);
  if (!labels.length) return "";

  const maxShown = 6;
  const lines = labels.slice(0, maxShown).map((label) => `• ${label}`);
  if (labels.length > maxShown) {
    lines.push(`…ещё ${labels.length - maxShown}`);
  }
  return lines.join("\n");
}

function bindAttachmentsBadgeHoverTooltip(badge, paths) {
  if (!badge) return;
  const normalized = (Array.isArray(paths) ? paths : [])
    .map((path) => String(path || "").trim())
    .filter(Boolean);
  if (!normalized.length) return;

  const refreshTooltip = () => {
    const tooltip = buildAttachmentsHoverTooltip(normalized);
    if (!tooltip) return;
    applyUiTooltip(badge, tooltip, { position: "top" });
  };

  refreshTooltip();
  badge.addEventListener("mouseenter", () => {
    void Promise.all(normalized.map((path) => fetchAttachmentSidecarMeta(path))).finally(refreshTooltip);
  });
}

function createAttachmentsCountBadge(count, { extraClass = "", attachmentPaths = null } = {}) {
  const normalized = Number(count);
  if (!Number.isFinite(normalized) || normalized <= 0) return null;
  const badge = document.createElement("span");
  badge.className = `nav-book-toc-attachments-badge${extraClass ? ` ${extraClass}` : ""}`;
  badge.innerHTML =
    '<svg class="nav-book-toc-attachments-badge-icon" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M21.44 11.05l-9.19 9.19a6 6 0 0 1-8.49-8.49l9.19-9.19a4 4 0 0 1 5.66 5.66l-9.2 9.19a2 2 0 0 1-2.83-2.83l8.49-8.48" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg>';
  if (normalized > 1) {
    const countNode = document.createElement("span");
    countNode.className = "nav-book-toc-attachments-badge-count";
    countNode.textContent = String(normalized);
    countNode.setAttribute("aria-hidden", "true");
    badge.appendChild(countNode);
  }
  const noun =
    normalized % 10 === 1 && normalized % 100 !== 11
      ? "вложение"
      : normalized % 10 >= 2 && normalized % 10 <= 4 && (normalized % 100 < 10 || normalized % 100 >= 20)
        ? "вложения"
        : "вложений";
  badge.title = `${normalized} ${noun}`;
  badge.setAttribute("aria-label", badge.title);
  if (Array.isArray(attachmentPaths) && attachmentPaths.length) {
    bindAttachmentsBadgeHoverTooltip(badge, attachmentPaths);
  }
  return badge;
}

function populateNavBookTocLeaders(leadersHost, attachmentCount, { hasMaterials = false, attachmentPaths = null, hasUnread = false } = {}) {
  if (!leadersHost) return;
  const count = Number(attachmentCount);
  const badges = [];
  if (hasUnread) {
    badges.push(createUnreadBadge());
  }
  if (Number.isFinite(count) && count > 0) {
    const attachmentBadge = createAttachmentsCountBadge(count, { attachmentPaths });
    if (attachmentBadge) badges.push(attachmentBadge);
  }
  if (hasMaterials) {
    const materialsBadge = createRecordMaterialsIndicatorBadge();
    if (materialsBadge) badges.push(materialsBadge);
  }
  if (badges.length) {
    leadersHost.classList.add("has-nav-book-toc-link-indicators");
    leadersHost.classList.toggle("has-nav-book-toc-unread-badge", hasUnread);
    leadersHost.classList.toggle(
      "has-nav-book-toc-attachments-badge",
      badges.some((node) => node.classList.contains("nav-book-toc-attachments-badge"))
    );
    leadersHost.classList.toggle("has-nav-book-toc-materials-badge", hasMaterials);
    leadersHost.replaceChildren(...badges);
    leadersHost.removeAttribute("aria-hidden");
    return;
  }
  leadersHost.classList.remove(
    "has-nav-book-toc-link-indicators",
    "has-nav-book-toc-unread-badge",
    "has-nav-book-toc-attachments-badge",
    "has-nav-book-toc-materials-badge"
  );
  leadersHost.replaceChildren();
  leadersHost.setAttribute("aria-hidden", "true");
}

