function getNavigationItemFileExtension(item) {
  const fromExt = String(item?.ext || "").trim();
  if (fromExt) {
    return (fromExt.startsWith(".") ? fromExt : `.${fromExt}`).toLowerCase();
  }
  const path = String(item?.path || item?.relativePath || "").replace(/\\/g, "/");
  const fileName = path.split("/").pop() || "";
  const dot = fileName.lastIndexOf(".");
  if (dot <= 0) return "";
  return fileName.slice(dot).toLowerCase();
}

function isNavigationMarkdownItem(item) {
  return [".md", ".markdown", ".txt"].includes(getNavigationItemFileExtension(item));
}

function isNavigationImageFileItem(item) {
  const path = String(item?.path || item?.relativePath || "").replace(/\\/g, "/");
  const group = String(item?.group || "").trim();
  const ext = getNavigationItemFileExtension(item).replace(/^\./, "");
  return (
    Boolean(path) &&
    (group === "Images" || /^(?:jpe?g|png|gif|webp|heic|heif|bmp|svg|avif|ico)$/.test(ext))
  );
}

function resolveNavigationItemPreviewUiForToc(item, nodePath = activePath) {
  if (isNavigationMarkdownItem(item)) {
    const externalPreview = resolveExternalItemPreviewUi(item, nodePath);
    if (externalPreview) return externalPreview;
    if (!isNavigationImageFileItem(item)) return null;
    const path = String(item?.path || item?.relativePath || "").replace(/\\/g, "/");
    const imageUrl = appendCacheBuster(buildMediaThumbUrl(path, nodePath, MEDIA_THUMB_MAX_SMALL));
    return imageUrl ? { imageUrl, previewPath: path } : null;
  }
  return resolveNavigationItemPreviewUi(item, nodePath);
}

function formatNavigationFileExtensionBadge(ext) {
  const raw = String(ext || "").replace(/^\./, "").trim();
  if (!raw) return "";
  if (raw.length <= 4) return raw.toUpperCase();
  return raw.slice(0, 4).toUpperCase();
}

function getNavigationTocFileIcon(item) {
  const ext = getNavigationItemFileExtension(item);
  if (ext) return getDocumentIcon(ext);
  if (item?.group && NAVIGATION_MEDIA_GROUP_ICONS[item.group]) {
    return NAVIGATION_MEDIA_GROUP_ICONS[item.group];
  }
  return "📎";
}

function resolveNavigationTocLinkIcon(item, { branch = false } = {}) {
  if (branch) return { branch: true };
  const ext = getNavigationItemFileExtension(item);
  if ([".md", ".txt", ".markdown"].includes(ext)) {
    return { kind: "record" };
  }
  const symbol = getNavigationTocFileIcon(item);
  return symbol ? { symbol } : {};
}

function getNavigationFileTypeTone(ext) {
  const normalized = String(ext || "").toLowerCase();
  if (normalized === ".pdf") return "pdf";
  if ([".doc", ".docx"].includes(normalized)) return "doc";
  if ([".xls", ".xlsx", ".csv"].includes(normalized)) return "sheet";
  if ([".ppt", ".pptx"].includes(normalized)) return "slide";
  if ([".md", ".txt", ".markdown"].includes(normalized)) return "text";
  if ([".mp4", ".mov", ".avi", ".webm", ".mkv"].includes(normalized)) return "video";
  if ([".mp3", ".wav", ".ogg", ".flac", ".m4a"].includes(normalized)) return "audio";
  if ([".zip", ".rar", ".7z", ".tar", ".gz"].includes(normalized)) return "archive";
  return "default";
}

function createNavBookTocLinkFileTypeLeading(item) {
  if (isNavigationMarkdownItem(item)) return null;

  const ext = getNavigationItemFileExtension(item);
  const badge = formatNavigationFileExtensionBadge(ext);
  if (!badge) return null;

  const wrap = document.createElement("span");
  wrap.className = `nav-book-toc-link-preview nav-book-toc-link-filetype nav-book-toc-link-filetype--${getNavigationFileTypeTone(ext)}`;
  wrap.title = ext.replace(/^\./, "").toUpperCase();

  const emoji = document.createElement("span");
  emoji.className = "nav-book-toc-link-filetype-emoji";
  emoji.setAttribute("aria-hidden", "true");
  applyNavigationFileIconToElement(emoji, item, getNavigationTocFileIcon(item));

  const label = document.createElement("span");
  label.className = "nav-book-toc-link-filetype-ext";
  label.textContent = badge;

  wrap.append(emoji, label);
  return wrap;
}

function createNavigationMediaBookTocLinkLeading(item, nodePath = activePath, { showBranch = true } = {}) {
  const previewWrap = document.createElement("span");
  previewWrap.className = "nav-book-toc-link-preview";

  const path = String(item?.path || item?.relativePath || "").replace(/\\/g, "/");
  if (isEntryOverviewMediaImageItem(item) && path) {
    const previewUi = { imageUrl: buildMediaThumbUrl(path, nodePath, MEDIA_THUMB_MAX_SMALL) };
    if (
      appendNavigationItemPreviewThumb(previewWrap, item, previewUi, {
        className: "nav-book-toc-link-preview-img"
      })
    ) {
      return showBranch ? wrapNavBookTocMediaLeading(previewWrap) : previewWrap;
    }
    const fallback = document.createElement("span");
    fallback.className = "nav-book-toc-link-filetype-emoji";
    fallback.setAttribute("aria-hidden", "true");
    applyNavigationFileIconToElement(fallback, item, "🖼");
    previewWrap.appendChild(fallback);
    return showBranch ? wrapNavBookTocMediaLeading(previewWrap) : previewWrap;
  }

  const ext = getNavigationItemFileExtension(item);
  const badge = formatNavigationFileExtensionBadge(ext);
  previewWrap.classList.add(
    "nav-book-toc-link-filetype",
    `nav-book-toc-link-filetype--${getNavigationFileTypeTone(ext)}`
  );

  const emoji = document.createElement("span");
  emoji.className = "nav-book-toc-link-filetype-emoji";
  emoji.setAttribute("aria-hidden", "true");
  applyNavigationFileIconToElement(emoji, item, getMediaIconForItem(item));
  previewWrap.appendChild(emoji);

  if (badge) {
    const label = document.createElement("span");
    label.className = "nav-book-toc-link-filetype-ext";
    label.textContent = badge;
    previewWrap.appendChild(label);
  }

  return showBranch ? wrapNavBookTocMediaLeading(previewWrap) : previewWrap;
}

function wrapNavBookTocMediaLeading(previewWrap) {
  const leadingWrap = document.createElement("span");
  leadingWrap.className = "nav-book-toc-link-leading";
  leadingWrap.appendChild(createNavBookTocLinkIcon({ branch: true }));
  leadingWrap.appendChild(previewWrap);
  return leadingWrap;
}

function createNavBookTocLinkLeading(item, nodePath = activePath, options = {}) {
  const preview = resolveNavigationItemPreviewUiForToc(item, nodePath);
  if (preview?.imageUrl && !preview.broken) {
    const previewWrap = document.createElement("span");
    previewWrap.className = "nav-book-toc-link-preview";
    if (
      appendNavigationItemPreviewThumb(previewWrap, item, preview, {
        className: "nav-book-toc-link-preview-img",
        clearOnError: isNavigationMarkdownItem(item)
      })
    ) {
      return previewWrap;
    }
  }

  const showBranch = options.showBranchLeading !== false;
  const showFileType = options.showFileTypeLeading !== false;
  if (!showBranch && !showFileType) {
    return null;
  }

  const leadingWrap = document.createElement("span");
  leadingWrap.className = "nav-book-toc-link-leading";
  if (showBranch) {
    leadingWrap.appendChild(createNavBookTocLinkIcon({ branch: true }));
  }
  if (showFileType) {
    const fileTypeLeading = createNavBookTocLinkFileTypeLeading(item);
    if (fileTypeLeading) leadingWrap.appendChild(fileTypeLeading);
  }

  return leadingWrap.childElementCount ? leadingWrap : null;
}

function buildNavBookTocEntryMarkers(item, nodePath = activePath, handlers = {}) {
  const status = createNavBookTocStatusBadge(resolveNavigationItemStatus(item));
  const awnId = resolveNavigationItemAwnId(item);
  const idBadge = awnId ? createNavBookTocIdBadge(awnId) : null;
  let icon = null;
  let preview = null;

  if (handlers.linkLeadingMode === "media") {
    const showBranch = handlers.showBranchLeading !== false;
    if (showBranch) {
      icon = createNavBookTocLinkIcon({ branch: true });
    }

    const path = String(item?.path || item?.relativePath || "").replace(/\\/g, "/");
    preview = document.createElement("span");
    preview.className = "nav-book-toc-link-preview";

    if (isEntryOverviewMediaImageItem(item) && path) {
      const previewUi = { imageUrl: buildMediaThumbUrl(path, nodePath, MEDIA_THUMB_MAX_SMALL) };
      if (
        !appendNavigationItemPreviewThumb(preview, item, previewUi, {
          className: "nav-book-toc-link-preview-img"
        })
      ) {
        const fallback = document.createElement("span");
        fallback.className = "nav-book-toc-link-filetype-emoji";
        fallback.setAttribute("aria-hidden", "true");
        applyNavigationFileIconToElement(fallback, item, "🖼");
        preview.appendChild(fallback);
      }
    } else {
      const ext = getNavigationItemFileExtension(item);
      const badge = formatNavigationFileExtensionBadge(ext);
      preview.classList.add(
        "nav-book-toc-link-filetype",
        `nav-book-toc-link-filetype--${getNavigationFileTypeTone(ext)}`
      );
      const emoji = document.createElement("span");
      emoji.className = "nav-book-toc-link-filetype-emoji";
      emoji.setAttribute("aria-hidden", "true");
      applyNavigationFileIconToElement(emoji, item, getMediaIconForItem(item));
      preview.appendChild(emoji);
      if (badge) {
        const label = document.createElement("span");
        label.className = "nav-book-toc-link-filetype-ext";
        label.textContent = badge;
        preview.appendChild(label);
      }
    }

    if (!icon) {
      const ext = getNavigationItemFileExtension(item);
      if ([".md", ".txt", ".markdown"].includes(ext)) {
        icon = createNavBookTocLinkIcon({ kind: "record" });
      } else if (!preview) {
        icon = createNavBookTocLinkIcon(resolveNavigationTocLinkIcon(item));
      }
    }

    return { icon, status, idBadge, preview };
  }

  const showBranch = handlers.showBranchLeading !== false;
  const showFileType = handlers.showFileTypeLeading !== false;

  if (showBranch) {
    icon = createNavBookTocLinkIcon({ branch: true });
  }

  const previewUi = resolveNavigationItemPreviewUiForToc(item, nodePath);
  if (previewUi?.imageUrl && !previewUi.broken) {
    preview = document.createElement("span");
    preview.className = "nav-book-toc-link-preview";
    appendNavigationItemPreviewThumb(preview, item, previewUi, {
      className: "nav-book-toc-link-preview-img",
      clearOnError: isNavigationMarkdownItem(item)
    });
    if (!preview.querySelector("img")) {
      preview = null;
    }
  } else if (showFileType) {
    preview = createNavBookTocLinkFileTypeLeading(item);
  }

  if (!icon) {
    const ext = getNavigationItemFileExtension(item);
    if ([".md", ".txt", ".markdown"].includes(ext)) {
      icon = createNavBookTocLinkIcon({ kind: "record" });
    } else if (!preview) {
      icon = createNavBookTocLinkIcon(resolveNavigationTocLinkIcon(item));
    }
  }

  return { icon, status, idBadge, preview };
}

function appendNavBookTocEntryMarkers(link, item, nodePath, handlers = {}) {
  const { icon, status, idBadge, preview } = buildNavBookTocEntryMarkers(item, nodePath, handlers);
  if (icon) link.appendChild(icon);
  if (status) link.appendChild(status);
  if (idBadge) link.appendChild(idBadge);
  if (preview) link.appendChild(preview);
  const gdriveBadge = createGoogleDriveSyncedBadge(item);
  if (gdriveBadge) link.appendChild(gdriveBadge);
}

function appendNavigationItemPreviewThumb(
  parent,
  item,
  preview,
  {
    className = "",
    cacheBust = true,
    loading = "lazy",
    clearOnError = false,
    timeoutMs = null
  } = {}
) {
  if (!preview || preview.broken) return false;

  const rawUrl = String(preview.imageUrl || "").trim();
  if (!rawUrl) return false;

  let imageUrl =
    /^https?:\/\//i.test(rawUrl) || rawUrl.startsWith("/api/")
      ? appendAgentToApiUrl(rawUrl)
      : rawUrl;
  if (cacheBust) imageUrl = appendCacheBuster(imageUrl);

  const img = document.createElement("img");
  img.className = className;
  img.alt = "";
  img.loading = loading;
  img.decoding = "async";

  const handlePreviewFail = () => {
    if (clearOnError) {
      img.remove();
      if (!parent.childElementCount) parent.remove();
      return;
    }
    applyBrokenImagePlaceholder(img, "Превью не найдено");
  };

  const lifecycle = bindPreviewImageLifecycle(img, {
    loadingClassTarget: parent,
    timeoutMs: timeoutMs ?? resolvePreviewLoadTimeoutMs(imageUrl),
    onFail: handlePreviewFail
  });

  parent.appendChild(img);
  img.src = imageUrl;
  lifecycle.checkAlreadyLoaded();
  return true;
}

const menuTreePreviewImageCache = new Map();

function collectMenuTreePreviewImages(root) {
  const byPath = new Map();
  if (!root) return byPath;
  root.querySelectorAll(".menu-item[data-path], .menu-folder[data-path]").forEach((btn) => {
    const path = normalizeMenuNodePath(btn.dataset.path || "");
    if (!path) return;
    const img = btn.querySelector(".menu-tree-preview-img");
    if (!img || img.classList.contains("broken-image-placeholder")) return;
    const src = String(img.currentSrc || img.src || "").trim();
    if (!src) return;
    byPath.set(path, img);
    menuTreePreviewImageCache.set(path, img);
  });
  return byPath;
}

function reuseMenuTreePreviewImages(root, previousByPath) {
  if (!root) return;
  root.querySelectorAll(".menu-item[data-path], .menu-folder[data-path]").forEach((btn) => {
    const path = normalizeMenuNodePath(btn.dataset.path || "");
    if (!path) return;
    const previousImg =
      previousByPath?.get?.(path) || menuTreePreviewImageCache.get(path) || null;
    if (!previousImg || previousImg.classList.contains("broken-image-placeholder")) return;
    const nextImg = btn.querySelector(".menu-tree-preview-img");
    if (!nextImg || previousImg === nextImg) return;
    nextImg.replaceWith(previousImg);
    menuTreePreviewImageCache.set(path, previousImg);
  });
}

function withPreservedMenuTreePreviews(agentId, work) {
  const host = getMenuTreeHost(agentId);
  const previousPreviews = collectMenuTreePreviewImages(host);
  const result = work();
  if (host) reuseMenuTreePreviewImages(host, previousPreviews);
  return result;
}

