function resolveEntryOverviewHeroTypeLabel(entries, context, navigationIndex = null) {
  if (context?.entryKind === "awn.media.asset") {
    return normalizeAwnTypeName("awn.media.asset") || "awn.media.asset";
  }
  const storageKind = context
    ? resolveEntryOverviewStorageMemoryKind(context, getResolvedNodePath(activePath))
    : null;
  if (
    context?.relativePath &&
    resolveEntryOverviewEntryKindForStoragePath(context.relPath, context.relativePath, storageKind) ===
      "awn.media.asset"
  ) {
    return normalizeAwnTypeName("awn.media.asset") || "awn.media.asset";
  }
  const fromProps = String(getPropsEntryValueByKey(entries, "awn-type") || "").trim();
  if (fromProps) return fromProps;
  if (!context || isEntryOverviewMemoryTocRoot(context)) return "";
  if (isEntryOverviewCategoryContext(context)) {
    const folderKey = normalizeSectionFolderKey(getSectionFolderFromCategoryContext(context));
    if (folderKey && navigationIndex?.sectionManifestByFolder instanceof Map) {
      const manifest = navigationIndex.sectionManifestByFolder.get(folderKey);
      const navProps = Array.isArray(manifest?.props) ? manifest.props : [];
      const fromNav = String(getPropsEntryValueByKey(navProps, "awn-type") || "").trim();
      if (fromNav) return fromNav;
    }
  }
  const rel = String(context.relativePath || context.relPath || "").replace(/\\/g, "/").replace(/^\/+/, "");
  if (!rel) return "";
  const mode = resolveEntryOverviewStorageMemoryKind(context, getResolvedNodePath(activePath));
  return String(inferAwnTypeFromRelPath(rel, { contentMode: mode }) || "").trim();
}

function formatEntryOverviewHeroPathLabel(entries, relativePath) {
  const slug = getPropsEntryValueByKey(entries, "awn-slug");
  if (slug) return `slug: ${slug}`;
  const normalized = String(relativePath || "").replace(/\\/g, "/").replace(/^\/+/, "");
  if (isSectionReadmePath(normalized)) {
    const folderPath = normalized.slice(0, -AREA_MANIFEST_FILE.length).replace(/\/$/, "");
    const segment = folderPath.split("/").filter(Boolean).pop() || "";
    const topicPath = getResolvedNodePath(activePath);
    const canon = segment ? canonicalizeHeroTopicSlug(segment, topicPath) : "";
    return canon ? `slug: ${canon}` : "slug: —";
  }
  const base = normalized.split("/").pop() || "";
  const stem = base.replace(/\.md$/i, "");
  return stem ? `slug: ${stem}` : "slug: —";
}

async function fetchEntryOverviewNavigationIndex(context, topicPath) {
  if (!topicPath) return null;
  try {
    if (context.memoryKind === "external") {
      const data = await fetchExternalFilesForNavigation(topicPath);
      if (data.slotsDisabled && data.groups) {
        const prepared = prepareNavigationMediaItems(data.groups, data.sectionManifests || [], {
          memoryKind: "media"
        });
        prepared.flexibleSlotMedia = true;
        return prepared;
      }
      return prepareNavigationExternalItems(
        combineNavigationStorageFileLists(data.files || [], data.nonMarkdownFiles || []),
        data.folders || []
      );
    }
    if (
      context.memoryKind === "media" ||
      context.memoryKind === "files" ||
      context.memoryKind === "assets"
    ) {
      if (isTopicSharedSlotActive(topicPath)) {
        const data = await fetchExternalFilesForNavigation(topicPath);
        if (data.slotsDisabled && data.groups) {
          const prepared = prepareNavigationMediaItems(data.groups, data.sectionManifests || [], {
            memoryKind: "media"
          });
          prepared.flexibleSlotMedia = true;
          return prepared;
        }
      }
      const folderMode =
        context.memoryKind === "assets"
          ? "assets"
          : isHubWorkspaceFilesSlotPage(topicPath) || context.memoryKind === "files"
            ? "files"
            : "media";
      const preparedMemoryKind =
        context.memoryKind === "files" ? "media" : context.memoryKind;
      const data = await fetchMediaLibraryOverview(topicPath, folderMode);
      return prepareNavigationMediaItems(data?.groups || {}, data?.sectionManifests || [], {
        memoryKind: preparedMemoryKind
      });
    }
    if (isFlatEntryOverviewMemoryKind(context.memoryKind)) {
      const slotKey = getDataStorageSlotForMode(context.memoryKind)?.key || context.memoryKind;
      const manifestPath = getWorkspaceStorageManifestApiPath(topicPath) || topicPath;
      return fetchFlatStorageNavigationIndex(manifestPath, slotKey);
    }
  } catch {
    return null;
  }
  return null;
}

function buildEntryOverviewTrailSegments(context, folderLabels, title) {
  if (isEntryOverviewMemoryTocRoot(context)) return [];

  const labels = folderLabels instanceof Map ? folderLabels : new Map();
  const relativePath = String(context.relativePath || "").replace(/\\/g, "/").replace(/^\/+/, "");
  const isCategory =
    context.entryKind === "awn.record.category" || context.entryKind === "awn.media.category";

  if (isCategory && isSectionReadmePath(relativePath)) {
    const folderPath = relativePath.slice(0, -AREA_MANIFEST_FILE.length).replace(/\/$/, "");
    const segments = collectNavigationFolderAncestors(`${folderPath}/placeholder.md`)
      .filter((path) => path !== folderPath)
      .map((path) => ({
        kind: "folder",
        path,
        label: labels.get(path) || path.split("/").pop() || path
      }));
    segments.push({
      kind: "folder",
      path: folderPath,
      label: title,
      isCurrent: true
    });
    return segments;
  }

  const segments = collectNavigationFolderAncestors(relativePath).map((path) => ({
    kind: "folder",
    path,
    label: labels.get(path) || path.split("/").pop() || path
  }));
  segments.push({
    kind: "file",
    path: relativePath,
    label: title,
    isCurrent: true
  });
  return segments;
}

