function entryOverviewItemMatchesQuery(item, folderLabels, queryLower, folderDescriptions = null) {
  if (!queryLower) return true;
  const path = String(item?.path || "").replace(/\\/g, "/");
  const title = item?.title || item?.displayName || item?.name || "";
  const description = getNavigationAwnDescription(item);
  const fileName = path.split("/").pop() || "";
  if (nodeMatchesQuery(path, queryLower)) return true;
  if (nodeMatchesQuery(title, queryLower)) return true;
  if (nodeMatchesQuery(description, queryLower)) return true;
  if (nodeMatchesQuery(fileName, queryLower)) return true;
  for (const ancestor of collectNavigationFolderAncestors(path)) {
    const label = folderLabels.get(ancestor);
    const folderDescription =
      folderDescriptions instanceof Map ? getNavigationAwnDescription({ description: folderDescriptions.get(ancestor) }) : "";
    if (nodeMatchesQuery(ancestor, queryLower)) return true;
    if (nodeMatchesQuery(label, queryLower)) return true;
    if (nodeMatchesQuery(folderDescription, queryLower)) return true;
  }
  return false;
}

function filterEntryOverviewNavigationIndex(navigationIndex, queryLower) {
  if (!navigationIndex || !queryLower) return navigationIndex;

  const folderLabels =
    navigationIndex.folderLabels instanceof Map ? navigationIndex.folderLabels : new Map();
  const folderDescriptions =
    navigationIndex.folderDescriptions instanceof Map ? navigationIndex.folderDescriptions : new Map();
  const matchingFiles = (navigationIndex.contentFiles || []).filter((item) =>
    entryOverviewItemMatchesQuery(item, folderLabels, queryLower, folderDescriptions)
  );

  const folderPaths = new Set();
  for (const folderPath of navigationIndex.folderPaths || []) {
    const label = folderLabels.get(folderPath);
    const description = getNavigationAwnDescription({ description: folderDescriptions.get(folderPath) });
    if (
      nodeMatchesQuery(folderPath, queryLower) ||
      nodeMatchesQuery(label, queryLower) ||
      nodeMatchesQuery(description, queryLower)
    ) {
      addMemorySectionFolderPath(folderPaths, folderPath);
    }
  }
  for (const file of matchingFiles) {
    for (const ancestor of collectNavigationFolderAncestors(
      file.path,
      activeEntryOverviewContext?.memoryKind === "assets" ? "assets" : null
    )) {
      addMemorySectionFolderPath(folderPaths, ancestor);
    }
  }

  return {
    ...navigationIndex,
    contentFiles: matchingFiles,
    folderPaths
  };
}

function getEntryOverviewFilteredNavigationIndex(navigationIndex) {
  const queryLower = entryOverviewSearchQuery.trim().toLowerCase();
  return filterEntryOverviewNavigationIndex(navigationIndex, queryLower);
}

function getEntryOverviewSectionListMountAnchor(hub) {
  if (!hub) return null;
  return (
    hub.querySelector(".node-entry-overview-manifest") ||
    hub.querySelector(".node-entry-overview-tabular-preview") ||
    hub.querySelector(".node-entry-overview-section-readme-offer") ||
    hub.querySelector(".node-overview-type-registry-fold") ||
    hub.querySelector(".node-entry-overview-section-list-anchor") ||
    hub.querySelector(".node-navigation-props") ||
    hub.querySelector(".node-navigation-hero")
  );
}

function shouldShowEntryOverviewSectionSearch(context) {
  if (!context || isEntryOverviewMemoryTocRoot(context)) return false;
  if (!isDataEntryOverviewMemoryKind(context.memoryKind)) return false;
  if (isBundleEntryOverviewMemoryKind(context.memoryKind)) return false;
  return getEntryOverviewSectionFolderPath(context) !== null;
}

function appendEntryOverviewSlotPanel(hub, context, topicPath) {
  const slotBar = acquireEntryOverviewDataSlotBar(context, topicPath);
  if (!slotBar) return null;

  const slotPanel = document.createElement("div");
  slotPanel.className = "node-entry-overview-slot-panel";
  slotPanel.appendChild(slotBar);
  hub.appendChild(slotPanel);
  return slotPanel;
}

function getEntryOverviewBrowsePanelMountAnchor(hub, { isMemoryTocRoot = false } = {}) {
  if (!hub) return null;
  if (isMemoryTocRoot) {
    return (
      hub.querySelector(".node-entry-overview-slot-panel") ||
      hub.querySelector(".node-entry-overview-memory-trail") ||
      null
    );
  }
  return getEntryOverviewSectionListMountAnchor(hub);
}

function renderEntryOverviewBrowseListBlock(context, navigationIndex, { isMemoryTocRoot = false, topicPreview = null } = {}) {
  const filteredIndex = getEntryOverviewFilteredNavigationIndex(navigationIndex);
  if (isMemoryTocRoot) {
    return renderEntryOverviewFullMemoryToc(context, filteredIndex, { topicPreview });
  }
  return renderEntryOverviewSectionList(context, filteredIndex);
}

function createEntryOverviewBrowsePanel(context, navigationIndex, { isMemoryTocRoot = false, slotFolderMissing = false, topicPreview = null } = {}) {
  const showSearch = !slotFolderMissing && (isMemoryTocRoot || shouldShowEntryOverviewSectionSearch(context));
  const showActions = shouldShowEntryOverviewBrowseActions(context);
  const listBlock = slotFolderMissing
    ? createEntryOverviewSlotFolderMissingNotice(context, getResolvedNodePath(activePath))
    : renderEntryOverviewBrowseListBlock(context, navigationIndex, { isMemoryTocRoot, topicPreview });
  if (!showSearch && !showActions && !listBlock) return null;

  const panel = document.createElement("div");
  panel.className = "node-entry-overview-browse-panel";
  if (slotFolderMissing) panel.classList.add("is-slot-folder-missing");

  let deferredToolbar = null;
  if (showSearch || showActions) {
    const toolbar = createEntryOverviewBrowseToolbar(context, {
      slotFolderMissing,
      topicPath: getResolvedNodePath(activePath)
    });
    if (toolbar) {
      if (slotFolderMissing) deferredToolbar = toolbar;
      else panel.appendChild(toolbar);
    }
  }

  if (showActions && !slotFolderMissing && supportsEntryOverviewBrowseUpload(context)) {
    ensureEntryOverviewBrowseUploadHost(panel, context);
    syncEntryOverviewBrowseUploadPanelUi();
  }

  if (listBlock) {
    panel.appendChild(listBlock);
    panel.dataset.railMemoryKind = context?.memoryKind || "";
    mountNavigationHubRailSlotTreeDragDrop(panel);
  }

  if (deferredToolbar) {
    panel.appendChild(deferredToolbar);
  }

  return panel.childElementCount ? panel : null;
}

function refreshEntryOverviewBrowseList(panel, context, navigationIndex, isMemoryTocRoot) {
  panel
    .querySelector(".node-entry-overview-memory-toc, .node-entry-overview-section-list")
    ?.remove();

  const listBlock = renderEntryOverviewBrowseListBlock(context, navigationIndex, { isMemoryTocRoot });
  if (listBlock) panel.appendChild(listBlock);
}

function mountEntryOverviewBrowsePanelElement(hub, panel, { isMemoryTocRoot = false } = {}) {
  if (!panel || !hub) return null;

  if (!isMemoryTocRoot) {
    const manifestNav = hub.querySelector(
      ".node-entry-overview-manifest > .node-navigation-manifest-nav"
    );
    if (manifestNav) {
      manifestNav.insertAdjacentElement("beforebegin", panel);
      return panel;
    }
  }

  const anchor = getEntryOverviewBrowsePanelMountAnchor(hub, { isMemoryTocRoot });
  if (anchor) {
    anchor.insertAdjacentElement("afterend", panel);
  } else {
    hub.appendChild(panel);
  }
  return panel;
}

function appendEntryOverviewBrowsePanel(
  hub,
  context,
  navigationIndex,
  { isMemoryTocRoot = false, slotFolderMissing = null, browseNavOptions = null, topicPreview = null } = {}
) {
  const panel = createEntryOverviewBrowsePanel(context, navigationIndex, {
    isMemoryTocRoot,
    slotFolderMissing: Boolean(slotFolderMissing),
    topicPreview
  });
  if (!panel) return null;
  const mounted = mountEntryOverviewBrowsePanelElement(hub, panel, { isMemoryTocRoot });
  if (mounted) {
    if (browseNavOptions) {
      prependEntryOverviewBrowseHeroNav(mounted, browseNavOptions);
    }
    if (shouldShowEntryOverviewSlotCountersInBrowsePanel(context, isMemoryTocRoot)) {
      void mountEntryOverviewBrowseSlotCounterStrip(
        mounted,
        context,
        getResolvedNodePath(activePath),
        { isMemoryTocRoot }
      ).then(() => finalizeEntryOverviewBrowsePanelChromeOrder(mounted));
    } else {
      finalizeEntryOverviewBrowsePanelChromeOrder(mounted);
    }
  }
  if (mounted && slotFolderMissing == null) {
    void syncEntryOverviewBrowseSlotFolderAction(
      mounted,
      context,
      getResolvedNodePath(activePath)
    );
  }
  return mounted;
}

async function appendHubChannelWorkspaceBrowsePanel(hubMain, topicPath, entries = null, options = {}) {
  if (!hubMain) return null;
  const resolvedPath = getResolvedNodePath(topicPath);
  if (resolveHubWorkspaceSlotPolicy(resolvedPath, entries)?.kind !== "channel") return null;

  const context = buildHubChannelWorkspaceBrowseContext(resolvedPath, entries);
  const manifestPath = getWorkspaceStorageManifestApiPath(resolvedPath);
  let navigationIndex = options.navigationIndex;
  if (navigationIndex === undefined) {
    navigationIndex = await fetchEntryOverviewNavigationIndex(context, manifestPath);
  }
  let slotFolderMissing = false;
  if (shouldOfferEntryOverviewStorageSlotCreate(context, resolvedPath)) {
    slotFolderMissing = !(await fetchEntryOverviewStorageSlotFolderExists(context, resolvedPath));
  }
  const slotTocNav = buildEntryOverviewBrowseTocNavOptions(context, resolvedPath);
  const panel = appendEntryOverviewBrowsePanel(hubMain, context, navigationIndex, {
    isMemoryTocRoot: true,
    slotFolderMissing,
    browseNavOptions: slotTocNav,
    topicPreview: null
  });
  if (panel) {
    panel.dataset.topicNodePath = resolvedPath;
    void syncEntryOverviewBrowseSlotFolderAction(panel, context, resolvedPath);
  }
  return panel;
}

async function appendHubMediaWorkspaceBrowsePanel(hubMain, topicPath, entries = null, options = {}) {
  if (!hubMain) return null;
  const resolvedPath = getResolvedNodePath(topicPath);
  if (resolveHubWorkspaceSlotPolicy(resolvedPath, entries)?.kind !== "media") return null;

  const context = buildHubMediaWorkspaceBrowseContext(resolvedPath, entries);
  const manifestPath = getWorkspaceStorageManifestApiPath(resolvedPath);
  let navigationIndex = options.navigationIndex;
  if (navigationIndex === undefined) {
    navigationIndex = await fetchEntryOverviewNavigationIndex(context, manifestPath);
  }
  if (!hasNavigationExternalPreparedContent(navigationIndex)) {
    const counters = await buildEntryOverviewDataSlotCounters(resolvedPath, {
      propsEntries: entries
    });
    const filesSlot = counters.find((slot) => slot.id === "files");
    if (hasNavigationExternalPreparedContent(filesSlot?.prepared)) {
      navigationIndex = filesSlot.prepared;
    }
  }
  let slotFolderMissing = false;
  if (shouldOfferEntryOverviewStorageSlotCreate(context, resolvedPath)) {
    slotFolderMissing = !(await fetchEntryOverviewStorageSlotFolderExists(context, resolvedPath));
  }
  const slotTocNav = buildEntryOverviewBrowseTocNavOptions(context, resolvedPath);
  const panel = appendEntryOverviewBrowsePanel(hubMain, context, navigationIndex, {
    isMemoryTocRoot: true,
    slotFolderMissing,
    browseNavOptions: slotTocNav,
    topicPreview: null
  });
  if (panel) {
    panel.dataset.topicNodePath = resolvedPath;
    void syncEntryOverviewBrowseSlotFolderAction(panel, context, resolvedPath);
  }
  return panel;
}

async function refreshHubMediaBrowsePanelContent(panel, context, navigationIndex, topicPath) {
  if (!panel) return;
  const resolvedPath = getResolvedNodePath(topicPath);
  const mediaContext =
    resolveHubWorkspaceSlotPolicy(resolvedPath, context?.propsEntries)?.kind === "media"
      ? buildHubMediaWorkspaceBrowseContext(resolvedPath, context?.propsEntries)
      : context;
  if (!mediaContext) return;
  let folderExists = true;
  if (shouldOfferEntryOverviewStorageSlotCreate(mediaContext, resolvedPath)) {
    folderExists = await fetchEntryOverviewStorageSlotFolderExists(mediaContext, resolvedPath);
  }
  if (!folderExists) {
    await syncEntryOverviewBrowseSlotFolderAction(panel, mediaContext, resolvedPath);
    return;
  }
  panel.classList.remove("is-slot-folder-missing");
  panel.querySelector(".node-entry-overview-slot-folder-missing")?.remove();
  refreshEntryOverviewBrowseList(panel, mediaContext, navigationIndex, true);
  panel.dataset.railMemoryKind = mediaContext.memoryKind || "";
  mountNavigationHubRailSlotTreeDragDrop(panel);
  const toolbar = panel.querySelector(".node-entry-overview-browse-toolbar");
  if (toolbar && shouldShowEntryOverviewBrowseActions(mediaContext)) {
    const freshToolbar = createEntryOverviewBrowseToolbar(mediaContext, { slotFolderMissing: false });
    if (freshToolbar) toolbar.replaceWith(freshToolbar);
    else toolbar.remove();
  }
  finalizeEntryOverviewBrowsePanelChromeOrder(panel);
}

async function refreshHubChannelBrowsePanelContent(panel, context, navigationIndex, topicPath) {
  if (!panel) return;
  const resolvedPath = getResolvedNodePath(topicPath);
  const channelContext = isHubChannelWorkspaceTopic(resolvedPath)
    ? buildHubChannelWorkspaceBrowseContext(resolvedPath, context?.propsEntries)
    : context;
  if (!channelContext) return;
  let folderExists = true;
  if (shouldOfferEntryOverviewStorageSlotCreate(channelContext, resolvedPath)) {
    folderExists = await fetchEntryOverviewStorageSlotFolderExists(channelContext, resolvedPath);
  }
  if (!folderExists) {
    await syncEntryOverviewBrowseSlotFolderAction(panel, channelContext, resolvedPath);
    return;
  }
  panel.classList.remove("is-slot-folder-missing");
  panel.querySelector(".node-entry-overview-slot-folder-missing")?.remove();
  refreshEntryOverviewBrowseList(panel, channelContext, navigationIndex, true);
  panel.dataset.railMemoryKind = channelContext.memoryKind || "";
  mountNavigationHubRailSlotTreeDragDrop(panel);
  const toolbar = panel.querySelector(".node-entry-overview-browse-toolbar");
  if (toolbar && shouldShowEntryOverviewBrowseActions(channelContext)) {
    const freshToolbar = createEntryOverviewBrowseToolbar(channelContext, { slotFolderMissing: false });
    if (freshToolbar) toolbar.replaceWith(freshToolbar);
    else toolbar.remove();
  }
  finalizeEntryOverviewBrowsePanelChromeOrder(panel);
}

function refreshEntryOverviewListFromSearch() {
  const state = entryOverviewSearchState;
  const hub = nodeOverviewContentNode?.querySelector(".node-navigation-hub");
  if (!state || !hub) return;

  const browsePanel = hub.querySelector(".node-entry-overview-browse-panel");
  if (browsePanel) {
    refreshEntryOverviewBrowseList(
      browsePanel,
      state.context,
      state.navigationIndex,
      state.isMemoryTocRoot
    );
    return;
  }

  hub.querySelector(".node-entry-overview-memory-toc")?.remove();
  hub.querySelector(".node-entry-overview-section-list")?.remove();

  const listBlock = renderEntryOverviewBrowseListBlock(state.context, state.navigationIndex, {
    isMemoryTocRoot: state.isMemoryTocRoot
  });
  if (!listBlock) return;

  const anchor = getEntryOverviewBrowsePanelMountAnchor(hub, {
    isMemoryTocRoot: state.isMemoryTocRoot
  });
  if (anchor) {
    anchor.insertAdjacentElement("afterend", listBlock);
  } else {
    hub.appendChild(listBlock);
  }
}

function getEntryOverviewTopicTitle() {
  return (
    getOverviewTitleFromProps(resolveNodeOverviewPropsEntries()) ||
    String(activeLabel || "").trim() ||
    getLabelFromPath(activePath) ||
    "Тема"
  );
}

async function resolveNavigationPrefetchValue(prefetched, key, fetcher) {
  if (Object.prototype.hasOwnProperty.call(prefetched, key)) {
    return prefetched[key];
  }
  return fetcher();
}

async function buildEntryOverviewDataSlotCounters(topicPath, prefetched = {}) {
  const manifestPath = resolveManifestPathForNodeApi(topicPath || getResolvedNodePath(activePath));
  if (!manifestPath || !topicPath) return [];
  const topicUsesFlexibleSlots = await shouldHideTopicStorageSlots(
    topicPath,
    prefetched.propsEntries || null
  );

  let intake = topicIntakeCacheByPath.get(manifestPath) || null;
  if (!intake) {
    try {
      intake = await fetchTopicIntake(manifestPath);
      topicIntakeCacheByPath.set(manifestPath, intake);
    } catch {
      intake = null;
    }
  }

  let overviewSpecs = DATA_STORAGE_SLOT_SPECS.filter((spec) =>
    shouldShowEntryOverviewSlotCounter(spec, topicPath)
  );
  if (topicUsesFlexibleSlots) {
    overviewSpecs = overviewSpecs.filter((spec) => isTopicFlexibleSingleFileSlotKey(spec?.key));
    if (!overviewSpecs.length) return [];
  }

  const hubFilesSlotPage = isHubWorkspaceFilesSlotPage(topicPath);

  const [
    externalData,
    mediaData,
    filesData,
    assetsData,
    todoData,
    roadmapData,
    internalData,
    tabularData,
    assetsPreview,
    storageScan,
    flatNavigationIndexes
  ] = await Promise.all([
    resolveNavigationPrefetchValue(prefetched, "externalData", () =>
      fetchExternalFilesForNavigation(topicPath).catch(() => ({ files: [], folders: [] }))
    ),
    resolveNavigationPrefetchValue(prefetched, "mediaData", () =>
      hubFilesSlotPage
        ? Promise.resolve({ groups: {}, sectionManifests: [], exists: false })
        : fetchMediaLibraryOverview(topicPath, "media").catch(() => ({ groups: {}, sectionManifests: [] }))
    ),
    resolveNavigationPrefetchValue(prefetched, "filesData", () =>
      hubFilesSlotPage
        ? fetchMediaLibraryOverview(topicPath, "files").catch(() => ({ groups: {}, sectionManifests: [] }))
        : Promise.resolve({ groups: {}, sectionManifests: [], exists: false })
    ),
    resolveNavigationPrefetchValue(prefetched, "assetsData", () =>
      fetchMediaLibraryOverview(topicPath, "assets").catch(() => ({ groups: {}, sectionManifests: [] }))
    ),
    resolveNavigationPrefetchValue(prefetched, "todoData", () => fetchTodoForOverview(topicPath).catch(() => null)),
    resolveNavigationPrefetchValue(prefetched, "roadmapData", () =>
      fetchRoadmapForOverview(topicPath).catch(() => null)
    ),
    resolveNavigationPrefetchValue(prefetched, "internalData", () =>
      fetchInternalMemoryForNavigation(topicPath).catch(() => null)
    ),
    resolveNavigationPrefetchValue(prefetched, "tabularData", () =>
      fetchTabularMemoryForNavigation(topicPath).catch(() => null)
    ),
    resolveNavigationPrefetchValue(prefetched, "assetsPreview", () =>
      fetchNodeOverviewPreview(topicPath).catch(() => null)
    ),
    resolveNavigationPrefetchValue(prefetched, "storageScan", () =>
      fetchStorageRootScan(manifestPath).catch(() => null)
    ),
    resolveNavigationPrefetchValue(prefetched, "flatNavigationIndexes", () =>
      fetchNavigationHubRailFlatIndexes(topicPath).catch(() => ({}))
    )
  ]);
  Object.assign(prefetched, {
    externalData,
    mediaData,
    filesData,
    assetsData,
    todoData,
    roadmapData,
    internalData,
    tabularData,
    assetsPreview,
    storageScan,
    flatNavigationIndexes
  });
  const assetsPreviewFilled = Boolean(assetsPreview?.imageUrl && !assetsPreview?.broken);

  const externalPrepared = prepareNavigationExternalItems(
    combineNavigationStorageFileLists(
      externalData.files || [],
      externalData.nonMarkdownFiles || []
    ),
    externalData.folders || []
  );
  const mediaPrepared = prepareNavigationMediaItems(
    mediaData?.groups || {},
    mediaData?.sectionManifests || []
  );
  const filesPrepared = prepareNavigationMediaItems(
    filesData?.groups || {},
    filesData?.sectionManifests || []
  );
  const assetsPrepared = prepareNavigationMediaItems(
    assetsData?.groups || {},
    assetsData?.sectionManifests || [],
    { memoryKind: "assets" }
  );
  const prefetchedIndex = { externalFiles: externalData.files || [] };

  const slots = overviewSpecs.map((spec) => {
    let count = 0;
    let filled = false;
    let tone = "";
    let title = spec.label;
    let bundleMetrics = null;
    let prepared = null;

    if (spec.sectionKind === "bundle") {
      bundleMetrics = getBundleMemoryCounterMetrics(spec, {
        internalData,
        tabularData,
        todoData,
        roadmapData
      });
      if (bundleMetrics) {
        count = bundleMetrics.count;
        filled = bundleMetrics.filled;
        title = bundleMetrics.title;
      }
    } else {
      if (spec.key === "memory") {
        prepared = externalPrepared;
      } else if (spec.key === "media") {
        prepared = mediaPrepared;
      } else if (spec.key === "files") {
        prepared = filesPrepared;
      } else if (spec.key === "assets") {
        prepared = assetsPrepared;
      } else if (spec.sectionKind === "flat") {
        const memoryKind = getEntryOverviewMemoryKindForSlot(spec);
        prepared = memoryKind ? flatNavigationIndexes[memoryKind] : null;
      }

      count = resolveNavigationSlotFileCount(spec, { storageScan, prepared });
      if (spec.key === "media") {
        filled =
          count > 0 ||
          hasNavigationExternalPreparedContent(prepared) ||
          Boolean(mediaData?.exists);
      } else if (spec.key === "files") {
        filled =
          count > 0 ||
          hasNavigationExternalPreparedContent(prepared) ||
          Boolean(filesData?.exists);
      } else if (spec.key === "assets") {
        filled =
          count > 0 ||
          hasNavigationExternalPreparedContent(prepared) ||
          Boolean(assetsData?.exists);
      } else {
        filled = count > 0 || hasNavigationExternalPreparedContent(prepared);
      }

      if (spec.key === "inbox") {
        const pending = Number(intake?.inbox?.pending) || 0;
        if (pending > 0) tone = "pending";
        filled = filled || Number(intake?.inbox?.total) > 0;
      }

      title = buildNavigationSlotCounterTitle(spec, count, { intake });
    }

    let folderExists = resolveStorageSlotFolderExistsFromScan(spec, storageScan);

    return {
      id: spec.key,
      label: spec.label,
      spec,
      count,
      filled,
      folderExists,
      available: bundleMetrics?.display === "flag" ? false : Boolean(bundleMetrics?.available),
      display: bundleMetrics?.display || "count",
      tone,
      title,
      hasIndex: false,
      prepared,
      assetsPreview: spec.key === "assets" && assetsPreviewFilled ? assetsPreview : null
    };
  });

  const indexStates = await Promise.all(
    slots.map(async (slot) => [slot.id, await resolveStorageSlotIndexFile(manifestPath, slot.spec, prefetchedIndex)])
  );
  const indexBySlotId = Object.fromEntries(indexStates);
  for (const slot of slots) {
    slot.indexFile = indexBySlotId[slot.id] || null;
    slot.hasIndex = Boolean(slot.indexFile);
  }

  const policy =
    prefetched.hubSlotPolicy ??
    resolveHubWorkspaceSlotPolicy(topicPath, prefetched.propsEntries || null);
  if (policy) {
    const allowed = new Set(policy.slotKeys);
    return slots.filter((slot) => allowed.has(slot.id));
  }

  return slots;
}

function isBundleMemoryCounterSlot(spec) {
  return spec?.sectionKind === "bundle" && Boolean(getEntryOverviewMemoryKindForSlot(spec));
}

function getBundleMemoryMeaningfulBody(raw) {
  const text = String(raw ?? "");
  if (!text.trim()) return "";
  const { body } = splitFrontmatter(text);
  return stripAwnDescCallouts(body).trim();
}

function isBundleInternalMemoryFilled(internalData) {
  if (!internalData) return false;
  if (internalData.exists === false && !String(internalData.content || "").trim()) return false;
  return getBundleMemoryMeaningfulBody(internalData.content).length > 0;
}

function isBundleTabularMemoryFilled(tabularData) {
  if (!tabularData) return false;
  const rawContent = String(tabularData.content || "").trim();
  if (tabularData.exists === false && !rawContent) return false;

  const rows = Array.isArray(tabularData.rows) ? tabularData.rows : [];
  if (rows.length) {
    return rows.some(
      (row) => Array.isArray(row) && row.some((cell) => String(cell ?? "").trim())
    );
  }

  return Number(tabularData.rowCount) > 0 && rawContent.length > 0;
}

function isBundleTodoMemoryFilled(todoData) {
  if (!todoData) return false;
  if (todoData.exists === false && !String(todoData.content || "").trim()) return false;
  return getBundleMemoryMeaningfulBody(todoData.content).length > 0;
}

function getBundleMemoryCounterMetrics(
  spec,
  { internalData = null, tabularData = null, todoData = null, roadmapData = null } = {}
) {
  if (!isBundleMemoryCounterSlot(spec)) return null;

  const memoryKind = getEntryOverviewMemoryKindForSlot(spec);
  if (memoryKind === "internal") {
    const body = getBundleMemoryMeaningfulBody(internalData?.content);
    const charCount = body.length;
    const filled = charCount > 0;
    return {
      available: true,
      filled,
      count: charCount,
      display: "flag",
      title: filled
        ? `${spec.label}: ${charCount.toLocaleString("ru-RU")} симв.`
        : `${spec.label}: пусто`
    };
  }

  if (memoryKind === "tabular") {
    const rowCount = Number(tabularData?.rowCount) || 0;
    const filled = isBundleTabularMemoryFilled(tabularData);
    return {
      available: true,
      filled,
      count: filled ? rowCount : 0,
      display: "flag",
      title: filled ? `${spec.label}: ${rowCount} строк` : `${spec.label}: пусто`
    };
  }

  if (memoryKind === "todo") {
    const todoLines = getBundleMemoryMeaningfulBody(todoData?.content)
      .split("\n")
      .map((line) => line.trim())
      .filter(Boolean);
    const filled = todoLines.length > 0;
    return {
      available: true,
      filled,
      count: filled ? todoLines.length : 0,
      display: "flag",
      title: filled ? `${spec.label}: ${todoLines.length} пунктов` : `${spec.label}: пусто`
    };
  }

  if (memoryKind === "roadmap") {
    const body = getBundleMemoryMeaningfulBody(roadmapData?.content);
    const filled = body.length > 0;
    return {
      available: true,
      filled,
      count: filled ? 1 : 0,
      display: "flag",
      title: filled ? `${spec.label}: заполнена` : `${spec.label}: пусто`
    };
  }

  return null;
}

function resolveWorkspaceCounterSlotIcon(slot) {
  const spec = resolveStorageSlotSpecFromCounterSlot(slot);
  return spec?.icon || "📁";
}

function createWorkspaceCounterSlotIcon(slot) {
  const icon = document.createElement("span");
  icon.className = "node-navigation-workspace-counter-icon";
  icon.setAttribute("aria-hidden", "true");
  icon.textContent = resolveWorkspaceCounterSlotIcon(slot);
  return icon;
}

function getWorkspaceCounterButtonStateClasses(slot) {
  const classes = ["node-navigation-workspace-counter"];
  if (isDeprecatedRepositoryCounterSlot(slot)) {
    classes.push("is-deprecated-slot", "is-empty");
    return classes.join(" ");
  }
  if (slot.display === "flag") {
    classes.push("is-flag");
    if (slot.filled) classes.push("is-filled");
    else classes.push("is-empty");
  } else if (slot.filled) {
    classes.push("is-filled");
  } else if (slot.available) {
    classes.push("is-available");
  } else {
    classes.push("is-empty");
  }
  if (slot.tone) classes.push(`is-${slot.tone}`);
  return classes.join(" ");
}

/** Hide/disable the legacy per-topic repository slot in workspace counters (use workspace awn-repositories). */
const REPOSITORY_SLOT_COUNTER_DEPRECATED = true;

function isDeprecatedRepositoryCounterSlot(slot) {
  if (!REPOSITORY_SLOT_COUNTER_DEPRECATED) return false;
  const key = slot?.id || slot?.spec?.key;
  return key === "repository";
}

function createDeprecatedRepositoryCounterIndicator() {
  const mark = document.createElement("span");
  mark.className =
    "node-navigation-workspace-counter-value node-navigation-workspace-counter-value--deprecated";
  mark.setAttribute("aria-hidden", "true");
  mark.textContent = "✕";
  return mark;
}

function applyWorkspaceCounterLabelForSlot(labelNode, slot) {
  if (!labelNode) return;
  if (!isDeprecatedRepositoryCounterSlot(slot)) {
    const spec = resolveStorageSlotSpecFromCounterSlot(slot);
    const title = slot.label || resolveDataStorageSlotDisplayLabel(slot.id || spec?.key);
    const typesTrigger = createWorkspaceCounterAllowedTypesTrigger(spec);

    labelNode.replaceChildren();
    labelNode.classList.remove(
      "node-navigation-workspace-counter-label--deprecated",
      "node-navigation-workspace-counter-label-note"
    );

    if (typesTrigger) {
      labelNode.classList.add("node-navigation-workspace-counter-label--stacked");
      const main = document.createElement("span");
      main.className = "node-navigation-workspace-counter-label-main";
      main.textContent = title;
      labelNode.append(main, typesTrigger);
      return;
    }

    labelNode.classList.remove("node-navigation-workspace-counter-label--stacked");
    labelNode.textContent = title;
    return;
  }

  labelNode.replaceChildren();
  labelNode.className =
    "node-navigation-workspace-counter-label node-navigation-workspace-counter-label--deprecated node-navigation-workspace-counter-label--stacked";

  const main = document.createElement("span");
  main.className = "node-navigation-workspace-counter-label-main is-struck";
  main.textContent = slot.label || "Репозитории";

  const note = document.createElement("span");
  note.className = "node-navigation-workspace-counter-label-note";
  note.textContent = "Откажемся от этого слота";

  labelNode.append(main, note);
}

function setWorkspaceCounterLabelText(labelNode, text) {
  if (!labelNode) return;
  const normalized = String(text || "").trim();
  const space = normalized.indexOf(" ");
  if (space === -1) {
    labelNode.textContent = normalized;
    return;
  }
  const first = normalized.slice(0, space);
  const rest = normalized.slice(space + 1).trim();
  labelNode.replaceChildren();
  labelNode.append(document.createTextNode(first));
  if (rest) {
    labelNode.appendChild(document.createElement("br"));
    labelNode.append(document.createTextNode(rest));
  }
}

function isWorkspaceCounterSlotFilled(slot) {
  if (isDeprecatedRepositoryCounterSlot(slot)) return false;
  if (slot.display === "flag") return Boolean(slot.filled);
  return Boolean(slot.filled) || Number(slot.count) > 0;
}

function createWorkspaceCounterStatusPoint(slot) {
  const wrap = document.createElement("span");
  wrap.className = "node-navigation-workspace-counter-status";
  wrap.setAttribute("aria-hidden", "true");
  wrap.appendChild(createNodeSlotStatusLamp(isWorkspaceCounterSlotFilled(slot)));
  return wrap;
}

function createWorkspaceCounterMetric(slot) {
  const wrap = document.createElement("span");
  wrap.className = "node-navigation-workspace-counter-metric";

  if (isDeprecatedRepositoryCounterSlot(slot)) {
    wrap.appendChild(createDeprecatedRepositoryCounterIndicator());
    return wrap;
  }

  if (slot.display === "flag") {
    const flag = document.createElement("span");
    flag.className = "node-navigation-workspace-counter-flag";
    flag.setAttribute("aria-hidden", "true");
    flag.innerHTML =
      '<svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M5 3v18" stroke="currentColor" stroke-width="2" stroke-linecap="round"/><path d="M5 4h10l-2.5 4L15 12H5" stroke="currentColor" stroke-width="2" stroke-linejoin="round" stroke-linecap="round" fill="currentColor" fill-opacity="0.12"/></svg>';
    wrap.appendChild(flag);
    return wrap;
  }

  const count = document.createElement("span");
  count.className = "node-navigation-workspace-counter-value";
  count.textContent = String(slot.count ?? 0);
  wrap.appendChild(count);
  return wrap;
}

function clearWorkspaceCounterButtonMetrics(btn) {
  if (!btn) return;
  btn.querySelector(".node-navigation-workspace-counter-status")?.remove();
  btn.querySelector(".node-navigation-workspace-counter-metric")?.remove();
  btn.querySelector(".node-navigation-workspace-counter-indicator")?.remove();
  btn.querySelector(".node-navigation-workspace-counter-value")?.remove();
  btn.querySelector(".node-navigation-workspace-counter-flag")?.remove();
}

function appendWorkspaceCounterButtonContent(btn, slot, labelNode) {
  clearWorkspaceCounterButtonMetrics(btn);
  btn.querySelector(".node-navigation-workspace-counter-icon")?.remove();
  btn.prepend(
    createWorkspaceCounterStatusPoint(slot),
    createWorkspaceCounterSlotIcon(slot),
    labelNode,
    createWorkspaceCounterMetric(slot)
  );
}

function getEntryOverviewDataSlotBarManifestPath(topicPath) {
  return getWorkspaceStorageManifestApiPath(topicPath || getResolvedNodePath(activePath));
}

function syncAllWorkspaceCounterStripActiveStates(context = activeEntryOverviewContext) {
  nodeOverviewContentNode
    ?.querySelectorAll(".node-navigation-workspace-counters")
    .forEach((wrap) => syncEntryOverviewDataSlotBarActiveState(wrap, context));
}

function syncEntryOverviewDataSlotBarActiveState(wrap, context) {
  if (!wrap) return;
  wrap.querySelector(".node-entry-overview-memory-mode-counters")?.remove();
  const activeSlotKey = getDataStorageSlotKeyForEntryView();
  wrap.querySelectorAll("[data-entry-overview-slot-key]").forEach((host) => {
    const btn = host.classList.contains("node-navigation-workspace-counter")
      ? host
      : host.querySelector(".node-navigation-workspace-counter");
    if (!btn) return;
    const isActive = activeSlotKey === host.dataset.entryOverviewSlotKey;
    btn.classList.toggle("is-active", isActive);
    btn.setAttribute("aria-selected", isActive ? "true" : "false");
  });
}

function updateEntryOverviewDataSlotBarCounts(wrap, slots = []) {
  if (!wrap) return;
  for (const slot of slots) {
    const card = wrap.querySelector(`[data-entry-overview-slot-key="${slot.id}"]`);
    if (!card) continue;
    const btn = card.classList.contains("node-navigation-workspace-counter")
      ? card
      : card.querySelector(".node-navigation-workspace-counter");
    if (!btn) continue;

    const labelNode = btn.querySelector(".node-navigation-workspace-counter-label");
    clearWorkspaceCounterButtonMetrics(btn);
    const icon = btn.querySelector(".node-navigation-workspace-counter-icon");
    if (icon) {
      btn.insertBefore(createWorkspaceCounterStatusPoint(slot), icon);
    } else {
      btn.prepend(createWorkspaceCounterStatusPoint(slot));
    }
    btn.appendChild(createWorkspaceCounterMetric(slot));

    btn.title = isDeprecatedRepositoryCounterSlot(slot)
      ? "Репозитории — откажемся от этого слота"
      : slot.title || "";
    btn.className = `${getWorkspaceCounterButtonStateClasses(slot)}${btn.classList.contains("is-active") ? " is-active" : ""}`;
    btn.classList.remove("is-pending", "is-unread");
    if (slot.tone) btn.classList.add(`is-${slot.tone}`);

    applyWorkspaceCounterLabelForSlot(labelNode, slot);

    syncWorkspaceCounterIndexButton(
      card.querySelector(".node-navigation-workspace-counter-index"),
      slot
    );
  }
  if (wrap.dataset.topicIndexFooter !== "0") {
    appendWorkspaceCounterTopicIndexFooter(
      wrap,
      wrap.dataset.topicNodePath || getResolvedNodePath(activePath),
      slots
    );
  }
}

function renderEntryOverviewDataSlotBarContent(wrap, context, slots = [], topicPath = null) {
  const activeSlotKey = getDataStorageSlotKeyForEntryView();
  const resolvedTopicPath = topicPath || wrap?.dataset.topicNodePath || getResolvedNodePath(activePath);
  wrap.replaceChildren();
  delete wrap.dataset.loading;

  if (!slots.length) return;

  const list = document.createElement("ul");
  list.className = "node-navigation-workspace-counter-list";
  list.setAttribute("role", "tablist");

  const gridSlots = slots.filter((slot) => !isStorageSlotCounterFullWidth(slot));
  const fullWidthSlots = slots.filter((slot) => isStorageSlotCounterFullWidth(slot));

  for (const slot of gridSlots) {
    const item = document.createElement("li");
    item.className = "node-navigation-workspace-counter-item";
    const card = createWorkspaceCounterCard(slot, {
      isActive: activeSlotKey === slot.id,
      topicPath: resolvedTopicPath,
      onClick: () => setActiveDataStorageSlotFromOverview(slot.spec)
    });
    card.dataset.entryOverviewSlotKey = slot.id;
    item.appendChild(card);
    list.appendChild(item);
  }

  wrap.appendChild(list);
  for (const slot of fullWidthSlots) {
    appendWorkspaceFullWidthCounterRow(wrap, slot, {
      isActive: activeSlotKey === slot.id,
      topicPath: resolvedTopicPath,
      entryOverviewSlotKey: slot.id,
      onClick: () => setActiveDataStorageSlotFromOverview(slot.spec)
    });
  }
  appendWorkspaceCounterTopicIndexFooter(wrap, resolvedTopicPath, slots);
}

function acquireEntryOverviewDataSlotBar(context, topicPath) {
  if (getNodeWorkspaceDomain() !== NODE_WORKSPACE_DOMAIN_DATA) return null;
  if (!isDataEntryOverviewMemoryKind(context?.memoryKind)) return null;

  const manifestPath = getEntryOverviewDataSlotBarManifestPath(topicPath);
  const existing = nodeOverviewContentNode?.querySelector(
    ".node-navigation-hub > .node-entry-overview-slot-counters"
  );
  if (
    existing?.dataset.topicPath === manifestPath &&
    existing.querySelector(".node-navigation-workspace-counter-list")
  ) {
    existing.remove();
    syncEntryOverviewDataSlotBarActiveState(existing, context);
    return existing;
  }

  return renderEntryOverviewDataSlotBar(context, topicPath);
}

function renderEntryOverviewDataSlotBar(context, topicPath) {
  if (getNodeWorkspaceDomain() !== NODE_WORKSPACE_DOMAIN_DATA) return null;
  if (!isDataEntryOverviewMemoryKind(context?.memoryKind)) return null;

  const manifestPath = getEntryOverviewDataSlotBarManifestPath(topicPath);
  const wrap = document.createElement("div");
  wrap.className = "node-navigation-workspace-counters node-entry-overview-slot-counters";
  wrap.setAttribute("aria-label", "Слоты данных");
  wrap.dataset.topicPath = manifestPath;
  wrap.dataset.topicNodePath = topicPath;

  const cachedSlots = entryOverviewSlotCountersCache.get(manifestPath);
  if (cachedSlots?.length) {
    renderEntryOverviewDataSlotBarContent(wrap, context, cachedSlots, topicPath);
    void refreshEntryOverviewDataSlotBar(wrap, context, topicPath, manifestPath);
  } else {
    wrap.dataset.loading = "true";
    void populateEntryOverviewDataSlotBar(wrap, context, topicPath, manifestPath);
  }

  return wrap;
}

async function populateEntryOverviewDataSlotBar(wrap, context, topicPath, manifestPath) {
  const renderSeq = (wrap._entryOverviewSlotBarSeq = (wrap._entryOverviewSlotBarSeq || 0) + 1);
  let slots = [];
  try {
    slots = await buildEntryOverviewDataSlotCounters(topicPath);
  } catch {
    slots = [];
  }
  if (renderSeq !== wrap._entryOverviewSlotBarSeq || !wrap.isConnected) return;

  entryOverviewSlotCountersCache.set(manifestPath, slots);
  if (wrap.querySelector(".node-navigation-workspace-counter-list")) {
    updateEntryOverviewDataSlotBarCounts(wrap, slots);
    syncAllWorkspaceCounterStripActiveStates(context);
    delete wrap.dataset.loading;
    return;
  }
  renderEntryOverviewDataSlotBarContent(wrap, context, slots, topicPath);
  syncAllWorkspaceCounterStripActiveStates(context);
}

async function refreshEntryOverviewDataSlotBar(wrap, context, topicPath, manifestPath) {
  const renderSeq = (wrap._entryOverviewSlotBarRefreshSeq = (wrap._entryOverviewSlotBarRefreshSeq || 0) + 1);
  let slots = [];
  try {
    slots = await buildEntryOverviewDataSlotCounters(topicPath);
  } catch {
    return;
  }
  if (renderSeq !== wrap._entryOverviewSlotBarRefreshSeq || !wrap.isConnected) return;
  entryOverviewSlotCountersCache.set(manifestPath, slots);
  updateEntryOverviewDataSlotBarCounts(wrap, slots);
}

function syncWorkspaceCounterIndexButton(indexBtn, slot) {
  if (!indexBtn) return;
  if (isDeprecatedRepositoryCounterSlot(slot)) {
    indexBtn.classList.add("hidden");
    return;
  }
  const spec = resolveStorageSlotSpecFromCounterSlot(slot);
  const showIndex = Boolean(spec && supportsDataEntryOverview(spec.key));
  indexBtn.classList.toggle("hidden", !showIndex);
  if (!showIndex) return;

  const hasIndex = Boolean(slot.hasIndex);
  const memoryKind = spec ? getEntryOverviewMemoryKindForSlot(spec) : null;
  indexBtn.disabled = false;
  indexBtn.classList.toggle("is-available", hasIndex);
  indexBtn.classList.toggle("is-generated", !hasIndex);
  indexBtn.classList.toggle("is-missing", false);
  if (hasIndex) {
    indexBtn.title = `Открыть ${STORAGE_SLOT_INDEX_FILE} — оглавление слота`;
  } else if (isBundleEntryOverviewMemoryKind(memoryKind)) {
    indexBtn.title = `Собрать оглавление слота (или создайте ${STORAGE_SLOT_INDEX_FILE} рядом с ${spec?.bundleFile || "файлом слота"})`;
  } else {
    indexBtn.title = `Собрать оглавление слота (или создайте ${STORAGE_SLOT_INDEX_FILE} в корне слота)`;
  }
}

function createStaticWorkspaceCounterStubItem({
  itemClass,
  cardClass,
  title,
  hint,
  tooltip,
  staticMarkText = "(static)",
  containerTag = "li"
}) {
  const item = document.createElement(containerTag);
  item.className = `node-navigation-workspace-counter-item ${itemClass}`;

  const card = document.createElement("div");
  card.className = `node-navigation-workspace-counter-card node-navigation-workspace-counter-card--static-stub ${cardClass}`;

  const body = document.createElement("div");
  body.className = "node-navigation-workspace-counter is-empty is-static-stub";
  body.setAttribute("aria-disabled", "true");
  body.title = tooltip;

  const value = document.createElement("span");
  value.className = "node-navigation-workspace-counter-value";
  value.textContent = "—";

  const label = document.createElement("span");
  label.className = "node-navigation-workspace-counter-label node-navigation-workspace-counter-label--stacked";

  const labelMain = document.createElement("span");
  labelMain.className = "node-navigation-workspace-counter-label-main";
  labelMain.textContent = title;

  label.appendChild(labelMain);
  if (hint) {
    const labelHint = document.createElement("span");
    labelHint.className = "node-navigation-workspace-counter-label-hint";
    labelHint.textContent = hint;
    label.appendChild(labelHint);
  }

  const staticMark = document.createElement("span");
  staticMark.className = "stub-static-mark";
  staticMark.textContent = staticMarkText;
  label.appendChild(staticMark);

  body.append(value, label);
  card.append(body);
  item.append(card);
  return item;
}

function isStorageSlotCounterFullWidth(slot) {
  return Boolean(slot?.counterFullWidth || slot?.spec?.counterFullWidth);
}

function appendWorkspaceFullWidthCounterRow(
  wrap,
  slot,
  { isActive = false, topicPath = null, onClick, entryOverviewSlotKey = null } = {}
) {
  if (!wrap || !slot) return;
  const row = document.createElement("div");
  row.className = "node-navigation-workspace-fullwidth-slot-row";
  const item = document.createElement("div");
  item.className = "node-navigation-workspace-counter-item node-navigation-workspace-counter-item--fullwidth-slot";
  const card = createWorkspaceCounterCard(slot, {
    isActive,
    topicPath,
    onClick
  });
  if (entryOverviewSlotKey) {
    card.dataset.entryOverviewSlotKey = entryOverviewSlotKey;
  }
  item.appendChild(card);
  row.appendChild(item);
  wrap.appendChild(row);
  wrap.classList.add("has-fullwidth-slot-counter");
}

const PAGE_OUTSIDE_SLOTS_SCOPE_LABELS = {
  "page-root": "Корень страницы",
  "storage-root": "awn-storage/ (файл в корне)",
  storage: "awn-storage/ (не слот)"
};

async function fetchPageOutsideSlotsReport(manifestPath) {
  const response = await fetch(buildApiUrl("/api/agent/page-outside-slots", { path: manifestPath }));
  if (!response.ok) {
    throw new Error(`page-outside-slots ${response.status}`);
  }
  return response.json();
}

function createOutsideSlotsMoveToInboxButton() {
  const btn = document.createElement("button");
  btn.type = "button";
  btn.className = "node-navigation-outside-slots-warning-move-inbox-btn";
  btn.textContent = "Переместить во входящие - выполнять в ручную!";
  btn.disabled = true;
  btn.setAttribute("aria-disabled", "true");
  return btn;
}

function createOutsideSlotsMoveToInboxActions() {
  const footer = document.createElement("div");
  footer.className = "node-navigation-outside-slots-warning-actions";
  footer.appendChild(createOutsideSlotsMoveToInboxButton());
  return footer;
}

function renderPageOutsideSlotsWarningPanel(report, topicPath) {
  const panel = document.createElement("section");
  panel.className = "node-navigation-outside-slots-warning";
  panel.setAttribute("role", "note");
  panel.setAttribute("aria-label", "Вне слотов");

  const header = document.createElement("div");
  header.className = "node-navigation-outside-slots-warning-header";

  const title = document.createElement("h3");
  title.className = "node-navigation-outside-slots-warning-title";
  title.textContent = "Вне слотов";

  const hint = document.createElement("p");
  hint.className = "node-navigation-outside-slots-warning-hint";
  hint.textContent =
    "Файлы и папки вне разрешённой структуры страницы. В корне — только manifest, index, config/schema, env и однофайловые слоты; в awn-storage/ при типовых слотах — только папки слотов.";

  header.append(title, hint);

  const list = document.createElement("ul");
  list.className = "node-navigation-outside-slots-warning-list";

  for (const item of report?.items || []) {
    const row = document.createElement("li");
    row.className = "node-navigation-outside-slots-warning-item";

    const scope = document.createElement("span");
    scope.className = "node-navigation-outside-slots-warning-scope";
    scope.textContent = PAGE_OUTSIDE_SLOTS_SCOPE_LABELS[item.scope] || item.scope || "—";

    const btn = document.createElement("button");
    btn.type = "button";
    btn.className = "node-navigation-outside-slots-warning-path";
    btn.textContent = item.relPath || item.name || "—";
    btn.title = item.kind === "folder" ? "Открыть папку" : "Открыть файл";
    btn.addEventListener("click", (event) => {
      event.preventDefault();
      event.stopPropagation();
      const relPath = String(item.relPath || "").trim();
      if (!relPath) return;
      if (item.kind === "folder") {
        void openFolderBrowseFromMenu(item.name || relPath, relPath);
        return;
      }
      void selectFile(item.name || relPath, relPath);
    });

    row.append(scope, btn);
    list.appendChild(row);
  }

  panel.append(header, list, createOutsideSlotsMoveToInboxActions());
  return panel;
}

function applyPageOutsideSlotsWarningRow(row, wrap, topicPath, report) {
  row.replaceChildren();
  if (!report?.items?.length) {
    row.hidden = true;
    wrap.classList.remove("has-outside-slots-warning");
    return;
  }
  row.hidden = false;
  wrap.classList.add("has-outside-slots-warning");
  row.appendChild(renderPageOutsideSlotsWarningPanel(report, topicPath));
}

async function refreshWorkspaceOutsideSlotsRow(row, wrap, topicPath, prefetchedReport = null) {
  if (!row || !wrap || !topicPath) return;
  const manifestPath = getOverviewNodeApiPath(topicPath);
  if (!manifestPath) {
    row.hidden = true;
    wrap.classList.remove("has-outside-slots-warning");
    return;
  }
  try {
    const report = prefetchedReport || (await fetchPageOutsideSlotsReport(manifestPath));
    if (!row.isConnected) return;
    applyPageOutsideSlotsWarningRow(row, wrap, topicPath, report);
  } catch {
    if (row.isConnected) {
      row.hidden = true;
      wrap.classList.remove("has-outside-slots-warning");
    }
  }
}

