function renderEntryOverviewMemoryTrail(context, navigationIndex, title, topicTitle) {
  if (!navigationIndex || !isDataEntryOverviewMemoryKind(context.memoryKind)) {
    return null;
  }

  const tocTitle = getEntryOverviewTocTitle(context.memoryKind);
  const segments = buildEntryOverviewTrailSegments(context, navigationIndex.folderLabels, title);
  const trail = document.createElement("nav");
  trail.className = "node-entry-overview-memory-trail";
  trail.setAttribute("aria-label", "Оглавление");

  const homeBtn = document.createElement("button");
  homeBtn.type = "button";
  homeBtn.className = "node-entry-overview-memory-trail-segment is-link node-entry-overview-memory-trail-home";
  homeBtn.textContent = topicTitle || "Топик";
  homeBtn.title = "Топик";
  homeBtn.setAttribute("aria-label", `Топик: ${topicTitle || "тема"}`);
  homeBtn.addEventListener("click", () => {
    if (!activePath) return;
    setContentMode(NODE_NAVIGATION_MODE);
  });
  trail.appendChild(homeBtn);

  appendEntryOverviewTrailSeparator(trail);

  const isMemoryTocRoot = isEntryOverviewMemoryTocRoot(context);
  if (isMemoryTocRoot) {
    const tocCurrent = document.createElement("span");
    tocCurrent.className =
      "node-entry-overview-memory-trail-segment is-current node-entry-overview-memory-trail-toc";
    tocCurrent.textContent = "Оглавление";
    tocCurrent.title = tocTitle;
    trail.appendChild(tocCurrent);
  } else {
    const tocBtn = document.createElement("button");
    tocBtn.type = "button";
    tocBtn.className = "node-entry-overview-memory-trail-segment is-link node-entry-overview-memory-trail-toc";
    tocBtn.textContent = "Оглавление";
    tocBtn.title = tocTitle;
    tocBtn.addEventListener("click", () => {
      openEntryOverviewMemoryTocFromNavigation(context.memoryKind);
    });
    trail.appendChild(tocBtn);
  }

  const handlers = getEntryOverviewNavigationHandlers(context.memoryKind);

  for (const segment of segments) {
    appendEntryOverviewTrailSeparator(trail);

    if (segment.isCurrent) {
      const current = document.createElement("span");
      current.className = "node-entry-overview-memory-trail-segment is-current";
      current.textContent = segment.label;
      current.title = segment.path;
      trail.appendChild(current);
      continue;
    }

    const btn = document.createElement("button");
    btn.type = "button";
    btn.className = "node-entry-overview-memory-trail-segment is-link";
    btn.textContent = segment.label;
    btn.title = segment.path;
    btn.addEventListener("click", () => {
      if (segment.kind === "folder") {
        handlers.onFolderClick(segment.path);
        return;
      }
      handlers.onFileClick({ path: segment.path, title: segment.label });
    });
    trail.appendChild(btn);
  }

  return trail;
}

function getEntryOverviewSectionFolderPath(context) {
  const relativePath = String(context.relativePath || "").replace(/\\/g, "/").replace(/^\/+/, "");
  if (context.memoryKind === "assets" && context.entryKind === "awn.assets.folder") {
    return relativePath.replace(/\/$/, "") || null;
  }
  const isCategory =
    context.entryKind === "awn.record.category" ||
    context.entryKind === "awn.media.category" ||
    isSectionReadmePath(relativePath);
  if (!isCategory || !isSectionReadmePath(relativePath)) return null;
  return relativePath.slice(0, -AREA_MANIFEST_FILE.length).replace(/\/$/, "");
}

function getEntryOverviewParentFolderPath(context) {
  const relativePath = String(context.relativePath || "").replace(/\\/g, "/").replace(/^\/+/, "");
  if (!relativePath) return "";
  const isCategory =
    context.entryKind === "awn.record.category" || context.entryKind === "awn.media.category";
  if (isCategory && isSectionReadmePath(relativePath)) {
    return relativePath.slice(0, -AREA_MANIFEST_FILE.length).replace(/\/$/, "");
  }
  const slash = relativePath.lastIndexOf("/");
  return slash === -1 ? "" : relativePath.slice(0, slash);
}

function getEntryOverviewSiblingFiles(context, navigationIndex) {
  if (!navigationIndex || isEntryOverviewMemoryTocRoot(context)) return [];

  const parentFolder = getEntryOverviewParentFolderPath(context);
  const prefix = parentFolder ? `${parentFolder}/` : "";

  return (navigationIndex.contentFiles || [])
    .filter((item) => {
      const path = String(item.path || "").replace(/\\/g, "/");
      if (!path || isSectionReadmePath(path)) return false;
      if (context.memoryKind !== "assets" && isMemorySectionInfrastructureFilePath(path)) {
        return false;
      }
      if (parentFolder) {
        if (!path.startsWith(prefix)) return false;
        const rel = path.slice(prefix.length);
        return rel && !rel.includes("/");
      }
      return !path.includes("/");
    })
    .sort((a, b) => compareNavigationPathsNatural(a.path, b.path));
}

function getEntryOverviewSiblingSectionFolders(context, navigationIndex) {
  if (!navigationIndex || !isEntryOverviewCategoryContext(context)) return [];

  const relativePath = String(context.relativePath || "").replace(/\\/g, "/").replace(/^\/+/, "");
  if (!isSectionReadmePath(relativePath)) return [];

  const sectionFolder = relativePath.slice(0, -AREA_MANIFEST_FILE.length).replace(/\/$/, "");
  const parentFolder = sectionFolder.includes("/")
    ? sectionFolder.slice(0, sectionFolder.lastIndexOf("/"))
    : "";
  const prefix = parentFolder ? `${parentFolder}/` : "";
  const folderLabels =
    navigationIndex.folderLabels instanceof Map ? navigationIndex.folderLabels : new Map();
  const folderPaths =
    navigationIndex.folderPaths instanceof Set ? navigationIndex.folderPaths : new Set();

  const entries = [];
  for (const folderPath of folderPaths) {
    const path = String(folderPath || "").replace(/\\/g, "/").replace(/\/$/, "");
    if (!path || path === sectionFolder) continue;
    if (parentFolder) {
      if (!path.startsWith(prefix)) continue;
      const rel = path.slice(prefix.length);
      if (!rel || rel.includes("/")) continue;
    } else if (path.includes("/")) {
      continue;
    }
    const title =
      String(folderLabels.get(path) || "").trim() || path.split("/").pop() || path;
    entries.push({
      path: `${path}/${AREA_MANIFEST_FILE}`,
      folderPath: path,
      title,
      isSectionCategory: true
    });
  }

  return entries.sort((a, b) => compareNavigationPathsNatural(a.path, b.path));
}

function getEntryOverviewSiblingEntries(context, navigationIndex) {
  if (isEntryOverviewCategoryContext(context) && isSectionReadmePath(String(context.relativePath || ""))) {
    const sectionSiblings = getEntryOverviewSiblingSectionFolders(context, navigationIndex);
    if (sectionSiblings.length) return sectionSiblings;
  }
  return getEntryOverviewSiblingFiles(context, navigationIndex);
}

function getEntryOverviewAdjacentSiblings(context, navigationIndex) {
  const siblings = getEntryOverviewSiblingEntries(context, navigationIndex);
  const currentPath = String(context.relativePath || "").replace(/\\/g, "/").replace(/^\/+/, "");
  const index = siblings.findIndex((item) => String(item.path || "").replace(/\\/g, "/") === currentPath);
  if (index === -1) return { prev: null, next: null };
  return {
    prev: index > 0 ? siblings[index - 1] : null,
    next: index < siblings.length - 1 ? siblings[index + 1] : null
  };
}

function resolveEntryOverviewUpNavigation(context) {
  if (!context || isEntryOverviewMemoryTocRoot(context)) return null;

  const relativePath = String(context.relativePath || "").replace(/\\/g, "/").replace(/^\/+/, "");
  const isCategory =
    context.entryKind === "awn.record.category" || context.entryKind === "awn.media.category";

  let parentFolder = "";
  if (isCategory && isSectionReadmePath(relativePath)) {
    const folderPath = relativePath.slice(0, -AREA_MANIFEST_FILE.length).replace(/\/$/, "");
    const slash = folderPath.lastIndexOf("/");
    parentFolder = slash === -1 ? "" : folderPath.slice(0, slash);
  } else {
    parentFolder = getEntryOverviewParentFolderPath(context);
  }

  if (parentFolder) {
    return { kind: "folder", folderPath: parentFolder };
  }
  return { kind: "toc" };
}

function buildEntryOverviewBrowseTocNavOptions(context, topicPath = activePath) {
  if (!context || !isEntryOverviewMemoryTocRoot(context)) return null;

  const resolvedTopicPath = getResolvedNodePath(topicPath) || getActiveNodeApiPath() || activePath;
  if (isHubWorkspaceFilesSlotPage(resolvedTopicPath)) {
    const topicLabel = getEntryOverviewTopicTitle();
    const channelPage = isAwnChannelPageNodePath(resolvedTopicPath);
    return {
      prevItem: null,
      nextItem: null,
      onFileClick: null,
      onUpClick: resolvedTopicPath
        ? () => {
            void openNodeNavigation(topicLabel, resolvedTopicPath);
          }
        : null,
      upTitle: topicLabel || (channelPage ? "Канал" : "Медиатека"),
      ariaLabel: channelPage ? "Навигация по каналу" : "Навигация по медиатеке"
    };
  }

  return buildEntryOverviewSlotTocNavOptions(context, topicPath);
}

function buildEntryOverviewSlotTocNavOptions(context, topicPath = activePath) {
  if (!context || !isEntryOverviewMemoryTocRoot(context)) return null;

  let overviewSpecs = DATA_STORAGE_SLOT_SPECS.filter((spec) =>
    shouldShowEntryOverviewSlotCounter(spec, topicPath)
  );
  overviewSpecs = filterTopicFlexibleSingleFileSlotSpecs(overviewSpecs, topicPath);
  const currentKind = String(context.memoryKind || "").trim();
  const currentIndex = overviewSpecs.findIndex((spec) => {
    const kind = getEntryOverviewMemoryKindForSlot(spec);
    return kind === currentKind || spec.key === currentKind || spec.defaultMode === currentKind;
  });

  const prevSpec = currentIndex > 0 ? overviewSpecs[currentIndex - 1] : null;
  const nextSpec =
    currentIndex >= 0 && currentIndex < overviewSpecs.length - 1
      ? overviewSpecs[currentIndex + 1]
      : null;

  const openSlotToc = (spec) => {
    if (!spec) return;
    openEntryOverviewMemoryTocFromNavigation(getEntryOverviewMemoryKindForSlot(spec) || spec.defaultMode);
  };

  const topicLabel = getEntryOverviewTopicTitle();
  const resolvedTopicPath = getResolvedNodePath(topicPath) || getActiveNodeApiPath() || activePath;

  return {
    prevItem: prevSpec ? { title: prevSpec.label, label: prevSpec.label, path: prevSpec.key } : null,
    nextItem: nextSpec ? { title: nextSpec.label, label: nextSpec.label, path: nextSpec.key } : null,
    onFileClick: (item) => {
      const spec = overviewSpecs.find((entry) => entry.key === item?.path);
      openSlotToc(spec);
    },
    onUpClick: resolvedTopicPath
      ? () => {
          void openNodeNavigation(topicLabel, resolvedTopicPath);
        }
      : null,
    upTitle: topicLabel || "Тема",
    ariaLabel: "Навигация по слотам данных"
  };
}

function getEntryOverviewBrowsePanelChromeInsertBefore(panel) {
  if (!panel) return null;
  return (
    panel.querySelector(":scope > .node-entry-overview-browse-toolbar") ||
    panel.querySelector(
      ":scope > .node-entry-overview-memory-toc, :scope > .node-entry-overview-section-list"
    )
  );
}

function finalizeEntryOverviewBrowseSlotFolderMissingLayout(panel) {
  if (!panel?.classList.contains("is-slot-folder-missing")) return;

  const toolbar = panel.querySelector(":scope > .node-entry-overview-browse-toolbar");
  const notice = panel.querySelector(":scope > .node-entry-overview-slot-folder-missing");
  if (!toolbar || !notice) return;

  const strip = panel.querySelector(":scope > .node-entry-overview-browse-slot-counters");
  const hero = panel.querySelector(":scope > .node-entry-overview-browse-hero-nav");
  const search = panel.querySelector(":scope > .node-entry-overview-cross-slot-search");

  panel.insertBefore(notice, toolbar);
  if (hero) panel.insertBefore(hero, notice);
  if (strip) panel.insertBefore(strip, hero || notice);
  if (search && strip) panel.insertBefore(search, strip);
}

function finalizeEntryOverviewBrowsePanelChromeOrder(panel) {
  if (!panel) return;

  const strip = panel.querySelector(":scope > .node-entry-overview-browse-slot-counters");
  const hero = panel.querySelector(":scope > .node-entry-overview-browse-hero-nav");
  const search = panel.querySelector(":scope > .node-entry-overview-cross-slot-search");

  if (strip) {
    panel.prepend(strip);
    if (search) panel.insertBefore(search, strip);
    if (hero) strip.insertAdjacentElement("afterend", hero);
  } else if (hero) {
    panel.prepend(hero);
    if (search) panel.insertBefore(search, hero);
  } else if (search) {
    panel.prepend(search);
  }

  finalizeEntryOverviewBrowseSlotFolderMissingLayout(panel);

  const hubMain = panel.closest(".node-navigation-hub-main");
  if (hubMain) {
    syncEntryOverviewCrossSlotSearchChrome(
      hubMain,
      activeEntryOverviewContext,
      getResolvedNodePath(activePath)
    );
  }
}

function dedupeEntryOverviewSlotCounterStrips(hubMain) {
  if (!hubMain) return null;

  const strips = Array.from(
    hubMain.querySelectorAll(
      ".node-entry-overview-browse-slot-counters, .node-entry-overview-hub-main-slot-counters, .node-entry-overview-hub-workspace-slot-counters"
    )
  );
  if (!strips.length) return null;
  if (strips.length === 1) return strips[0];

  let keeper =
    strips.find((strip) => strip.classList.contains("node-entry-overview-hub-workspace-slot-counters")) ||
    strips.find((strip) => strip.parentElement === hubMain) ||
    strips.find((strip) => strip.classList.contains("node-entry-overview-hub-top-slot-counters")) ||
    strips[0];
  strips.forEach((strip) => {
    if (strip !== keeper) strip.remove();
  });
  return keeper;
}

function resolveHubWorkspaceSlotCounterActiveKey(context, hubPolicy) {
  if (!hubPolicy) return getDataStorageSlotKeyForEntryView(NODE_ENTRY_OVERVIEW_MODE);
  const fromView = getDataStorageSlotKeyForEntryView(NODE_ENTRY_OVERVIEW_MODE);
  if (fromView && hubPolicy.slotKeys.includes(fromView)) return fromView;
  const memoryKind = String(context?.memoryKind || "").trim();
  if (memoryKind) {
    const fromKind = getDataStorageSlotForMode(memoryKind)?.key;
    if (fromKind && hubPolicy.slotKeys.includes(fromKind)) return fromKind;
  }
  return (
    getDataStorageSlotForMode(hubPolicy.defaultMemoryKind)?.key || hubPolicy.slotKeys[0] || null
  );
}

function renderHubWorkspaceSlotCounterStripElement(
  context,
  topicPath,
  propsEntries = null,
  { activeSlotKey = null } = {}
) {
  const resolvedTopicPath = topicPath || getResolvedNodePath(activePath);
  const hubPolicy = resolveHubWorkspaceSlotPolicy(resolvedTopicPath, propsEntries);
  if (!hubPolicy || !shouldShowHubWorkspaceSlotStrip(resolvedTopicPath, hubPolicy.slotKeys.length, propsEntries)) {
    return null;
  }
  const manifestPath = getEntryOverviewDataSlotBarManifestPath(resolvedTopicPath);
  const cachedSlots = entryOverviewSlotCountersCache.get(manifestPath);
  const slots = mergeHubPolicySlotCounters(
    hubPolicy,
    filterHubWorkspaceSlotCounters(resolvedTopicPath, cachedSlots || [], propsEntries)
  );
  if (!slots.length) return null;

  const strip = renderNodeNavigationWorkspaceCounterStrip(
    slots.map((slot) => ({
      ...slot,
      modeId: slot.spec?.defaultMode || slot.id
    })),
    {
      entryOverview: true,
      activeSlotKey: activeSlotKey ?? resolveHubWorkspaceSlotCounterActiveKey(context, hubPolicy),
      topicPath: resolvedTopicPath,
      includeTopicIndexFooter: false
    }
  );
  if (!strip) return null;
  strip.classList.add(
    "node-entry-overview-slot-counters",
    "node-entry-overview-hub-top-slot-counters",
    "node-entry-overview-hub-workspace-slot-counters"
  );
  strip.dataset.topicIndexFooter = "0";
  strip.dataset.topicNodePath = resolvedTopicPath;
  strip.setAttribute("aria-label", "Слоты данных");
  return strip;
}

function detachPreservedHubWorkspaceSlotCounterStrip(topicPath) {
  const resolvedTopicPath = getResolvedNodePath(topicPath);
  if (!resolvedTopicPath || !nodeOverviewContentNode) return null;
  const prevMain = nodeOverviewContentNode.querySelector(".node-navigation-hub-main");
  const prevStrip = prevMain?.querySelector(":scope > .node-entry-overview-hub-workspace-slot-counters");
  if (
    !prevStrip ||
    prevStrip.dataset.topicNodePath !== resolvedTopicPath ||
    !prevStrip.querySelector(".node-navigation-workspace-counter-list")
  ) {
    return null;
  }
  prevStrip.remove();
  return prevStrip;
}

function tryRefreshHubChannelEntryOverviewInPlace(context, topicPath, navigationIndex, isStale) {
  if (isStale()) return false;
  const policy = resolveHubWorkspaceSlotPolicy(topicPath);
  if (!policy || policy.kind !== "channel" || !isHubWorkspaceFilesSlotPage(topicPath)) return false;
  if (!isEntryOverviewMemoryTocRoot(context) || !nodeOverviewContentNode) return false;

  const hub = nodeOverviewContentNode.querySelector(".node-navigation-hub.is-awn-channel-workspace-hub");
  const hubMain = hub?.querySelector(":scope > .node-navigation-hub-main");
  if (!hubMain) return false;

  const resolvedTopicPath = getResolvedNodePath(topicPath);
  const activeResolved = getResolvedNodePath(activePath);
  if (activeResolved && resolvedTopicPath !== activeResolved) return false;
  const strip = hubMain.querySelector(":scope > .node-entry-overview-hub-workspace-slot-counters");
  const iblock = hubMain.querySelector(":scope > .media-library-workspace-iblock-layout");
  const panel = hubMain.querySelector(":scope > .node-entry-overview-browse-panel");
  if (!strip || !iblock || !panel || strip.dataset.topicNodePath !== resolvedTopicPath) return false;

  const channelContext = buildHubChannelWorkspaceBrowseContext(topicPath, context?.propsEntries);
  entryOverviewSearchState = { context: channelContext, navigationIndex, isMemoryTocRoot: true };
  entryOverviewBreadcrumbState = { context: channelContext, navigationIndex, title: "Оглавление" };
  if (activeEntryOverviewContext && isEntryOverviewMemoryTocRoot(activeEntryOverviewContext)) {
    activeEntryOverviewContext = {
      ...activeEntryOverviewContext,
      relPath: channelContext.relPath,
      memoryKind: channelContext.memoryKind,
      entryKind: channelContext.entryKind
    };
  }
  syncEntryOverviewKindClass(getEntryOverviewKindClass(channelContext.entryKind));
  syncEntryOverviewMediaAssetKindClass(null);

  void refreshHubChannelBrowsePanelContent(panel, channelContext, navigationIndex, topicPath);

  const browseNavOptions = buildEntryOverviewBrowseTocNavOptions(context, topicPath);
  if (browseNavOptions) {
    panel.querySelector(":scope > .node-entry-overview-browse-hero-nav")?.remove();
    prependEntryOverviewBrowseHeroNav(panel, browseNavOptions);
  }

  syncAllWorkspaceCounterStripActiveStates(context);
  refreshEntryOverviewSlotCounterStripCounts(strip, context, resolvedTopicPath, { force: false });
  updateBreadcrumbsForActiveMode();
  scheduleWorkspaceScrollChromeSync();
  syncDataHubSlugWarning(NODE_ENTRY_OVERVIEW_MODE);

  return true;
}

function tryRefreshHubMediaEntryOverviewInPlace(context, topicPath, navigationIndex, isStale) {
  if (isStale()) return false;
  const policy = resolveHubWorkspaceSlotPolicy(topicPath);
  if (!policy || policy.kind !== "media" || !isHubWorkspaceFilesSlotPage(topicPath)) return false;
  if (!isEntryOverviewMemoryTocRoot(context) || !nodeOverviewContentNode) return false;

  const hub = nodeOverviewContentNode.querySelector(
    ".node-navigation-hub.is-media-library-workspace-hub:not(.is-awn-channel-workspace-hub)"
  );
  const hubMain = hub?.querySelector(":scope > .node-navigation-hub-main");
  if (!hubMain) return false;

  const resolvedTopicPath = getResolvedNodePath(topicPath);
  const activeResolved = getResolvedNodePath(activePath);
  if (activeResolved && resolvedTopicPath !== activeResolved) return false;
  const strip = hubMain.querySelector(":scope > .node-entry-overview-hub-workspace-slot-counters");
  const iblock = hubMain.querySelector(":scope > .media-library-workspace-iblock-layout");
  const panel = hubMain.querySelector(":scope > .node-entry-overview-browse-panel");
  if (!iblock || !panel) return false;
  const panelTopicPath = panel.dataset.topicNodePath || strip?.dataset.topicNodePath || "";
  if (panelTopicPath && panelTopicPath !== resolvedTopicPath) return false;
  if (strip && strip.dataset.topicNodePath !== resolvedTopicPath) return false;

  const mediaContext = buildHubMediaWorkspaceBrowseContext(topicPath, context?.propsEntries);
  entryOverviewSearchState = { context: mediaContext, navigationIndex, isMemoryTocRoot: true };
  entryOverviewBreadcrumbState = { context: mediaContext, navigationIndex, title: "Оглавление" };
  if (activeEntryOverviewContext && isEntryOverviewMemoryTocRoot(activeEntryOverviewContext)) {
    activeEntryOverviewContext = {
      ...activeEntryOverviewContext,
      relPath: mediaContext.relPath,
      memoryKind: mediaContext.memoryKind,
      entryKind: mediaContext.entryKind
    };
  }
  syncEntryOverviewKindClass(getEntryOverviewKindClass(mediaContext.entryKind));
  syncEntryOverviewMediaAssetKindClass(null);

  void refreshHubMediaBrowsePanelContent(panel, mediaContext, navigationIndex, topicPath);

  const browseNavOptions = buildEntryOverviewBrowseTocNavOptions(context, topicPath);
  if (browseNavOptions) {
    panel.querySelector(":scope > .node-entry-overview-browse-hero-nav")?.remove();
    prependEntryOverviewBrowseHeroNav(panel, browseNavOptions);
  }

  syncAllWorkspaceCounterStripActiveStates(context);
  if (strip) {
    refreshEntryOverviewSlotCounterStripCounts(strip, context, resolvedTopicPath, { force: false });
  }
  updateBreadcrumbsForActiveMode();
  scheduleWorkspaceScrollChromeSync();
  syncDataHubSlugWarning(NODE_ENTRY_OVERVIEW_MODE);

  return true;
}

function relocateEntryOverviewSlotCountersChrome(hubMain) {
  if (!hubMain) return;

  const workspaceStrip = hubMain.querySelector(":scope > .node-entry-overview-hub-workspace-slot-counters");
  if (workspaceStrip) {
    const iblock = hubMain.querySelector(":scope > .media-library-workspace-iblock-layout");
    if (iblock && workspaceStrip.nextElementSibling !== iblock) {
      hubMain.insertBefore(workspaceStrip, iblock);
    }
    syncAllWorkspaceCounterStripActiveStates();
    return;
  }

  const strip = dedupeEntryOverviewSlotCounterStrips(hubMain);
  if (!strip) {
    hubMain.querySelectorAll(".node-entry-overview-cross-slot-search").forEach((node) => node.remove());
    return;
  }

  const iblock = hubMain.querySelector(":scope > .media-library-workspace-iblock-layout");
  if (iblock) {
    if (strip.nextElementSibling !== iblock) {
      hubMain.insertBefore(strip, iblock);
    }
    strip.classList.add("node-entry-overview-hub-top-slot-counters");
    strip.classList.remove("node-entry-overview-manifest-top-slot-counters");
    syncEntryOverviewCrossSlotSearchChrome(
      hubMain,
      activeEntryOverviewContext,
      strip.dataset.topicNodePath || getResolvedNodePath(activePath)
    );
    return;
  }

  const hero = hubMain.querySelector(
    ":scope > .node-navigation-hero, :scope > .node-entry-overview-media-asset"
  );
  if (hero) {
    if (strip.nextElementSibling !== hero) {
      hubMain.insertBefore(strip, hero);
    }
    strip.classList.add("node-entry-overview-hub-top-slot-counters");
    strip.classList.remove("node-entry-overview-manifest-top-slot-counters");
    syncEntryOverviewCrossSlotSearchChrome(
      hubMain,
      activeEntryOverviewContext,
      strip.dataset.topicNodePath || getResolvedNodePath(activePath)
    );
    return;
  }

  const manifest = hubMain.querySelector(":scope > .node-entry-overview-manifest");
  if (!manifest || !manifest.contains(strip)) {
    syncEntryOverviewCrossSlotSearchChrome(
      hubMain,
      activeEntryOverviewContext,
      strip.dataset.topicNodePath || getResolvedNodePath(activePath)
    );
    return;
  }
  if (strip.parentElement !== manifest || strip !== manifest.firstElementChild) {
    manifest.insertBefore(strip, manifest.firstChild);
  }
  strip.classList.add("node-entry-overview-manifest-top-slot-counters");
  strip.classList.remove("node-entry-overview-hub-top-slot-counters");
  syncEntryOverviewCrossSlotSearchChrome(
    hubMain,
    activeEntryOverviewContext,
    strip.dataset.topicNodePath || getResolvedNodePath(activePath)
  );
}

function shouldShowEntryOverviewSlotCountersOnHubMain(context) {
  if (isHubWorkspaceFilesSlotPage()) return false;
  if (!context || isEntryOverviewMemoryTocRoot(context)) return false;
  if (getNodeWorkspaceDomain() !== NODE_WORKSPACE_DOMAIN_DATA) return false;
  if (!isDataEntryOverviewMemoryKind(context.memoryKind)) return false;
  // Оглавление слота / раздел: полоса в browse-панели, hero на hub-main нет.
  if (shouldShowEntryOverviewBrowseActions(context)) return false;
  return true;
}

function shouldShowEntryOverviewSlotCountersInHero() {
  return false;
}

function shouldShowEntryOverviewSlotCountersInBrowsePanel(context, isMemoryTocRoot = false) {
  const topicPath = getResolvedNodePath(activePath);
  const policy = resolveHubWorkspaceSlotPolicy(topicPath);
  if (policy) {
    if (!isMemoryTocRoot && !isEntryOverviewMemoryTocRoot(context)) return false;
    return shouldShowHubWorkspaceSlotStrip(topicPath, policy.slotKeys.length);
  }
  if (isHubWorkspaceFilesSlotPage()) return false;
  if (isMemoryTocRoot || isEntryOverviewMemoryTocRoot(context)) return true;
  if (getNodeWorkspaceDomain() !== NODE_WORKSPACE_DOMAIN_DATA) return false;
  if (!isDataEntryOverviewMemoryKind(context.memoryKind)) return false;
  return shouldShowEntryOverviewBrowseActions(context);
}

function renderEntryOverviewSlotCounterStripFromSlots(context, topicPath, slots = []) {
  if (!context || !slots.length) return null;

  const resolvedTopicPath = topicPath || getResolvedNodePath(activePath);
  if (!resolvedTopicPath) return null;

  const strip = renderNodeNavigationWorkspaceCounterStrip(
    slots.map((slot) => ({
      ...slot,
      modeId: slot.spec?.defaultMode || slot.id
    })),
    {
      entryOverview: true,
      activeSlotKey: getDataStorageSlotKeyForEntryView(NODE_ENTRY_OVERVIEW_MODE),
      topicPath: resolvedTopicPath,
      includeTopicIndexFooter: false
    }
  );
  if (!strip) return null;

  strip.classList.add("node-entry-overview-slot-counters");
  strip.dataset.topicIndexFooter = "0";
  strip.dataset.topicNodePath = resolvedTopicPath;
  strip.setAttribute("aria-label", "Слоты данных");
  return strip;
}

async function createEntryOverviewSlotCounterStripElement(context, topicPath, { propsEntries = null } = {}) {
  if (!context) return null;
  const resolvedTopicPath = topicPath || getResolvedNodePath(activePath);
  if (!resolvedTopicPath) return null;
  const hubPolicy = resolveHubWorkspaceSlotPolicy(resolvedTopicPath, propsEntries);

  if (!hubPolicy) {
    if (getNodeWorkspaceDomain() !== NODE_WORKSPACE_DOMAIN_DATA) return null;
    if (!isDataEntryOverviewMemoryKind(context.memoryKind) && !isEntryOverviewMemoryTocRoot(context)) {
      return null;
    }
  }

  let slots = await loadEntryOverviewSlotCounters(resolvedTopicPath, {
    propsEntries,
    hubSlotPolicy: hubPolicy
  });
  slots = filterHubWorkspaceSlotCounters(resolvedTopicPath, slots, propsEntries);
  if (hubPolicy) {
    slots = mergeHubPolicySlotCounters(hubPolicy, slots);
    if (!shouldShowHubWorkspaceSlotStrip(resolvedTopicPath, hubPolicy.slotKeys.length, propsEntries)) {
      return null;
    }
  } else if (!slots.length) {
    return null;
  }

  const activeSlotKey = hubPolicy
    ? resolveHubWorkspaceSlotCounterActiveKey(context, hubPolicy)
    : getDataStorageSlotKeyForEntryView(NODE_ENTRY_OVERVIEW_MODE);

  const strip = renderNodeNavigationWorkspaceCounterStrip(
    slots.map((slot) => ({
      ...slot,
      modeId: slot.spec?.defaultMode || slot.id
    })),
    {
      entryOverview: true,
      activeSlotKey,
      topicPath: resolvedTopicPath,
      includeTopicIndexFooter: false
    }
  );
  if (!strip) return null;
  strip.classList.add("node-entry-overview-slot-counters");
  strip.dataset.topicIndexFooter = "0";
  strip.dataset.topicNodePath = resolvedTopicPath;
  strip.setAttribute("aria-label", "Слоты данных");
  return strip;
}

function refreshEntryOverviewSlotCounterStripCounts(wrap, context, topicPath, { force = true } = {}) {
  if (!wrap || !context) return;
  wrap.querySelector(".node-navigation-workspace-counter-topic-index-row")?.remove();
  const resolvedTopicPath = topicPath || wrap.dataset.topicNodePath || getResolvedNodePath(activePath);
  void loadEntryOverviewSlotCounters(resolvedTopicPath, { force }).then((slots) => {
    if (!wrap.isConnected || !slots.length) return;
    if (wrap.querySelector(".node-navigation-workspace-counter-list")) {
      updateEntryOverviewDataSlotBarCounts(wrap, slots);
    } else {
      renderEntryOverviewDataSlotBarContent(wrap, context, slots, resolvedTopicPath);
    }
    syncAllWorkspaceCounterStripActiveStates(context);
    delete wrap.dataset.loading;
  });
}

function placeEntryOverviewHubMainSlotCounterStrip(hubMain, anchor, strip) {
  if (!hubMain || !anchor || !strip) return;
  const live = hubMain.querySelector(":scope > .node-entry-overview-hub-main-slot-counters");
  if (live && live !== strip) live.remove();
  if (strip.parentElement === hubMain && strip.nextElementSibling === anchor) return;
  if (strip.parentElement) strip.remove();
  hubMain.insertBefore(strip, anchor);
}

/** Полоса слотов hub (канал / медиатека) над iblock-карточкой — не зависит от browse-панели. */
async function mountHubWorkspaceSlotCounterStrip(hubMain, anchor, context, topicPath) {
  if (!hubMain || !anchor || !context) return null;

  const resolvedTopicPath = topicPath || getResolvedNodePath(activePath);
  const propsEntries = context?.propsEntries || null;
  const policy = resolveHubWorkspaceSlotPolicy(resolvedTopicPath, propsEntries);
  if (!policy || !shouldShowHubWorkspaceSlotStrip(resolvedTopicPath, policy.slotKeys.length, propsEntries)) {
    return null;
  }
  let existing = hubMain.querySelector(":scope > .node-entry-overview-hub-workspace-slot-counters");
  if (
    existing?.dataset.topicNodePath === resolvedTopicPath &&
    existing.querySelector(".node-navigation-workspace-counter-list")
  ) {
    if (existing.nextElementSibling !== anchor) hubMain.insertBefore(existing, anchor);
    syncAllWorkspaceCounterStripActiveStates(context);
    refreshEntryOverviewSlotCounterStripCounts(existing, context, resolvedTopicPath, { force: false });
    return existing;
  }

  if (!existing) {
    const syncStrip = renderHubWorkspaceSlotCounterStripElement(context, resolvedTopicPath, propsEntries);
    if (syncStrip) {
      hubMain.insertBefore(syncStrip, anchor);
      existing = syncStrip;
      syncAllWorkspaceCounterStripActiveStates(context);
    }
  }

  const mountSeq = (hubMain._hubWorkspaceSlotStripSeq = (hubMain._hubWorkspaceSlotStripSeq || 0) + 1);
  if (existing?.dataset.topicNodePath === resolvedTopicPath && existing.querySelector(".node-navigation-workspace-counter-list")) {
    refreshEntryOverviewSlotCounterStripCounts(existing, context, resolvedTopicPath, { force: false });
    return existing;
  }

  const strip = await createEntryOverviewSlotCounterStripElement(context, resolvedTopicPath, {
    propsEntries
  });
  if (mountSeq !== hubMain._hubWorkspaceSlotStripSeq || !hubMain.isConnected) return strip || existing;
  if (!strip) return existing;

  strip.classList.add(
    "node-entry-overview-hub-top-slot-counters",
    "node-entry-overview-hub-workspace-slot-counters"
  );
  const live = hubMain.querySelector(":scope > .node-entry-overview-hub-workspace-slot-counters");
  if (live && live !== strip) live.replaceWith(strip);
  else if (!live) hubMain.insertBefore(strip, anchor);
  syncAllWorkspaceCounterStripActiveStates(context);
  refreshEntryOverviewSlotCounterStripCounts(strip, context, resolvedTopicPath, { force: false });
  return strip;
}

async function mountEntryOverviewHubMainSlotCounterStrip(hubMain, anchor, context, topicPath) {
  if (!hubMain || !anchor || !shouldShowEntryOverviewSlotCountersOnHubMain(context)) return null;

  anchor.querySelector(".node-entry-overview-hero-slot-counters")?.remove();

  const resolvedTopicPath = topicPath || getResolvedNodePath(activePath);
  const mountSeq = (hubMain._hubMainSlotStripSeq = (hubMain._hubMainSlotStripSeq || 0) + 1);
  const existing =
    dedupeEntryOverviewSlotCounterStrips(hubMain) ||
    hubMain.querySelector(":scope > .node-entry-overview-hub-main-slot-counters");

  if (
    existing?.dataset.topicNodePath === resolvedTopicPath &&
    existing.querySelector(".node-navigation-workspace-counter-list")
  ) {
    placeEntryOverviewHubMainSlotCounterStrip(hubMain, anchor, existing);
    refreshEntryOverviewSlotCounterStripCounts(existing, context, resolvedTopicPath);
    return existing;
  }

  const manifestPath = getEntryOverviewDataSlotBarManifestPath(resolvedTopicPath);
  const cachedSlots = entryOverviewSlotCountersCache.get(manifestPath);
  let strip = cachedSlots?.length
    ? renderEntryOverviewSlotCounterStripFromSlots(context, resolvedTopicPath, cachedSlots)
    : null;

  if (strip && hubMain.isConnected) {
    strip.classList.add("node-entry-overview-hub-main-slot-counters");
    if (existing) existing.replaceWith(strip);
    else placeEntryOverviewHubMainSlotCounterStrip(hubMain, anchor, strip);
    syncAllWorkspaceCounterStripActiveStates(context);
  } else if (existing && existing.dataset.topicNodePath !== resolvedTopicPath) {
    existing.remove();
  }

  const loadedStrip = await createEntryOverviewSlotCounterStripElement(context, resolvedTopicPath);
  if (mountSeq !== hubMain._hubMainSlotStripSeq || !hubMain.isConnected) return loadedStrip;

  if (!loadedStrip) return strip;

  loadedStrip.classList.add("node-entry-overview-hub-main-slot-counters");
  const live = hubMain.querySelector(":scope > .node-entry-overview-hub-main-slot-counters");
  if (live && live !== loadedStrip) live.replaceWith(loadedStrip);
  else placeEntryOverviewHubMainSlotCounterStrip(hubMain, anchor, loadedStrip);

  syncAllWorkspaceCounterStripActiveStates(context);
  return loadedStrip;
}

async function mountEntryOverviewBrowseSlotCounterStrip(
  panel,
  context,
  topicPath,
  { isMemoryTocRoot = false } = {}
) {
  if (!panel || !context) return null;
  if (!shouldShowEntryOverviewSlotCountersInBrowsePanel(context, isMemoryTocRoot)) return null;

  const resolvedTopicPath = topicPath || getResolvedNodePath(activePath);
  if (!resolvedTopicPath) return null;

  const hubMain = panel.closest(".node-navigation-hub-main");
  const hubChannelPolicy = resolveHubWorkspaceSlotPolicy(resolvedTopicPath);
  if (hubChannelPolicy?.kind === "channel") {
    relocateEntryOverviewSlotCountersChrome(hubMain);
    syncAllWorkspaceCounterStripActiveStates(context);
    return hubMain?.querySelector(":scope > .node-entry-overview-hub-workspace-slot-counters") || null;
  }
  const mountSeq = (panel._browseSlotStripSeq = (panel._browseSlotStripSeq || 0) + 1);
  const existingInPanel = panel.querySelector(".node-entry-overview-browse-slot-counters");
  const existingGlobal = hubMain
    ? dedupeEntryOverviewSlotCounterStrips(hubMain)
    : existingInPanel;

  if (
    existingGlobal &&
    !panel.contains(existingGlobal) &&
    existingGlobal.dataset.topicNodePath === resolvedTopicPath &&
    existingGlobal.querySelector(".node-navigation-workspace-counter-list")
  ) {
    refreshEntryOverviewSlotCounterStripCounts(existingGlobal, context, resolvedTopicPath);
    finalizeEntryOverviewBrowsePanelChromeOrder(panel);
    relocateEntryOverviewSlotCountersChrome(hubMain);
    return existingGlobal;
  }

  const existing = existingInPanel;

  if (
    existing?.dataset.topicNodePath === resolvedTopicPath &&
    existing.querySelector(".node-navigation-workspace-counter-list")
  ) {
    refreshEntryOverviewSlotCounterStripCounts(existing, context, resolvedTopicPath);
    finalizeEntryOverviewBrowsePanelChromeOrder(panel);
    relocateEntryOverviewSlotCountersChrome(hubMain);
    return existing;
  }

  const insertBefore = getEntryOverviewBrowsePanelChromeInsertBefore(panel);
  const manifestPath = getEntryOverviewDataSlotBarManifestPath(resolvedTopicPath);
  const cachedSlots = entryOverviewSlotCountersCache.get(manifestPath);
  let strip = cachedSlots?.length
    ? renderEntryOverviewSlotCounterStripFromSlots(context, resolvedTopicPath, cachedSlots)
    : null;

  if (strip && panel.isConnected) {
    strip.classList.add("node-entry-overview-browse-slot-counters");
    if (existing) existing.replaceWith(strip);
    else if (insertBefore) panel.insertBefore(strip, insertBefore);
    else panel.prepend(strip);
    syncAllWorkspaceCounterStripActiveStates(context);
    finalizeEntryOverviewBrowsePanelChromeOrder(panel);
    relocateEntryOverviewSlotCountersChrome(hubMain);
  } else if (existing && existing.dataset.topicNodePath !== resolvedTopicPath) {
    existing.remove();
  }

  const loadedStrip = await createEntryOverviewSlotCounterStripElement(context, resolvedTopicPath);
  if (mountSeq !== panel._browseSlotStripSeq || !panel.isConnected) return loadedStrip;

  if (!loadedStrip) {
    finalizeEntryOverviewBrowsePanelChromeOrder(panel);
    relocateEntryOverviewSlotCountersChrome(hubMain);
    return strip;
  }

  const globalAfterLoad = hubMain ? dedupeEntryOverviewSlotCounterStrips(hubMain) : null;
  if (globalAfterLoad && !panel.contains(globalAfterLoad)) {
    refreshEntryOverviewSlotCounterStripCounts(globalAfterLoad, context, resolvedTopicPath);
    finalizeEntryOverviewBrowsePanelChromeOrder(panel);
    relocateEntryOverviewSlotCountersChrome(hubMain);
    return globalAfterLoad;
  }

  loadedStrip.classList.add("node-entry-overview-browse-slot-counters");
  const live = panel.querySelector(".node-entry-overview-browse-slot-counters");
  if (live) {
    if (live !== loadedStrip) live.replaceWith(loadedStrip);
  } else if (insertBefore) panel.insertBefore(loadedStrip, insertBefore);
  else panel.prepend(loadedStrip);

  syncAllWorkspaceCounterStripActiveStates(context);
  finalizeEntryOverviewBrowsePanelChromeOrder(panel);
  relocateEntryOverviewSlotCountersChrome(hubMain);
  return loadedStrip;
}

function prependEntryOverviewBrowseHeroNav(panel, navOptions) {
  if (!panel || !navOptions) return null;
  const nav = createEntryOverviewSiblingNav({
    ...navOptions,
    variant: "manifest",
    ariaLabel: navOptions.ariaLabel || "Навигация по записям раздела"
  });
  if (!nav) return null;
  nav.classList.add("node-entry-overview-browse-hero-nav");
  const insertBefore = getEntryOverviewBrowsePanelChromeInsertBefore(panel);
  if (insertBefore) panel.insertBefore(nav, insertBefore);
  else panel.prepend(nav);
  finalizeEntryOverviewBrowsePanelChromeOrder(panel);
  return nav;
}

function buildEntryOverviewSiblingNavOptions(context, navigationIndex) {
  if (!context || isEntryOverviewMemoryTocRoot(context)) return null;
  if (isBundleEntryOverviewMemoryKind(context.memoryKind)) return null;

  const { prev, next } = getEntryOverviewAdjacentSiblings(context, navigationIndex);
  const upNavigation = resolveEntryOverviewUpNavigation(context);
  const { onFileClick: openNavFile, onFolderClick } = getEntryOverviewNavigationHandlers(context.memoryKind);

  return {
    prevItem: prev,
    nextItem: next,
    onFileClick: (item) => {
      if (!item) return;
      if (item.isSectionCategory || item.folderPath || isSectionReadmePath(String(item.path || ""))) {
        const folder =
          String(item.folderPath || "").replace(/\\/g, "/").replace(/\/$/, "") ||
          String(item.path || "")
            .replace(/\\/g, "/")
            .replace(/\/manifest\.md$/i, "")
            .replace(/\/$/, "");
        if (folder) {
          onFolderClick(folder);
          return;
        }
      }
      openNavFile(item);
    },
    onUpClick: upNavigation
      ? () => {
          if (upNavigation.kind === "toc") {
            openEntryOverviewMemoryTocFromNavigation(context.memoryKind);
            return;
          }
          onFolderClick(upNavigation.folderPath);
        }
      : null,
    upTitle:
      upNavigation?.kind === "folder"
        ? upNavigation.folderPath.split("/").pop() || upNavigation.folderPath
        : "Оглавление",
    ariaLabel: isHubWorkspaceFilesSlotPage()
      ? isAwnChannelPageNodePath()
        ? "Навигация по содержимому канала"
        : "Навигация по содержимому медиатеки"
      : "Навигация по записям раздела"
  };
}

function findNavigationTreeFolderNode(root, folderPath) {
  const segments = String(folderPath || "")
    .replace(/\\/g, "/")
    .replace(/\/$/, "")
    .split("/")
    .filter(Boolean);
  let cursor = root;
  for (const segment of segments) {
    if (!cursor?.folders?.has(segment)) return null;
    cursor = cursor.folders.get(segment);
  }
  return cursor;
}

function buildEntryOverviewSectionTree(navigationIndex, folderPath, memoryKind = null) {
  if (!navigationIndex) return null;

  const { contentFiles, folderLabels, folderStatuses, folderPaths } = navigationIndex;
  const normalizedFolder = String(folderPath || "").replace(/\\/g, "/").replace(/\/$/, "");

  const fullTree = buildNavigationPathTree(contentFiles || [], folderLabels, memoryKind);
  ensureNavigationTreeFolders(fullTree, folderPaths, folderLabels, memoryKind);

  let tree = fullTree;
  if (normalizedFolder) {
    const folderNode = findNavigationTreeFolderNode(fullTree, normalizedFolder);
    tree = {
      label: "",
      folderPath: normalizedFolder,
      folders: folderNode?.folders || new Map(),
      files: folderNode ? [...folderNode.files] : []
    };
  }

  if (!tree.folders.size && !tree.files.length) return null;

  return {
    tree,
    folderLabels,
    folderDescriptions: navigationIndex.folderDescriptions,
    folderStatuses,
    sectionManifestByFolder: navigationIndex.sectionManifestByFolder
  };
}

function renderEntryOverviewSectionList(context, navigationIndex) {
  const folderPath = getEntryOverviewSectionFolderPath(context);
  if (folderPath === null || !navigationIndex) return null;

  const built = buildEntryOverviewSectionTree(navigationIndex, folderPath, context.memoryKind);
  if (!built) return null;

  const { tree, folderLabels, folderDescriptions, folderStatuses, sectionManifestByFolder } = built;
  if (!tree.folders.size && !tree.files.length) return null;

  const sectionTitle = isMediaLibrarySlotMemoryKind(context.memoryKind)
    ? "Содержимое раздела"
    : context.memoryKind === "media"
      ? "Содержимое раздела"
      : "Записи раздела";

  const section = document.createElement("section");
  section.className = "node-entry-overview-memory-toc node-entry-overview-section-list";

  const head = document.createElement("h3");
  head.className = "node-entry-overview-section-list-title visually-hidden";
  head.textContent = sectionTitle;
  section.appendChild(head);

  const nav = document.createElement("nav");
  nav.className = "node-navigation-book-toc node-entry-overview-memory-toc-nav";
  nav.setAttribute("aria-label", sectionTitle);

  const list = document.createElement("ul");
  list.className = "nav-book-toc-list nav-book-toc-list--root";

  const { onFolderClick, onFileClick } = getEntryOverviewNavigationHandlers(context.memoryKind);
  const listHandlers = buildEntryOverviewBookTocHandlers(context, {
    folderLabels,
    folderDescriptions,
    folderStatuses,
    sectionManifestByFolder,
    onFolderClick,
    onFileClick,
    showFileTypeLeading: true,
    showBranchLeading: false,
    treeStyle: "guide",
    collapseDepthThreshold: 99,
    linkLeadingMode: isMediaLibrarySlotMemoryKind(context.memoryKind) ? "media" : undefined,
    readManifestPath: getOverviewNodeApiPath(activePath),
    readMemoryKind: context.memoryKind
  });

  if (isMediaLibrarySlotMemoryKind(context.memoryKind)) {
    appendEntryOverviewMediaBookTocList(list, tree, 0, listHandlers);
  } else {
    appendNavigationBookTocList(list, tree, 0, listHandlers);
  }

  nav.classList.add("nav-book-toc-tree--guide");

  nav.appendChild(list);
  section.appendChild(nav);
  void prefetchNavBookTocSectionSchemaBadges(section, {
    manifestPath: getOverviewNodeApiPath(activePath),
    memoryKind: context.memoryKind,
    folderPaths: collectNavigationTreeFolderPaths(tree)
  });
  return section;
}

function createEntryOverviewThumbWrap(context, preview, title, entries) {
  if (context.entryKind === "awn.media.asset") {
    return null;
  }

  const thumbMount = createOverviewThumbWrap(preview, title, context.relPath, {
    readOnly: true,
    entryOverviewContext: context,
    propEntries: entries
  });

  const thumbWrap = getOverviewThumbWrapNode(thumbMount);
  if (thumbWrap && thumbWrap.dataset.hasPreview !== "1") {
    const emoji = getPropsEntryValueByKey(entries, "awn-emoji");
    if (emoji) {
      thumbWrap.replaceChildren();
      const emojiNode = document.createElement("span");
      emojiNode.className = "node-overview-thumb-emoji";
      emojiNode.textContent = emoji;
      thumbWrap.appendChild(emojiNode);
    }
  }

  return thumbMount;
}

