function createEntryOverviewMediaAssetShowcase(
  context,
  assetKind,
  nodePath = activePath,
  navigationIndex = null
) {
  const relativePath = String(context.relativePath || "");
  const indexed = findEntryOverviewMediaItemMeta(navigationIndex, relativePath);
  const sizeHint = indexed?.size ?? null;

  if (assetKind === "code") {
    return createEntryOverviewMediaAssetCodeShowcase(context, nodePath, sizeHint);
  }

  const cacheMeta = indexed || { path: relativePath, size: sizeHint };
  const assetUrl = appendMediaCacheBuster(buildMediaAssetUrl(relativePath, nodePath), cacheMeta);
  const showcase = document.createElement("div");
  showcase.className = `node-entry-overview-media-asset-showcase is-kind-${assetKind}`;

  if (assetKind === "video") {
    const video = document.createElement("video");
    video.className = "node-entry-overview-media-asset-video";
    video.controls = true;
    video.preload = "metadata";
    video.playsInline = true;
    video.src = assetUrl;
    showcase.appendChild(video);
    return showcase;
  }

  if (assetKind === "audio") {
    const visual = document.createElement("div");
    visual.className = "node-entry-overview-media-asset-audio-visual";
    visual.setAttribute("aria-hidden", "true");
    visual.textContent = "🎵";

    const audio = document.createElement("audio");
    audio.className = "node-entry-overview-media-asset-audio";
    audio.controls = true;
    audio.preload = "none";
    audio.src = assetUrl;

    showcase.append(visual, audio);
    return showcase;
  }

  if (assetKind === "image") {
    if (isSvgMediaAssetPath(relativePath)) {
      const object = document.createElement("object");
      object.className = "node-entry-overview-media-asset-image node-entry-overview-media-asset-svg";
      object.type = "image/svg+xml";
      object.data = assetUrl;
      object.setAttribute("aria-label", context.title || relativePath.split("/").pop() || "SVG");
      object.addEventListener("click", () => openMediaAssetExternal(relativePath));

      const fallbackImg = document.createElement("img");
      fallbackImg.className = "node-entry-overview-media-asset-image is-svg-media";
      fallbackImg.alt = context.title || relativePath.split("/").pop() || "";
      fallbackImg.decoding = "async";
      fallbackImg.src = assetUrl;
      fallbackImg.addEventListener("click", () => openMediaAssetExternal(relativePath));
      object.appendChild(fallbackImg);
      showcase.appendChild(object);
      return showcase;
    }

    const img = document.createElement("img");
    img.className = "node-entry-overview-media-asset-image";
    img.alt = context.title || relativePath.split("/").pop() || "";
    img.decoding = "async";
    img.src = assetUrl;
    markMediaAssetImageElement(img, relativePath);
    img.addEventListener("click", () => openMediaAssetExternal(relativePath));
    img.addEventListener("error", () => {
      showcase.replaceChildren();
      showcase.classList.add("is-fallback");
      const fallback = document.createElement("div");
      fallback.className = "node-entry-overview-media-asset-file-fallback";
      fillEntryOverviewMediaAssetFileFallback(fallback, relativePath, "image");
      showcase.appendChild(fallback);
    });
    showcase.appendChild(img);
    return showcase;
  }

  if (assetKind === "pdf") {
    const frame = document.createElement("iframe");
    frame.className = "node-entry-overview-media-asset-pdf";
    frame.title = context.title || "PDF документ";
    frame.loading = "lazy";
    frame.src = assetUrl;
    showcase.appendChild(frame);
    return showcase;
  }

  const fallback = document.createElement("div");
  fallback.className = "node-entry-overview-media-asset-file-fallback";
  fillEntryOverviewMediaAssetFileFallback(fallback, context.relativePath, assetKind);
  showcase.appendChild(fallback);
  return showcase;
}

