function resolveNavigationMediaGridImageUrl(
  filePath,
  nodePath = getResolvedNodePath(activePath),
  columns = navigationMediaImagesLayout === "strip" ? 3 : navigationMediaImagesLayout,
  item = null
) {
  const path = String(filePath || "").trim();
  if (!path) return "";
  const cacheMeta = item || { path };
  if (columns === 1 || isSvgMediaAssetPath(path)) {
    return appendMediaCacheBuster(buildMediaAssetUrl(path, nodePath), cacheMeta);
  }
  return appendMediaCacheBuster(buildMediaThumbUrl(path, nodePath, MEDIA_THUMB_MAX_GRID), cacheMeta);
}

function isNavigationMediaImageItem(item) {
  if (!item || item.isFolder) return false;
  return isEntryOverviewMediaImageItem(item);
}

function createNavigationMediaGridCard(item, nodePath, onActivate) {
  const card = document.createElement("article");
  card.className = "folder-browse-image-card navigation-media-image-card";
  card.dataset.mediaGridPath = item.path || "";
  card.dataset.folderBrowsePath = item.path || "";
  card.dataset.mediaGridNodePath = nodePath || "";
  card.title = item.displayName || item.name || item.path || "";

  const open = document.createElement("div");
  open.className = "folder-browse-image-open";

  const imgWrap = document.createElement("div");
  imgWrap.className = "folder-browse-image-thumb";
  const gridColumns = navigationMediaImagesLayout === "strip" ? 3 : navigationMediaImagesLayout;
  if (gridColumns === 1) {
    imgWrap.classList.add("folder-browse-image-thumb--original");
  }

  const img = document.createElement("img");
  img.alt = item.displayName || item.title || item.name || "";
  img.loading = "lazy";
  img.draggable = false;
  img.src = resolveNavigationMediaGridImageUrl(item.path, nodePath, gridColumns, item);
  markMediaAssetImageElement(img, item.path);
  attachFolderBrowseImageFallback(img);
  imgWrap.appendChild(img);
  const gdriveBadge = createGoogleDriveSyncedBadge(item, { size: "md" });
  if (gdriveBadge) imgWrap.appendChild(gdriveBadge);
  open.appendChild(imgWrap);

  const footerItem = {
    name: String(item.displayName || item.title || item.name || "").trim(),
    size: item.size
  };
  appendFolderBrowseImageFooter(open, footerItem);

  card.appendChild(open);
  card.addEventListener("click", (event) => {
    event.preventDefault();
    event.stopPropagation();
    onActivate(item);
  });
  return card;
}

function renderNavigationMediaImagesGrid(items, nodePath, onActivate) {
  const images = items.filter(isNavigationMediaImageItem);
  if (!images.length) return null;

  const columns = navigationMediaImagesLayout === "strip" ? 3 : navigationMediaImagesLayout;
  const wrap = document.createElement("div");
  wrap.className = "navigation-media-images-grid-wrap";
  const grid = document.createElement("div");
  grid.className = `folder-browse-images-grid folder-browse-images-grid--cols-${columns}`;
  grid.setAttribute("role", "list");
  grid.setAttribute("aria-label", "Изображения");
  for (const item of images) {
    grid.appendChild(createNavigationMediaGridCard(item, nodePath, onActivate));
  }
  wrap.appendChild(grid);
  return wrap;
}

function collectNavigationMediaImageItems(groups, contentFiles = []) {
  const fromGroups = Array.isArray(groups?.Images) ? groups.Images : [];
  const merged = [...fromGroups, ...(contentFiles || [])].filter(isNavigationMediaImageItem);
  const seen = new Set();
  return merged.filter((item) => {
    const path = String(item.path || "").trim();
    if (!path || seen.has(path)) return false;
    seen.add(path);
    return true;
  });
}

function createNavigationMediaImageThumb(item, nodePath) {
  const btn = document.createElement("button");
  btn.type = "button";
  btn.className = "node-navigation-media-thumb";
  btn.title = item.path || item.name || "";

  const img = document.createElement("img");
  img.alt = item.name || "";
  img.loading = "lazy";
  img.decoding = "async";
  img.src = appendMediaCacheBuster(buildMediaThumbUrl(item.path, nodePath, MEDIA_THUMB_MAX_SMALL), item);
  img.addEventListener("error", () => {
    btn.classList.add("node-navigation-media-thumb--error");
    img.remove();
    const fallback = document.createElement("span");
    fallback.className = "node-navigation-media-thumb-fallback";
    fallback.textContent = "🖼";
    btn.appendChild(fallback);
  });
  btn.appendChild(img);
  const gdriveBadge = createGoogleDriveSyncedBadge(item, { size: "md" });
  if (gdriveBadge) btn.appendChild(gdriveBadge);
  btn.addEventListener("click", (event) => {
    event.preventDefault();
    event.stopPropagation();
    openMediaEntryOverviewFromNavigation(item);
  });
  return btn;
}

function appendNavigationMediaImageStrip(parent, items, nodePath) {
  const images = items.filter((item) => !item.isFolder);
  if (!images.length) return;

  const strip = document.createElement("div");
  strip.className = "node-navigation-media-thumbs";
  strip.setAttribute("role", "list");
  strip.setAttribute("aria-label", "Превью изображений");

  const visible = images.slice(0, NAVIGATION_MEDIA_IMAGE_THUMB_LIMIT);
  for (const item of visible) {
    strip.appendChild(createNavigationMediaImageThumb(item, nodePath));
  }

  if (images.length > NAVIGATION_MEDIA_IMAGE_THUMB_LIMIT) {
    const moreBtn = document.createElement("button");
    moreBtn.type = "button";
    moreBtn.className = "node-navigation-media-thumbs-more";
    moreBtn.textContent = `+${images.length - NAVIGATION_MEDIA_IMAGE_THUMB_LIMIT}`;
    moreBtn.title = "Открыть все изображения";
    moreBtn.addEventListener("click", (event) => {
      event.stopPropagation();
      openNavigationPanelMode("media");
    });
    strip.appendChild(moreBtn);
  }

  parent.appendChild(strip);
}

