function getThreadLastSeenStorageKey(manifestPath) {
  return `${THREAD_LAST_SEEN_STORAGE_PREFIX}${activeWorkspaceId || "main"}:${manifestPath}`;
}

function getThreadLastSeenId(manifestPath) {
  try {
    return String(localStorage.getItem(getThreadLastSeenStorageKey(manifestPath)) || "").trim();
  } catch {
    return "";
  }
}

function markThreadLastSeen(manifestPath, messageId) {
  const id = String(messageId || "").trim();
  if (!id) return;
  try {
    localStorage.setItem(getThreadLastSeenStorageKey(manifestPath), id);
  } catch {
    // ignore storage errors
  }
}

function getThreadUnreadCount(manifestPath, intake) {
  const discussion = intake?.discussion || intake?.thread;
  if (!discussion?.lastMessageId) return 0;
  if (discussion.lastMessageRole !== "agent") return 0;
  const lastSeen = getThreadLastSeenId(manifestPath);
  if (!lastSeen) return 1;
  return discussion.lastMessageId !== lastSeen ? 1 : 0;
}

async function postInboxCreate(manifestPath, payload = {}, agentId = activeWorkspaceId) {
  const title = String(payload.title || "Входящее").trim() || "Входящее";
  const body = String(payload.body || "").trim() || `# ${title}\n`;
  const response = await fetch(buildApiUrl("/api/storage/file/create", {}, agentId), {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      path: manifestPath,
      folder: STORAGE_SUBFOLDER_INBOX,
      title,
      body,
      source: payload.source || "ui",
      author: payload.author || resolveDialogAuthor(),
      status: "new"
    })
  });
  if (!response.ok) {
    let details = `Request failed with ${response.status}`;
    try {
      const data = await response.json();
      if (data?.error) details = data.error;
    } catch {
      // ignore parse errors
    }
    throw new Error(details);
  }
  return response.json();
}

