async function fetchWorkspaceFolderBrowse(folderPath, agentId = activeFolderBrowseAgentId || activeWorkspaceId) {
  const response = await fetch(
    buildApiUrl("/api/workspace/folder/browse", { folderPath: normalizeCreateParentPath(folderPath) }, agentId)
  );
  if (!response.ok) throw new Error(`Request failed with ${response.status}`);
  return response.json();
}

function collectFolderBrowseListingItems(data) {
  if (!data) return [];
  return [
    ...(data.folders || []).map((item) => ({ ...item, path: item.folderPath })),
    ...(data.images || []),
    ...(data.pages || []),
    ...(data.videos || []),
    ...(data.audio || []),
    ...(data.other || [])
  ];
}

async function tryOpenUnknownPathAsAdoptFile(workspacePath) {
  const filePath = String(workspacePath || "").replace(/\\/g, "/").replace(/^\/+/, "");
  if (!filePath) return false;
  const fileName = filePath.split("/").pop() || "";
  if (!fileName || fileName.startsWith(".") || !fileName.includes(".")) return false;

  const folderPath = normalizeCreateParentPath(getFolderBrowseParentPath(filePath));
  if (!folderPath) return false;

  let data;
  try {
    data = await fetchWorkspaceFolderBrowse(folderPath);
  } catch {
    return false;
  }
  if (!data?.exists) return false;

  const listed = collectFolderBrowseListingItems(data);
  if (!listed.some((item) => item.path === filePath || item.path === fileName)) return false;

  await openFolderBrowseFile(fileName, filePath.includes("/") ? filePath : fileName, {
    folderPath,
    skipRouteSync: true
  });
  return true;
}

