function prepareNavigationHubRailSlotIndex(slotKey, nodePath, prefetched = {}, slotMeta = null) {
  const spec = DATA_STORAGE_SLOT_SPECS.find((item) => item.key === slotKey);
  const memoryKind = getEntryOverviewMemoryKindForSlot(spec);
  if (!memoryKind) return { kind: "empty", memoryKind: null, spec };
  if (isBundleEntryOverviewMemoryKind(memoryKind)) {
    return { kind: "bundle", memoryKind, spec };
  }

  const preparedFromSlot = slotMeta?.prepared;
  let navigationIndex = null;
  if (memoryKind === "external") {
    navigationIndex = prepareNavigationExternalItems(
      combineNavigationStorageFileLists(
        prefetched.externalData?.files || [],
        prefetched.externalData?.nonMarkdownFiles || []
      ),
      prefetched.externalData?.folders || []
    );
  } else if (memoryKind === "media") {
    navigationIndex = prepareNavigationMediaItems(
      prefetched.mediaData?.groups || {},
      prefetched.mediaData?.sectionManifests || []
    );
  } else if (memoryKind === "assets") {
    navigationIndex = prepareNavigationMediaItems(
      prefetched.assetsData?.groups || {},
      prefetched.assetsData?.sectionManifests || [],
      { memoryKind: "assets" }
    );
  } else if (isFlatEntryOverviewMemoryKind(memoryKind)) {
    navigationIndex =
      prefetched.flatNavigationIndexes?.[memoryKind] ||
      null;
  }

  if (
    preparedFromSlot &&
    hasNavigationExternalPreparedContent(preparedFromSlot) &&
    !hasNavigationExternalPreparedContent(navigationIndex)
  ) {
    navigationIndex = preparedFromSlot;
  }

  return { kind: "tree", memoryKind, navigationIndex, spec };
}

function patchTopicSlotCountersFromEntryOverviewNavigation(topicSlotCounters, prefetched = {}) {
  const prepared = prefetched.entryOverviewNavigationIndex;
  const memoryKind = String(prefetched.entryOverviewMemoryKind || "").trim();
  if (!prepared || !memoryKind || !hasNavigationExternalPreparedContent(prepared)) {
    return topicSlotCounters;
  }

  let slotKey = null;
  if (memoryKind === "external") slotKey = "memory";
  else if (memoryKind === "files") slotKey = "files";
  else slotKey = getDataStorageSlotForMode(memoryKind)?.key || memoryKind;
  if (!slotKey) return topicSlotCounters;

  return (topicSlotCounters || []).map((slot) => {
    if (slot.id !== slotKey) return slot;
    if (hasNavigationExternalPreparedContent(slot.prepared)) return slot;
    const filled = Boolean(slot.filled) || hasNavigationExternalPreparedContent(prepared);
    return { ...slot, prepared, filled };
  });
}

function createNavigationHubRailBookTocNav(navigationIndex, memoryKind, nodePath, slotId, activeCtx = null) {
  if (!navigationIndex) return null;

  const filteredIndex = filterEntryOverviewNavigationIndex(
    navigationIndex,
    getNavigationHubRailSlotSearchQuery(nodePath, slotId).trim().toLowerCase()
  );

  const folderLabels = filteredIndex.folderLabels || new Map();
  const folderDescriptions = filteredIndex.folderDescriptions || new Map();
  const folderStatuses = filteredIndex.folderStatuses || new Map();
  const sectionManifestByFolder = filteredIndex.sectionManifestByFolder || new Map();
  const folderPaths = filteredIndex.folderPaths || new Set();
  const mdItems = [...(filteredIndex.contentFiles || [])].sort((a, b) =>
    compareNavigationPathsNatural(a.path, b.path)
  );

  if (!mdItems.length && (!folderPaths || folderPaths.size === 0)) return null;

  const handlers = getNavigationHubRailTocHandlers(memoryKind);
  const nav = document.createElement("nav");
  nav.className = "node-navigation-book-toc nav-book-toc-tree--classic nav-book-toc-tree--rail";
  nav.setAttribute("aria-label", getEntryOverviewTocTitle(memoryKind));

  const list = document.createElement("ul");
  list.className = "nav-book-toc-list nav-book-toc-list--root";
  const tree = buildNavigationPathTree(mdItems, folderLabels, memoryKind);
  ensureNavigationTreeFolders(tree, folderPaths, folderLabels, memoryKind);

  const tocHandlers = {
    folderLabels,
    folderDescriptions,
    folderStatuses,
    sectionManifestByFolder,
    nodePath,
    treeStyle: "classic",
    collapseDepthThreshold: 99,
    activeContext: activeCtx,
    resourceContextMenuMemoryKind: memoryKind,
    readManifestPath: resolveManifestPathForNodeApi(nodePath),
    readMemoryKind: memoryKind,
    enableFolderCreateActions: true,
    enableRailDragDrop: true,
    railCreateTargetMode: memoryKind,
    railSlotKey: slotId,
    ...handlers
  };

  if (memoryKind === "media" || memoryKind === "assets") {
    appendNavigationBookTocList(list, tree, 0, {
      ...tocHandlers,
      linkLeadingMode: "media",
      showFileTypeLeading: false,
      showBranchLeading: false
    });
  } else if (isFlatEntryOverviewMemoryKind(memoryKind)) {
    appendNavigationBookTocList(list, tree, 0, {
      ...tocHandlers,
      showFileTypeLeading: true,
      showBranchLeading: false
    });
  } else {
    appendNavigationBookTocList(list, tree, 0, {
      ...tocHandlers,
      showFileTypeLeading: false,
      showBranchLeading: false
    });
  }

  nav.appendChild(list);
  refreshClassicNavBookTocTreeLines(nav);
  return nav;
}

function appendNavigationHubRailAssetsPreview(host, preview, nodePath = activePath) {
  const section = renderEntryOverviewTopicPreviewMediaSection({ memoryKind: "assets" }, preview);
  if (!section) return false;
  host.appendChild(section);
  return true;
}

function refreshNavigationHubRailSlotTreeBody(body, slot, slotIndex, nodePath, activeCtx, prefetched) {
  const treeHost = body.querySelector(".node-navigation-hub-rail-slot-tree");
  if (!treeHost) return;
  treeHost.replaceChildren();

  if (slotIndex.kind === "tree") {
    const nav = createNavigationHubRailBookTocNav(
      slotIndex.navigationIndex,
      slotIndex.memoryKind,
      nodePath,
      slot.id,
      activeCtx
    );
    if (nav) {
      treeHost.dataset.railMemoryKind = slotIndex.memoryKind || "";
      treeHost.appendChild(nav);
      mountNavigationHubRailSlotTreeDragDrop(treeHost);
    } else if (slotIndex.memoryKind === "assets") {
      appendNavigationHubRailAssetsPreview(
        treeHost,
        slot.assetsPreview || prefetched.assetsPreview,
        nodePath
      );
    }
    if (!treeHost.childElementCount) {
      appendNavigationHubRailSlotTreeEmptyState(treeHost, slot, slotIndex, nodePath);
    }
    return;
  }

  if (slotIndex.kind === "bundle") {
    const hintWrap = document.createElement("div");
    if (appendNavigationHubRailBundleHint(hintWrap, slotIndex.memoryKind, prefetched)) {
      treeHost.appendChild(hintWrap);
    } else {
      appendNavigationHubRailSlotTreeEmptyState(treeHost, slot, slotIndex, nodePath);
    }
  }
}

function mountDeferredNavigationHubRailSlotTree(body) {
  if (!body?.dataset.railTreeDeferred) return false;
  const state = navigationHubRailSlotBodyState.get(body);
  if (!state) return false;
  delete body.dataset.railTreeDeferred;
  refreshNavigationHubRailSlotTreeBody(
    body,
    state.slot,
    state.slotIndex,
    state.nodePath,
    state.activeCtx,
    state.prefetched
  );
  if (
    !state.slotIndex.navigationIndex &&
    isFlatEntryOverviewMemoryKind(state.slotIndex.memoryKind) &&
    state.slot.filled &&
    state.prefetched._flatIndexTopicPath
  ) {
    void fetchFlatStorageNavigationIndex(
      state.prefetched._flatIndexTopicPath,
      state.slotIndex.spec?.key || state.slot.id
    ).then((index) => {
      if (!index || !body.isConnected) return;
      state.slotIndex.navigationIndex = index;
      refreshNavigationHubRailSlotTreeBody(
        body,
        state.slot,
        state.slotIndex,
        state.nodePath,
        state.activeCtx,
        state.prefetched
      );
    });
  }
  if (
    !state.slotIndex.navigationIndex &&
    state.slotIndex.memoryKind === "assets" &&
    state.slot.filled
  ) {
    void fetchMediaLibraryOverview(state.nodePath, "assets").then((data) => {
      if (!body.isConnected) return;
      const index = prepareNavigationMediaItems(data?.groups || {}, data?.sectionManifests || [], {
        memoryKind: "assets"
      });
      if (!hasNavigationExternalPreparedContent(index)) return;
      state.slotIndex.navigationIndex = index;
      refreshNavigationHubRailSlotTreeBody(
        body,
        state.slot,
        state.slotIndex,
        state.nodePath,
        state.activeCtx,
        state.prefetched
      );
    });
  }
  return true;
}

function mountNavigationHubRailSlotTreeBody(
  body,
  slot,
  slotIndex,
  nodePath,
  activeCtx,
  prefetched,
  { deferTreeMount = false } = {}
) {
  body.replaceChildren();

  if (slotIndex.kind === "tree") {
    const navIndex = slotIndex.navigationIndex;
    const itemCount = resolveNavigationPreparedItemCount(navIndex);

    if (itemCount >= NAVIGATION_HUB_RAIL_SEARCH_MIN_ITEMS) {
      body.appendChild(
        createNavigationSectionSearchInput({
          value: getNavigationHubRailSlotSearchQuery(nodePath, slot.id),
          placeholder: "Поиск...",
          ariaLabel: `Поиск: ${slot.label}`,
          onInput: (value) => {
            setNavigationHubRailSlotSearchQuery(nodePath, slot.id, value);
            refreshNavigationHubRailSlotTreeBody(body, slot, slotIndex, nodePath, activeCtx, prefetched);
          }
        })
      );
    }

    const treeHost = document.createElement("div");
    treeHost.className = "node-navigation-hub-rail-slot-tree";
    body.appendChild(treeHost);

    if (deferTreeMount) {
      body.dataset.railTreeDeferred = "1";
      navigationHubRailSlotBodyState.set(body, { slot, slotIndex, nodePath, activeCtx, prefetched });
    } else {
      refreshNavigationHubRailSlotTreeBody(body, slot, slotIndex, nodePath, activeCtx, prefetched);
    }

    if (
      !deferTreeMount &&
      !slotIndex.navigationIndex &&
      isFlatEntryOverviewMemoryKind(slotIndex.memoryKind) &&
      slot.filled &&
      prefetched._flatIndexTopicPath
    ) {
      void fetchFlatStorageNavigationIndex(
        prefetched._flatIndexTopicPath,
        slotIndex.spec?.key || slot.id
      ).then((index) => {
        if (!index || !body.isConnected) return;
        slotIndex.navigationIndex = index;
        refreshNavigationHubRailSlotTreeBody(body, slot, slotIndex, nodePath, activeCtx, prefetched);
      });
    }

    if (
      !deferTreeMount &&
      !slotIndex.navigationIndex &&
      slotIndex.memoryKind === "assets" &&
      slot.filled
    ) {
      void fetchMediaLibraryOverview(nodePath, "assets").then((data) => {
        if (!body.isConnected) return;
        const index = prepareNavigationMediaItems(data?.groups || {}, data?.sectionManifests || [], {
          memoryKind: "assets"
        });
        if (!hasNavigationExternalPreparedContent(index)) return;
        slotIndex.navigationIndex = index;
        refreshNavigationHubRailSlotTreeBody(body, slot, slotIndex, nodePath, activeCtx, prefetched);
      });
    }

    const treeHasContent = deferTreeMount
      ? true
      : Boolean(treeHost.childElementCount);

    return treeHasContent || Boolean(slot.filled && isFlatEntryOverviewMemoryKind(slotIndex.memoryKind));
  }

  if (slotIndex.kind === "bundle") {
    if (isNavigationHubRailSlotEmpty(slot)) {
      body.appendChild(
        createNavigationHubRailSlotEmptyState({
          message: getNavigationHubRailSlotEmptyMessage(slot, slotIndex),
          title: getNavigationHubRailSlotEmptyMessage(slot, slotIndex)
        })
      );
    }
    return true;
  }

  return false;
}

function mountNavigationHubRailBundlePreview(body, memoryKind, prefetched = {}, nodePath = activePath) {
  if (memoryKind === "internal") {
    const content = String(prefetched.internalData?.content || "").trim();
    const meaningful = getBundleMemoryMeaningfulBody(content);
    if (!meaningful) return false;

    const wrap = document.createElement("div");
    wrap.className = "node-navigation-hub-rail-bundle-preview";

    const preview = document.createElement("div");
    preview.className =
      "node-navigation-preview file-content-preview node-navigation-hub-rail-bundle-preview-body";
    const manifestPath = nodePath || getResolvedNodePath(activePath);
    const linkBasePath = manifestPath ? resolveNodeSidecarRelPath(manifestPath, "content") : "";
    const workspacePath = prefetched.internalData?.path || linkBasePath || manifestPath;
    setMarkdownPreviewHtml(preview, meaningful, {
      linkBasePath: linkBasePath || manifestPath,
      workspacePath
    });
    enhanceMarkdownPreviewImages(preview);
    wrap.appendChild(preview);
    body.appendChild(wrap);
    return true;
  }

  if (memoryKind === "tabular") {
    const tabularData = prefetched.tabularData || {};
    const columns = tabularData.columns || [];
    const rows = tabularData.rows || [];
    if (!columns.length && !rows.length) return false;

    const wrap = document.createElement("div");
    wrap.className = "node-navigation-hub-rail-bundle-preview node-navigation-hub-rail-bundle-preview--tabular";
    const tableHost = document.createElement("div");
    tableHost.className = "node-navigation-tabular";
    appendTabularPreviewTable(tableHost, tabularData, { maxRows: 12, showMeta: false });
    wrap.appendChild(tableHost);
    body.appendChild(wrap);
    return true;
  }

  if (memoryKind === "todo") {
    const content = String(prefetched.todoData?.content || "").trim();
    if (!content) return false;

    const previewLimit = 1600;
    const previewSource =
      content.length > previewLimit ? `${content.slice(0, previewLimit).trim()}…` : content;

    const wrap = document.createElement("div");
    wrap.className = "node-navigation-hub-rail-bundle-preview";

    const preview = document.createElement("div");
    preview.className =
      "node-navigation-preview file-content-preview node-navigation-hub-rail-bundle-preview-body";
    const manifestPath = nodePath || getResolvedNodePath(activePath);
    const todoPath = resolveNodeSidecarRelPath(manifestPath, "todo");
    setMarkdownPreviewHtml(preview, previewSource, { nodePath: manifestPath, workspacePath: todoPath });
    wrap.appendChild(preview);

    if (content.length > previewLimit) {
      const note = document.createElement("p");
      note.className = "node-navigation-hub-rail-bundle-hint";
      note.textContent = `Показано ${previewLimit.toLocaleString("ru-RU")} из ${content.length.toLocaleString("ru-RU")} символов.`;
      wrap.appendChild(note);
    }

    body.appendChild(wrap);
    return true;
  }

  return false;
}

function appendNavigationHubRailBundleHint(body, memoryKind, prefetched = {}) {
  if (memoryKind === "internal") {
    const content = String(prefetched.internalData?.content || "").trim();
    if (!content) return false;
    const hint = document.createElement("p");
    hint.className = "node-navigation-hub-rail-bundle-hint";
    hint.textContent = `${content.length.toLocaleString("ru-RU")} символов`;
    body.appendChild(hint);
    return true;
  }

  if (memoryKind === "tabular") {
    const rowCount = Number(prefetched.tabularData?.rowCount) || 0;
    const columnCount = (prefetched.tabularData?.columns || []).length;
    if (!rowCount && !columnCount) return false;
    const hint = document.createElement("p");
    hint.className = "node-navigation-hub-rail-bundle-hint";
    hint.textContent = `${rowCount}×${columnCount}`;
    body.appendChild(hint);
    return true;
  }

  if (memoryKind === "todo") {
    const lines = String(prefetched.todoData?.content || "")
      .split("\n")
      .map((line) => line.trim())
      .filter(Boolean);
    if (!lines.length) return false;
    const hint = document.createElement("p");
    hint.className = "node-navigation-hub-rail-bundle-hint";
    hint.textContent = `${lines.length} пункт(ов)`;
    body.appendChild(hint);
    return true;
  }

  return false;
}

function fillNavigationHubRailDocumentOutlineList(list, headings) {
  list.replaceChildren();
  for (const heading of headings) {
    const item = document.createElement("li");
    item.className = `node-navigation-rail-doc-outline-item node-navigation-rail-doc-outline-h${heading.level}`;
    const btn = document.createElement("button");
    btn.type = "button";
    btn.className = "node-navigation-rail-link node-navigation-rail-doc-outline-link";
    btn.dataset.slug = heading.slug || "";
    btn.dataset.headingIndex = String(heading.index);
    btn.textContent = heading.text;
    btn.title = heading.text;
    btn.addEventListener("click", (event) => {
      event.preventDefault();
      event.stopPropagation();
      const rail = btn.closest(".node-navigation-hub-rail");
      const documentSlot = getNavigationHubRailDocumentSlot(rail);
      setNavigationHubRailDocumentOutlineCurrentLink(documentSlot, btn);
      scrollToEntryOverviewDocumentHeading({
        slug: btn.dataset.slug || "",
        index: Number(btn.dataset.headingIndex),
        text: btn.textContent || heading.text
      });
    });
    item.appendChild(btn);
    list.appendChild(item);
  }
}

function renderNavigationHubRailDocumentOutline(markdown, nodePath, heroTitle = "") {
  const content = prepareEntryOverviewDocumentMarkdown(markdown, heroTitle);
  const headings = parseMarkdownHeadings(content);
  const hasHeadings = headings.length > 0;

  const details = document.createElement("details");
  details.className = "node-navigation-hub-rail-slot";
  details.dataset.railSlotId = NAV_HUB_RAIL_DOCUMENT_SLOT_ID;
  details.classList.toggle("is-filled", hasHeadings);
  details.classList.toggle("is-empty", !hasHeadings);
  const defaultDocumentOpen = hasHeadings && activeContentMode === NODE_ENTRY_OVERVIEW_MODE;
  details.open = isNavHubRailSlotOpen(nodePath, NAV_HUB_RAIL_DOCUMENT_SLOT_ID, defaultDocumentOpen);
  details.addEventListener("toggle", () => {
    setNavHubRailSlotOpen(nodePath, NAV_HUB_RAIL_DOCUMENT_SLOT_ID, details.open);
    syncNavigationHubRailSlotToggleButton(toggleBtn, documentSlotMeta, details.open);
    syncNavigationHubRailDocumentSlotState(details);
  });

  const documentSlotMeta = {
    label: "Оглавление",
    count: headings.length,
    filled: hasHeadings,
    spec: { iconSvg: NAVIGATION_HUB_RAIL_TOC_ICON_SVG }
  };

  let toggleBtn = null;
  const summary = document.createElement("summary");
  summary.className = "node-navigation-hub-rail-slot-summary";
  if (!hasHeadings) {
    summary.title = "В документе нет заголовков для навигации. Перетащите в чат Agent CMS Voice или редактор для ссылки";
  }

  ({ toggleBtn } = appendNavigationHubRailSlotSummaryParts(summary, documentSlotMeta, {
    toggleExpanded: details.open,
    onToggleClick: () => {
      details.open = !details.open;
    }
  }));

  if (!hasHeadings) {
    const countEl = summary.querySelector(".node-navigation-hub-rail-slot-count");
    if (countEl) countEl.textContent = "—";
  }

  summary.addEventListener("click", (event) => {
    event.preventDefault();
  });
  syncNavigationHubRailSlotToggleButton(toggleBtn, documentSlotMeta, details.open);
  details.appendChild(summary);

  const bodyNode = document.createElement("div");
  bodyNode.className = "node-navigation-hub-rail-slot-body";

  if (hasHeadings) {
    const nav = document.createElement("nav");
    nav.className = "node-navigation-hub-rail-document-outline";
    nav.setAttribute("aria-label", "Навигация по документу");

    const list = document.createElement("ul");
    list.className = "node-navigation-rail-doc-outline-list";
    fillNavigationHubRailDocumentOutlineList(list, headings);
    nav.appendChild(list);
    bodyNode.appendChild(nav);
  } else {
    bodyNode.appendChild(
      createNavigationHubRailSlotEmptyState({
        message: "Нет заголовков для навигации",
        title: "В документе нет заголовков для навигации"
      })
    );
  }

  details.appendChild(bodyNode);
  return details;
}

function renderNavigationHubRailSlotSection(slot, slotIndex, prefetched, nodePath, activeCtx = null) {
  if (!isNavigationHubRailSlotExpandable(slot, slotIndex)) {
    return renderNavigationHubRailFlatSlot(slot, slotIndex, activeCtx);
  }

  const defaultOpen = shouldNavigationHubRailSlotDefaultOpen(slot, slotIndex, activeCtx);
  const details = document.createElement("details");
  details.className = "node-navigation-hub-rail-slot";
  if (slotIndex.memoryKind) details.dataset.railSlotMemoryKind = slotIndex.memoryKind;
  details.dataset.railSlotId = slot.id;
  if (isNavigationHubRailSlotSelected(slot, slotIndex, activeCtx)) {
    details.classList.add("is-active-slot");
  }
  details.open = isNavHubRailSlotOpen(nodePath, slot.id, defaultOpen);
  let toggleBtn = null;
  details.addEventListener("toggle", () => {
    setNavHubRailSlotOpen(nodePath, slot.id, details.open);
    syncNavigationHubRailSlotToggleButton(toggleBtn, slot, details.open);
    if (details.open) {
      const bodyNode = details.querySelector(".node-navigation-hub-rail-slot-body");
      if (bodyNode) mountDeferredNavigationHubRailSlotTree(bodyNode);
    }
    bindNavigationHubRailScrollDownButton(details.closest(".node-navigation-hub-rail"));
  });
  details.classList.toggle("is-empty", isNavigationHubRailSlotEmpty(slot));
  details.classList.toggle("is-filled", Boolean(slot.filled));
  if (slotIndex.kind === "bundle") details.classList.add("node-navigation-hub-rail-slot--bundle");
  if (slot.tone) details.classList.add(`is-${slot.tone}`);

  const summary = document.createElement("summary");
  summary.className = "node-navigation-hub-rail-slot-summary";
  ({ toggleBtn } = appendNavigationHubRailSlotSummaryParts(summary, slot, {
    toggleExpanded: details.open,
    onLabelClick: () => openNavigationHubRailSlotTarget(slot),
    onToggleClick: () => {
      details.open = !details.open;
    }
  }));
  summary.addEventListener("click", (event) => {
    event.preventDefault();
  });
  syncNavigationHubRailSlotToggleButton(toggleBtn, slot, details.open);
  details.appendChild(summary);

  const body = document.createElement("div");
  body.className = "node-navigation-hub-rail-slot-body";

  const slotActions = createNavigationHubRailSlotActions(slot, slotIndex, activeCtx);
  if (slotActions) body.appendChild(slotActions);

  const hasContent = mountNavigationHubRailSlotTreeBody(
    body,
    slot,
    slotIndex,
    nodePath,
    activeCtx,
    prefetched,
    { deferTreeMount: !details.open }
  );

  if (!hasContent && !slotActions) {
    body.appendChild(
      createNavigationHubRailSlotEmptyState({
        message: getNavigationHubRailSlotEmptyMessage(slot, slotIndex),
        title: getNavigationHubRailSlotEmptyMessage(slot, slotIndex)
      })
    );
  }

  details.appendChild(body);
  if (details.open) {
    mountDeferredNavigationHubRailSlotTree(body);
  }
  return details;
}

function renderNavigationHubRail(topicSlotCounters, childEntries, nodePath, prefetched = {}, options = {}) {
  const rail = document.createElement("aside");
  rail.className = "node-navigation-hub-rail";
  rail.setAttribute("aria-label", "Слоты и подразделы");

  const activeCtx = buildNavigationHubRailActiveContext();

  const subsections = renderNavigationHubRailSubsections(childEntries, activeCtx);
  if (subsections) rail.appendChild(subsections);

  const documentOutline = renderNavigationHubRailDocumentOutline(
    options.documentMarkdown ?? "",
    nodePath,
    options.documentHeroTitle ?? ""
  );

  const slotsWrap = document.createElement("div");
  slotsWrap.className = "node-navigation-hub-rail-slots";
  if (options.sharedSlotMode) {
    slotsWrap.classList.add("node-navigation-hub-rail-slots--flexible");
  }

  if (documentOutline) slotsWrap.appendChild(documentOutline);

  if (options.sharedSlotMode) {
    const flexSlot = renderNavigationHubRailFlexibleSlotSection(nodePath, prefetched, activeCtx);
    if (flexSlot) slotsWrap.appendChild(flexSlot);
  } else if (topicSlotCounters.length) {
    for (const slot of topicSlotCounters) {
      const slotIndex = prepareNavigationHubRailSlotIndex(
        slot.id,
        nodePath,
        {
          ...prefetched,
          assetsPreview: slot.assetsPreview || prefetched.assetsPreview || null
        },
        slot
      );
      slotsWrap.appendChild(
        renderNavigationHubRailSlotSection(
          slot,
          slotIndex,
          {
            ...prefetched,
            assetsPreview: slot.assetsPreview || prefetched.assetsPreview || null
          },
          nodePath,
          activeCtx
        )
      );
    }
  }

  if (slotsWrap.childElementCount) rail.appendChild(slotsWrap);

  return rail.childElementCount ? rail : null;
}

function buildNodeNavigationMemoryPanelsWrap({
  isInlineNavHub = false,
  slotsDisabled = false,
  nodePath,
  externalData,
  internalData,
  tabularData,
  mediaData,
  assetsData,
  todoData
}) {
  const panelsWrap = document.createElement("div");
  panelsWrap.className = "node-navigation-panels";

  if (!isInlineNavHub) {
    const panels = [
      renderNavigationExternalPart(externalData, { slotsDisabled }),
      renderNavigationInternalPart(internalData, { nodePath }),
      renderNavigationTabularPart(tabularData),
      slotsDisabled ? null : renderNavigationMediaPart(mediaData),
      slotsDisabled || !NODE_NAVIGATION_ASSETS_PANEL_ENABLED
        ? null
        : renderNavigationAssetsPart(assetsData)
    ].filter(Boolean);
    for (const panel of panels) {
      panelsWrap.appendChild(panel);
    }
  }

  const todoPanel = renderNavigationTodoPart(todoData);
  if (todoPanel) panelsWrap.appendChild(todoPanel);

  return panelsWrap.childElementCount ? panelsWrap : null;
}

async function fetchNodeNavigationMemoryBundle(nodePath) {
  const isInlineNavHub = usesNavigationHubInlineSubsections(nodePath);
  const slotsDisabled = await readTopicSlotsDisabledForPath(nodePath);
  const emptyExternal = { exists: false, files: [], folders: [], nonMarkdownFiles: [], slotsDisabled: false };
  const emptyTabular = { exists: false, columns: [], rows: [], rowCount: 0, path: null };

  const [internalData, externalData, tabularData, todoData, mediaData, assetsData] = await Promise.all(
    isInlineNavHub
      ? [
          fetchInternalMemoryForNavigation(nodePath),
          Promise.resolve(emptyExternal),
          Promise.resolve(emptyTabular),
          fetchTodoForOverview(nodePath),
          Promise.resolve(null),
          Promise.resolve(null)
        ]
      : [
          fetchInternalMemoryForNavigation(nodePath),
          fetchExternalFilesForNavigation(nodePath),
          fetchTabularMemoryForNavigation(nodePath),
          fetchTodoForOverview(nodePath),
          slotsDisabled ? Promise.resolve(null) : fetchMediaLibraryOverview(nodePath, "media").catch(() => null),
          slotsDisabled ? Promise.resolve(null) : fetchMediaLibraryOverview(nodePath, "assets").catch(() => null)
        ]
  );
  return { isArea: isInlineNavHub, slotsDisabled, internalData, externalData, tabularData, mediaData, assetsData, todoData };
}

async function appendNodeNavigationSplitRail(
  hub,
  nodePath,
  prefetched,
  { isStale = () => false, documentMarkdown = null } = {}
) {
  if (usesNavigationHubInlineSubsections(nodePath)) return false;
  if (await shouldHideTopicStorageSlots(nodePath)) {
    const childEntries = getNavigationSubsectionEntries();
    const flatNavigationIndexes =
      prefetched.flatNavigationIndexes ?? (await fetchNavigationHubRailFlatIndexes(nodePath));
    if (isStale()) return false;
    const rail = renderNavigationHubRail([], childEntries, nodePath, {
      ...prefetched,
      flatNavigationIndexes,
      _flatIndexTopicPath: nodePath
    }, { documentMarkdown, sharedSlotMode: true });
    if (isStale()) return false;
    if (rail) {
      hub.appendChild(rail);
      return true;
    }
    hub.classList.remove("node-navigation-hub--split");
    syncNodeOverviewNavigationSplitClass(false);
    return false;
  }

  const childEntries = getNavigationSubsectionEntries();
  let topicSlotCounters =
    prefetched.topicSlotCounters ?? (await buildEntryOverviewDataSlotCounters(nodePath, prefetched));
  topicSlotCounters = patchTopicSlotCountersFromEntryOverviewNavigation(topicSlotCounters, prefetched);
  if (isStale()) return false;

  try {
    const assetsData =
      prefetched.assetsData ??
      (await fetchMediaLibraryOverview(nodePath, "assets").catch(() => null));
    if (isStale()) return false;

    const flatNavigationIndexes =
      prefetched.flatNavigationIndexes ?? (await fetchNavigationHubRailFlatIndexes(nodePath));
    if (isStale()) return false;

    const assetsSlotPreview = topicSlotCounters.find((slot) => slot.id === "assets")?.assetsPreview || null;

    const rail = renderNavigationHubRail(
      topicSlotCounters.map((slot) => ({
        ...slot,
        modeId: slot.spec?.defaultMode || slot.id
      })),
      childEntries,
      nodePath,
      {
        ...prefetched,
        assetsData,
        assetsPreview: assetsSlotPreview || prefetched.assetsPreview || null,
        flatNavigationIndexes,
        _flatIndexTopicPath: nodePath
      },
      { documentMarkdown }
    );
    if (isStale()) return false;
    if (rail) {
      hub.appendChild(rail);
      return true;
    }
  } catch (railError) {
    console.warn("appendNodeNavigationSplitRail failed", railError);
  }

  hub.classList.remove("node-navigation-hub--split");
  syncNodeOverviewNavigationSplitClass(false);
  return false;
}

async function renderNodeNavigation() {
  if (!nodeOverviewContentNode || !activePath) return;

  if (isRepositoryPageNodePath()) {
    await renderRepositoryNavigationPage();
    return;
  }

  syncEntryOverviewKindClass(null);
  syncEntryOverviewMediaAssetKindClass(null);

  const renderSeq = ++nodeOverviewRenderSeq;
  const isStale = () =>
    renderSeq !== nodeOverviewRenderSeq ||
    activeContentMode !== NODE_NAVIGATION_MODE ||
    !nodeOverviewContentNode;

  if (isStale()) return;

  try {
  navPerfMark("renderNodeNavigation:start");
  const nodePath = getResolvedNodePath(activePath);
  const manifestApiPath = resolveManifestPathForNodeApi(nodePath);

  await Promise.all([
    activePath && !propsFormEntries.length && !String(propsInputNode.value || "").trim()
      ? loadPropertiesForActivePath()
      : Promise.resolve(),
    ensureTopicSchemaForActiveContext().catch(() => null),
    ensureNavigationManifestCached(),
    manifestApiPath ? fetchNodeReadState(manifestApiPath) : Promise.resolve()
  ]);
  navPerfMark("renderNodeNavigation:prep");
  if (isStale()) return;

  const childEntries = getNavigationSubsectionEntries();
  const isInlineNavHub = usesNavigationHubInlineSubsections(nodePath);
  const entries = resolveNodeOverviewPropsEntries();
  let slotsDisabled = isTopicSlotsDisabledFromEntries(entries);
  if (!slotsDisabled && !entries?.length) {
    slotsDisabled = await readTopicSlotsDisabledForPath(nodePath);
  }
  const heroTitle = getOverviewTitleFromProps(entries);
  const showHeroUnread = isNodePageUnread(manifestApiPath);

  const emptyExternal = { exists: false, files: [], folders: [], nonMarkdownFiles: [], slotsDisabled: false };
  const emptyTabular = { exists: false, columns: [], rows: [], rowCount: 0, path: null };

  const navigationPrefetch = {};
  const [
    internalData,
    externalData,
    tabularData,
    todoData,
    preview,
    nodeMeta,
    mediaData,
    assetsData,
    nodeConfigPayload,
    outsideSlotsReport
  ] = await Promise.all(
    isInlineNavHub
      ? [
          fetchInternalMemoryForNavigation(nodePath),
          Promise.resolve(emptyExternal),
          Promise.resolve(emptyTabular),
          fetchTodoForOverview(nodePath),
          fetchNodeOverviewPreview(nodePath, entries),
          fetchNodeNavigationMeta(nodePath),
          Promise.resolve(null),
          Promise.resolve(null),
          loadNodeConfig(nodePath).catch(() => null),
          manifestApiPath && !isWorkspaceRootNodePath(nodePath)
            ? fetchPageOutsideSlotsReport(manifestApiPath).catch(() => null)
            : Promise.resolve(null)
        ]
      : [
          fetchInternalMemoryForNavigation(nodePath),
          fetchExternalFilesForNavigation(nodePath),
          fetchTabularMemoryForNavigation(nodePath),
          fetchTodoForOverview(nodePath),
          fetchNodeOverviewPreview(nodePath, entries),
          fetchNodeNavigationMeta(nodePath),
          slotsDisabled ? Promise.resolve(null) : fetchMediaOverview(nodePath),
          slotsDisabled
            ? Promise.resolve(null)
            : fetchMediaLibraryOverview(nodePath, "assets").catch(() => null),
          loadNodeConfig(nodePath).catch(() => null),
          manifestApiPath && !isWorkspaceRootNodePath(nodePath)
            ? fetchPageOutsideSlotsReport(manifestApiPath).catch(() => null)
            : Promise.resolve(null)
        ]
  );
  navPerfMark("renderNodeNavigation:prefetch");
  const configSettingsEntries = nodeConfigPayload?.content
    ? parseNodeConfigContent(nodeConfigPayload.content).entries
    : [];
  Object.assign(navigationPrefetch, {
    internalData,
    externalData,
    tabularData,
    todoData,
    mediaData,
    assetsData,
    outsideSlotsReport: outsideSlotsReport || null
  });
  if (isStale()) return;

  const slotStripGroups = buildNodeSlotStripGroups({
    nodePath,
    isArea: isInlineNavHub,
    slotsDisabled,
    descriptionRaw: modeContentCache.description || "",
    internalData,
    externalData,
    tabularData,
    mediaData,
    todoData
  });

  const hubFilesSlotWorkspace = isHubWorkspaceFilesSlotPage(nodePath, entries);
  const hubSlotPolicy = resolveHubWorkspaceSlotPolicy(nodePath, entries);
  navigationPrefetch.propsEntries = entries;
  navigationPrefetch.hubSlotPolicy = hubSlotPolicy;

  const hub = document.createElement("div");
  const useSplitLayout = shouldUseNavigationSplitRailLayout(nodePath);
  hub.className = useSplitLayout
    ? "node-navigation-hub node-navigation-hub--split"
    : "node-navigation-hub";
  if (hubFilesSlotWorkspace) {
    hub.classList.add("is-media-library-workspace-hub");
    if (hubSlotPolicy?.kind === "channel") hub.classList.add("is-awn-channel-workspace-hub");
  }

  const hubMain = document.createElement("div");
  hubMain.className = "node-navigation-hub-main";

  const topicSiblingNav = buildTopicSiblingNavOptions(nodePath);
  const topicTypeLabel = getPropsEntryValueByKey(entries, "awn-type") || "";

  if (hubFilesSlotWorkspace) {
    const preservedNavHubStrip =
      hubSlotPolicy?.kind === "channel" ? detachPreservedHubWorkspaceSlotCounterStrip(nodePath) : null;
    const hubPolicy = hubSlotPolicy;
    const hubCtx = buildHubChannelWorkspaceBrowseContext(nodePath, entries);
    hubCtx.title = heroTitle;
    const slotAnchor = document.createElement("div");
    slotAnchor.className = "node-navigation-hub-workspace-slot-anchor";
    hubMain.appendChild(slotAnchor);

    const isAwnChannelWorkspace =
      hubPolicy?.kind === "channel" ||
      isAwnChannelHubWorkspacePath(nodePath) ||
      isAwnChannelPageNodePath(nodePath, entries);
    const isMediaLibraryWorkspace =
      hubPolicy?.kind === "media" ||
      isMediaLibraryHubWorkspacePath(nodePath) ||
      isMediaLibraryPageNodePath(nodePath, entries);
    const manifestPath =
      isMediaLibraryManifestPath(nodePath) || isAwnChannelManifestPath(nodePath)
        ? nodePath
        : isAwnChannelWorkspace
          ? getAwnChannelManifestPathFromFolder(nodePath)
          : getMediaLibraryManifestPathFromFolder(nodePath);
    const { body: manifestBody } = splitFrontmatter(modeContentCache.description || "");
    const hubWorkspaceKind = isAwnChannelWorkspace ? "channel" : "media";
    const iblockLayout = createMediaLibraryWorkspaceIblockLayout({
      title: heroTitle,
      manifestPath,
      typeLabel: topicTypeLabel || (hubWorkspaceKind === "channel" ? HUB_CHANNEL_TYPE_ID : HUB_MEDIA_TYPE_ID),
      manifestEntries: entries,
      manifestBodyMarkdown: manifestBody,
      onEditClick: openDescriptionFromOverview,
      onIdAssigned: refreshUiAfterWorkspaceRecordIdAssign,
      hubWorkspaceKind
    });
    if (iblockLayout) {
      const showNavHubStrip =
        hubPolicy && shouldShowHubWorkspaceSlotStrip(nodePath, hubPolicy.slotKeys.length, entries);
      if (showNavHubStrip) {
        if (preservedNavHubStrip) {
          hubMain.appendChild(preservedNavHubStrip);
        } else {
          const syncStrip = renderHubWorkspaceSlotCounterStripElement(hubCtx, nodePath, entries);
          if (syncStrip) hubMain.appendChild(syncStrip);
        }
      }
      hubMain.appendChild(iblockLayout);
      void mountHubWorkspaceStoreSchema(iblockLayout, manifestPath);
      if (showNavHubStrip) {
        void mountHubWorkspaceSlotCounterStrip(hubMain, iblockLayout, hubCtx, nodePath).then(() => {
          slotAnchor.remove();
        });
      } else {
        slotAnchor.remove();
      }
      if (hubPolicy?.kind === "channel") {
        await appendHubChannelWorkspaceBrowsePanel(hubMain, nodePath, entries);
        if (isStale()) return;
      } else if (hubPolicy?.kind === "media") {
        await appendHubMediaWorkspaceBrowsePanel(hubMain, nodePath, entries);
        if (isStale()) return;
      }
    } else {
      slotAnchor.remove();
    }
  } else {
    const hero = createNavigationHero(preview, heroTitle, nodePath, {
      meta: nodeMeta,
      propEntries: entries,
      configSettingsEntries,
      descriptionRaw: modeContentCache.description || "",
      typeLabel: topicTypeLabel,
      showHeroInstruction: true,
      onEditClick: openDescriptionFromOverview,
      settingsSlots: isRepositoryManifestPath(nodePath) ? [] : slotStripGroups.settings || [],
      hideSharedSlot: isRepositoryManifestPath(nodePath),
      showWorkspaceMarkers: !isRepositoryManifestPath(nodePath),
      slugIssue: getNodeManifestSlugIssue(nodePath),
      recordPath: getOverviewNodeApiPath(nodePath),
      pageManifestPath: getOverviewNodeApiPath(nodePath),
      onIdAssigned: refreshUiAfterWorkspaceRecordIdAssign,
      showUnread: showHeroUnread,
      entryOverviewNav: topicSiblingNav,
    });
    hubMain.appendChild(hero);
  }

  await appendNodeOverviewTypeRegistryFold(hubMain, nodePath);
  if (isStale()) return;

  let topicSlotCounters = isInlineNavHub
    ? []
    : await buildEntryOverviewDataSlotCounters(nodePath, {
        ...navigationPrefetch,
        propsEntries: entries
      });
  topicSlotCounters = filterHubWorkspaceSlotCounters(nodePath, topicSlotCounters, entries);
  if (isInlineNavHub) {
    navigationPrefetch.topicSlotCounters = [];
  } else {
    navigationPrefetch.topicSlotCounters = topicSlotCounters;
  }
  if (isStale()) return;

  if (!isInlineNavHub && !hubFilesSlotWorkspace) {
    await appendTopicSlotCounterStrip(hubMain, nodePath, { isStale, slots: topicSlotCounters, propsEntries: entries });
    if (isStale()) return;
  }

  const panelsWrap = buildNodeNavigationMemoryPanelsWrap({
    isInlineNavHub,
    slotsDisabled,
    nodePath,
    externalData,
    internalData,
    tabularData,
    mediaData,
    assetsData,
    todoData
  });

  if (isInlineNavHub) {
    const subsectionsBlock = renderNavigationSubsectionsBlock(childEntries);
    if (subsectionsBlock) hubMain.appendChild(subsectionsBlock);
  } else {
    const elementsNavAccordion = renderNodeNavigationElementsNavAccordion({
      childEntries,
      nodePath,
      heroTitle,
      slots: topicSlotCounters,
      externalData,
      mediaData
    });
    if (slotsDisabled) {
      const topicNavCluster = document.createElement("div");
      topicNavCluster.className = "node-navigation-hub-topic-nav-cluster";
      if (!topicSlotCounters.length) {
        appendTopicLiteIndexControlsRow(topicNavCluster, nodePath);
      }
      if (elementsNavAccordion) topicNavCluster.appendChild(elementsNavAccordion);
      else if (!useSplitLayout) {
        const subsectionsBlock = renderNavigationSubsectionsBlock(childEntries);
        if (subsectionsBlock) topicNavCluster.appendChild(subsectionsBlock);
      }
      if (topicNavCluster.childElementCount) hubMain.appendChild(topicNavCluster);
    } else if (!hubFilesSlotWorkspace && elementsNavAccordion) {
      hubMain.appendChild(elementsNavAccordion);
    } else if (!useSplitLayout && !hubFilesSlotWorkspace) {
      const subsectionsBlock = renderNavigationSubsectionsBlock(childEntries);
      if (subsectionsBlock) hubMain.appendChild(subsectionsBlock);
    }
  }

  if (isInlineNavHub) {
    const internalPanel = renderNavigationInternalPart(internalData, { areaMode: true, nodePath });
    if (internalPanel) hubMain.appendChild(internalPanel);
  }

  if (panelsWrap && !hubFilesSlotWorkspace) {
    hubMain.appendChild(panelsWrap);
  }

  appendTopicSiblingNavBottom(hubMain, topicSiblingNav);
  hub.appendChild(hubMain);

  if (useSplitLayout) {
    const railMounted = await appendNodeNavigationSplitRail(
      hub,
      nodePath,
      navigationPrefetch,
      { isStale, documentMarkdown: modeContentCache.description || "" }
    );
    if (isStale()) return;
    if (!railMounted) {
      hub.className = "node-navigation-hub";
      const subsectionsBlock = renderNavigationSubsectionsBlock(childEntries);
      if (subsectionsBlock && panelsWrap) hubMain.insertBefore(subsectionsBlock, panelsWrap);
      else if (subsectionsBlock) hubMain.appendChild(subsectionsBlock);
    }
  } else {
    syncNodeOverviewNavigationSplitClass(false);
  }

  if (getActiveNodeApiPath()) {
    await appendNodeCommentsBlockToContainer(hubMain, {
      manifestPath: getActiveNodeApiPath(),
      nodeTitle: heroTitle,
      mode: "description"
    });
    if (isStale()) return;
  }

  if (isStale()) return;
  if (!hub.children.length) {
    const empty = document.createElement("p");
    empty.className = "node-navigation-empty";
    empty.textContent = "Нет данных для отображения";
    hub.appendChild(empty);
  }
  nodeOverviewContentNode.replaceChildren(hub);
  finalizeNavigationHubSplitUi(hub);
  mountPageOutsideSlotsWarningBlock(
    hubMain,
    nodePath,
    navigationPrefetch.outsideSlotsReport
  );
  navPerfMark("renderNodeNavigation:dom");
  hideContentLoading({ force: true });
  scheduleWorkspaceScrollChromeSync();
  syncDataHubSlugWarning(NODE_NAVIGATION_MODE);
  } catch (error) {
    console.error("renderNodeNavigation failed", error);
    nodeOverviewContentNode.replaceChildren();
    const errorNode = document.createElement("p");
    errorNode.className = "node-navigation-empty";
    errorNode.textContent = `Ошибка загрузки навигации: ${error.message || error}`;
    nodeOverviewContentNode.appendChild(errorNode);
    hideContentLoading({ force: true });
    scheduleWorkspaceScrollChromeSync();
  }
}

// Creates a single editable field widget for the type-fields form in the node overview.
// Updates propsFormEntries on change so the standard saveProperties() pipeline handles saving.
function createTypeFieldControl(key, fieldDef, entry) {
  const widget = resolvePropsFieldWidget(key, fieldDef);
  const value = entry?.value;

  let el;
  if (widget === "textarea") {
    el = document.createElement("textarea");
    el.className = "type-field-ctrl type-field-ctrl--textarea";
    el.rows = 3;
    el.placeholder = fieldDef?.hint || fieldDef?.description || "";
    el.value = String(value ?? "");
  } else if (widget === "boolean") {
    const label = document.createElement("label");
    label.className = "type-field-ctrl type-field-ctrl--boolean";
    const input = document.createElement("input");
    input.type = "checkbox";
    input.checked = entry?.kind === "bool" ? Boolean(value) : String(value).trim() === "true";
    const caption = document.createElement("span");
    caption.textContent = input.checked ? "Да" : "Нет";
    input.addEventListener("change", () => { caption.textContent = input.checked ? "Да" : "Нет"; });
    label.append(input, caption);
    return label;
  } else if (widget === "select") {
    el = document.createElement("select");
    el.className = "type-field-ctrl type-field-ctrl--select";
    const opts = getEnumOptionsForField(fieldDef);
    const emptyOpt = document.createElement("option");
    emptyOpt.value = "";
    emptyOpt.textContent = "—";
    el.appendChild(emptyOpt);
    for (const opt of opts) {
      const o = document.createElement("option");
      o.value = typeof opt === "object" ? (opt.key ?? opt.value ?? "") : String(opt);
      o.textContent = typeof opt === "object" ? (opt.name ?? opt.label ?? o.value) : String(opt);
      o.selected = o.value === String(value ?? "");
      el.appendChild(o);
    }
  } else if (widget === "color") {
    el = document.createElement("input");
    el.type = "color";
    el.className = "type-field-ctrl type-field-ctrl--color";
    el.value = String(value || "#000000");
  } else if (widget === "date") {
    el = document.createElement("input");
    el.type = "date";
    el.className = "type-field-ctrl";
    el.value = String(value ?? "").slice(0, 10);
  } else if (widget === "datetime") {
    el = document.createElement("input");
    el.type = "datetime-local";
    el.className = "type-field-ctrl";
    el.value = String(value ?? "").slice(0, 16);
  } else if (widget === "number") {
    el = document.createElement("input");
    el.type = "number";
    el.className = "type-field-ctrl";
    el.value = String(value ?? "");
  } else if (widget === "url") {
    el = document.createElement("input");
    el.type = "url";
    el.className = "type-field-ctrl";
    el.placeholder = "https://";
    el.value = String(value ?? "");
  } else {
    el = document.createElement("input");
    el.type = "text";
    el.className = "type-field-ctrl";
    el.placeholder = fieldDef?.hint || fieldDef?.description || "";
    el.value = String(value ?? "");
  }
  return el;
}

// Reads value from a type-field control element.
function readTypeFieldControlValue(el, widget) {
  if (widget === "boolean" || el.tagName === "LABEL") {
    const input = el.tagName === "LABEL" ? el.querySelector("input[type=checkbox]") : el;
    return input?.checked ?? false;
  }
  if (el.type === "checkbox") return el.checked;
  return el.value ?? "";
}

// Renders an accordion section in the node overview for editing type-specific custom fields.
// Only shows fields that are defined in the leaf type (not inherited from parent types).
function renderNodeTypeFieldsSection(typeId, currentEntries) {
  if (!typeId || !awnTypesCache?.types) return null;

  const ownFields = getTypeOwnFields(typeId);
  if (!Object.keys(ownFields).length) return null;

  const form = document.createElement("div");
  form.className = "node-type-fields-form";

  const fieldEls = [];

  for (const [key, fieldDef] of Object.entries(ownFields)) {
    const normalizedKey = normalizePropsKey(key);
    if (!normalizedKey) continue;

    const fieldLabel = getFieldDefDisplayName(fieldDef, normalizedKey) || normalizedKey;
    const meta = getPropsFieldMetaFromSchema(normalizedKey) || {
      label: fieldLabel,
      hint: fieldDef?.description || fieldDef?.hint || "",
      required: Boolean(fieldDef?.required),
      locked: Boolean(fieldDef?.locked),
      fieldDef
    };
    const existingEntry = currentEntries.find((e) => normalizePropsKey(e.key) === normalizedKey);
    const entry = existingEntry || {
      key: normalizedKey,
      kind: fieldDefToEntryKind(fieldDef),
      value: fieldDefDefaultValue(fieldDef)
    };

    const widget = resolvePropsFieldWidget(normalizedKey, fieldDef);
    const fieldEl = createTypeFieldControl(normalizedKey, fieldDef, entry);

    const row = document.createElement("div");
    row.className = "node-type-field-row";
    row.dataset.fieldKey = normalizedKey;

    const labelEl = document.createElement("label");
    labelEl.className = "node-type-field-label";
    labelEl.textContent = meta.label || normalizedKey;
    if (meta.hint) labelEl.title = meta.hint;
    if (meta.required) {
      const req = document.createElement("span");
      req.className = "node-type-field-required";
      req.textContent = " *";
      labelEl.appendChild(req);
    }

    row.append(labelEl, fieldEl);
    form.appendChild(row);
    fieldEls.push({ key: normalizedKey, el: fieldEl, widget, entry });
  }

  if (!fieldEls.length) return null;

  // Save button — syncs values back to propsFormEntries then calls saveProperties()
  const footer = document.createElement("div");
  footer.className = "node-type-fields-footer";

  const saveBtn = document.createElement("button");
  saveBtn.type = "button";
  saveBtn.className = "node-type-fields-save-btn";
  saveBtn.textContent = "Сохранить";

  saveBtn.addEventListener("click", async () => {
    saveBtn.disabled = true;
    try {
      // Write updated values back to propsFormEntries
      for (const { key, el, widget } of fieldEls) {
        const rawValue = readTypeFieldControlValue(el, widget);
        const idx = propsFormEntries.findIndex((e) => normalizePropsKey(e.key) === key);
        if (idx >= 0) {
          propsFormEntries[idx] = { ...propsFormEntries[idx], value: rawValue };
        } else {
          propsFormEntries.push({ key, kind: typeof rawValue === "boolean" ? "bool" : "string", value: rawValue });
        }
      }
      flushPropsYamlFromFormBeforeSave();
      await saveProperties({ showToastOnSuccess: true });
    } finally {
      saveBtn.disabled = false;
    }
  });

  footer.appendChild(saveBtn);
  form.appendChild(footer);

  return form;
}

async function renderNodeOverview() {
  if (!nodeOverviewContentNode || !activePath) return;

  syncEntryOverviewKindClass(null);
  syncEntryOverviewMediaAssetKindClass(null);

  const renderSeq = ++nodeOverviewRenderSeq;
  const isStale = () =>
    renderSeq !== nodeOverviewRenderSeq ||
    activeContentMode !== NODE_OVERVIEW_MODE ||
    !nodeOverviewContentNode;

  await Promise.all([
    activePath && !propsFormEntries.length && !String(propsInputNode.value || "").trim()
      ? loadPropertiesForActivePath()
      : Promise.resolve(),
    ensureTopicSchemaForActiveContext().catch(() => null)
  ]);
  if (isStale()) return;

  const entries = resolveNodeOverviewPropsEntries();
  const manifestRaw = modeContentCache.description || "";
  const title = getOverviewTitleFromProps(entries);
  const desc = getOverviewDescription(manifestRaw, entries);
  const typeLabel = getPropsEntryValueByKey(entries, "awn-type");
  const nodePathResolved = getResolvedNodePath(activePath);

  if (isRepositoryTypeLabel(typeLabel) || isRepositoryPageNodePath(nodePathResolved, entries)) {
    await renderRepositoryNavigationPage();
    return;
  }

  const excerpt = stripLeadingDuplicateMarkdownHeading(
    getOverviewMarkdownBeforeDivider(manifestRaw),
    title
  ).trim();
  const isOverviewArea = isAreaNodePath(activePath);
  const [preview, memorySummaryForSlots, mediaOverviewForSlots, todoDataForSlots, nodeConfigPayload] =
    await Promise.all([
      fetchNodeOverviewPreview(),
      fetchMemorySummary(nodePathResolved),
      isOverviewArea ? null : fetchMediaOverview(nodePathResolved),
      fetchTodoForOverview(nodePathResolved),
      loadNodeConfig(nodePathResolved).catch(() => null)
    ]);
  const configSettingsEntries = nodeConfigPayload?.content
    ? parseNodeConfigContent(nodeConfigPayload.content).entries
    : [];
  if (isStale()) return;

  const slotStripGroups = buildNodeSlotStripGroups({
    nodePath: nodePathResolved,
    isArea: isOverviewArea,
    descriptionRaw: manifestRaw,
    memorySummary: memorySummaryForSlots,
    mediaData: mediaOverviewForSlots,
    todoData: todoDataForSlots
  });

  const fragment = document.createDocumentFragment();

  const hero = document.createElement("div");
  hero.className = "node-overview-hero";

  const heroMain = document.createElement("div");
  heroMain.className = "node-overview-hero-main";

  const thumbWrap = createOverviewThumbWrap(preview, title, activePath);

  const head = document.createElement("div");
  head.className = "node-overview-head";

  const headTop = document.createElement("div");
  headTop.className = "node-overview-head-top";

  const statusRaw = resolveAwnStatusFromPropEntries(entries);
  const titleRow = createHeroTitleRow(title, statusRaw, {
    rowClass: "node-navigation-hero-title-row node-overview-title-row",
    titleClass: "node-overview-title",
    statusClass: "node-navigation-hero-status",
    propEntries: entries
  });

  const editManifestBtn = document.createElement("button");
  editManifestBtn.type = "button";
  editManifestBtn.className = "node-overview-action-btn node-overview-edit-btn";
  editManifestBtn.append(createOverviewEditManifestIcon(), document.createTextNode("Редактировать"));
  editManifestBtn.addEventListener("click", openDescriptionFromOverview);

  const revealFolderBtn = document.createElement("button");
  revealFolderBtn.type = "button";
  revealFolderBtn.className = "node-overview-action-btn";
  revealFolderBtn.title = getRevealFolderLabel();
  revealFolderBtn.setAttribute("aria-label", getRevealFolderLabel());
  revealFolderBtn.append(createOverviewRevealFolderIcon(), document.createTextNode(getRevealFolderShortLabel()));
  revealFolderBtn.addEventListener("click", () => {
    void revealNodeFolderInExplorer();
  });

  const headActions = document.createElement("div");
  headActions.className = "node-overview-head-actions";
  headActions.append(editManifestBtn, revealFolderBtn);

  headTop.append(titleRow, headActions);
  head.appendChild(headTop);
  if (typeLabel) {
    const typeNode = document.createElement("span");
    typeNode.className = "node-overview-type";
    typeNode.textContent = typeLabel;
    head.appendChild(typeNode);
  }
  if (desc) {
    const descNode = document.createElement("p");
    descNode.className = "node-overview-desc";
    descNode.textContent = desc;
    head.appendChild(descNode);
  }

  const slotStrip = renderNodeSlotStrip(slotStripGroups);
  if (slotStrip) head.appendChild(slotStrip);

  // Async: view selector (after slotStrip so it doesn't block rendering)
  renderNodeOverviewViewSelector(nodePathResolved).then((viewSelectorEl) => {
    if (viewSelectorEl && head.isConnected) head.appendChild(viewSelectorEl);
  }).catch(() => {});

  heroMain.append(thumbWrap, head);
  hero.appendChild(heroMain);
  appendNavigationHeroProps(hero, entries, { configSettingsEntries, nodePath: nodePathResolved });
  appendNavigationHeroTags(hero, entries);
  fragment.appendChild(hero);

  await appendNodeOverviewTypeRegistryFold(fragment, nodePathResolved);
  if (isStale()) return;

  // Type-specific custom fields form (only for specific sub-types, not generic awn.hub.topic)
  if (typeLabel && awnTypesCache?.types) {
    const typeFieldsSection = renderNodeTypeFieldsSection(typeLabel, entries);
    if (typeFieldsSection) {
      fragment.appendChild(
        createOverviewAccordionSection("type-fields", "✏️ Поля типа", typeFieldsSection, { defaultOpen: true })
      );
    }
  }

  if (excerpt) {
    const excerptBlock = document.createElement("section");
    excerptBlock.className = "node-overview-excerpt";
    const excerptHead = document.createElement("div");
    excerptHead.className = "node-overview-excerpt-head";
    const excerptLabel = document.createElement("span");
    excerptLabel.className = "node-overview-excerpt-label";
    excerptLabel.textContent = desc ? "📖 Подробнее" : "📖 Описание";
    const excerptBody = document.createElement("div");
    excerptBody.className = "node-overview-excerpt-body";
    const excerptText = document.createElement("div");
    excerptText.className = "node-overview-excerpt-text file-content-preview";
    setMarkdownPreviewHtml(excerptText, excerpt, { nodePath: getResolvedNodePath(activePath) });
    excerptHead.appendChild(excerptLabel);
    excerptBody.appendChild(excerptText);
    excerptBlock.append(excerptHead, excerptBody);
    fragment.appendChild(excerptBlock);
  }

  if (isContainerNodePath(activePath) && currentMenuData) {
    const childEntries = getNavigationSubsectionEntries();
    if (childEntries.length) {
      const childrenSection = document.createElement("section");
      childrenSection.className = "node-overview-children";
      const grid = document.createElement("div");
      grid.className = "node-overview-children-grid";
      for (const entry of childEntries) {
        grid.appendChild(createMenuCard(entry, { gallery: true }));
      }
      childrenSection.appendChild(grid);
      fragment.appendChild(
        createOverviewAccordionSection("children", "🗂️ Подразделы", childrenSection, { defaultOpen: true })
      );
    }
  }

  const memorySummary =
    memorySummaryForSlots ?? (await fetchMemorySummary(nodePathResolved)) ?? createEmptyMemorySummary();
  if (isStale()) return;
  activeMemorySummary = memorySummary;
  syncNodeMemoryDriverOptions(memorySummary);
  const memoryBlock = renderOverviewMemoryBlock(memorySummary, nodePathResolved, {
    areaMode: isOverviewArea
  });
  if (memoryBlock) {
    fragment.appendChild(
      createOverviewAccordionSection("memory", "🧠 Память", memoryBlock, { defaultOpen: true })
    );
  }

  const mediaOverview = isOverviewArea ? null : mediaOverviewForSlots ?? (await fetchMediaOverview(nodePathResolved));
  if (isStale()) return;

  const sectionsWrap = document.createElement("div");
  sectionsWrap.className = "node-overview-sections";
  for (const group of getOverviewModeGroups()) {
    if (group.id === "memory") continue;
    if (isOverviewArea && group.id === "files") continue;

    const modes = (group.modes || []).filter((mode) => !mode.disabled && mode.id !== NODE_OVERVIEW_MODE);
    if (!modes.length) continue;

    const section = document.createElement("section");
    section.className = "node-overview-section";
    const isAccordionGroup = OVERVIEW_ACCORDION_GROUP_IDS.has(group.id);
    if (!isAccordionGroup && (group.id === "main" || group.id === "files")) {
      section.classList.add("node-overview-divider");
    }

    const links = document.createElement("div");
    links.className = "node-overview-links node-overview-branch-list";
    for (const mode of modes) {
      if (group.id === "memory" && MEMORY_DRIVER_MODES.has(mode.id) && memorySummary) {
        if (!shouldShowMemoryDriverBlock(mode.id, memorySummary)) continue;
      }
      if (group.id === "main" && mode.id === "description") continue;
      if (mode.id === "media") {
        if (!isOverviewArea) {
          links.appendChild(renderOverviewMediaLink(mediaOverview, getResolvedNodePath(activePath)));
        }
        continue;
      }
      const btn = document.createElement("button");
      btn.type = "button";
      btn.className = "node-overview-link";
      const icon = document.createElement("span");
      icon.className = "node-overview-link-icon";
      icon.setAttribute("aria-hidden", "true");
      icon.textContent = group.icon || "→";
      const label = document.createElement("span");
      label.className = "node-overview-link-label";
      label.textContent = mode.label;
      btn.append(icon, label);
      btn.addEventListener("click", () => {
        if (isOverviewArea && AREA_BLOCKED_CONTENT_MODES.has(mode.id)) return;
        if (NODE_MEMORY_SUB_MODE_IDS.has(mode.id)) {
          openMemoryModeFromOverview(mode.id);
          return;
        }
        if (group.id === "memory" && MEMORY_DRIVER_MODES.has(mode.id)) {
          openMemoryModeFromOverview(mode.id);
          return;
        }
        setContentMode(mode.id);
      });
      links.appendChild(btn);
    }
    if (!links.children.length) continue;
    section.appendChild(links);

    if (isAccordionGroup) {
      sectionsWrap.appendChild(
        createOverviewAccordionSection(
          group.id,
          `${group.icon || ""} ${group.title}`.trim(),
          section,
          { defaultOpen: group.id !== "main" }
        )
      );
      continue;
    }

    const sectionTitle = document.createElement("h3");
    sectionTitle.className = "node-overview-section-title";
    sectionTitle.textContent = `${group.icon || ""} ${group.title}`.trim();
    section.prepend(sectionTitle);
    sectionsWrap.appendChild(section);
  }
  if (sectionsWrap.children.length) {
    fragment.appendChild(sectionsWrap);
  }

  const todoData = todoDataForSlots ?? (await fetchTodoForOverview(nodePathResolved));
  if (isStale()) return;
  const todoBlock = renderOverviewTodoBlock(todoData, getResolvedNodePath(activePath));
  const todoHasContent = Boolean(String(todoData?.content || "").trim());
  fragment.appendChild(
    createOverviewAccordionSection("todo", "✅ TODO", todoBlock, { defaultOpen: todoHasContent })
  );

  if (getActiveNodeApiPath()) {
    await appendNodeCommentsBlockToContainer(fragment, {
      manifestPath: getActiveNodeApiPath(),
      nodeTitle: title,
      mode: "description"
    });
    if (isStale()) return;
  }

  if (isStale()) return;
  nodeOverviewContentNode.replaceChildren(fragment);
  scheduleWorkspaceScrollChromeSync();
  syncDataHubSlugWarning(NODE_OVERVIEW_MODE);
}

