function setTitleSlugLinked(linked) {
  titleSlugLinked = Boolean(linked);
  applyTitleSlugLinkedUi();
  if (titleSlugLinked) syncTitleSlugFromDisplayName();
}

function setCreateSlugLinked(linked) {
  createSlugLinked = Boolean(linked);
  applyCreateSlugLinkedUi();
  if (createSlugLinked) syncCreateSlugFromDisplayName();
}

function getActiveTitleEditorPath() {
  if (activeContentMode === "external" && activeExternalFilePath) return activeExternalFilePath;
  if (isFlatStorageFileEditing()) return activeFlatStorageFilePath;
  if (isMediaLibraryContentMode() && activeMediaMarkdownPath) return activeMediaMarkdownPath;
  if (isMediaLibraryContentMode() && activeMediaSidecarSourcePath) return activeMediaSidecarSourcePath;
  return activePath;
}

function isTitleSlugRenameSupported(nodePath = getActiveTitleEditorPath()) {
  if (!nodePath) return false;
  if (isSlugLockedManifestPath(nodePath)) return false;
  if (activeContentMode === "description") {
    return !isAgentRootIndexPath(nodePath) && !isPartNodePath(nodePath);
  }
  if (activeContentMode === "external" && isSameStorageEditorPath(activeExternalFilePath, nodePath)) {
    return !isSectionReadmePath(nodePath);
  }
  if (isFlatStorageFileEditing() && isSameStorageEditorPath(activeFlatStorageFilePath, nodePath)) {
    return !isSectionReadmePath(nodePath);
  }
  if (isMediaLibraryContentMode() && activeMediaMarkdownPath === nodePath) {
    return !isSectionReadmePath(nodePath);
  }
  if (isMediaLibraryContentMode() && activeMediaSidecarSourcePath === nodePath) {
    return false;
  }
  return false;
}

function isTitleSlugRowVisible(nodePath = getActiveTitleEditorPath()) {
  if (!nodePath) return false;
  if (activeContentMode === "description") {
    return isTitleSlugRenameSupported(nodePath) || isSlugLockedManifestPath(nodePath);
  }
  if (activeContentMode === "external" && isSameStorageEditorPath(activeExternalFilePath, nodePath)) {
    return true;
  }
  if (isFlatStorageFileEditing() && isSameStorageEditorPath(activeFlatStorageFilePath, nodePath)) {
    return true;
  }
  if (isMediaLibraryContentMode() && activeMediaMarkdownPath === nodePath) return true;
  if (isMediaLibraryContentMode() && activeMediaSidecarSourcePath === nodePath) return false;
  return false;
}

function getAwnIdRawForNode(nodePath = activePath) {
  if (!nodePath) return "";
  const visibleEntry = propsFormEntries.find((item) => normalizePropsKey(item?.key) === "awn-id");
  if (visibleEntry) return String(visibleEntry.value ?? "");
  const hiddenEntry = propsFormHiddenEntries.find((item) => normalizePropsKey(item?.key) === "awn-id");
  if (hiddenEntry) return String(hiddenEntry.value ?? "");
  return getYamlScalarFromFrontmatter(propsInputNode?.value || "", "awn-id");
}

function syncTitleIdFromNode(nodePath = getActiveTitleEditorPath()) {
  if (!titleIdRowNode || !titleIdInputNode) return;
  const slugRowVisible = isTitleSlugRowVisible(nodePath);
  const idValue = slugRowVisible ? normalizeAwnIdDisplayValue(getAwnIdRawForNode(nodePath)) : "";
  titleIdInputNode.value = idValue;
  titleIdRowNode.classList.toggle("hidden", !idValue);
}

function showTitleSlugRow(nodePath = getActiveTitleEditorPath()) {
  if (!titleSlugRowNode) return;
  const visible = isTitleSlugRowVisible(nodePath);
  titleSlugRowNode.classList.toggle("hidden", !visible);
  syncTitleIdFromNode(nodePath);
  if (!visible || !titleSlugInputNode) {
    syncDataHubSlugWarning(activeContentMode);
    return;
  }
  const renameSupported = isTitleSlugRenameSupported(nodePath);
  titleSlugUnlinkBtn?.classList.toggle("hidden", !renameSupported);
  if (!renameSupported) {
    titleSlugInputNode.readOnly = true;
    titleSlugUnlinkBtn?.classList.add("hidden");
    syncDataHubSlugWarning(activeContentMode);
    return;
  }
  applyTitleSlugLinkedUi();
  syncDataHubSlugWarning(activeContentMode);
}

function normalizeAwnNameForStorage(displayName, slug) {
  const trimmed = String(displayName || "").trim();
  if (!trimmed) return "";
  if (trimmed === String(slug || "").trim()) return "";
  return trimmed;
}

function getAwnNameRawForNode(nodePath = activePath) {
  if (!nodePath) return "";
  const hiddenEntry = propsFormHiddenEntries.find(
    (item) => normalizePropsKey(item?.key) === "awn-name"
  );
  if (hiddenEntry) return String(hiddenEntry.value ?? "").trim();
  const frontmatter = propsInputNode?.value || "";
  return getYamlScalarFromFrontmatter(frontmatter, "awn-name").trim();
}

function syncTitleFieldsFromNode(nodePath = getActiveTitleEditorPath()) {
  if (!titleInputNode || !nodePath) return;
  const slug = getNodeSlugFromPath(nodePath);
  const rawAwnName = getAwnNameRawForNode(nodePath);
  titleInputNode.value = rawAwnName;
  titleInputNode.placeholder = slug ? `Пусто → в меню: ${slug}` : "Название";
  if (titleSlugInputNode) {
    titleSlugInputNode.value = slug;
  }
  const displayForLink = rawAwnName || slug;
  titleSlugLinked = isAutoSlugForDisplay(displayForLink, slug);
  applyTitleSlugLinkedUi();
  showTitleSlugRow(nodePath);
  syncTitleDescriptionFromNode(nodePath);
  syncDisplayNameLengthHint(titleInputNode);
}

function getNodeSlugFromPath(filePath) {
  const normalized = String(filePath || "").replace(/\\/g, "/");
  const parts = normalized.split("/").filter(Boolean);
  const fileName = parts[parts.length - 1] || "";
  if (isAreaManifestFileName(fileName)) {
    const folderName = parts[parts.length - 2] || "";
    if (folderName.toLowerCase() === STORAGE_ROOT_FOLDER && parts.length >= 3) {
      return stripTopicPrefix(parts[parts.length - 3] || "");
    }
    return stripTopicPrefix(folderName);
  }
  return stripStorageRecordSlugFromFileName(fileName);
}

/** Slug for hero/CHPU display — same canonical segments as workspaceRelToChpuPath / getNodeRoutePath. */
function canonicalizeHeroTopicSlug(slug, filePath = "") {
  const key = String(slug || "").trim().toLowerCase();
  if (!key) return "";
  const pathLower = String(filePath || "").replace(/\\/g, "/").toLowerCase();
  if (pathLower.includes("/0-agent-kit/") || pathLower.includes("/awn-topics/0-agent-kit/")) {
    return AGENT_KIT_TOPIC_LEGACY_SLUG_TO_CANON[key] || String(slug || "").trim();
  }
  if (pathLower.includes("/0-shared/") || pathLower.includes("/awn-topics/0-shared/")) {
    return SHARED_THEME_LEGACY_SLUG_TO_CANON[key] || String(slug || "").trim();
  }
  return String(slug || "").trim();
}

function getNodeHeroSlugFromPath(filePath) {
  const diskSlug = getNodeSlugFromPath(filePath);
  const normalizedPath = String(filePath || "").replace(/\\/g, "/").trim();
  if (!normalizedPath) return diskSlug;

  const routePath = getNodeRoutePath(normalizedPath);
  if (!routePath) return canonicalizeHeroTopicSlug(diskSlug, normalizedPath);
  if (!diskSlug) {
    const tail = routePath.split("/").filter(Boolean).pop() || "";
    return tail || canonicalizeHeroTopicSlug(diskSlug, normalizedPath);
  }

  const diskParts = normalizedPath.split("/").filter(Boolean);
  const routeParts = routePath.split("/").filter(Boolean);
  for (let i = diskParts.length - 1; i >= 0; i -= 1) {
    const part = diskParts[i];
    if (isAreaManifestFileName(part)) continue;
    const stripped = stripTopicPrefix(part);
    if (stripped !== diskSlug && part !== diskSlug) continue;
    if (routeParts[i]) return routeParts[i];
    break;
  }

  return canonicalizeHeroTopicSlug(diskSlug, normalizedPath);
}

function resolveNodeDisplayName(awnNameRaw, slug) {
  const awnName = normalizeYamlDisplayString(awnNameRaw);
  const slugLabel = String(slug || "").trim();
  if (!awnName) return slugLabel;
  if (awnName.toLowerCase() === "manifest") return slugLabel;
  return awnName;
}

function getNodeDisplayTitleFromFrontmatter(filePath, frontmatter = "") {
  const slug = getNodeSlugFromPath(filePath);
  const awnName =
    getYamlScalarFromFrontmatter(frontmatter, "name") ||
    getYamlScalarFromFrontmatter(frontmatter, "awn-name");
  return resolveNodeDisplayName(awnName, slug);
}

function getNodeDisplayTitleForActiveManifest(nodePath = activePath) {
  if (!nodePath) return "";
  const slug = getNodeSlugFromPath(nodePath);
  return resolveNodeDisplayName(getAwnNameRawForNode(nodePath), slug);
}

function syncDisplayNameIntoAwnNameProp(
  nodePath = activePath ||
    activeExternalFilePath ||
    activeFlatStorageFilePath ||
    activeMediaMarkdownPath ||
    activeMediaSidecarSourcePath
) {
  if (!titleInputNode || titleInputNode.disabled) return;
  if (activeContentMode === "description" && isTitleLockedNodePath(nodePath)) return;
  const slug = getNodeSlugFromPath(nodePath);
  const valueToStore = normalizeAwnNameForStorage(titleInputNode.value, slug);

  const upsertHidden = (key, value) => {
    const index = propsFormHiddenEntries.findIndex((entry) => normalizePropsKey(entry.key) === key);
    const nextEntry = { key, kind: "string", value };
    if (index >= 0) propsFormHiddenEntries[index] = nextEntry;
    else propsFormHiddenEntries.push(nextEntry);
  };

  upsertHidden("awn-name", valueToStore);
  propsFormHiddenEntries = propsFormHiddenEntries.filter(
    (entry) => normalizePropsKey(entry.key) !== "title"
  );
  propsFormEntries = propsFormEntries.filter(
    (entry) => !["awn-name", "title"].includes(normalizePropsKey(entry.key))
  );
}

function getAwnDescriptionRawForNode(nodePath = activePath) {
  if (!nodePath) return "";
  const hiddenEntry = propsFormHiddenEntries.find(
    (item) => normalizePropsKey(item?.key) === "awn-description"
  );
  if (hiddenEntry) return String(hiddenEntry.value ?? "");
  const visibleEntry = propsFormEntries.find(
    (item) => normalizePropsKey(item?.key) === "awn-description"
  );
  if (visibleEntry) return String(visibleEntry.value ?? "");
  return getYamlScalarFromFrontmatter(propsInputNode?.value || "", "awn-description");
}

function syncDescriptionIntoAwnDescriptionProp(
  nodePath = activePath ||
    activeExternalFilePath ||
    activeFlatStorageFilePath ||
    activeMediaMarkdownPath ||
    activeMediaSidecarSourcePath
) {
  if (!titleDescriptionInputNode || titleDescriptionInputNode.disabled) return;
  if (activeContentMode === "description" && isTitleLockedNodePath(nodePath)) return;
  const valueToStore = String(titleDescriptionInputNode.value ?? "")
    .replace(/^\s+/, "")
    .replace(/\s+$/, "");

  const upsertHidden = (key, value) => {
    const index = propsFormHiddenEntries.findIndex((entry) => normalizePropsKey(entry.key) === key);
    const nextEntry = { key, kind: "string", value };
    if (index >= 0) propsFormHiddenEntries[index] = nextEntry;
    else propsFormHiddenEntries.push(nextEntry);
  };

  upsertHidden("awn-description", valueToStore);
  propsFormEntries = stripTitleBarKeysFromVisibleEntries(propsFormEntries);
}

function isTitleDescriptionRowVisible(nodePath = getActiveTitleEditorPath()) {
  if (!nodePath) return false;
  if (activeContentMode === "description") {
    return !isPartNodePath(nodePath);
  }
  return isTitleSlugRowVisible(nodePath);
}

function showTitleDescriptionRow(nodePath = getActiveTitleEditorPath()) {
  if (!titleDescriptionRowNode || !titleDescriptionInputNode) return;
  const visible = isTitleDescriptionRowVisible(nodePath);
  titleDescriptionRowNode.classList.toggle("hidden", !visible);
  if (!visible) return;
  const readOnly = isPropsFormReadOnly();
  titleDescriptionInputNode.disabled = readOnly;
  titleDescriptionInputNode.readOnly = readOnly;
}

function syncTitleDescriptionFromNode(nodePath = getActiveTitleEditorPath()) {
  if (!titleDescriptionInputNode) return;
  titleDescriptionInputNode.value = getAwnDescriptionRawForNode(nodePath);
  showTitleDescriptionRow(nodePath);
}

function getNodeDisplayPath(nodePath) {
  const normalized = getResolvedNodePath(nodePath).replace(/\\/g, "/");
  if (!normalized) return "";

  const filePartMatch = normalized.match(/^(.*)\/_Parts\/([^/]+)\.node\.md$/i);
  if (filePartMatch) {
    const parentPath = filePartMatch[1];
    const partName = filePartMatch[2];
    return stripAgentContentPrefixFromRelPath(parentPath ? `${parentPath}/${partName}` : partName);
  }

  if (isPartNodePath(normalized)) {
    const withoutManifest = stripNodeManifestFromPath(normalized);
    const partsMatch = withoutManifest.match(/^(.*)\/_Parts\/([^/]+)$/i);
    if (partsMatch) {
      const parentPath = partsMatch[1];
      const partName = partsMatch[2];
      return stripAgentContentPrefixFromRelPath(parentPath ? `${parentPath}/${partName}` : partName);
    }
  }

  if (isNodeManifestPath(normalized)) {
    if (isAgentSystemRootIndexPath(normalized)) {
      return getServiceRootMenuTitle();
    }
    if (isAgentContainerRootIndexPath(normalized)) {
      return getContainerRootMenuTitle();
    }
    if (isAgentRootIndexPath(normalized)) {
      return getActiveAgentLabel() || getAgentTreeTitle();
    }
    const folderPath = getFolderPathFromManifest(normalized);
    return stripAgentContentPrefixFromRelPath(folderPath || getAgentTreeTitle());
  }

  return rewriteLegacyTopicPathsInRelPathClient(
    stripAgentContentPrefixFromRelPath(normalized.replace(MANIFEST_MD_RE, ""))
  );
}

function getNodeRoutePath(nodePath) {
  const normalized = normalizeMenuNodePath(getResolvedNodePath(nodePath));
  if (!normalized) return "";

  const toRoutePath = (rel) => rewriteLegacyTopicPathsInRelPathClient(stripAgentContentPrefixFromRelPath(rel));

  const filePartMatch = normalized.match(/^(.*)\/_Parts\/([^/]+)\.node\.md$/i);
  if (filePartMatch) {
    const parentPath = filePartMatch[1];
    const partName = filePartMatch[2];
    return toRoutePath(parentPath ? `${parentPath}/${partName}` : partName);
  }

  if (isPartNodePath(normalized)) {
    const withoutManifest = stripNodeManifestFromPath(normalized);
    const partsMatch = withoutManifest.match(/^(.*)\/_Parts\/([^/]+)$/i);
    if (partsMatch) {
      const parentPath = partsMatch[1];
      const partName = partsMatch[2];
      return toRoutePath(parentPath ? `${parentPath}/${partName}` : partName);
    }
  }

  if (isNodeManifestPath(normalized) || isTopicManifestPath(normalized)) {
    const folderPath = getFolderPathFromManifest(normalized);
    return toRoutePath(folderPath || "");
  }

  return toRoutePath(normalized.replace(MANIFEST_MD_RE, ""));
}

function normalizeBreadcrumbPath(nodePath) {
  const normalized = String(nodePath || "").replace(/\\/g, "/").trim();
  if (!normalized) return "";
  if (isNodeManifestPath(normalized) || isTopicManifestPath(normalized) || isPartNodePath(normalized)) {
    return getNodeDisplayPath(normalized);
  }
  return stripNodeManifestFromPath(normalized);
}

function collectAllMenuFlatEntries(menu = currentMenuData) {
  return collectAgentMenuFlatEntries(menu, activeWorkspaceId, { includeHiddenSections: true });
}

function resolveMenuEntryByDisplayPath(displayPath) {
  const normalized = stripVaultPrefixFromRelPath(String(displayPath || "").replace(/\\/g, "/").trim());
  if (!normalized || !currentMenuData) return null;
  const normalizedLower = normalized.toLowerCase();

  for (const entry of collectAllMenuFlatEntries()) {
    const entryDisplay = stripVaultPrefixFromRelPath(entry.displayPath || "");
    if (entryDisplay === normalized) return entry;
    const routePath = getNodeRoutePath(entry.path);
    if (routePath === normalized || routePath.toLowerCase() === normalizedLower) return entry;
  }

  const baseTree = { title: getAgentTreeTitle(), ...currentMenuData };
  if (baseTree.indexPath) {
    const rootDisplay = stripVaultPrefixFromRelPath(getNodeDisplayPath(baseTree.indexPath));
    const rootRoute = getNodeRoutePath(baseTree.indexPath);
    if (rootDisplay === normalized || rootRoute === normalized) {
      return {
        path: baseTree.indexPath,
        label: getLabelFromPath(baseTree.indexPath),
        displayPath: rootDisplay
      };
    }
  }
  return null;
}

function getParentNodeManifestPath(manifestPath) {
  const resolved = normalizeMenuNodePath(String(manifestPath || "").replace(/\\/g, "/"));
  if (!resolved || isAgentRootIndexPath(resolved)) return null;

  if (isNodeManifestPath(resolved)) {
    const folderPath = getFolderPathFromManifest(resolved);
    const parentFolderParts = folderPath.split("/").filter(Boolean);
    parentFolderParts.pop();
    const parentFolder = parentFolderParts.join("/");
    return parentFolder ? `${parentFolder}/${AREA_MANIFEST_FILE}` : AREA_MANIFEST_FILE;
  }

  const folderPath = getFolderPathFromManifest(resolved);
  if (!folderPath) return AREA_MANIFEST_FILE;
  const parentFolderParts = folderPath.split("/").filter(Boolean);
  parentFolderParts.pop();
  const parentFolder = parentFolderParts.join("/");
  return parentFolder ? `${parentFolder}/${AREA_MANIFEST_FILE}` : AREA_MANIFEST_FILE;
}

function getBreadcrumbDisplayParts(filePath = null) {
  const sourcePath =
    filePath ??
    (isNodeWorkspaceBreadcrumbDomain() ? getNodeDisplayPath(activePath) : getBreadcrumbPathForActiveMode());
  return normalizeBreadcrumbPath(sourcePath).split("/").filter(Boolean);
}

function getBreadcrumbManifestPathForSegmentIndex(segmentIndex, displayParts) {
  if (!activePath || segmentIndex < 0 || segmentIndex >= displayParts.length - 1) return null;

  const expectedDisplay = displayParts.slice(0, segmentIndex + 1).join("/");
  const entry = resolveMenuEntryByDisplayPath(expectedDisplay);
  if (entry?.path) return normalizeMenuNodePath(entry.path);

  let manifestPath = normalizeMenuNodePath(getResolvedNodePath(activePath));
  const stepsUp = displayParts.length - 1 - segmentIndex;
  for (let step = 0; step < stepsUp && manifestPath; step += 1) {
    manifestPath = getParentNodeManifestPath(manifestPath);
  }
  if (
    manifestPath &&
    normalizeBreadcrumbPath(getNodeDisplayPath(manifestPath)) === expectedDisplay
  ) {
    return manifestPath;
  }
  return null;
}

async function navigateBreadcrumbToNode(manifestPath) {
  if (!manifestPath || !activePath) return;
  const targetPath = normalizeMenuNodePath(manifestPath);
  const currentPath = normalizeMenuNodePath(getResolvedNodePath(activePath));
  if (targetPath === currentPath) return;
  await openNodeFromMenu(getLabelFromPath(manifestPath), manifestPath);
}

function appendBreadcrumbSeparator() {
  const sepNode = document.createElement("span");
  sepNode.className = "breadcrumb-sep";
  sepNode.textContent = "/";
  filePathNode.appendChild(sepNode);
}

function getBreadcrumbSegmentKindClass(manifestPath) {
  if (!manifestPath) return "";
  if (isAreaNodePath(manifestPath)) return "is-area";
  if (isTopicManifestPath(manifestPath)) return "is-topic";
  return "is-file";
}

function resolveAwnDataBreadcrumbStore(relPath, isCurrent = false) {
  const normalized = String(relPath || "").replace(/\\/g, "/").replace(/^\/+|\/+$/g, "");
  if (!normalized) return null;
  return (
    findAwnDataStoreInPayload(menuAwnDataStoresLastPayload, normalized) ||
    (isCurrent &&
    String(awnDataViewStoreCache?.relPath || "")
      .replace(/\\/g, "/")
      .replace(/^\/+|\/+$/g, "") === normalized
      ? awnDataViewStoreCache
      : null)
  );
}

function createAwnDataBreadcrumbIcon({ className = "", store = null } = {}) {
  const wrap = document.createElement("span");
  wrap.className = "breadcrumb-crumb-icon";
  wrap.setAttribute("aria-hidden", "true");

  if (className === "is-awn-databases-root") {
    const icon = document.createElement("span");
    icon.className = "breadcrumb-crumb-icon-glyph breadcrumb-crumb-icon-glyph--awn-root";
    wrap.appendChild(icon);
    return wrap;
  }

  if (className === "is-awn-databases-record") {
    const icon = document.createElement("span");
    icon.className = "breadcrumb-crumb-icon-glyph breadcrumb-crumb-icon-glyph--record";
    wrap.appendChild(icon);
    return wrap;
  }

  const resolvedStore =
    store ||
    (className === "is-awn-databases-group"
      ? { kind: "group" }
      : className === "is-awn-databases-store"
        ? { kind: "collection" }
        : null);
  if (resolvedStore) {
    const kindNode = createAwnDataStoreKindNode(resolvedStore, { extraClass: "breadcrumb-crumb-kind" });
    kindNode.removeAttribute("title");
    wrap.appendChild(kindNode);
  }
  return wrap;
}

function appendBreadcrumbCrumb(
  label,
  { className = "", isCurrent = false, onClick = null, title = "", store = null, withIcon = false } = {}
) {
  const normalizedLabel = String(label || "").trim();
  if (!normalizedLabel) return false;

  const clickable = Boolean(onClick) && !isCurrent;
  const crumbNode = clickable ? document.createElement("button") : document.createElement("span");
  if (clickable) {
    crumbNode.type = "button";
    crumbNode.addEventListener("click", (event) => {
      event.preventDefault();
      void onClick();
    });
  }
  crumbNode.className = [
    "breadcrumb",
    "is-pill",
    className,
    isCurrent ? "current" : "",
    clickable ? "is-link" : "is-static",
    withIcon ? "has-crumb-icon" : ""
  ]
    .filter(Boolean)
    .join(" ");

  if (withIcon) {
    crumbNode.appendChild(createAwnDataBreadcrumbIcon({ className, store }));
  }

  const labelNode = document.createElement("span");
  labelNode.className = "breadcrumb-crumb-label";
  labelNode.textContent = normalizedLabel;
  crumbNode.appendChild(labelNode);

  if (title) crumbNode.title = title;
  if (clickable && !title) crumbNode.title = `Перейти: ${label}`;
  filePathNode.appendChild(crumbNode);
  return true;
}

function renderFolderBrowseBreadcrumbs(filePath) {
  placeTitleFixedInTitleRow();
  titleFixedValueNode?.classList.add("hidden");

  const normalized = normalizeBreadcrumbPath(filePath);
  const parts = normalized.split("/").filter(Boolean);
  const isFileView =
    activeContentMode === FOLDER_BROWSE_FILE_MODE && Boolean(activeFolderBrowseFilePath);
  const folderPartCount = isFileView ? Math.max(parts.length - 1, 0) : parts.length;

  clearFilePathNode();
  filePathNode.classList.toggle("is-empty", parts.length === 0);

  for (let index = 0; index < folderPartCount; index += 1) {
    const part = parts[index];
    const folderPath = parts.slice(0, index + 1).join("/");
    const label = formatCreateParentLabel(folderPath);
    const isCurrentFolder = !isFileView && index === folderPartCount - 1;

    appendBreadcrumbCrumb(label, {
      isCurrent: isCurrentFolder,
      className: "is-folder-browse-folder",
      onClick:
        isCurrentFolder
          ? null
          : () => {
              void openFolderBrowseFromMenu(label, folderPath);
            },
      title: part !== label ? part : ""
    });

    if (index < folderPartCount - 1 || isFileView) appendBreadcrumbSeparator();
  }

  if (isFileView && parts.length) {
    const fileName = parts[parts.length - 1];
    appendBreadcrumbCrumb(fileName, {
      isCurrent: true,
      className: "is-folder-browse-file is-muted"
    });
  }

  updateWorkspaceShareLinkButton();
}

function scrollToEntryOverviewDocumentHeading(heading) {
  if (!heading) return;
  const preview = findEntryOverviewMarkdownPreview();
  if (!preview) return;
  const target = resolveEntryOverviewPreviewHeadingTarget(preview, heading);
  if (!target) return;

  const scrollElement = findEntryOverviewDocumentScrollElement(preview);
  const scrollOffset = 20;

  if (scrollElement && scrollElement.contains(target)) {
    const targetTop = getOffsetTopWithinScrollContainer(target, scrollElement);
    const nextTop = Math.max(0, targetTop - scrollOffset);
    if (typeof scrollElement.scrollTo === "function") {
      scrollElement.scrollTo({ top: nextTop, behavior: "smooth" });
    } else {
      scrollElement.scrollTop = nextTop;
    }
    return;
  }

  target.scrollIntoView({ behavior: "smooth", block: "start" });
}

function renderEntryOverviewPathBreadcrumbs(context, state = entryOverviewBreadcrumbState) {
  if (!context || !filePathNode) return;

  clearFilePathNode();
  placeTitleFixedInTitleRow();
  titleFixedValueNode?.classList.add("hidden");
  filePathNode.classList.toggle("is-empty", false);

  const topicTitle = getEntryOverviewTopicTitle();
  const navigationIndex = state?.navigationIndex;
  const title = String(state?.title || context.title || "").trim();
  const isMemoryTocRoot = isEntryOverviewMemoryTocRoot(context);
  const tocTitle = getEntryOverviewTocTitle(context.memoryKind);
  const handlers = getEntryOverviewNavigationHandlers(context.memoryKind);

  appendBreadcrumbCrumb(topicTitle, {
    className: "is-topic",
    onClick: () => {
      const topicPath = getResolvedNodePath(activePath) || getActiveNodeApiPath() || "";
      if (isHubWorkspaceFilesSlotPage(topicPath)) {
        void openNodeNavigation(topicTitle, topicPath);
        return;
      }
      setContentMode(NODE_NAVIGATION_MODE);
    },
    title: isAwnChannelPageNodePath()
      ? "Канал"
      : isMediaLibraryPageNodePath()
        ? "Медиатека"
        : "Тема"
  });
  appendBreadcrumbSeparator();

  if (isMemoryTocRoot) {
    appendBreadcrumbCrumb("Оглавление", { isCurrent: true, title: tocTitle });
    updateWorkspaceShareLinkButton();
    return;
  }

  appendBreadcrumbCrumb("Оглавление", {
    onClick: () => openEntryOverviewMemoryTocFromNavigation(context.memoryKind),
    title: tocTitle
  });

  const segments = buildEntryOverviewTrailSegments(context, navigationIndex?.folderLabels, title);
  for (const segment of segments) {
    appendBreadcrumbSeparator();
    if (segment.isCurrent) {
      appendBreadcrumbCrumb(segment.label, { isCurrent: true, title: segment.path });
      continue;
    }
    appendBreadcrumbCrumb(segment.label, {
      onClick: () => {
        if (segment.kind === "folder") {
          handlers.onFolderClick(segment.path);
          return;
        }
        handlers.onFileClick({ path: segment.path, title: segment.label });
      },
      title: segment.path
    });
  }

  updateWorkspaceShareLinkButton();
}

function renderBreadcrumbs(filePath) {
  if (activeContentMode === NODE_ENTRY_OVERVIEW_MODE && activeEntryOverviewContext) {
    renderEntryOverviewPathBreadcrumbs(activeEntryOverviewContext);
    return;
  }

  if (activeContentMode === FOLDER_BROWSE_MODE || activeContentMode === FOLDER_BROWSE_FILE_MODE) {
    renderFolderBrowseBreadcrumbs(filePath);
    return;
  }

  if (activeContentMode === AWN_DATA_VIEW_MODE && awnDataViewStoreRel) {
    renderAwnDataBreadcrumbs();
    return;
  }

  if (isAwnDatabaseManifestEditing()) {
    renderAwnDatabaseManifestEditBreadcrumbs();
    return;
  }

  if (isServiceStyleContentOpen()) {
    const label = getServiceStyleContentLabel();
    const parts = String(filePath || label || "")
      .split("/")
      .filter(Boolean);
    const prefixParts = parts.length > 1 ? parts.slice(0, -1) : [];

    clearFilePathNode();
    filePathNode.classList.toggle("is-empty", false);

    prefixParts.forEach((part, index) => {
      if (index > 0) appendBreadcrumbSeparator();
      appendBreadcrumbCrumb(part);
    });

    if (prefixParts.length > 0) appendBreadcrumbSeparator();

    setTitleLockedDisplay(label);
    return;
  }

  placeTitleFixedInTitleRow();
  titleFixedValueNode?.classList.add("hidden");

  const parts = normalizeBreadcrumbPath(filePath).split("/").filter(Boolean);
  clearFilePathNode();
  filePathNode.classList.toggle("is-empty", parts.length === 0);

  const visibleSegments = parts
    .map((part, index) => ({ part, index }))
    .filter(
      ({ part }) =>
        !isSectionReadmeSegmentName(part) && !isAwnDatabaseBreadcrumbInfrastructureSegment(part, parts)
    );

  visibleSegments.forEach(({ part, index }, visibleIndex) => {
    const isLast = visibleIndex === visibleSegments.length - 1;
    const manifestPath = isLast
      ? getResolvedNodePath(activePath)
      : getBreadcrumbManifestPathForSegmentIndex(index, parts);
    const label = getBreadcrumbSegmentDisplayLabel(index, parts);
    const added = appendBreadcrumbCrumb(label, {
      isCurrent: isLast,
      className: getBreadcrumbSegmentKindClass(manifestPath),
      onClick: !isLast && manifestPath ? () => navigateBreadcrumbToNode(manifestPath) : null,
      title: part !== label ? part : ""
    });
    if (added && !isLast) appendBreadcrumbSeparator();
  });
  updateWorkspaceShareLinkButton();
}

function createSectionNode(title, depth = 0) {
  const sectionNode = document.createElement("div");
  sectionNode.className = "menu-section";
  if (depth > 0) sectionNode.classList.add("menu-section-nested");
  return sectionNode;
}

function nodeMatchesQuery(value, queryLower) {
  if (!queryLower) return true;
  return String(value || "").toLowerCase().includes(queryLower);
}

function filterMenuTree(node, queryLower, agentId = activeWorkspaceId) {
  if (!node) return null;

  if (!queryLower) {
    return pruneMenuTreeForDisplay(node, agentId);
  }

  const filteredSections = [];
  for (const section of node.sections || []) {
    const filteredSection = filterMenuTree(section, queryLower, agentId);
    if (filteredSection) filteredSections.push(filteredSection);
  }

  const filteredItems = (node.items || []).filter((item) => {
    if (!nodeMatchesQuery(item.label, queryLower)) return false;
    if (getMenuTreeSettings(agentId).showActiveTopicsOnly && !isMenuTopicActiveStatus(item.status)) {
      return false;
    }
    return true;
  });
  const filteredRepoServiceItems = getMenuRepoServiceItems(node).filter((item) => {
    if (!nodeMatchesQuery(item.label, queryLower)) return false;
    if (getMenuTreeSettings(agentId).showActiveTopicsOnly && !isMenuTopicActiveStatus(item.status)) {
      return false;
    }
    return true;
  });
  const filteredServiceTree = node.serviceTree
    ? filterMenuTree({ title: SERVICE_SECTION_TITLE, ...node.serviceTree }, queryLower, agentId)
    : null;
  const filteredContainerTree = node.containerTree
    ? filterMenuTree({ title: CONTAINER_SECTION_LABEL, ...node.containerTree }, queryLower, agentId)
    : null;
  const selfMatch = nodeMatchesQuery(node.title, queryLower);
  const keepEmptyFolder =
    isMenuFolderWithoutTopics(node) && getMenuTreeSettings(agentId).showEmptyFolders;

  if (
    selfMatch ||
    keepEmptyFolder ||
    filteredSections.length > 0 ||
    filteredItems.length > 0 ||
    filteredRepoServiceItems.length > 0 ||
    filteredServiceTree ||
    filteredContainerTree
  ) {
    if (!shouldShowMenuTreeFolder(node, agentId) && !selfMatch) return null;
    return {
      ...node,
      sections: filteredSections,
      items: filteredItems,
      repoItems: filteredRepoServiceItems,
      repoServiceItems: filteredRepoServiceItems,
      serviceTree: filteredServiceTree || null,
      containerTree: filteredContainerTree || null
    };
  }

  return null;
}

function compareMenuPathsNatural(aPath, bPath) {
  const collator = new Intl.Collator("ru", { sensitivity: "base", numeric: true });
  const aParts = String(aPath || "").split("/").filter(Boolean);
  const bParts = String(bPath || "").split("/").filter(Boolean);
  const len = Math.min(aParts.length, bParts.length);
  for (let i = 0; i < len; i += 1) {
    const cmp = collator.compare(aParts[i], bParts[i]);
    if (cmp !== 0) return cmp;
  }
  return aParts.length - bParts.length;
}

function getMenuFolderSortIdentity(entry) {
  return String(entry?.folderPath || entry?.indexPath || "").replace(/\\/g, "/");
}

function getMenuItemSortIdentity(entry) {
  return normalizeMenuNodePath(entry?.path || "");
}

function getOrderedMenuChildren(node) {
  if (!node) return [];
  const sections = (node.sections || []).filter(Boolean);
  const items = (node.items || []).filter(Boolean);
  const order = Array.isArray(node.menuOrder) ? node.menuOrder : null;
  const sectionBySlug = new Map();
  const sectionByTitle = new Map();
  for (const entry of sections) {
    if (!entry.title) continue;
    sectionByTitle.set(entry.title, entry);
    const slug = getMenuSortSlugFromFolderEntry(entry);
    if (slug) sectionBySlug.set(slug, entry);
  }
  const itemBySlug = new Map();
  const itemByLabel = new Map();
  for (const entry of items) {
    if (!entry.label) continue;
    itemByLabel.set(entry.label, entry);
    const slug = getMenuSortSlugFromItemEntry(entry);
    if (slug) itemBySlug.set(slug, entry);
  }
  const orderedFolders = [];
  const orderedItems = [];
  const usedSections = new Set();
  const usedItems = new Set();

  if (order?.length) {
    for (const name of order) {
      const sectionEntry = sectionBySlug.get(name) || sectionByTitle.get(name);
      const sectionIdentity = sectionEntry ? getMenuFolderSortIdentity(sectionEntry) : "";
      if (sectionEntry && sectionIdentity && !usedSections.has(sectionIdentity)) {
        orderedFolders.push({ kind: "folder", entry: sectionEntry });
        usedSections.add(sectionIdentity);
        continue;
      }
      const itemEntry = itemBySlug.get(name) || itemByLabel.get(name);
      const itemIdentity = itemEntry ? getMenuItemSortIdentity(itemEntry) : "";
      if (itemEntry && itemIdentity && !usedItems.has(itemIdentity)) {
        orderedItems.push({ kind: "item", entry: itemEntry });
        usedItems.add(itemIdentity);
      }
    }
  }

  const remainingSections = sections
    .filter((entry) => {
      const identity = getMenuFolderSortIdentity(entry);
      return entry.title && identity && !usedSections.has(identity);
    })
    .sort((a, b) => String(a.title).localeCompare(String(b.title), "ru"));
  const remainingItems = items
    .filter((entry) => {
      const identity = getMenuItemSortIdentity(entry);
      return entry.label && identity && !usedItems.has(identity);
    })
    .sort((a, b) => String(a.label).localeCompare(String(b.label), "ru"));

  // Области (папки) всегда выше тем (файлов), даже если в awn-sort.json порядок смешан.
  return [
    ...orderedFolders,
    ...remainingSections.map((entry) => ({ kind: "folder", entry })),
    ...orderedItems,
    ...remainingItems.map((entry) => ({ kind: "item", entry }))
  ];
}

function normalizeMenuNodePath(nodePath) {
  const normalized = String(nodePath || "").replace(/\\/g, "/");
  const base = normalized.includes("/")
    ? normalized.slice(normalized.lastIndexOf("/") + 1)
    : normalized;
  if (isAreaManifestFileName(base) && base !== AREA_MANIFEST_FILE) {
    const dir = normalized.includes("/") ? normalized.slice(0, normalized.lastIndexOf("/")) : "";
    return dir ? `${dir}/${AREA_MANIFEST_FILE}` : AREA_MANIFEST_FILE;
  }
  return normalized;
}

function findMenuNodeByPath(node, targetPath) {
  const normalized = normalizeMenuNodePath(targetPath);
  if (!node || !normalized) return null;
  if (normalizeMenuNodePath(node.indexPath) === normalized) return node;

  for (const item of node.items || []) {
    if (normalizeMenuNodePath(item.path) === normalized) {
      return {
        indexPath: item.path,
        title: item.label,
        items: [],
        sections: [],
        color: item.color || null,
        hasPreview: Boolean(item.hasPreview),
        previewUrl: item.previewUrl || null,
        awnEmoji: item.awnEmoji || null
      };
    }
  }

  for (const item of getMenuRepoServiceItems(node)) {
    if (normalizeMenuNodePath(item.path) === normalized) {
      return {
        indexPath: item.path,
        title: item.label,
        items: [],
        sections: [],
        color: item.color || null,
        hasPreview: Boolean(item.hasPreview),
        previewUrl: item.previewUrl || null,
        awnEmoji: item.awnEmoji || null
      };
    }
  }

  for (const section of node.sections || []) {
    const found = findMenuNodeByPath(section, normalized);
    if (found) return found;
  }
  return null;
}

function findMenuNodeInAgentMenu(menuRoot, targetPath) {
  const normalized = normalizeMenuNodePath(getResolvedNodePath(targetPath));
  if (!menuRoot || !normalized) return null;

  const mainMatch = findMenuNodeByPath(menuRoot, normalized);
  if (mainMatch) return mainMatch;

  const serviceTree = menuRoot?.serviceTree;
  if (serviceTree) {
    const serviceMatch = findMenuNodeByPath({ title: "", ...serviceTree }, normalized);
    if (serviceMatch) return serviceMatch;
  }

  const containerTree = menuRoot?.containerTree;
  if (containerTree) {
    const containerMatch = findMenuNodeByPath({ title: "", ...containerTree }, normalized);
    if (containerMatch) return containerMatch;
  }

  const sharedTree = menuRoot?.sharedTree;
  if (!sharedTree) return null;
  return findMenuNodeByPath({ title: "", ...sharedTree }, normalized);
}

function findMenuNodeInContainerMenu(menuRoot, targetPath) {
  const normalized = normalizeMenuNodePath(getResolvedNodePath(targetPath));
  if (!menuRoot?.containerTree || !normalized) return null;
  return findMenuNodeByPath({ title: "", ...menuRoot.containerTree }, normalized);
}

function findMenuSectionInAgentMenu(menuRoot, folderPath) {
  if (!menuRoot) return null;
  const folderSection = findMenuSectionByFolderPath(menuRoot, folderPath);
  if (folderSection) return folderSection;
  const serviceTree = menuRoot?.serviceTree;
  if (serviceTree) {
    const serviceSection = findMenuSectionByFolderPath({ title: "", ...serviceTree }, folderPath);
    if (serviceSection) return serviceSection;
  }
  const containerTree = menuRoot?.containerTree;
  if (containerTree) {
    const containerSection = findMenuSectionByFolderPath({ title: "", ...containerTree }, folderPath);
    if (containerSection) return containerSection;
  }

  const sharedTree = menuRoot?.sharedTree;
  if (!sharedTree) return null;
  return findMenuSectionByFolderPath({ title: "", ...sharedTree }, folderPath);
}

function menuNodeHasChildren(node) {
  const nestedServiceChildren = node.serviceTree ? getOrderedMenuChildren(node.serviceTree).length : 0;
  const nestedContainerChildren = node.containerTree ? getOrderedMenuChildren(node.containerTree).length : 0;
  const nestedSharedChildren = node.sharedTree ? getOrderedMenuChildren(node.sharedTree).length : 0;
  return (
    getOrderedMenuChildren(node).length > 0 ||
    getMenuRepoServiceItems(node).length > 0 ||
    nestedServiceChildren > 0 ||
    nestedContainerChildren > 0 ||
    nestedSharedChildren > 0
  );
}

function filterRepoServiceItemsForMenuSection(items, sectionFolderPath = ".") {
  if (normalizeFolderPath(sectionFolderPath || ".") !== ".") {
    return (items || []).filter(Boolean);
  }
  return (items || []).filter((item) => {
    const path = normalizeMenuNodePath(item?.path);
    if (!path) return true;
    return path.includes("/");
  });
}

function appendRepoServiceMenuItems(
  container,
  repoServiceItems,
  parentMenuNode,
  agentId = activeWorkspaceId,
  sectionFolderPath = "."
) {
  const items = filterRepoServiceItemsForMenuSection(repoServiceItems, sectionFolderPath);
  if (!items.length) return;

  for (const item of items) {
    const itemRow = document.createElement("div");
    itemRow.className = "menu-item-row menu-item-row--repo-service";
    itemRow.dataset.sortName = getMenuSortSlugFromItemEntry(item);
    appendMenuTreeItemRowLeadingSpacer(itemRow);

    const btn = document.createElement("button");
    btn.type = "button";
    btn.className = "menu-item menu-item--repo-service";
    setMenuTreeItemLabel(btn, item, parentMenuNode, agentId);
    const itemPath = normalizeMenuNodePath(item.path);
    btn.dataset.path = itemPath;
    btn.title = item.path;
    applyNodeColorVars(btn, item.color);
    btn.addEventListener("click", (event) => {
      const pathFromNode = event.currentTarget?.dataset?.path || "";
      void selectRepoLooseFile(getLabelFromPath(pathFromNode), pathFromNode);
    });

    itemRow.appendChild(btn);
    itemRow.appendChild(createBookmarkButton(itemPath));
    container.appendChild(itemRow);
  }
}

function findMenuSectionByFolderPath(node, folderPath, parentSectionPath = "", depth = 0) {
  if (!node) return null;
  const targetFolder = normalizeMenuNodePath(folderPath);
  const sectionFolderPath = normalizeMenuNodePath(resolveSectionFolderPath(node, parentSectionPath, depth));
  const indexFolder = node.indexPath
    ? normalizeMenuNodePath(getFolderPathFromManifest(node.indexPath))
    : "";

  if (menuNodeHasChildren(node) && indexFolder === targetFolder) {
    return node;
  }
  if (menuNodeHasChildren(node) && depth > 0 && sectionFolderPath === targetFolder) {
    return node;
  }

  if (node.containerTree) {
    const containerFolder = getActiveAgentContainerFolder();
    if (containerFolder) {
      const containerPrefix =
        sectionFolderPath === "."
          ? containerFolder
          : `${sectionFolderPath}/${containerFolder}`.replace(/\/+/g, "/");
      const found = findMenuSectionByFolderPath(
        { title: "", ...node.containerTree },
        folderPath,
        containerPrefix,
        depth + 1
      );
      if (found) return found;
    }
  }

  for (const section of node.sections || []) {
    const found = findMenuSectionByFolderPath(
      section,
      folderPath,
      resolveSectionFolderPath(node, parentSectionPath, depth),
      depth + 1
    );
    if (found) return found;
  }
  return null;
}

function findOverviewChildrenSourceNode(menuRoot, nodePath) {
  const normalized = normalizeMenuNodePath(getResolvedNodePath(nodePath));
  const direct = findMenuNodeInAgentMenu(menuRoot, normalized);
  if (direct && menuNodeHasChildren(direct)) {
    return direct;
  }

  const folderRel = normalizeMenuNodePath(getFolderPathFromManifest(normalized));
  const folderSection = findMenuSectionInAgentMenu(menuRoot, folderRel);
  if (folderSection) return folderSection;

  return direct;
}

function collectDirectChildNodeEntries(menuNode) {
  if (!menuNode) return [];
  const entries = [];
  const seenPaths = new Set();

  function pushEntry(entry) {
    const key = String(entry?.path || "");
    if (!key || seenPaths.has(key)) return;
    seenPaths.add(key);
    entries.push(entry);
  }

  function entryFromSection(section) {
    if (!section?.indexPath || section.empty) return null;
    return {
      path: section.indexPath,
      label: resolveMenuEntryLabel(section.indexPath, section.title),
      displayPath: getNodeDisplayPath(section.indexPath),
      color: section.color || null,
      status: section.status || null,
      hasPreview: Boolean(section.hasPreview),
      previewUrl: section.previewUrl || null,
      isFolder: true
    };
  }

  function entryFromItem(item) {
    if (!item?.path) return null;
    return {
      path: item.path,
      label: resolveMenuEntryLabel(item.path, item.label),
      displayPath: getNodeDisplayPath(item.path),
      color: item.color || null,
      status: item.status || null,
      hasPreview: Boolean(item.hasPreview),
      previewUrl: item.previewUrl || null,
      isFolder: isNodeManifestPath(item.path) && !isPartNodePath(item.path)
    };
  }

  function walkNode(node) {
    for (const child of getOrderedMenuChildren(node)) {
      if (child.kind === "folder") {
        const section = child.entry;
        if (section?.empty) continue;
        const folderEntry = entryFromSection(section);
        if (folderEntry) {
          pushEntry(folderEntry);
          continue;
        }
        walkNode(section);
        continue;
      }

      const itemEntry = entryFromItem(child.entry);
      if (itemEntry) pushEntry(itemEntry);
    }
  }

  walkNode(menuNode);
  return entries;
}

function collectRepoRootFlatEntries(node, acc, agentId = activeWorkspaceId) {
  const activeOnly = getMenuTreeSettings(agentId).showActiveTopicsOnly;
  for (const item of getMenuRepoServiceItems(node)) {
    if (activeOnly && !isMenuTopicActiveStatus(item?.status)) continue;
    acc.push({
      path: item.path,
      label: getLabelFromPath(item.path),
      displayPath: `${REPO_ROOT_MENU_GROUP_LABEL} / ${getNodeDisplayPath(item.path)}`,
      color: item.color || null,
      hasPreview: Boolean(item.hasPreview),
      previewUrl: item.previewUrl || null,
      tags: Array.isArray(item.tags) ? item.tags : [],
      category: item.category || null,
      isFolder: false,
      isRepoRoot: true
    });
  }
  return acc;
}

function collectFlatMenuEntries(node, acc = [], options = {}) {
  const includeRepoRoot = options.includeRepoRoot !== false;
  const agentId = options.agentId || activeWorkspaceId;
  const activeOnly = getMenuTreeSettings(agentId).showActiveTopicsOnly;

  if (node.indexPath) {
    if (!activeOnly || isMenuTopicActiveStatus(node.status)) {
      const displayPath = getNodeDisplayPath(node.indexPath);
      const normalizedDisplay = stripVaultPrefixFromRelPath(displayPath);
      const folderPath = stripVaultPrefixFromRelPath(
        stripAgentContentPrefixFromRelPath(getFolderPathFromManifest(node.indexPath) || "")
      );
      const menuMap = getMenuDisplayLabelMap();
      const mapped =
        menuMap.get(normalizeMenuNodePath(node.indexPath)) ||
        menuMap.get(normalizedDisplay) ||
        (folderPath ? menuMap.get(folderPath) : null);
      acc.push({
        path: node.indexPath,
        label: mapped || String(node.title || "").trim() || getLabelFromPath(node.indexPath),
        displayPath,
        color: node.color || null,
        status: node.status || null,
        hasPreview: Boolean(node.hasPreview),
        previewUrl: node.previewUrl || null,
        awnEmoji: node.awnEmoji || null,
        tags: Array.isArray(node.tags) ? node.tags : [],
        category: node.category || null,
        isFolder: true,
        hasGit: Boolean(node.hasGitSelf ?? node.hasGit),
        hasObsidian: Boolean(node.hasObsidianSelf ?? node.hasObsidian),
        hasAgent: Boolean(node.hasAgentSelf ?? node.hasAgent),
        hasGitSelf: Boolean(node.hasGitSelf ?? node.hasGit),
        hasObsidianSelf: Boolean(node.hasObsidianSelf ?? node.hasObsidian),
        hasAgentSelf: Boolean(node.hasAgentSelf ?? node.hasAgent)
      });
    }
  }

  const childOptions = { includeRepoRoot: false, agentId };

  if (node.serviceTree) {
    collectFlatMenuEntries(pruneMenuTreeForDisplay({ title: "", ...node.serviceTree }, agentId), acc, childOptions);
  }
  if (node.containerTree) {
    collectFlatMenuEntries(pruneMenuTreeForDisplay({ title: "", ...node.containerTree }, agentId), acc, childOptions);
  }

  for (const child of getVisibleMenuChildren(node, agentId)) {
    if (child.kind === "folder") {
      collectFlatMenuEntries(child.entry, acc, childOptions);
      continue;
    }
    if (activeOnly && !isMenuTopicActiveStatus(child.entry?.status)) continue;
    acc.push({
      path: child.entry.path,
      label: resolveMenuEntryLabel(child.entry.path, child.entry.label),
      displayPath: getNodeDisplayPath(child.entry.path),
      color: child.entry.color || null,
      status: child.entry.status || null,
      hasPreview: Boolean(child.entry.hasPreview),
      previewUrl: child.entry.previewUrl || null,
      awnEmoji: child.entry.awnEmoji || null,
      tags: Array.isArray(child.entry.tags) ? child.entry.tags : [],
      category: child.entry.category || null,
      isFolder: false
    });
  }

  if (includeRepoRoot) {
    collectRepoRootFlatEntries(node, acc, agentId);
  }

  return acc;
}

function collectAgentMenuFlatEntries(menu, agentId = activeWorkspaceId, options = {}) {
  if (!menu) return [];
  const includeHiddenSections = options.includeHiddenSections === true;
  const childOptions = { includeRepoRoot: false, agentId };
  const baseTree = getWorkspaceRootMenuTreeNode(menu, agentId);
  const entries = collectFlatMenuEntries(
    baseTree,
    [],
    options.includeRepoRoot === false ? childOptions : { ...childOptions, includeRepoRoot: true }
  );

  if (menu.serviceTree && (includeHiddenSections || shouldShowServiceSectionInMenu(agentId))) {
    entries.push(
      ...collectFlatMenuEntries(
        pruneMenuTreeForDisplay({ title: "", ...menu.serviceTree }, agentId),
        [],
        childOptions
      )
    );
  }
  if (menu.containerTree && (includeHiddenSections || shouldShowContainerSectionInMenu(agentId))) {
    entries.push(
      ...collectFlatMenuEntries(
        pruneMenuTreeForDisplay({ title: "", ...menu.containerTree }, agentId),
        [],
        childOptions
      )
    );
  }
  if (menu.sharedTree && (includeHiddenSections || shouldShowSharedSectionInMenu(agentId))) {
    entries.push(
      ...collectFlatMenuEntries(
        pruneMenuTreeForDisplay({ title: "", ...menu.sharedTree }, agentId),
        [],
        childOptions
      )
    );
  }
  return entries;
}

function normalizeSystemFileName(name) {
  const base = String(name || "").trim();
  const lower = base.toLowerCase();
  if (lower === "todo.md" || lower === "todo") return ROOT_SYSTEM_TODO_FILE;
  if (lower === "note.md" || lower === "note" || lower === "notes.md" || lower === "notes") {
    return ROOT_SYSTEM_NOTE_FILE;
  }
  if (lower === "agents.md" || lower === "agents") return "AGENTS.md";
  if (lower === "auth.md" || lower === "auth") return "AUTH.md";
  if (lower === "bootstrap.md" || lower === "bootstrap") return "BOOTSTRAP.md";
  if (lower === "onboarding.md" || lower === "onboarding") return "ONBOARDING.md";
  if (lower === "skill.md" || lower === "skill") return "SKILL.md";
  if (lower === "readme.md" || lower === "readme") return "README.md";
  if (lower === "wsmap.md" || lower === "ws-map.md" || lower === "wsmap" || lower === "ws-map") {
    return WORKSPACE_WSMAP_FILE;
  }
  if (lower === ".env" || lower === "env") return ".env";
  if (lower === ".gitignore" || lower === "gitignore") return ".gitignore";
  return base;
}

function getSystemFileMenuLabel(name) {
  return normalizeSystemFileName(name);
}

function classifySystemFileGroup(name) {
  const base = String(name || "").trim();
  const lower = base.toLowerCase();
  if (lower.endsWith(".md")) return "md";
  const configNames = new Set([
    ".env",
    ".gitignore",
    ".dockerignore",
    ".editorconfig",
    ".npmrc",
    ".nvmrc",
    ".prettierrc",
    ".eslintrc",
    "dockerfile",
    "makefile",
    "procfile",
    "dependencies.csv",
    "docker-compose.yml",
    "docker-compose.yaml"
  ]);
  if (configNames.has(lower)) return "config";
  if (lower.startsWith(".env.") || lower.startsWith("docker-compose.")) return "config";
  if (/\.(csv|json|ya?ml|toml|ini|cfg|conf|properties|env)$/i.test(lower)) return "config";
  if (lower.startsWith(".") && !lower.includes(".", 1)) return "config";
  return "other";
}

function isCoreSystemFileName(name) {
  return CORE_SYSTEM_FILES.has(normalizeSystemFileName(name));
}

const ROOT_SYSTEM_CONFIG_FILES = new Set([
  "dependencies.csv",
  "docker-compose.yml",
  "docker-compose.yaml"
]);

function resolveSystemFileOpenMode(name, exists) {
  const base = normalizeSystemFileName(name);
  if (isCoreSystemFileName(base)) return "system";
  if (ROOT_SYSTEM_CONFIG_FILES.has(base)) return "system";
  return exists ? "adopt" : "system";
}

function collectSystemFileMenuEntries(files) {
  return (Array.isArray(files) ? files : [])
    .filter((file) => Boolean(normalizeSystemFileName(file?.name)))
    .map((file) => {
    const systemFile = normalizeSystemFileName(file.name);
    const exists = Boolean(file.exists);
    const group = file.group || classifySystemFileGroup(systemFile);
    const openMode = resolveSystemFileOpenMode(systemFile, exists);
    return {
      path: null,
      systemFile,
      label: getSystemFileMenuLabel(systemFile),
      displayPath: getSystemFileMenuLabel(systemFile),
      color: "slate",
      hasPreview: false,
      previewUrl: null,
      exists,
      empty: Boolean(file.empty ?? !exists),
      group,
      openMode,
      scaffold: Boolean(file.scaffold),
      isSystemFile: true
    };
  });
}

function groupSystemFileMenuEntries(entries) {
  const groups = new Map(SYSTEM_FILE_GROUP_ORDER.map((id) => [id, []]));
  for (const entry of entries) {
    const groupId = SYSTEM_FILE_GROUP_ORDER.includes(entry.group) ? entry.group : "other";
    if (!groups.has(groupId)) groups.set(groupId, []);
    groups.get(groupId).push(entry);
  }
  return SYSTEM_FILE_GROUP_ORDER
    .map((id) => ({
      id,
      label: SYSTEM_FILE_GROUP_LABELS[id] || id,
      entries: groups.get(id) || []
    }))
    .filter((group) => group.entries.length > 0);
}

function buildSystemFileItemClassName(file) {
  const empty = Boolean(file?.empty ?? !file?.exists);
  return ["menu-item", "system-file-item", empty ? "empty" : file?.exists ? "exists" : ""]
    .filter(Boolean)
    .join(" ");
}

function getMenuEntrySearchSlug(entry) {
  if (entry?.isSystemFile) return normalizeSystemFileName(entry.systemFile);
  if (entry?.path) return getMenuSortSlugFromItemEntry(entry) || getNodeSlugFromPath(entry.path);
  return "";
}

function entryMatchesMenuQuery(entry, queryLower) {
  if (!queryLower) return true;
  if (nodeMatchesQuery(entry.label, queryLower)) return true;

  const slug = getMenuEntrySearchSlug(entry);
  if (slug && nodeMatchesQuery(slug, queryLower)) return true;

  if (nodeMatchesQuery(entry.systemFile, queryLower)) return true;
  if (nodeMatchesQuery(entry.category, queryLower)) return true;
  if (Array.isArray(entry.tags) && entry.tags.some((tag) => nodeMatchesQuery(tag, queryLower))) {
    return true;
  }

  const path = String(entry.path || "").replace(/\\/g, "/");
  if (path) {
    for (const segment of path.split("/").filter(Boolean)) {
      const stem = segment.replace(/\.md$/i, "");
      if (nodeMatchesQuery(stem, queryLower)) return true;
    }
  }

  return false;
}

function collectMenuSearchEntries(menu, agentId = activeWorkspaceId) {
  if (!menu) return [];
  const entries = [
    ...collectAgentMenuFlatEntries(menu, agentId, { includeHiddenSections: true }),
    ...collectSystemFileMenuEntries(systemFilesCache)
  ];
  if (menu.systemTree && shouldShowAgentSystemSectionInMenu(agentId)) {
    entries.push(
      ...collectFlatMenuEntries(
        pruneMenuTreeForDisplay({ title: AGENT_SYSTEM_SECTION_LABEL, ...menu.systemTree }, agentId),
        [],
        { includeRepoRoot: false, agentId }
      )
    );
  }
  const seen = new Set();
  return entries.filter((entry) => {
    const key = entry.isSystemFile
      ? `system:${entry.systemFile}`
      : `path:${normalizeMenuNodePath(entry.path || "")}`;
    if (!key || seen.has(key)) return false;
    seen.add(key);
    return Boolean(entry.isSystemFile || entry.path);
  });
}

function getMenuSearchResultEntries(menu, agentId = activeWorkspaceId) {
  const queryLower = menuSearchQuery.trim().toLowerCase();
  if (!queryLower) return [];
  return collectMenuSearchEntries(menu, agentId).filter((entry) => entryMatchesMenuQuery(entry, queryLower));
}

function filterMenuEntriesByQuery(entries, queryLower) {
  if (!queryLower) return entries;
  return entries.filter((entry) => entryMatchesMenuQuery(entry, queryLower));
}

function menuSearchHasResults(menu, agentId = activeWorkspaceId) {
  const queryLower = menuSearchQuery.trim().toLowerCase();
  if (!queryLower) return true;
  return getMenuSearchResultEntries(menu, agentId).length > 0;
}

