async function executeMenuNodeMove(move) {
  if (!move) return false;
  const sourceLabel = resolveMenuEntryLabel(move.source);
  const targetLabel = resolveMenuEntryLabel(move.target);
  const confirmed = await askConfirm(
    `Переместить «${sourceLabel}» в «${targetLabel}»?`,
    { okLabel: "Подтвердить" }
  );
  if (!confirmed) return false;
  try {
    const data = await moveNodeByPath(move.source, move.parentPath);
    invalidateMenuAgentCache(activeWorkspaceId);
    await refreshMenu();
    if (data.path) {
      await openNodeFromMenu(getLabelFromPath(data.path), data.path);
    }
    notifyMarkdownLinkRewrite(data.linkRewrite);
    showToast("Перемещено", "success");
    return true;
  } catch (error) {
    showToast(`Ошибка перемещения: ${error.message}`, "error");
    return false;
  }
}

function findMenuNodeInAgentMenuForPath(targetPath, agentId = activeWorkspaceId) {
  const menu = menuCacheByAgent.get(agentId) || (agentId === activeWorkspaceId ? currentMenuData : null);
  if (!menu) return null;
  const menuRoot = { title: getAgentTreeTitle(agentId), ...menu };
  return (
    findMenuNodeInAgentMenu(menuRoot, targetPath) ||
    (menu.sharedTree ? findMenuNodeByPath({ title: "", ...menu.sharedTree }, targetPath) : null)
  );
}

function menuTreeNodeHasChildSlots(node) {
  if (!node) return false;
  if ((node.sections || []).length > 0) return true;
  if ((node.items || []).length > 0) return true;
  if (node.containerTree) return true;
  if (node.serviceTree) return true;
  if (node.sharedTree) return true;
  return false;
}

function canMenuNodeAcceptChildNodes(nodePath, agentId = activeWorkspaceId) {
  const normalized = normalizeMenuNodePath(nodePath);
  if (!normalized || !getMenuContextMenuKind(normalized)) return false;
  if (isPartNodePath(normalized) || isSystemReferenceManifestPath(normalized)) return false;
  if (
    isAgentRootIndexPath(normalized) ||
    isAgentContainerRootIndexPath(normalized) ||
    isAgentSharedRootIndexPath(normalized) ||
    isAgentSystemRootIndexPath(normalized)
  ) {
    return true;
  }
  if (isAreaNodePath(normalized)) return true;

  const declared = getDeclaredManifestTreeType(normalized);
  if (declared === "area" || declared === "workspace") return true;

  const menuNode = findMenuNodeInAgentMenuForPath(normalized, agentId);
  if (menuTreeNodeHasChildSlots(menuNode)) return true;

  if (declared === "topic") return false;
  if (isTopicManifestPath(normalized) && !isAreaNodePath(normalized)) return false;

  return isNodeManifestPath(normalized) && getManifestTreeFolderDepth(normalized) < 2;
}

function resolveMenuDragMove(sourcePath, targetPath) {
  const source = normalizeMenuNodePath(sourcePath);
  const target = normalizeMenuNodePath(targetPath);
  if (!source || !target || source === target) return null;
  if (!getMenuContextMenuKind(source) || !getMenuContextMenuKind(target)) return null;
  if (!canMenuNodeAcceptChildNodes(target)) return null;

  const parentPath = getFolderPathFromManifest(target) || ".";

  if (isAreaNodePath(source)) {
    const sourceFolder = getFolderPathFromManifest(source);
    if (
      sourceFolder &&
      (parentPath === sourceFolder || parentPath.startsWith(`${sourceFolder}/`))
    ) {
      return null;
    }
    if (getNodeParentPathForMove(source) === parentPath) return null;
  } else if ((getFolderPathFromManifest(source) || ".") === parentPath) {
    return null;
  }

  return { source, target, parentPath };
}

function setupMenuNodeMoveDragDrop() {
  if (!menuNode || menuNode.dataset.moveDragBound === "1") return;
  menuNode.dataset.moveDragBound = "1";

  menuNode.addEventListener("dragover", (event) => {
    if (menuSortDragRow || !menuLinkDragBtn || !isMenuContextMenuTarget(menuLinkDragBtn)) return;
    const targetBtn = event.target.closest(MENU_LINK_DRAG_SOURCE_SELECTOR);
    if (!targetBtn || targetBtn === menuLinkDragBtn || !isMenuContextMenuTarget(targetBtn)) {
      clearMenuMoveDropTarget();
      return;
    }
    const move = resolveMenuDragMove(
      menuLinkDragBtn.dataset.path,
      targetBtn.dataset.path
    );
    if (!move) {
      clearMenuMoveDropTarget();
      return;
    }
    event.preventDefault();
    event.stopPropagation();
    event.dataTransfer.dropEffect = "move";
    setMenuMoveDropTarget(targetBtn);
  });

  menuNode.addEventListener("dragleave", (event) => {
    if (!menuLinkDragBtn || menuNode.contains(event.relatedTarget)) return;
    clearMenuMoveDropTarget();
  });

  menuNode.addEventListener("drop", async (event) => {
    if (menuSortDragRow || !menuLinkDragBtn || !isMenuContextMenuTarget(menuLinkDragBtn)) return;
    const targetBtn = event.target.closest(MENU_LINK_DRAG_SOURCE_SELECTOR);
    clearMenuMoveDropTarget();
    if (!targetBtn || targetBtn === menuLinkDragBtn || !isMenuContextMenuTarget(targetBtn)) return;

    const move = resolveMenuDragMove(
      menuLinkDragBtn.dataset.path,
      targetBtn.dataset.path
    );
    if (!move) return;

    event.preventDefault();
    event.stopPropagation();

    clearMenuMoveDropTarget();
    menuSortDragRow?.classList.remove("is-dragging");
    menuSortDragRow = null;
    await executeMenuNodeMove(move);
  });

  menuNode.addEventListener("dragend", () => {
    clearMenuMoveDropTarget();
  });
}

function setupEditorMenuLinkDrop() {
  const targets = [
    editorSurfaceNode,
    editorCodeWrapNode,
    editorWysiwygWrapNode,
    fileContentInputNode,
    fileContentPreviewNode
  ].filter(Boolean);
  if (!targets.length || editorSurfaceNode?.dataset.menuLinkDropBound === "1") return;
  if (editorSurfaceNode) editorSurfaceNode.dataset.menuLinkDropBound = "1";

  const setDropTarget = (active) => {
    editorSurfaceNode?.classList.toggle("is-menu-link-drop-target", active);
  };

  for (const target of targets) {
    target.addEventListener("dragover", (event) => {
      if (!dataTransferHasMenuLink(event.dataTransfer)) return;
      if (!canPasteMarkdownAttachment()) return;
      event.preventDefault();
      event.dataTransfer.dropEffect = "copy";
      setDropTarget(true);
    });

    target.addEventListener("dragleave", (event) => {
      if (!editorSurfaceNode?.contains(event.relatedTarget)) {
        setDropTarget(false);
      }
    });

    target.addEventListener("drop", (event) => {
      setDropTarget(false);
      if (!dataTransferHasMenuLink(event.dataTransfer)) return;
      if (!canPasteMarkdownAttachment()) return;
      const payload = extractMenuLinkFromDataTransfer(event.dataTransfer);
      const linkText = payload?.markdownLink || payload?.wikilink;
      if (!linkText) return;
      event.preventDefault();
      event.stopPropagation();
      if (editorViewMode === "source" && fileContentInputNode) {
        fileContentInputNode.focus();
      }
      insertMarkdownAtEditorCursor(linkText);
    });
  }
}

function renderMenu(menu, agentId = activeWorkspaceId, options = {}) {
  const menuOnly = Boolean(options.menuOnly);
  menu = stripPlatformDataFoldersFromMenu(menu);
  if (agentId === activeWorkspaceId && activeWorkspaceId) {
    hideMenuNoAgentPlaceholder();
  }
  const target = ensureMenuAgentPane(agentId);
  menuCacheByAgent.set(agentId, menu);
  indexManifestTreeTypesFromMenu(menu);
  if (agentId === activeWorkspaceId) {
    currentMenuData = menu;
    invalidateMenuDisplayLabelMap();
    if (!menuOnly) {
      invalidateAgentStorageLayoutCache();
    }
    activateMenuAgentPane(agentId);
  }

  const agentTitle = getAgentTreeTitle(agentId);
  const baseTree = getWorkspaceRootMenuTreeNode(menu, agentId);
  const filteredTree = filterMenuTree(baseTree, menuSearchQuery.trim().toLowerCase(), agentId);
  const treeToRender = filteredTree || { title: agentTitle, sections: [], items: [], indexPath: null };

  if (agentId === activeWorkspaceId && !menuOnly) {
    sanitizeCollapsedFolderPaths(agentId);
    const allPaths = new Set(
      collectAllMenuFlatEntries(menu).map((entry) => nodeStorageKey(agentId, entry.path))
    );
    pruneBookmarks(allPaths);
    pruneNodeConfigCache(allPaths);
    applyMenuCardsFilterUi();
  }

  if (isMenuTreeLayoutMode() && !menuSearchQuery.trim() && getPinnedMenuFolder(agentId)) {
    applyPinnedBranchCollapse(agentId);
  }

  target.innerHTML = "";
  if (menuViewMode === "bookmarks") {
    renderBookmarksMenu(menu, target, agentId);
  } else if (menuViewMode === "cards") {
    renderCardsMenu(menu, target, agentId);
  } else if (menuSearchQuery.trim()) {
    if (!menuSearchHasResults(menu, agentId)) {
      appendMenuSearchEmptyState(target);
    } else {
      renderMenuSearchResults(menu, target, agentId);
    }
  } else {
    renderTree(treeToRender, target, 0, ".", null, agentId);
    const childrenContainer = getWorkspacesTreeChildren(agentId);
    if (childrenContainer) {
      renderRootMenuReservedSections(menu, childrenContainer, agentId);
    }
    renderSystemFiles(systemFilesCache);
    decorateMenuSortRows(target);
    refreshClassicMenuTreeLines(agentId);
    refreshMenuTreeIntakeBadges(agentId);
    refreshMenuTreeRuntimeBadges(agentId);
    void prefetchMenuReadStates(menu, agentId).then(() => refreshMenuReadBadges(agentId));
  }

  if (agentId === activeWorkspaceId) {
    if (!menuOnly) {
      syncAgentPreview();
    }
    syncMenuViewLayoutClass(agentId);
    syncMenuSearchLayoutClass(agentId);
    syncMenuCollapseAllButton();
    syncMenuPinBranchUi(agentId);
    ensureSidebarWorkspacePageIndexRow();
    syncAgentGitToolbarUi();
    void prefetchAgentGitToolbarRepoState();
  }

  enableMenuLinkDragSources(target);

  if (agentId === activeWorkspaceId && getDocAsideTab() === "links") {
    renderDocLinksLibrary();
  }

  if (agentId === activeWorkspaceId) {
    scheduleMenuAgentStatsSync(menu);
    requestAnimationFrame(syncMenuScrollTopButton);
    updateActiveButton();
    syncWorkspaceTreeCutMarkers();
    syncWorkspaceTreeSelectionMarkers();
  }
}

