async function syncMenuAgentStats(menu = currentMenuData) {
  if (!menuAgentStatsNode) return;

  if (!activeWorkspaceId) {
    hideMenuAgentStats();
    return;
  }

  const seq = ++menuAgentStatsSeq;
  menuAgentStorageSummaryCache = null;
  const counts = countAgentMenuNodes(menu);
  menuAgentStatsNode.classList.remove("hidden");
  renderMenuAgentStatsContent({ counts, loading: true });
  syncMenuSystemEnvironment();

  try {
    const [workspace, intakeTotals] = await Promise.all([
      fetchAgentWorkspaceStats().catch(() => null),
      refreshMenuIntakeSummary(menu, activeWorkspaceId).catch(() => null)
    ]);
    if (seq !== menuAgentStatsSeq) return;
    renderMenuAgentStatsContent({
      counts,
      workspace,
      summaryLine: menuAgentStorageSummaryCache?.summaryLine
    });
    syncChannelLiveUpdates();
  } catch {
    if (seq !== menuAgentStatsSeq) return;
    renderMenuAgentStatsContent({ counts, workspace: null });
  }
}

function getWorkspacesTreeChildren(agentId = activeWorkspaceId) {
  const rootHost = menuAgentPanes.get(agentId) || getMenuQueryRoot();
  const rootSection = rootHost?.querySelector(".menu-section");
  if (!rootSection) return null;

  const containerClass =
    menuViewMode === "bookmarks"
      ? "menu-flat-list"
      : menuViewMode === "cards"
        ? "menu-cards-grid"
        : "tree-children";
  let childrenNode = rootSection.querySelector(`:scope > .${containerClass}`);
  if (!childrenNode) {
    childrenNode = document.createElement("div");
    childrenNode.className = containerClass;
    rootSection.appendChild(childrenNode);
  }
  return childrenNode;
}

function createWorkspaceRootTreeBodyWrap(folderPath = ".") {
  const wrap = document.createElement("div");
  wrap.className = "menu-workspace-root-section";
  const body = document.createElement("div");
  body.className = "tree-children menu-workspace-body";
  body.dataset.sortFolder = folderPath || ".";
  wrap.appendChild(body);
  return { wrap, body };
}

function findWorkspaceRootTreeBody(parentSection) {
  return (
    parentSection?.querySelector(
      ":scope > .tree-children > .menu-workspace-root-section > .tree-children.menu-workspace-body"
    ) || null
  );
}

function ensureWorkspaceRootTreeBody(parentSection) {
  const existing = findWorkspaceRootTreeBody(parentSection);
  if (existing) return existing;

  let outer = parentSection.querySelector(":scope > .tree-children");
  if (!outer) {
    outer = document.createElement("div");
    outer.className = "tree-children";
    parentSection.appendChild(outer);
  }

  const { wrap, body } = createWorkspaceRootTreeBodyWrap(".");
  const insertBefore = getMenuTreeInsertAnchor(outer);
  if (insertBefore) {
    outer.insertBefore(wrap, insertBefore);
  } else {
    outer.appendChild(wrap);
  }
  return body;
}

function resolveMenuTreeSortContainer(parentSection, folderPath = ".") {
  if (normalizeFolderPath(folderPath) === ".") {
    return ensureWorkspaceRootTreeBody(parentSection);
  }
  return parentSection?.querySelector(":scope > .tree-children") || null;
}

const SYSTEM_FILE_SORT_PRIORITY = new Map(
  [
    ".env",
    ".gitignore",
    "dependencies.csv",
    "docker-compose.yml",
    "docker-compose.yaml"
  ].map((name, index) => [name.toLowerCase(), index])
);

function systemFileSortPriority(name) {
  const key = String(name || "").trim().toLowerCase();
  return SYSTEM_FILE_SORT_PRIORITY.has(key) ? SYSTEM_FILE_SORT_PRIORITY.get(key) : 1000;
}

function sortSystemFilesByName(files) {
  return [...(Array.isArray(files) ? files : [])].sort((a, b) => {
    const pa = systemFileSortPriority(a?.name);
    const pb = systemFileSortPriority(b?.name);
    if (pa !== pb) return pa - pb;
    return String(a?.name || "").localeCompare(String(b?.name || ""), "en");
  });
}

function clearSystemFileMenuNodes(container) {
  if (!container) return;
  container.querySelectorAll(".menu-system-files-section").forEach((node) => node.remove());
  clearMenuSystemFilesDivider(container);
}

function createSystemFileGroupLabel(label, groupId) {
  const node = document.createElement("div");
  node.className = "system-file-group-label";
  node.dataset.systemFileGroup = groupId;
  node.setAttribute("role", "presentation");

  if (isMenuTreeLayoutMode()) {
    const text = document.createElement("span");
    text.className = "system-file-group-label-text menu-tree-title-text";
    text.textContent = label;
    node.appendChild(text);
  } else {
    node.textContent = label;
  }

  return node;
}

async function openRootSystemMenuFile(file) {
  const systemFile = normalizeSystemFileName(file?.systemFile || file?.name);
  if (!systemFile) return;
  const exists = Boolean(file?.exists);
  const openMode = resolveSystemFileOpenMode(systemFile, exists);
  if (openMode === "adopt" && exists) {
    await openFolderBrowseFile(file.label || systemFile, systemFile, { folderPath: "." });
    return;
  }
  const empty = Boolean(file?.empty ?? !exists);
  // Menu always opens in preview (no ~edit). Only empty hint scaffolds
  // (.env / .gitignore) start in edit so the yellow template strip works.
  const startInEdit =
    !isReadOnlyWorkspacePageIndexSystemFile(systemFile) &&
    (!exists || empty) &&
    Boolean(getSystemFileHintSpec(systemFile));
  await selectSystemFile(systemFile, { edit: startInEdit });
}

function renderSystemFiles(files) {
  const container = getWorkspacesTreeChildren();
  if (!container) return;

  clearSystemFileMenuNodes(container);

  const queryLower = menuSearchQuery.trim().toLowerCase();
  const visibleFiles = filterMenuEntriesByQuery(
    collectSystemFileMenuEntries(sortSystemFilesByName(files)),
    queryLower
  );
  const groups = groupSystemFileMenuEntries(visibleFiles);

  syncMenuSystemFilesDivider(container, groups.length > 0);
  if (groups.length === 0) {
    enableMenuLinkDragSources(getMenuQueryRoot());
    refreshClassicMenuTreeLines();
    return;
  }

  const section = document.createElement("div");
  section.className = "menu-system-files-section";

  for (const group of groups) {
    section.appendChild(createSystemFileGroupLabel(group.label, group.id));
    for (const file of group.entries) {
      const row = document.createElement("div");
      row.className = "menu-item-row system-file-row";
      row.dataset.systemFileGroup = group.id;
      appendMenuTreeItemRowLeadingSpacer(row);

      const btn = document.createElement("button");
      btn.type = "button";
      btn.className = buildSystemFileItemClassName(file);
      btn.classList.add("system-file-item");
      btn.textContent = file.label;
      btn.dataset.systemFile = file.systemFile;
      btn.dataset.systemFileGroup = group.id;
      btn.dataset.openMode = file.openMode || resolveSystemFileOpenMode(file.systemFile, file.exists);
      const hasContent = file.exists && !file.empty;
      btn.title = hasContent
        ? "Открыть служебный файл"
        : file.exists
          ? "Открыть для редактирования"
          : "Создать и заполнить";
      btn.addEventListener("click", () => {
        void openRootSystemMenuFile(file);
      });

      row.appendChild(btn);
      section.appendChild(row);
    }
  }

  container.appendChild(section);

  enableMenuLinkDragSources(getMenuQueryRoot());
  refreshClassicMenuTreeLines();
}

async function loadSystemFileTemplates() {
  try {
    const response = await fetch(buildApiUrl("/api/system-file-templates"));
    if (!response.ok) throw new Error(`Request failed with ${response.status}`);
    const data = await response.json();
    const raw = data?.templates && typeof data.templates === "object" ? data.templates : {};
    const next = {};
    for (const [key, template] of Object.entries(raw)) {
      const target = normalizeSystemFileName(key);
      if (!target || !template?.body) continue;
      next[target] = template;
    }
    systemFileTemplatesByTarget = next;
  } catch {
    systemFileTemplatesByTarget = {};
  }
}

async function loadSystemFiles(options = {}) {
  await loadSystemFileTemplates();
  const mergeSystemFileLists = (primary, fallback) => {
    const byName = new Map();
    for (const file of fallback) {
      const name = normalizeSystemFileName(file?.name);
      if (!name) continue;
      byName.set(name.toLowerCase(), { ...file, name });
    }
    for (const file of primary) {
      const name = normalizeSystemFileName(file?.name);
      if (!name) continue;
      const key = name.toLowerCase();
      byName.set(key, { ...(byName.get(key) || {}), ...file, name });
    }
    return sortSystemFilesByName([...byName.values()]);
  };

  try {
    const response = await fetch(buildApiUrl("/api/system-files"));
    if (!response.ok) throw new Error(`Request failed with ${response.status}`);
    const data = await response.json();
    const apiFiles = (Array.isArray(data.files) ? data.files : []).map((file) => {
      const name = normalizeSystemFileName(file.name);
      const exists = Boolean(file.exists);
      return {
        ...file,
        name,
        exists,
        empty: Boolean(file.empty ?? !exists),
        group: file.group || classifySystemFileGroup(name),
        openMode: resolveSystemFileOpenMode(name, exists)
      };
    });
    systemFilesCache = mergeSystemFileLists(apiFiles, SYSTEM_FILE_SCAFFOLD_FALLBACK);
  } catch {
    systemFilesCache = mergeSystemFileLists([], SYSTEM_FILE_SCAFFOLD_FALLBACK);
  }
  if (options.skipRender) return;
  if (currentMenuData) {
    withPreservedMenuScroll(() => {
      renderMenu(currentMenuData);
    });
    updateActiveButton();
  } else {
    renderSystemFiles(systemFilesCache);
  }
  syncRepositoriesDependenciesButtonState();
  if (options.refreshNotePreview) {
    void syncAgentTodoPreview();
  }
}

function isMenuTreeButtonActive(item, { resolvedActive, resolvedFolderBrowse } = {}) {
  if (activeSystemFile) return false;

  const rawFolderPath = item.dataset.folderPath;
  if (rawFolderPath != null && rawFolderPath !== "") {
    if (activePath || !activeFolderBrowsePath) return false;
    return normalizeCreateParentPath(rawFolderPath) === resolvedFolderBrowse;
  }

  const itemPath = normalizeMenuNodePath(item.dataset.path || "");
  return Boolean(resolvedActive) && itemPath === resolvedActive;
}

function updateActiveButton() {
  const root = getMenuQueryRoot();
  const resolvedActive = activePath ? normalizeMenuNodePath(getResolvedNodePath(activePath)) : "";
  const resolvedFolderBrowse = activeFolderBrowsePath
    ? normalizeCreateParentPath(activeFolderBrowsePath)
    : null;
  const items = root.querySelectorAll(".menu-item, .menu-folder");
  for (const item of items) {
    const isActive = isMenuTreeButtonActive(item, { resolvedActive, resolvedFolderBrowse });
    item.classList.toggle("active", isActive);
  }
  for (const item of root.querySelectorAll(".system-file-item")) {
    const name = normalizeSystemFileName(item.dataset.systemFile || "");
    const asSystem = Boolean(activeSystemFile) && name === activeSystemFile;
    const asAdopt =
      activeContentMode === FOLDER_BROWSE_FILE_MODE &&
      Boolean(activeFolderBrowseFilePath) &&
      normalizeCreateParentPath(activeFolderBrowseFilePath) === name;
    item.classList.toggle("active", asSystem || asAdopt);
  }
  syncAgentNotePreviewActiveState();
  for (const card of (appRootNode || document).querySelectorAll(".menu-card-body[data-path]")) {
    const itemPath = normalizeMenuNodePath(card.dataset.path || "");
    const isActive = !activeSystemFile && Boolean(resolvedActive) && itemPath === resolvedActive;
    card.classList.toggle("active", isActive);
    card.closest(".menu-card")?.classList.toggle("active", isActive);
  }
  for (const card of (appRootNode || document).querySelectorAll(".menu-card[data-system-file]")) {
    const name = normalizeSystemFileName(card.dataset.systemFile || "");
    card.classList.toggle("active", Boolean(activeSystemFile) && name === activeSystemFile);
  }
  syncFocusPanelActiveState();
  syncMenuPinBranchUi();
  syncSidebarRoadmapGlobeToolbarUi();
  syncMenuMediaLibraryActiveState();
  const wsIndexOpen = document.querySelector(".sidebar-workspace-page-index-open");
  if (wsIndexOpen) {
    wsIndexOpen.classList.toggle(
      "active",
      Boolean(activeWorkspaceTocRelPath) &&
        activeWorkspaceTocRelPath.toLowerCase() === getWorkspacePageIndexRelPath().toLowerCase()
    );
  }
}

async function selectSystemFile(name, options = {}) {
  const normalizedName = normalizeSystemFileName(name);
  if (!normalizedName) return;
  clearActiveWorkspaceTocView();
  if (isReadOnlyWorkspacePageIndexSystemFile(normalizedName)) {
    options = { ...options, edit: false };
  }
  if (
    !options.force &&
    normalizedName === activeSystemFile &&
    normalizedName === ROOT_SYSTEM_NOTE_FILE &&
    options.edit === undefined
  ) {
    updateActiveButton();
    syncAgentNotePreviewActiveState();
    syncAgentTodoPreviewFromEditor();
    if (!options.skipRouteSync) {
      syncAppRouteToUrl({ replace: true });
    }
    return;
  }
  hideHomeView();
  nodeOverviewRenderSeq += 1;
  activeSystemFile = normalizedName;
  systemFileEditActive = Boolean(options.edit);
  editorViewMode = resolveSystemFileEditorViewMode(normalizedName, { edit: systemFileEditActive });
  activePath = null;
  activeLabel = null;
  activeFolderBrowsePath = null;
  activeFolderBrowseFilePath = null;
  folderBrowseExpandedPagePath = null;
  if (
    activeContentMode === FOLDER_BROWSE_MODE ||
    activeContentMode === FOLDER_BROWSE_FILE_MODE
  ) {
    activeContentMode = "description";
  }
  activeExternalFilePath = null;
  nodeSettingsViewActive = false;
  nodeMemoryViewActive = false;
  clearMediaSidecarEditor();
  updateActiveButton();
  setLoading("Загрузка файла...");

  try {
    const response = await fetch(buildApiUrl("/api/system-file", { name: normalizedName }));
    if (!response.ok) throw new Error(`Request failed with ${response.status}`);
    const data = await response.json();
    const contentEmpty = data.exists === false || !(data.content || "").trim();
    // Auto-edit only when the caller did not choose a mode (e.g. deep link) and
    // the file is an empty hint-scaffold. Menu clicks pass edit explicitly.
    if (
      !isReadOnlyWorkspacePageIndexSystemFile(normalizedName) &&
      options.edit === undefined &&
      contentEmpty &&
      Boolean(getSystemFileHintSpec(normalizedName))
    ) {
      systemFileEditActive = true;
      editorViewMode = resolveSystemFileEditorViewMode(normalizedName, { edit: true });
    }
    fileContentInputNode.value = data.content || "";
    setPropsYamlContent("");
    applyModeUi();
    refreshEditorViewContent();
    commitEditorSaveBaseline();
  } catch (error) {
    fileContentInputNode.value = `Ошибка чтения файла: ${error.message}`;
    applyModeUi();
    commitEditorSaveBaseline();
  } finally {
    hideContentLoading({ force: true });
    if (normalizedName === ROOT_SYSTEM_NOTE_FILE) {
      syncAgentTodoPreviewFromEditor();
    } else if (normalizedName === ROOT_SYSTEM_TODO_FILE) {
      syncAppFooterIdeasFromEditor();
    }
    if (!options.skipRouteSync) {
      syncAppRouteToUrl({ replace: true });
    }
  }
}

async function selectRepoLooseFile(label, filePath, options = {}) {
  const normalizedPath = normalizeMenuNodePath(filePath);
  if (!normalizedPath || !isGitRepoLooseFilePath(normalizedPath)) {
    await selectFile(label, filePath);
    return;
  }

  hideHomeView();
  nodeOverviewRenderSeq += 1;
  clearActiveSystemFile();
  activePath = normalizedPath;
  activeLabel = label || getLabelFromPath(normalizedPath);
  activeFolderBrowsePath = null;
  activeFolderBrowseFilePath = null;
  folderBrowseExpandedPagePath = null;
  activeExternalFilePath = null;
  nodeSettingsViewActive = false;
  nodeMemoryViewActive = false;
  clearMediaSidecarEditor();
  updateActiveButton();
  setLoading("Загрузка файла...");
  setPropsYamlContent("");
  const isMd = /\.md$/i.test(normalizedPath);
  applyContentModeState(isMd ? "internal" : "description");

  try {
    const response = await fetch(buildApiUrl("/api/repo-loose-file", { path: normalizedPath }));
    if (!response.ok) throw new Error(`Request failed with ${response.status}`);
    const data = await response.json();
    const content = data.content || "";
    if (isMd) {
      modeContentCache.internal = content;
    }
    fileContentInputNode.value = content;
    applyModeUi();
    if (isGitRepoLooseMdEditing()) {
      updateBreadcrumbsForActiveMode();
      setDocAsideTab("outline");
    }
    refreshEditorViewContent();
    commitEditorSaveBaseline();
  } catch (error) {
    fileContentInputNode.value = `Ошибка чтения файла: ${error.message}`;
    applyModeUi();
    commitEditorSaveBaseline();
  } finally {
    hideContentLoading({ force: true });
    if (!options.skipRouteSync) {
      syncAppRouteToUrl({ replace: true });
    }
  }
}

