// ── Type YAML helpers ──────────────────────────────────────────────────────
function toggleTypeYamlVisibility() {
  appRootNode.classList.toggle("is-agent-type-form-mode");
}

function patchTypeYamlList(key, items) {
  if (!fileContentInputNode) return;
  const yaml = fileContentInputNode.value;
  const safeKey = key.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  const newBlock = items.length > 0
    ? `${key}:\n${items.map((i) => `  - ${i}`).join("\n")}`
    : `${key}: []`;
  const listRe = new RegExp(`^${safeKey}:[ \\t]*(?:\\[\\]|(?:\\n(?:  - [^\\n]*))+)`, "m");
  const patched = listRe.test(yaml)
    ? yaml.replace(listRe, newBlock)
    : `${yaml.trimEnd()}\n${newBlock}\n`;
  fileContentInputNode.value = patched;
  fileContentInputNode.dispatchEvent(new Event("input", { bubbles: true }));
}

function deleteTypeFieldFromYaml(fieldKey) {
  if (!fileContentInputNode || !fieldKey) return;
  const yaml = fileContentInputNode.value;
  const lines = yaml.split("\n");
  const fieldPrefix = `  ${fieldKey}:`;
  let inField = false;
  const result = [];
  for (const line of lines) {
    if (!inField) {
      const isTarget = line.startsWith(fieldPrefix) &&
        (line.length === fieldPrefix.length || line[fieldPrefix.length] === " ");
      if (isTarget) { inField = true; continue; }
      result.push(line);
    } else {
      if (line.startsWith("    ") || line.trim() === "") continue;
      inField = false;
      result.push(line);
    }
  }
  fileContentInputNode.value = result.join("\n");
  fileContentInputNode.dispatchEvent(new Event("input", { bubbles: true }));
}

function buildTypeStorageSlotsEditor(currentSlots) {
  const KNOWN_SLOTS = ["main", "media", "inbox", "discussion", "references", "scripts", "templates", "base", "notebooklm", "task-queue", "artefacts", "assets", "repository"];
  const slots = Array.isArray(currentSlots) ? [...currentSlots] : [];

  const wrap = document.createElement("div");
  wrap.className = "type-slots-editor";

  const label = document.createElement("span");
  label.className = "type-meta-edit-label";
  label.textContent = "Слоты";

  const tagsWrap = document.createElement("div");
  tagsWrap.className = "type-slots-tags";

  function renderTags() {
    tagsWrap.replaceChildren();
    for (const slot of slots) {
      const tag = document.createElement("span");
      tag.className = "type-slot-tag";
      tag.textContent = slot;
      const del = document.createElement("button");
      del.type = "button";
      del.className = "type-slot-tag-del";
      del.textContent = "×";
      del.title = `Удалить слот ${slot}`;
      del.addEventListener("click", () => {
        slots.splice(slots.indexOf(slot), 1);
        renderTags();
        patchTypeYamlList("storage-slots", slots);
      });
      tag.appendChild(del);
      tagsWrap.appendChild(tag);
    }
    // Add input
    const addRow = document.createElement("span");
    addRow.className = "type-slots-add-row";
    const inp = document.createElement("input");
    inp.type = "text";
    inp.className = "type-slots-add-input";
    inp.placeholder = "слот...";
    inp.list = "type-slots-datalist";
    const confirm = document.createElement("button");
    confirm.type = "button";
    confirm.className = "type-slots-add-btn";
    confirm.textContent = "+";
    const addSlot = () => {
      const val = inp.value.trim().toLowerCase().replace(/\s+/g, "-");
      if (val && !slots.includes(val)) {
        slots.push(val);
        renderTags();
        patchTypeYamlList("storage-slots", slots);
      }
      inp.value = "";
    };
    confirm.addEventListener("click", addSlot);
    inp.addEventListener("keydown", (e) => { if (e.key === "Enter") { e.preventDefault(); addSlot(); } });
    addRow.append(inp, confirm);
    tagsWrap.appendChild(addRow);

    // datalist for autocomplete
    let dl = document.getElementById("type-slots-datalist");
    if (!dl) {
      dl = document.createElement("datalist");
      dl.id = "type-slots-datalist";
      document.body.appendChild(dl);
    }
    dl.replaceChildren();
    for (const s of KNOWN_SLOTS.filter((s) => !slots.includes(s))) {
      const opt = document.createElement("option");
      opt.value = s;
      dl.appendChild(opt);
    }
  }

  renderTags();
  wrap.append(label, tagsWrap);
  return wrap;
}

function patchTypeYamlScalar(key, rawValue) {
  if (!fileContentInputNode) return;
  const yaml = fileContentInputNode.value;
  const safeKey = key.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  const re = new RegExp(`^(${safeKey}):[^\\S\\n]*.*$`, "m");
  const needsQuotes = /[:#\[\]{}|>&*!,'"%@`]/.test(String(rawValue)) || /^\s|\s$/.test(String(rawValue));
  const formatted = needsQuotes ? `"${String(rawValue).replace(/"/g, '\\"')}"` : String(rawValue);
  const newLine = `${key}: ${formatted}`;
  const patched = re.test(yaml) ? yaml.replace(re, newLine) : `${yaml.trimEnd()}\n${newLine}\n`;
  fileContentInputNode.value = patched;
  fileContentInputNode.dispatchEvent(new Event("input", { bubbles: true }));
}

function addTypeFieldToYaml(fieldKey, fieldType, fieldTitle) {
  if (!fileContentInputNode || !fieldKey || !fieldType) return;
  const yaml = fileContentInputNode.value;
  const indent = "  ";
  let fieldBlock = `${indent}${fieldKey}:\n${indent}  type: ${fieldType}\n`;
  if (fieldTitle) fieldBlock += `${indent}  title: ${fieldTitle}\n`;
  const fieldsRe = /^(fields:)\s*\n/m;
  let patched;
  if (fieldsRe.test(yaml)) {
    patched = yaml.replace(fieldsRe, `$1\n${fieldBlock}`);
  } else {
    patched = `${yaml.trimEnd()}\nfields:\n${fieldBlock}`;
  }
  fileContentInputNode.value = patched;
  fileContentInputNode.dispatchEvent(new Event("input", { bubbles: true }));
}

function buildTypeMetaEditForm(detail) {
  const wrap = document.createElement("div");
  wrap.className = "type-meta-edit-form";

  function makeRow(labelText, inputEl) {
    const row = document.createElement("label");
    row.className = "type-meta-edit-row";
    const lbl = document.createElement("span");
    lbl.className = "type-meta-edit-label";
    lbl.textContent = labelText;
    row.append(lbl, inputEl);
    return row;
  }

  const nameInput = document.createElement("input");
  nameInput.type = "text";
  nameInput.className = "type-meta-edit-input";
  nameInput.value = detail.name || "";
  nameInput.placeholder = "Название типа";
  nameInput.addEventListener("change", () => patchTypeYamlScalar("name", nameInput.value.trim()));
  wrap.appendChild(makeRow("Название", nameInput));

  const descInput = document.createElement("input");
  descInput.type = "text";
  descInput.className = "type-meta-edit-input";
  descInput.value = detail.description || "";
  descInput.placeholder = "Описание";
  descInput.addEventListener("change", () => patchTypeYamlScalar("description", descInput.value.trim()));
  wrap.appendChild(makeRow("Описание", descInput));

  const statusSel = document.createElement("select");
  statusSel.className = "type-meta-edit-select";
  for (const [val, label] of [["active", "Активен"], ["inactive", "Неактивен"], ["draft", "Черновик"]]) {
    const opt = document.createElement("option");
    opt.value = val;
    opt.textContent = label;
    if (val === (detail.status || "active")) opt.selected = true;
    statusSel.appendChild(opt);
  }
  statusSel.addEventListener("change", () => patchTypeYamlScalar("status", statusSel.value));
  wrap.appendChild(makeRow("Статус", statusSel));

  // Доменные контролы формы строятся из properties: самого типа (по цепочке
  // наследования), а НЕ хардкодятся. Хочешь новое поле в форме — добавь его в
  // properties базового типа домена (например awn.slot, awn.view.base).
  const schema = detail.schema || {};
  const mergedSchema = detail.mergedSchema || {};
  // У fields блок properties описывает ЭКЗЕМПЛЯР поля (type/name/hint…), а не
  // top-level конфиг типа-поля — поэтому для fields рендерим курируемо ниже.
  const props =
    detail.domain !== "fields" && mergedSchema.properties && typeof mergedSchema.properties === "object"
      ? mergedSchema.properties
      : {};

  const propValue = (key) => {
    if (schema[key] != null) return schema[key];
    if (mergedSchema[key] != null) return mergedSchema[key];
    return "";
  };
  const normEnum = (arr) =>
    (Array.isArray(arr) ? arr : []).map((o) =>
      o && typeof o === "object"
        ? [String(o.key ?? o.value ?? ""), String(o.name ?? o.label ?? o.key ?? o.value ?? "")]
        : [String(o), String(o)]
    );

  // Доменные контролы — в отдельную секцию с подзаголовком и акцентом, чтобы
  // визуально отличались от базовых полей (name/description/status).
  const domainWrap = document.createElement("div");
  domainWrap.className = "type-meta-domain-section";

  // Служебные/структурные ключи уже редактируются сверху или менять их вручную нельзя.
  const META_PROP_SKIP = new Set(["id", "name", "description", "status", "kind", "extends", "domain"]);
  for (const [key, rawSpec] of Object.entries(props)) {
    if (META_PROP_SKIP.has(key)) continue;
    const spec = rawSpec && typeof rawSpec === "object" ? rawSpec : {};
    const label = spec.title || key;
    const value = propValue(key);
    const isList = spec.type === "list" || spec.type === "array" || Array.isArray(value);
    let control;

    if (Array.isArray(spec.enum) && spec.enum.length) {
      control = document.createElement("select");
      control.className = "type-meta-edit-select";
      const opts = spec.required
        ? normEnum(spec.enum)
        : [["", "— не задан —"], ...normEnum(spec.enum)];
      const cur = String(value || "");
      for (const [v, l] of opts) {
        const opt = document.createElement("option");
        opt.value = v;
        opt.textContent = l;
        if (v === cur) opt.selected = true;
        control.appendChild(opt);
      }
      control.addEventListener("change", () => patchTypeYamlScalar(key, control.value));
    } else if (spec.type === "boolean") {
      control = document.createElement("input");
      control.type = "checkbox";
      control.className = "type-meta-edit-checkbox";
      control.checked = value === true || value === "true";
      control.addEventListener("change", () =>
        patchTypeYamlScalar(key, control.checked ? "true" : "false")
      );
    } else {
      control = document.createElement("input");
      control.type = "text";
      control.className = "type-meta-edit-input";
      control.value = isList
        ? Array.isArray(value)
          ? value.join(", ")
          : String(value || "")
        : value != null
          ? String(value)
          : "";
      if (spec.placeholder) control.placeholder = String(spec.placeholder);
      control.addEventListener("change", () => {
        const raw = control.value.trim();
        if (isList) {
          const items = raw
            .replace(/^\[|\]$/g, "")
            .split(",")
            .map((s) => s.trim())
            .filter(Boolean);
          patchTypeYamlList(key, items);
        } else {
          patchTypeYamlScalar(key, raw);
        }
      });
    }

    const row = makeRow(label, control);
    row.classList.add("type-meta-domain-row");
    if (spec.description) row.title = String(spec.description).replace(/\s+/g, " ").trim();
    if (spec.required) row.classList.add("type-meta-required");
    domainWrap.appendChild(row);
  }

  // fields: top-level ключи типа-поля — widget (примитив) + storage.
  if (detail.domain === "fields") {
    const widgetSel = document.createElement("select");
    widgetSel.className = "type-meta-edit-select";
    for (const w of ["input", "textarea", "checkbox", "select", "select-multiple", "radio", "number", "date", "datetime", "color", "url", "file", "link", "nullable-input"]) {
      const opt = document.createElement("option");
      opt.value = w;
      opt.textContent = w;
      if (w === (schema.widget || mergedSchema.widget || "input")) opt.selected = true;
      widgetSel.appendChild(opt);
    }
    widgetSel.addEventListener("change", () => patchTypeYamlScalar("widget", widgetSel.value));
    const widgetRow = makeRow("Widget", widgetSel);
    widgetRow.classList.add("type-meta-domain-row");
    domainWrap.appendChild(widgetRow);

    const storageInput = document.createElement("input");
    storageInput.type = "text";
    storageInput.className = "type-meta-edit-input";
    storageInput.value = schema.storage != null ? String(schema.storage) : "";
    storageInput.placeholder = "string / boolean / number …";
    storageInput.addEventListener("change", () => patchTypeYamlScalar("storage", storageInput.value.trim()));
    const storageRow = makeRow("Storage", storageInput);
    storageRow.classList.add("type-meta-domain-row");
    domainWrap.appendChild(storageRow);
  }

  // md-blocks: кнопка бутстрапа JS-рендера (когда render: fence).
  if (detail.domain === "md-blocks") {
    const slug = detail.id?.split(".").pop() || "block";
    const renderMode = String(propValue("render") || "template");
    if (renderMode === "fence") {
      const jsBtn = document.createElement("button");
      jsBtn.type = "button";
      jsBtn.className = "type-add-field-btn";
      jsBtn.textContent = "Создать JS-рендер";
      jsBtn.title = "Записать стартовый файл рендера в awn-system/renderers/";
      jsBtn.addEventListener("click", () => {
        const rel = String(propValue("renderer") || `awn-system/renderers/${slug}.js`);
        void createStarterRenderer(rel, detail.name || slug);
      });
      domainWrap.appendChild(jsBtn);
    }
    const tplNote = document.createElement("p");
    tplNote.className = "agent-system-type-inspector-hint";
    tplNote.textContent =
      "template (что вставляется в редактор) правится в YAML ниже. Для fence сделайте template с ```<fence-tag>.";
    domainWrap.appendChild(tplNote);
  }

  if (detail.domain === "pages" || detail.domain === "content") {
    const slotsEditor = buildTypeStorageSlotsEditor(detail.storageSlots || []);
    domainWrap.appendChild(slotsEditor);
  }

  // Подзаголовок + секция появляются только если у типа есть доменные контролы.
  if (domainWrap.childElementCount) {
    const head = document.createElement("div");
    head.className = "type-meta-section-head";
    head.textContent = "Свойства типа";
    wrap.appendChild(head);
    wrap.appendChild(domainWrap);
  }

  return wrap;
}

function buildTypeAddFieldForm() {
  const wrap = document.createElement("div");
  wrap.className = "type-add-field-wrap";

  const toggleBtn = document.createElement("button");
  toggleBtn.type = "button";
  toggleBtn.className = "type-add-field-toggle";
  toggleBtn.textContent = "+ Добавить поле";

  const form = document.createElement("div");
  form.className = "type-add-field-form hidden";

  const keyInput = document.createElement("input");
  keyInput.type = "text";
  keyInput.className = "type-meta-edit-input";
  keyInput.placeholder = "ключ-поля";

  const typeSel = document.createElement("select");
  typeSel.className = "type-meta-edit-select";
  const registry = awnTypesCache?.fieldRegistry || {};
  const fieldIds = Object.keys(registry).length
    ? Object.keys(registry)
    : ["awn.field.string", "awn.field.text", "awn.field.relation.one", "awn.field.file.one"];
  for (const fid of fieldIds) {
    const opt = document.createElement("option");
    opt.value = fid;
    opt.textContent = registry[fid]?.name || fid;
    typeSel.appendChild(opt);
  }

  const titleInput = document.createElement("input");
  titleInput.type = "text";
  titleInput.className = "type-meta-edit-input";
  titleInput.placeholder = "Название поля";

  const addBtn = document.createElement("button");
  addBtn.type = "button";
  addBtn.className = "type-add-field-confirm";
  addBtn.textContent = "Добавить";

  addBtn.addEventListener("click", () => {
    const key = keyInput.value.trim();
    if (!key) { keyInput.focus(); return; }
    addTypeFieldToYaml(key, typeSel.value, titleInput.value.trim());
    keyInput.value = "";
    titleInput.value = "";
    form.classList.add("hidden");
    toggleBtn.textContent = "+ Добавить поле";
  });

  form.append(keyInput, typeSel, titleInput, addBtn);

  toggleBtn.addEventListener("click", () => {
    const hidden = form.classList.toggle("hidden");
    toggleBtn.textContent = hidden ? "+ Добавить поле" : "✕ Отмена";
  });

  wrap.append(toggleBtn, form);
  return wrap;
}
