function renderAgentSystemTypeInspector(detail) {
  if (!agentSystemTypeInspectorNode || !detail) {
    clearAgentSystemTypeInspector();
    return;
  }

  agentSystemTypeInspectorNode.replaceChildren();
  agentSystemTypeInspectorNode.classList.remove("hidden");

  const panel = document.createElement("div");
  panel.className = "agent-system-type-inspector-panel";

  const head = document.createElement("header");
  head.className = "agent-system-type-inspector-head";
  const idBadge = document.createElement("code");
  idBadge.className = "agent-system-type-inspector-id";
  idBadge.textContent = detail.id || "";
  head.appendChild(idBadge);

  if (Array.isArray(detail.inheritanceChain) && detail.inheritanceChain.length) {
    const chain = document.createElement("div");
    chain.className = "agent-system-type-chain";
    chain.appendChild(document.createTextNode("Наследование: "));
    detail.inheritanceChain.forEach((item, index) => {
      if (index > 0) {
        chain.appendChild(document.createTextNode(" → "));
      }
      if (item.catalogFile && item.id !== detail.id) {
        const link = document.createElement("button");
        link.type = "button";
        link.className = "agent-system-type-chain-link";
        link.textContent = item.name || item.id;
        link.title = item.id;
        link.addEventListener("click", () => {
          void selectAgentSystemFile(item.name || item.id, item.catalogFile);
        });
        chain.appendChild(link);
      } else {
        const span = document.createElement("span");
        span.className = "agent-system-type-chain-current";
        span.textContent = item.name || item.id;
        chain.appendChild(span);
      }
    });
    head.appendChild(chain);
  }

  panel.appendChild(head);

  // Индикатор: влияет ли тип на систему или это данные для агента.
  if (detail.usage) {
    const usage = detail.usage;
    const bar = document.createElement("div");
    bar.className = `agent-system-type-usage ${usage.wired ? "is-wired" : "is-data"}`;
    const icon = document.createElement("span");
    icon.className = "agent-system-type-usage-icon";
    icon.textContent = usage.wired ? "✓" : "○";
    const text = document.createElement("span");
    text.className = "agent-system-type-usage-text";
    if (usage.wired && Array.isArray(usage.consumers) && usage.consumers.length) {
      text.innerHTML =
        `<strong>Влияет:</strong> ${usage.consumers.map((c) => escapeHtml(c)).join(", ")}`;
    } else {
      text.innerHTML = `<strong>Не влияет.</strong> ${escapeHtml(
        usage.note || "данные для агента"
      )}`;
    }
    bar.append(icon, text);
    panel.appendChild(bar);
  }

  // Editable metadata form
  panel.appendChild(buildTypeMetaEditForm(detail));

  if (Array.isArray(detail.storageSlots) && detail.storageSlots.length) {
    const slots = document.createElement("p");
    slots.className = "agent-system-type-inspector-line";
    slots.innerHTML = `Слоты: <code>${detail.storageSlots.join("</code>, <code>")}</code>`;
    panel.appendChild(slots);
  }

  const hint = document.createElement("p");
  hint.className = "agent-system-type-inspector-hint";
  hint.textContent =
    detail.ownFieldCount > 0
      ? "Собственные поля помечены «этот тип». Унаследованные открываются по клику на источник."
      : "Нет собственных полей — набор задаётся родителем. Добавьте поле кнопкой ниже или через YAML.";
  panel.appendChild(hint);

  const mergedFields = detail.mergedFields && typeof detail.mergedFields === "object" ? detail.mergedFields : {};
  const ownFields = detail.ownFields && typeof detail.ownFields === "object" ? detail.ownFields : {};
  const inheritedFields =
    detail.inheritedFields && typeof detail.inheritedFields === "object" ? detail.inheritedFields : {};
  const fieldKeys = Object.keys(mergedFields);

  if (fieldKeys.length) {
    const tableWrap = document.createElement("div");
    tableWrap.className = "agent-system-type-fields-wrap";
    const table = document.createElement("table");
    table.className = "node-overview-meta-table agent-system-type-fields-table";
    const thead = document.createElement("thead");
    thead.innerHTML =
      "<tr><th>Поле</th><th>Тип</th><th>Название</th><th>Источник</th><th>Флаги</th><th></th></tr>";
    table.appendChild(thead);
    const tbody = document.createElement("tbody");
    for (const fieldKey of fieldKeys.sort((a, b) => a.localeCompare(b, "ru"))) {
      const fieldDef = mergedFields[fieldKey];
      const row = document.createElement("tr");
      if (ownFields[fieldKey]) row.classList.add("is-own-field");

      const sourceCell = document.createElement("td");
      if (ownFields[fieldKey]) {
        sourceCell.textContent = "этот тип";
        sourceCell.classList.add("is-own");
      } else if (inheritedFields[fieldKey]?.fromType) {
        const fromType = inheritedFields[fieldKey].fromType;
        const fromEntry = (detail.inheritanceChain || []).find((item) => item.id === fromType);
        if (fromEntry?.catalogFile) {
          const link = document.createElement("button");
          link.type = "button";
          link.className = "agent-system-type-source-link";
          link.textContent = fromEntry.name || fromType;
          link.title = fromType;
          link.addEventListener("click", () => {
            void selectAgentSystemFile(fromEntry.name || fromType, fromEntry.catalogFile);
          });
          sourceCell.appendChild(link);
        } else {
          sourceCell.innerHTML = `<code>${fromType}</code>`;
        }
      } else {
        sourceCell.textContent = "—";
      }

      const keyCell = document.createElement("td");
      keyCell.innerHTML = `<code>${fieldKey}</code>`;
      const typeCell = document.createElement("td");
      typeCell.innerHTML = `<code>${fieldDef?.type || "—"}</code>`;
      const titleCell = document.createElement("td");
      titleCell.textContent = fieldDef?.title || fieldDef?.name || fieldDef?.description || "—";

      row.append(keyCell, typeCell, titleCell, sourceCell);
      const flagsCell = document.createElement("td");
      flagsCell.appendChild(createAwnTypeFieldFlags(fieldDef));
      row.appendChild(flagsCell);
      const actCell = document.createElement("td");
      actCell.className = "agent-system-type-field-actions";
      if (ownFields[fieldKey]) {
        const delBtn = document.createElement("button");
        delBtn.type = "button";
        delBtn.className = "type-field-delete-btn";
        delBtn.textContent = "×";
        delBtn.title = `Удалить поле ${fieldKey}`;
        delBtn.addEventListener("click", () => {
          if (!confirm(`Удалить поле «${fieldKey}» из типа?`)) return;
          deleteTypeFieldFromYaml(fieldKey);
          row.remove();
        });
        actCell.appendChild(delBtn);
      }
      row.appendChild(actCell);
      tbody.appendChild(row);
    }
    table.appendChild(tbody);
    tableWrap.appendChild(table);
    panel.appendChild(tableWrap);
  } else {
    const empty = document.createElement("p");
    empty.className = "agent-system-type-inspector-empty";
    empty.textContent = "Нет полей в цепочке наследования.";
    panel.appendChild(empty);
  }

  // Add field button
  panel.appendChild(buildTypeAddFieldForm());

  const yamlToggleBtn = document.createElement("button");
  yamlToggleBtn.type = "button";
  yamlToggleBtn.className = "agent-system-type-yaml-toggle";
  yamlToggleBtn.textContent = "Показать YAML";
  yamlToggleBtn.title = "Показать / скрыть исходный YAML для ручного редактирования";
  yamlToggleBtn.addEventListener("click", () => {
    const isHiding = toggleTypeYamlVisibility();
    yamlToggleBtn.textContent = appRootNode.classList.contains("is-agent-type-form-mode")
      ? "Показать YAML"
      : "Скрыть YAML";
  });
  panel.appendChild(yamlToggleBtn);

  agentSystemTypeInspectorNode.appendChild(panel);
}

async function selectAgentSystemFile(label, filePath, options = {}) {
  const normalizedPath = normalizeMenuNodePath(filePath);
  if (!isAgentSystemEditableFilePath(normalizedPath)) {
    await openNodeFromMenu(label, filePath, options);
    return;
  }

  hideHomeView();
  nodeOverviewRenderSeq += 1;
  clearActiveSystemFile();
  activePath = normalizedPath;
  activeLabel = label || getLabelFromPath(normalizedPath);
  activeExternalFilePath = null;
  nodeSettingsViewActive = false;
  nodeMemoryViewActive = false;
  clearMediaSidecarEditor();
  updateActiveButton();
  setLoading("Загрузка типа...");
  setPropsYamlContent("");
  applyContentModeState("description");

  try {
    const [fileResponse, typeDetail] = await Promise.all([
      fetch(buildApiUrl("/api/agent-system/file", { path: normalizedPath })),
      loadAgentSystemTypeDetail(normalizedPath).catch(() => null)
    ]);
    if (!fileResponse.ok) throw new Error(`Request failed with ${fileResponse.status}`);
    const data = await fileResponse.json();
    fileContentInputNode.value = data.content || "";
    renderAgentSystemTypeInspector(typeDetail);
    applyModeUi();
    // Hide raw YAML by default when a type has a parsed form
    appRootNode.classList.toggle("is-agent-type-form-mode", Boolean(typeDetail));
    refreshEditorViewContent();
    commitEditorSaveBaseline();
  } catch (error) {
    fileContentInputNode.value = `Ошибка чтения файла: ${error.message}`;
    appRootNode.classList.remove("is-agent-type-form-mode");
    applyModeUi();
    commitEditorSaveBaseline();
  } finally {
    hideContentLoading({ force: true });
    if (!options.skipRouteSync) {
      syncAppRouteToUrl({ replace: true });
    } else {
      scheduleActivePageContextSync();
    }
  }
}

async function selectFile(label, filePath) {
  if (isGitRepoLooseFilePath(filePath)) {
    await selectRepoLooseFile(label, filePath);
    return;
  }
  clearActiveWorkspaceTocView();
  if (!filePath) {
    fileContentInputNode.value = "Ошибка чтения файла: пустой путь";
    return;
  }

  hideHomeView();
  clearActiveSystemFile();
  if (!isNodeSettingsTargetPath(filePath)) {
    nodeSettingsViewActive = false;
    nodeMemoryViewActive = false;
  }
  const nextPath = getResolvedNodePath(filePath);
  if (normalizeMenuNodePath(nextPath) !== normalizeMenuNodePath(activePath)) {
    lastNonTocEntryOverviewContext = null;
    activeDataStorageAllItems = false;
    invalidateStorageRootScanCache();
  }
  activePath = nextPath;
  activeLabel = label;
  hideLiveFileUpdateBanner();
  hideLiveFileDiffPanel();
  clearLiveSyncInlineDiffState();
  liveSyncPendingChange = null;
  liveSyncMtimeBaselineReady = false;
  liveSyncMtimeByPath = new Map();
  activeFolderBrowsePath = null;
  activeFolderBrowseFilePath = null;
  folderBrowseExpandedPagePath = null;
  resetPropsLibrariesCache();
  activeExternalFilePath = null;
  activeExternalSectionFolder = null;
  activeMediaSectionFolder = null;
  for (const mode of FLAT_STORAGE_SECTION_MODES) {
    activeFlatStorageSectionFolder[mode] = null;
  }
  nodeOverviewRenderSeq += 1;
  clearMediaSidecarEditor();
  updateActiveButton();
  titleInputNode.value = label;
  const showFileLoadingOverlay = !isAsyncOverviewRenderMode();
  if (showFileLoadingOverlay) {
    showContentLoading({ variant: "default", message: "Загрузка файла…" });
  }
  fileContentInputNode.value = "";
  refreshEditorViewContent();

  try {
    navPerfMark("selectFile:start", activeContentMode);
    const apiPath = getResolvedNodePath(filePath);
    const deferOverviewSideLoads = isAsyncOverviewRenderMode(activeContentMode);
    let fileContent = "";
    if (isAwnDatabaseRecordContentPath(apiPath)) {
      fileContent = await fetchAwnDatabaseRecordEditorContent(apiPath);
      if (/\.csv$/i.test(apiPath)) {
        editorViewMode = "source";
      }
    } else {
      const [loadedContent] = await Promise.all([
        (async () => {
          const response = await fetch(buildApiUrl("/api/file", { path: apiPath }));
          if (!response.ok) throw new Error(`Request failed with ${response.status}`);
          const data = await response.json();
          return data.content;
        })(),
        loadPropertiesForActivePath()
      ]);
      fileContent = loadedContent;
      navPerfMark("selectFile:file+properties");
    }
    modeContentCache.description = fileContent;
    navigationManifestCachedPath = getActiveNodeApiPath();
    modeContentCache.internal = "";
    modeContentCache.external = "";
    modeContentCache.inbox = "";
    modeContentCache.note = "";
    modeContentCache["quick-notes"] = "";
    modeContentCache.references = "";
    modeContentCache.artefacts = "";
    modeContentCache.assets = "";
    modeContentCache.repository = "";
    modeContentCache.media = "";
    modeContentCache.configs = "";
    modeContentCache.env = "";
    modeContentCache.scripts = "";
    modeContentCache.todo = "";
    if (isAwnDatabaseRecordContentPath(apiPath)) {
      await loadPropertiesForActivePath();
      navPerfMark("selectFile:properties");
    }
    if (isNodeMdPath(activePath) && !deferOverviewSideLoads) {
      try {
        await loadNodeConfig(activePath);
      } catch {
        invalidateNodeConfigCache(activePath);
      }
    }
    if (
      !deferOverviewSideLoads &&
      isTopicSchemaModeAvailable(activePath) &&
      activeContentMode !== "topic-schema"
    ) {
      try {
        await loadTopicSchemaForManifest(activePath);
      } catch {
        const manifestPath = getTopicSchemaManifestPath(activePath);
        if (manifestPath) invalidateTopicSchemaCacheForManifest(manifestPath);
      }
    }
    applyNodeManifestBody(modeContentCache.description || "");
    await loadContentByMode({
      skipPropertiesFetch: deferOverviewSideLoads
    });
    navPerfMark("selectFile:loadContentByMode");
    syncTitleFieldsFromNode(activePath);
    applyNodeWorkspaceViewUi();
  } catch (error) {
    fileContentInputNode.value = `Ошибка чтения файла: ${error.message}`;
    hideContentLoading({ force: true });
  } finally {
    if (showFileLoadingOverlay) {
      hideContentLoading();
    }
    scheduleActivePageContextSync();
  }
}

async function resolveFlatStorageSectionFolderName(mode) {
  const normalizedMode =
    mode === "quick-notes" ? "notes" : mode === "note" ? "notes" : mode;
  const primary = getFlatStorageSectionFolderName(normalizedMode);
  if (normalizedMode !== "notes") return primary;
  const manifestPath = getActiveNodeApiPath();
  if (!manifestPath) return primary;
  for (const folder of getStorageFolderNamesForSlotKey("notes")) {
    const summary = await fetchFolderViewSummary(manifestPath, folder);
    if (summary.exists) return folder;
  }
  return primary;
}

async function loadFlatStorageSectionContent(mode, preserveSectionFolder = null) {
  const resolvedMode = mode === "quick-notes" ? "note" : mode;
  const folder = await resolveFlatStorageSectionFolderName(resolvedMode);
  if (!folder) return;
  const response = await fetch(
    buildApiUrl("/api/folder/view", { path: getActiveNodeApiPath(), folder })
  );
  if (!response.ok) throw new Error(`Request failed with ${response.status}`);
  const data = await response.json();
  applyFlatStorageFolderLoadState(resolvedMode, data);
  const sectionToRestore =
    preserveSectionFolder ||
    activeFlatStorageSectionFolder[resolvedMode] ||
    activeFlatStorageSectionFolder[mode] ||
    getActiveFlatStorageSectionParentForCreate(resolvedMode);
  if (sectionToRestore) {
    activeFlatStorageSectionFolder[resolvedMode] = String(sectionToRestore).replace(/\\/g, "/").replace(/\/$/, "");
    pruneActiveFlatStorageSectionFolder(resolvedMode);
  }
  applyModeUi();
  renderListViewContent();
  renderPreviewFromEditor();
}

async function loadContentByMode(options = {}) {
  if (!activePath) return;
  const forceReload = Boolean(options.forceReload);
  const skipPropertiesFetch = Boolean(options.skipPropertiesFetch);
  const preserveMediaSectionFolder = options.preserveMediaSectionFolder || null;
  const preserveExternalSectionFolder = options.preserveExternalSectionFolder || null;
  const preserveFlatStorageSectionFolder = options.preserveFlatStorageSectionFolder || null;

  if (activeContentMode === "node-preview") {
    activeContentMode = "description";
    setDocAsideTab("props");
    syncDocAsideUi(getDocAsideTabAvailability());
  }

  const deferLoadingEnd = isAsyncOverviewRenderMode();
  if (!deferLoadingEnd) {
    showContentLoading({
      variant: contentLoadingVariantForMode(),
      message: "Загрузка…"
    });
  }

  try {
  if (activeContentMode !== "external") {
    activeExternalFilePath = null;
  }

  if (activeContentMode === NODE_OVERVIEW_MODE) {
    if (forceReload || !modeContentCache.description) {
      const response = await fetch(buildApiUrl("/api/file", { path: getActiveNodeApiPath() }));
      if (!response.ok) throw new Error(`Request failed with ${response.status}`);
      const data = await response.json();
      modeContentCache.description = data.content || "";
      navigationManifestCachedPath = getActiveNodeApiPath();
      rememberLiveSyncLoadedSnapshot(getActiveNodeApiPath(), modeContentCache.description);
    }
    if (!skipPropertiesFetch) {
      await loadPropertiesForActivePath();
    }
    applyNodeManifestBody(modeContentCache.description || "");
    fileContentInputNode.value = "";
    if (isRepositoryWorkspacePath()) {
      applyModeUi({ skipAsyncRender: true });
      await renderRepositoryNavigationPage();
    } else {
      applyModeUi();
    }
    updateBreadcrumbsForActiveMode();
    return;
  }

  if (activeContentMode === NODE_NAVIGATION_MODE) {
    if (forceReload || !getNodeDescriptionHasContent(modeContentCache.description)) {
      const response = await fetch(buildApiUrl("/api/file", { path: getActiveNodeApiPath() }));
      if (!response.ok) throw new Error(`Request failed with ${response.status}`);
      const data = await response.json();
      modeContentCache.description = data.content || "";
      navigationManifestCachedPath = getActiveNodeApiPath();
      rememberLiveSyncLoadedSnapshot(getActiveNodeApiPath(), modeContentCache.description);
    }
    fileContentInputNode.value = "";
    applyModeUi();
    updateBreadcrumbsForActiveMode();
    return;
  }

  if (activeContentMode === FOLDER_BROWSE_MODE) {
    fileContentInputNode.value = "";
    applyModeUi();
    updateBreadcrumbsForActiveMode();
    return;
  }

  if (activeContentMode === AWN_DATA_VIEW_MODE) {
    fileContentInputNode.value = "";
    applyModeUi();
    updateBreadcrumbsForActiveMode();
    return;
  }

  if (activeContentMode === NODE_ENTRY_OVERVIEW_MODE) {
    fileContentInputNode.value = "";
    // Keep shell/mode UI in sync, then await overview so refresh doesn't race an empty props state.
    applyModeUi({ skipAsyncRender: true });
    await renderEntryOverview();
    updateBreadcrumbsForActiveMode();
    return;
  }

  if (activeContentMode === NODE_DISCUSSION_MODE) {
    fileContentInputNode.value = "";
    void renderNodeThread();
    updateBreadcrumbsForActiveMode();
    return;
  }

  if (activeContentMode === NODE_JOURNAL_MODE) {
    fileContentInputNode.value = "";
    void renderNodeJournal();
    updateBreadcrumbsForActiveMode();
    return;
  }

  if (activeContentMode === NODE_MINDMAP_MODE) {
    fileContentInputNode.value = "";
    applyModeUi();
    updateBreadcrumbsForActiveMode();
    return;
  }

  if (activeContentMode === "description") {
    if (forceReload || !modeContentCache.description) {
      const apiPath = getActiveNodeApiPath();
      if (isAwnDatabaseRecordContentPath(apiPath)) {
        modeContentCache.description = await fetchAwnDatabaseRecordEditorContent(apiPath);
      } else {
        const response = await fetch(buildApiUrl("/api/file", { path: apiPath }));
        if (!response.ok) throw new Error(`Request failed with ${response.status}`);
        const data = await response.json();
        modeContentCache.description = data.content || "";
      }
      rememberLiveSyncLoadedSnapshot(getActiveNodeApiPath(), modeContentCache.description);
    }
    await loadPropertiesForActivePath();
    applyNodeManifestBody(modeContentCache.description || "");
    syncTitleFieldsFromNode(activePath);
    applyModeUi();
    refreshEditorViewContent();
    updateBreadcrumbsForActiveMode();
    return;
  }

  if (activeContentMode === "internal") {
    if (isGitRepoLooseMdEditing()) {
      fileContentInputNode.value = modeContentCache.internal || fileContentInputNode.value || "";
      applyModeUi();
      refreshEditorViewContent();
      updateBreadcrumbsForActiveMode();
      return;
    }
    try {
      const response = await fetch(buildApiUrl("/api/memory/internal", { path: getActiveNodeApiPath() }));
      if (!response.ok) throw new Error(`Request failed with ${response.status}`);
      const data = await response.json();
      modeContentCache.internal = data.content || "";
      fileContentInputNode.value = modeContentCache.internal;
      applyModeUi();
      refreshEditorViewContent();
      if (isDataHubBundleEditorMode("internal")) activateDataHubBundleEditorUi("internal");
    } catch (error) {
      fileContentInputNode.value = `Ошибка чтения краткой памяти: ${error.message}`;
      fileContentInputNode.readOnly = true;
    }
    updateBreadcrumbsForActiveMode();
    return;
  }

  if (activeContentMode === "tabular") {
    const preserveTabularSource = Boolean(options.preserveTabularSource && isTabularSourceEditing());
    try {
      const response = await fetch(buildApiUrl("/api/memory/tabular", { path: getActiveNodeApiPath() }));
      if (!response.ok) throw new Error(`Request failed with ${response.status}`);
      const data = await response.json();
      modeContentCache.tabular = data.content || "";
      tabularDataCache = {
        columns: Array.isArray(data.columns) ? data.columns : [],
        rows: Array.isArray(data.rows) ? data.rows : [],
        rowCount: data.rowCount || 0
      };
      fileContentInputNode.value = data.content || "";
      if (!preserveTabularSource) {
        editorViewMode = "preview";
      }
      applyModeUi();
      if (preserveTabularSource) {
        refreshEditorViewContent();
      } else {
        renderListViewContent();
      }
    } catch (error) {
      fileContentInputNode.value = `Ошибка чтения табличной памяти: ${error.message}`;
      fileContentInputNode.readOnly = true;
    }
    updateBreadcrumbsForActiveMode();
    return;
  }

  if (activeContentMode === "external") {
    try {
      const exists = await refreshExternalMemoryCaches();
      const targetFile = String(options.openExternalFile || "")
        .replace(/\\/g, "/")
        .trim();
      if (targetFile) {
        const parentFolder = targetFile.includes("/")
          ? targetFile.split("/").filter(Boolean).slice(0, -1).join("/")
          : null;
        if (parentFolder) {
          activeExternalSectionFolder = parentFolder;
          pruneActiveExternalSectionFolder();
        }
        fileContentInputNode.value = exists ? modeContentCache.external : "Папка не найдена";
        await openExternalFile(targetFile, { skipRouteSync: true });
        syncAppRouteToUrl({ replace: true });
        updateBreadcrumbsForActiveMode();
        return;
      }
      fileContentInputNode.value = exists ? modeContentCache.external : "Папка не найдена";
      activeExternalFilePath = null;
      const sectionToRestore =
        preserveExternalSectionFolder ||
        activeExternalSectionFolder ||
        getActiveExternalSectionParentForCreate();
      if (sectionToRestore) {
        activeExternalSectionFolder = String(sectionToRestore).replace(/\\/g, "/").replace(/\/$/, "");
        pruneActiveExternalSectionFolder();
      }
      applyModeUi();
      renderListViewContent();
      renderPreviewFromEditor();
    } catch (error) {
      fileContentInputNode.value = `Ошибка чтения произвольной памяти: ${error.message}`;
      fileContentInputNode.readOnly = true;
    }
    updateBreadcrumbsForActiveMode();
    return;
  }

  if (activeContentMode === "inbox") {
    try {
      await loadInboxSectionContent(
        activeContentMode === "inbox" ? preserveFlatStorageSectionFolder : null
      );
    } catch (error) {
      fileContentInputNode.value = `Ошибка чтения входящих: ${error.message}`;
      renderListViewContent();
      fileContentInputNode.readOnly = true;
    }
    updateBreadcrumbsForActiveMode();
    return;
  }

  if (activeContentMode === "note" || activeContentMode === "quick-notes") {
    try {
      await loadFlatStorageSectionContent(
        "note",
        activeContentMode === "note" || activeContentMode === "quick-notes"
          ? preserveFlatStorageSectionFolder
          : null
      );
    } catch (error) {
      fileContentInputNode.value = `Ошибка чтения заметок: ${error.message}`;
      renderListViewContent();
      fileContentInputNode.readOnly = true;
    }
    updateBreadcrumbsForActiveMode();
    return;
  }

  if (activeContentMode === "references") {
    try {
      await loadFlatStorageSectionContent(
        "references",
        activeContentMode === "references" ? preserveFlatStorageSectionFolder : null
      );
    } catch (error) {
      fileContentInputNode.value = `Ошибка чтения источников: ${error.message}`;
      renderListViewContent();
      fileContentInputNode.readOnly = true;
    }
    updateBreadcrumbsForActiveMode();
    return;
  }

  if (isMediaLibraryContentMode()) {
    clearMediaSidecarEditor();
    fileContentInputNode.value = "";
    const sectionToRestore =
      preserveMediaSectionFolder || activeMediaSectionFolder || getActiveMediaSectionParentForCreate();
    const mode = activeContentMode;
    try {
      const response = await fetch(
        buildApiUrl("/api/media", buildMediaLibraryApiParams({ path: getActiveNodeApiPath() }, mode))
      );
      if (!response.ok) throw new Error(`Request failed with ${response.status}`);
      const data = await response.json();
      mediaAssetsExists = Boolean(data.exists);
      modeContentCache[mode] = data.content || "";
      syncMediaFilesCache(data.content, data.groups, data.sectionManifests);
      if (sectionToRestore) {
        activeMediaSectionFolder = String(sectionToRestore).replace(/\\/g, "/").replace(/\/$/, "");
        pruneActiveMediaSectionFolder();
      }
      const storedView = loadStoredMediaViewMode();
      if (storedView) {
        mediaViewMode = storedView;
      } else if (activeMediaSectionFolder && mediaViewMode === "dashboard") {
        mediaViewMode = "all";
      }
      if (mediaViewSelectNode) mediaViewSelectNode.value = getEffectiveMediaViewMode();
      applyModeUi();
      renderListViewContent();
    } catch (error) {
      mediaAssetsExists = true;
      modeContentCache[mode] = "";
      syncMediaFilesCache("", {}, []);
      applyModeUi();
      listViewContentNode.innerHTML = "";
      renderMediaEmpty(
        listViewContentNode,
        `Ошибка чтения ${getMediaLibraryModeLabel(mode).toLowerCase()}: ${error.message}`
      );
      showToast(
        `Ошибка чтения ${getMediaLibraryModeLabel(mode).toLowerCase()}: ${error.message}`,
        "error"
      );
    }
    updateBreadcrumbsForActiveMode();
    return;
  }

  if (activeContentMode === "graph") {
    fileContentInputNode.value = "";
    applyModeUi();
    updateBreadcrumbsForActiveMode();
    return;
  }

  if (activeContentMode === "configs") {
    try {
      await loadAwnTypes(activeWorkspaceId);
      const cache = await loadNodeSettingsForManifest(activePath, { force: true });
      modeContentCache.configs = buildNodeConfigYamlFromState(cache || {});
      fileContentInputNode.value = "";
      applyModeUi();
      renderNodeSettingsEditor(cache);
      commitEditorSaveBaseline();
    } catch (error) {
      if (nodeConfigFieldsNode) nodeConfigFieldsNode.replaceChildren();
      nodeConfigEmptyNode?.classList.remove("hidden");
      if (nodeConfigPanelNode) {
        const note = document.createElement("p");
        note.className = "node-config-error";
        note.textContent = `Ошибка чтения ${BUNDLE_CONFIG_FILE}: ${error.message}`;
        nodeConfigFieldsNode?.append(note);
      }
    }
    updateBreadcrumbsForActiveMode();
    return;
  }

  if (activeContentMode === "topic-schema") {
    try {
      await loadAwnTypes(activeWorkspaceId);
      if (isWorkspaceSchemaContext(activePath)) {
        topicSchemaActiveTarget = "workspace";
      } else if (isAreaSchemaContext(activePath)) {
        topicSchemaActiveTarget = "area";
      } else if (topicSchemaActiveTarget === "topic" || topicSchemaActiveTarget === "workspace" || topicSchemaActiveTarget === "area") {
        syncTopicSchemaActiveTargetToStorageSlot();
      }
      await loadTopicSchemaForManifest(activePath, {
        topicOnly: true,
        force: Boolean(options.forceReload)
      });
      fileContentInputNode.value = "";
      applyModeUi();
    } catch (error) {
      if (topicSchemaBaseFieldsNode) topicSchemaBaseFieldsNode.textContent = `Ошибка: ${error.message}`;
      topicSchemaFieldsNode?.replaceChildren();
      topicSchemaEmptyNode?.classList.remove("hidden");
      applyModeUi();
    }
    updateBreadcrumbsForActiveMode();
    return;
  }

  if (activeContentMode === "env") {
    try {
      const response = await fetch(buildApiUrl("/api/env", { path: getActiveNodeApiPath() }));
      if (!response.ok) throw new Error(`Request failed with ${response.status}`);
      const data = await response.json();
      modeContentCache.env = data.content || "";
      fileContentInputNode.value = modeContentCache.env;
      applyModeUi();
    } catch (error) {
      fileContentInputNode.value = `Ошибка чтения .env: ${error.message}`;
      fileContentInputNode.readOnly = true;
    }
    updateBreadcrumbsForActiveMode();
    return;
  }

  if (activeContentMode === "todo") {
    try {
      const response = await fetch(buildApiUrl("/api/todo", { path: getActiveNodeApiPath() }));
      if (!response.ok) throw new Error(`Request failed with ${response.status}`);
      const data = await response.json();
      modeContentCache.todo = data.content || "";
      fileContentInputNode.value = modeContentCache.todo;
      applyModeUi();
      refreshEditorViewContent();
      if (isDataHubBundleEditorMode("todo")) activateDataHubBundleEditorUi("todo");
    } catch (error) {
      fileContentInputNode.value = `Ошибка чтения TODO: ${error.message}`;
      fileContentInputNode.readOnly = true;
    }
    updateBreadcrumbsForActiveMode();
    return;
  }

  if (activeContentMode === "roadmap") {
    try {
      const response = await fetch(buildApiUrl("/api/roadmap", { path: getActiveNodeApiPath() }));
      if (!response.ok) throw new Error(`Request failed with ${response.status}`);
      const data = await response.json();
      modeContentCache.roadmap = data.content || "";
      fileContentInputNode.value = modeContentCache.roadmap;
      applyModeUi();
      refreshEditorViewContent();
      if (isDataHubBundleEditorMode("roadmap")) activateDataHubBundleEditorUi("roadmap");
    } catch (error) {
      fileContentInputNode.value = `Ошибка чтения дорожной карты: ${error.message}`;
      fileContentInputNode.readOnly = true;
    }
    updateBreadcrumbsForActiveMode();
    return;
  }

  if (activeContentMode === "artefacts") {
    try {
      await loadFlatStorageSectionContent(
        "artefacts",
        activeContentMode === "artefacts" ? preserveFlatStorageSectionFolder : null
      );
    } catch (error) {
      fileContentInputNode.value = `Ошибка чтения артефактов: ${error.message}`;
      renderListViewContent();
      fileContentInputNode.readOnly = true;
    }
    updateBreadcrumbsForActiveMode();
    return;
  }

  if (activeContentMode === "scripts") {
    try {
      await loadFlatStorageSectionContent(
        "scripts",
        activeContentMode === "scripts" ? preserveFlatStorageSectionFolder : null
      );
    } catch (error) {
      fileContentInputNode.value = `Ошибка чтения скриптов: ${error.message}`;
      fileContentInputNode.readOnly = true;
    }
    updateBreadcrumbsForActiveMode();
    return;
  }

  if (activeContentMode === "repository") {
    try {
      await loadFlatStorageSectionContent(
        "repository",
        activeContentMode === "repository" ? preserveFlatStorageSectionFolder : null
      );
    } catch (error) {
      fileContentInputNode.value = `Ошибка чтения репозитория: ${error.message}`;
      renderListViewContent();
      fileContentInputNode.readOnly = true;
    }
    updateBreadcrumbsForActiveMode();
    return;
  }

  if (activeContentMode === "temp") {
    try {
      const response = await fetch(
        buildApiUrl("/api/folder/view", { path: getActiveNodeApiPath(), folder: STORAGE_SUBFOLDER_TEMP })
      );
      if (!response.ok) throw new Error(`Request failed with ${response.status}`);
      const data = await response.json();
      applyFlatStorageFolderLoadState("temp", data);
      applyModeUi();
      renderListViewContent();
      renderPreviewFromEditor();
    } catch (error) {
      fileContentInputNode.value = `Ошибка чтения временных файлов: ${error.message}`;
      renderListViewContent();
      fileContentInputNode.readOnly = true;
    }
    updateBreadcrumbsForActiveMode();
    return;
  }
  } finally {
    if (!deferLoadingEnd) {
      hideContentLoading();
    }
    syncEditorLineNumbers();
    commitEditorSaveBaseline();
  }
}

function replaceActiveMenuLabel(newLabel, pathHint = activePath) {
  const normalizedHint = normalizeMenuNodePath(pathHint);
  const menu = menuCacheByAgent.get(activeWorkspaceId) || currentMenuData;
  if (menu && newLabel) {
    if (isAgentContainerRootIndexPath(normalizedHint) && menu.containerTree) {
      menu.containerTree.title = newLabel;
      menuCacheByAgent.set(activeWorkspaceId, menu);
      if (currentMenuData) currentMenuData.containerTree = menu.containerTree;
      patchContainerMenuAfterCreate(activeWorkspaceId);
      return;
    }
    if (isAgentSystemRootIndexPath(normalizedHint) && menu.serviceTree) {
      menu.serviceTree.title = newLabel;
      menuCacheByAgent.set(activeWorkspaceId, menu);
      if (currentMenuData) currentMenuData.serviceTree = menu.serviceTree;
      patchServiceMenuAfterCreate(activeWorkspaceId);
      return;
    }
  }

  const items = getMenuQueryRoot().querySelectorAll(".menu-item, .menu-folder");
  for (const item of items) {
    if (item.dataset.path === pathHint) {
      item.textContent = newLabel;
      break;
    }
  }
}

function patchTreePaths(oldPath, newPath) {
  const oldPrefix = `${oldPath.replace(/\/+$/, "")}/`;
  const newPrefix = `${newPath.replace(/\/+$/, "")}/`;
  const nodes = getMenuQueryRoot().querySelectorAll("[data-path]");
  for (const node of nodes) {
    const currentPath = node.dataset.path || "";
    if (currentPath === oldPath || currentPath.startsWith(oldPrefix)) {
      node.dataset.path = currentPath === oldPath ? newPath : `${newPrefix}${currentPath.slice(oldPrefix.length)}`;
    }
  }
}

function buildSaveContentPayload() {
  if (activeSystemFile) {
    return normalizeMarkdownInlineAssetRefs(fileContentInputNode.value || "");
  }
  const rawContent = isExternalFileEditing()
    ? buildExternalFileContent()
    : isFlatStorageFileEditing()
      ? buildFlatStorageFileContent()
      : isAttachmentSidecarEditing()
        ? buildAttachmentSidecarEditorContent()
      : isMediaMarkdownEditing()
      ? buildMediaMarkdownContent()
      : isMediaSidecarEditing()
        ? buildMediaSidecarContent()
        : isGitRepoLooseFilePath(activePath)
          ? getEditorContentValue()
          : activeContentMode === "description"
            ? buildNodeManifestContent()
            : getEditorContentValue();
  return typeof rawContent === "string" ? rawContent : String(rawContent ?? "");
}

async function saveContent() {
  if (!isEditorSaveTrackingActive()) return;
  if (editorViewMode === "wysiwyg") {
    syncSourceFromWysiwygEditor();
  }
  const deferDescriptionContentBuild = activeContentMode === "description";
  let content = deferDescriptionContentBuild ? "" : buildSaveContentPayload();

  if (activeSystemFile) {
    setSaveButtonsState(true, "Сохраняю...");
    let saveSucceeded = false;
    try {
      const response = await fetch(buildApiUrl("/api/system-file"), {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ name: activeSystemFile, content: fileContentInputNode.value })
      });
      if (!response.ok) {
        const errorData = await response.json().catch(() => ({}));
        const reason = errorData.error || `Request failed with ${response.status}`;
        const details = errorData.details ? `: ${errorData.details}` : "";
        throw new Error(`${reason}${details}`);
      }
      await loadSystemFiles({
        refreshNotePreview: activeSystemFile === ROOT_SYSTEM_NOTE_FILE
      });
      saveSucceeded = true;
      showToast("Сохранено", "success");
    } catch (error) {
      showToast(`Ошибка сохранения: ${error.message}`, "error");
    } finally {
      setSaveButtonsState(false);
      if (saveSucceeded) commitEditorSaveBaseline();
    }
    return;
  }

  if (isAgentSystemFileEditing()) {
    if (deferDescriptionContentBuild) {
      content = getEditorContentValue();
    }
    setSaveButtonsState(true, "Сохраняю...");
    let saveSucceeded = false;
    try {
      const response = await fetch(buildApiUrl("/api/agent-system/file"), {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ path: getActiveNodeApiPath(), content })
      });
      if (!response.ok) {
        const errorData = await response.json().catch(() => ({}));
        const reason = errorData.error || `Request failed with ${response.status}`;
        const details = errorData.details ? `: ${errorData.details}` : "";
        throw new Error(`${reason}${details}`);
      }
      invalidateTypeCatalogCache(activeWorkspaceId);
      const [detail] = await Promise.all([
        loadAgentSystemTypeDetail(getActiveNodeApiPath()).catch(() => null),
        loadAwnTypes(activeWorkspaceId).catch(() => null)
      ]);
      renderAgentSystemTypeInspector(detail);
      saveSucceeded = true;
      showToast("Тип сохранён", "success");
    } catch (error) {
      showToast(`Ошибка сохранения: ${error.message}`, "error");
    } finally {
      setSaveButtonsState(false);
      if (saveSucceeded) commitEditorSaveBaseline();
    }
    return;
  }

  if (isGitRepoLooseFilePath(activePath)) {
    if (deferDescriptionContentBuild) {
      content = getEditorContentValue();
    }
    setSaveButtonsState(true, "Сохраняю...");
    let saveSucceeded = false;
    try {
      const response = await fetch(buildApiUrl("/api/repo-loose-file"), {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ path: getActiveNodeApiPath(), content })
      });
      if (!response.ok) {
        const errorData = await response.json().catch(() => ({}));
        const reason = errorData.error || `Request failed with ${response.status}`;
        const details = errorData.details ? `: ${errorData.details}` : "";
        throw new Error(`${reason}${details}`);
      }
      if (isGitRepoLooseMdEditing()) {
        modeContentCache.internal = content;
      }
      saveSucceeded = true;
      showToast("Сохранено", "success");
    } catch (error) {
      showToast(`Ошибка сохранения: ${error.message}`, "error");
    } finally {
      setSaveButtonsState(false);
      if (saveSucceeded) commitEditorSaveBaseline();
    }
    return;
  }

  if (activeContentMode === PROJECT_SETTINGS_MODE) {
    await saveProjectSettingsFormContent();
    return;
  }

  if (!activePath) return;

  if (isAwnDatabaseRecordContentPath(getActiveNodeApiPath())) {
    if (deferDescriptionContentBuild) {
      content = buildSaveContentPayload();
    }
    setSaveButtonsState(true, "Сохраняю...");
    let saveSucceeded = false;
    try {
      const response = await fetch(buildApiUrl("/api/workspace/fs/write"), {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ path: getActiveNodeApiPath(), content })
      });
      if (!response.ok) {
        const errorData = await response.json().catch(() => ({}));
        const reason = errorData.error || `Request failed with ${response.status}`;
        const details = errorData.details ? `: ${errorData.details}` : "";
        throw new Error(`${reason}${details}`);
      }
      modeContentCache.description = content;
      saveSucceeded = true;
      showToast("Сохранено", "success");
    } catch (error) {
      showToast(`Ошибка сохранения: ${error.message}`, "error");
    } finally {
      setSaveButtonsState(false);
      if (saveSucceeded) commitEditorSaveBaseline();
    }
    return;
  }

  if (activeContentMode === "configs") {
    setSaveButtonsState(true, "Сохраняю...");
    let saveSucceeded = false;
    try {
      await saveNodeSettingsContent();
      saveSucceeded = true;
      showToast(`Конфигурация сохранена в ${BUNDLE_CONFIG_FILE}`, "success");
    } catch (error) {
      showToast(`Ошибка сохранения: ${error.message}`, "error");
    } finally {
      setSaveButtonsState(false);
      if (saveSucceeded) commitEditorSaveBaseline();
    }
    return;
  }

  if (activeContentMode === "topic-schema") {
    setSaveButtonsState(true, "Сохраняю...");
    let saveSucceeded = false;
    try {
      await saveTopicSchemaContent();
      saveSucceeded = true;
      showToast(`Схема полей сохранена в ${SCHEMA_MOD_FILE}`, "success");
    } catch (error) {
      showToast(`Ошибка сохранения: ${error.message}`, "error");
    } finally {
      setSaveButtonsState(false);
      if (saveSucceeded) commitEditorSaveBaseline();
    }
    return;
  }

  const nextTitle = titleInputNode.value.trim();
  const manifestSlug = getNodeSlugFromPath(activePath);
  const previousRawAwnName = getAwnNameRawForNode(activePath);
  const nextStoredAwnName = normalizeAwnNameForStorage(nextTitle, manifestSlug);
  const displayNameChanged =
    activeContentMode === "description" &&
    nextStoredAwnName !== previousRawAwnName &&
    !isPartNodePath(activePath) &&
    (!isAgentRootIndexPath(activePath) || isReservedRootManifestPath(activePath));
  const nextSlug = getTitleSlugInputValue();
  const shouldRenameSlug =
    activeContentMode === "description" &&
    isTitleSlugRenameSupported(activePath) &&
    shouldRenameByTitleSlugInput(manifestSlug, nextSlug);
  const currentExternalSlug = activeExternalFilePath ? getNodeSlugFromPath(activeExternalFilePath) : "";
  const currentMediaSidecarSlug = activeMediaSidecarSourcePath
    ? getMediaFileSlugFromPath(activeMediaSidecarSourcePath)
    : "";
  const shouldRenameExternal =
    activeContentMode === "external" &&
    activeExternalFilePath &&
    isTitleSlugRenameSupported(activeExternalFilePath) &&
    shouldRenameByTitleSlugInput(currentExternalSlug, nextSlug);
  const currentFlatStorageSlug = activeFlatStorageFilePath
    ? getNodeSlugFromPath(activeFlatStorageFilePath)
    : "";
  const shouldRenameFlatStorage =
    isFlatStorageFileEditing() &&
    isTitleSlugRenameSupported(activeFlatStorageFilePath) &&
    shouldRenameByTitleSlugInput(currentFlatStorageSlug, nextSlug);
  const shouldRenameMediaSidecar =
    isMediaLibraryContentMode() &&
    activeMediaSidecarPath &&
    isTitleSlugRenameSupported(activeMediaSidecarSourcePath) &&
    shouldRenameByTitleSlugInput(currentMediaSidecarSlug, nextSlug);
  const currentMediaMarkdownSlug = activeMediaMarkdownPath
    ? getNodeSlugFromPath(activeMediaMarkdownPath)
    : "";
  const shouldRenameMediaMarkdown =
    isMediaLibraryContentMode() &&
    activeMediaMarkdownPath &&
    isTitleSlugRenameSupported(activeMediaMarkdownPath) &&
    shouldRenameByTitleSlugInput(currentMediaMarkdownSlug, nextSlug);

  setSaveButtonsState(true, "Сохраняю...");
  let saveSucceeded = false;

  try {
    if (shouldRenameSlug) {
      const renameResponse = await fetch(buildApiUrl("/api/file/title"), {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ path: getActiveNodeApiPath(), title: nextSlug })
      });

      if (!renameResponse.ok) {
        const errorData = await renameResponse.json().catch(() => ({}));
        const reason = errorData.error || `Request failed with ${renameResponse.status}`;
        const details = errorData.details ? `: ${errorData.details}` : "";
        throw new Error(`Ошибка переименования slug: ${reason}${details}`);
      }

      const renameData = await renameResponse.json();
      const pendingTitleBarEdits = captureTitleBarPendingEdits();
      if (activeContentMode === "description" && typeof renameData.content === "string") {
        modeContentCache.description = renameData.content;
        applyNodeManifestBody(renameData.content);
      }
      const oldPath = activePath;
      activePath = renameData.path;
      restoreTitleBarAfterSlugRename(renameData.path, pendingTitleBarEdits);
      activeLabel = resolveNodeDisplayName(nextStoredAwnName, getNodeSlugFromPath(activePath));
      updateBreadcrumbsForActiveMode();

      const currentNode = getMenuQueryRoot().querySelector(`[data-path="${CSS.escape(oldPath)}"]`);
      if (currentNode) currentNode.dataset.path = renameData.path;

      if (isNodeManifestPath(oldPath) && isNodeManifestPath(renameData.path) && !isPartNodePath(oldPath)) {
        const oldFolderPath = getFolderPathFromManifest(oldPath);
        const newFolderPath = getFolderPathFromManifest(renameData.path);
        patchTreePaths(oldFolderPath, newFolderPath);
      } else if (isTopicManifestPath(oldPath)) {
        patchTreePaths(oldPath, renameData.path);
      }

      try {
        await refreshMenu({ agentId: activeWorkspaceId });
      } catch {
        // menu will resync on next open
      }
      updateActiveButton();
      syncAppRouteToUrl({ replace: true });
      notifyMarkdownLinkRewrite(renameData.linkRewrite);
    }

    if (deferDescriptionContentBuild) {
      content = buildSaveContentPayload();
    }

    if (shouldRenameExternal) {
      const oldExternalFile = activeExternalFilePath;
      const renameResponse = await fetch(buildApiUrl("/api/external/file/rename"), {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ path: getActiveNodeApiPath(), file: activeExternalFilePath, title: nextSlug })
      });
      if (!renameResponse.ok) {
        const errorData = await renameResponse.json().catch(() => ({}));
        const reason = errorData.error || `Request failed with ${renameResponse.status}`;
        const details = errorData.details ? `: ${errorData.details}` : "";
        throw new Error(`Ошибка переименования файла ${STORAGE_SUBFOLDER_CONTENT}: ${reason}${details}`);
      }
      const renameData = await renameResponse.json();
      activeExternalFilePath = renameData.file;
      patchEntryOverviewContextsAfterStorageFileRename(
        oldExternalFile,
        renameData.file,
        "external",
        nextStoredAwnName || nextSlug
      );
      updateBreadcrumbsForActiveMode();
      const pendingTitleBarEdits = captureTitleBarPendingEdits();
      await applyExternalFileContentUi(renameData.content || "");
      restoreTitleBarAfterSlugRename(renameData.file, pendingTitleBarEdits);
      await refreshExternalMemoryCaches();
      rerenderExternalListViewBody();
      syncAppRouteToUrl({ replace: true });
      showToast("Переименовано", "success");
      notifyMarkdownLinkRewrite(renameData.linkRewrite);
    }

    if (shouldRenameFlatStorage) {
      const oldFlatStorageFile = activeFlatStorageFilePath;
      const renameResponse = await fetch(buildApiUrl("/api/storage/file/rename"), {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          path: getActiveNodeApiPath(),
          folder: getFlatStorageSectionFolderName(activeContentMode),
          file: activeFlatStorageFilePath,
          title: nextSlug
        })
      });
      if (!renameResponse.ok) {
        const errorData = await renameResponse.json().catch(() => ({}));
        const reason = errorData.error || `Request failed with ${renameResponse.status}`;
        const details = errorData.details ? `: ${errorData.details}` : "";
        throw new Error(`Ошибка переименования файла: ${reason}${details}`);
      }
      const renameData = await renameResponse.json();
      activeFlatStorageFilePath = renameData.file;
      patchEntryOverviewContextsAfterStorageFileRename(
        oldFlatStorageFile,
        renameData.file,
        activeContentMode,
        nextStoredAwnName || nextSlug
      );
      updateBreadcrumbsForActiveMode();
      const pendingTitleBarEdits = captureTitleBarPendingEdits();
      await applyStorageFileContentUi(renameData.content || "", { mode: "external" });
      restoreTitleBarAfterSlugRename(renameData.file, pendingTitleBarEdits);
      await reloadFlatStorageFolderMode(activeContentMode);
      renderListViewContent();
      syncAppRouteToUrl({ replace: true });
      showToast("Переименовано", "success");
      notifyMarkdownLinkRewrite(renameData.linkRewrite);
    }

    if (shouldRenameMediaSidecar) {
      const oldMediaSidecarFile = activeMediaSidecarSourcePath;
      const renameResponse = await fetch(buildApiUrl("/api/media/file/rename"), {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          path: getActiveNodeApiPath(),
          file: activeMediaSidecarSourcePath,
          title: nextSlug
        })
      });
      if (!renameResponse.ok) {
        const errorData = await renameResponse.json().catch(() => ({}));
        const reason = errorData.error || `Request failed with ${renameResponse.status}`;
        const details = errorData.details ? `: ${errorData.details}` : "";
        throw new Error(`Ошибка переименования медиафайла: ${reason}${details}`);
      }
      const renameData = await renameResponse.json();
      activeMediaSidecarSourcePath = renameData.file;
      activeMediaSidecarPath = renameData.sidecar || getMediaSidecarPath(renameData.file);
      patchEntryOverviewContextsAfterStorageFileRename(
        oldMediaSidecarFile,
        renameData.file,
        "media",
        nextStoredAwnName || nextSlug
      );
      updateBreadcrumbsForActiveMode();
      const pendingTitleBarEdits = captureTitleBarPendingEdits();
      if (typeof renameData.content === "string") {
        applyMediaSidecarContentUi(renameData.content);
      }
      restoreTitleBarAfterSlugRename(renameData.file, pendingTitleBarEdits);
      await refreshMediaCache();
      renderListViewContent();
      syncAppRouteToUrl({ replace: true });
      showToast("Файл переименован", "success");
      notifyMarkdownLinkRewrite(renameData.linkRewrite);
    }

    if (shouldRenameMediaMarkdown) {
      const oldMediaMarkdownFile = activeMediaMarkdownPath;
      const renameResponse = await fetch(buildApiUrl("/api/media/file/rename"), {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          path: getActiveNodeApiPath(),
          file: activeMediaMarkdownPath,
          title: nextSlug
        })
      });
      if (!renameResponse.ok) {
        const errorData = await renameResponse.json().catch(() => ({}));
        const reason = errorData.error || `Request failed with ${renameResponse.status}`;
        const details = errorData.details ? `: ${errorData.details}` : "";
        throw new Error(`Ошибка переименования markdown-файла: ${reason}${details}`);
      }
      const renameData = await renameResponse.json();
      activeMediaMarkdownPath = renameData.file;
      patchEntryOverviewContextsAfterStorageFileRename(
        oldMediaMarkdownFile,
        renameData.file,
        "media",
        nextStoredAwnName || nextSlug
      );
      updateBreadcrumbsForActiveMode();
      if (typeof renameData.content === "string" && renameData.content.trim()) {
        const pendingTitleBarEdits = captureTitleBarPendingEdits();
        applyMediaSidecarContentUi(renameData.content);
        restoreTitleBarAfterSlugRename(renameData.file, pendingTitleBarEdits);
      }
      await refreshMediaCache();
      renderListViewContent();
      syncAppRouteToUrl({ replace: true });
      showToast("Файл переименован", "success");
      notifyMarkdownLinkRewrite(renameData.linkRewrite);
    }

    const saveUrl = buildApiUrl(
      activeContentMode === "external" && activeExternalFilePath
        ? "/api/external/file"
        : activeContentMode === "internal"
          ? "/api/memory/internal"
          : activeContentMode === "tabular"
            ? "/api/memory/tabular"
          : activeContentMode === "todo"
            ? "/api/todo"
            : activeContentMode === "roadmap"
              ? "/api/roadmap"
            : isNodeConfigEditorMode()
              ? "/api/file/node-config"
              : activeContentMode === "env"
                ? "/api/env"
                : "/api/file/content"
    );
    if (!isEditorSaveTrackingActive()) {
      throw new Error("Этот режим доступен только для чтения");
    }

    if (isMediaLibraryContentMode() && activeMediaMarkdownPath) {
      const response = await fetch(buildApiUrl("/api/media/markdown"), {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          ...buildMediaLibraryApiParams(),
          file: activeMediaMarkdownPath,
          content
        })
      });
      if (!response.ok) {
        const errorData = await response.json().catch(() => ({}));
        const reason = errorData.error || `Request failed with ${response.status}`;
        const details = errorData.details ? `: ${errorData.details}` : "";
        throw new Error(`${reason}${details}`);
      }
      const data = await response.json();
      applyMediaSidecarContentUi(data.content || "");
      await refreshMediaCache();
      refreshEditorViewContent();
      saveSucceeded = true;
      showToast("Сохранено", "success");
      return;
    }

    if (isAttachmentSidecarEditing() && activeAttachmentSidecarRef) {
      const mediaRel = resolveAttachmentMediaRelPath(activeAttachmentSidecarRef);
      const response = await fetch(buildApiUrl("/api/media/sidecar"), {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          ...buildAttachmentSidecarApiParams(mediaRel),
          content
        })
      });
      if (!response.ok) {
        const errorData = await response.json().catch(() => ({}));
        const reason = errorData.error || `Request failed with ${response.status}`;
        const details = errorData.details ? `: ${errorData.details}` : "";
        throw new Error(`${reason}${details}`);
      }
      const data = await response.json();
      applyMediaSidecarContentUi(data.content || content);
      invalidateAttachmentSidecarMeta(activeAttachmentSidecarRef);
      await refreshAttachmentSidecarLabelsEverywhere();
      refreshEditorViewContent();
      saveSucceeded = true;
      showToast("Sidecar вложения сохранён", "success");
      return;
    }

    if (isMediaLibraryContentMode() && activeMediaSidecarPath) {
      const response = await fetch(buildApiUrl("/api/media/sidecar"), {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          ...buildTopicMediaSidecarApiParams(activeMediaSidecarSourcePath),
          content
        })
      });
      if (!response.ok) {
        const errorData = await response.json().catch(() => ({}));
        const reason = errorData.error || `Request failed with ${response.status}`;
        const details = errorData.details ? `: ${errorData.details}` : "";
        throw new Error(`${reason}${details}`);
      }
      const data = await response.json();
      applyMediaSidecarContentUi(data.content || "");
      await refreshMediaCache();
      refreshEditorViewContent();
      void refreshAllFocusPanels();
      saveSucceeded = true;
      showToast("Sidecar сохранён", "success");
      return;
    }

    if (isFlatStorageFileEditing()) {
      const saveApiPath = isFlatStorageMarkdownRecordEditing() ? "/api/storage/markdown" : "/api/storage/file";
      const response = await fetch(buildApiUrl(saveApiPath), {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          path: getActiveNodeApiPath(),
          folder: getFlatStorageSectionFolderName(activeContentMode),
          file: activeFlatStorageFilePath,
          content
        })
      });
      if (!response.ok) {
        const errorData = await response.json().catch(() => ({}));
        const reason = errorData.error || `Request failed with ${response.status}`;
        const details = errorData.details ? `: ${errorData.details}` : "";
        throw new Error(`${reason}${details}`);
      }
      const data = await response.json();
      const pendingTitleBarEdits = captureTitleBarPendingEdits();
      await applyStorageFileContentUi(data.content || content, { mode: "external" });
      restoreTitleBarAfterSlugRename(activeFlatStorageFilePath, pendingTitleBarEdits);
      await reloadFlatStorageFolderMode(activeContentMode);
      refreshEditorViewContent();
      saveSucceeded = true;
      showToast("Сохранено", "success");
      return;
    }

    const response = await fetch(saveUrl, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(
        activeContentMode === "external" && activeExternalFilePath
          ? { path: getActiveNodeApiPath(), file: activeExternalFilePath, content }
          : { path: getActiveNodeApiPath(), content }
      )
    });

    if (!response.ok) {
      const errorData = await response.json().catch(() => ({}));
      const reason = errorData.error || `Request failed with ${response.status}`;
      const details = errorData.details ? `: ${errorData.details}` : "";
      throw new Error(`${reason}${details}`);
    }

    const data = await response.json();
    if (activeContentMode === "description") {
      modeContentCache.description = data.content || "";
      const { frontmatter } = splitFrontmatter(modeContentCache.description);
      setPropsYamlContent(frontmatter);
      applyNodeManifestBody(modeContentCache.description);
      refreshEditorViewContent();
      if (displayNameChanged) {
        activeLabel = resolveNodeDisplayName(nextStoredAwnName, getNodeSlugFromPath(activePath));
        replaceActiveMenuLabel(activeLabel, activePath);
        try {
          await refreshMenu({ agentId: activeWorkspaceId });
        } catch {
          // menu will resync on next open
        }
      }
      syncTitleFieldsFromNode(activePath);
      syncAppRouteToUrl({ replace: true });
      void refreshAllFocusPanels();
      saveSucceeded = true;
      showToast("Сохранено", "success");
      return;
    }
    if (activeContentMode === "internal") modeContentCache.internal = data.content || "";
    if (activeContentMode === "tabular") {
      modeContentCache.tabular = data.content || "";
      tabularDataCache = {
        columns: Array.isArray(data.columns) ? data.columns : [],
        rows: Array.isArray(data.rows) ? data.rows : [],
        rowCount: data.rowCount || 0
      };
      setEditorViewMode("preview");
      renderListViewContent();
      saveSucceeded = true;
      showToast("CSV сохранён", "success");
      return;
    }
    if (activeContentMode === "todo") {
      modeContentCache.todo = data.content || "";
      fileContentInputNode.value = modeContentCache.todo;
      saveSucceeded = true;
      showToast("TODO сохранён", "success");
      refreshEditorViewContent();
      return;
    }
    if (activeContentMode === "roadmap") {
      modeContentCache.roadmap = data.content || "";
      fileContentInputNode.value = modeContentCache.roadmap;
      saveSucceeded = true;
      showToast("Карты сохранены", "success");
      refreshEditorViewContent();
      return;
    }
    if (isNodeConfigEditorMode()) {
      modeContentCache.configs = data.content || "";
      setCachedNodeConfig(getNodeSettingsManifestPath(), {
        path: data.path || "",
        content: data.content || "",
        exists: Boolean(data.exists),
        defaultLandingMode: data.defaultLandingMode || parseNodeConfigContent(data.content || "").defaultLandingMode
      });
      syncNodeDefaultLandingBtn();
      saveSucceeded = true;
      showToast(
        isProjectSettingsMode() ? "Настройки сохранены" : `${BUNDLE_CONFIG_FILE} сохранён`,
        "success"
      );
      refreshEditorViewContent();
      return;
    }
    if (activeContentMode === "env") modeContentCache.env = data.content || "";
    if (activeContentMode === "external" && activeExternalFilePath) {
      const pendingTitleBarEdits = captureTitleBarPendingEdits();
      await applyExternalFileContentUi(data.content || "");
      restoreTitleBarAfterSlugRename(activeExternalFilePath, pendingTitleBarEdits);
      refreshEditorViewContent();
      saveSucceeded = true;
      showToast(`Файл ${STORAGE_SUBFOLDER_CONTENT} сохранен`, "success");
      return;
    }
    fileContentInputNode.value = data.content;
    refreshEditorViewContent();
    saveSucceeded = true;
    showToast("Сохранено", "success");
  } catch (error) {
    showToast(`Ошибка сохранения: ${error.message}`, "error");
  } finally {
    setSaveButtonsState(false);
    if (saveSucceeded) commitEditorSaveBaseline();
  }
}

async function loadPropertiesForActivePath() {
  if (!activePath) {
    setPropsYamlContent("");
    return;
  }
  if (isAwnDatabaseCsvRecordContentPath(getResolvedNodePath(activePath))) {
    setPropsYamlContent("");
    return;
  }
  if (isMediaAssetEditing()) {
    return;
  }
  await ensureTopicSchemaForActiveContext();
  try {
    const response = await fetch(buildApiUrl("/api/file/properties", { path: getPropertiesApiPath() }));
    if (!response.ok) throw new Error(`Request failed with ${response.status}`);
    const data = await response.json();
    setPropsYamlContent(data.content || "");
  } catch (error) {
    setPropsYamlContent(`# Ошибка чтения YAML-свойств: ${error.message}`);
    propsRawYamlVisible = true;
    propsInputNode.classList.remove("hidden");
    setPropsYamlToggleLabel("Скрыть YAML");
    propsYamlToggleBtn?.classList.add("active");
  }
}

async function saveProperties({ showToastOnSuccess = true, fromSyncedYaml = false } = {}) {
  if (!activePath) return;
  const manifestSlug = getNodeSlugFromPath(activePath);
  const previousRawAwnName = getAwnNameRawForNode(activePath);
  const nextTitle = titleInputNode?.value?.trim() || "";
  const nextStoredAwnName = normalizeAwnNameForStorage(nextTitle, manifestSlug);
  const displayNameChanged =
    activeContentMode === "description" &&
    nextStoredAwnName !== previousRawAwnName &&
    !isAgentSystemRootIndexPath(activePath) &&
    !isPartNodePath(activePath);
  if (!fromSyncedYaml) {
    if (activeContentMode === "description" && !isPartNodePath(activePath)) {
      syncDisplayNameIntoAwnNameProp(activePath);
    }
    flushPropsYamlFromFormBeforeSave();
  }
  const content = propsInputNode.value;
  try {
    const response = await fetch(buildApiUrl("/api/file/properties"), {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ path: getPropertiesApiPath(), content })
    });
    if (!response.ok) {
      const errorData = await response.json().catch(() => ({}));
      const reason = errorData.error || `Request failed with ${response.status}`;
      const details = errorData.details ? `: ${errorData.details}` : "";
      throw new Error(`${reason}${details}`);
    }
    const data = await response.json();
    setPropsYamlContent(data.content || "", { preserveRawMode: propsRawYamlVisible });
    if (
      activeContentMode === "description" ||
      activeContentMode === NODE_OVERVIEW_MODE ||
      activeContentMode === NODE_NAVIGATION_MODE
    ) {
      const { body } = splitFrontmatter(modeContentCache.description || "");
      modeContentCache.description = joinFrontmatter(data.content || "", body);
    }
    if (displayNameChanged) {
      activeLabel = resolveNodeDisplayName(nextStoredAwnName, getNodeSlugFromPath(activePath));
      replaceActiveMenuLabel(activeLabel, activePath);
      try {
        if (isAgentRootIndexPath(activePath)) {
          await loadAgents();
          renderAgentSelect();
        }
        await refreshMenu({ agentId: activeWorkspaceId });
      } catch {
        // menu will resync on next open
      }
      syncTitleFieldsFromNode(activePath);
    }
    if (showToastOnSuccess) {
      showToast("YAML сохранен", "success");
    }
    invalidateTopicSlotsDisabledCache(getPropertiesApiPath());
    await refreshMenuRuntimeFlagsCache(activeWorkspaceId);
    patchMenuNodeRuntimeCommandsFromProps(activePath, mergePropsFormEntries());
    const menu = menuCacheByAgent.get(activeWorkspaceId);
    if (menu) enrichMenuRuntimeFromCache(menu, activeWorkspaceId);
    refreshMenuTreeRuntimeBadges(activeWorkspaceId);
    void refreshAllFocusPanels();
  } catch (error) {
    showToast("Ошибка YAML", "error");
    throw error;
  }
}

function parseDefaultWorkspaceViewFromAwnUi(awnUi) {
  const raw = awnUi?.[AWN_UI_DEFAULT_WORKSPACE_VIEW_KEY];
  if (raw === undefined || raw === null || raw === "") return null;
  const view = normalizeVisibleAgentWorkspaceView(String(raw).trim());
  return isAcceptedAgentWorkspaceView(view) ? view : null;
}

function isAcceptedAgentWorkspaceView(view) {
  return (
    view === "dashboard" ||
    view === "dashboard2" ||
    view === "dashboard3" ||
    view === "git" ||
    view === "journal" ||
    view === "project-settings" ||
    view === "large-files" ||
    view === "broken-links" ||
    view === "run-scripts" ||
    view === "todo-list" ||
    view === "module-catalog" ||
    view === "runtime-registry" ||
    view === "awn-types" ||
    view === "map" ||
    view === "map2" ||
    view === "map3" ||
    view === "schema" ||
    view === "roadmap-map" ||
    view === "vault" ||
    view === "graph" ||
    view === "storage" ||
    view === "table" ||
    view === "timeline" ||
    view === "timeline-axis" ||
    view === "timeline-vertical"
  );
}

function shouldPersistAgentWorkspaceViewToConfig(view) {
  return (
    view !== "roadmap-map" &&
    view !== "git" &&
    view !== "awn-types" &&
    view !== "large-files" &&
    view !== "broken-links" &&
    view !== "run-scripts" &&
    view !== "todo-list" &&
    view !== "module-catalog" &&
    view !== "runtime-registry"
  );
}

function shouldApplyAgentWorkspaceViewFromConfig() {
  if (activePath || activeSystemFile || activeFolderBrowsePath) return false;
  const route = parseAppRoute(location.pathname);
  if (route.type === "agentHome") {
    return !route.view;
  }
  if (route.type === "chpu") {
    const chpuPath = String(route.chpuPath || "").replace(/^\/+/, "");
    if (!chpuPath) return true;
    const first = chpuPath.split("/").filter(Boolean)[0] || "";
    if (first.startsWith("~") && CHPU_WORKSPACE_MODULE_VIEW_IDS.has(first.slice(1))) return false;
    return true;
  }
  return false;
}

async function readAgentWorkspaceViewFromWorkspaceConfig(agentId = activeWorkspaceId) {
  const manifestPath = getAgentWorkspaceRootManifestPath();
  if (!manifestPath || !agentId) return null;
  try {
    const data = await loadNodeConfig(manifestPath, { agentId, force: false });
    const awnUi = NodeConfigBundle.parseNodeConfigBundle(data.content || "").awn_ui;
    return parseDefaultWorkspaceViewFromAwnUi(awnUi);
  } catch {
    return null;
  }
}

let persistAgentWorkspaceViewToConfigPromise = null;

async function persistAgentWorkspaceViewToWorkspaceConfig(view, agentId = activeWorkspaceId) {
  if (!shouldPersistAgentWorkspaceViewToConfig(view)) return;
  const manifestPath = getAgentWorkspaceRootManifestPath();
  if (!manifestPath || !agentId || !isNodeMdPath(manifestPath)) return;
  const normalized = normalizeVisibleAgentWorkspaceView(view);
  if (!isAcceptedAgentWorkspaceView(normalized)) return;

  const run = async () => {
    try {
      const current = await loadNodeConfig(manifestPath, { agentId, force: true });
      const content = NodeConfigBundle.applyAwnUiToConfig(current.content || "", {
        [AWN_UI_DEFAULT_WORKSPACE_VIEW_KEY]: normalized
      });
      await saveNodeConfigContent(manifestPath, content, agentId);
    } catch {
      // ignore config save errors for workspace view
    }
  };

  persistAgentWorkspaceViewToConfigPromise = run();
  await persistAgentWorkspaceViewToConfigPromise;
  persistAgentWorkspaceViewToConfigPromise = null;
}

async function syncAgentWorkspaceViewFromWorkspaceConfig(agentId = activeWorkspaceId) {
  if (agentId !== activeWorkspaceId || !shouldApplyAgentWorkspaceViewFromConfig()) return;
  const configView = await readAgentWorkspaceViewFromWorkspaceConfig(agentId);
  if (!configView) return;
  const normalized = normalizeVisibleAgentWorkspaceView(configView);
  if (normalized === agentWorkspaceView) {
    syncAgentWorkspaceViewButtons();
    return;
  }
  agentWorkspaceView = normalized;
  saveAgentWorkspaceView(normalized);
  syncAgentWorkspaceViewButtons();
  if (isAgentWorkspaceCanvasVisible()) {
    applyAgentWorkspaceCanvasUi();
  }
}

