function setAgentWorkspaceView(
  view,
  { skipRouteSync = false, persistWorkspaceConfig = true, saveSessionView = true, push = false } = {}
) {
  if (view === "journal") {
    void openWorkspaceJournalModule({ skipRouteSync, push });
    return;
  }
  if (view === "project-settings") {
    void openProjectSettingsHub({ skipRouteSync, push });
    return;
  }
  if (
    view !== "dashboard" &&
    view !== "dashboard2" &&
    view !== "dashboard3" &&
    view !== "git" &&
    view !== "project-settings" &&
    view !== "large-files" &&
    view !== "broken-links" &&
    view !== "run-scripts" &&
    view !== "todo-list" &&
    view !== "module-catalog" &&
    view !== "runtime-registry" &&
    view !== "awn-types" &&
    view !== "map" &&
    view !== "map2" &&
    view !== "map3" &&
    view !== "schema" &&
    view !== "roadmap-map" &&
    view !== "vault" &&
    view !== "graph" &&
    view !== "storage" &&
    view !== "table" &&
    view !== "timeline" &&
    view !== "timeline-axis" &&
    view !== "timeline-vertical"
  ) {
    return;
  }
  agentWorkspaceView = view;
  if (saveSessionView) {
    saveAgentWorkspaceView(view);
  }
  if (persistWorkspaceConfig) {
    void persistAgentWorkspaceViewToWorkspaceConfig(view);
  }

  if (activePath || activeSystemFile) {
    showHomeView();
    applyAgentWorkspaceCanvasUi();
    if (!skipRouteSync) {
      syncAppRouteToUrl({ push, replace: !push });
    }
    return;
  }

  if (!isAgentWorkspaceCanvasVisible()) {
    showHomeView();
    return;
  }

  applyAgentWorkspaceCanvasUi();
  if (!skipRouteSync) {
    syncAppRouteToUrl({ push, replace: !push });
  }
}

function countAgentMenuNodes(menu) {
  if (!menu) return { total: 0, folders: 0, leaves: 0 };
  const entries = collectAgentMenuFlatEntries(menu, activeWorkspaceId, { includeHiddenSections: true });
  const folders = entries.filter((entry) => entry.isFolder).length;
  return {
    total: entries.length,
    folders,
    leaves: entries.length - folders
  };
}


