function agentGitBasenameMatchesConfigExtras(filePath) {
  const base = String(filePath || "").replace(/\\/g, "/").split("/").pop() || "";
  const lower = base.toLowerCase();
  if (lower === ".gitignore") return true;
  if (lower === ".env" || lower.startsWith(".env.")) return true;
  if (lower.endsWith(".lock")) return true;
  return AGENT_GIT_EXTRA_BASENAMES.some((name) => String(name || "").toLowerCase() === lower);
}

function agentGitChangeMatchesCommitBatch(change, batch) {
  if (!change || !batch) return false;
  const extSet = agentGitCommitBatchExtensionSet(batch);
  const paths = [change.path, change.oldPath].filter(Boolean);
  for (const filePath of paths) {
    if (String(batch.id || "") === "configs" && agentGitBasenameMatchesConfigExtras(filePath)) {
      return true;
    }
    const normalized = String(filePath || "").replace(/\\/g, "/");
    const dot = normalized.lastIndexOf(".");
    const ext = dot >= 0 ? normalized.slice(dot + 1).toLowerCase() : "";
    if (ext && extSet.has(ext)) return true;
  }
  return false;
}

function resolveAgentGitChangeCommitBatch(change, batches = agentGitModuleConfig?.commitBatches) {
  const list = Array.isArray(batches) ? batches : [];
  const batchId = String(change?.commitBatchId || "").trim();
  if (batchId) {
    const byId = list.find((entry) => String(entry?.id || "") === batchId);
    if (byId) return byId;
  }
  for (const entry of list) {
    if (agentGitChangeMatchesCommitBatch(change, entry)) return entry;
  }
  return null;
}

function isAgentGitOutOfBatchChange(change, batches = agentGitModuleConfig?.commitBatches) {
  return !resolveAgentGitChangeCommitBatch(change, batches);
}

function getAgentGitOutOfBatchCommitBatch() {
  const other = (agentGitModuleConfig?.commitBatches || []).find(
    (entry) => String(entry?.id || "") === "other"
  );
  const maxFileSizeMb = Number(other?.maxFileSizeMb) > 0 ? Number(other.maxFileSizeMb) : 25;
  return {
    id: AGENT_GIT_OUT_OF_BATCH_BATCH_ID,
    emoji: "❔",
    label: "Вне списка",
    extensions: [],
    messageTemplate: AGENT_GIT_COMMIT_TEMPLATE_OUT_OF_BATCH_FALLBACK,
    maxFileSizeMb
  };
}

function getAgentGitFullCommitBatch() {
  return {
    id: AGENT_GIT_FULL_COMMIT_BATCH_ID,
    emoji: "🌐",
    label: "Full",
    extensions: [],
    messageTemplate: "[{branch}] Сохранение workspace ({date} {time}) - Full",
    maxFileSizeMb: 0
  };
}

function listAgentGitFullCommitChanges(changes = []) {
  return (Array.isArray(changes) ? changes : []).filter((change) => change?.commitAllowed !== false);
}

function buildAgentGitFullCommitModalOption(changes = []) {
  const batch = getAgentGitFullCommitBatch();
  const batchChanges = listAgentGitFullCommitChanges(changes);
  const count = batchChanges.length;
  const byteTotal = sumAgentGitCommitChangesByteTotal(batchChanges);
  return {
    batch,
    optionId: AGENT_GIT_FULL_COMMIT_BATCH_ID,
    chunkIndex: null,
    chunkTotal: 1,
    count,
    byteTotal,
    overLimit: false
  };
}

function agentGitChangeBelongsToCommitBatch(
  change,
  batch,
  batches = agentGitModuleConfig?.commitBatches
) {
  const batchId = String(batch?.id || "");
  if (batchId === AGENT_GIT_FULL_COMMIT_BATCH_ID) {
    return change?.commitAllowed !== false;
  }
  if (batchId === AGENT_GIT_OUT_OF_BATCH_BATCH_ID) {
    return isAgentGitOutOfBatchChange(change, batches);
  }
  return resolveAgentGitChangeCommitBatch(change, batches)?.id === batchId;
}

function countAgentGitOutOfBatchCommittableChanges(changes = []) {
  return (Array.isArray(changes) ? changes : []).filter(
    (change) => isAgentGitOutOfBatchChange(change) && change?.commitAllowed !== false
  ).length;
}

function countAgentGitChangesForCommitBatch(batch, changes = []) {
  const batchId = String(batch?.id || "");
  return (Array.isArray(changes) ? changes : []).filter((change) => {
    if (change?.commitAllowed === false) return false;
    return agentGitChangeBelongsToCommitBatch(change, batch);
  }).length;
}

function countAgentGitChangesInBatch(batch, changes = []) {
  const batchId = String(batch?.id || "");
  return (Array.isArray(changes) ? changes : []).filter((change) => {
    if (change?.commitBatchId) return change.commitBatchId === batchId;
    return agentGitChangeMatchesCommitBatch(change, batch);
  }).length;
}

function agentGitExtensionLabelFromChangePath(filePath) {
  const normalized = String(filePath || "").replace(/\\/g, "/");
  const dot = normalized.lastIndexOf(".");
  if (dot < 0) return "";
  return normalized.slice(dot + 1).toLowerCase();
}

function agentGitExtensionLabelForBatchChange(change, batch) {
  const paths = [change?.path, change?.oldPath].filter(Boolean);
  for (const filePath of paths) {
    if (String(batch?.id || "") === "configs" && agentGitBasenameMatchesConfigExtras(filePath)) {
      return "";
    }
    const ext = agentGitExtensionLabelFromChangePath(filePath);
    if (ext) return ext;
  }
  return "";
}

function countAgentGitBatchChangesByExtension(batch, changes = []) {
  const counts = new Map();
  for (const change of Array.isArray(changes) ? changes : []) {
    if (!agentGitChangeMatchesCommitBatch(change, batch)) continue;
    const ext = agentGitExtensionLabelForBatchChange(change, batch);
    if (!ext) continue;
    counts.set(ext, (counts.get(ext) || 0) + 1);
  }
  return counts;
}

function countAgentGitChangesByExtension(changes = []) {
  const counts = new Map();
  for (const change of Array.isArray(changes) ? changes : []) {
    const ext = agentGitExtensionLabelFromChangePath(change?.path || change?.oldPath);
    if (!ext) continue;
    counts.set(ext, (counts.get(ext) || 0) + 1);
  }
  return counts;
}

function formatAgentGitCommitBatchFileCountLabel(count) {
  const n = Number(count) || 0;
  if (n <= 0) return "0";
  const mod10 = n % 10;
  const mod100 = n % 100;
  let word = "файлов";
  if (mod10 === 1 && mod100 !== 11) word = "файл";
  else if (mod10 >= 2 && mod10 <= 4 && (mod100 < 12 || mod100 > 14)) word = "файла";
  return `${n} ${word}`;
}

function getAgentGitCommitMaxBatchBytes() {
  const fromConfig = Number(agentGitModuleConfig?.commitMaxBatchBytes);
  if (Number.isFinite(fromConfig) && fromConfig > 0) return fromConfig;
  const mb = Number(agentGitModuleConfig?.commitMaxBatchMb);
  if (!Number.isFinite(mb) || mb <= 0) return 0;
  return Math.round(mb * 1024 * 1024);
}

function formatAgentGitByteSizeLabel(bytes) {
  const size = Number(bytes);
  if (!Number.isFinite(size) || size < 0) return "—";
  if (size < 1024) return `${size} B`;
  if (size < 1024 * 1024) return `${(size / 1024).toFixed(1)} KB`;
  if (size < 1024 * 1024 * 1024) return `${(size / (1024 * 1024)).toFixed(1)} MB`;
  return `${(size / (1024 * 1024 * 1024)).toFixed(2)} GB`;
}

function sumAgentGitCommitBatchByteTotal(batch, changes = []) {
  let total = 0;
  for (const change of Array.isArray(changes) ? changes : []) {
    if (change?.commitAllowed === false) continue;
    if (!agentGitChangeBelongsToCommitBatch(change, batch)) continue;
    if (change?.kind === "deleted") continue;
    const size = Number(change?.sizeBytes);
    if (Number.isFinite(size) && size > 0) total += size;
  }
  return total;
}

function sumAgentGitCommitChangesByteTotal(changes = []) {
  let total = 0;
  for (const change of Array.isArray(changes) ? changes : []) {
    if (change?.commitAllowed === false) continue;
    if (change?.kind === "deleted") continue;
    const size = Number(change?.sizeBytes);
    if (Number.isFinite(size) && size > 0) total += size;
  }
  return total;
}

function listAgentGitChangesForCommitBatch(batch, changes = []) {
  return (Array.isArray(changes) ? changes : []).filter((change) => {
    if (change?.commitAllowed === false) return false;
    return agentGitChangeBelongsToCommitBatch(change, batch);
  });
}

function parseAgentGitCommitBatchOptionId(optionId) {
  const raw = String(optionId || "").trim();
  const match = raw.match(/^(.+)#(\d+)$/);
  if (!match) {
    return { batchId: raw, chunkIndex: null, optionId: raw };
  }
  const batchId = String(match[1] || "").trim();
  const chunkIndex = Number(match[2]) || 0;
  return {
    batchId,
    chunkIndex: chunkIndex > 0 ? chunkIndex : null,
    optionId: raw
  };
}

function splitAgentGitCommitChangesIntoChunksSync(changes, maxBatchBytes) {
  const list = (Array.isArray(changes) ? changes : []).filter((change) => change?.commitAllowed !== false);
  const limit = Number(maxBatchBytes) || 0;
  if (!list.length) return [];
  if (limit <= 0) return [list];

  const sorted = [...list].sort((left, right) =>
    String(left?.path || left?.oldPath || "").localeCompare(
      String(right?.path || right?.oldPath || ""),
      "ru"
    )
  );

  const chunks = [];
  let current = [];
  let currentBytes = 0;

  const flush = () => {
    if (!current.length) return;
    chunks.push(current);
    current = [];
    currentBytes = 0;
  };

  for (const change of sorted) {
    const size =
      change?.kind === "deleted"
        ? 0
        : Number.isFinite(Number(change?.sizeBytes)) && Number(change.sizeBytes) > 0
          ? Number(change.sizeBytes)
          : 0;
    if (size > limit) {
      flush();
      chunks.push([change]);
      continue;
    }
    if (current.length && currentBytes + size > limit) {
      flush();
    }
    current.push(change);
    currentBytes += size;
  }
  flush();
  return chunks;
}

function buildAgentGitCommitModalBatchOptions(batch, changes = []) {
  const maxBatchBytes = getAgentGitCommitMaxBatchBytes();
  const batchChanges = listAgentGitChangesForCommitBatch(batch, changes);
  const count = batchChanges.length;
  const byteTotal = sumAgentGitCommitBatchByteTotal(batch, changes);

  if (count === 0) {
    return [
      {
        batch,
        optionId: String(batch.id || ""),
        chunkIndex: null,
        chunkTotal: 1,
        count: 0,
        byteTotal: 0,
        overLimit: false
      }
    ];
  }

  const needsSplit = maxBatchBytes > 0 && byteTotal > maxBatchBytes;
  if (!needsSplit) {
    return [
      {
        batch,
        optionId: String(batch.id || ""),
        chunkIndex: null,
        chunkTotal: 1,
        count,
        byteTotal,
        overLimit: false
      }
    ];
  }

  const chunks = splitAgentGitCommitChangesIntoChunksSync(batchChanges, maxBatchBytes);
  const chunkTotal = chunks.length || 1;
  if (chunkTotal <= 1) {
    return [
      {
        batch,
        optionId: String(batch.id || ""),
        chunkIndex: 1,
        chunkTotal: 1,
        count,
        byteTotal,
        overLimit: true
      }
    ];
  }

  return chunks.map((chunk, index) => {
    const chunkIndex = index + 1;
    const chunkBytes = sumAgentGitCommitChangesByteTotal(chunk);
    return {
      batch,
      optionId: `${String(batch.id || "")}#${chunkIndex}`,
      chunkIndex,
      chunkTotal,
      count: chunk.length,
      byteTotal: chunkBytes,
      overLimit: maxBatchBytes > 0 && chunkBytes > maxBatchBytes
    };
  });
}

function listAgentGitCommitModalOptions(changes = []) {
  const batches = listAgentGitCommitBatchesForDisplay(changes);
  const options = [buildAgentGitFullCommitModalOption(changes)];
  for (const batch of batches) {
    options.push(...buildAgentGitCommitModalBatchOptions(batch, changes));
  }
  return options;
}

function agentGitCommitBatchExceedsMaxSize(batch, changes = []) {
  const maxBytes = getAgentGitCommitMaxBatchBytes();
  if (!maxBytes) return false;
  return sumAgentGitCommitBatchByteTotal(batch, changes) > maxBytes;
}

function getAgentGitCommitBatchById(batchId) {
  const id = parseAgentGitCommitBatchOptionId(batchId).batchId;
  if (!id) return null;
  if (id === AGENT_GIT_FULL_COMMIT_BATCH_ID) return getAgentGitFullCommitBatch();
  if (id === AGENT_GIT_OUT_OF_BATCH_BATCH_ID) return getAgentGitOutOfBatchCommitBatch();
  const batches = Array.isArray(agentGitModuleConfig?.commitBatches)
    ? agentGitModuleConfig.commitBatches
    : [];
  return batches.find((batch) => String(batch.id || "") === id) || null;
}

/** Порядок как в integrations.yml; партии с файлами (count > 0) — выше, с 0 — внизу. */
function listAgentGitCommitBatchesForDisplay(changes = []) {
  const batches = Array.isArray(agentGitModuleConfig?.commitBatches) ? agentGitModuleConfig.commitBatches : [];
  const outOfBatch = getAgentGitOutOfBatchCommitBatch();
  const withOutOfBatch = [...batches, outOfBatch];
  return withOutOfBatch
    .map((batch, index) => ({
      batch,
      index,
      count: countAgentGitChangesForCommitBatch(batch, changes)
    }))
    .sort((left, right) => {
      const leftActive = left.count > 0 ? 1 : 0;
      const rightActive = right.count > 0 ? 1 : 0;
      if (rightActive !== leftActive) return rightActive - leftActive;
      return left.index - right.index;
    })
    .map((entry) => entry.batch);
}

function buildAgentGitBatchCommitMessagePrefix(batch, now = new Date(), chunkIndex = null, chunkTotal = 1) {
  const pad = (value) => String(value).padStart(2, "0");
  const datePart = `${now.getFullYear()}-${pad(now.getMonth() + 1)}-${pad(now.getDate())}`;
  const timePart = `${pad(now.getHours())}:${pad(now.getMinutes())}`;
  const template =
    String(batch?.messageTemplate || "").trim() || AGENT_GIT_COMMIT_MESSAGE_TEMPLATE_FALLBACK;
  let prefix = applyAgentGitCommitMessageTemplate(template, {
    branch: getAgentGitCommitBranchLabel(),
    date: datePart,
    time: timePart
  });
  const total = Number(chunkTotal) || 0;
  const index = Number(chunkIndex) || 0;
  if (total > 1 && index > 0) {
    prefix += ` [${index}/${total}]`;
  }
  return prefix;
}

