function collectWorkspaceTodoSources() {
  const sources = [
    {
      path: ROOT_SYSTEM_TODO_FILE,
      label: "Корень workspace",
      kind: "root"
    }
  ];
  const menu = currentMenuData;
  if (!menu) return sources;

  const seen = new Set([ROOT_SYSTEM_TODO_FILE.toLowerCase()]);
  for (const entry of collectAgentMenuFlatEntries(menu, activeWorkspaceId, { includeHiddenSections: true })) {
    if (entry.isFolder) continue;
    const manifestPath = normalizeMenuNodePath(resolveManifestPathForNodeApi(entry.path) || entry.path || "");
    if (!manifestPath || !isNodeManifestPath(manifestPath)) continue;
    const todoPath = normalizeMenuNodePath(getNamedStorageBundleRel(manifestPath, BUNDLE_TODO_FILE));
    if (!todoPath || seen.has(todoPath.toLowerCase())) continue;
    seen.add(todoPath.toLowerCase());
    sources.push({
      path: todoPath,
      label: entry.label || getLabelFromPath(entry.path),
      kind: "topic"
    });
  }
  return sources;
}

function countTodoLines(text) {
  return String(text || "")
    .split(/\r?\n/)
    .map((line) => line.trim())
    .filter((line) => /^[-*]\s+\S/.test(line) || /^\[[ xX]\]\s+\S/.test(line)).length;
}

function countNonemptyLines(text) {
  return String(text || "")
    .split(/\r?\n/)
    .filter((line) => line.trim()).length;
}

function formatRussianLineCountLabel(count) {
  const n = Math.abs(Number(count) || 0);
  const mod10 = n % 10;
  const mod100 = n % 100;
  if (mod10 === 1 && mod100 !== 11) return "строка";
  if (mod10 >= 2 && mod10 <= 4 && (mod100 < 12 || mod100 > 14)) return "строки";
  return "строк";
}

function formatRussianTaskCountLabel(count) {
  const n = Math.abs(Number(count) || 0);
  const mod10 = n % 10;
  const mod100 = n % 100;
  if (mod10 === 1 && mod100 !== 11) return "задача";
  if (mod10 >= 2 && mod10 <= 4 && (mod100 < 12 || mod100 > 14)) return "задачи";
  return "задач";
}

function formatAgentNotePreviewToggleLabel(rawContent = "") {
  const previewMarkdown = getAgentTodoSidebarPreviewMarkdown(rawContent);
  if (!previewMarkdown) return AGENT_NOTE_PREVIEW_LABEL_EMPTY;
  const lineCount = countNonemptyLines(previewMarkdown);
  if (lineCount <= 0) return AGENT_NOTE_PREVIEW_LABEL_EMPTY;
  return `NOTE.md (заметка - ${lineCount} ${formatRussianLineCountLabel(lineCount)})`;
}

