function shouldHideAgentSchemaTreeNode(path) {
  return isAgentRootIndexPath(path);
}

function walkAgentSchemaMenu(node, parentUl, sizeByPath = null) {
  const children = getOrderedMenuChildren(node);

  const appendAgentSchemaChild = (child) => {
    if (child.kind === "folder") {
      walkAgentSchemaMenu(child.entry, parentUl, sizeByPath);
      return;
    }
    if (shouldHideAgentSchemaTreeNode(child.entry.path)) return;
    parentUl.appendChild(
      createAgentSchemaItemLi(
        {
          path: child.entry.path,
          label: child.entry.label || getLabelFromPath(child.entry.path),
          displayPath: getNodeDisplayPath(child.entry.path)
        },
        sizeByPath
      )
    );
  };

  if (node.indexPath && shouldHideAgentSchemaTreeNode(node.indexPath)) {
    for (const child of children) appendAgentSchemaChild(child);
    return;
  }

  if (node.indexPath) {
    const li = createAgentSchemaItemLi(
      {
        path: node.indexPath,
        label: getLabelFromPath(node.indexPath),
        displayPath: getNodeDisplayPath(node.indexPath)
      },
      sizeByPath
    );

    const childUl = document.createElement("ul");
    childUl.className = "agent-schema-branch-list";

    for (const child of children) {
      if (child.kind === "folder") {
        walkAgentSchemaMenu(child.entry, childUl, sizeByPath);
      } else if (!shouldHideAgentSchemaTreeNode(child.entry.path)) {
        childUl.appendChild(
          createAgentSchemaItemLi(
            {
              path: child.entry.path,
              label: child.entry.label || getLabelFromPath(child.entry.path),
              displayPath: getNodeDisplayPath(child.entry.path)
            },
            sizeByPath
          )
        );
      }
    }

    if (childUl.children.length > 0) {
      li.appendChild(childUl);
    }
    parentUl.appendChild(li);
    return;
  }

  for (const child of children) appendAgentSchemaChild(child);
}

function getSortedAwnTypesList(typesMap) {
  return Object.entries(typesMap || {})
    .filter(([typeKey]) => !AWN_TYPE_LIST_SKIP.has(typeKey))
    .map(([typeKey, typeDef]) => ({ typeKey, typeDef }))
    .sort((a, b) => {
      const aOrder = getAwnTypeKindSortOrder(a.typeDef?.kind);
      const bOrder = getAwnTypeKindSortOrder(b.typeDef?.kind);
      if (aOrder !== bOrder) return aOrder - bOrder;
      return String(a.typeKey || "").localeCompare(String(b.typeKey || ""));
    });
}

function createAwnTypeKindBadge(kind) {
  return createAwnTypeKindBadgeElement(kind, { className: "agent-awn-type-badge" });
}

function setAwnTypeKindManifest(kinds) {
  awnTypeKindManifestById = kinds && typeof kinds === "object" ? kinds : null;
}

function getAwnTypeKindMeta(kind) {
  const key = String(kind || "type").trim() || "type";
  const hit = awnTypeKindManifestById?.[key];
  if (hit) return hit;
  return { id: key, label: AWN_KIND_BADGE_LABELS[key] || key, badge: null };
}

function applyAwnTypeKindBadgeStyle(el, badge) {
  if (!el || !badge || typeof badge !== "object") return;
  if (badge.background) el.style.backgroundColor = badge.background;
  if (badge.border) el.style.borderColor = badge.border;
  if (badge.text) el.style.color = badge.text;
}

function createAwnTypeKindBadgeElement(kind, { className = "agent-awn-type-nav-kind" } = {}) {
  const normalizedKind = String(kind || "type").trim() || "type";
  const meta = getAwnTypeKindMeta(normalizedKind);
  const badge = document.createElement("span");
  badge.className = `${className} agent-awn-type-nav-kind--${normalizedKind.replace(/[^a-z0-9_-]/gi, "-")}`;
  badge.textContent = meta.label || AWN_KIND_BADGE_LABELS[normalizedKind] || normalizedKind;
  applyAwnTypeKindBadgeStyle(badge, meta.badge);
  return badge;
}

// Группы навигации реестра (domain/kind). Порядок = порядок в сайдбаре.
const AWN_TYPE_NAV_GROUPS = [
  { label: "Страницы и контент", domains: ["pages", "content"] },
  { label: "Слоты", domains: ["slots"] },
  { label: "Типы полей", domains: ["fields"] },
  { label: "Блоки редактора", domains: ["md-blocks"] },
  { label: "Настройки", domains: ["settings"] },
  { label: "Пресеты", domains: ["presets"] },
  { label: "Инфоблоки (awn-databases)", domains: ["infoblock", "data"] },
  { label: "Миксины", domains: ["mixins"] },
  { label: "Базовые", kinds: ["base", "entity", "meta"] }
];

function entryMatchesAwnTypeNavGroup(entry, group) {
  const kind = entry?.typeDef?.kind || "type";
  const domain = String(entry?.typeDef?.domain || "").trim();
  const kinds = Array.isArray(group?.kinds) ? group.kinds : group?.kind ? [group.kind] : null;
  const domains = Array.isArray(group?.domains) ? group.domains : null;
  if (domains?.length && !domains.includes(domain)) return false;
  if (kinds?.length && !kinds.includes(kind)) return false;
  return Boolean(domains?.length || kinds?.length);
}

