function createAwnTypeNavItem(typeKey, typeDef, isActive) {
  const btn = document.createElement("button");
  btn.type = "button";
  btn.className = `agent-awn-type-nav-item${isActive ? " is-active" : ""}`;
  btn.setAttribute("role", "tab");
  btn.setAttribute("aria-selected", isActive ? "true" : "false");
  btn.dataset.typeKey = typeKey || "";

  // First row: badge + id inline
  const firstRow = document.createElement("span");
  firstRow.className = "agent-awn-type-nav-row";

  const kind = typeDef?.kind || "type";
  firstRow.appendChild(createAwnTypeKindBadgeElement(kind));

  const id = document.createElement("span");
  id.className = "agent-awn-type-nav-id";
  id.textContent = typeDef?.id || typeKey || "—";
  firstRow.appendChild(id);
  btn.appendChild(firstRow);

  // Second row: human name
  const humanName = String(typeDef?.name || "").trim();
  if (humanName && humanName !== typeDef?.id) {
    const title = document.createElement("span");
    title.className = "agent-awn-type-nav-name";
    title.textContent = humanName;
    btn.appendChild(title);
  }

  return btn;
}

function createAwnTypeFieldFlags(fieldDef) {
  const flags = document.createElement("span");
  flags.className = "agent-awn-type-field-flags";
  if (fieldDef?.required) {
    const required = document.createElement("span");
    required.className = "agent-awn-type-field-flag agent-awn-type-field-flag--required";
    required.textContent = "обяз.";
    required.title = "Обязательное поле";
    flags.appendChild(required);
  }
  if (fieldDef?.locked) {
    const locked = document.createElement("span");
    locked.className = "agent-awn-type-field-flag agent-awn-type-field-flag--locked";
    locked.textContent = "закр.";
    locked.title = "Только чтение";
    flags.appendChild(locked);
  }
  if (!flags.childElementCount) {
    flags.textContent = "—";
  }
  return flags;
}

function appendAwnTypeDetailMetaLine(meta, label, value, { asCode = true } = {}) {
  if (value == null || value === "" || (Array.isArray(value) && !value.length)) return;
  const node = document.createElement("p");
  node.className = "agent-awn-type-detail-line";
  const rendered = asCode
    ? `<code>${Array.isArray(value) ? value.join(", ") : value}</code>`
    : String(value);
  node.innerHTML = `${label}: ${rendered}`;
  meta.appendChild(node);
}

function renderAwnTypeDetailPanel(typeDef) {
  const panel = document.createElement("div");
  panel.className = "agent-awn-type-detail";
  panel.setAttribute("role", "tabpanel");

  const head = document.createElement("header");
  head.className = "agent-awn-type-detail-head";

  const titleRow = document.createElement("div");
  titleRow.className = "agent-awn-type-detail-title-row";
  const title = document.createElement("h4");
  title.className = "agent-awn-type-detail-title";
  title.textContent = typeDef?.name || typeDef?.id || "—";
  titleRow.append(title, createAwnTypeKindBadge(typeDef?.kind || "type"));
  head.appendChild(titleRow);

  if (typeDef?.id) {
    const idLine = document.createElement("p");
    idLine.className = "agent-awn-type-detail-id";
    idLine.innerHTML = `<code>${typeDef.id}</code>`;
    head.appendChild(idLine);
  }

  panel.appendChild(head);

  const meta = document.createElement("div");
  meta.className = "agent-awn-type-detail-meta";

  if (typeDef?.description) {
    const desc = document.createElement("p");
    desc.className = "agent-awn-type-detail-desc";
    desc.textContent = typeDef.description;
    meta.appendChild(desc);
  }

  const usage = getAwnTypeUsageHint(typeDef?.id || typeDef?.name);
  if (usage) {
    const usageNode = document.createElement("p");
    usageNode.className = "agent-awn-type-detail-usage";
    usageNode.textContent = usage;
    meta.appendChild(usageNode);
  }

  if (typeDef?.extends) {
    const extendsNode = document.createElement("p");
    extendsNode.className = "agent-awn-type-detail-line";
    extendsNode.innerHTML = `Наследует: <code>${typeDef.extends}</code>`;
    meta.appendChild(extendsNode);
  }

  if (Array.isArray(typeDef?.mixins) && typeDef.mixins.length) {
    const mixinsNode = document.createElement("p");
    mixinsNode.className = "agent-awn-type-detail-line";
    mixinsNode.innerHTML = `Миксины: <code>${typeDef.mixins.join("</code>, <code>")}</code>`;
    meta.appendChild(mixinsNode);
  }

  appendAwnTypeDetailMetaLine(meta, "Виджет", typeDef?.widget);
  appendAwnTypeDetailMetaLine(meta, "Хранение", typeDef?.storage);
  appendAwnTypeDetailMetaLine(meta, "mdbase", typeDef?.mdbase);
  appendAwnTypeDetailMetaLine(meta, "Настройки", typeDef?.settings);

  if (meta.childNodes.length) panel.appendChild(meta);

  const fields = typeDef?.fields && typeof typeDef.fields === "object" ? typeDef.fields : {};
  const fieldKeys = Object.keys(fields);
  if (fieldKeys.length) {
    const tableWrap = document.createElement("div");
    tableWrap.className = "agent-awn-type-fields-table-wrap";
    const table = document.createElement("table");
    table.className = "agent-awn-field-registry-table agent-awn-type-fields-table";
    table.innerHTML =
      "<thead><tr>" +
      "<th>Поле</th><th>Тип</th><th>Название</th><th>Флаги</th>" +
      "</tr></thead>";
    const tbody = document.createElement("tbody");
    for (const fieldKey of fieldKeys) {
      const fieldDef = fields[fieldKey];
      const row = document.createElement("tr");
      const keyCell = document.createElement("td");
      keyCell.innerHTML = `<code>${fieldKey}</code>`;
      const typeCell = document.createElement("td");
      typeCell.innerHTML = `<code>${fieldDef?.type || "—"}</code>`;
      const titleCell = document.createElement("td");
      titleCell.textContent = fieldDef?.title || fieldDef?.description || "—";
      const flagsCell = document.createElement("td");
      flagsCell.appendChild(createAwnTypeFieldFlags(fieldDef));
      row.append(keyCell, typeCell, titleCell, flagsCell);
      tbody.appendChild(row);
    }
    table.appendChild(tbody);
    tableWrap.appendChild(table);
    panel.appendChild(tableWrap);
  } else {
    const empty = document.createElement("p");
    empty.className = "agent-awn-type-detail-empty";
    empty.textContent = "У типа нет собственных полей.";
    panel.appendChild(empty);
  }

  return panel;
}

function createAwnTypesBrowserSection(typeEntries) {
  const section = document.createElement("section");
  section.className = "agent-awn-types-section agent-awn-types-section--browser";

  if (!typeEntries.length) {
    const empty = document.createElement("p");
    empty.className = "agent-awn-types-empty";
    empty.textContent = "Типы не найдены.";
    section.appendChild(empty);
    return section;
  }

  const selectedKey =
    typeEntries.find((entry) => entry.typeKey === awnTypesSelectedKey)?.typeKey ||
    typeEntries[0].typeKey;
  awnTypesSelectedKey = selectedKey;
  const selectedEntry =
    typeEntries.find((entry) => entry.typeKey === selectedKey) || typeEntries[0];

  const browser = document.createElement("div");
  browser.className = "agent-awn-types-browser";

  const nav = document.createElement("nav");
  nav.className = "agent-awn-types-nav";
  nav.setAttribute("role", "tablist");
  nav.setAttribute("aria-label", "Реестр типов, модулей и компонентов");

  // Search input
  const searchWrap = document.createElement("div");
  searchWrap.className = "agent-awn-types-search-wrap";
  const searchInput = document.createElement("input");
  searchInput.type = "search";
  searchInput.className = "agent-awn-types-search";
  searchInput.placeholder = "Поиск в реестре…";
  searchInput.setAttribute("aria-label", "Поиск в реестре");
  searchWrap.appendChild(searchInput);
  nav.appendChild(searchWrap);

  const countBadge = document.createElement("span");
  countBadge.className = "agent-awn-types-search-count";
  searchWrap.appendChild(countBadge);

  function renderNavGroups(query) {
    nav.querySelectorAll(".agent-awn-types-nav-group").forEach((n) => n.remove());
    const q = query.trim().toLowerCase();
    let totalVisible = 0;
    const assigned = new Set();

    function matchesQuery(entry) {
      if (!q) return true;
      const id = String(entry.typeDef?.id || entry.typeKey || "").toLowerCase();
      const name = String(entry.typeDef?.name || "").toLowerCase();
      return id.includes(q) || name.includes(q);
    }

    function appendNavGroup(label, groupEntries) {
      const visibleEntries = groupEntries.filter(matchesQuery);
      if (!visibleEntries.length) return;
      totalVisible += visibleEntries.length;

      const groupNode = document.createElement("div");
      groupNode.className = "agent-awn-types-nav-group";

      const groupLabel = document.createElement("div");
      groupLabel.className = "agent-awn-types-nav-group-label";
      groupLabel.textContent = label;
      groupNode.appendChild(groupLabel);

      const list = document.createElement("div");
      list.className = "agent-awn-types-nav-list";
      for (const { typeKey, typeDef } of visibleEntries) {
        list.appendChild(createAwnTypeNavItem(typeKey, typeDef, typeKey === selectedKey));
      }
      groupNode.appendChild(list);
      nav.appendChild(groupNode);
    }

    for (const group of AWN_TYPE_NAV_GROUPS) {
      const groupEntries = [];
      for (const entry of typeEntries) {
        if (assigned.has(entry.typeKey)) continue;
        if (!entryMatchesAwnTypeNavGroup(entry, group)) continue;
        assigned.add(entry.typeKey);
        groupEntries.push(entry);
      }
      appendNavGroup(group.label, groupEntries);
    }

    const rest = typeEntries.filter((entry) => !assigned.has(entry.typeKey));
    if (rest.length) appendNavGroup("Прочее", rest);

    countBadge.textContent = String(totalVisible);
    countBadge.title = `${totalVisible} в реестре`;
  }

  renderNavGroups("");
  searchInput.addEventListener("input", () => renderNavGroups(searchInput.value));

  const detailHost = document.createElement("div");
  detailHost.className = "agent-awn-types-detail-host";
  detailHost.appendChild(renderAwnTypeDetailPanel(selectedEntry.typeDef));

  browser.append(nav, detailHost);
  section.appendChild(browser);

  nav.addEventListener("click", (event) => {
    const tab = event.target.closest(".agent-awn-type-nav-item");
    if (!tab?.dataset.typeKey || tab.dataset.typeKey === awnTypesSelectedKey) return;
    awnTypesSelectedKey = tab.dataset.typeKey;
    nav.querySelectorAll(".agent-awn-type-nav-item").forEach((node) => {
      const isActive = node.dataset.typeKey === awnTypesSelectedKey;
      node.classList.toggle("is-active", isActive);
      node.setAttribute("aria-selected", isActive ? "true" : "false");
    });
    const nextEntry = typeEntries.find((entry) => entry.typeKey === awnTypesSelectedKey);
    if (nextEntry) {
      detailHost.replaceChildren(renderAwnTypeDetailPanel(nextEntry.typeDef));
    }
  });

  return section;
}

async function renderAgentAwnTypesView({ forceReload = false } = {}) {
  if (!agentAwnTypesContentNode) return;
  if (forceReload) {
    awnTypesCache = null;
    awnTypesLoadPromise = null;
  }
  await loadAwnTypes(activeWorkspaceId);
  await renderAwnTypesContent(agentAwnTypesContentNode);
}

async function renderAwnTypesContent(containerNode, { agentId = activeWorkspaceId } = {}) {
  if (!containerNode) return;
  containerNode.innerHTML = "";

  if (!agentId) {
    renderListEmptyMessage(
      containerNode,
      "Выберите агента в меню слева — схемы подгружаются в контексте workspace."
    );
    return;
  }

  let allTypesData = null;
  try {
    const res = await fetch(buildApiUrl("/api/type-catalog", {}, agentId));
    if (res.ok) {
      const catalog = await res.json();
      setAwnTypeKindManifest(catalog.kinds);
      const types = (catalog.types || []).map((t) => ({
        id: t.id,
        name: t.name || t.id,
        kind: t.kind || t.schema?.kind || "type",
        domain: t.domain || "",
        extends: t.extends || null,
        status: t.status || "active",
        description: t.schema?.description || t.description || "",
        source: t.source || "platform",
        fields: t.schema?.fields || null,
        widget: t.schema?.widget || t.widget || null,
        storage: t.schema?.storage || t.storage || null,
        mdbase: t.schema?.mdbase || t.mdbase || null,
        settings: t.schema?.settings || t.settings || null
      }));
      allTypesData = { types, total: types.length };
    }
  } catch {}

  if (!allTypesData?.types?.length) {
    renderListEmptyMessage(containerNode, "Типы не найдены. Проверьте awn-system/types/.");
    return;
  }

  // Convert flat array → typeEntries format { typeKey, typeDef }
  const typeEntries = allTypesData.types.map((t) => ({
    typeKey: t.id,
    typeDef: t
  }));

  containerNode.appendChild(createAwnTypesBrowserSection(typeEntries));
}

let agentSchemaSizeSeq = 0;

async function fetchAgentTopicSizes() {
  const response = await fetch(buildApiUrl("/api/agent/topic-sizes"));
  if (!response.ok) {
    const errorData = await response.json().catch(() => ({}));
    throw new Error(errorData.error || `HTTP ${response.status}`);
  }
  return response.json();
}

function buildAgentSchemaSizeLookup(byPath = {}, { loading = false } = {}) {
  const lookup = { __loading: loading };
  for (const [manifestPath, meta] of Object.entries(byPath || {})) {
    lookup[manifestPath] = { ...meta, loading: false };
  }
  return lookup;
}

function renderAgentSchemaSizeChart(ranking = [], totalTopicBytes = 0) {
  const section = document.createElement("section");
  section.className = "agent-schema-size-chart";
  section.setAttribute("aria-label", "Сравнение тем по объёму");

  const head = document.createElement("header");
  head.className = "agent-schema-size-chart-head";
  const title = document.createElement("h3");
  title.className = "agent-schema-size-chart-title";
  title.textContent = "Темы по объёму";
  const note = document.createElement("p");
  note.className = "agent-schema-size-chart-note";
  note.textContent = "Сравниваются только темы; у областей — сумма вложенных тем.";
  head.append(title, note);
  section.appendChild(head);

  if (!ranking.length) {
    const empty = document.createElement("p");
    empty.className = "agent-schema-size-chart-empty";
    empty.textContent = "Нет тем для сравнения";
    section.appendChild(empty);
    return section;
  }

  const maxBytes = Math.max(...ranking.map((item) => Number(item.bytes) || 0), 1);
  const list = document.createElement("div");
  list.className = "agent-schema-size-chart-list";

  for (const item of ranking.slice(0, 16)) {
    const row = document.createElement("div");
    row.className = "agent-schema-size-chart-row";

    const label = document.createElement("span");
    label.className = "agent-schema-size-chart-label";
    label.textContent = item.label || getLabelFromPath(item.manifestPath);
    label.title = item.manifestPath || "";

    const track = document.createElement("div");
    track.className = "agent-schema-size-chart-bar-track";
    track.setAttribute("role", "presentation");
    const fill = document.createElement("div");
    fill.className = "agent-schema-size-chart-bar-fill";
    const percent = Math.max(4, Math.round(((Number(item.bytes) || 0) / maxBytes) * 100));
    fill.style.width = `${percent}%`;
    track.appendChild(fill);

    const value = document.createElement("span");
    value.className = "agent-schema-size-chart-value";
    value.textContent = item.sizeLabel || formatFileSize(item.bytes || 0);
    if (totalTopicBytes > 0) {
      const share = Math.round(((Number(item.bytes) || 0) / totalTopicBytes) * 100);
      value.title = `${share}% от суммарного объёма тем`;
    }

    row.append(label, track, value);
    list.appendChild(row);
  }

  section.appendChild(list);
  return section;
}

function syncAgentRoadmapMapViewNotesVisibility() {
  document.querySelectorAll("[data-rmm-view-notes]").forEach((panel) => {
    const match = panel.dataset.rmmViewNotes === agentRoadmapMapSubview;
    panel.classList.toggle("hidden", !match);
  });
}

function clearAgentRoadmapMapLiveTimers() {
  if (agentRoadmapMapLiveBrainUnmount) {
    agentRoadmapMapLiveBrainUnmount();
    agentRoadmapMapLiveBrainUnmount = null;
  }
}

function renderAgentRoadmapMapView() {
  if (!agentRoadmapMapHostNode) return;
  ensureAgentRoadmapMapUiBindings();
  syncAgentRoadmapMapViewNotesVisibility();
  applyAgentGraphSettingsUi();
  clearAgentRoadmapMapLiveTimers();
  const renderSeq = ++agentRoadmapMapRenderSeq;
  agentRoadmapMapHostNode?.classList.toggle("agent-rmm-host--live-solo", agentRoadmapMapSubview === "live");
  agentRoadmapMapHostNode.replaceChildren();
  agentRoadmapMapDetailNode?.classList.add("hidden");
  agentRoadmapMapViewportApi = null;
  agentRoadmapMapPaneNode?.classList.toggle("agent-rmm-subview-live", agentRoadmapMapSubview === "live");
  const showZoom =
    agentRoadmapMapSubview === "graph" ||
    agentRoadmapMapSubview === "mindmap" ||
    agentRoadmapMapSubview === "live";
  agentRoadmapMapZoomNode?.classList.toggle("hidden", !showZoom);
  const graphChrome = document.getElementById("agent-rmm-graph-chrome");
  const showGraphToolbar = agentRoadmapMapSubview === "graph";
  graphChrome?.classList.toggle("hidden", !showGraphToolbar);
  graphChrome?.setAttribute("aria-hidden", showGraphToolbar ? "false" : "true");

  if (agentRoadmapMapSubview === "toc" || agentRoadmapMapSubview === "kanban") {
    renderAgentRoadmapMapPlaceholderSubview(agentRoadmapMapHostNode);
    return;
  }

  if (!currentMenuData) {
    renderListEmptyMessage(agentRoadmapMapHostNode, "Дерево агента ещё не загружено");
    return;
  }

  applyAgentGraphSettingsUi();
  if (agentRoadmapMapSubview === "live") {
    void renderAgentRoadmapMapLiveView(renderSeq);
    return;
  }
  if (agentRoadmapMapSubview === "graph") {
    void renderAgentRoadmapMapGraphView(renderSeq);
    return;
  }
  if (agentRoadmapMapSubview === "mindmap") {
    void renderAgentRoadmapMapMindmapView(renderSeq);
    return;
  }
  void renderAgentRoadmapMapRoadmapView(renderSeq);
}

