function handleAgentGraphNodeClick(node) {
  if (node?.nodePath) {
    openNodeFromMenu(getLabelFromPath(node.nodePath), node.nodePath);
    return;
  }
  const target = node?.graphTarget;
  if (!target) return;
  if (
    target.kind === "repository-index" ||
    target.kind === "iblock-index" ||
    target.kind === "media-library-index" ||
    target.kind === "channel-index"
  ) {
    if (target.kind === "media-library-index") {
      void openMediaLibraryIndexOverview();
      return;
    }
    if (target.kind === "channel-index") {
      void openAwnChannelsIndexOverview();
      return;
    }
    void openWorkspaceFilePreviewByRelPath(String(target.path || "").replace(/\\/g, "/"));
    return;
  }
  if (target.kind === "repository") {
    void openRepositoryWorkspacePath(String(target.path || "").replace(/\\/g, "/"));
    return;
  }
  if (target.kind === "media-library") {
    void openMediaLibraryWorkspacePath(String(target.path || "").replace(/\\/g, "/"));
    return;
  }
  if (target.kind === "channel") {
    void openAwnChannelWorkspacePath(String(target.path || "").replace(/\\/g, "/"));
    return;
  }
  if (target.kind === "iblock" && target.storeRel) {
    void openAwnDataViewPage(target.storeRel);
  }
}

function isGraphReservedSubtreeEntry(entry, menu) {
  if (!entry?.path) return false;
  const normalized = normalizeMenuNodePath(entry.path);
  const kitFolder = getActiveAgentKitFolder();
  const containerFolder = getActiveAgentContainerFolder();
  if (menu?.serviceTree && kitFolder) {
    const kitManifest = normalizeMenuNodePath(getServiceRootManifestPath());
    if (normalized === kitManifest || normalized === kitFolder || normalized.startsWith(`${kitFolder}/`)) {
      return true;
    }
  }
  if (menu?.containerTree && containerFolder) {
    const containerManifest = normalizeMenuNodePath(getContainerRootManifestPath());
    if (
      normalized === containerManifest ||
      normalized === containerFolder ||
      normalized.startsWith(`${containerFolder}/`)
    ) {
      return true;
    }
  }
  return false;
}

function getServiceGraphRelativePath(entry) {
  const rawDisplay = entry?.displayPath || (entry?.path ? getNodeDisplayPath(entry.path) : "");
  const stripped = stripGraphKitFolderPrefix(stripServicePrefixFromRelPath(rawDisplay));
  if (stripped) return stripped.replace(/\\/g, "/").trim();
  return stripGraphKitFolderPrefix(stripServicePrefixFromRelPath(entry?.path || "")).replace(/\\/g, "/").trim();
}

function getContainerGraphRelativePath(entry) {
  const rawDisplay = entry?.displayPath || (entry?.path ? getNodeDisplayPath(entry.path) : "");
  const stripped = stripGraphContainerFolderPrefix(String(rawDisplay || entry?.path || ""));
  return stripped.replace(/\\/g, "/").trim();
}

function getScopedGraphRelativePath(entry, scopePrefix) {
  if (scopePrefix === "service") return getServiceGraphRelativePath(entry);
  if (scopePrefix === "container") return getContainerGraphRelativePath(entry);
  if (entry?.path) {
    const routePath = getNodeRoutePath(entry.path);
    if (routePath) return routePath.replace(/\\/g, "/").trim();
  }
  return String(entry.displayPath || entry.label || getLabelFromPath(entry.path)).replace(/\\/g, "/").trim();
}

function resolveGraphIntermediateFolderLabel(entries, relPath, fallback, scopePrefix) {
  for (const entry of entries) {
    if (!entry?.isFolder || !entry.path) continue;
    const entryRel = getScopedGraphRelativePath(entry, scopePrefix);
    if (entryRel !== relPath) continue;
    return resolveGraphEntryLabel(entry);
  }

  const fromManifest = resolveGraphAreaLabelFromRel(relPath, scopePrefix);
  if (fromManifest) return fromManifest;

  const mapped = getMenuDisplayLabelMap().get(relPath);
  if (mapped) return mapped;

  return fallback;
}

function buildGraphDataFromAgentMenu(
  menu,
  {
    repositoriesPayload = null,
    awnDataPayload = null,
    mediaLibrariesPayload = null,
    channelsPayload = null,
    pageIndexPayload = null
  } = {}
) {
  const manifestMetaMap = buildGraphManifestMetaMap(pageIndexPayload);
  const baseTree = getWorkspaceRootMenuTreeNode(menu);
  const workspaceEntries = collectFlatMenuEntries(baseTree);
  const serviceEntries = menu?.serviceTree
    ? collectFlatMenuEntries({ title: "", ...menu.serviceTree })
    : [];
  const containerEntries = menu?.containerTree && getActiveAgentContainerFolder()
    ? collectFlatMenuEntries({ title: "", ...menu.containerTree })
    : [];

  const previewByDisplayPath = new Map();
  for (const entry of workspaceEntries) {
    if (!entry.previewUrl) continue;
    const displayPath = entry.displayPath || getNodeDisplayPath(entry.path);
    if (!displayPath) continue;
    previewByDisplayPath.set(displayPath, entry.previewUrl);
  }
  for (const entry of serviceEntries) {
    if (!entry.previewUrl) continue;
    const displayPath = getServiceGraphRelativePath(entry);
    if (!displayPath) continue;
    previewByDisplayPath.set(displayPath, entry.previewUrl);
    previewByDisplayPath.set(`service/${displayPath}`, entry.previewUrl);
  }
  for (const entry of containerEntries) {
    if (!entry.previewUrl) continue;
    const displayPath = getContainerGraphRelativePath(entry);
    if (!displayPath) continue;
    previewByDisplayPath.set(displayPath, entry.previewUrl);
    previewByDisplayPath.set(`container/${displayPath}`, entry.previewUrl);
  }

  const rootId = "agent-root";
  const rootNode = {
    id: rootId,
    label: getAgentTreeTitle(),
    type: "folder",
    depth: 0,
    nodePath: baseTree.indexPath || null,
    previewUrl: baseTree.hasPreview ? baseTree.previewUrl || null : null
  };
  applyGraphNodeRecordMeta(rootNode, { manifestPath: baseTree.indexPath, metaMap: manifestMetaMap });
  const nodes = [rootNode];
  const edges = [];
  const folderIds = new Map([["", rootId]]);
  const nodeIds = new Set([rootId]);
  const skipNormalizedPaths = new Set();
  if (baseTree.indexPath) {
    skipNormalizedPaths.add(normalizeMenuNodePath(baseTree.indexPath));
  }

  let serviceRootId = null;
  if (menu?.serviceTree && getActiveAgentKitFolder()) {
    serviceRootId = "service-root";
    const serviceManifestPath = menu.serviceTree.indexPath || getServiceRootManifestPath();
    if (serviceManifestPath) {
      skipNormalizedPaths.add(normalizeMenuNodePath(serviceManifestPath));
    }
    nodes.push({
      id: serviceRootId,
      label: getServiceRootMenuTitle(),
      type: "folder",
      depth: 1,
      nodePath: serviceManifestPath || null,
      previewUrl: menu.serviceTree.hasPreview ? menu.serviceTree.previewUrl || null : null
    });
    applyGraphNodeRecordMeta(nodes[nodes.length - 1], {
      manifestPath: serviceManifestPath,
      metaMap: manifestMetaMap
    });
    edges.push({ from: rootId, to: serviceRootId });
    folderIds.set("service/", serviceRootId);
    nodeIds.add(serviceRootId);
  }

  let containerRootId = null;
  if (menu?.containerTree && getActiveAgentContainerFolder()) {
    containerRootId = "container-root";
    const containerManifestPath = menu.containerTree.indexPath || getContainerRootManifestPath();
    if (containerManifestPath) {
      skipNormalizedPaths.add(normalizeMenuNodePath(containerManifestPath));
    }
    nodes.push({
      id: containerRootId,
      label: getContainerRootMenuTitle(),
      type: "folder",
      depth: 1,
      nodePath: containerManifestPath || null,
      previewUrl: menu.containerTree.hasPreview ? menu.containerTree.previewUrl || null : null
    });
    applyGraphNodeRecordMeta(nodes[nodes.length - 1], {
      manifestPath: containerManifestPath,
      metaMap: manifestMetaMap
    });
    edges.push({ from: rootId, to: containerRootId });
    folderIds.set("container/", containerRootId);
    nodeIds.add(containerRootId);
  }

  // Области (_registration.md) уже есть в меню — не создавать вторую «пустую» folder:path для того же displayPath.
  for (const entry of workspaceEntries) {
    if (!entry.isFolder || !entry.path) continue;
    if (skipNormalizedPaths.has(normalizeMenuNodePath(entry.path))) continue;
    if (isGraphReservedSubtreeEntry(entry, menu)) continue;
    const displayPath = String(entry.displayPath || entry.label || getLabelFromPath(entry.path))
      .replace(/\\/g, "/")
      .trim();
    if (!displayPath) continue;
    folderIds.set(displayPath, `node:${normalizeMenuNodePath(entry.path)}`);
  }
  for (const entry of serviceEntries) {
    if (!entry.isFolder || !entry.path) continue;
    const rel = getServiceGraphRelativePath(entry);
    if (!rel) continue;
    folderIds.set(`service/${rel}`, `node:${normalizeMenuNodePath(entry.path)}`);
  }
  for (const entry of containerEntries) {
    if (!entry.isFolder || !entry.path) continue;
    const rel = getContainerGraphRelativePath(entry);
    if (!rel) continue;
    folderIds.set(`container/${rel}`, `node:${normalizeMenuNodePath(entry.path)}`);
  }

  const appendGraphMenuEntries = (entries, { parentRootId, scopePrefix = null }) => {
    for (const entry of entries) {
      const normPath = entry.path ? normalizeMenuNodePath(entry.path) : null;
      if (normPath && skipNormalizedPaths.has(normPath)) continue;
      if (!scopePrefix && isGraphReservedSubtreeEntry(entry, menu)) continue;

      const displayPath = getScopedGraphRelativePath(entry, scopePrefix);
      if (!displayPath) continue;
      const parts = String(displayPath).split("/").filter(Boolean);
      if (!parts.length) continue;
      let parentId = parentRootId;

      for (let i = 0; i < parts.length - 1; i += 1) {
        const built = scopePrefix
          ? `${scopePrefix}/${parts.slice(0, i + 1).join("/")}`
          : parts.slice(0, i + 1).join("/");
        if (!folderIds.has(built)) {
          const folderId = `folder:${built}`;
          const relPath = parts.slice(0, i + 1).join("/");
          nodes.push({
            id: folderId,
            label: resolveGraphIntermediateFolderLabel(entries, relPath, parts[i], scopePrefix),
            type: "folder",
            depth: (scopePrefix ? 1 : 0) + i + 1,
            nodePath: null,
            previewUrl: resolveGraphFolderPreviewUrl(previewByDisplayPath, scopePrefix, parts, i)
          });
          edges.push({ from: parentId, to: folderId });
          folderIds.set(built, folderId);
          nodeIds.add(folderId);
        }
        parentId = folderIds.get(built);
      }

      const nodeId = `node:${normalizeMenuNodePath(entry.path)}`;
      if (!nodeIds.has(nodeId)) {
        const nodeFields = {
          id: nodeId,
          label: resolveGraphEntryLabel(entry),
          type: entry.isFolder ? "folder" : "file",
          depth: Math.max((scopePrefix ? 1 : 0) + parts.length, scopePrefix ? 2 : 1),
          nodePath: entry.path,
          previewUrl: entry.previewUrl || null
        };
        applyGraphNodeRecordMeta(nodeFields, { manifestPath: entry.path, entry, metaMap: manifestMetaMap });
        nodes.push(nodeFields);
        nodeIds.add(nodeId);
      }
      edges.push({ from: parentId, to: nodeId });
    }
  };

  appendGraphMenuEntries(workspaceEntries, { parentRootId: rootId });
  if (serviceRootId) {
    appendGraphMenuEntries(serviceEntries, { parentRootId: serviceRootId, scopePrefix: "service" });
  }
  if (containerRootId) {
    appendGraphMenuEntries(containerEntries, { parentRootId: containerRootId, scopePrefix: "container" });
  }

  appendAgentGraphRepositoriesBranch({ nodes, edges, nodeIds, rootId, repositoriesPayload });
  appendAgentGraphAwnDataBranch({ nodes, edges, nodeIds, rootId, awnDataPayload });
  appendAgentGraphMediaLibrariesBranch({ nodes, edges, nodeIds, rootId, mediaLibrariesPayload });
  appendAgentGraphChannelsBranch({ nodes, edges, nodeIds, rootId, channelsPayload });

  return { nodes, edges };
}

