function formatNotFoundRequestPath(requestedPath = "") {
  const raw = String(requestedPath || "").trim();
  if (raw) {
    if (raw.startsWith("/")) return raw;
    return `/${raw.replace(/^\/+/, "")}`;
  }
  return `${location.pathname}${location.search}${location.hash}`;
}

