function getMenuScrollSnapshot() {
  const sidebar = document.querySelector(".sidebar");
  const menuScrollShell = document.querySelector(".sidebar-slab-menu .menu-scroll-shell");
  return {
    sidebar: sidebar?.scrollTop ?? 0,
    shell: menuScrollShell?.scrollTop ?? 0
  };
}

function restoreMenuScrollSnapshot(snapshot) {
  if (!snapshot) return;
  const sidebar = document.querySelector(".sidebar");
  const menuScrollShell = document.querySelector(".sidebar-slab-menu .menu-scroll-shell");
  if (sidebar) sidebar.scrollTop = snapshot.sidebar;
  if (menuScrollShell) menuScrollShell.scrollTop = snapshot.shell;
}

function scheduleMenuScrollRestore(snapshot) {
  restoreMenuScrollSnapshot(snapshot);
  requestAnimationFrame(() => {
    restoreMenuScrollSnapshot(snapshot);
    requestAnimationFrame(() => restoreMenuScrollSnapshot(snapshot));
  });
  window.setTimeout(() => restoreMenuScrollSnapshot(snapshot), 0);
}

function withPreservedMenuScroll(run) {
  const snapshot = getMenuScrollSnapshot();
  const result = run();
  scheduleMenuScrollRestore(snapshot);
  return result;
}

async function preserveMenuScrollDuring(asyncWork) {
  const snapshot = getMenuScrollSnapshot();
  try {
    return await asyncWork();
  } finally {
    scheduleMenuScrollRestore(snapshot);
  }
}

const MENU_SCROLL_TOP_THRESHOLD = 48;
const SCROLL_TOP_DRAG_MAX_RADIUS_PX = 100;
const SCROLL_TOP_DRAG_CLICK_THRESHOLD_PX = 6;

function constrainScrollTopOffset(offset, maxRadius = SCROLL_TOP_DRAG_MAX_RADIUS_PX) {
  let x = Math.max(0, Number(offset.x) || 0);
  let y = Math.max(0, Number(offset.y) || 0);
  const radius = Math.hypot(x, y);
  if (radius > maxRadius && radius > 0) {
    const scale = maxRadius / radius;
    x *= scale;
    y *= scale;
  }
  return { x, y };
}

function applyScrollTopButtonOffset(button, offset = { x: 0, y: 0 }) {
  if (!button) return;
  button.style.setProperty("--scroll-top-shift-x", `${offset.x}px`);
  button.style.setProperty("--scroll-top-shift-y", `${offset.y}px`);
}

function setupDraggableScrollTopButton(
  button,
  { maxRadius = SCROLL_TOP_DRAG_MAX_RADIUS_PX, onActivate } = {}
) {
  if (!button) return;

  let offset = { x: 0, y: 0 };
  applyScrollTopButtonOffset(button, offset);

  let dragState = null;
  let suppressClick = false;

  button.addEventListener("pointerdown", (event) => {
    if (!button.classList.contains("is-visible")) return;
    if (event.button !== 0) return;
    dragState = {
      pointerId: event.pointerId,
      startX: event.clientX,
      startY: event.clientY,
      baseX: offset.x,
      baseY: offset.y,
      moved: false
    };
    button.setPointerCapture(event.pointerId);
  });

  button.addEventListener("pointermove", (event) => {
    if (!dragState || event.pointerId !== dragState.pointerId) return;
    const deltaX = dragState.startX - event.clientX;
    const deltaY = dragState.startY - event.clientY;
    if (!dragState.moved && Math.hypot(deltaX, deltaY) < SCROLL_TOP_DRAG_CLICK_THRESHOLD_PX) return;
    dragState.moved = true;
    button.classList.add("is-dragging");
    event.preventDefault();
    offset = constrainScrollTopOffset(
      {
        x: dragState.baseX + deltaX,
        y: dragState.baseY + deltaY
      },
      maxRadius
    );
    applyScrollTopButtonOffset(button, offset);
  });

  const finishDrag = (event) => {
    if (!dragState || event.pointerId !== dragState.pointerId) return;
    if (dragState.moved) suppressClick = true;
    dragState = null;
    button.classList.remove("is-dragging");
    try {
      button.releasePointerCapture(event.pointerId);
    } catch {
      /* ignore */
    }
  };

  button.addEventListener("pointerup", finishDrag);
  button.addEventListener("pointercancel", finishDrag);

  button.addEventListener("click", (event) => {
    if (suppressClick) {
      event.preventDefault();
      event.stopImmediatePropagation();
      suppressClick = false;
      return;
    }
    onActivate?.();
  });
}

window.setupDraggableScrollTopButton = setupDraggableScrollTopButton;

function getScrollMetrics(element) {
  if (!element) {
    return { scrollTop: 0, maxScroll: 0, percent: 0, screens: 0, scrollable: false };
  }
  const scrollTop = Math.max(0, element.scrollTop || 0);
  const maxScroll = Math.max(0, element.scrollHeight - element.clientHeight);
  const percent = maxScroll > 0 ? Math.round((scrollTop / maxScroll) * 100) : 0;
  const screens = element.clientHeight > 0 ? scrollTop / element.clientHeight : 0;
  return {
    scrollTop,
    maxScroll,
    percent,
    screens,
    scrollable: maxScroll > 8
  };
}

function formatScrollDepthLabel(metrics) {
  if (!metrics?.scrollable || metrics.percent <= 0) return "";
  return `${metrics.percent}%`;
}

function syncScrollChrome({
  scrollElement,
  topButton,
  progressNode,
  depthNode,
  chromeNode = null,
  topThreshold = MENU_SCROLL_TOP_THRESHOLD
} = {}) {
  if (!scrollElement) {
    if (topButton) {
      topButton.classList.remove("is-visible");
      topButton.setAttribute("aria-hidden", "true");
      topButton.tabIndex = -1;
    }
    if (progressNode) {
      progressNode.style.width = "0%";
    }
    if (depthNode) {
      depthNode.textContent = "";
      depthNode.classList.add("hidden");
    }
    if (chromeNode) {
      chromeNode.classList.remove("is-active");
    }
    return;
  }
  const metrics = getScrollMetrics(scrollElement);
  const depthLabel = formatScrollDepthLabel(metrics);
  const showTop = metrics.scrollable && metrics.scrollTop > topThreshold;

  if (topButton) {
    topButton.classList.toggle("is-visible", showTop);
    topButton.setAttribute("aria-hidden", showTop ? "false" : "true");
    topButton.tabIndex = showTop ? 0 : -1;
  }
  if (progressNode) {
    progressNode.style.width = `${metrics.percent}%`;
  }
  if (depthNode) {
    depthNode.textContent = depthLabel;
    depthNode.classList.toggle("hidden", !depthLabel);
  }
  if (chromeNode) {
    chromeNode.classList.toggle("is-active", metrics.scrollable && metrics.percent > 0);
  }
}

