async function registerMenuAwnChannel(payload = {}, agentId = activeWorkspaceId, options = {}) {
  const slug = String(payload.slug || "").trim();
  if (!slug) return null;
  const resolvedAgent = String(agentId || activeWorkspaceId || "").trim();
  if (!resolvedAgent) {
    showToast("Выберите агента", "error");
    return null;
  }
  const response = await fetch(buildApiUrl("/api/agent/channels", {}, resolvedAgent), {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      slug,
      ...(payload.name ? { name: payload.name } : {}),
      ...(payload.description ? { description: payload.description } : {})
    })
  });
  const data = await response.json().catch(() => ({}));
  if (!response.ok) {
    throw new Error(data.error || data.details || `HTTP ${response.status}`);
  }
  if (!options.skipAutoOpen && data.path) {
    await openAwnChannelWorkspaceEntry(
      {
        slug,
        name: payload.name || slug,
        folderPath: data.folderPath || `awn-channels/${slug}`,
        manifestPath: data.path,
        registered: true
      },
      { skipRouteSync: true }
    );
  }
  return data;
}

