function formatAwnDataIndexEntriesMarkdown(entries, { emptyHint = "_Нет накопителей для оглавления._" } = {}) {
  return formatStorageIndexEntriesMarkdown(entries, { emptyHint, tableVariant: "awn-databases" });
}

function formatAwnDataIndexPayloadAsMarkdown(payload) {
  const entries = (payload?.entries || []).map((entry) => {
    const workspacePath = resolveAwnDataIndexWorkspacePath(entry);
    const storeRel = workspacePath.replace(/^awn-databases\/?/, "");
    return {
    ...entry,
    type: resolveAwnDataIndexTypeKey(entry),
    kind: entry.kind || resolveAwnDataIndexTypeKey(entry),
    path: workspacePath,
    group: entry.group || "—",
    linkPath:
      entry.linkPath ||
      (storeRel ? `awn-databases/${storeRel}/manifest.md`.replace(/\/+/g, "/") : ""),
    recordCount: Number.isFinite(Number(entry.recordCount)) ? Number(entry.recordCount) : 0,
    childCount: Number.isFinite(Number(entry.childCount)) ? Number(entry.childCount) : 0,
    subsections: entry.subsections || formatStorageIndexSubsectionsCell(entry),
    storageDriver: entry.storageDriver || entry.configurations || "—",
    fileTypes: entry.fileTypes || "—",
    configurations: entry.configurations || "—"
  };
  });
  const lines = ["# Оглавление инфоблоков", "", formatAwnDataIndexEntriesMarkdown(entries)];
  appendContentIndexLegends(lines, { includeLinesLegend: true });
  return lines.join("\n").trimEnd();
}

async function fetchAwnDataIndexMarkdownFromApi(agentId = activeWorkspaceId) {
  const resolvedAgent = String(agentId || activeWorkspaceId || "").trim();
  const response = await fetch(buildApiUrl("/api/agent/awn-databases-index", {}, resolvedAgent));
  if (!response.ok) {
    const errorData = await response.json().catch(() => ({}));
    throw new Error(errorData.error || errorData.details || `awn-databases-index ${response.status}`);
  }
  const payload = await response.json();
  if (payload.markdown) {
    return payload.markdown.endsWith("\n") ? payload.markdown : `${payload.markdown}\n`;
  }
  return `${formatAwnDataIndexPayloadAsMarkdown(payload)}\n`;
}

let awnDataIndexPreviewOverride = null;

async function openAwnDataIndexOverview(agentId = activeWorkspaceId) {
  const resolvedAgent = String(agentId || activeWorkspaceId || "").trim();
  if (!resolvedAgent) {
    showToast("Выберите агента", "error");
    return;
  }
  const relPath = getAwnDataIndexRelPath();
  awnDataIndexPreviewOverride = null;
  if (!(await probeAwnDataIndexExists(resolvedAgent))) {
    try {
      awnDataIndexPreviewOverride = await fetchAwnDataIndexMarkdownFromApi(resolvedAgent);
    } catch (error) {
      showToast(`Не удалось сформировать оглавление: ${error.message}`, "error");
      return;
    }
  }
  hideHomeView();
  await openFolderBrowseFile("Оглавление инфоблоков", relPath, {
    folderPath: "awn-databases",
    agentId: resolvedAgent
  });
  void renderFolderBrowseFileView();
}

async function refreshAwnDataIndexOverview(agentId = activeWorkspaceId) {
  const resolvedAgent = String(agentId || activeWorkspaceId || "").trim();
  if (!resolvedAgent) {
    throw new Error("Выберите агента");
  }
  const response = await fetch(buildApiUrl("/api/agent/awn-databases-index", {}, resolvedAgent), {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ overwrite: true })
  });
  if (!response.ok) {
    const errorData = await response.json().catch(() => ({}));
    throw new Error(errorData.error || errorData.details || `awn-databases-index ${response.status}`);
  }
  awnDataIndexPreviewOverride = null;
  return true;
}

