function formatRussianFileCount(count) {
  const n = Number(count) || 0;
  const abs = Math.abs(n) % 100;
  const last = abs % 10;
  if (abs >= 11 && abs <= 14) return `${n} файлов`;
  if (last === 1) return `${n} файл`;
  if (last >= 2 && last <= 4) return `${n} файла`;
  return `${n} файлов`;
}

