function resolveGoogleDriveSyncMenuTriggerState(status) {
  if (!status?.exists) {
    return {
      label: MEDIA_CLOUD_TRIGGER_LABEL,
      badge: "",
      title: "Файл не найден",
      synced: false
    };
  }
  const count = Array.isArray(status.providers) ? status.providers.length : 0;
  const synced = Boolean(status.synced && count > 0);
  const title = synced
    ? count === 1
      ? "Файл в облаке (1 сервис). Откройте меню для другого сервиса или возврата."
      : `Файл в облаке (${count} сервиса). Откройте меню.`
    : "Выгрузка в облако — выберите сервис в меню.";
  return {
    label: MEDIA_CLOUD_TRIGGER_LABEL,
    badge: synced ? String(count) : "",
    title,
    synced
  };
}

function resolveMediaCloudSyncToastMessage(result, runtimeConfig, providerId) {
  const providerTitle = resolveMediaCloudProviderTitle(runtimeConfig, providerId);
  if (result.action === "provider-removed" || result.action === "unsynced" || !result.synced) {
    return `Файл убран из облака «${providerTitle}»`;
  }
  return `Файл добавлен в облако «${providerTitle}»`;
}

function setGoogleDriveSyncMenuOpen(bar, open) {
  if (!bar) return;
  const panel = bar.querySelector(".node-gdrive-sync-menu-panel");
  const trigger = bar.querySelector(".node-gdrive-sync-menu-trigger");
  if (!panel || !trigger) return;
  const nextOpen = Boolean(open);
  panel.hidden = !nextOpen;
  trigger.setAttribute("aria-expanded", nextOpen ? "true" : "false");
  bar.classList.toggle("is-open", nextOpen);
}

function bindGoogleDriveSyncMenuDismiss(bar) {
  if (!bar || bar._cloudMenuDismissBound) return;
  bar._cloudMenuDismissBound = true;
  if (window._mediaCloudMenuDismissBound) return;
  window._mediaCloudMenuDismissBound = true;
  document.addEventListener(
    "click",
    (event) => {
      document.querySelectorAll(".node-gdrive-sync-bar.is-open").forEach((openBar) => {
        if (!openBar.contains(event.target)) {
          setGoogleDriveSyncMenuOpen(openBar, false);
        }
      });
    },
    true
  );
  document.addEventListener("keydown", (event) => {
    if (event.key !== "Escape") return;
    document.querySelectorAll(".node-gdrive-sync-bar.is-open").forEach((openBar) => {
      setGoogleDriveSyncMenuOpen(openBar, false);
    });
  });
}

function resolveCloudSyncConfigForWorkspaceFile(relPath) {
  const filePath = String(relPath || "").replace(/\\/g, "/").replace(/^\/+/, "").trim();
  let manifestPath = filePath;
  const storageMarker = "/awn-storage/";
  const storageIdx = filePath.indexOf(storageMarker);
  if (storageIdx > 0) {
    manifestPath = `${filePath.slice(0, storageIdx)}/manifest.md`;
  }
  return {
    scope: "file",
    manifestPath,
    filePath
  };
}

async function fetchGoogleDriveSyncStatus({ scope = "file", manifestPath, filePath = null, providerId = null } = {}) {
  const params = { path: manifestPath, scope };
  if (scope === "file" && filePath) params.file = filePath;
  if (scope === "file" && providerId) params.provider = providerId;
  const response = await fetch(buildApiUrl("/api/gdrive/status", params));
  if (!response.ok) {
    const errorData = await response.json().catch(() => ({}));
    throw new Error(errorData.error || `HTTP ${response.status}`);
  }
  return response.json();
}

async function toggleGoogleDriveSyncRequest({
  scope = "file",
  manifestPath,
  filePath = null,
  providerId = null
} = {}) {
  const response = await fetch(buildApiUrl("/api/gdrive/toggle"), {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      path: manifestPath,
      scope,
      file: scope === "file" ? filePath : undefined,
      provider: scope === "file" ? providerId : undefined
    })
  });
  if (!response.ok) {
    const errorData = await response.json().catch(() => ({}));
    throw new Error(errorData.error || errorData.details || `HTTP ${response.status}`);
  }
  return response.json();
}

function renderGoogleDriveSyncMenuItems(bar, providers, status) {
  const sendList = bar.querySelector('[data-cloud-menu="send"]');
  const retrieveList = bar.querySelector('[data-cloud-menu="retrieve"]');
  const retrieveGroup = bar.querySelector('[data-cloud-menu-group="retrieve"]');
  if (!sendList || !retrieveList || !retrieveGroup) return;

  const activeIds = new Set(Array.isArray(status?.providers) ? status.providers : []);
  const canSend = Boolean(status?.exists);
  const canRetrieve = Boolean(status?.synced) && activeIds.size > 0;

  sendList.replaceChildren(
    ...providers.map((provider) => {
      const btn = document.createElement("button");
      btn.type = "button";
      btn.className = "node-gdrive-sync-menu-item";
      btn.dataset.providerId = provider.key;
      btn.dataset.cloudAction = "send";
      btn.textContent = provider.title || provider.key;
      const already = activeIds.has(provider.key);
      btn.disabled = !canSend || already;
      if (already) btn.title = "Уже в этом облаке";
      return btn;
    })
  );

  retrieveList.replaceChildren(
    ...providers.map((provider) => {
      const btn = document.createElement("button");
      btn.type = "button";
      btn.className = "node-gdrive-sync-menu-item node-gdrive-sync-menu-item--retrieve";
      btn.dataset.providerId = provider.key;
      btn.dataset.cloudAction = "retrieve";
      btn.textContent = provider.title || provider.key;
      btn.disabled = !canRetrieve || !activeIds.has(provider.key);
      return btn;
    })
  );

  retrieveGroup.classList.toggle("is-empty", !canRetrieve);
}

async function refreshGoogleDriveSyncBar(bar, runtimeConfig = {}) {
  if (!bar) return;
  const triggerLabel = bar.querySelector(".node-gdrive-sync-menu-trigger-label");
  const triggerBadge = bar.querySelector(".node-gdrive-sync-menu-trigger-badge");
  const trigger = bar.querySelector(".node-gdrive-sync-menu-trigger");
  bar.classList.add("is-loading");
  try {
    const status = await fetchGoogleDriveSyncStatus(runtimeConfig);
    bar._cloudSyncStatus = status;
    const triggerState = resolveGoogleDriveSyncMenuTriggerState(status);
    if (triggerLabel) triggerLabel.textContent = triggerState.label;
    if (triggerBadge) {
      triggerBadge.textContent = triggerState.badge || "";
      triggerBadge.classList.toggle("hidden", !triggerState.badge);
    }
    if (trigger) {
      trigger.title = triggerState.title;
      trigger.setAttribute("aria-label", triggerState.title);
      trigger.classList.toggle("is-synced", triggerState.synced);
      trigger.disabled = !status.exists;
    }
    bar.dataset.gdriveSynced = status.synced ? "1" : "0";
    renderGoogleDriveSyncMenuItems(bar, runtimeConfig.providersList || [], status);
  } catch (error) {
    if (triggerLabel) triggerLabel.textContent = MEDIA_CLOUD_TRIGGER_LABEL;
    if (trigger) trigger.title = String(error.message || "Ошибка облака");
  } finally {
    bar.classList.remove("is-loading");
  }
}

async function handleGoogleDriveSyncAction(bar, runtimeConfig = {}, { providerId, action } = {}) {
  if (!bar || bar.classList.contains("is-loading")) return;
  bar.classList.add("is-loading");
  try {
    const config = { ...runtimeConfig, providerId };
    const result = await toggleGoogleDriveSyncRequest(config);
    showToast(resolveMediaCloudSyncToastMessage(result, runtimeConfig, providerId), "success");
    setGoogleDriveSyncMenuOpen(bar, false);
    void refreshMenuGoogleDriveStats();
    if (activeContentMode !== NODE_ENTRY_OVERVIEW_MODE) {
      await refreshMediaListIfVisible();
      rerenderMediaListViewBody();
    }
    await refreshGoogleDriveSyncBar(bar, runtimeConfig);
  } catch (error) {
    showToast(`Облако: ${error.message}`, "error");
    await refreshGoogleDriveSyncBar(bar, runtimeConfig);
  } finally {
    bar.classList.remove("is-loading");
  }
}

function isEntryOverviewOcrCandidate(relativePath) {
  const ext = getEntryOverviewMediaAssetExt(relativePath);
  if (!ext) return false;
  return ENTRY_OVERVIEW_MEDIA_IMAGE_EXTS.has(ext) || ext === ".pdf";
}

function resolveEntryOverviewOcrSourcePath(context = {}) {
  const relPath = String(context.relPath || "").replace(/\\/g, "/").replace(/^\/+/, "");
  if (relPath) return relPath;
  const topicPath = getActiveNodeApiPath() || activePath;
  const memoryKind = context.memoryKind === "assets" ? "assets" : "media";
  const relativePath = String(context.relativePath || "").replace(/\\/g, "/").replace(/^\/+/, "");
  if (!relativePath) return "";
  return getMediaLibraryItemContextPath(relativePath, memoryKind, topicPath);
}

function resolveEntryOverviewOcrBarLabel(extracted = false, failed = false) {
  if (failed) return "OCR не распознан";
  if (extracted) return "OCR выполнен";
  return "Распознать текст (OCR)";
}

