function loadAwnDataViewRecordsLayout() {
  loadAwnDataViewCardsColumns();
  const prefs = readAwnDataViewStoreUiPrefs();
  if (prefs.layout === "table" || prefs.layout === "fields" || prefs.layout === "cards" || prefs.layout === "toc") {
    awnDataViewRecordsLayout = prefs.layout;
    return;
  }
  try {
    const stored = localStorage.getItem(AWN_DATA_VIEW_LAYOUT_STORAGE_KEY);
    if (stored === "table" || stored === "fields" || stored === "cards" || stored === "toc") {
      awnDataViewRecordsLayout = stored;
      return;
    }
    const legacy = localStorage.getItem(AWN_DATA_VIEW_LAYOUT_STORAGE_KEY_LEGACY);
    if (legacy === "table") awnDataViewRecordsLayout = "table";
    else if (legacy === "cards") awnDataViewRecordsLayout = "fields";
  } catch {
    // ignore
  }
}

function saveAwnDataViewRecordsLayout(layout) {
  if (layout !== "table" && layout !== "fields" && layout !== "cards" && layout !== "toc") return;
  if (awnDataViewRecordsLayout === layout) return;
  awnDataViewRecordsLayout = layout;
  saveAwnDataViewStoreUiPrefs("", { layout });
  syncAwnDataViewLayoutToggleUi();
  if (awnDataViewStoreCache && !awnDataViewRecordId) {
    renderAwnDataViewStoreContent(awnDataViewStoreCache, awnDataViewCatalogAgentId || activeWorkspaceId);
  }
  syncAwnDataViewColumnsPickerUi(awnDataViewStoreCache);
}

function saveAwnDataViewCardsLayout(columns) {
  if (!AWN_DATA_VIEW_CARDS_COLUMN_OPTIONS.includes(columns)) return;
  const layoutChanged = awnDataViewRecordsLayout !== "cards";
  const colsChanged = awnDataViewCardsColumns !== columns;
  if (!layoutChanged && !colsChanged) return;
  saveAwnDataViewCardsColumns(columns);
  if (layoutChanged) {
    awnDataViewRecordsLayout = "cards";
    saveAwnDataViewStoreUiPrefs("", { layout: "cards", cardsCols: columns });
  }
  syncAwnDataViewLayoutToggleUi();
  if (awnDataViewStoreCache && !awnDataViewRecordId) {
    renderAwnDataViewStoreContent(awnDataViewStoreCache, awnDataViewCatalogAgentId || activeWorkspaceId);
  }
  syncAwnDataViewColumnsPickerUi(awnDataViewStoreCache);
}

function syncAwnDataViewLayoutToggleUi() {
  if (!awnDataViewLayoutToggleNode) return;
  for (const btn of awnDataViewLayoutToggleNode.querySelectorAll("[data-awn-databases-layout]")) {
    const active = btn.dataset.awnDatabaseLayout === awnDataViewRecordsLayout;
    btn.classList.toggle("is-active", active);
    btn.setAttribute("aria-pressed", active ? "true" : "false");
  }
  for (const btn of awnDataViewLayoutToggleNode.querySelectorAll("[data-awn-databases-cards-cols]")) {
    const cols = Number(btn.dataset.awnDatabaseCardsCols);
    const active = awnDataViewRecordsLayout === "cards" && cols === awnDataViewCardsColumns;
    btn.classList.toggle("is-active", active);
    btn.setAttribute("aria-pressed", active ? "true" : "false");
  }
}

