function normalizeAwnDataDescriptionCompareText(value) {
  return String(value || "")
    .trim()
    .replace(/^#+\s*/, "")
    .replace(/\s+/g, " ")
    .toLowerCase();
}

function stripAwnDataManifestTitleHeading(markdown, title) {
  const text = String(markdown || "").trim();
  const titleNorm = normalizeAwnDataDescriptionCompareText(title);
  if (!text || !titleNorm) return text;

  const lines = text.split("\n");
  let index = 0;
  while (index < lines.length && !lines[index].trim()) index += 1;
  if (index >= lines.length) return "";

  const firstLine = lines[index].trim();
  const h1Match = firstLine.match(/^#\s+(.+)$/);
  if (h1Match && normalizeAwnDataDescriptionCompareText(h1Match[1]) === titleNorm) {
    index += 1;
    while (index < lines.length && !lines[index].trim()) index += 1;
  }

  return lines.slice(index).join("\n").trim();
}

function resolveAwnDataIblockDescriptionMarkdown(store) {
  const title = String(store?.name || store?.schema?.name || "").trim();
  const titleNorm = normalizeAwnDataDescriptionCompareText(title);
  const manifestMarkdown = String(store?.manifestMarkdown || "").trim();

  let markdown = stripAwnDataManifestTitleHeading(manifestMarkdown, title);
  if (!markdown) {
    const schemaDesc = String(store?.description || store?.schema?.description || "").trim();
    if (schemaDesc && normalizeAwnDataDescriptionCompareText(schemaDesc) !== titleNorm) {
      markdown = schemaDesc;
    }
  }

  return markdown.trim();
}

function setAwnDataViewIblockCardVisible(visible) {
  awnDataViewIblockDescriptionBlockNode?.classList.toggle("hidden", !visible);
}

function resolveAwnDataStoreManifestRelPath(store) {
  const explicit = String(store?.manifestRelPath || "").replace(/\\/g, "/").trim();
  if (explicit) return explicit;
  const rel = String(store?.relPath || awnDataViewStoreRel || "")
    .replace(/\\/g, "/")
    .replace(/^\/+/, "")
    .replace(/\/+$/, "");
  if (!rel) return "";
  if (/\/manifest\.md$/i.test(rel)) return rel.startsWith("awn-databases/") ? rel : `awn-databases/${rel}`;
  return `awn-databases/${rel}/manifest.md`;
}

function resolveAwnDataCommentsContext(store, record = null) {
  const manifestPath = resolveAwnDataStoreManifestRelPath(store);
  if (!manifestPath) return null;
  const viewStore = normalizeAwnDataStoreView(store || {});
  const storeTitle = String(viewStore.name || viewStore.relPath || "инфоблок").trim();

  if (!record) {
    return {
      manifestPath,
      mode: "description",
      file: null,
      nodeTitle: storeTitle
    };
  }

  const recordTitle = String(record.title || record.id || "запись").trim();
  if (isAwnDataSingleCsvStore(viewStore)) {
    const csvFile = String(viewStore.recordFile || "main.csv").trim() || "main.csv";
    return {
      manifestPath,
      mode: "container",
      file: csvFile,
      nodeTitle: `${recordTitle} · ${csvFile}`
    };
  }

  const recordId = String(record.id || record.ref || "").trim();
  const recordExt = isAwnDataCsvFilesStore(viewStore) ? "csv" : "md";
  const fileName = String(record?.fileName || "").trim();
  const file = fileName || (recordId ? `${recordId}.${recordExt}` : `${recordId}.md`);
  return {
    manifestPath,
    mode: "container",
    file,
    nodeTitle: recordTitle
  };
}

function clearAwnDataViewCommentsMount() {
  for (const mount of [awnDataViewIblockCommentsMountNode, awnDataViewRecordCommentsMountNode]) {
    mount?.replaceChildren();
  }
}

async function mountAwnDataViewComments(store, record = null) {
  ensureAwnDataViewHubMounted();
  clearAwnDataViewCommentsMount();

  const isRecord = Boolean(record);
  const wrapper = isRecord ? awnDataViewRecordCommentsMountNode : awnDataViewIblockCommentsMountNode;
  if (!wrapper) return;

  const context = resolveAwnDataCommentsContext(store, record);
  if (!context) return;

  await appendNodeCommentsBlockToContainer(wrapper, {
    manifestPath: context.manifestPath,
    nodeTitle: context.nodeTitle,
    mode: context.mode,
    file: context.file,
    disabled: !AWN_DATA_COMMENTS_ENABLED
  });
  scheduleWorkspaceScrollChromeSync();
}

function renderAwnDataIblockDescription(store) {
  const bodyNode = awnDataViewIblockDescriptionBodyNode;
  const descNode = awnDataViewIblockDescriptionNode;
  const emptyNode = awnDataViewIblockDescriptionEmptyNode;
  const briefFold = awnDataViewIblockBriefFoldNode;
  if (!descNode) return;

  if (awnDataViewRecordId) {
    briefFold?.classList.add("hidden");
    bodyNode?.classList.add("hidden");
    descNode.replaceChildren();
    emptyNode?.classList.add("hidden");
    return;
  }

  briefFold?.classList.remove("hidden");
  bodyNode?.classList.remove("hidden");

  const markdown = store ? resolveAwnDataIblockDescriptionMarkdown(store) : "";
  if (!markdown) {
    descNode.replaceChildren();
    descNode.classList.add("hidden");
    emptyNode?.classList.remove("hidden");
    if (emptyNode) emptyNode.textContent = IBLOCK_INSTRUCTION_EMPTY_TEXT;
    briefFold?.classList.toggle("is-empty", true);
    if (briefFold && !briefFold.open) briefFold.open = true;
    return;
  }

  descNode.classList.remove("hidden");
  emptyNode?.classList.add("hidden");
  briefFold?.classList.toggle("is-empty", false);
  const manifestPath =
    store?.manifestRelPath || (store?.relPath ? `awn-databases/${store.relPath}/manifest.md` : "");
  if (typeof renderMarkdownToHtml === "function") {
    descNode.innerHTML = renderMarkdownToHtml(markdown, { nodePath: manifestPath });
  } else {
    descNode.textContent = markdown;
  }
}

