async function openAwnDatabaseEditorFromRoute(resolved, agentId = activeWorkspaceId) {
  const storeRel = String(resolved?.storeRel || "").replace(/^\/+|\/+$/g, "");
  if (!storeRel) return false;

  let store = null;
  if (awnDataViewStoreRelMatches(awnDataViewStoreCache?.relPath, storeRel)) {
    store = normalizeAwnDataStoreView(awnDataViewStoreCache);
  } else {
    try {
      const response = await fetch(buildApiUrl("/api/awn-databases", { store: storeRel }, agentId));
      if (!response.ok) return false;
      const data = await response.json();
      store = normalizeAwnDataStoreView(data.store);
    } catch {
      return false;
    }
  }
  if (!store) return false;

  const recordId = String(resolved?.recordId || "").trim();
  if (recordId) {
    const allRecords = getAwnDataStoreAllRecords(store);
    let record = allRecords.find((item) => String(item.id || "").trim() === recordId);
    if (!record) {
      const normalizedId = recordId.replace(/\\/g, "/").replace(/^\/+/, "").toLowerCase();
      record = allRecords.find((item) => {
        const rel = String(item?.relPath || "").replace(/\\/g, "/").replace(/^\/+/, "").toLowerCase();
        const fileName = String(item?.fileName || "").replace(/\\/g, "/").toLowerCase();
        return (
          rel.endsWith(`/${normalizedId}`) ||
          rel.endsWith(`/${normalizedId}.md`) ||
          rel.endsWith(`/${normalizedId}.csv`) ||
          fileName === `${normalizedId}.md` ||
          fileName === `${normalizedId}.csv`
        );
      });
    }
    if (!record) return false;
    awnDataViewStoreRel = storeRel;
    awnDataViewRecordId = String(record.id || "").trim();
    awnDataViewStoreCache = store;
    awnDataViewRecordCache = record;
    await openAwnDataRecordEditor(record, store);
    return true;
  }

  if (isAwnDataSingleTableStore(store)) {
    awnDataViewStoreRel = storeRel;
    awnDataViewStoreCache = store;
    await openAwnDataSingleStoreContentEdit(store);
    return true;
  }

  awnDataViewStoreRel = storeRel;
  awnDataViewStoreCache = store;
  await openAwnDataStoreManifestEdit(store);
  return true;
}

async function openAwnDatabaseManifestContentEditor({ label, filePath, storeRel, recordId = "" }) {
  const normalizedPath = String(filePath || "").replace(/\\/g, "/").replace(/^\/+/, "");
  if (!normalizedPath) {
    showToast("Не удалось определить путь к файлу", "error");
    return;
  }
  if (awnDatabaseManifestEditorOpening) return;
  awnDatabaseManifestEditorOpening = true;

  awnDataManifestEditReturnRel = String(storeRel || awnDataViewStoreRel || "")
    .replace(/\\/g, "/")
    .replace(/^\/+|\/+$/g, "");
  awnDataManifestEditReturnRecordId = String(recordId || "").trim();
  nodeSettingsViewActive = true;
  nodeMemoryViewActive = false;
  hideHomeView();
  clearActiveSystemFile();
  nodeOverviewRenderSeq += 1;

  const nextPath = getResolvedNodePath(normalizedPath);
  suspendAppRouteSync();
  try {
    activePath = nextPath;
    activeLabel = label;
    activeFolderBrowsePath = null;
    activeFolderBrowseFilePath = null;
    titleInputNode.value = label;
    updateActiveButton();
    fileContentInputNode.value = "";
    refreshEditorViewContent();

    if (!applyContentModeState("description", { skipWorkspaceUi: true })) {
      throw new Error("Не удалось переключить режим редактора");
    }

    revealAwnDatabaseManifestEditorShell();

    const fileContent = await fetchAwnDatabaseRecordEditorContent(nextPath);
    modeContentCache.description = fileContent;
    navigationManifestCachedPath = getActiveNodeApiPath();
    if (/\.csv$/i.test(nextPath)) {
      editorViewMode = "source";
    }

    applyAwnDatabaseEditorPropertiesFromContent(fileContent, nextPath);
    await ensureTopicSchemaForActiveContext().catch(() => null);
    applyNodeManifestBody(modeContentCache.description || "");
    syncTitleFieldsFromNode(activePath);
    refreshEditorViewContent();

    applyModeUi({ skipAwnDataLoad: true, skipWorkspaceUi: true });
    applyNodeWorkspaceViewUi({ skipBreadcrumbs: true });
    updateBreadcrumbsForActiveMode();
    if (shouldRenderPropsFormNow()) renderPropsForm();
  } catch (error) {
    awnDataManifestEditReturnRel = "";
    awnDataManifestEditReturnRecordId = "";
    fileContentInputNode.value = `Ошибка чтения файла: ${error.message}`;
    showToast(String(error.message || error), "error");
  } finally {
    awnDatabaseManifestEditorOpening = false;
    resumeAppRouteSync();
    hideContentLoading({ force: true });
    syncAppRouteToUrl({ replace: true });
    scheduleActivePageContextSync();
  }
}

