function createAwnDataViewSectionTreeGutters(depth, ancLines, isLast) {
  const levelCount = Number(depth) || 0;
  if (levelCount <= 0) return null;

  const wrap = document.createElement("span");
  wrap.className = "awn-databases-view-section-tree-gutters";
  wrap.setAttribute("aria-hidden", "true");

  for (let level = 0; level < levelCount; level += 1) {
    const seg = document.createElement("span");
    seg.className = "awn-databases-view-section-tree-gutter";
    const isJoint = level === levelCount - 1;
    if (isJoint) {
      seg.classList.add("awn-databases-view-section-tree-gutter--joint");
      if (isLast) seg.classList.add("is-last");
    } else if (ancLines[level]) {
      seg.classList.add("awn-databases-view-section-tree-gutter--line");
    } else {
      seg.classList.add("awn-databases-view-section-tree-gutter--spacer");
    }
    wrap.appendChild(seg);
  }

  return wrap;
}

function appendAwnDataViewSectionTreeItem(
  container,
  { id, label, depth = 0, record = null, store = null, ancLines = [], isLast = true }
) {
  const row = document.createElement("div");
  row.className = "awn-databases-view-section-tree-row";
  if (depth > 0) row.classList.add("is-nested");
  const isUnregistered = Boolean(record && awnDataSectionMissingManifest(record));
  if (isUnregistered) row.classList.add("awn-databases-view-section-tree-row--unregistered");

  const btn = document.createElement("a");
  btn.className = "awn-databases-view-section-tree-item";
  btn.href = buildAwnDataViewSectionTreeHref(id);
  btn.dataset.sectionId = id;
  btn.style.setProperty("--tree-depth", String(depth));
  btn.setAttribute("role", "treeitem");
  btn.setAttribute("aria-selected", id === awnDataViewSectionId ? "true" : "false");
  if (isUnregistered) {
    btn.classList.add("awn-databases-view-section-tree-item--unregistered");
    btn.title = getAwnDataSectionUnregisteredTitle(record);
  }
  if (id === awnDataViewSectionId) {
    row.classList.add("is-active");
    btn.classList.add("is-active");
  }

  const gutters = createAwnDataViewSectionTreeGutters(depth, ancLines, isLast);
  if (gutters) btn.appendChild(gutters);

  const icon = document.createElement("span");
  icon.className = "awn-databases-view-section-tree-icon";
  icon.setAttribute("aria-hidden", "true");

  const text = document.createElement("span");
  text.className = "awn-databases-view-section-tree-label";
  if (isUnregistered) text.classList.add("awn-databases-view-section-tree-label--unregistered");
  text.textContent = label;

  btn.append(icon, text);
  row.appendChild(btn);

  if (record && store && !String(id).startsWith("__")) {
    row.appendChild(createAwnDataViewSectionTreeActions(record, store));
  }

  container.appendChild(row);
}

function appendAwnDataViewSectionTreeBranch(container, node, depth = 0, store = null) {
  appendAwnDataViewSectionTreeBranchFiltered(container, node, depth, "", store);
}

function awnDataSectionTreeHaystack(node) {
  const title = String(node?.title || node?.id || "").trim();
  return [node?.id, title].map((value) => String(value || "").toLowerCase()).join(" ");
}

function awnDataSectionTreeNodeMatchesQuery(node, query) {
  const q = String(query || "").trim().toLowerCase();
  if (!q) return true;
  if (awnDataSectionTreeHaystack(node).includes(q)) return true;
  const children = Array.isArray(node?.children) ? node.children : [];
  return children.some((child) => awnDataSectionTreeNodeMatchesQuery(child, q));
}

function appendAwnDataViewSectionTreeBranchFiltered(
  container,
  node,
  depth,
  query,
  store = null,
  ancLines = [],
  isLast = true
) {
  const q = String(query || "").trim().toLowerCase();
  const children = Array.isArray(node?.children) ? node.children : [];
  const title = String(node?.title || node?.id || "").trim() || "—";
  const selfMatches = !q || awnDataSectionTreeHaystack(node).includes(q);
  const matchingChildren = q
    ? children.filter((child) => awnDataSectionTreeNodeMatchesQuery(child, q))
    : children;

  if (!q || selfMatches || matchingChildren.length) {
    appendAwnDataViewSectionTreeItem(container, {
      id: String(node.id),
      label: title,
      depth,
      record: node,
      store,
      ancLines,
      isLast
    });
    for (let index = 0; index < matchingChildren.length; index += 1) {
      const child = matchingChildren[index];
      const childIsLast = index === matchingChildren.length - 1;
      appendAwnDataViewSectionTreeBranchFiltered(
        container,
        child,
        depth + 1,
        query,
        store,
        [...ancLines, !isLast],
        childIsLast
      );
    }
  }
}

function syncAwnDataViewSectionTree(store) {
  if (!awnDataViewSectionWrapNode || !awnDataViewSectionTreeNode) return;

  const viewStore = normalizeAwnDataStoreView(store || {});
  const sections = getAwnDataStoreSections(viewStore);
  const hierarchyEnabled = resolveAwnDataRecordHierarchy(viewStore);

  if (viewStore?.kind !== "collection" || !hierarchyEnabled || isAwnDataSingleCsvStore(viewStore)) {
    awnDataViewSectionWrapNode.classList.add("hidden");
    awnDataViewSectionTreeNode.replaceChildren();
    awnDataViewSectionNoticesNode?.replaceChildren();
    awnDataViewSectionNoticesNode?.classList.add("hidden");
    awnDataViewSectionCreateFormNode?.classList.add("hidden");
    awnDataViewSectionId = "__all__";
    return;
  }

  const validIds = collectAwnDataSectionTreeIds(store);
  if (!validIds.has(awnDataViewSectionId)) awnDataViewSectionId = "__all__";

  awnDataViewSectionWrapNode.classList.remove("hidden");
  awnDataViewSectionTreeNode.replaceChildren();

  const query = String(awnDataViewSectionSearchInputNode?.value || "").trim();
  const queryLower = query.toLowerCase();
  let visibleCount = 0;

  const staticItems = [
    { id: "__all__", label: "Все записи" },
    { id: "__root__", label: "Корень (без родителя)" }
  ];
  for (const item of staticItems) {
    const haystack = [item.id, item.label].map((value) => String(value).toLowerCase()).join(" ");
    if (!queryLower || haystack.includes(queryLower)) {
      appendAwnDataViewSectionTreeItem(awnDataViewSectionTreeNode, {
        id: item.id,
        label: item.label,
        depth: 0
      });
      visibleCount += 1;
    }
  }

  const sectionTree = buildAwnDataSectionTree(sections);
  const visibleRoots = sectionTree.filter(
    (node) => !queryLower || awnDataSectionTreeNodeMatchesQuery(node, queryLower)
  );
  for (let index = 0; index < visibleRoots.length; index += 1) {
    const node = visibleRoots[index];
    appendAwnDataViewSectionTreeBranchFiltered(
      awnDataViewSectionTreeNode,
      node,
      0,
      queryLower,
      viewStore,
      [],
      index === visibleRoots.length - 1
    );
    visibleCount += 1;
  }

  if (queryLower && !visibleCount) {
    const empty = document.createElement("p");
    empty.className = "awn-databases-view-section-tree-empty";
    empty.textContent = "Разделы не найдены";
    awnDataViewSectionTreeNode.appendChild(empty);
  }

  applyAwnDataActiveSectionToAddParentSelect();
  syncAwnDataViewSectionPanelNotices(viewStore);
}

function filterAwnDataViewRecordsBySection(contentRecords, sectionId, sectionCatalog) {
  const records = (Array.isArray(contentRecords) ? contentRecords : []).filter(
    (record) => !isAwnDataSectionRecord(record)
  );
  const sid = String(sectionId || "__all__");
  if (sid === "__all__") return records;
  const catalog = Array.isArray(sectionCatalog) ? sectionCatalog : records;
  return records.filter((record) => recordMatchesAwnDataSectionFilter(record, sid, catalog));
}

function filterAwnDataViewRecords(records, query) {
  const q = String(query || "").trim().toLowerCase();
  if (!q) return records;
  return records.filter((record) => {
    const fmValues = Object.values(record.frontmatter || {}).map((value) => String(value || ""));
    const haystack = [record.id, record.title, record.parent, record.relPath, ...fmValues]
      .map((value) => String(value || "").toLowerCase())
      .join(" ");
    return haystack.includes(q);
  });
}

function formatAwnDataViewFieldLabel(field, key) {
  return String(field?.title || key).trim().replace(/^\{[^}]+\}\s*/, "") || key;
}

function sortAwnDataViewSchemaFieldKeys(keys, fields = {}) {
  return [...keys].sort((a, b) => {
    const sortA = Number(fields[a]?.sort);
    const sortB = Number(fields[b]?.sort);
    const hasA = Number.isFinite(sortA);
    const hasB = Number.isFinite(sortB);
    if (hasA && hasB && sortA !== sortB) return sortA - sortB;
    if (hasA && !hasB) return -1;
    if (!hasA && hasB) return 1;
    return a.localeCompare(b, "ru");
  });
}

function resolveAwnDataViewRecordSchemaFields(store) {
  const schema = store?.schema && typeof store.schema === "object" ? store.schema : {};
  const mergedFields = schema.fields && typeof schema.fields === "object" ? schema.fields : {};
  const fieldsLocal = schema.fieldsLocal && typeof schema.fieldsLocal === "object" ? schema.fieldsLocal : {};
  if (Object.keys(mergedFields).length) return { ...mergedFields, ...fieldsLocal };
  if (Object.keys(fieldsLocal).length) return fieldsLocal;
  return {};
}

function getAwnDataViewColumnsStorageKey(store) {
  const storeRel = resolveAwnDataStoreRelPath(store) || String(awnDataViewStoreRel || "").replace(/^\/+|\/+$/g, "");
  return `${AWN_DATA_VIEW_COLUMNS_STORAGE_PREFIX}${activeWorkspaceId || "main"}:${storeRel}`;
}

function getAwnDataViewSchemaColumnOptions(store) {
  const viewStore = normalizeAwnDataStoreView(store || {});
  if (
    viewStore?.kind === "group" ||
    isAwnDataSingleTableStore(viewStore) ||
    isAwnDataCsvFilesStore(viewStore)
  ) {
    return [];
  }

  const schemaFields = resolveAwnDataViewRecordSchemaFields(viewStore);
  const options = [];
  const seen = new Set();

  for (const key of sortAwnDataViewSchemaFieldKeys(Object.keys(schemaFields), schemaFields)) {
    if (key === "id" || seen.has(key)) continue;
    const field = schemaFields[key] || {};
    if (field.hidden) continue;
    seen.add(key);
    options.push({
      key,
      label: formatAwnDataViewFieldLabel(field, key)
    });
  }

  const hasTitleField = options.some((column) => isAwnDataViewTitleFieldKey(column.key));
  if (!hasTitleField) {
    options.unshift({ key: "__title__", label: "Название" });
  }

  const records = getAwnDataViewContentRecords(viewStore);
  const hasParentInData = records.some((record) => String(record.parent || "").trim());
  const hasParentInSchema =
    Object.prototype.hasOwnProperty.call(schemaFields, "parent") ||
    Object.prototype.hasOwnProperty.call(schemaFields, "awn-parent");
  if (!hasParentInSchema && hasParentInData && viewStore?.kind === "collection") {
    options.push({ key: "__parent__", label: "Раздел" });
  }

  return options;
}

function getAwnDataViewDefaultVisibleColumnKeys(store) {
  const available = new Set(getAwnDataViewSchemaColumnOptions(store).map((column) => column.key));
  const defaults = AWN_DATA_VIEW_DEFAULT_COLUMN_KEYS.filter((key) => available.has(key));
  if (defaults.length) return defaults;
  return [...available].slice(0, Math.min(2, available.size));
}

function getAwnDataViewVisibleColumnKeys(store = awnDataViewStoreCache) {
  const options = getAwnDataViewSchemaColumnOptions(store);
  const allKeys = options.map((column) => column.key);
  if (!allKeys.length) return [];

  const scope = getAwnDataViewColumnsStorageKey(store);
  if (awnDataViewVisibleColumnKeysScope !== scope) {
    awnDataViewVisibleColumnKeysScope = scope;
    awnDataViewVisibleColumnKeysCache = null;
    const stored = readStorageItem(scope);
    if (stored) {
      try {
        const parsed = JSON.parse(stored);
        if (Array.isArray(parsed)) {
          awnDataViewVisibleColumnKeysCache = parsed.filter((key) => allKeys.includes(key));
        }
      } catch {
        awnDataViewVisibleColumnKeysCache = null;
      }
    }
  }

  if (!awnDataViewVisibleColumnKeysCache?.length) {
    return getAwnDataViewDefaultVisibleColumnKeys(store);
  }
  return awnDataViewVisibleColumnKeysCache.filter((key) => allKeys.includes(key));
}

function setAwnDataViewVisibleColumnKeys(store, keys) {
  const allKeys = getAwnDataViewSchemaColumnOptions(store).map((column) => column.key);
  const normalized = keys.filter((key) => allKeys.includes(key));
  awnDataViewVisibleColumnKeysCache = normalized.length
    ? normalized
    : getAwnDataViewDefaultVisibleColumnKeys(store);
  awnDataViewVisibleColumnKeysScope = getAwnDataViewColumnsStorageKey(store);
  writeStorageItem(awnDataViewVisibleColumnKeysScope, JSON.stringify(awnDataViewVisibleColumnKeysCache));
  syncAwnDataViewColumnsPickerUi(store);
  if (awnDataViewStoreCache && !awnDataViewRecordId) {
    renderAwnDataViewStoreContent(awnDataViewStoreCache, awnDataViewCatalogAgentId || activeWorkspaceId);
  }
}

function syncAwnDataViewColumnsPickerUi(store = awnDataViewStoreCache) {
  if (!awnDataViewColumnsWrapNode) return;
  const viewStore = normalizeAwnDataStoreView(store || {});
  const hidePicker =
    viewStore?.kind === "group" ||
    isAwnDataSingleTableStore(viewStore) ||
    isAwnDataCsvFilesStore(viewStore) ||
    awnDataViewRecordsLayout === "cards" ||
    awnDataViewRecordsLayout === "toc";
  awnDataViewColumnsWrapNode.classList.toggle("hidden", hidePicker);
  if (hidePicker) return;

  const columnsBtn = awnDataViewColumnsWrapNode.querySelector(".awn-databases-view-columns-btn");
  if (!columnsBtn) return;
  syncAwnDataViewColumnsButtonLabel(columnsBtn, viewStore);
}

function renderAwnDataViewColumnsPanel(panel, store = awnDataViewStoreCache) {
  if (!panel) return;
  panel.replaceChildren();

  const head = document.createElement("div");
  head.className = "external-list-columns-panel-head";
  const title = document.createElement("span");
  title.className = "external-list-columns-panel-title";
  title.textContent = "Колонки схемы";
  const actions = document.createElement("div");
  actions.className = "external-list-columns-panel-actions";
  const resetBtn = document.createElement("button");
  resetBtn.type = "button";
  resetBtn.className = "external-list-columns-action-btn";
  resetBtn.textContent = "По умолч.";
  resetBtn.addEventListener("click", () => {
    setAwnDataViewVisibleColumnKeys(store, getAwnDataViewDefaultVisibleColumnKeys(store));
    renderAwnDataViewColumnsPanel(panel, store);
  });
  const showAllBtn = document.createElement("button");
  showAllBtn.type = "button";
  showAllBtn.className = "external-list-columns-action-btn";
  showAllBtn.textContent = "Все";
  showAllBtn.addEventListener("click", () => {
    setAwnDataViewVisibleColumnKeys(
      store,
      getAwnDataViewSchemaColumnOptions(store).map((column) => column.key)
    );
    renderAwnDataViewColumnsPanel(panel, store);
  });
  actions.append(resetBtn, showAllBtn);
  head.append(title, actions);
  panel.appendChild(head);

  const list = document.createElement("div");
  list.className = "external-list-columns-panel-list";
  const visible = new Set(getAwnDataViewVisibleColumnKeys(store));

  for (const column of getAwnDataViewSchemaColumnOptions(store)) {
    const label = document.createElement("label");
    label.className = "external-list-columns-option";

    const input = document.createElement("input");
    input.type = "checkbox";
    input.checked = visible.has(column.key);
    input.addEventListener("change", () => {
      const next = new Set(getAwnDataViewVisibleColumnKeys(store));
      if (input.checked) next.add(column.key);
      else next.delete(column.key);
      if (!next.size) {
        input.checked = true;
        return;
      }
      setAwnDataViewVisibleColumnKeys(store, [...next]);
      renderAwnDataViewColumnsPanel(panel, store);
    });

    const text = document.createElement("span");
    text.textContent = column.label;
    text.title = column.key;
    label.append(input, text);
    list.appendChild(label);
  }

  panel.appendChild(list);
}

function bindAwnDataViewColumnsPicker(wrap, columnsBtn, columnsPanel) {
  if (!wrap || !columnsBtn || !columnsPanel || columnsBtn.dataset.bound === "1") return;
  columnsBtn.dataset.bound = "1";

  const syncColumnsPickerOpenState = () => {
    const open = !columnsPanel.classList.contains("hidden");
    columnsBtn.classList.toggle("is-active", open);
    columnsBtn.setAttribute("aria-expanded", open ? "true" : "false");
  };

  columnsBtn.addEventListener("click", (event) => {
    event.stopPropagation();
    const willOpen = columnsPanel.classList.contains("hidden");
    document
      .querySelectorAll(".awn-databases-view-columns-panel, .external-list-columns-panel")
      .forEach((node) => {
        if (node !== columnsPanel) node.classList.add("hidden");
      });
    if (willOpen) renderAwnDataViewColumnsPanel(columnsPanel, awnDataViewStoreCache);
    columnsPanel.classList.toggle("hidden");
    syncColumnsPickerOpenState();
  });

  if (!wrap.dataset.columnsPickerBound) {
    wrap.dataset.columnsPickerBound = "1";
    document.addEventListener("click", (event) => {
      if (wrap.contains(event.target)) return;
      columnsPanel.classList.add("hidden");
      syncColumnsPickerOpenState();
    });
    document.addEventListener("keydown", (event) => {
      if (event.key === "Escape") {
        columnsPanel.classList.add("hidden");
        syncColumnsPickerOpenState();
      }
    });
  }

  syncColumnsPickerOpenState();
}

function isAwnDataViewTitleFieldKey(key) {
  const normalized = String(key || "").trim().toLowerCase();
  return normalized === "title" || normalized === "awn-title";
}

function getAwnDataViewColumns(store) {
  if (isAwnDataCsvFilesStore(store)) {
    return [
      { key: "__id__", label: "ID", kind: "id" },
      { key: "__title__", label: "Название файла", kind: "title" },
      { key: "__csv_rows__", label: "Строк", kind: "csvRows" },
      { key: "__file_size__", label: "Размер файла", kind: "fileSize" }
    ];
  }
  const viewStore = normalizeAwnDataStoreView(store || {});
  const schemaFields = resolveAwnDataViewRecordSchemaFields(viewStore);
  const visibleKeys = new Set(getAwnDataViewVisibleColumnKeys(viewStore));
  const columns = [{ key: "__id__", label: "ID", kind: "id" }];

  for (const key of sortAwnDataViewSchemaFieldKeys(Object.keys(schemaFields), schemaFields)) {
    if (key === "id" || key === "awn-id") continue;
    if (!visibleKeys.has(key)) continue;
    const field = schemaFields[key] || {};
    if (field.hidden) continue;
    columns.push({
      key,
      label: formatAwnDataViewFieldLabel(field, key),
      kind: "field",
      fieldType: String(field?.type || "awn.field.string"),
      field
    });
  }

  const hasParentInSchema =
    Object.prototype.hasOwnProperty.call(schemaFields, "parent") ||
    Object.prototype.hasOwnProperty.call(schemaFields, "awn-parent");
  const records = getAwnDataViewContentRecords(viewStore);
  const hasParentInData = records.some((record) => String(record.parent || "").trim());
  if (
    !hasParentInSchema &&
    hasParentInData &&
    viewStore?.kind === "collection" &&
    visibleKeys.has("__parent__")
  ) {
    columns.push({ key: "__parent__", label: "Раздел", kind: "parent" });
  }

  const hasTitleColumn = columns.some((column) => column.kind === "title" || isAwnDataViewTitleFieldKey(column.key));
  if (!hasTitleColumn && visibleKeys.has("__title__")) {
    columns.splice(1, 0, { key: "__title__", label: "Название", kind: "title" });
  }

  return columns;
}

function formatAwnDataViewCellValue(record, column, store = awnDataViewStoreCache) {
  if (column.kind === "id") return record.id || "—";
  if (column.kind === "parent") {
    const parentId = String(record.parent || "").trim();
    if (!parentId) return "—";
    const section = getAwnDataStoreSections(store).find((item) => String(item.id || "").trim() === parentId);
    return section ? resolveAwnDataRecordDisplayName(section) : parentId;
  }
  if (column.kind === "title") {
    return String(record.title || record.fileName || record.id || "—").trim() || "—";
  }
  if (column.kind === "csvRows") {
    const count = Number(record.csvRowCount);
    return Number.isFinite(count) ? String(count) : "—";
  }
  if (column.kind === "fileSize") {
    const size = Number(record.fileSize);
    return Number.isFinite(size) && size > 0 ? formatFileSize(size) : "—";
  }

  const frontmatter = record?.frontmatter || {};
  let raw = frontmatter[column.key];
  if (raw === undefined || raw === null || String(raw).trim() === "") {
    if (isAwnDataViewTitleFieldKey(column.key)) return record.title || "—";
    return "—";
  }

  const fieldType = column.fieldType || "";
  if (fieldType === "awn.boolean") {
    const value = String(raw).trim().toLowerCase();
    return value === "true" || value === "yes" || value === "1" ? "да" : "нет";
  }

  if (Array.isArray(raw)) {
    const items = raw.map((item) => String(item ?? "").trim()).filter(Boolean);
    return items.length ? items.join(", ") : "—";
  }

  return String(raw).trim();
}

function isAwnDataViewImagePreviewColumn(column) {
  if (column.kind !== "field") return false;
  const fieldType = String(column.fieldType || "");
  if (fieldTypeIs(fieldType, "file.image.for-preview")) return true;
  const key = String(column.key || "").trim().toLowerCase();
  return key === "awn-preview" || key === "preview";
}

function appendAwnDataViewPreviewFieldCell(cell, record, column, store) {
  const frontmatter = record?.frontmatter || {};
  let raw = frontmatter[column.key];
  raw = raw === undefined || raw === null ? "" : String(raw).trim();
  if (!raw) {
    cell.textContent = "—";
    return;
  }

  cell.classList.add("external-table-cover-cell", "awn-databases-view-record-field-preview");
  cell.title = raw;
  const filePath = resolveAwnDataRecordFilePath(record, store);
  const preview = buildPreviewUiFromPath(raw, filePath);
  if (appendPreviewUiThumb(cell, preview, { className: "external-table-cover-thumb" })) return;
  cell.textContent = raw;
}

function updateAwnDataViewCount(shown, total) {
  if (!awnDataViewCountNode) return;
  if (!total) {
    awnDataViewCountNode.textContent = "";
    return;
  }
  const formatCount = (count) => {
    const mod10 = count % 10;
    const mod100 = count % 100;
    if (mod10 === 1 && mod100 !== 11) return `${count} запись`;
    if (mod10 >= 2 && mod10 <= 4 && (mod100 < 10 || mod100 >= 20)) return `${count} записи`;
    return `${count} записей`;
  };
  awnDataViewCountNode.textContent =
    shown === total ? formatCount(total) : `${shown} из ${formatCount(total)}`;
}

function resolveAwnDataRecordFilePath(record, store = awnDataViewStoreCache) {
  const viewStore = normalizeAwnDataStoreView(store || {});
  if (isAwnDataSingleCsvStore(viewStore)) {
    return resolveAwnDataSingleStoreFileRel(viewStore);
  }

  let relPath = String(record?.relPath || "").replace(/\\/g, "/").replace(/^\/+/, "");
  if (!relPath) return "";
  return relPath.startsWith("awn-databases/") ? relPath : `awn-databases/${relPath}`;
}

function isAwnDataBinaryFileRecord(record, store = awnDataViewStoreCache) {
  const viewStore = normalizeAwnDataStoreView(store || {});
  if (record?.isFile) return true;
  const filePath = resolveAwnDataRecordFilePath(record, viewStore);
  if (!filePath) return false;
  if (/\.(md|csv)$/i.test(filePath)) return false;
  if (resolveAwnDataCollectionKind(viewStore) === "files") return true;
  return isAwnDatabaseRecordContentPath(filePath);
}

async function openAwnDataRecordEditor(record, store = awnDataViewStoreCache) {
  const viewStore = normalizeAwnDataStoreView(store || {});
  const filePath = resolveAwnDataRecordFilePath(record, viewStore);
  if (!filePath) {
    showToast("Не удалось определить путь к записи", "error");
    return;
  }

  const storeRel = String(viewStore?.relPath || awnDataViewStoreRel || "")
    .replace(/\\/g, "/")
    .replace(/^\/+|\/+$/g, "");
  const recordId = String(record?.id || awnDataViewRecordId || "").trim();
  const isSingleCsvStore = isAwnDataSingleCsvStore(viewStore);
  const label = isSingleCsvStore
    ? `${viewStore?.name || storeRel} · ${viewStore?.recordFile || "main.csv"}`
    : String(record?.title || record?.fileName || record?.id || filePath.split("/").pop() || filePath).trim();

  if (isAwnDataBinaryFileRecord(record, viewStore)) {
    const catalogAgentId = awnDataViewCatalogAgentId || awnDataCatalogAgentId || activeWorkspaceId;
    const folderPath = storeRel
      ? `awn-databases/${storeRel}/awn-storage/data`
      : getFolderBrowseParentPath(filePath);
    awnDataManifestEditReturnRel = storeRel;
    awnDataManifestEditReturnRecordId = recordId;
    try {
      suspendAppRouteSync();
      await openFolderBrowseFile(label, filePath, {
        agentId: catalogAgentId,
        folderPath,
        skipRouteSync: true
      });
      updateBreadcrumbsForActiveMode();
    } catch (error) {
      awnDataManifestEditReturnRel = "";
      awnDataManifestEditReturnRecordId = "";
      showToast(String(error.message || error), "error");
    } finally {
      resumeAppRouteSync();
      syncAppRouteToUrl({ replace: true });
    }
    return;
  }

  await openAwnDatabaseManifestContentEditor({
    label,
    filePath,
    storeRel,
    recordId
  });
}

function buildAwnDataRecordViewPropEntries(record) {
  const frontmatter = record?.frontmatter && typeof record.frontmatter === "object" ? record.frontmatter : {};
  const entries = [];
  for (const [key, value] of Object.entries(frontmatter)) {
    if (value === undefined || value === null) continue;
    entries.push({ key, value });
  }
  return normalizePropsEntries(entries);
}

function buildAwnDataParentSectionSelectOptions(store) {
  const options = [{ value: "", label: "Корень (без родителя)" }];

  const walk = (nodes, depth = 0) => {
    for (const node of nodes) {
      const title = String(node?.title || node?.id || "").trim() || node.id;
      const prefix = depth > 0 ? `${"  ".repeat(depth)}` : "";
      options.push({ value: String(node.id), label: `${prefix}${title}` });
      if (Array.isArray(node.children) && node.children.length) walk(node.children, depth + 1);
    }
  };
  walk(buildAwnDataSectionTree(getAwnDataStoreSections(store)));
  return options;
}

function applyAwnDataActiveSectionToAddParentSelect() {
  if (!awnDataAddParentSelectNode || awnDataAddParentSelectNode.classList.contains("hidden")) return;
  const parent = resolveAwnDataCreateSectionParent();
  const hasOption = [...awnDataAddParentSelectNode.options].some((option) => option.value === parent);
  awnDataAddParentSelectNode.value = parent && hasOption ? parent : "";
}

function syncAwnDataParentSectionSelect(store) {
  if (!awnDataAddParentSelectNode) return;
  const options = buildAwnDataParentSectionSelectOptions(store);
  awnDataAddParentSelectNode.replaceChildren();
  for (const option of options) {
    const node = document.createElement("option");
    node.value = option.value;
    node.textContent = option.label;
    awnDataAddParentSelectNode.appendChild(node);
  }
  applyAwnDataActiveSectionToAddParentSelect();
}

function syncAwnDataViewAddForm(store) {
  if (!awnDataViewAddWrapNode) return;
  const viewStore = normalizeAwnDataStoreView(store || {});
  const collectionKind = resolveAwnDataCollectionKind(viewStore);
  const isFiles = collectionKind === "files";
  const isCsvFiles = isAwnDataCsvFilesStore(viewStore);
  const isSingleCsv = isAwnDataSingleCsvStore(viewStore);
  const hierarchy = resolveAwnDataRecordHierarchy(viewStore);
  const records = Array.isArray(viewStore?.records) ? viewStore.records : [];
  const hasParentInData = records.some((record) => String(record.parent || "").trim());
  const showCreateMainCsv = shouldShowAwnDataCreateMainCsvForm(viewStore);

  awnDataAddRecordsFormNode?.classList.toggle("hidden", isFiles || isSingleCsv);
  awnDataCreateMainCsvFormNode?.classList.toggle("hidden", !showCreateMainCsv);
  awnDataAddFilesFormNode?.classList.toggle("hidden", !isFiles && !isCsvFiles);

  const addNameLabel = awnDataAddRecordsFormNode?.querySelector(".awn-databases-add-name-field > span");
  const addSlugLabel = awnDataAddRecordsFormNode?.querySelector(".slug-field-label");
  const addRecordBtn = awnDataAddRecordBtn;
  if (isCsvFiles) {
    if (addNameLabel) addNameLabel.textContent = "Новый CSV-файл";
    if (addSlugLabel) addSlugLabel.textContent = "Имя файла (slug)";
    if (addRecordBtn) addRecordBtn.textContent = "Создать CSV-файл";
  } else if (!isSingleCsv) {
    if (addNameLabel) addNameLabel.textContent = "Новый элемент";
    if (addSlugLabel) addSlugLabel.textContent = "Имя файла (slug)";
    if (addRecordBtn) addRecordBtn.textContent = "Добавить элемент";
  }

  if (awnDataCreateMainCsvBtn && showCreateMainCsv) {
    const recordFile = String(viewStore.recordFile || "main.csv").trim() || "main.csv";
    awnDataCreateMainCsvBtn.textContent = `Создать ${recordFile}`;
  }

  const showParent = !isFiles && !isSingleCsv && (hierarchy || hasParentInData);
  awnDataAddParentFieldNode?.classList.toggle("hidden", !showParent);

  if (awnDataAddParentLabelNode) {
    awnDataAddParentLabelNode.textContent = hierarchy
      ? "Раздел (опционально)"
      : "Родитель (id, опционально)";
  }

  if (hierarchy && !isSingleCsv && !isFiles) {
    awnDataAddParentInputNode?.classList.add("hidden");
    awnDataAddParentSelectNode?.classList.remove("hidden");
    syncAwnDataParentSectionSelect(viewStore);
  } else {
    awnDataAddParentInputNode?.classList.remove("hidden");
    awnDataAddParentSelectNode?.classList.add("hidden");
    if (isSingleCsv && awnDataAddParentInputNode) awnDataAddParentInputNode.value = "";
  }

  const idMode = String(viewStore?.schema?.record?.["id-mode"] || viewStore?.schema?.record?.idMode || "numeric")
    .trim()
    .toLowerCase();
  awnDataAddRecordsFormNode
    ?.querySelector(".awn-databases-add-slug-row")
    ?.classList.toggle("hidden", idMode === "numeric");
  if (idMode === "numeric") {
    awnDataAddSlugController?.reset();
  }

  if (isFiles) {
    const fileTypes = resolveAwnDataRecordFileTypes(viewStore);
    const accept = fileTypesToAcceptAttribute(fileTypes);
    if (awnDataUploadInputNode) {
      if (accept) awnDataUploadInputNode.setAttribute("accept", accept);
      else awnDataUploadInputNode.removeAttribute("accept");
    }
    if (awnDataUploadHintNode) {
      awnDataUploadHintNode.textContent = fileTypes
        ? `Допустимые типы: ${fileTypes}`
        : "Любые файлы в папку инфоблока.";
    }
    if (awnDataUploadBtnNode) {
      const uploadLabel = awnDataUploadBtnNode.querySelector(".folder-browse-upload-btn-label");
      if (uploadLabel) uploadLabel.textContent = "Загрузить";
    }
  } else if (isCsvFiles) {
    if (awnDataUploadInputNode) awnDataUploadInputNode.setAttribute("accept", ".csv");
    if (awnDataUploadHintNode) {
      awnDataUploadHintNode.textContent = "Загрузить существующий .csv — имя файла станет id записи.";
    }
    if (awnDataUploadBtnNode) {
      const uploadLabel = awnDataUploadBtnNode.querySelector(".folder-browse-upload-btn-label");
      if (uploadLabel) uploadLabel.textContent = "Загрузить CSV";
    }
  }
}

function resolveAwnDataAddParentValue() {
  const viewStore = normalizeAwnDataStoreView(awnDataViewStoreCache || {});
  const hierarchy = resolveAwnDataRecordHierarchy(viewStore);
  const isSingleCsv = isAwnDataSingleCsvStore(viewStore);
  const isFiles = resolveAwnDataCollectionKind(viewStore) === "files";
  if (isSingleCsv || isFiles) return "";
  if (hierarchy && awnDataAddParentSelectNode && !awnDataAddParentSelectNode.classList.contains("hidden")) {
    return String(awnDataAddParentSelectNode.value || "").trim();
  }
  return String(awnDataAddParentInputNode?.value || "").trim();
}

function resolveAwnDataViewRecordGridPreview(record, viewStore) {
  const filePath = resolveAwnDataRecordFilePath(record, viewStore);
  const fileName = String(record?.fileName || filePath.split("/").pop() || "").trim();
  const gridColumns = awnDataViewCardsColumns;
  if (ATTACHMENTS_IMAGE_EXT_RE.test(fileName) && filePath) {
    return {
      isImage: true,
      src: buildWorkspaceFolderBrowseFileUrl(filePath, {
        thumb: gridColumns !== 1,
        max: gridColumns === 1 ? 960 : MEDIA_THUMB_MAX_GRID
      })
    };
  }

  const storeRel = String(viewStore?.relPath || "").replace(/^\/+|\/+$/g, "");
  const frontmatter = record?.frontmatter || {};
  for (const key of ["awn-preview", "preview", "cover", "image", "thumbnail"]) {
    const raw = String(frontmatter[key] || "").trim();
    if (!raw) continue;
    const previewName = raw.split("/").pop() || raw;
    if (!ATTACHMENTS_IMAGE_EXT_RE.test(previewName)) continue;
    const rel = raw.startsWith("awn-databases/")
      ? raw
      : resolveWorkspaceBrowseRelPath(storeRel ? `awn-databases/${storeRel}` : "awn-databases", raw);
    return {
      isImage: true,
      src: buildWorkspaceFolderBrowseFileUrl(rel, {
        thumb: gridColumns !== 1,
        max: gridColumns === 1 ? 960 : MEDIA_THUMB_MAX_GRID
      })
    };
  }

  const titleColumn = { key: "awn-title" };
  const title = formatAwnDataViewCellValue(record, titleColumn);
  const idLabel = formatAwnDataViewCellValue(record, { kind: "id", key: "__id__" });
  const label = title !== "—" ? title : idLabel;
  return { isImage: false, label };
}

function awnDataRecordToNavTocItem(record) {
  const frontmatter = record?.frontmatter || {};
  const relPath = String(record?.relPath || "").replace(/\\/g, "/");
  const fileName = String(record?.fileName || relPath.split("/").pop() || "").trim();
  return {
    path: fileName,
    relativePath: relPath,
    title: resolveAwnDataRecordDisplayName(record),
    description: String(frontmatter["awn-description"] || frontmatter.description || "").trim(),
    status: String(frontmatter["awn-status"] || "").trim(),
    awnId: frontmatter["awn-id"] || record?.id || "",
    fileName
  };
}

