function renderAwnDataViewTransposedRecords(records, viewStore, columns) {
  const table = document.createElement("table");
  table.className = "awn-databases-view-table awn-databases-view-table--transposed";

  const thead = document.createElement("thead");
  const headRow = document.createElement("tr");

  const cornerHead = document.createElement("th");
  cornerHead.scope = "col";
  cornerHead.className = "awn-databases-view-transposed-corner";
  cornerHead.textContent = "Поле";
  headRow.appendChild(cornerHead);

  for (const record of records) {
    const th = document.createElement("th");
    th.scope = "col";
    th.className = "awn-databases-view-transposed-record-head";
    if (isAwnDataSystemRecord(record)) th.classList.add("is-system");
    const idLabel = formatAwnDataViewCellValue(record, { kind: "id", key: "__id__" });
    const titleLabel = formatAwnDataViewCellValue(record, { key: "title" });
    th.textContent = titleLabel !== "—" && titleLabel !== idLabel ? `${titleLabel} · ${idLabel}` : idLabel;
    th.title = record.relPath || idLabel;
    wireAwnDataViewRecordOpen(th, record, viewStore);
    headRow.appendChild(th);
  }

  thead.appendChild(headRow);
  table.appendChild(thead);

  const tbody = document.createElement("tbody");

  for (const column of columns) {
    const row = document.createElement("tr");
    row.className = "awn-databases-view-transposed-field-row";

    const labelCell = document.createElement("th");
    labelCell.scope = "row";
    labelCell.className = "awn-databases-view-transposed-field-label";
    labelCell.textContent = column.label;
    row.appendChild(labelCell);

    for (const record of records) {
      const cell = document.createElement("td");
      const value = formatAwnDataViewCellValue(record, column);
      cell.className = "awn-databases-view-transposed-field-value";
      if (column.kind === "id") {
        cell.classList.add("awn-databases-view-record-id");
        cell.append(createAwnDataViewRecordIdCell(record, viewStore, value));
      } else if (isAwnDataViewImagePreviewColumn(column)) {
        appendAwnDataViewPreviewFieldCell(cell, record, column, viewStore);
      } else {
        cell.textContent = value;
        if (value !== "—") cell.title = value;
      }
      if (isAwnDataSystemRecord(record)) cell.classList.add("is-system");
      wireAwnDataViewRecordOpen(cell, record, viewStore);
      row.appendChild(cell);
    }

    tbody.appendChild(row);
  }

  table.appendChild(tbody);
  return table;
}

function resolveAwnDataStoreRelPath(store) {
  return String(store?.relPath || awnDataViewStoreRel || "")
    .replace(/\\/g, "/")
    .replace(/^\/+/, "")
    .replace(/\/+$/, "");
}

function isAwnDataEntityTypesStore(store) {
  const rel = resolveAwnDataStoreRelPath(store);
  return rel.endsWith("cms-base/entities") || rel === "entities";
}

function resolveAwnDataRecordBodyFields(record) {
  if (record?.bodyFields && typeof record.bodyFields === "object") {
    return record.bodyFields;
  }
  const body = String(record?.body || "").trim();
  if (!body || !body.includes("awn-fields:")) return {};
  const fields = {};
  const lines = body.split("\n");
  let currentKey = "";
  let current = null;
  for (const line of lines) {
    const keyMatch = line.match(/^  ([a-zA-Z0-9_-]+):\s*$/);
    if (keyMatch) {
      currentKey = keyMatch[1];
      current = {};
      fields[currentKey] = current;
      continue;
    }
    if (!currentKey || !current) continue;
    const propMatch = line.match(/^    ([a-zA-Z0-9_-]+):\s*(.*)$/);
    if (propMatch) current[propMatch[1]] = propMatch[2].replace(/^["']|["']$/g, "");
  }
  return fields;
}

function formatAwnDataBodyFieldType(field) {
  const raw = String(field?.type || "string").trim();
  return raw.replace(/^awn\.field\./, "awn.").replace(/^awn\./, "");
}

