async function submitAwnDataCreateStore(agentId = activeWorkspaceId) {
  if (!agentId) {
    showToast("Выберите агента", "error");
    return;
  }
  const name = String(awnDataCreateNameInputNode?.value || "").trim();
  const tail =
    getAwnDataCreateSlugInputValue() ||
    transliterateDisplayToSlug(name) ||
    sanitizeSlugValue(slugifyAwnDataStoreName(name).split("/").pop() || "");
  const parentGroup = String(awnDataCreateParentGroup || "").trim().replace(/\/+$/g, "");
  const slug = parentGroup && tail ? `${parentGroup}/${tail}` : tail;
  const description = String(awnDataCreateDescriptionInputNode?.value || "").trim();
  if (!name || !slug) {
    showToast("Укажите название и папку (slug)", "error");
    return;
  }
  const taxonomyKey =
    isAwnTaxonomiesParentGroup(parentGroup) && awnDataCreateKind === "collection"
      ? resolveAwnDataCreateTaxonomyKey()
      : "";
  if (isAwnTaxonomiesParentGroup(parentGroup) && awnDataCreateKind === "collection" && !taxonomyKey) {
    showToast("Укажите папку (slug) справочника", "error");
    return;
  }

  awnDataCreateSubmitBtn.disabled = true;
  try {
    const response = await fetch(buildApiUrl("/api/awn-databases/stores", {}, agentId), {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        kind: awnDataCreateKind,
        name,
        slug,
        description,
        withSampleRecord: awnDataCreateKind === "collection" ? Boolean(awnDataCreateSampleInputNode?.checked) : false,
        ...(awnDataCreateKind === "collection" ? resolveAwnDataCreateCollectionPayload() : {}),
        ...(isAwnTaxonomiesParentGroup(parentGroup) && awnDataCreateKind === "collection"
          ? {
              taxonomyCardinality: String(awnDataCreateTaxonomyCardinalityInputNode?.value || "one").trim(),
              taxonomyHierarchy: Boolean(awnDataCreateTaxonomyHierarchyInputNode?.checked)
            }
          : {})
      })
    });
    const data = await response.json().catch(() => ({}));
    if (!response.ok) throw new Error(data.details || data.error || `HTTP ${response.status}`);
    closeAwnDataCreateModal();
    showToast(`Накопитель «${name}» создан`, "success");
    const taxonomySlugPrefix = String(slug || "").replace(/\\/g, "/");
    if (
      taxonomySlugPrefix.startsWith("0-taxonomies/") ||
      taxonomySlugPrefix.startsWith("taxonomies/") ||
      taxonomySlugPrefix.startsWith("awn-taxonomies/")
    ) {
      invalidateAgentTaxonomiesCache(agentId);
    }
    await refreshMenuAwnDataStores(agentId);
    if (!awnTypesCache?.types) await loadAwnTypes(agentId).catch(() => null);
    if (data.store?.relPath) void openAwnDataViewPage(data.store.relPath, agentId);
  } catch (error) {
    showToast(String(error.message || error), "error");
  } finally {
    awnDataCreateSubmitBtn.disabled = false;
  }
}

async function submitAwnDataUploadFiles(fileList, agentId = activeWorkspaceId) {
  if (!awnDataViewStoreRel || !agentId) return;
  const store = normalizeAwnDataStoreView(awnDataViewStoreCache || {});
  const isCsvFiles = isAwnDataCsvFilesStore(store);
  let files = Array.from(fileList || []).filter(Boolean);
  if (isCsvFiles) {
    files = files.filter((file) => String(file?.name || "").toLowerCase().endsWith(".csv"));
    if (!files.length) {
      showToast("Выберите CSV-файлы (.csv)", "error");
      return;
    }
  }
  if (!files.length) return;

  const storeRel = String(awnDataViewStoreRel || "").replace(/^\/+/, "");
  const recordRoot = String(store.recordRoot || "").replace(/^\/+|\/+$/g, "");
  let folderPath = recordRoot
    ? `awn-databases/${storeRel}/${recordRoot}`
    : `awn-databases/${storeRel}`;
  if (resolveAwnDataRecordHierarchy(store)) {
    const sectionPath = resolveAwnDataViewActiveSectionPath(store);
    if (sectionPath) folderPath = `${folderPath}/${sectionPath}`;
  }
  awnDataUploadBtnNode?.setAttribute("disabled", "disabled");
  awnDataUploadBtnNode?.classList.add("is-uploading");
  try {
    const result = await uploadWorkspaceFolderFiles(folderPath, files, { trackProgress: true });
    const uploaded = Number(result?.uploaded) || files.length;
    showToast(`Загружено файлов: ${uploaded}`, "success");
    await refreshMenuAwnDataStores(agentId);
    await openAwnDataViewPage(awnDataViewStoreRel, agentId);
  } catch (error) {
    showToast(String(error.message || error), "error");
  } finally {
    awnDataUploadBtnNode?.removeAttribute("disabled");
    awnDataUploadBtnNode?.classList.remove("is-uploading");
  }
}

