function repositoryStatusLabel(status) {
  const key = String(status || "").trim().toLowerCase();
  if (key === "active") return "активный";
  if (key === "study") return "изучение";
  if (key === "archived") return "архив";
  if (key === "vendored") return "vendor";
  return key || "—";
}

function slugifyRepositorySlug(name) {
  return slugifyAwnDataStoreName(name).replace(/\//g, "-").replace(/^-+|-+$/g, "");
}

const DEFAULT_REPOSITORY_GROUPS = [
  { id: "new", title: "Новый" },
  { id: "active", title: "Активный" },
  { id: "study", title: "Изучение" },
  { id: "vendored", title: "Вендор" },
  { id: "archived", title: "Архив" }
];
const DEFAULT_REPOSITORY_GROUP_IDS = new Set(DEFAULT_REPOSITORY_GROUPS.map((group) => group.id));
const REPOSITORY_STATUS_LABELS = {
  study: "📚 Изучение",
  active: "🟢 Активный",
  archived: "📦 Архив",
  vendored: "📌 Вендор"
};

function resolveRepositoryGroupsCatalog(groupsCatalog) {
  const defs = Array.isArray(groupsCatalog?.groups) ? groupsCatalog.groups : [];
  if (!defs.length) {
    return DEFAULT_REPOSITORY_GROUPS.map((group) => ({ ...group }));
  }

  const byId = new Map(DEFAULT_REPOSITORY_GROUPS.map((group) => [group.id, { ...group }]));
  const merged = [];
  const seen = new Set();

  for (const group of defs) {
    const id = normalizeRepositoryGroupId(group?.id);
    if (!id || seen.has(id)) continue;
    seen.add(id);
    const fallback = byId.get(id);
    merged.push({
      id,
      title: String(group.title || fallback?.title || id).trim() || id
    });
  }

  for (const group of DEFAULT_REPOSITORY_GROUPS) {
    if (!seen.has(group.id)) merged.push({ ...group });
  }

  return merged;
}

