function formatMenuRepositoryFilesTitle(entryCount) {
  const n = Number(entryCount);
  if (!Number.isFinite(n) || n < 0) return "";
  const mod10 = n % 10;
  const mod100 = n % 100;
  if (mod10 === 1 && mod100 !== 11) return `${n} файл`;
  if (mod10 >= 2 && mod10 <= 4 && (mod100 < 12 || mod100 > 14)) return `${n} файла`;
  return `${n} файлов`;
}

