function readMenuRepositoryGroupOpenState() {
  if (!menuRepositoriesListNode) return {};
  const state = {};
  menuRepositoriesListNode.querySelectorAll(".menu-repository-group").forEach((groupNode) => {
    const groupId = String(groupNode.dataset.repositoryGroupId || "").trim();
    if (!groupId) return;
    state[groupId] = !groupNode.classList.contains("is-collapsed");
  });
  return state;
}

function menuRepositoryEntrySearchHaystack(entry) {
  return [
    entry?.name,
    entry?.slug,
    entry?.description,
    entry?.origin,
    entry?.folderPath,
    entry?.manifestPath,
    entry?.group,
    entry?.status,
    entry?.hint
  ]
    .map((value) => String(value || "").trim().toLowerCase())
    .filter(Boolean)
    .join(" ");
}

function menuRepositoryEntryMatchesSearchQuery(entry, queryLower) {
  if (!queryLower) return true;
  const haystack = menuRepositoryEntrySearchHaystack(entry);
  if (!haystack) return false;
  return haystack.includes(queryLower);
}

function filterMenuRepositoriesPayload(payload, query = menuRepositoriesSearchQuery) {
  const queryLower = String(query || "")
    .trim()
    .toLowerCase();
  if (!queryLower || !payload) return payload;
  const repositories = (Array.isArray(payload.repositories) ? payload.repositories : []).filter((entry) =>
    menuRepositoryEntryMatchesSearchQuery(entry, queryLower)
  );
  const unregistered = (Array.isArray(payload.unregistered) ? payload.unregistered : []).filter((entry) =>
    menuRepositoryEntryMatchesSearchQuery(entry, queryLower)
  );
  return {
    ...payload,
    repositories,
    unregistered,
    _searchActive: true
  };
}

function createMenuRepositoryGroupNode(
  groupId,
  title,
  items,
  { highlightUnregistered = false, openState = null, forceExpanded = false } = {}
) {
  const item = document.createElement("li");
  item.className = highlightUnregistered
    ? "menu-repository-group menu-repository-group--unregistered"
    : "menu-repository-group";
  item.dataset.repositoryGroupId = String(groupId || "").trim();

  const resolvedGroupId = String(groupId || "").trim();
  const hasPreservedOpenState =
    openState && Object.prototype.hasOwnProperty.call(openState, resolvedGroupId);
  const defaultExpanded = items.length > 0;
  const isExpanded =
    forceExpanded && items.length > 0
      ? true
      : hasPreservedOpenState
        ? Boolean(openState[resolvedGroupId])
        : defaultExpanded;
  let isCollapsed = !isExpanded;
  const hasChildren = items.length > 0;
  if (!hasChildren) item.classList.add("is-empty");

  const headRow = document.createElement("div");
  headRow.className = highlightUnregistered
    ? "menu-repository-group-head menu-repository-group-head--unregistered"
    : "menu-repository-group-head";
  headRow.dataset.repositoryGroupDropZone = "1";

  const body = document.createElement("div");
  body.className = "menu-repository-group-body";
  body.dataset.repositoryGroupDropZone = "1";

  const syncCollapsedUi = () => {
    item.classList.toggle("is-collapsed", isCollapsed);
    body.hidden = isCollapsed;
    toggleBtn.textContent = formatMenuFolderToggleGlyph(isCollapsed, hasChildren);
    toggleBtn.title = hasChildren ? (isCollapsed ? "Раскрыть" : "Скрыть") : "Нет репозиториев";
  };

  const toggleBtn = createFolderToggleButton(hasChildren, isCollapsed, () => {
    isCollapsed = !isCollapsed;
    syncCollapsedUi();
  });
  if (!hasChildren) {
    toggleBtn.classList.add("folder-toggle-btn--empty-group");
  }

  const labelWrap = document.createElement("div");
  labelWrap.className = "menu-repository-group-label";
  labelWrap.dataset.repositoryGroupDropZone = "1";

  const titleNode = document.createElement("span");
  titleNode.className = "menu-repository-group-title";
  titleNode.textContent = title;

  const count = document.createElement("span");
  count.className = "menu-repository-group-count";
  count.textContent = String(items.length);

  labelWrap.append(titleNode, count);
  headRow.append(toggleBtn, labelWrap);

  const list = document.createElement("ul");
  list.className = "menu-repository-group-children";
  list.dataset.repositoryGroupDropZone = "1";

  if (!hasChildren) {
    const empty = document.createElement("li");
    empty.className = "menu-repository-group-drop-empty";
    empty.textContent = "Перетащите репозиторий";
    empty.dataset.repositoryGroupDropZone = "1";
    list.appendChild(empty);
  } else {
    items.forEach((row, index) => {
      const child =
        row.kind === "unregistered"
          ? createMenuRepositoryUnregisteredRow(row.entry)
          : createMenuRepositoryRow(row.entry);
      child.classList.add("menu-tree-branch");
      if (index === items.length - 1) child.classList.add("menu-tree-branch-last");
      list.appendChild(child);
    });
  }

  body.appendChild(list);
  item.append(headRow, body);
  syncCollapsedUi();
  return item;
}

function renderMenuRepositories(payload = null, { loading = false, error = false } = {}) {
  if (!menuRepositoriesListNode) return;
  menuRepositoriesListNode.classList.remove("is-loading");
  const openState = readMenuRepositoryGroupOpenState();
  menuRepositoriesListNode.replaceChildren();

  if (loading && !menuRepositoriesLastPayload) {
    const item = document.createElement("li");
    item.className = "menu-repository-item menu-repository-item--empty menu-repository-item--skeleton";
    item.textContent = "Загрузка…";
    menuRepositoriesListNode.appendChild(item);
    return;
  }

  if (error && !menuRepositoriesLastPayload) {
    const item = document.createElement("li");
    item.className = "menu-repository-item menu-repository-item--empty is-error";
    item.textContent = "Не удалось прочитать";
    menuRepositoriesListNode.appendChild(item);
    return;
  }

  const data = payload || menuRepositoriesLastPayload;
  if (!data) return;

  if (data.emptyHint === "select-agent") {
    const item = document.createElement("li");
    item.className = "menu-repository-item menu-repository-item--empty";
    item.textContent = "Выберите агента";
    menuRepositoriesListNode.appendChild(item);
    return;
  }

  const viewData = filterMenuRepositoriesPayload(data, menuRepositoriesSearchQuery);
  const repositories = Array.isArray(viewData.repositories) ? viewData.repositories : [];
  const unregistered = Array.isArray(viewData.unregistered) ? viewData.unregistered : [];
  const sections = groupMenuRepositories(repositories, unregistered, viewData.groupsCatalog).filter(
    (section) => !viewData._searchActive || section.items.length > 0
  );
  if (!sections.length) {
    const item = document.createElement("li");
    item.className = "menu-repository-item menu-repository-item--empty";
    item.textContent = viewData._searchActive ? "Ничего не найдено" : "Нет репозиториев";
    menuRepositoriesListNode.appendChild(item);
    return;
  }
  for (const section of sections) {
    menuRepositoriesListNode.appendChild(
      createMenuRepositoryGroupNode(section.id, section.title, section.items, {
        highlightUnregistered: section.highlightUnregistered,
        openState,
        forceExpanded: Boolean(viewData._searchActive)
      })
    );
  }
  enableVoiceChatDragSources(menuRepositoriesListNode);
}

