function awnDataStoreKindClass(kind) {
  if (kind === "single") return "menu-awn-databases-store-kind--single";
  if (kind === "group") return "menu-awn-databases-store-kind--group";
  return "menu-awn-databases-store-kind--collection";
}

function awnDataStoreKindLabel(kind) {
  return getAwnDataStoreKindMeta(kind).label;
}

function resolveAwnDataCollectionStorageLabel(store) {
  if (store?.kind !== "collection") return "";
  return resolveAwnDataCollectionType(store);
}

function resolveAwnDataStoreKindTitle(store) {
  const kind = store?.kind || "collection";
  if (kind === "group") return awnDataStoreKindLabel("group");
  if (kind === "single") return awnDataStoreKindLabel("single");
  const format = resolveAwnDataCollectionStorageLabel(store);
  let title = "Коллекция md-записей";
  if (format === "files") title = "Коллекция файлов";
  else if (format === "csv-files") title = "Коллекция CSV-файлов";
  else if (format === "csv") title = "Коллекция CSV";
  else if (format === "md-lite") title = "Коллекция md-lite записей";
  if (shouldShowAwnDataStoreHierarchyBadge(store)) {
    title = `${title} · ${AWN_DATA_SECTIONS_SUPPORT_LABEL.toLowerCase()}`;
  }
  return title;
}

function shouldShowAwnDataStoreHierarchyBadge(store) {
  if (store?.kind !== "collection") return false;
  if (isAwnDataSingleCsvStore(store)) return false;
  return resolveAwnDataRecordHierarchy(store);
}

const AWN_DATA_STORE_HIERARCHY_BADGE_SVG =
  '<svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><circle cx="12" cy="5" r="2.25" fill="currentColor" stroke="none"/><circle cx="6" cy="19" r="2.25" fill="currentColor" stroke="none"/><circle cx="18" cy="19" r="2.25" fill="currentColor" stroke="none"/><path d="M12 7.25v3.5M12 10.75H6v5.25M12 10.75h6v5.25" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg>';

function createAwnDataHierarchyBadgeElement(store) {
  if (!shouldShowAwnDataStoreHierarchyBadge(store)) return null;
  const badge = document.createElement("span");
  badge.className = "menu-awn-databases-store-hierarchy-badge";
  badge.setAttribute("aria-hidden", "true");
  badge.title = `${AWN_DATA_SECTIONS_SUPPORT_LABEL}: иерархия записей (родитель и разделы)`;
  badge.innerHTML = AWN_DATA_STORE_HIERARCHY_BADGE_SVG;
  return badge;
}

function createAwnDataCollectionStorageBadgeElement(store) {
  if (store?.kind !== "collection") return null;
  const format = resolveAwnDataCollectionStorageLabel(store);
  const badge = document.createElement("span");
  badge.className = `menu-awn-databases-store-kind-letter menu-awn-databases-store-kind-letter-${format}`;
  badge.textContent = formatAwnDataCollectionStorageBadgeLabel(format);
  badge.title = resolveAwnDataStoreKindTitle(store);
  return badge;
}

function createAwnDataStoreKindNode(store, { extraClass = "", showStorageBadge = true } = {}) {
  const kind = store?.kind || "collection";
  const wrap = document.createElement("span");
  wrap.className = `menu-awn-databases-store-kind-wrap${extraClass ? ` ${extraClass}` : ""}`;
  wrap.title = resolveAwnDataStoreKindTitle(store);
  wrap.setAttribute("aria-hidden", "true");

  const icon = document.createElement("span");
  icon.className = `menu-awn-databases-store-kind ${awnDataStoreKindClass(kind)}`;
  wrap.appendChild(icon);

  if (kind === "collection" && showStorageBadge) {
    const hierarchyBadge = createAwnDataHierarchyBadgeElement(store);
    if (hierarchyBadge) wrap.appendChild(hierarchyBadge);
    const badge = createAwnDataCollectionStorageBadgeElement(store);
    if (badge) wrap.appendChild(badge);
  }

  return wrap;
}

function resolveAwnDataRecordCount(store) {
  if (store?.kind === "group") {
    const childCount = Number(store.childCount);
    if (Number.isFinite(childCount) && childCount >= 0) return childCount;
    return Array.isArray(store.children) ? store.children.length : 0;
  }
  if (Array.isArray(store?.records)) return store.records.length;
  const explicit = Number(store?.recordCount);
  return Number.isFinite(explicit) ? explicit : 0;
}

let awnDataGroupCreatePopoverNode = null;
let awnDataGroupCreatePopoverListNode = null;
let awnDataGroupCreatePopoverAnchor = null;

function ensureAwnDataGroupCreatePopover() {
  if (awnDataGroupCreatePopoverNode) return;
  const popover = document.createElement("div");
  popover.id = "menu-awn-databases-group-create-popover";
  popover.className = "menu-awn-databases-group-create-popover menu-context-menu hidden";
  popover.setAttribute("role", "menu");
  popover.setAttribute("aria-label", "Создать в группе");
  const list = document.createElement("ul");
  list.className = "menu-context-menu-list";
  list.id = "menu-awn-databases-group-create-popover-list";
  list.setAttribute("role", "none");
  popover.appendChild(list);
  document.body.appendChild(popover);
  awnDataGroupCreatePopoverNode = popover;
  awnDataGroupCreatePopoverListNode = list;

  list.addEventListener("click", (event) => {
    const btn = event.target.closest(".menu-context-menu-btn");
    if (!btn || btn.disabled) return;
    event.preventDefault();
    event.stopPropagation();
    const action = btn.dataset.action;
    const parentGroup = String(awnDataGroupCreatePopoverNode?.dataset.parentGroup || "").trim();
    closeAwnDataGroupCreatePopover();
    if (!parentGroup) return;
    if (action === "single") {
      openAwnDataCreateModal("single", { parentGroup });
      return;
    }
    openAwnDataCreateModal("collection", { parentGroup });
  });
}

function closeAwnDataGroupCreatePopover() {
  awnDataGroupCreatePopoverNode?.classList.add("hidden");
  awnDataGroupCreatePopoverNode?.removeAttribute("data-parent-group");
  if (awnDataGroupCreatePopoverAnchor) {
    awnDataGroupCreatePopoverAnchor.setAttribute("aria-expanded", "false");
    awnDataGroupCreatePopoverAnchor = null;
  }
}

function positionAwnDataGroupCreatePopover(anchor) {
  if (!awnDataGroupCreatePopoverNode || !anchor) return;
  awnDataGroupCreatePopoverNode.classList.remove("hidden");
  const anchorRect = anchor.getBoundingClientRect();
  const popoverRect = awnDataGroupCreatePopoverNode.getBoundingClientRect();
  const margin = 6;
  const left = Math.min(
    Math.max(8, anchorRect.right - popoverRect.width),
    Math.max(8, window.innerWidth - popoverRect.width - 8)
  );
  let top = anchorRect.top - popoverRect.height - margin;
  if (top < 8) {
    top = anchorRect.bottom + margin;
  }
  top = Math.max(8, Math.min(top, window.innerHeight - popoverRect.height - 8));
  awnDataGroupCreatePopoverNode.style.left = `${left}px`;
  awnDataGroupCreatePopoverNode.style.top = `${top}px`;
}

function populateAwnDataGroupCreatePopover(parentGroupRel) {
  ensureAwnDataGroupCreatePopover();
  const list = awnDataGroupCreatePopoverListNode;
  if (!list || !awnDataGroupCreatePopoverNode) return false;
  list.replaceChildren();

  const parentGroup = String(parentGroupRel || "")
    .trim()
    .replace(/\\/g, "/")
    .replace(/^\/+|\/+$/g, "");
  const isTaxonomyGroup = parentGroup === SHARED_TAXONOMIES_SLUG;
  for (const item of [
    { action: "collection", label: "Коллекция" },
    { action: "single", label: "Одиночка", hiddenForTaxonomy: true }
  ]) {
    if (isTaxonomyGroup && item.hiddenForTaxonomy) continue;
    const row = document.createElement("li");
    row.className = "menu-context-menu-item";
    row.setAttribute("role", "none");
    const btn = document.createElement("button");
    btn.type = "button";
    btn.className = "menu-context-menu-btn";
    btn.dataset.action = item.action;
    btn.textContent = item.label;
    btn.setAttribute("role", "menuitem");
    row.appendChild(btn);
    list.appendChild(row);
  }

  awnDataGroupCreatePopoverNode.dataset.parentGroup = String(parentGroupRel || "").trim();
  return true;
}

function openAwnDataGroupCreatePopover(event, parentGroupRel) {
  event.preventDefault();
  event.stopPropagation();
  closeMenuContextMenu();
  closeResourceContextMenu();
  closeNavigationHubRailFolderCreatePopover();

  const anchor = event.currentTarget;
  const isSameAnchor =
    awnDataGroupCreatePopoverAnchor === anchor &&
    awnDataGroupCreatePopoverNode &&
    !awnDataGroupCreatePopoverNode.classList.contains("hidden");
  if (isSameAnchor) {
    closeAwnDataGroupCreatePopover();
    return;
  }

  closeAwnDataGroupCreatePopover();
  if (!populateAwnDataGroupCreatePopover(parentGroupRel)) return;

  awnDataGroupCreatePopoverAnchor = anchor;
  anchor.setAttribute("aria-expanded", "true");
  positionAwnDataGroupCreatePopover(anchor);
}

function createAwnDataGroupCreateBtn(store) {
  const createBtn = document.createElement("button");
  createBtn.type = "button";
  createBtn.className = "menu-awn-databases-group-create-btn";
  createBtn.title = `Новый инфоблок в ${store.relPath}/`;
  createBtn.setAttribute("aria-label", "Создать в группе");
  createBtn.setAttribute("aria-haspopup", "menu");
  createBtn.setAttribute("aria-expanded", "false");
  createBtn.innerHTML =
    '<svg class="menu-awn-databases-group-create-icon" viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M12 5v14M5 12h14" stroke="currentColor" stroke-width="2.5" stroke-linecap="round"/></svg>';
  createBtn.addEventListener("click", (event) => {
    openAwnDataGroupCreatePopover(event, store.relPath);
  });
  return createBtn;
}

function createAwnDataStoreMetaNode(store) {
  const metaNode = document.createElement("span");
  metaNode.className = "menu-awn-databases-store-meta";

  if (store?.kind === "group") {
    const childCount = resolveAwnDataRecordCount(store);
    const badge = document.createElement("span");
    badge.className = "menu-awn-databases-store-badge menu-awn-databases-store-badge--count";
    if (childCount <= 0) badge.classList.add("is-zero");
    badge.textContent = String(childCount);
    badge.title =
      childCount <= 0
        ? "В группе нет инфоблоков"
        : childCount === 1
          ? "1 инфоблок"
          : `${childCount} инфоблоков`;
    metaNode.appendChild(badge);
    return metaNode;
  }

  if (store?.kind === "collection") {
    const hierarchyBadge = createAwnDataHierarchyBadgeElement(store);
    if (hierarchyBadge) metaNode.appendChild(hierarchyBadge);
    const typeBadge = createAwnDataCollectionStorageBadgeElement(store);
    if (typeBadge) metaNode.appendChild(typeBadge);
  }

  const count = resolveAwnDataRecordCount(store);
  const badge = document.createElement("span");
  badge.className = "menu-awn-databases-store-badge menu-awn-databases-store-badge--count";
  if (count <= 0) badge.classList.add("is-zero");
  badge.textContent = String(count);

  if (store?.kind === "single") {
    badge.title = count > 0 ? "main.md заполнен" : "main.md пуст";
  } else {
    badge.title = count === 1 ? "1 запись" : `${count} записей`;
  }

  metaNode.appendChild(badge);
  return metaNode;
}

function syncAwnDataMenuActiveStore(storeRel = awnDataViewStoreRel) {
  if (!menuAwnDataStoresNode) return;
  const normalized = String(storeRel || "")
    .replace(/\\/g, "/")
    .replace(/^\/+/, "")
    .replace(/\/+$/, "");
  for (const row of menuAwnDataStoresNode.querySelectorAll(".menu-awn-databases-store[role='button']")) {
    const rel = String(row.dataset.storeRel || "")
      .replace(/\\/g, "/")
      .replace(/^\/+/, "")
      .replace(/\/+$/, "");
    row.classList.toggle("is-active", Boolean(normalized) && rel === normalized);
  }
  for (const openBtn of menuAwnDataStoresNode.querySelectorAll(".menu-awn-databases-store-group-open-btn")) {
    const rel = String(openBtn.dataset.storeRel || "")
      .replace(/\\/g, "/")
      .replace(/^\/+/, "")
      .replace(/\/+$/, "");
    const active = Boolean(normalized) && rel === normalized;
    openBtn.classList.toggle("is-active", active);
    openBtn.closest(".menu-awn-databases-store-group")?.classList.toggle("is-active", active);
  }
}

function wireAwnDataStoreRow(row, store) {
  row.dataset.storeRel = String(store.relPath || "")
    .replace(/\\/g, "/")
    .replace(/^\/+/, "")
    .replace(/\/+$/, "");
  row.tabIndex = 0;
  row.setAttribute("role", "button");
  row.addEventListener("click", () => void openAwnDataViewPage(store.relPath));
  row.addEventListener("keydown", (event) => {
    if (event.key === "Enter" || event.key === " ") {
      event.preventDefault();
      void openAwnDataViewPage(store.relPath);
    }
  });
}

function createAwnDataStoreRow(store, { nested = false } = {}) {
  const row = document.createElement("li");
  row.className = "menu-awn-databases-store";
  if (nested) row.classList.add("menu-awn-databases-store--nested");
  const displayName = String(store.name || store.id || store.relPath || "").trim();
  const pathHint = store.relPath && store.relPath !== displayName ? store.relPath : "";
  row.title = store.description || (pathHint ? `${displayName} · ${pathHint}` : displayName);

  const kindNode = createAwnDataStoreKindNode(store, { showStorageBadge: false });

  const nameNode = document.createElement("span");
  nameNode.className = "menu-awn-databases-store-name";
  nameNode.textContent = displayName;
  const idBadge = createNavBookTocIdBadge(resolveAwnDataStoreAwnId(store));
  if (idBadge) idBadge.classList.add("menu-awn-databases-store-id-badge");
  row.append(kindNode, ...(idBadge ? [idBadge] : []), nameNode, createAwnDataStoreMetaNode(store));

  wireAwnDataStoreRow(row, store);
  return row;
}

function awnDataStoreSearchHaystack(store) {
  return [
    store?.name,
    store?.id,
    resolveAwnDataStoreAwnId(store),
    store?.relPath,
    store?.description,
    store?.kind,
    awnDataStoreKindLabel(store?.kind)
  ]
    .map((value) => String(value || "").trim())
    .filter(Boolean)
    .join(" ")
    .toLowerCase();
}

function awnDataStoreMatchesSearchQuery(store, queryLower) {
  const haystack = awnDataStoreSearchHaystack(store);
  if (!queryLower) return true;
  if (!haystack) return false;
  return haystack.includes(queryLower);
}

function filterAwnDataStoresPayload(payload, query = menuAwnDataSearchQuery) {
  const queryLower = String(query || "")
    .trim()
    .toLowerCase();
  if (!queryLower) return payload;
  const stores = Array.isArray(payload?.stores) ? payload.stores : [];
  const filteredStores = [];
  for (const store of stores) {
    if (store?.kind === "group") {
      const children = Array.isArray(store.children) ? store.children : [];
      const groupMatches = awnDataStoreMatchesSearchQuery(store, queryLower);
      const matchedChildren = children.filter((child) => awnDataStoreMatchesSearchQuery(child, queryLower));
      if (groupMatches) {
        filteredStores.push(store);
        continue;
      }
      if (matchedChildren.length) {
        filteredStores.push({
          ...store,
          children: matchedChildren,
          childCount: matchedChildren.length,
          _filterExpanded: true
        });
      }
      continue;
    }
    if (awnDataStoreMatchesSearchQuery(store, queryLower)) {
      filteredStores.push(store);
    }
  }
  return { ...payload, stores: filteredStores, _searchActive: true };
}

function createAwnDataStoreGroupNode(store, { forceExpanded = false } = {}) {
  const item = document.createElement("li");
  item.className = "menu-awn-databases-store-group";
  const relPath = String(store?.relPath || "")
    .replace(/\\/g, "/")
    .replace(/^\/+/, "")
    .replace(/\/+$/, "");
  const isBuiltinGroup = isBuiltinAwnDataGroupRel(relPath);
  if (isBuiltinGroup) {
    item.classList.add("menu-awn-databases-store-group--builtin");
  }

  const children = Array.isArray(store.children) ? store.children : [];
  const hasChildren = children.length > 0;
  let isCollapsed = forceExpanded ? false : false;
  if (!hasChildren) item.classList.add("is-empty");

  const headRow = document.createElement("div");
  headRow.className = "menu-awn-databases-store-group-head";

  const body = document.createElement("div");
  body.className = "menu-awn-databases-store-group-body";

  const syncCollapsedUi = () => {
    item.classList.toggle("is-collapsed", isCollapsed);
    body.hidden = isCollapsed;
    toggleBtn.textContent = formatMenuFolderToggleGlyph(isCollapsed, true);
    toggleBtn.title = isCollapsed ? "Раскрыть" : "Скрыть";
  };

  const toggleBtn = createFolderToggleButton(true, isCollapsed, () => {
    isCollapsed = !isCollapsed;
    syncCollapsedUi();
  });
  if (!hasChildren) {
    toggleBtn.classList.add("folder-toggle-btn--empty-group");
  }

  const kindNode = createAwnDataStoreKindNode(store);

  const displayName = String(store.name || store.id || store.relPath || "Группа").trim();
  const pathHint = store.relPath && store.relPath !== displayName ? store.relPath : "";

  const openBtn = document.createElement("button");
  openBtn.type = "button";
  openBtn.className = "menu-awn-databases-store-group-open-btn";
  openBtn.dataset.storeRel = String(store.relPath || "")
    .replace(/\\/g, "/")
    .replace(/^\/+/, "")
    .replace(/\/+$/, "");
  openBtn.title = pathHint ? `${displayName} · ${pathHint}` : displayName;

  const idBadge = createNavBookTocIdBadge(resolveAwnDataStoreAwnId(store));
  if (idBadge) {
    idBadge.classList.add("menu-awn-databases-store-id-badge");
  }

  const nameNode = document.createElement("span");
  nameNode.className = "menu-awn-databases-store-name";
  nameNode.textContent = displayName;
  openBtn.appendChild(nameNode);
  if (isBuiltinGroup) {
    const builtinBadge = document.createElement("span");
    builtinBadge.className = "menu-awn-databases-store-builtin-badge";
    builtinBadge.textContent = "встр.";
    builtinBadge.title = "Встроенная системная группа";
    openBtn.appendChild(builtinBadge);
  }

  openBtn.addEventListener("click", () => void openAwnDataViewPage(store.relPath));
  openBtn.addEventListener("keydown", (event) => {
    if (event.key === "Enter" || event.key === " ") {
      event.preventDefault();
      void openAwnDataViewPage(store.relPath);
    }
  });

  const actionsNode = document.createElement("span");
  actionsNode.className = "menu-awn-databases-store-group-actions";
  actionsNode.append(createAwnDataGroupCreateBtn(store), createAwnDataStoreMetaNode(store));

  headRow.append(toggleBtn, kindNode, ...(idBadge ? [idBadge] : []), openBtn, actionsNode);

  const childList = document.createElement("ul");
  childList.className = "menu-awn-databases-store-group-children";
  if (!hasChildren) {
    const empty = document.createElement("li");
    empty.className = "menu-awn-databases-store-group-empty-hint";
    empty.title = "В группе пока нет накопителей";
    empty.setAttribute("aria-label", "В группе пока нет накопителей");
    const emptyState = document.createElement("div");
    emptyState.className = "menu-awn-databases-store-group-empty-state";
    const emptyIcon = document.createElement("span");
    emptyIcon.className = "menu-awn-databases-store-group-empty-icon";
    emptyIcon.setAttribute("aria-hidden", "true");
    emptyState.appendChild(emptyIcon);
    empty.appendChild(emptyState);
    childList.appendChild(empty);
  } else {
    children.forEach((child, index) => {
      const childRow = createAwnDataStoreRow(child, { nested: true });
      childRow.classList.add("menu-tree-branch");
      if (index === children.length - 1) childRow.classList.add("menu-tree-branch-last");
      childList.appendChild(childRow);
    });
  }

  body.appendChild(childList);
  item.append(headRow, body);
  syncCollapsedUi();
  return item;
}

function renderMenuAwnDataStores(payload = null, { loading = false, error = false } = {}) {
  if (!menuAwnDataStoresNode) return;
  menuAwnDataStoresNode.replaceChildren();

  if (loading) {
    const item = document.createElement("li");
    item.className = "menu-awn-databases-store menu-awn-databases-store--empty";
    item.textContent = "Загрузка…";
    menuAwnDataStoresNode.appendChild(item);
    return;
  }

  if (error) {
    menuAwnDataStoresLastPayload = null;
    const item = document.createElement("li");
    item.className = "menu-awn-databases-store menu-awn-databases-store--empty is-error";
    item.textContent = "Не удалось прочитать";
    menuAwnDataStoresNode.appendChild(item);
    return;
  }

  if (!payload) {
    const item = document.createElement("li");
    item.className = "menu-awn-databases-store menu-awn-databases-store--empty is-error";
    item.textContent = "Не удалось прочитать";
    menuAwnDataStoresNode.appendChild(item);
    return;
  }

  menuAwnDataStoresLastPayload = payload;
  const viewPayload = filterAwnDataStoresPayload(payload, menuAwnDataSearchQuery);
  const stores = Array.isArray(viewPayload.stores) ? viewPayload.stores : [];
  if (!stores.length) {
    const item = document.createElement("li");
    item.className = "menu-awn-databases-store menu-awn-databases-store--empty";
    item.textContent = viewPayload._searchActive
      ? "Ничего не найдено"
      : payload.emptyHint === "select-agent"
        ? "Выберите агента"
        : "Нет накопителей";
    menuAwnDataStoresNode.appendChild(item);
    return;
  }

  if (viewPayload.source === "platform" && viewPayload.sourceAgentId) {
    const note = document.createElement("li");
    note.className = "menu-awn-databases-store menu-awn-databases-store--platform-note";
    note.textContent = `Модели платформы (${viewPayload.sourceAgentId})`;
    menuAwnDataStoresNode.appendChild(note);
  }

  for (const store of stores) {
    if (store.kind === "group") {
      menuAwnDataStoresNode.appendChild(
        createAwnDataStoreGroupNode(store, { forceExpanded: Boolean(store._filterExpanded) })
      );
      continue;
    }
    menuAwnDataStoresNode.appendChild(createAwnDataStoreRow(store));
  }
  if (isProjectSettingsMode()) {
    renderProjectSettingsScopeList();
    if (isProjectSettingsIblockScope(getNodeSettingsManifestPath())) {
      renderProjectSettingsIblockStubPage();
    }
  }
}

function isLegacyOnlyAwnDataPayload(payload) {
  const stores = Array.isArray(payload?.stores) ? payload.stores : [];
  if (!stores.length) return true;
  if (stores.length !== 1) return false;
  const only = stores[0];
  const rel = String(only?.relPath || only?.id || "").trim();
  return rel === "_base";
}

async function refreshMenuAwnDataStores(agentId = activeWorkspaceId, { showLoading = false } = {}) {
  if (!menuAwnDataStoresNode) return;
  if (menuAwnDataIndexRowNode) {
    menuAwnDataIndexRowNode.dataset.awnDatabaseHasIndex = "0";
  }
  syncMenuAwnDataIndexRowState();

  const seq = ++menuAwnDataStoresLoadSeq;
  const hasRenderedStores = menuAwnDataStoresNode.childElementCount > 0;
  if (showLoading || !hasRenderedStores) {
    renderMenuAwnDataStores(null, { loading: true });
  }

  const resolvedAgent = String(agentId || activeWorkspaceId || "").trim();
  if (!resolvedAgent) {
    if (seq !== menuAwnDataStoresLoadSeq) return;
    renderMenuAwnDataStores({ stores: [], emptyHint: "select-agent" });
    return;
  }

  try {
    const response = await fetch(buildApiUrl("/api/awn-databases", {}, resolvedAgent));
    if (!response.ok) throw new Error(`HTTP ${response.status}`);
    const data = await response.json();
    if (seq !== menuAwnDataStoresLoadSeq) return;
    awnDataCatalogAgentId = resolveAwnDataCatalogAgentId(data, resolvedAgent);
    renderMenuAwnDataStores(data);
    void probeAwnDataIndexExists(resolvedAgent).then((exists) => {
      if (!menuAwnDataIndexRowNode?.isConnected) return;
      menuAwnDataIndexRowNode.dataset.awnDatabaseHasIndex = exists ? "1" : "0";
      syncMenuAwnDataIndexRowState();
    });
  } catch {
    if (seq !== menuAwnDataStoresLoadSeq) return;
    renderMenuAwnDataStores(null, { error: true });
  }
}

