async function init() {
  await Promise.all([
    ensureEditorCoreHelpersLoaded(),
    ensureEditorCmsCoreLoaded(),
    ensureEditorMarkdownPreviewLoaded(),
    ensureEditorUiIconsLoaded(),
    ensureEditorPostMainScriptsLoaded(),
    ensureEditorSecondaryPanelsLoaded(),
    ensureConnectionStatusLoaded()
  ]).catch(() => {});

  setupMaintenancePaneUi();
  const splashStartedAt = Date.now();
  const finishSplash = () => {
    const elapsed = Date.now() - splashStartedAt;
    const wait = Math.max(0, APP_SPLASH_MIN_MS - elapsed);
    window.setTimeout(hideAppSplash, wait);
  };
  const splashFailsafe = window.setTimeout(() => {
    finishSplash();
    if (document.body.classList.contains("app-booting")) {
      showAppLandingView("Загрузка заняла слишком много времени. Проверьте сервер и обновите страницу.");
      setMenuLoading(false);
    }
  }, 20000);

  try {
    if (location.hash === "#graph") {
      history.replaceState(null, "", `${location.pathname}${location.search}`);
    }

    if (window.agentAppLock?.whenUnlocked) {
      await window.agentAppLock.whenUnlocked();
    }

    await loadPlatformUiSettings().catch(() => {});
    if (platformUiSettings.maintenanceMode) {
      return;
    }

    await loadAgents();
    window.WorkspaceIndexPanel?.refreshStatus?.();
    if (activeWorkspaceId) await loadUserSettingsForAgent(activeWorkspaceId).catch(() => {});
    await ensureWorkspaceComfortScriptsLoaded().catch(() => {});
    setupWorkspaceIdleScreensaver();
    setupWorkspacePomodoro();
    if (activeWorkspaceId) reloadWorkspaceIdleScreensaverSettings(activeWorkspaceId);
    if (activeWorkspaceId) reloadWorkspacePomodoroForAgent(activeWorkspaceId);
    applyMenuTreeSettingsUi();
    applyAgentGraphSettingsUi();

    if (activeWorkspaceId) {
      void loadSystemFiles({ refreshNotePreview: true });
    }

    const bootRoute = parseAppRoute(location.pathname);
    if (bootRoute.type !== "root" && bootRoute.type !== "legacy" && activeWorkspaceId) {
      setMenuLoading(true, "Загрузка дерева…");
      await refreshMenu();
      setMenuLoading(false);
      void loadAwnTypes(activeWorkspaceId);
    }

    suspendAppRouteSync();
    try {
      await applyAppRouteFromUrl();
    } finally {
      resumeAppRouteSync();
    }

    if (activeWorkspaceId && !isAppLandingViewActive()) {
      void loadAgentFocusItems(activeWorkspaceId);
    }

    syncAppRouteToUrl({ replace: true });
  } catch (error) {
    showAppLandingView(`Ошибка загрузки: ${formatBootLoadErrorMessage(error)}`);
  } finally {
    if (isAppLandingViewActive()) {
      void renderAppLandingAgents();
    }
    window.clearTimeout(splashFailsafe);
    finishSplash();
    setMenuLoading(false);
  }
}

function hideAppSplash() {
  if (!appSplashNode) {
    document.body.classList.remove("app-booting");
    return;
  }
  document.body.classList.remove("app-booting");
  appSplashNode.classList.add("app-splash--hide");
  window.setTimeout(() => {
    appSplashNode.remove();
  }, APP_SPLASH_HIDE_MS);
}

globalThis.__agentCmsRunBoot = function agentCmsRunBoot() {
  void init().catch((error) => {
    console.error("[Agent CMS] init failed", error);
    try {
      hideAppSplash();
      showAppLandingView(`Ошибка загрузки: ${formatBootLoadErrorMessage(error)}`);
    } catch (_secondary) {
      document.body.classList.remove("app-booting");
    }
  });
};

