agentGitCommitModalSubmitBtn?.addEventListener("click", () => {
  void (async () => {
    let batchIds = [];
    ensureAgentGitCommitBatchRadioSelection();
    batchIds = getAgentGitSelectedCommitBatchIds();
    if (!batchIds.length) {
      window.alert("Выберите партию для коммита");
      return;
    }
    const messageSuffix = String(agentGitCommitMessageNoteNode?.value || "").trim();
    if (agentGitSaveBtn) agentGitSaveBtn.disabled = true;
    if (agentGitCommitModalSubmitBtn) agentGitCommitModalSubmitBtn.disabled = true;
    try {
      const freshStatus = await fetchAgentGitStatus();
      syncAgentGitSettingsUi(freshStatus);
      ensureAgentGitCommitBatchRadioSelection();
      batchIds = getAgentGitSelectedCommitBatchIds();
      if (!batchIds.length) {
        window.alert("Выберите партию для коммита");
        return;
      }
      const changes = getAgentGitAllStatusChanges(freshStatus);
      const modalOptions = listAgentGitCommitModalOptions(changes);
      const selectedOption =
        modalOptions.find((entry) => entry.optionId === batchIds[0]) ||
        getAgentGitCommitModalSelectedOption();
      const batch = selectedOption?.batch || getAgentGitCommitBatchById(batchIds[0]);
      const committableCount = selectedOption?.count ?? 0;
      if (committableCount <= 0) {
        window.alert(
          "В выбранной партии нет файлов для коммита (обновите статус или проверьте лимит размера файла)."
        );
        return;
      }
      if (selectedOption?.overLimit) {
        const maxMb = Number(agentGitModuleConfig?.commitMaxBatchMb) || 250;
        window.alert(`Эта часть партии превышает лимит ${maxMb} МБ на один коммит.`);
        return;
      }
      closeAgentGitCommitModal();
      const result = await commitAgentGitChanges({ batchIds, messageSuffix });
      const chunkLabel =
        selectedOption?.chunkTotal > 1 && selectedOption.chunkIndex
          ? `${batch?.label || batch?.id} [${selectedOption.chunkIndex}/${selectedOption.chunkTotal}]`
          : batch?.label || batch?.id;
      reportAgentGitCommitResult(result, {
        batchIds,
        batchLabel: chunkLabel,
        committableCount,
        agentId: activeWorkspaceId
      });
    } catch (error) {
      const failBatchId = batchIds[0] || "";
      showAgentGitCommitResultModal({
        title: "Ошибка коммита",
        summary: error?.message || "Не удалось выполнить запрос",
        details: buildAgentGitCommitResultDetailsText({}, {
          batchIds,
          batchLabel: getAgentGitCommitBatchById(failBatchId)?.label,
          agentId: activeWorkspaceId,
          errorPayload: error?.payload || {
            code: error?.code,
            details: error?.details,
            httpStatus: error?.httpStatus,
            message: error?.message
          }
        }),
        success: false
      });
    } finally {
      if (agentGitCommitModalSubmitBtn) agentGitCommitModalSubmitBtn.disabled = false;
      void renderAgentGitView();
    }
  })();
});

